window.VOCAB = {"batches":[{"id":"a2-01","title":"A2 · A (1)","level":"A2","words":[{"de":"die Abendkasse","en":"box office (evening)","pos":"noun","plural":"die Abendkassen","meanings":[{"en":"box office at a theater/concert where tickets are sold just before the event","de":"Kasse am Veranstaltungsort, kurz vor Beginn"}],"rule":"Compound noun: der Abend + die Kasse; gender follows the second part (die Kasse).","example":"Karten gibt es auch an der Abendkasse.","exampleEn":"Tickets are also available at the box office (on the evening).","example2":"Die Abendkasse öffnet eine Stunde vor der Vorstellung.","example2En":"The evening box office opens one hour before the performance."},{"de":"abfahren","en":"to depart, leave","pos":"verb","plural":"","meanings":[{"en":"to leave / depart (vehicle, train, person)","de":"losfahren, wegfahren"}],"rule":"Trennbar: fährt ab, fuhr ab, ist abgefahren. Perfekt mit sein.","example":"Der Zug fährt um 9 Uhr ab.","exampleEn":"The train departs at 9 o'clock.","example2":"Wir fahren morgen früh ab.","example2En":"We're leaving early tomorrow morning."},{"de":"die Abfahrt","en":"departure","pos":"noun","plural":"die Abfahrten","meanings":[{"en":"departure (of a train, bus, etc.)","de":"das Abfahren, Beginn der Fahrt"},{"en":"motorway exit / ski descent","de":"Ausfahrt von der Autobahn; Skiabfahrt"}],"rule":"Feminine noun, from abfahren. Often seen on timetables (Abfahrt/Ankunft).","example":"Die Abfahrt des Zuges ist um 9 Uhr.","exampleEn":"The train's departure is at 9 o'clock.","example2":"An der nächsten Abfahrt müssen wir die Autobahn verlassen.","example2En":"We have to leave the motorway at the next exit."},{"de":"abgeben","en":"to hand in, drop off","pos":"verb","plural":"","meanings":[{"en":"to hand in / submit (documents, homework)","de":"etwas bei jemandem lassen, einreichen"},{"en":"to drop off (a person or thing)","de":"jemanden/etwas an einen Ort bringen"}],"rule":"Trennbar: gibt ab, gab ab, hat abgegeben. + Akkusativ (etwas abgeben).","example":"Ich muss die Prüfung bis Freitag abgeben.","exampleEn":"I have to hand in the exam by Friday.","example2":"Kannst du die Kinder in der Schule abgeben?","example2En":"Can you drop the kids off at school?"},{"de":"abheben","en":"to withdraw (money); to take off","pos":"verb","plural":"","meanings":[{"en":"to withdraw money from an account","de":"Geld vom Konto nehmen"},{"en":"to take off (plane)","de":"in die Luft steigen"},{"en":"to pick up / answer the phone receiver","de":"den Hörer hochnehmen"}],"rule":"Trennbar: hebt ab, hob ab, hat abgehoben. Unregelmäßig (heben).","example":"Ich möchte 100 Euro vom Konto abheben.","exampleEn":"I'd like to withdraw 100 euros from my account.","example2":"Das Flugzeug hebt pünktlich ab.","example2En":"The plane takes off on time."},{"de":"abholen","en":"to pick up, collect","pos":"verb","plural":"","meanings":[{"en":"to pick up / collect a person or thing","de":"jemanden/etwas holen, wegbringen"}],"rule":"Trennbar: holt ab, holte ab, hat abgeholt. + Akkusativ.","example":"Ich hole dich um 8 Uhr vom Bahnhof ab.","exampleEn":"I'll pick you up from the station at 8 o'clock.","example2":"Kannst du das Paket abholen?","example2En":"Can you pick up the package?"},{"de":"das Abitur","en":"school-leaving exam (Abi)","pos":"noun","plural":"","meanings":[{"en":"the German secondary school final exam qualifying for university","de":"Abschlussprüfung am Gymnasium"}],"rule":"Uncountable, no plural. Short form: das Abi (umgangssprachlich).","example":"Sie macht nächstes Jahr ihr Abitur.","exampleEn":"She's taking her school-leaving exam (Abitur) next year.","example2":"Nach dem Abi möchte er studieren.","example2En":"After his Abitur, he wants to study at university."},{"de":"ablegen","en":"to take off, lay down; to take (a test)","pos":"verb","plural":"","meanings":[{"en":"to take off / lay down (coat, item)","de":"etwas weglegen, ausziehen"},{"en":"to take/sit an exam","de":"eine Prüfung machen"}],"rule":"Trennbar: legt ab, legte ab, hat abgelegt.","example":"Bitte legen Sie Ihren Mantel ab.","exampleEn":"Please take off your coat.","example2":"Er hat die Prüfung erfolgreich abgelegt.","example2En":"He passed the exam successfully."},{"de":"ablehnen","en":"to reject, decline","pos":"verb","plural":"","meanings":[{"en":"to reject / refuse / decline something","de":"nein zu etwas sagen, etwas nicht annehmen"}],"rule":"Trennbar: lehnt ab, lehnte ab, hat abgelehnt. + Akkusativ.","example":"Er hat das Angebot abgelehnt.","exampleEn":"He declined the offer.","example2":"Meine Bewerbung wurde abgelehnt.","example2En":"My application was rejected."},{"de":"ablesen","en":"to read off (a meter/display)","pos":"verb","plural":"","meanings":[{"en":"to read off a value from a meter, display, or paper","de":"einen Wert von etwas lesen"}],"rule":"Trennbar: liest ab, las ab, hat abgelesen. Unregelmäßig (lesen).","example":"Der Techniker liest den Stromzähler ab.","exampleEn":"The technician reads off the electricity meter.","example2":"Sie las die Rede vom Blatt ab.","example2En":"She read the speech off the page."},{"de":"die Ablesung","en":"meter reading","pos":"noun","plural":"die Ablesungen","meanings":[{"en":"the act of reading a meter/display","de":"das Ablesen, z. B. des Zählers"}],"rule":"Feminine noun from ablesen; common in utility bills (Zählerablesung).","example":"Die Ablesung des Wasserzählers findet einmal im Jahr statt.","exampleEn":"The water meter reading takes place once a year.","example2":"Bitte notieren Sie das Datum der Ablesung.","example2En":"Please note down the date of the reading."},{"de":"abmelden","en":"to deregister, sign off (sich)","pos":"verb","plural":"","meanings":[{"en":"to deregister / cancel (a service, registration)","de":"etwas offiziell beenden lassen"},{"en":"sich abmelden: to log off / register one's departure","de":"sich offiziell als weggehend melden"}],"rule":"Trennbar, oft reflexiv (sich abmelden): meldet ab, meldete ab, hat abgemeldet.","example":"Ich muss mein Auto abmelden.","exampleEn":"I have to deregister my car.","example2":"Sie hat sich am Computer abgemeldet.","example2En":"She logged off at the computer."},{"de":"die Abmeldung","en":"deregistration, cancellation","pos":"noun","plural":"die Abmeldungen","meanings":[{"en":"official deregistration or cancellation of something","de":"das Abmelden, offizielle Beendigung"}],"rule":"Feminine noun from abmelden; opposite of die Anmeldung.","example":"Die Abmeldung beim Einwohnermeldeamt ist kostenlos.","exampleEn":"Deregistering at the residents' registration office is free.","example2":"Er hat die Abmeldung seines Autos vergessen.","example2En":"He forgot to deregister his car."},{"de":"abschalten","en":"to switch off, turn off","pos":"verb","plural":"","meanings":[{"en":"to switch off / turn off a device","de":"ein Gerät ausschalten"},{"en":"to switch off mentally, relax","de":"sich entspannen, nicht mehr an Arbeit denken"}],"rule":"Trennbar: schaltet ab, schaltete ab, hat abgeschaltet.","example":"Bitte schalte den Computer ab.","exampleEn":"Please switch off the computer.","example2":"Am Wochenende kann ich gut abschalten.","example2En":"On the weekend I can really switch off/relax."},{"de":"abschließen","en":"to lock; to complete, finish","pos":"verb","plural":"","meanings":[{"en":"to lock (a door)","de":"eine Tür mit einem Schlüssel schließen"},{"en":"to complete / finish (a course, contract)","de":"etwas beenden, zu Ende bringen"}],"rule":"Trennbar: schließt ab, schloss ab, hat abgeschlossen. Unregelmäßig (schließen).","example":"Hast du die Tür abgeschlossen?","exampleEn":"Did you lock the door?","example2":"Sie hat ihr Studium letztes Jahr abgeschlossen.","example2En":"She finished her degree last year."},{"de":"der Abschluss","en":"completion, graduation; conclusion","pos":"noun","plural":"die Abschlüsse","meanings":[{"en":"a qualification / graduation / diploma","de":"ein Zeugnis, ein erfolgreiches Ende der Ausbildung"},{"en":"the end/conclusion of something","de":"das Ende von etwas"}],"rule":"Masculine noun from abschließen.","example":"Er hat einen guten Schulabschluss.","exampleEn":"He has a good school-leaving qualification.","example2":"Zum Abschluss sagte die Lehrerin noch etwas.","example2En":"At the end, the teacher said something more."},{"de":"absetzen","en":"to drop off; to deduct","pos":"verb","plural":"","meanings":[{"en":"to drop off (a passenger); to put down","de":"jemanden aussteigen lassen; etwas hinstellen"},{"en":"to deduct (from taxes)","de":"von der Steuer abziehen"}],"rule":"Trennbar: setzt ab, setzte ab, hat abgesetzt.","example":"Er hat mich am Bahnhof abgesetzt.","exampleEn":"He dropped me off at the station.","example2":"Man kann die Kosten von der Steuer absetzen.","example2En":"You can deduct the costs from your taxes."},{"de":"abstellen","en":"to put down, park; to turn off","pos":"verb","plural":"","meanings":[{"en":"to put down / park (a bike, bag)","de":"etwas irgendwohin stellen"},{"en":"to turn off / switch off (water, gas, engine)","de":"etwas ausschalten, stoppen"}],"rule":"Trennbar: stellt ab, stellte ab, hat abgestellt.","example":"Stell dein Fahrrad bitte hier ab.","exampleEn":"Please park your bike here.","example2":"Vergiss nicht, das Wasser abzustellen.","example2En":"Don't forget to turn off the water."},{"de":"die Abteilung","en":"department","pos":"noun","plural":"die Abteilungen","meanings":[{"en":"department (in a company, store, hospital)","de":"Bereich einer Firma, eines Kaufhauses o. Ä."}],"rule":"Feminine noun, plural with -en. Often used with 'in der Abteilung für...'.","example":"Ich arbeite in der Abteilung für Marketing.","exampleEn":"I work in the marketing department.","example2":"Wo finde ich die Abteilung für Schuhe?","example2En":"Where can I find the shoe department?"},{"de":"das Accessoire","en":"accessory","pos":"noun","plural":"die Accessoires","meanings":[{"en":"fashion accessory (bag, jewelry, scarf, etc.)","de":"modischer Zusatzartikel wie Tasche, Schmuck, Schal"}],"rule":"Neuter noun (from French): das Accessoire, plural die Accessoires. Usually used in the plural in everyday speech. Pronounced roughly [akse-SWAR].","example":"Im Schaufenster liegen schöne Accessoires.","exampleEn":"There are beautiful accessories in the shop window.","example2":"Sie kauft gern Accessoires wie Taschen und Gürtel.","example2En":"She likes buying accessories like bags and belts."},{"de":"afrikanisch","en":"African","pos":"adjective","plural":"","meanings":[{"en":"relating to Africa","de":"aus Afrika, zu Afrika gehörend"}],"rule":"Adjective of origin; like other nationality/continent adjectives (deutsch, amerikanisch) it is not normally used in the comparative/superlative. Always written lowercase, unlike the noun 'Afrika'.","example":"Wir essen heute in einem afrikanischen Restaurant.","exampleEn":"We're eating at an African restaurant today.","example2":"Sie hört gern afrikanische Musik.","example2En":"She likes listening to African music."},{"de":"aggressiv","en":"aggressive","pos":"adjective","plural":"","meanings":[{"en":"aggressive, hostile in behavior","de":"feindselig, angriffslustig"}],"rule":"Regular adjective: aggressiv, aggressiver, am aggressivsten.","example":"Der Hund wird aggressiv, wenn Fremde kommen.","exampleEn":"The dog gets aggressive when strangers come.","example2":"Er war im Streit sehr aggressiv.","example2En":"He was very aggressive during the argument."},{"de":"ähnlich","en":"similar","pos":"adjective","plural":"","meanings":[{"en":"similar, alike","de":"fast gleich, vergleichbar"}],"rule":"Regular adjective; used with + Dativ: 'ähnlich sein/sehen + Dativ'. ähnlich, ähnlicher, am ähnlichsten.","example":"Das Kleid ist ähnlich wie meins.","exampleEn":"The dress is similar to mine.","example2":"Sie sieht ihrer Mutter sehr ähnlich.","example2En":"She looks a lot like her mother."},{"de":"die Aktivität","en":"activity","pos":"noun","plural":"die Aktivitäten","meanings":[{"en":"activity, thing one does","de":"Tätigkeit, Beschäftigung"}],"rule":"Feminine noun, plural -en; often used in plural for hobbies/events ('Freizeitaktivitäten').","example":"Im Urlaub machen wir viele Aktivitäten.","exampleEn":"On vacation we do a lot of activities.","example2":"Welche Aktivitäten bietet der Verein an?","example2En":"What activities does the club offer?"},{"de":"aktuell","en":"current, up to date","pos":"adjective","plural":"","meanings":[{"en":"current, present-day","de":"gegenwärtig, im Moment gültig"},{"en":"topical, relevant right now","de":"von aktuellem Interesse"}],"rule":"Regular adjective: aktuell, aktueller, am aktuellsten. False friend: does NOT mean 'actual' (= tatsächlich).","example":"Das ist der aktuelle Stand der Dinge.","exampleEn":"That's the current state of affairs.","example2":"Dieses Thema ist im Moment sehr aktuell.","example2En":"This topic is very topical right now."},{"de":"die Akupunktur","en":"acupuncture","pos":"noun","plural":"","meanings":[{"en":"acupuncture (medical treatment)","de":"Heilmethode mit Nadeln"}],"rule":"Feminine noun, usually uncountable (no plural in everyday use).","example":"Gegen die Rückenschmerzen macht sie Akupunktur.","exampleEn":"She's doing acupuncture for her back pain.","example2":"Der Arzt hat mir Akupunktur empfohlen.","example2En":"The doctor recommended acupuncture to me."},{"de":"alle","en":"all, everyone","pos":"pronoun","plural":"","meanings":[{"en":"all (of them), everyone","de":"jeder, alle Personen/Dinge"},{"en":"finished, used up (colloquial)","de":"nichts mehr davon da, aufgebraucht"}],"rule":"Indefinite pronoun/determiner; declined like an adjective (alle, allen, aller). Colloquial: 'alle sein' = to be all gone.","example":"Alle Schüler waren heute da.","exampleEn":"All the students were there today.","example2":"Die Milch ist alle.","example2En":"The milk is all gone."},{"de":"die Alternative","en":"alternative","pos":"noun","plural":"die Alternativen","meanings":[{"en":"alternative, other option","de":"andere Möglichkeit"}],"rule":"Feminine noun, plural -n. Often with 'zu + Dativ': 'eine Alternative zu...'.","example":"Gibt es eine Alternative zu diesem Termin?","exampleEn":"Is there an alternative to this appointment?","example2":"Fahrrad ist eine gute Alternative zum Auto.","example2En":"The bicycle is a good alternative to the car."},{"de":"das Altglas","en":"used glass (for recycling)","pos":"noun","plural":"","meanings":[{"en":"glass collected for recycling","de":"gebrauchtes Glas zum Recyceln"}],"rule":"Neuter noun, uncountable, no plural. Compound of alt + Glas.","example":"Wir bringen das Altglas zum Container.","exampleEn":"We take the used glass to the recycling container.","example2":"Flaschen gehören in den Altglas-Container.","example2En":"Bottles belong in the glass recycling container."},{"de":"das Amt","en":"office, authority","pos":"noun","plural":"die Ämter","meanings":[{"en":"government office, public authority","de":"Behörde"},{"en":"official post, position","de":"öffentliches Amt, Funktion"}],"rule":"Neuter noun, plural with umlaut: die Ämter.","example":"Ich muss zum Amt, um den Pass zu verlängern.","exampleEn":"I have to go to the office to renew my passport.","example2":"Sie übernimmt ein wichtiges Amt in der Stadt.","example2En":"She's taking on an important office in the city."},{"de":"das Amtsdeutsch","en":"official/bureaucratic German","pos":"noun","plural":"","meanings":[{"en":"formal, bureaucratic style of German used in official documents","de":"komplizierte Sprache in Ämtern und Formularen"}],"rule":"Neuter noun, uncountable, no plural. Compound: Amt + Deutsch.","example":"Das Formular ist voller Amtsdeutsch.","exampleEn":"The form is full of bureaucratic German.","example2":"Amtsdeutsch ist oft schwer zu verstehen.","example2En":"Official German is often hard to understand."},{"de":"anbieten","en":"to offer","pos":"verb","plural":"","meanings":[{"en":"to offer (something to someone)","de":"jemandem etwas zur Verfügung stellen"}],"rule":"Trennbar: bietet ... an; unregelmäßig: bietet an, bot an, hat angeboten. Oft mit + Dativ (Person) + Akkusativ (Sache).","example":"Der Kellner bietet uns die Karte an.","exampleEn":"The waiter offers us the menu.","example2":"Kann ich dir einen Kaffee anbieten?","example2En":"Can I offer you a coffee?"},{"de":"ändern","en":"to change, alter","pos":"verb","plural":"","meanings":[{"en":"to change, modify something","de":"etwas anders machen"},{"en":"(sich ändern) to change, alter oneself/itself","de":"anders werden"}],"rule":"Regelmäßig: ändert, änderte, hat geändert. Auch reflexiv: sich ändern.","example":"Wir müssen den Termin ändern.","exampleEn":"We have to change the appointment.","example2":"Das Wetter ändert sich schnell.","example2En":"The weather changes quickly."},{"de":"anders","en":"different(ly)","pos":"adverb","plural":"","meanings":[{"en":"different, in another way","de":"nicht gleich, auf andere Weise"}],"rule":"Adverb, invariable (no endings). Often with 'als': 'anders als'.","example":"Heute ist alles anders als sonst.","exampleEn":"Today everything is different than usual.","example2":"Er denkt anders über das Thema.","example2En":"He thinks differently about the topic."},{"de":"anerkannt","en":"recognized, accepted","pos":"adjective","plural":"","meanings":[{"en":"officially recognized, accepted","de":"offiziell akzeptiert"}],"rule":"Partizip II von 'anerkennen' als Adjektiv gebraucht; anerkannt, anerkannter, am anerkanntesten.","example":"Ihr Abschluss ist in Deutschland anerkannt.","exampleEn":"Her degree is recognized in Germany.","example2":"Er ist ein anerkannter Experte auf seinem Gebiet.","example2En":"He's a recognized expert in his field."},{"de":"der Anfänger / die Anfängerin","en":"beginner","pos":"noun","plural":"die Anfänger / die Anfängerinnen","meanings":[{"en":"beginner, someone new to something","de":"jemand, der etwas gerade erst lernt"}],"rule":"Maskulin: der Anfänger, Plural die Anfänger; feminin: die Anfängerin, Plural die Anfängerinnen.","example":"Der Kurs ist für Anfänger geeignet.","exampleEn":"The course is suitable for beginners.","example2":"Als Anfängerin macht sie noch viele Fehler.","example2En":"As a beginner, she still makes a lot of mistakes."},{"de":"anfordern","en":"to request; to order (formally)","pos":"verb","plural":"","meanings":[{"en":"to request something officially","de":"etwas offiziell verlangen/bestellen"}],"rule":"trennbar: fordert ... an, forderte an, hat angefordert","example":"Ich fordere die Unterlagen per E-Mail an.","exampleEn":"I request the documents by email.","example2":"Der Arzt fordert ein Blutbild an.","example2En":"The doctor orders a blood test."},{"de":"angeben","en":"to state, indicate; to show off","pos":"verb","plural":"","meanings":[{"en":"to state/indicate (information)","de":"eine Information nennen"},{"en":"to show off, brag","de":"prahlen"}],"rule":"trennbar, irregular: gibt ... an, gab an, hat angegeben","example":"Bitte geben Sie Ihre Adresse an.","exampleEn":"Please state your address.","example2":"Er gibt gern mit seinem neuen Auto an.","example2En":"He likes to show off with his new car."},{"de":"die Angst","en":"fear","pos":"noun","plural":"die Ängste","meanings":[{"en":"fear, anxiety","de":"das Gefühl von Furcht"}],"rule":"Redewendung: Angst haben vor + Dativ","example":"Ich habe Angst vor Spinnen.","exampleEn":"I'm afraid of spiders.","example2":"Keine Angst, alles wird gut.","example2En":"Don't worry, everything will be fine."},{"de":"anhaben","en":"to wear, to have on","pos":"verb","plural":"","meanings":[{"en":"to be wearing (clothes)","de":"Kleidung tragen"}],"rule":"trennbar, irregular: hat ... an, hatte an, hat angehabt","example":"Sie hat heute ein rotes Kleid an.","exampleEn":"She is wearing a red dress today.","example2":"Was hattest du gestern an?","example2En":"What were you wearing yesterday?"},{"de":"anklicken","en":"to click on","pos":"verb","plural":"","meanings":[{"en":"to click on something (computer)","de":"mit der Maus klicken"}],"rule":"trennbar, regelmäßig: klickt ... an, klickte an, hat angeklickt; transitiv (etwas anklicken) - kein 'auf' nötig, anders als bei 'auf etwas klicken'","example":"Klicken Sie den Button an.","exampleEn":"Click on the button.","example2":"Er hat versehentlich den falschen Link angeklickt.","example2En":"He accidentally clicked the wrong link."},{"de":"ankommen","en":"to arrive","pos":"verb","plural":"","meanings":[{"en":"to arrive (at a place)","de":"an einem Ort eintreffen"},{"en":"to depend on, to matter","de":"wichtig sein, abhängen von"}],"rule":"trennbar, irregular: kommt ... an, kam an, ist angekommen; 'es kommt darauf an' = it depends","example":"Der Zug kommt um neun Uhr an.","exampleEn":"The train arrives at nine o'clock.","example2":"Es kommt darauf an, wie viel Zeit wir haben.","example2En":"It depends on how much time we have."},{"de":"ankreuzen","en":"to tick, to check (a box)","pos":"verb","plural":"","meanings":[{"en":"to mark with a cross/tick","de":"ein Kreuz machen"}],"rule":"trennbar, regelmäßig: kreuzt ... an, kreuzte an, hat angekreuzt","example":"Kreuzen Sie die richtige Antwort an.","exampleEn":"Tick the correct answer.","example2":"Ich habe versehentlich zwei Felder angekreuzt.","example2En":"I accidentally checked two boxes."},{"de":"die Ankunft","en":"arrival","pos":"noun","plural":"die Ankünfte","meanings":[{"en":"arrival","de":"das Eintreffen"}],"rule":"Gegenteil: die Abfahrt/der Abflug","example":"Die Ankunft des Fluges verspätet sich.","exampleEn":"The flight's arrival is delayed.","example2":"Bei Ankunft bitte am Schalter melden.","example2En":"Please report to the counter upon arrival."},{"de":"der Anruf","en":"phone call","pos":"noun","plural":"die Anrufe","meanings":[{"en":"a telephone call","de":"ein Telefonat"}],"rule":"Verb dazu: anrufen (trennbar)","example":"Ich habe einen wichtigen Anruf verpasst.","exampleEn":"I missed an important phone call.","example2":"Danke für Ihren Anruf.","example2En":"Thank you for your call."},{"de":"der Anrufer / die Anruferin","en":"caller","pos":"noun","plural":"die Anrufer / die Anruferinnen","meanings":[{"en":"person who calls","de":"jemand, der anruft"}],"rule":"maskuline/feminine Form je nach Geschlecht","example":"Der Anrufer wollte seinen Namen nicht nennen.","exampleEn":"The caller didn't want to give his name.","example2":"Die Anruferin bat um Rückruf.","example2En":"The caller (female) asked for a callback."},{"de":"der Anschluss","en":"connection","pos":"noun","plural":"die Anschlüsse","meanings":[{"en":"connection (train, phone, internet)","de":"eine Verbindung"}],"rule":"häufig: Anschluss verpassen/haben","example":"Wir haben den Anschluss in Köln verpasst.","exampleEn":"We missed the connection in Cologne.","example2":"Haben Sie einen Internetanschluss zu Hause?","example2En":"Do you have an internet connection at home?"},{"de":"der Anschlusszug","en":"connecting train","pos":"noun","plural":"die Anschlusszüge","meanings":[{"en":"train that connects to another train","de":"ein Zug, der Anschluss bietet"}],"rule":"Zusammensetzung aus Anschluss + Zug","example":"Der Anschlusszug wartet auf Gleis 3.","exampleEn":"The connecting train is waiting on platform 3.","example2":"Wir haben den Anschlusszug knapp geschafft.","example2En":"We just barely caught the connecting train."},{"de":"die Anschrift","en":"address","pos":"noun","plural":"die Anschriften","meanings":[{"en":"postal address","de":"die Adresse"}],"rule":"formelles Synonym für 'Adresse'","example":"Bitte geben Sie Ihre Anschrift an.","exampleEn":"Please provide your address.","example2":"Die Anschrift auf dem Brief war falsch.","example2En":"The address on the letter was wrong."},{"de":"der Ansprechpartner / die Ansprechpartnerin","en":"contact person","pos":"noun","plural":"die Ansprechpartner / die Ansprechpartnerinnen","meanings":[{"en":"the person to contact for something","de":"die zuständige Kontaktperson"}],"rule":"oft im Büro-/Formularkontext: 'Ihr Ansprechpartner ist...'","example":"Frau Müller ist Ihre Ansprechpartnerin für Fragen.","exampleEn":"Mrs. Müller is your contact person for questions.","example2":"Wer ist der Ansprechpartner in dieser Abteilung?","example2En":"Who is the contact person in this department?"}]},{"id":"a2-02","title":"A2 · A (2)","level":"A2","words":[{"de":"der Antrag","en":"application, request form","pos":"noun","plural":"die Anträge","meanings":[{"en":"formal application/request","de":"ein offizielles Gesuch"}],"rule":"Redewendung: einen Antrag stellen","example":"Sie hat einen Antrag auf Kindergeld gestellt.","exampleEn":"She submitted an application for child benefit.","example2":"Der Antrag muss bis Freitag eingereicht werden.","example2En":"The application must be submitted by Friday."},{"de":"der Antragsteller / die Antragstellerin","en":"applicant","pos":"noun","plural":"die Antragsteller / die Antragstellerinnen","meanings":[{"en":"person who submits an application","de":"jemand, der einen Antrag stellt"}],"rule":"Zusammensetzung aus Antrag + Steller/in","example":"Der Antragsteller muss alle Dokumente vorlegen.","exampleEn":"The applicant must present all documents.","example2":"Die Antragstellerin wartet auf eine Antwort.","example2En":"The applicant (female) is waiting for a reply."},{"de":"die Anweisung","en":"instruction","pos":"noun","plural":"die Anweisungen","meanings":[{"en":"an instruction or order","de":"eine Handlungsvorgabe"}],"rule":"Redewendung: Anweisungen befolgen/geben","example":"Bitte folgen Sie den Anweisungen auf dem Bildschirm.","exampleEn":"Please follow the instructions on the screen.","example2":"Der Chef gab klare Anweisungen.","example2En":"The boss gave clear instructions."},{"de":"die Apfelschorle","en":"apple juice spritzer","pos":"noun","plural":"die Apfelschorlen","meanings":[{"en":"apple juice mixed with sparkling water","de":"Getränk aus Apfelsaft und Mineralwasser"}],"rule":"Compound of Apfel + Schorle; feminine because Schorle is feminine.","example":"Ich trinke eine Apfelschorle zum Essen.","exampleEn":"I drink an apple juice spritzer with the meal.","example2":"Zwei Apfelschorlen, bitte!","example2En":"Two apple juice spritzers, please!"},{"de":"die App","en":"app","pos":"noun","plural":"die Apps","meanings":[{"en":"mobile application","de":"kleines Programm für Smartphone oder Tablet"}],"rule":"Loanword from English; feminine like 'die Applikation'.","example":"Ich habe eine neue App auf mein Handy geladen.","exampleEn":"I downloaded a new app onto my phone.","example2":"Mit dieser App kann man Fahrkarten kaufen.","example2En":"With this app you can buy tickets."},{"de":"der Appetit","en":"appetite","pos":"noun","plural":"","meanings":[{"en":"desire to eat","de":"Lust, etwas zu essen"}],"rule":"Uncountable; common phrase 'Guten Appetit!' = 'Enjoy your meal!'","example":"Guten Appetit!","exampleEn":"Enjoy your meal!","example2":"Ich habe heute keinen Appetit.","example2En":"I have no appetite today."},{"de":"der Arbeitgeber / die Arbeitgeberin","en":"employer","pos":"noun","plural":"die Arbeitgeber / die Arbeitgeberinnen","meanings":[{"en":"person or company that employs someone","de":"Person oder Firma, die jemanden beschäftigt"}],"rule":"Compound: Arbeit + Geber (one who gives work); masculine form der Arbeitgeber, feminine die Arbeitgeberin.","example":"Mein Arbeitgeber zahlt pünktlich das Gehalt.","exampleEn":"My employer pays the salary on time.","example2":"Die Firma ist ein guter Arbeitgeber.","example2En":"The company is a good employer."},{"de":"die Arbeitsagentur","en":"employment agency","pos":"noun","plural":"die Arbeitsagenturen","meanings":[{"en":"public office that helps people find jobs","de":"staatliche Behörde für Arbeitssuche"}],"rule":"Compound Arbeit + Agentur; refers especially to the German Bundesagentur für Arbeit.","example":"Ich habe einen Termin bei der Arbeitsagentur.","exampleEn":"I have an appointment at the employment agency.","example2":"Die Arbeitsagentur hilft bei der Jobsuche.","example2En":"The employment agency helps with the job search."},{"de":"der Arbeitsauftrag","en":"work order; task assignment","pos":"noun","plural":"die Arbeitsaufträge","meanings":[{"en":"a specific task or job assignment","de":"konkrete Aufgabe, die man erledigen soll"}],"rule":"Compound Arbeit + Auftrag; masculine like Auftrag.","example":"Der Chef gibt mir einen neuen Arbeitsauftrag.","exampleEn":"The boss gives me a new work assignment.","example2":"Bitte lesen Sie den Arbeitsauftrag genau.","example2En":"Please read the task assignment carefully."},{"de":"der Arbeitsbeginn","en":"start of work","pos":"noun","plural":"","meanings":[{"en":"the time work starts","de":"Uhrzeit, zu der die Arbeit beginnt"}],"rule":"Compound Arbeit + Beginn; usually uncountable, used with a time.","example":"Der Arbeitsbeginn ist um acht Uhr.","exampleEn":"Work starts at eight o'clock.","example2":"Bitte seien Sie pünktlich zum Arbeitsbeginn.","example2En":"Please be on time for the start of work."},{"de":"die Arbeitserlaubnis","en":"work permit","pos":"noun","plural":"die Arbeitserlaubnisse","meanings":[{"en":"official permission to work","de":"offizielle Genehmigung, in einem Land zu arbeiten"}],"rule":"Compound Arbeit + Erlaubnis; feminine like Erlaubnis; nouns ending in -nis double the s in the plural (Erlaubnis → Erlaubnisse).","example":"Für diese Stelle brauche ich eine Arbeitserlaubnis.","exampleEn":"For this job I need a work permit.","example2":"Ohne Arbeitserlaubnis darf sie nicht arbeiten.","example2En":"Without a work permit she is not allowed to work."},{"de":"das Arbeitslosengeld","en":"unemployment benefit","pos":"noun","plural":"","meanings":[{"en":"government payment to unemployed people","de":"Geld vom Staat für Arbeitslose"}],"rule":"Compound arbeitslos + Geld; neuter like Geld; uncountable.","example":"Er bekommt seit drei Monaten Arbeitslosengeld.","exampleEn":"He has been receiving unemployment benefit for three months.","example2":"Man muss das Arbeitslosengeld beantragen.","example2En":"You have to apply for unemployment benefit."},{"de":"der Arbeitsplatz","en":"workplace; job","pos":"noun","plural":"die Arbeitsplätze","meanings":[{"en":"the place where one works","de":"Ort, an dem man arbeitet"},{"en":"a job position","de":"Stelle / Beschäftigung"}],"rule":"Compound Arbeit + Platz; masculine like Platz.","example":"Mein Arbeitsplatz ist im dritten Stock.","exampleEn":"My workplace is on the third floor.","example2":"Die Firma hat viele Arbeitsplätze geschaffen.","example2En":"The company has created many jobs."},{"de":"der Arbeitsschutz","en":"occupational safety","pos":"noun","plural":"","meanings":[{"en":"rules and measures to protect workers","de":"Regeln zum Schutz der Arbeitnehmer"}],"rule":"Compound Arbeit + Schutz; uncountable.","example":"Der Arbeitsschutz ist in dieser Fabrik sehr wichtig.","exampleEn":"Occupational safety is very important in this factory.","example2":"Wir tragen Helme wegen des Arbeitsschutzes.","example2En":"We wear helmets because of occupational safety rules."},{"de":"die Arbeitsvermittlung","en":"job placement (service)","pos":"noun","plural":"die Arbeitsvermittlungen","meanings":[{"en":"a service that helps match people with jobs","de":"Vermittlung von Arbeitsstellen"}],"rule":"Compound Arbeit + Vermittlung; feminine like Vermittlung.","example":"Die Arbeitsvermittlung hat mir eine neue Stelle vermittelt.","exampleEn":"The job placement service found me a new position.","example2":"Er sucht Hilfe bei der Arbeitsvermittlung.","example2En":"He is looking for help from the job placement service."},{"de":"der Arbeitsvertrag","en":"employment contract","pos":"noun","plural":"die Arbeitsverträge","meanings":[{"en":"legal agreement between employer and employee","de":"Vertrag zwischen Arbeitgeber und Arbeitnehmer"}],"rule":"Compound Arbeit + Vertrag; masculine like Vertrag.","example":"Ich habe meinen Arbeitsvertrag unterschrieben.","exampleEn":"I signed my employment contract.","example2":"Der Arbeitsvertrag dauert zwei Jahre.","example2En":"The employment contract runs for two years."},{"de":"die Architektur","en":"architecture","pos":"noun","plural":"","meanings":[{"en":"the art and science of designing buildings","de":"Baukunst, Gestaltung von Gebäuden"}],"rule":"Uncountable in the general sense; stress on the last syllable (Architektúr).","example":"Sie interessiert sich sehr für Architektur.","exampleEn":"She is very interested in architecture.","example2":"Die Architektur der Stadt ist sehr alt.","example2En":"The architecture of the city is very old."},{"de":"die Armut","en":"poverty","pos":"noun","plural":"","meanings":[{"en":"the state of being poor","de":"Zustand, wenig Geld zu haben"}],"rule":"Uncountable abstract noun derived from the adjective 'arm' (poor); feminine gender, no plural.","example":"Viele Menschen leben in Armut.","exampleEn":"Many people live in poverty.","example2":"Die Regierung will die Armut bekämpfen.","example2En":"The government wants to fight poverty."},{"de":"asiatisch","en":"Asian","pos":"adjective","plural":"","meanings":[{"en":"relating to Asia","de":"aus Asien, zu Asien gehörend"}],"rule":"Regular adjective, no irregular comparison; lowercase unlike the noun 'Asien'.","example":"Wir essen gern asiatisches Essen.","exampleEn":"We like eating Asian food.","example2":"Er hat einen asiatischen Freund.","example2En":"He has an Asian friend."},{"de":"die Aubergine","en":"eggplant, aubergine","pos":"noun","plural":"die Auberginen","meanings":[{"en":"a purple vegetable (eggplant)","de":"violettes Gemüse"}],"rule":"French loanword; feminine; pronounced with soft 'g' like in French (Auberschine).","example":"Ich kaufe zwei Auberginen für das Gericht.","exampleEn":"I buy two eggplants for the dish.","example2":"Auberginen schmecken gut gegrillt.","example2En":"Eggplants taste good grilled."},{"de":"der Aufenthalt","en":"stay; residence","pos":"noun","plural":"die Aufenthalte","meanings":[{"en":"stay (period of time somewhere)","de":"das Verweilen an einem Ort"},{"en":"stopover (e.g. on a journey)","de":"kurzer Zwischenstopp, z. B. bei einer Reise"}],"rule":"Abgeleitet vom Verb sich aufhalten (= sich an einem Ort befinden) – kein Kompositum. Oft mit Dauerangabe: 'ein Aufenthalt von drei Tagen'.","example":"Wir hatten einen Aufenthalt von zwei Wochen in Berlin.","exampleEn":"We had a stay of two weeks in Berlin.","example2":"Der Zug hat in Köln zehn Minuten Aufenthalt.","example2En":"The train has a ten-minute stopover in Cologne."},{"de":"die Aufenthaltserlaubnis","en":"residence permit","pos":"noun","plural":"die Aufenthaltserlaubnisse","meanings":[{"en":"official permit to live in a country","de":"offizielle Erlaubnis, in einem Land zu wohnen"}],"rule":"Compound noun: Aufenthalt + Erlaubnis; gender follows die Erlaubnis.","example":"Sie braucht eine Aufenthaltserlaubnis für Deutschland.","exampleEn":"She needs a residence permit for Germany.","example2":"Die Aufenthaltserlaubnis gilt für zwei Jahre.","example2En":"The residence permit is valid for two years."},{"de":"aufheben","en":"to pick up; to keep; to cancel","pos":"verb","plural":"","meanings":[{"en":"to pick something up from the ground","de":"etwas vom Boden nehmen"},{"en":"to keep/save something for later","de":"etwas für später aufbewahren"},{"en":"to cancel/abolish (a rule, law)","de":"eine Regel oder ein Gesetz ungültig machen"}],"rule":"Trennbar, unregelmäßig: hebt ... auf, hob auf, hat aufgehoben.","example":"Kannst du den Schlüssel aufheben?","exampleEn":"Can you pick up the key?","example2":"Ich hebe die Rechnung für die Steuer auf.","example2En":"I'm keeping the receipt for taxes."},{"de":"aufhören","en":"to stop","pos":"verb","plural":"","meanings":[{"en":"to stop doing something","de":"etwas nicht mehr tun"}],"rule":"Trennbar: hört ... auf, hörte auf, hat aufgehört. Oft mit 'mit + Dativ' oder 'zu + Infinitiv'.","example":"Hör auf zu reden!","exampleEn":"Stop talking!","example2":"Der Regen hat endlich aufgehört.","example2En":"The rain has finally stopped."},{"de":"die Auflistung","en":"listing; list","pos":"noun","plural":"die Auflistungen","meanings":[{"en":"a listing/enumeration of items","de":"eine Liste von Dingen"}],"rule":"Von auflisten (trennbar) abgeleitetes Nomen.","example":"Bitte schicken Sie mir eine Auflistung aller Kosten.","exampleEn":"Please send me a listing of all costs.","example2":"Die Auflistung der Termine liegt auf dem Tisch.","example2En":"The list of appointments is on the table."},{"de":"aufpassen","en":"to pay attention; to watch out","pos":"verb","plural":"","meanings":[{"en":"to pay attention/be careful","de":"vorsichtig sein, konzentriert sein"},{"en":"to look after (someone/something)","de":"auf jemanden/etwas achten"}],"rule":"Trennbar: passt ... auf, passte auf, hat aufgepasst. Oft mit 'auf + Akkusativ'.","example":"Pass auf, die Straße ist glatt!","exampleEn":"Watch out, the street is slippery!","example2":"Kannst du auf meine Tasche aufpassen?","example2En":"Can you watch my bag?"},{"de":"aufrufen","en":"to call out; to call up","pos":"verb","plural":"","meanings":[{"en":"to call someone's name/number (e.g. in a waiting room)","de":"jemandes Namen oder Nummer laut nennen"},{"en":"to call up/open (e.g. a website)","de":"eine Internetseite öffnen"}],"rule":"Trennbar, unregelmäßig: ruft ... auf, rief auf, hat aufgerufen.","example":"Der Arzt hat meinen Namen aufgerufen.","exampleEn":"The doctor called out my name.","example2":"Ich rufe die Webseite auf meinem Handy auf.","example2En":"I'm calling up the website on my phone."},{"de":"aufschließen","en":"to unlock","pos":"verb","plural":"","meanings":[{"en":"to unlock a door/lock with a key","de":"eine Tür oder ein Schloss mit einem Schlüssel öffnen"}],"rule":"Trennbar, unregelmäßig: schließt ... auf, schloss auf, hat aufgeschlossen.","example":"Kannst du bitte die Tür aufschließen?","exampleEn":"Can you please unlock the door?","example2":"Er schloss das Büro morgens immer auf.","example2En":"He always unlocked the office in the morning."},{"de":"der Aufzug","en":"elevator; lift","pos":"noun","plural":"die Aufzüge","meanings":[{"en":"elevator/lift","de":"Fahrstuhl in einem Gebäude"}],"rule":"Synonym: der Fahrstuhl. Von aufziehen abgeleitet.","example":"Wir nehmen den Aufzug in den fünften Stock.","exampleEn":"We take the elevator to the fifth floor.","example2":"Der Aufzug ist heute leider kaputt.","example2En":"The elevator is unfortunately broken today."},{"de":"der Ausbildungsplatz","en":"apprenticeship position","pos":"noun","plural":"die Ausbildungsplätze","meanings":[{"en":"a training/apprenticeship position at a company","de":"eine Stelle für eine berufliche Ausbildung"}],"rule":"Kompositum aus Ausbildung + Platz.","example":"Er sucht einen Ausbildungsplatz als Elektriker.","exampleEn":"He is looking for an apprenticeship as an electrician.","example2":"Die Firma bietet drei Ausbildungsplätze an.","example2En":"The company offers three apprenticeship positions."},{"de":"ausblenden","en":"to hide; to fade out","pos":"verb","plural":"","meanings":[{"en":"to hide/remove from view (e.g. on a screen)","de":"etwas nicht mehr anzeigen, z. B. am Bildschirm"}],"rule":"Trennbar: blendet ... aus, blendete aus, hat ausgeblendet.","example":"Ich blende die Werbung auf der Seite aus.","exampleEn":"I hide the ads on the page.","example2":"Man kann die Spalte in der Tabelle ausblenden.","example2En":"You can hide the column in the table."},{"de":"ausdrucken","en":"to print out","pos":"verb","plural":"","meanings":[{"en":"to print a document on paper","de":"ein Dokument auf Papier drucken"}],"rule":"Trennbar: druckt ... aus, druckte aus, hat ausgedruckt.","example":"Kannst du mir die Rechnung ausdrucken?","exampleEn":"Can you print out the invoice for me?","example2":"Ich habe den Fahrplan ausgedruckt.","example2En":"I printed out the timetable."},{"de":"ausfallen","en":"to be cancelled; to fall out","pos":"verb","plural":"","meanings":[{"en":"to be cancelled (e.g. a class, event)","de":"nicht stattfinden"},{"en":"to fall out (e.g. hair)","de":"z. B. Haare: herausfallen"}],"rule":"Trennbar, unregelmäßig: fällt ... aus, fiel aus, ist ausgefallen.","example":"Der Unterricht fällt morgen aus.","exampleEn":"Class is cancelled tomorrow.","example2":"Nach der Krankheit sind ihr die Haare ausgefallen.","example2En":"After the illness her hair fell out."},{"de":"der Ausflug","en":"excursion; trip","pos":"noun","plural":"die Ausflüge","meanings":[{"en":"a short trip/excursion","de":"eine kurze Reise, z. B. für einen Tag"}],"rule":"Von ausfliegen; feststehende Wendung: einen Ausflug machen.","example":"Am Wochenende machen wir einen Ausflug in die Berge.","exampleEn":"On the weekend we're going on a trip to the mountains.","example2":"Der Ausflug mit der Schule war sehr lustig.","example2En":"The school trip was a lot of fun."},{"de":"ausführen","en":"to carry out; to take out","pos":"verb","plural":"","meanings":[{"en":"to carry out/execute (a task, order)","de":"eine Aufgabe oder einen Auftrag erledigen"},{"en":"to take out (e.g. a dog, someone for dinner)","de":"jemanden/etwas mit nach draußen nehmen"}],"rule":"Trennbar: führt ... aus, führte aus, hat ausgeführt.","example":"Er hat den Auftrag genau ausgeführt.","exampleEn":"He carried out the order exactly.","example2":"Sie führt jeden Abend den Hund aus.","example2En":"She takes the dog out every evening."},{"de":"ausgeben","en":"to spend (money); to give out","pos":"verb","plural":"","meanings":[{"en":"to spend money","de":"Geld für etwas verwenden"},{"en":"to give out/distribute","de":"etwas verteilen, austeilen"}],"rule":"Trennbar, unregelmäßig: gibt ... aus, gab aus, hat ausgegeben.","example":"Ich habe zu viel Geld für Kleidung ausgegeben.","exampleEn":"I spent too much money on clothes.","example2":"Die Lehrerin gibt die Arbeitsblätter aus.","example2En":"The teacher hands out the worksheets."},{"de":"ausgezeichnet","en":"excellent","pos":"adjective","plural":"","meanings":[{"en":"excellent, very good","de":"sehr gut"}],"rule":"Wird meist nicht gesteigert, da es selbst schon eine sehr hohe Qualität ausdrückt (ausgezeichnet, ausgezeichneter, am ausgezeichnetsten – selten verwendet). Auch Partizip II von 'auszeichnen' (jemanden/etwas mit etwas auszeichnen).","example":"Das Essen im Restaurant war ausgezeichnet.","exampleEn":"The food at the restaurant was excellent.","example2":"Sie spricht ausgezeichnet Deutsch.","example2En":"She speaks excellent German."},{"de":"der Ausgleich","en":"balance; compensation","pos":"noun","plural":"die Ausgleiche","meanings":[{"en":"compensation/balancing (out) of a difference","de":"das Ausgleichen eines Unterschieds"},{"en":"equalizer (sport)","de":"Tor oder Punkt, der den Spielstand ausgleicht"}],"rule":"Von ausgleichen abgeleitet. Feste Wendung: zum Ausgleich (als Kompensation).","example":"Sport ist für mich ein guter Ausgleich zur Arbeit.","exampleEn":"Sport is a good balance for me against work.","example2":"In der letzten Minute gelang ihm der Ausgleich.","example2En":"In the last minute he scored the equalizer."},{"de":"der Aushilfsjob","en":"temp job; casual/part-time job","pos":"noun","plural":"die Aushilfsjobs","meanings":[{"en":"a temporary or casual job, often to earn extra money","de":"eine vorübergehende Arbeit, oft als Nebenjob"}],"rule":"Compound noun: Aushilfe (help/stand-in) + Job; masculine like 'der Job'.","example":"Ich habe im Sommer einen Aushilfsjob im Supermarkt.","exampleEn":"I have a temp job at the supermarket in summer.","example2":"Der Aushilfsjob war gut für mein Studium.","example2En":"The temp job was good alongside my studies."},{"de":"das Ausland","en":"abroad; foreign countries","pos":"noun","plural":"","meanings":[{"en":"foreign countries, abroad (opposite of Inland)","de":"fremde Länder, nicht das eigene Land"}],"rule":"Uncountable, no plural. Used with prepositions: 'im Ausland' (abroad), 'ins Ausland' (to abroad).","example":"Meine Schwester lebt im Ausland.","exampleEn":"My sister lives abroad.","example2":"Er fliegt nächste Woche ins Ausland.","example2En":"He is flying abroad next week."},{"de":"das Ausländeramt","en":"immigration office","pos":"noun","plural":"die Ausländerämter","meanings":[{"en":"the office that handles residence permits for foreigners","de":"das Amt, das für Aufenthaltstitel von Ausländern zuständig ist"}],"rule":"Older/informal term; official term today is often 'Ausländerbehörde'. Compound: Ausländer + Amt.","example":"Ich muss zum Ausländeramt, um meine Papiere zu verlängern.","exampleEn":"I have to go to the immigration office to extend my papers.","example2":"Das Ausländeramt hat heute geschlossen.","example2En":"The immigration office is closed today."},{"de":"die Ausländerbehörde","en":"immigration authority","pos":"noun","plural":"die Ausländerbehörden","meanings":[{"en":"the government authority responsible for foreigners' residence matters","de":"die Behörde, die für Aufenthaltsfragen von Ausländern zuständig ist"}],"rule":"Compound noun: Ausländer + Behörde (die); official term used in most German cities.","example":"Die Ausländerbehörde prüft meinen Antrag.","exampleEn":"The immigration authority is checking my application.","example2":"Ich habe einen Termin bei der Ausländerbehörde.","example2En":"I have an appointment at the immigration authority."},{"de":"ausmachen","en":"to turn off; to arrange/agree on; to matter","pos":"verb","plural":"","meanings":[{"en":"to switch off (light, TV, etc.)","de":"ausschalten"},{"en":"to arrange or agree on something","de":"vereinbaren"},{"en":"to matter, to make a difference","de":"eine Rolle spielen, wichtig sein"}],"rule":"Trennbar (separable): macht ... aus, machte ... aus, hat ... ausgemacht.","example":"Kannst du bitte das Licht ausmachen?","exampleEn":"Can you please turn off the light?","example2":"Macht es dir etwas aus, wenn ich rauche?","example2En":"Does it bother you if I smoke?"},{"de":"ausreichend","en":"sufficient; enough","pos":"adjective","plural":"","meanings":[{"en":"enough, sufficient in quantity or quality","de":"genug, genügend"}],"rule":"Regular comparison: ausreichend, ausreichender, am ausreichendsten (rarely used in comparative forms).","example":"Wir haben ausreichend Essen für alle.","exampleEn":"We have enough food for everyone.","example2":"Seine Deutschkenntnisse sind ausreichend.","example2En":"His German skills are sufficient."},{"de":"die Ausrüstung","en":"equipment; gear","pos":"noun","plural":"die Ausrüstungen","meanings":[{"en":"equipment or gear needed for an activity","de":"die Geräte oder Sachen, die man für eine Tätigkeit braucht"}],"rule":"Usually singular in everyday use, though a plural form exists for different sets of equipment.","example":"Für die Wanderung brauchen wir gute Ausrüstung.","exampleEn":"We need good equipment for the hike.","example2":"Die Ausrüstung der Feuerwehr ist sehr modern.","example2En":"The fire department's equipment is very modern."},{"de":"aussehen","en":"to look (like); to appear","pos":"verb","plural":"","meanings":[{"en":"to look a certain way, to appear","de":"einen bestimmten Eindruck machen, erscheinen"}],"rule":"Trennbar; irregular: sieht ... aus, sah ... aus, hat ... ausgesehen.","example":"Du siehst heute müde aus.","exampleEn":"You look tired today.","example2":"Das Essen sieht sehr lecker aus.","example2En":"The food looks very delicious."},{"de":"der Außendienst","en":"field service; sales representative role","pos":"noun","plural":"","meanings":[{"en":"work done outside the office, e.g. sales visits","de":"Arbeit außerhalb des Büros, z. B. beim Kunden"}],"rule":"Usually uncountable; opposite of 'Innendienst'. Often used as 'im Außendienst arbeiten'.","example":"Er arbeitet im Außendienst als Vertreter.","exampleEn":"He works in field service as a sales rep.","example2":"Der Außendienst besucht die Kunden vor Ort.","example2En":"The field team visits customers on site."},{"de":"außer","en":"except; besides; out of","pos":"preposition","plural":"","meanings":[{"en":"except, apart from","de":"ausgenommen"},{"en":"out of (a state), e.g. außer Betrieb","de":"nicht mehr in einem Zustand, z. B. außer Betrieb"}],"rule":"Governs Dativ; e.g. 'außer mir', 'außer dem Chef'.","example":"Alle waren da, außer Tom.","exampleEn":"Everyone was there except Tom.","example2":"Der Aufzug ist außer Betrieb.","example2En":"The elevator is out of service."},{"de":"die Aussicht","en":"view; prospect","pos":"noun","plural":"die Aussichten","meanings":[{"en":"a scenic view","de":"der Blick auf die Landschaft"},{"en":"a prospect or chance for the future","de":"eine Chance oder Möglichkeit für die Zukunft"}],"rule":"Compound: aus + Sicht; 'Aussicht auf etwas haben' = to have a chance/prospect of something.","example":"Von hier hat man eine schöne Aussicht auf die Berge.","exampleEn":"From here you have a beautiful view of the mountains.","example2":"Er hat gute Aussichten auf den Job.","example2En":"He has good prospects for the job."},{"de":"aussteigen","en":"to get out/off (a vehicle); to quit","pos":"verb","plural":"","meanings":[{"en":"to get off/out of a vehicle (bus, train, car)","de":"ein Fahrzeug verlassen"},{"en":"to quit, to withdraw from something","de":"bei etwas nicht mehr mitmachen"}],"rule":"Trennbar, uses 'sein' as auxiliary: steigt ... aus, stieg ... aus, ist ... ausgestiegen.","example":"Ich steige an der nächsten Haltestelle aus.","exampleEn":"I'm getting off at the next stop.","example2":"Er ist aus dem Projekt ausgestiegen.","example2En":"He dropped out of the project."}]},{"id":"a2-03","title":"A2 · A–B (3)","level":"A2","words":[{"de":"aussuchen","en":"to choose; to pick out","pos":"verb","plural":"","meanings":[{"en":"to select something from a range of options","de":"etwas auswählen"}],"rule":"Trennbar: sucht ... aus, suchte ... aus, hat ... ausgesucht. Often used reflexively: sich etwas aussuchen.","example":"Such dir ein Geschenk aus.","exampleEn":"Pick out a gift for yourself.","example2":"Wir haben uns ein schönes Hotel ausgesucht.","example2En":"We chose a nice hotel."},{"de":"der Ausweis","en":"ID card; identity document","pos":"noun","plural":"die Ausweise","meanings":[{"en":"an official identity document (ID card, passport, etc.)","de":"ein amtliches Dokument zur Identifizierung"}],"rule":"Compound related to 'ausweisen'; 'sich ausweisen' = to show ID/identify oneself.","example":"Zeigen Sie bitte Ihren Ausweis.","exampleEn":"Please show your ID.","example2":"Ich habe meinen Ausweis verloren.","example2En":"I lost my ID card."},{"de":"ausziehen","en":"to take off (clothes); to move out","pos":"verb","plural":"","meanings":[{"en":"to take off clothing","de":"Kleidung ablegen"},{"en":"to move out of a home","de":"eine Wohnung verlassen"}],"rule":"Trennbar; irregular: zieht ... aus, zog ... aus, hat/ist ... ausgezogen (hat for clothes, ist for moving out).","example":"Zieh bitte deine Schuhe aus.","exampleEn":"Please take off your shoes.","example2":"Sie ist letzten Monat ausgezogen.","example2En":"She moved out last month."},{"de":"das Autofahren","en":"driving (a car)","pos":"noun","plural":"","meanings":[{"en":"the activity of driving a car","de":"mit dem Auto fahren"}],"rule":"Verbal noun from 'Auto fahren'; neuter, uncountable, capitalized as a noun.","example":"Autofahren macht mir Spaß.","exampleEn":"I enjoy driving.","example2":"Er hat das Autofahren mit 18 gelernt.","example2En":"He learned to drive at 18."},{"de":"der Automat","en":"vending machine; automatic machine","pos":"noun","plural":"die Automaten","meanings":[{"en":"a vending or ticket machine that works automatically","de":"eine Maschine, die automatisch funktioniert, z. B. Verkaufsautomat"}],"rule":"Weak noun (n-Deklination): der Automat, den/dem/des Automaten.","example":"Am Automaten kann man Tickets kaufen.","exampleEn":"You can buy tickets at the machine.","example2":"Der Automat ist leider kaputt.","example2En":"The machine is unfortunately broken."},{"de":"der Autounfall","en":"car accident","pos":"noun","plural":"die Autounfälle","meanings":[{"en":"a collision involving a car","de":"ein Unfall mit einem Auto"}],"rule":"Compound noun: Auto + Unfall; gender follows der Unfall.","example":"Gestern hatte mein Nachbar einen Autounfall.","exampleEn":"Yesterday my neighbor had a car accident.","example2":"Bei dem Autounfall wurde niemand verletzt.","example2En":"No one was injured in the car accident."},{"de":"der Babyartikel","en":"baby product","pos":"noun","plural":"die Babyartikel","meanings":[{"en":"a product/item for babies (e.g. diapers, bottles)","de":"ein Produkt für Babys"}],"rule":"Compound: Baby + Artikel; gender follows der Artikel (masc.), plural unchanged: die Babyartikel. Often used in the plural to refer to baby products in general.","example":"Im Supermarkt gibt es eine Abteilung für Babyartikel.","exampleEn":"There is a baby-products section in the supermarket.","example2":"Wir haben viele Babyartikel für das neue Kind gekauft.","example2En":"We bought a lot of baby products for the new child."},{"de":"der Babysitter / die Babysitterin","en":"babysitter","pos":"noun","plural":"die Babysitter / die Babysitterinnen","meanings":[{"en":"a person who looks after children for pay","de":"jemand, der auf Kinder aufpasst"}],"rule":"Loanword from English; masculine form also used generically.","example":"Am Samstag kommt ein Babysitter für unsere Tochter.","exampleEn":"On Saturday a babysitter is coming for our daughter.","example2":"Sie arbeitet als Babysitterin für zwei Kinder.","example2En":"She works as a babysitter for two children."},{"de":"der Bäckereifachverkäufer / die Bäckereifachverkäuferin","en":"trained bakery sales assistant","pos":"noun","plural":"die Bäckereifachverkäufer / die Bäckereifachverkäuferinnen","meanings":[{"en":"a person trained to sell bakery products","de":"jemand, der Brot und Backwaren verkauft (mit Ausbildung)"}],"rule":"Compound: Bäckerei + Fachverkäufer(in); job title after vocational training.","example":"Er macht eine Ausbildung zum Bäckereifachverkäufer.","exampleEn":"He is training to become a bakery sales assistant.","example2":"Die Bäckereifachverkäuferin berät die Kunden freundlich.","example2En":"The bakery sales assistant advises the customers in a friendly way."},{"de":"die Badesachen","en":"swimwear / swimming gear","pos":"noun","plural":"die Badesachen","meanings":[{"en":"clothes and items needed for swimming/bathing","de":"Kleidung und Sachen zum Schwimmen/Baden"}],"rule":"Used only in plural (Plural).","example":"Vergiss deine Badesachen nicht, wir gehen zum See.","exampleEn":"Don't forget your swimming gear, we're going to the lake.","example2":"Ich packe die Badesachen in die Tasche.","example2En":"I'm packing the swimming gear into the bag."},{"de":"das Bahnfahren","en":"traveling by train","pos":"noun","plural":"","meanings":[{"en":"the activity of traveling by train","de":"das Reisen mit dem Zug"}],"rule":"Nominalized infinitive (das + Verb); uncountable, no plural.","example":"Bahnfahren ist oft günstiger als Fliegen.","exampleEn":"Traveling by train is often cheaper than flying.","example2":"Ich mag das Bahnfahren durch die Berge.","example2En":"I like traveling by train through the mountains."},{"de":"der Bahnsteig","en":"platform (train)","pos":"noun","plural":"die Bahnsteige","meanings":[{"en":"the raised area beside the tracks where passengers wait","de":"der Ort am Gleis, wo man auf den Zug wartet"}],"rule":"Compound: Bahn + Steig; not to be confused with 'Gleis' (track).","example":"Der Zug fährt von Bahnsteig 3 ab.","exampleEn":"The train departs from platform 3.","example2":"Wir warten auf dem Bahnsteig auf den Zug.","example2En":"We are waiting for the train on the platform."},{"de":"die Band","en":"(music) band","pos":"noun","plural":"die Bands","meanings":[{"en":"a group of musicians","de":"eine Gruppe von Musikern"}],"rule":"Loanword from English; feminine gender, plural with -s.","example":"Meine Freunde haben eine eigene Band.","exampleEn":"My friends have their own band.","example2":"Die Band spielt heute Abend im Club.","example2En":"The band is playing at the club tonight."},{"de":"die Bankkarte","en":"bank card","pos":"noun","plural":"die Bankkarten","meanings":[{"en":"a card used for banking/payment","de":"eine Karte für Geld und Bezahlung"}],"rule":"Compound: Bank + Karte; gender from die Karte.","example":"Ich bezahle immer mit meiner Bankkarte.","exampleEn":"I always pay with my bank card.","example2":"Meine Bankkarte ist leider nicht mehr gültig.","example2En":"Unfortunately my bank card is no longer valid."},{"de":"der Bankkaufmann / die Bankkauffrau","en":"bank clerk (trained)","pos":"noun","plural":"die Bankkaufleute","meanings":[{"en":"a person professionally trained in banking","de":"jemand mit einer Ausbildung im Bankwesen"}],"rule":"Irregular plural: Bankkaufleute (from Kaufmann/Kauffrau → Kaufleute).","example":"Sie ist Bankkauffrau bei einer großen Bank.","exampleEn":"She is a trained bank clerk at a large bank.","example2":"Er hat seine Ausbildung zum Bankkaufmann abgeschlossen.","example2En":"He completed his training as a bank clerk."},{"de":"die Bankleitzahl","en":"bank sort code","pos":"noun","plural":"die Bankleitzahlen","meanings":[{"en":"a number identifying a bank branch","de":"eine Nummer, die eine Bank identifiziert"}],"rule":"Compound: Bank + Leitzahl; abbreviated BLZ, mostly replaced by IBAN today.","example":"Geben Sie bitte die Bankleitzahl und die Kontonummer an.","exampleEn":"Please provide the bank sort code and account number.","example2":"Die Bankleitzahl steht auf der Rechnung.","example2En":"The bank sort code is on the invoice."},{"de":"der Bankschalter","en":"bank counter","pos":"noun","plural":"die Bankschalter","meanings":[{"en":"the counter at a bank where customers are served","de":"der Schalter in einer Bank, an dem man bedient wird"}],"rule":"Compound: Bank + Schalter; gender from der Schalter.","example":"Am Bankschalter kann man Geld abheben.","exampleEn":"You can withdraw money at the bank counter.","example2":"Er wartet am Bankschalter auf seinen Termin.","example2En":"He is waiting at the bank counter for his appointment."},{"de":"bar","en":"in cash","pos":"adjective","plural":"","meanings":[{"en":"paid with cash, not by card","de":"mit Bargeld bezahlt"}],"rule":"Often used adverbially with 'bezahlen': 'bar bezahlen' = pay in cash.","example":"Ich bezahle lieber bar.","exampleEn":"I prefer to pay in cash.","example2":"Kann ich hier bar bezahlen?","example2En":"Can I pay in cash here?"},{"de":"das Bargeld","en":"cash","pos":"noun","plural":"","meanings":[{"en":"physical money (coins and notes)","de":"Geld in Scheinen und Münzen"}],"rule":"Uncountable, no plural; compound: bar + Geld.","example":"Ich habe kein Bargeld dabei.","exampleEn":"I don't have any cash with me.","example2":"An diesem Automaten kann man Bargeld abheben.","example2En":"You can withdraw cash at this machine."},{"de":"bargeldlos","en":"cashless","pos":"adjective","plural":"","meanings":[{"en":"without using cash, e.g. by card or transfer","de":"ohne Bargeld, z. B. mit Karte"}],"rule":"Adjective formed with suffix -los (without); opposite of 'bar'.","example":"Viele Kunden zahlen heute bargeldlos.","exampleEn":"Many customers pay cashless today.","example2":"Bargeldlose Zahlung ist hier möglich.","example2En":"Cashless payment is possible here."},{"de":"der Bart","en":"beard","pos":"noun","plural":"die Bärte","meanings":[{"en":"facial hair on the chin/cheeks","de":"Haare im Gesicht, am Kinn"}],"rule":"Plural with umlaut: der Bart → die Bärte.","example":"Mein Vater hat einen grauen Bart.","exampleEn":"My father has a gray beard.","example2":"Er rasiert sich jeden Tag den Bart.","example2En":"He shaves his beard every day."},{"de":"die Basis","en":"basis; base","pos":"noun","plural":"die Basen","meanings":[{"en":"the foundation or starting point of something","de":"die Grundlage von etwas"}],"rule":"Irregular plural: die Basis → die Basen (like Greek/Latin loanwords).","example":"Gute Grammatik ist die Basis für gutes Deutsch.","exampleEn":"Good grammar is the basis for good German.","example2":"Auf dieser Basis können wir weiterarbeiten.","example2En":"We can continue working on this basis."},{"de":"der Basketball","en":"basketball","pos":"noun","plural":"die Basketbälle","meanings":[{"en":"the sport basketball","de":"die Sportart Basketball"},{"en":"the ball used in basketball","de":"der Ball für dieses Spiel"}],"rule":"Compound: Basket + Ball; plural like 'der Ball' → 'die Bälle'.","example":"Meine Kinder spielen gern Basketball.","exampleEn":"My kids like playing basketball.","example2":"Der Basketball liegt im Schrank.","example2En":"The basketball is in the cupboard."},{"de":"basteln","en":"to do handicrafts; to make (by hand)","pos":"verb","plural":"","meanings":[{"en":"to make/craft things by hand (as a hobby)","de":"etwas mit den Händen herstellen"}],"rule":"regular weak verb: bastelt, bastelte, hat gebastelt; often with 'an + Dativ' (an etwas basteln)","example":"Die Kinder basteln eine Karte für Oma.","exampleEn":"The children are making a card for grandma.","example2":"Er bastelt gern an seinem Fahrrad.","example2En":"He likes tinkering with his bicycle."},{"de":"beachten","en":"to pay attention to; to observe (a rule)","pos":"verb","plural":"","meanings":[{"en":"to follow/observe (a rule, sign, instruction)","de":"eine Regel befolgen"},{"en":"to notice/take note of someone or something","de":"auf etwas achten"}],"rule":"regular weak verb: beachtet, beachtete, hat beachtet; + Akkusativ","example":"Bitte beachten Sie die Hausordnung.","exampleEn":"Please observe the house rules.","example2":"Niemand hat ihn beachtet.","example2En":"Nobody paid attention to him."},{"de":"beantragen","en":"to apply for (officially)","pos":"verb","plural":"","meanings":[{"en":"to formally apply for / request something official","de":"offiziell um etwas bitten, z. B. bei einer Behörde"}],"rule":"regular weak verb: beantragt, beantragte, hat beantragt; + Akkusativ, oft bei Behörden","example":"Ich möchte einen neuen Reisepass beantragen.","exampleEn":"I would like to apply for a new passport.","example2":"Sie hat Kindergeld beantragt.","example2En":"She applied for child benefit."},{"de":"bearbeiten","en":"to work on; to process (a request)","pos":"verb","plural":"","meanings":[{"en":"to process/handle (an application, order)","de":"etwas (z. B. einen Antrag) erledigen"},{"en":"to edit/work on a text or material","de":"an etwas arbeiten, z. B. einen Text"}],"rule":"regular weak verb: bearbeitet, bearbeitete, hat bearbeitet; + Akkusativ","example":"Die Bank bearbeitet Ihren Antrag in drei Tagen.","exampleEn":"The bank processes your application within three days.","example2":"Kannst du den Text noch bearbeiten?","example2En":"Can you edit the text a bit more?"},{"de":"bedeuten","en":"to mean; to signify","pos":"verb","plural":"","meanings":[{"en":"to have a certain meaning","de":"eine bestimmte Bedeutung haben"},{"en":"to be important to someone","de":"für jemanden wichtig sein"}],"rule":"regular weak verb: bedeutet, bedeutete, hat bedeutet; + Akkusativ","example":"Was bedeutet dieses Wort?","exampleEn":"What does this word mean?","example2":"Die Familie bedeutet ihm sehr viel.","example2En":"Family means a lot to him."},{"de":"bedienen","en":"to serve; to operate (a machine)","pos":"verb","plural":"","meanings":[{"en":"to serve a customer","de":"einem Kunden helfen, z. B. im Geschäft"},{"en":"to operate a machine or device","de":"eine Maschine benutzen"}],"rule":"regular weak verb: bedient, bediente, hat bedient; + Akkusativ; reflexiv 'sich bedienen' = sich selbst nehmen","example":"Die Kellnerin bedient die Gäste.","exampleEn":"The waitress serves the guests.","example2":"Kannst du die Kaffeemaschine bedienen?","example2En":"Can you operate the coffee machine?"},{"de":"beenden","en":"to end; to finish","pos":"verb","plural":"","meanings":[{"en":"to bring something to an end / finish it","de":"etwas zu Ende bringen"}],"rule":"regular weak verb: beendet, beendete, hat beendet; + Akkusativ","example":"Sie hat ihr Studium beendet.","exampleEn":"She has finished her studies.","example2":"Wir beenden die Sitzung um 16 Uhr.","example2En":"We will end the meeting at 4 pm."},{"de":"befriedigend","en":"satisfactory","pos":"adjective","plural":"","meanings":[{"en":"satisfactory, acceptable (e.g. as a grade)","de":"ausreichend gut, zufriedenstellend"}],"rule":"regelmäßige Steigerung: befriedigend, befriedigender, am befriedigendsten; in Deutschland auch Schulnote (3)","example":"Seine Note in Mathe war nur befriedigend.","exampleEn":"His grade in math was only satisfactory.","example2":"Das Ergebnis des Tests ist befriedigend.","example2En":"The test result is satisfactory."},{"de":"begleichen","en":"to settle (a bill/debt)","pos":"verb","plural":"","meanings":[{"en":"to pay off a bill or debt","de":"eine Rechnung oder Schuld bezahlen"}],"rule":"unregelmäßig: begleicht, beglich, hat beglichen; + Akkusativ, formell (z. B. eine Rechnung begleichen)","example":"Bitte begleichen Sie die Rechnung bis Freitag.","exampleEn":"Please settle the bill by Friday.","example2":"Er hat seine Schulden beglichen.","example2En":"He paid off his debts."},{"de":"begründen","en":"to justify; to give reasons for","pos":"verb","plural":"","meanings":[{"en":"to give reasons/justification for something","de":"Gründe für etwas nennen"}],"rule":"regular weak verb: begründet, begründete, hat begründet; + Akkusativ","example":"Können Sie Ihre Entscheidung begründen?","exampleEn":"Can you justify your decision?","example2":"Sie hat ihre Absage kurz begründet.","example2En":"She briefly explained the reason for her refusal."},{"de":"die Begrüßung","en":"greeting; welcome","pos":"noun","plural":"die Begrüßungen","meanings":[{"en":"the act of greeting/welcoming someone","de":"das Willkommenheißen einer Person"}],"rule":"abgeleitet von 'begrüßen'; feminines Nomen auf -ung, Plural mit -en","example":"Die Begrüßung der Gäste war sehr herzlich.","exampleEn":"The welcome of the guests was very warm.","example2":"Zur Begrüßung gab es Kaffee und Kuchen.","example2En":"There was coffee and cake for the welcome."},{"de":"die Behandlung","en":"treatment (medical)","pos":"noun","plural":"die Behandlungen","meanings":[{"en":"medical treatment","de":"ärztliche Versorgung"},{"en":"way of dealing with/handling someone or something","de":"der Umgang mit jemandem/etwas"}],"rule":"abgeleitet von 'behandeln'; feminines Nomen auf -ung, Plural mit -en","example":"Die Behandlung beim Arzt hat lange gedauert.","exampleEn":"The treatment at the doctor's took a long time.","example2":"Er beschwerte sich über die schlechte Behandlung.","example2En":"He complained about the poor treatment."},{"de":"die Behörde","en":"authority; government office","pos":"noun","plural":"die Behörden","meanings":[{"en":"a government office/public authority","de":"staatliche Institution, z. B. Amt"}],"rule":"feminines Nomen, Plural mit -n; oft: 'auf die Behörde/zum Amt gehen'","example":"Für den Antrag müssen Sie zur Behörde gehen.","exampleEn":"For the application you have to go to the authority.","example2":"Die Behörde hat den Antrag genehmigt.","example2En":"The authority approved the application."},{"de":"der Beinbruch","en":"broken leg","pos":"noun","plural":"die Beinbrüche","meanings":[{"en":"a fracture of the leg","de":"ein gebrochenes Bein"}],"rule":"Kompositum: das Bein + der Bruch; maskulines Nomen, Plural mit Umlaut -e","example":"Nach dem Sturz hatte er einen Beinbruch.","exampleEn":"After the fall he had a broken leg.","example2":"Mit einem Beinbruch kann man nicht Ski fahren.","example2En":"You can't ski with a broken leg."},{"de":"die Bekleidung","en":"clothing; apparel","pos":"noun","plural":"","meanings":[{"en":"clothing, garments in general (often formal/commercial term)","de":"Kleidung allgemein"}],"rule":"feminines Nomen, meist ohne Plural (Kollektivbegriff); formeller als 'Kleidung', oft in Geschäften: Damenbekleidung, Herrenbekleidung","example":"Das Geschäft verkauft Bekleidung für Kinder.","exampleEn":"The shop sells clothing for children.","example2":"Warme Bekleidung ist im Winter wichtig.","example2En":"Warm clothing is important in winter."},{"de":"belegen","en":"to enroll in / to reserve; to prove","pos":"verb","plural":"","meanings":[{"en":"to sign up for (a course)","de":"einen Kurs/Platz reservieren, sich anmelden für"},{"en":"to prove, document","de":"mit Beweisen/Dokumenten nachweisen"}],"rule":"regelmäßig: belegt, belegte, hat belegt. + Akkusativ (einen Kurs belegen).","example":"Ich möchte einen Deutschkurs belegen.","exampleEn":"I would like to enroll in a German course.","example2":"Können Sie das mit Dokumenten belegen?","example2En":"Can you prove that with documents?"},{"de":"der Benutzername","en":"username","pos":"noun","plural":"die Benutzernamen","meanings":[{"en":"login name for a computer system","de":"Name zum Einloggen in ein System"}],"rule":"maskulin, aus 'Benutzer' + 'Name'; zusammen mit 'Passwort' oft genannt.","example":"Bitte geben Sie Ihren Benutzernamen ein.","exampleEn":"Please enter your username.","example2":"Ich habe meinen Benutzernamen vergessen.","example2En":"I forgot my username."},{"de":"beraten","en":"to advise","pos":"verb","plural":"","meanings":[{"en":"to give advice to someone","de":"jemandem einen Rat geben"}],"rule":"unregelmäßig: berät, beriet, hat beraten. + Akkusativ der Person (ich berate dich).","example":"Die Ärztin berät ihre Patienten gut.","exampleEn":"The doctor advises her patients well.","example2":"Können Sie mich beraten?","example2En":"Can you advise me?"},{"de":"die Beratung","en":"advice; consultation","pos":"noun","plural":"die Beratungen","meanings":[{"en":"advice given by an expert","de":"fachlicher Rat"},{"en":"a consultation session/office","de":"Gespräch oder Stelle, wo man beraten wird"}],"rule":"feminin, von 'beraten' abgeleitet (-ung).","example":"Die Beratung war sehr hilfreich.","exampleEn":"The consultation was very helpful.","example2":"Gehst du zur Beratung im Jobcenter?","example2En":"Are you going to the consultation at the job center?"},{"de":"das Beratungsgespräch","en":"consultation talk / advisory meeting","pos":"noun","plural":"die Beratungsgespräche","meanings":[{"en":"a conversation for advice or consultation","de":"Gespräch, in dem man beraten wird"}],"rule":"neutral, Kompositum aus 'Beratung' + 'Gespräch'.","example":"Wir hatten ein langes Beratungsgespräch mit der Bank.","exampleEn":"We had a long consultation with the bank.","example2":"Das Beratungsgespräch dauert etwa eine Stunde.","example2En":"The consultation meeting takes about an hour."},{"de":"berechnen","en":"to calculate; to charge","pos":"verb","plural":"","meanings":[{"en":"to compute a value","de":"etwas rechnerisch ermitteln"},{"en":"to charge a price for something","de":"einen Preis für etwas verlangen"}],"rule":"regelmäßig: berechnet, berechnete, hat berechnet. + Akkusativ.","example":"Der Computer berechnet das Ergebnis automatisch.","exampleEn":"The computer calculates the result automatically.","example2":"Der Mechaniker hat mir 50 Euro berechnet.","example2En":"The mechanic charged me 50 euros."},{"de":"der Bereich","en":"area, field, sector","pos":"noun","plural":"die Bereiche","meanings":[{"en":"a field or domain (subject/work)","de":"ein Fachgebiet oder Themenfeld"},{"en":"a physical area/zone","de":"ein räumlicher Abschnitt"}],"rule":"maskulin.","example":"Sie arbeitet im Bereich Marketing.","exampleEn":"She works in the marketing field.","example2":"Dieser Bereich ist für Besucher gesperrt.","example2En":"This area is closed to visitors."},{"de":"bereit","en":"ready","pos":"adjective","plural":"","meanings":[{"en":"prepared, ready to do something","de":"vorbereitet, fertig für etwas"}],"rule":"Adjektiv, meist prädikativ verwendet; oft mit 'zu' + Infinitiv oder 'für' + Akkusativ (bereit für etwas / bereit, etwas zu tun).","example":"Bist du bereit für die Prüfung?","exampleEn":"Are you ready for the exam?","example2":"Er ist bereit, sofort anzufangen.","example2En":"He is ready to start right away."},{"de":"bereitstellen","en":"to provide, to make available","pos":"verb","plural":"","meanings":[{"en":"to supply or make something available","de":"etwas zur Verfügung stellen"}],"rule":"trennbar: stellt ... bereit, stellte ... bereit, hat bereitgestellt.","example":"Die Firma stellt neue Laptops bereit.","exampleEn":"The company provides new laptops.","example2":"Wir stellen Ihnen alle Unterlagen bereit.","example2En":"We will provide you with all the documents."},{"de":"der Bericht","en":"report","pos":"noun","plural":"die Berichte","meanings":[{"en":"a written or spoken account of events","de":"eine schriftliche oder mündliche Darstellung"}],"rule":"maskulin, von 'berichten'.","example":"Ich habe den Bericht gelesen.","exampleEn":"I read the report.","example2":"Sie schreibt einen Bericht über den Unfall.","example2En":"She is writing a report about the accident."},{"de":"die Berufsausbildung","en":"vocational training","pos":"noun","plural":"die Berufsausbildungen","meanings":[{"en":"training for a profession, esp. apprenticeship","de":"Ausbildung für einen Beruf"}],"rule":"feminin, Kompositum aus 'Beruf' + 'Ausbildung'.","example":"Nach der Schule beginnt er seine Berufsausbildung.","exampleEn":"After school he starts his vocational training.","example2":"Die Berufsausbildung dauert drei Jahre.","example2En":"The vocational training lasts three years."},{"de":"die Berufsberatung","en":"career counseling","pos":"noun","plural":"die Berufsberatungen","meanings":[{"en":"advice about choosing a career/job","de":"Beratung bei der Berufswahl"}],"rule":"feminin, Kompositum aus 'Beruf' + 'Beratung'.","example":"Ich habe einen Termin bei der Berufsberatung.","exampleEn":"I have an appointment at career counseling.","example2":"Die Berufsberatung hilft Jugendlichen bei der Berufswahl.","example2En":"Career counseling helps young people choose a career."}]},{"id":"a2-04","title":"A2 · B (4)","level":"A2","words":[{"de":"das Berufsfeld","en":"career field, professional field","pos":"noun","plural":"die Berufsfelder","meanings":[{"en":"a general area/category of professions","de":"ein Bereich von ähnlichen Berufen"}],"rule":"neutral, Kompositum aus 'Beruf' + 'Feld'.","example":"Welches Berufsfeld interessiert dich?","exampleEn":"Which career field interests you?","example2":"Sie arbeitet im Berufsfeld Gesundheit.","example2En":"She works in the healthcare professional field."},{"de":"das Berufsinformationszentrum","en":"career information center","pos":"noun","plural":"die Berufsinformationszentren","meanings":[{"en":"a center providing information about careers/jobs","de":"Einrichtung mit Informationen zu Berufen"}],"rule":"neutral, oft abgekürzt 'BIZ'; Kompositum.","example":"Im Berufsinformationszentrum kann man sich über Berufe informieren.","exampleEn":"At the career information center you can learn about professions.","example2":"Ich gehe heute ins Berufsinformationszentrum.","example2En":"I'm going to the career information center today."},{"de":"das Berufskolleg","en":"vocational college","pos":"noun","plural":"die Berufskollegs","meanings":[{"en":"a school type offering vocational and general education","de":"Schulform mit beruflicher und allgemeiner Bildung"}],"rule":"neutral, Kompositum aus 'Beruf' + 'Kolleg'.","example":"Er macht sein Abitur am Berufskolleg.","exampleEn":"He is doing his Abitur at the vocational college.","example2":"Das Berufskolleg bietet verschiedene Fachrichtungen an.","example2En":"The vocational college offers various specializations."},{"de":"die Berufsschule","en":"vocational school","pos":"noun","plural":"die Berufsschulen","meanings":[{"en":"school attended alongside an apprenticeship","de":"Schule, die man während der Ausbildung besucht"}],"rule":"feminin, Kompositum aus 'Beruf' + 'Schule'.","example":"Zweimal pro Woche geht sie in die Berufsschule.","exampleEn":"Twice a week she goes to vocational school.","example2":"Die Berufsschule ergänzt die praktische Ausbildung im Betrieb.","example2En":"Vocational school complements the practical training at the company."},{"de":"berufstätig","en":"employed, working","pos":"adjective","plural":"","meanings":[{"en":"having a job, being employed","de":"einen Beruf ausüben, arbeiten"}],"rule":"keine Steigerung üblich; oft 'berufstätig sein'.","example":"Meine Mutter ist berufstätig.","exampleEn":"My mother is employed.","example2":"Viele berufstätige Eltern brauchen einen Kitaplatz.","example2En":"Many working parents need a daycare spot."},{"de":"der Berufswunsch","en":"desired profession, career aspiration","pos":"noun","plural":"die Berufswünsche","meanings":[{"en":"the job/career someone wants to have","de":"der Beruf, den jemand gern ausüben möchte"}],"rule":"maskulin, Kompositum aus 'Beruf' + 'Wunsch'.","example":"Was ist dein Berufswunsch?","exampleEn":"What is your desired profession?","example2":"Ihr Berufswunsch ist Ärztin.","example2En":"Her career aspiration is to become a doctor."},{"de":"die Bescheinigung","en":"certificate; confirmation","pos":"noun","plural":"die Bescheinigungen","meanings":[{"en":"an official document confirming something","de":"ein offizielles Dokument, das etwas bestätigt"}],"rule":"Often used with 'eine Bescheinigung ausstellen/vorlegen'.","example":"Ich brauche eine Bescheinigung vom Arzt.","exampleEn":"I need a certificate from the doctor.","example2":"Können Sie mir eine Bescheinigung für die Schule ausstellen?","example2En":"Can you issue me a certificate for school?"},{"de":"die Beschwerde","en":"complaint","pos":"noun","plural":"die Beschwerden","meanings":[{"en":"a formal complaint","de":"eine offizielle Klage oder Kritik"}],"rule":"Common phrase: 'eine Beschwerde einreichen/schreiben'.","example":"Ich möchte eine Beschwerde schreiben.","exampleEn":"I would like to write a complaint.","example2":"Er hat sich über den Service beschwert und eine Beschwerde eingereicht.","example2En":"He complained about the service and filed a complaint."},{"de":"besichtigen","en":"to view; to visit (a sight)","pos":"verb","plural":"","meanings":[{"en":"to visit and look at something, e.g. a building or sight","de":"sich etwas ansehen, z. B. ein Gebäude"}],"rule":"Regular verb: besichtigt, besichtigte, hat besichtigt. Takes direct object (Akkusativ).","example":"Wir besichtigen morgen das Schloss.","exampleEn":"We are visiting the castle tomorrow.","example2":"Möchten Sie die Wohnung besichtigen?","example2En":"Would you like to view the apartment?"},{"de":"besonders","en":"especially; particularly","pos":"adverb","plural":"","meanings":[{"en":"especially, particularly","de":"vor allem, speziell"}],"rule":"Can also modify adjectives: 'besonders gut'. No comparison forms (used as intensifier).","example":"Das Essen war besonders lecker.","exampleEn":"The food was especially delicious.","example2":"Ich mag besonders den Sommer.","example2En":"I especially like summer."},{"de":"besprechen","en":"to discuss","pos":"verb","plural":"","meanings":[{"en":"to talk about and discuss something","de":"über etwas sprechen und sich austauschen"}],"rule":"Irregular: bespricht, besprach, hat besprochen. Not separable (be- prefix).","example":"Wir müssen das Projekt besprechen.","exampleEn":"We need to discuss the project.","example2":"Können wir die Details später besprechen?","example2En":"Can we discuss the details later?"},{"de":"die Besprechung","en":"meeting; discussion","pos":"noun","plural":"die Besprechungen","meanings":[{"en":"a meeting where something is discussed","de":"ein Treffen, bei dem etwas besprochen wird"}],"rule":"Synonym for 'Meeting' in office contexts.","example":"Die Besprechung beginnt um zehn Uhr.","exampleEn":"The meeting starts at ten o'clock.","example2":"Ich habe heute drei Besprechungen.","example2En":"I have three meetings today."},{"de":"das Besteck","en":"cutlery","pos":"noun","plural":"","meanings":[{"en":"knife, fork and spoon used for eating","de":"Messer, Gabel und Löffel zum Essen"}],"rule":"Uncountable noun, always singular.","example":"Kannst du das Besteck auf den Tisch legen?","exampleEn":"Can you put the cutlery on the table?","example2":"Das Besteck ist im obersten Schubfach.","example2En":"The cutlery is in the top drawer."},{"de":"bestellen","en":"to order","pos":"verb","plural":"","meanings":[{"en":"to order food, drinks or goods","de":"etwas anfordern, z. B. im Restaurant oder online"}],"rule":"Regular: bestellt, bestellte, hat bestellt. + Akkusativ.","example":"Ich möchte einen Kaffee bestellen.","exampleEn":"I would like to order a coffee.","example2":"Wir haben das Buch im Internet bestellt.","example2En":"We ordered the book online."},{"de":"die Bestellnummer","en":"order number","pos":"noun","plural":"die Bestellnummern","meanings":[{"en":"a reference number for an order","de":"eine Nummer zur Identifizierung einer Bestellung"}],"rule":"Compound noun from the verb stem 'bestell-' (bestellen) + Nummer, not from the noun 'Bestellung' directly.","example":"Bitte geben Sie Ihre Bestellnummer an.","exampleEn":"Please provide your order number.","example2":"Die Bestellnummer finden Sie in der E-Mail.","example2En":"You can find the order number in the email."},{"de":"die Bestellung","en":"order","pos":"noun","plural":"die Bestellungen","meanings":[{"en":"a request for goods or food","de":"das Bestellen von Waren oder Essen"}],"rule":"Related to verb 'bestellen'.","example":"Meine Bestellung ist noch nicht angekommen.","exampleEn":"My order has not arrived yet.","example2":"Er hat eine große Bestellung aufgegeben.","example2En":"He placed a large order."},{"de":"bestimmt","en":"certain; surely","pos":"adjective","plural":"","meanings":[{"en":"specific, particular","de":"speziell, festgelegt"},{"en":"surely, certainly (as adverb)","de":"sicher, gewiss"}],"rule":"As adjective means 'certain/specific'; as adverb means 'surely/probably'.","example":"Er sucht ein bestimmtes Buch.","exampleEn":"He is looking for a certain book.","example2":"Sie kommt bestimmt zu spät.","example2En":"She will surely be late."},{"de":"betätigen","en":"to operate; to activate","pos":"verb","plural":"","meanings":[{"en":"to operate or press a button/switch","de":"einen Knopf oder Schalter bedienen"}],"rule":"Regular: betätigt, betätigte, hat betätigt. + Akkusativ. Often with 'den Knopf/Schalter betätigen'.","example":"Bitte betätigen Sie den Notknopf.","exampleEn":"Please press the emergency button.","example2":"Er hat den Schalter betätigt.","example2En":"He activated the switch."},{"de":"betreffen","en":"to concern; to affect","pos":"verb","plural":"","meanings":[{"en":"to concern or be relevant to someone/something","de":"jemanden oder etwas angehen"}],"rule":"Irregular: betrifft, betraf, hat betroffen. + Akkusativ. Often used as 'was ... betrifft' (as for).","example":"Diese Regel betrifft alle Mitarbeiter.","exampleEn":"This rule concerns all employees.","example2":"Was mich betrifft, bin ich einverstanden.","example2En":"As for me, I agree."},{"de":"bewahren","en":"to keep; to preserve","pos":"verb","plural":"","meanings":[{"en":"to keep or protect something safely","de":"etwas sicher aufbewahren oder schützen"}],"rule":"Regular: bewahrt, bewahrte, hat bewahrt. Do not confuse with 'bewähren' (to prove oneself).","example":"Sie bewahrt alte Briefe in einer Kiste.","exampleEn":"She keeps old letters in a box.","example2":"Bitte bewahren Sie Ruhe.","example2En":"Please stay calm (keep calm)."},{"de":"bewegen","en":"to move","pos":"verb","plural":"","meanings":[{"en":"to move physically","de":"die Position verändern"},{"en":"to move emotionally","de":"jemanden emotional berühren"}],"rule":"Regular in both senses shown here: bewegt, bewegte, hat bewegt. Reflexive: sich bewegen = to move oneself/exercise. (The irregular forms bewog/bewogen exist only for 'jemanden zu etwas bewegen' = to induce someone to do something.)","example":"Ich kann meinen Arm nicht bewegen.","exampleEn":"I cannot move my arm.","example2":"Der Film hat mich sehr bewegt.","example2En":"The film moved me a lot."},{"de":"der Bewerber / die Bewerberin","en":"applicant","pos":"noun","plural":"die Bewerber / die Bewerberinnen","meanings":[{"en":"a person applying for a job or place","de":"eine Person, die sich bewirbt"}],"rule":"From verb 'sich bewerben' (to apply). Masculine/feminine forms with -in suffix.","example":"Der Bewerber hat viel Erfahrung.","exampleEn":"The applicant has a lot of experience.","example2":"Wir haben viele Bewerberinnen eingeladen.","example2En":"We invited many (female) applicants."},{"de":"der Bezirk","en":"district","pos":"noun","plural":"die Bezirke","meanings":[{"en":"an administrative area of a city or region","de":"ein Verwaltungsgebiet einer Stadt oder Region"}],"rule":"Used especially for city districts (e.g. Berlin's Bezirke).","example":"Sie wohnt im Bezirk Mitte.","exampleEn":"She lives in the Mitte district.","example2":"Der Bezirk hat ein neues Rathaus.","example2En":"The district has a new town hall."},{"de":"der BIC","en":"BIC (Bank Identifier Code)","pos":"noun","plural":"die BICs","meanings":[{"en":"an international bank code used for transfers","de":"ein internationaler Bankcode für Überweisungen"}],"rule":"Used together with IBAN for international bank transfers; plural 'BICs' exists but is rarely used since each bank usually has only one.","example":"Wie lautet der BIC Ihrer Bank?","exampleEn":"What is the BIC of your bank?","example2":"Für die Überweisung brauchen Sie IBAN und BIC.","example2En":"For the transfer you need the IBAN and BIC."},{"de":"bieten","en":"to offer","pos":"verb","plural":"","meanings":[{"en":"to offer (something to someone)","de":"jemandem etwas anbieten"},{"en":"to provide/present (a view, chance, etc.)","de":"etwas bereitstellen, zeigen"}],"rule":"unregelmäßig: er bietet, bot, hat geboten","example":"Das Hotel bietet einen schönen Blick auf den See.","exampleEn":"The hotel offers a beautiful view of the lake.","example2":"Die Firma bietet ihren Mitarbeitern viele Vorteile.","example2En":"The company offers its employees many benefits."},{"de":"der Bildschirm","en":"screen, monitor","pos":"noun","plural":"die Bildschirme","meanings":[{"en":"screen / monitor (of a computer, TV, phone)","de":"das Display eines Geräts"}],"rule":"Kompositum: das Bild + der Schirm; Genus vom Grundwort 'der Schirm'","example":"Mein Bildschirm ist kaputt.","exampleEn":"My screen is broken.","example2":"Sie schaut den ganzen Tag auf den Bildschirm.","example2En":"She looks at the screen all day."},{"de":"der Bildungsweg","en":"educational path, course of education","pos":"noun","plural":"die Bildungswege","meanings":[{"en":"path of education/training someone follows","de":"der Weg der schulischen/beruflichen Ausbildung"}],"rule":"oft in 'zweiter Bildungsweg' = alternative route to qualifications for adults","example":"Er hat seinen Bildungsweg mit einer Ausbildung begonnen.","exampleEn":"He started his educational path with an apprenticeship.","example2":"Sie hat das Abitur auf dem zweiten Bildungsweg gemacht.","example2En":"She got her high school diploma through adult education."},{"de":"die Biologie","en":"biology","pos":"noun","plural":"","meanings":[{"en":"the science of living things; school subject","de":"die Wissenschaft von den Lebewesen"}],"rule":"unzählbar, kein Plural","example":"Biologie ist mein Lieblingsfach.","exampleEn":"Biology is my favorite subject.","example2":"Sie studiert Biologie an der Universität.","example2En":"She is studying biology at university."},{"de":"der Biomüll","en":"organic waste, biowaste","pos":"noun","plural":"","meanings":[{"en":"compostable organic waste (food scraps, garden waste)","de":"organischer Abfall, z. B. Essensreste"}],"rule":"unzählbar; gehört in die Biotonne","example":"Obstschalen gehören in den Biomüll.","exampleEn":"Fruit peels belong in the organic waste.","example2":"Wir trennen unseren Biomüll vom Restmüll.","example2En":"We separate our organic waste from general waste."},{"de":"die Biotonne","en":"organic waste bin","pos":"noun","plural":"die Biotonnen","meanings":[{"en":"bin for collecting organic/compostable waste","de":"der Mülleimer für Biomüll"}],"rule":"Kompositum: Bio + Tonne (die Tonne = bin)","example":"Die Biotonne wird einmal pro Woche geleert.","exampleEn":"The organic waste bin is emptied once a week.","example2":"Wirf die Essensreste bitte in die Biotonne.","example2En":"Please throw the food scraps into the organic waste bin."},{"de":"bitten","en":"to ask, to request","pos":"verb","plural":"","meanings":[{"en":"to ask someone for something politely","de":"jemanden höflich um etwas bitten"}],"rule":"unregelmäßig: er bittet, bat, hat gebeten; + um + Akkusativ; nicht verwechseln mit 'bieten'","example":"Ich bitte dich um Hilfe.","exampleEn":"I'm asking you for help.","example2":"Er bat den Kellner um die Rechnung.","example2En":"He asked the waiter for the bill."},{"de":"der Blick","en":"look, glance, view","pos":"noun","plural":"die Blicke","meanings":[{"en":"a look or glance","de":"das kurze Sehen zu jemandem/etwas"},{"en":"a view (from a place)","de":"die Aussicht von einem Ort"}],"rule":"von 'blicken' (to glance); 'auf den ersten Blick' = at first sight","example":"Er warf einen kurzen Blick auf die Uhr.","exampleEn":"He took a quick glance at the clock.","example2":"Von hier hat man einen tollen Blick auf die Berge.","example2En":"From here you have a great view of the mountains."},{"de":"blond","en":"blond","pos":"adjective","plural":"","meanings":[{"en":"having fair/blond hair","de":"mit hellen, gelblichen Haaren"}],"rule":"regelmäßige Steigerung: blond, blonder, am blondesten","example":"Meine Schwester hat blonde Haare.","exampleEn":"My sister has blond hair.","example2":"Das kleine Mädchen ist blond.","example2En":"The little girl is blond."},{"de":"der Boden","en":"floor, ground, soil","pos":"noun","plural":"die Böden","meanings":[{"en":"floor (inside a room)","de":"der Fußboden"},{"en":"ground, soil (outside)","de":"die Erde, das Erdreich"}],"rule":"Plural mit Umlaut: die Böden","example":"Der Boden im Wohnzimmer ist aus Holz.","exampleEn":"The floor in the living room is made of wood.","example2":"Der Boden hier ist sehr fruchtbar.","example2En":"The soil here is very fertile."},{"de":"der Brand","en":"fire, blaze","pos":"noun","plural":"die Brände","meanings":[{"en":"a fire (uncontrolled burning)","de":"das Feuer, das etwas zerstört"}],"rule":"Plural mit Umlaut: die Brände; vgl. 'brennen'","example":"Die Feuerwehr hat den Brand schnell gelöscht.","exampleEn":"The fire brigade quickly put out the fire.","example2":"Bei dem Brand wurde niemand verletzt.","example2En":"No one was injured in the fire."},{"de":"die Brandbekämpfung","en":"firefighting","pos":"noun","plural":"","meanings":[{"en":"the act of fighting/extinguishing fires","de":"das Löschen eines Brandes"}],"rule":"unzählbar; Kompositum aus Brand + Bekämpfung","example":"Die Feuerwehrleute sind für die Brandbekämpfung zuständig.","exampleEn":"The firefighters are responsible for firefighting.","example2":"Zur Brandbekämpfung braucht man spezielle Ausrüstung.","example2En":"Special equipment is needed for firefighting."},{"de":"der Brandfall","en":"case of fire, fire emergency","pos":"noun","plural":"die Brandfälle","meanings":[{"en":"an event/situation in which a fire occurs","de":"der Fall, dass ein Feuer ausbricht"}],"rule":"oft in der Wendung 'im Brandfall' = in case of fire","example":"Im Brandfall bitte den Aufzug nicht benutzen.","exampleEn":"In case of fire, please do not use the elevator.","example2":"Der Brandfall wurde sofort gemeldet.","example2En":"The fire emergency was reported immediately."},{"de":"der Brandmelder","en":"fire detector, fire alarm","pos":"noun","plural":"die Brandmelder","meanings":[{"en":"a device that detects fire/smoke and gives an alarm","de":"ein Gerät, das Feuer oder Rauch meldet"}],"rule":"Plural = Singular (der Brandmelder, die Brandmelder); nicht zu verwechseln mit 'der Rauchmelder' (der kleine Rauchmelder in der Wohnung)","example":"In jeder Wohnung muss ein Brandmelder installiert sein.","exampleEn":"A fire detector must be installed in every apartment.","example2":"Der Brandmelder hat laut gepiept.","example2En":"The fire detector beeped loudly."},{"de":"der Brandschutz","en":"fire protection, fire safety","pos":"noun","plural":"","meanings":[{"en":"measures to prevent and limit fire damage","de":"Maßnahmen gegen Brände"}],"rule":"unzählbar","example":"Der Brandschutz im Gebäude wurde überprüft.","exampleEn":"The fire safety in the building was checked.","example2":"Feuerlöscher sind wichtig für den Brandschutz.","example2En":"Fire extinguishers are important for fire protection."},{"de":"braten","en":"to fry, to roast","pos":"verb","plural":"","meanings":[{"en":"to cook meat/food in fat or an oven","de":"etwas in Fett oder im Ofen garen"}],"rule":"unregelmäßig: er brät, briet, hat gebraten","example":"Meine Mutter brät heute Fisch.","exampleEn":"My mother is frying fish today.","example2":"Er hat das Hähnchen im Ofen gebraten.","example2En":"He roasted the chicken in the oven."},{"de":"brennen","en":"to burn","pos":"verb","plural":"","meanings":[{"en":"to be on fire / to burn","de":"in Flammen stehen"},{"en":"to hurt, to sting (pain sensation)","de":"schmerzen, wie Feuer fühlen"}],"rule":"unregelmäßig: es brennt, brannte, hat gebrannt","example":"Das Haus hat lichterloh gebrannt.","exampleEn":"The house was burning fiercely.","example2":"Meine Augen brennen vom Rauch.","example2En":"My eyes are burning from the smoke."},{"de":"das Brett","en":"board, plank","pos":"noun","plural":"die Bretter","meanings":[{"en":"a flat piece of wood","de":"ein flaches Stück Holz"}],"rule":"unregelmäßiger Plural auf -er: die Bretter (kein Umlaut, da Stammvokal 'e')","example":"Er sägt ein Brett für das Regal.","exampleEn":"He is sawing a board for the shelf.","example2":"Auf dem Brett liegen frische Kräuter.","example2En":"Fresh herbs are lying on the board."},{"de":"der Briefkasten","en":"mailbox","pos":"noun","plural":"die Briefkästen","meanings":[{"en":"mailbox (for letters)","de":"Kasten für Briefe"}],"rule":"Kompositum aus 'Brief' + 'Kasten'; Plural mit Umlaut: die Briefkästen.","example":"Ich werfe den Brief in den Briefkasten.","exampleEn":"I put the letter in the mailbox.","example2":"Der Briefkasten ist schon voll.","example2En":"The mailbox is already full."},{"de":"die Broschüre","en":"brochure","pos":"noun","plural":"die Broschüren","meanings":[{"en":"brochure, pamphlet","de":"kleines Informationsheft"}],"rule":"Feminines Substantiv, Plural auf -n.","example":"Im Reisebüro liegt eine Broschüre über Italien.","exampleEn":"There is a brochure about Italy at the travel agency.","example2":"Kannst du mir eine Broschüre mitbringen?","example2En":"Can you bring me a brochure?"},{"de":"buchen","en":"to book","pos":"verb","plural":"","meanings":[{"en":"to book, reserve","de":"reservieren"}],"rule":"Regelmäßiges Verb: bucht, buchte, hat gebucht.","example":"Wir buchen den Flug online.","exampleEn":"We book the flight online.","example2":"Hast du das Hotel schon gebucht?","example2En":"Have you already booked the hotel?"},{"de":"die Buchhaltung","en":"accounting, bookkeeping","pos":"noun","plural":"","meanings":[{"en":"accounting department / bookkeeping","de":"Abteilung für Rechnungen und Finanzen"}],"rule":"Feminines Substantiv, meist unzählbar, kein Plural.","example":"Sie arbeitet in der Buchhaltung.","exampleEn":"She works in accounting.","example2":"Die Buchhaltung prüft die Rechnungen.","example2En":"The accounting department checks the invoices."},{"de":"bummeln","en":"to stroll","pos":"verb","plural":"","meanings":[{"en":"to stroll, wander leisurely","de":"gemütlich spazieren gehen"}],"rule":"Regelmäßiges Verb: bummelt, bummelte, ist gebummelt.","example":"Am Samstag bummeln wir durch die Stadt.","exampleEn":"On Saturday we stroll through the city.","example2":"Sie bummeln gern durch die Geschäfte.","example2En":"They like to stroll through the shops."},{"de":"das Bundesland","en":"federal state","pos":"noun","plural":"die Bundesländer","meanings":[{"en":"federal state (of Germany/Austria)","de":"Teilstaat eines Bundesstaates"}],"rule":"Neutrum; Plural mit Umlaut: die Bundesländer.","example":"Bayern ist ein Bundesland in Deutschland.","exampleEn":"Bavaria is a federal state in Germany.","example2":"Deutschland hat sechzehn Bundesländer.","example2En":"Germany has sixteen federal states."},{"de":"bunt","en":"colorful","pos":"adjective","plural":"","meanings":[{"en":"colorful, multicolored","de":"vielfarbig"}],"rule":"Regelmäßige Steigerung: bunt, bunter, am buntesten.","example":"Das Kind malt ein buntes Bild.","exampleEn":"The child paints a colorful picture.","example2":"Sie trägt ein buntes Kleid.","example2En":"She is wearing a colorful dress."},{"de":"die Büroorganisation","en":"office organization","pos":"noun","plural":"","meanings":[{"en":"organization of office work","de":"Organisation der Arbeit im Büro"}],"rule":"Kompositum aus 'Büro' + 'Organisation'; meist unzählbar.","example":"Sie ist für die Büroorganisation verantwortlich.","exampleEn":"She is responsible for office organization.","example2":"Gute Büroorganisation spart Zeit.","example2En":"Good office organization saves time."}]},{"id":"a2-05","title":"A2 · C–E (5)","level":"A2","words":[{"de":"das Camping","en":"camping","pos":"noun","plural":"","meanings":[{"en":"camping","de":"Urlaub im Zelt oder Wohnwagen"}],"rule":"Neutrum, Anglizismus, kein Plural.","example":"Wir machen im Sommer Camping am See.","exampleEn":"We go camping by the lake in summer.","example2":"Camping ist ein günstiger Urlaub.","example2En":"Camping is a cheap holiday."},{"de":"der Champignon","en":"mushroom (button)","pos":"noun","plural":"die Champignons","meanings":[{"en":"button mushroom","de":"weißer Speisepilz"}],"rule":"Aus dem Französischen; Aussprache: 'Schamp-injong'; Plural: die Champignons.","example":"Ich kaufe frische Champignons für die Suppe.","exampleEn":"I buy fresh mushrooms for the soup.","example2":"Der Salat hat Champignons.","example2En":"The salad has mushrooms in it."},{"de":"das Chaos","en":"chaos","pos":"noun","plural":"","meanings":[{"en":"chaos, complete disorder","de":"völlige Unordnung"}],"rule":"Neutrum, kein Plural; Aussprache 'Kaos'.","example":"Nach der Party war ein totales Chaos im Zimmer.","exampleEn":"After the party there was total chaos in the room.","example2":"Im Büro herrscht heute Chaos.","example2En":"There is chaos in the office today."},{"de":"chatten","en":"to chat (online)","pos":"verb","plural":"","meanings":[{"en":"to chat online","de":"online schreiben und kommunizieren"}],"rule":"Regelmäßiges Verb: chattet, chattete, hat gechattet.","example":"Ich chatte jeden Abend mit meinen Freunden.","exampleEn":"I chat with my friends every evening.","example2":"Sie hat gestern lange mit ihm gechattet.","example2En":"She chatted with him for a long time yesterday."},{"de":"die Chemie","en":"chemistry","pos":"noun","plural":"","meanings":[{"en":"chemistry (subject/science)","de":"Naturwissenschaft von Stoffen"}],"rule":"Feminines Substantiv, kein Plural; Aussprache: 'Ch' wie der Ich-Laut (wie in 'ich'), nicht wie 'K'.","example":"Chemie ist mein Lieblingsfach.","exampleEn":"Chemistry is my favorite subject.","example2":"Er studiert Chemie an der Uni.","example2En":"He studies chemistry at university."},{"de":"der Chor","en":"choir","pos":"noun","plural":"die Chöre","meanings":[{"en":"choir","de":"Gruppe von Sängern"}],"rule":"Maskulin; Plural mit Umlaut: die Chöre; Anfangsbuchstaben wie 'K' ausgesprochen.","example":"Sie singt im Chor der Schule.","exampleEn":"She sings in the school choir.","example2":"Der Chor probt jeden Mittwoch.","example2En":"The choir rehearses every Wednesday."},{"de":"der Cousin / die Cousine","en":"cousin","pos":"noun","plural":"die Cousins / die Cousinen","meanings":[{"en":"cousin (male/female)","de":"Kind von Onkel oder Tante"}],"rule":"Maskulin: der Cousin (Aussprache 'Kusäng'); feminin: die Cousine.","example":"Mein Cousin wohnt in Berlin.","exampleEn":"My cousin lives in Berlin.","example2":"Meine Cousine besucht uns am Wochenende.","example2En":"My cousin is visiting us this weekend."},{"de":"die Currywurst","en":"currywurst","pos":"noun","plural":"die Currywürste","meanings":[{"en":"currywurst (German sausage dish with curry sauce)","de":"Bratwurst mit Ketchup und Currypulver"}],"rule":"Feminines Kompositum aus 'Curry' + 'Wurst'; Plural mit Umlaut: die Currywürste.","example":"Zum Mittagessen esse ich eine Currywurst mit Pommes.","exampleEn":"For lunch I eat currywurst with fries.","example2":"Die Currywurst ist typisch für Berlin.","example2En":"Currywurst is typical of Berlin."},{"de":"dabei","en":"present / along with it","pos":"adverb","plural":"","meanings":[{"en":"present, there, included","de":"anwesend, mit dabei"},{"en":"in the process of / while doing that","de":"gleichzeitig, während dessen"}],"rule":"Adverb; oft in 'dabei sein' (anwesend sein) oder als Verbindungswort für zwei gleichzeitige Handlungen.","example":"Warst du bei der Party dabei?","exampleEn":"Were you there at the party?","example2":"Ich koche und höre dabei Musik.","example2En":"I cook and listen to music while doing that."},{"de":"dagegen","en":"against it","pos":"adverb","plural":"","meanings":[{"en":"against it, opposed to it","de":"gegen diese Sache"},{"en":"in contrast, on the other hand","de":"im Gegensatz dazu"}],"rule":"Pronominaladverb 'da(r) + gegen'; ersetzt 'gegen + es/das'.","example":"Ich bin dagegen, dass wir jetzt gehen.","exampleEn":"I am against us leaving now.","example2":"Er ist groß, sein Bruder dagegen ist klein.","example2En":"He is tall, his brother, on the other hand, is small."},{"de":"daheim","en":"at home","pos":"adverb","plural":"","meanings":[{"en":"at home","de":"zu Hause"}],"rule":"Süddeutsch/österreichisch für 'zu Hause'; bedeutet Ort, nicht Richtung.","example":"Am Wochenende bleibe ich daheim.","exampleEn":"On the weekend I stay at home.","example2":"Ist deine Mutter daheim?","example2En":"Is your mother at home?"},{"de":"damals","en":"back then, at that time","pos":"adverb","plural":"","meanings":[{"en":"at that time (in the past)","de":"zu dieser Zeit (in der Vergangenheit)"}],"rule":"Bezieht sich immer auf die Vergangenheit, nicht auf die Zukunft; oft mit Präteritum.","example":"Damals wohnten wir in Berlin.","exampleEn":"Back then we lived in Berlin.","example2":"Damals hatte ich kein Handy.","example2En":"At that time I didn't have a mobile phone."},{"de":"die Dame","en":"lady, woman","pos":"noun","plural":"die Damen","meanings":[{"en":"lady (polite term for a woman)","de":"höfliches Wort für Frau"}],"rule":"Höflicheres/formelleres Wort als 'Frau', besonders beim Sprechen über eine Frau; feminines Nomen, regelmäßiger Plural auf -n.","example":"Die Dame an der Kasse war sehr freundlich.","exampleEn":"The lady at the checkout was very friendly.","example2":"Meine Damen und Herren, bitte nehmen Sie Platz.","example2En":"Ladies and gentlemen, please take a seat."},{"de":"damit","en":"with it; so that","pos":"conjunction","plural":"","meanings":[{"en":"with it/that (pronominal adverb)","de":"mit diesem/dieser Sache"},{"en":"so that, in order that (purpose clause)","de":"damit-Satz für ein Ziel"}],"rule":"Als Pronominaladverb: 'mit + es/das' → 'damit'. Als Konjunktion leitet es Finalsätze ein (Verb am Ende); bei verschiedenen Subjekten statt 'um...zu'.","example":"Hast du einen Stift? Ich möchte damit schreiben.","exampleEn":"Do you have a pen? I want to write with it.","example2":"Ich spreche langsam, damit du mich verstehst.","example2En":"I speak slowly so that you understand me."},{"de":"danken","en":"to thank","pos":"verb","plural":"","meanings":[{"en":"to thank someone","de":"jemandem Dank sagen"}],"rule":"+ Dativ; regelmäßig: dankt, dankte, hat gedankt.","example":"Ich danke dir für das Geschenk.","exampleEn":"I thank you for the gift.","example2":"Er dankte dem Lehrer für die Hilfe.","example2En":"He thanked the teacher for the help."},{"de":"darin","en":"in it, inside","pos":"adverb","plural":"","meanings":[{"en":"in it/inside (pronominal adverb)","de":"in diesem/dieser Sache"}],"rule":"Pronominaladverb: 'in + es/das' → 'darin'; bezieht sich auf bereits Genanntes. Feste Wendung: 'der Vorteil liegt darin, dass...' (Verb 'liegt' bleibt in Position 2).","example":"Das ist meine Tasche. Darin sind meine Bücher.","exampleEn":"This is my bag. My books are inside it.","example2":"Der Vorteil liegt darin, dass es billiger ist.","example2En":"The advantage is that it's cheaper."},{"de":"darum","en":"that's why; about it","pos":"adverb","plural":"","meanings":[{"en":"that's why, therefore","de":"deshalb, aus diesem Grund"},{"en":"about it/that (pronominal adverb)","de":"um diese Sache"}],"rule":"Als Kausaladverb = 'deshalb' (Satzposition 1 oder nach Verb). Als Pronominaladverb: 'um + es/das'.","example":"Es regnet, darum bleibe ich zu Hause.","exampleEn":"It's raining, that's why I'm staying home.","example2":"Ich habe ihn gebeten, aber er kümmert sich nicht darum.","example2En":"I asked him, but he doesn't take care of it."},{"de":"dass","en":"that (conjunction)","pos":"conjunction","plural":"","meanings":[{"en":"that (introducing a subordinate clause)","de":"leitet einen Nebensatz ein"}],"rule":"Leitet Nebensätze ein, Verb steht am Ende; nicht verwechseln mit 'das' (Artikel/Pronomen).","example":"Ich glaube, dass er recht hat.","exampleEn":"I think that he is right.","example2":"Sie hofft, dass es morgen nicht regnet.","example2En":"She hopes that it won't rain tomorrow."},{"de":"die Datei","en":"file (computer)","pos":"noun","plural":"die Dateien","meanings":[{"en":"computer file","de":"digitale Daten, die gespeichert sind"}],"rule":"Feminines Nomen; nicht verwechseln mit 'Diät' (diet) oder 'Datum' (date).","example":"Ich habe die Datei per E-Mail geschickt.","exampleEn":"I sent the file by email.","example2":"Kannst du die Datei öffnen?","example2En":"Can you open the file?"},{"de":"die Dauer","en":"duration, length (of time)","pos":"noun","plural":"","meanings":[{"en":"duration, length of time","de":"Zeitspanne"}],"rule":"Feminines Nomen, meist ohne Plural verwendet; oft in 'die Dauer von...'.","example":"Die Dauer des Kurses beträgt sechs Wochen.","exampleEn":"The duration of the course is six weeks.","example2":"Auf Dauer wird das zu teuer.","example2En":"In the long run, that will be too expensive."},{"de":"der Daumen","en":"thumb","pos":"noun","plural":"die Daumen","meanings":[{"en":"thumb (body part)","de":"der erste, dickste Finger der Hand"}],"rule":"Maskulines Nomen, Plural = Singular (der Daumen, die Daumen); Redewendung: 'Ich drücke dir die Daumen' = ich wünsche dir Glück.","example":"Ich habe mir in den Daumen geschnitten.","exampleEn":"I cut my thumb.","example2":"Ich drücke dir die Daumen für die Prüfung.","example2En":"I'm keeping my fingers crossed for your exam."},{"de":"die Decke","en":"blanket; ceiling","pos":"noun","plural":"die Decken","meanings":[{"en":"blanket","de":"warmes Tuch zum Zudecken"},{"en":"ceiling","de":"obere Fläche eines Raums"}],"rule":"Feminines Nomen; zwei Bedeutungen je nach Kontext (Bett/Kälte vs. Zimmer/oben).","example":"Im Winter schlafe ich unter einer warmen Decke.","exampleEn":"In winter I sleep under a warm blanket.","example2":"Die Lampe hängt an der Decke.","example2En":"The lamp hangs from the ceiling."},{"de":"defekt","en":"defective, broken","pos":"adjective","plural":"","meanings":[{"en":"defective, broken (especially machines/devices)","de":"kaputt, funktioniert nicht richtig"}],"rule":"Wird meist für technische Geräte benutzt; ähnlich wie 'kaputt', aber etwas formeller.","example":"Der Fernseher ist defekt.","exampleEn":"The TV is broken.","example2":"Die Waschmaschine war defekt und musste repariert werden.","example2En":"The washing machine was defective and had to be repaired."},{"de":"der/die Angehörige","en":"relative, family member","pos":"noun","plural":"die Angehörigen","meanings":[{"en":"a relative or family member","de":"ein Familienmitglied"}],"rule":"Adjektivdeklination: der Angehörige, ein Angehöriger / die Angehörige, eine Angehörige","example":"Nur Angehörige dürfen den Patienten besuchen.","exampleEn":"Only relatives may visit the patient.","example2":"Sie informierten die Angehörigen sofort.","example2En":"They informed the family members immediately."},{"de":"deshalb","en":"therefore, that's why","pos":"adverb","plural":"","meanings":[{"en":"therefore, for that reason","de":"aus diesem Grund"}],"rule":"Kausaladverb, oft in Position 1; danach Verb-Subjekt-Umstellung (Verb Zweitstelle).","example":"Ich war krank, deshalb bin ich nicht gekommen.","exampleEn":"I was sick, that's why I didn't come.","example2":"Es ist spät, deshalb müssen wir gehen.","example2En":"It's late, therefore we have to go."},{"de":"deutlich","en":"clear, distinct","pos":"adjective","plural":"","meanings":[{"en":"clear, easy to understand/perceive","de":"klar, gut verständlich oder erkennbar"}],"rule":"Regelmäßige Steigerung: deutlich, deutlicher, am deutlichsten; oft mit 'sprechen' oder 'zeigen'.","example":"Bitte sprechen Sie deutlich.","exampleEn":"Please speak clearly.","example2":"Der Unterschied ist deutlich zu sehen.","example2En":"The difference is clearly visible."},{"de":"dich","en":"you (accusative)","pos":"pronoun","plural":"","meanings":[{"en":"you (informal, accusative case)","de":"Akkusativ von 'du'"}],"rule":"Akkusativform von 'du'; nicht verwechseln mit Dativ 'dir'.","example":"Ich sehe dich morgen.","exampleEn":"I'll see you tomorrow.","example2":"Ich liebe dich.","example2En":"I love you."},{"de":"dick","en":"thick; fat","pos":"adjective","plural":"","meanings":[{"en":"thick (objects)","de":"nicht dünn"},{"en":"fat, overweight (people)","de":"übergewichtig"}],"rule":"Regelmäßige Steigerung: dick, dicker, am dicksten; bei Personen vorsichtig verwenden, da wertend.","example":"Das Buch ist sehr dick.","exampleEn":"The book is very thick.","example2":"Der Pullover ist warm und dick.","example2En":"The sweater is warm and thick."},{"de":"der Dieb / die Diebin","en":"thief","pos":"noun","plural":"die Diebe / die Diebinnen","meanings":[{"en":"thief, person who steals","de":"jemand, der stiehlt"}],"rule":"Maskulin 'der Dieb', feminin 'die Diebin'; verwandtes Verb: stehlen.","example":"Der Dieb ist mit der Tasche weggelaufen.","exampleEn":"The thief ran away with the bag.","example2":"Die Polizei hat die Diebin gefasst.","example2En":"The police caught the (female) thief."},{"de":"dieselbe","en":"the same (one)","pos":"pronoun","plural":"","meanings":[{"en":"the same (person/thing)","de":"die gleiche Person/Sache"}],"rule":"Demonstrativpronomen: dieselbe (fem. sg.), derselbe (masc.), dasselbe (neutr.); unterscheide von 'die gleiche' (identisch, aber nicht zwingend ein und dasselbe Exemplar).","example":"Ich habe dieselbe Tasche wie meine Schwester.","exampleEn":"I have the same bag as my sister.","example2":"Wir wohnen in derselben Straße.","example2En":"We live on the same street."},{"de":"das Ding","en":"thing","pos":"noun","plural":"die Dinge","meanings":[{"en":"object/thing","de":"Gegenstand, Sache"}],"rule":"Neutrum; Plural 'die Dinge' (umgangssprachlich auch 'die Dinger').","example":"Was ist das für ein Ding?","exampleEn":"What is that thing?","example2":"Leg die Dinge auf den Tisch.","example2En":"Put the things on the table."},{"de":"das Diplom","en":"diploma","pos":"noun","plural":"die Diplome","meanings":[{"en":"diploma/degree certificate","de":"Abschlusszeugnis, Urkunde"}],"rule":"Neutrum; oft mit 'machen': ein Diplom machen.","example":"Sie hat ihr Diplom bekommen.","exampleEn":"She received her diploma.","example2":"Er zeigt stolz sein Diplom.","example2En":"He proudly shows his diploma."},{"de":"diskutieren","en":"to discuss","pos":"verb","plural":"","meanings":[{"en":"to discuss, debate","de":"über etwas sprechen, streiten"}],"rule":"Regelmäßig: diskutiert, diskutierte, hat diskutiert; oft mit 'über + Akkusativ'.","example":"Wir diskutieren über das Wetter.","exampleEn":"We are discussing the weather.","example2":"Die Kollegen diskutieren lange über den Plan.","example2En":"The colleagues discuss the plan for a long time."},{"de":"divers","en":"diverse; various","pos":"adjective","plural":"","meanings":[{"en":"various, several","de":"verschiedene, mehrere"},{"en":"diverse (gender)","de":"geschlechtlich divers"}],"rule":"Wird wie ein normales Adjektiv dekliniert; 'divers' als Geschlechtsangabe (m/w/d) ist eine besondere Bedeutung.","example":"Es gibt diverse Möglichkeiten.","exampleEn":"There are various options.","example2":"Auf dem Formular steht: männlich, weiblich, divers.","example2En":"The form says: male, female, diverse."},{"de":"das Dokument","en":"document","pos":"noun","plural":"die Dokumente","meanings":[{"en":"document/paper","de":"wichtiges Schriftstück"}],"rule":"Neutrum; oft im Plural 'die Dokumente' (z. B. Ausweisdokumente).","example":"Bitte bringen Sie alle Dokumente mit.","exampleEn":"Please bring all documents.","example2":"Ich speichere das Dokument auf dem Computer.","example2En":"I save the document on the computer."},{"de":"drehen","en":"to turn; to shoot (film)","pos":"verb","plural":"","meanings":[{"en":"to turn/rotate","de":"etwas im Kreis bewegen"},{"en":"to shoot a film","de":"einen Film produzieren"}],"rule":"Regelmäßig: dreht, drehte, hat gedreht; reflexiv 'sich drehen' = sich im Kreis bewegen.","example":"Dreh den Schlüssel nach rechts.","exampleEn":"Turn the key to the right.","example2":"Sie drehen einen neuen Film in Berlin.","example2En":"They are shooting a new film in Berlin."},{"de":"drüben","en":"over there","pos":"adverb","plural":"","meanings":[{"en":"over there, on the other side","de":"auf der anderen Seite"}],"rule":"Lokaladverb, oft mit 'da drüben' oder 'dort drüben'.","example":"Der Supermarkt ist drüben.","exampleEn":"The supermarket is over there.","example2":"Meine Freunde wohnen da drüben.","example2En":"My friends live over there."},{"de":"drucken","en":"to print","pos":"verb","plural":"","meanings":[{"en":"to print (paper/text)","de":"Text auf Papier ausgeben"}],"rule":"Regelmäßig: druckt, druckte, hat gedruckt; nicht verwechseln mit 'drücken' (to press).","example":"Kannst du das Dokument drucken?","exampleEn":"Can you print the document?","example2":"Der Drucker druckt sehr langsam.","example2En":"The printer prints very slowly."},{"de":"drücken","en":"to press; to pinch","pos":"verb","plural":"","meanings":[{"en":"to press/push","de":"Druck auf etwas ausüben"},{"en":"to pinch (shoes)","de":"zu eng sein, schmerzen"}],"rule":"Regelmäßig: drückt, drückte, hat gedrückt; nicht verwechseln mit 'drucken' (to print).","example":"Bitte drücken Sie auf den Knopf.","exampleEn":"Please press the button.","example2":"Die neuen Schuhe drücken.","example2En":"The new shoes pinch."},{"de":"der Duft","en":"scent, fragrance","pos":"noun","plural":"die Düfte","meanings":[{"en":"pleasant smell, fragrance","de":"angenehmer Geruch"}],"rule":"Maskulinum; Plural mit Umlaut: die Düfte.","example":"Der Duft von frischem Brot ist toll.","exampleEn":"The smell of fresh bread is great.","example2":"Ich mag den Duft dieses Parfüms.","example2En":"I like the scent of this perfume."},{"de":"dünn","en":"thin","pos":"adjective","plural":"","meanings":[{"en":"thin (not thick)","de":"nicht dick"}],"rule":"Regelmäßige Steigerung: dünn, dünner, am dünnsten; Gegenteil: dick.","example":"Das Buch ist sehr dünn.","exampleEn":"The book is very thin.","example2":"Sie schneidet das Brot in dünne Scheiben.","example2En":"She cuts the bread into thin slices."},{"de":"das Duschgel","en":"shower gel","pos":"noun","plural":"die Duschgele","meanings":[{"en":"shower gel","de":"Flüssigseife zum Duschen"}],"rule":"Neutrum; regelmäßiger Plural 'die Duschgele' (wie 'das Gel → die Gele'), umgangssprachlich auch 'die Duschgels'; oft im Singular gebraucht, da eine Produktart.","example":"Ich kaufe ein neues Duschgel.","exampleEn":"I'm buying a new shower gel.","example2":"Das Duschgel riecht nach Zitrone.","example2En":"The shower gel smells of lemon."},{"de":"echt","en":"real, genuine; really","pos":"adjective","plural":"","meanings":[{"en":"real, genuine (not fake)","de":"nicht falsch, original"},{"en":"really (intensifier)","de":"wirklich, sehr"}],"rule":"Als Adjektiv dekliniert (echtes Gold); als Umgangssprache auch als Adverb 'echt gut' = wirklich gut.","example":"Ist das echtes Gold?","exampleEn":"Is that real gold?","example2":"Das Konzert war echt super.","example2En":"The concert was really great."},{"de":"die Ecke","en":"corner","pos":"noun","plural":"die Ecken","meanings":[{"en":"corner (of street/room)","de":"Winkel, Kante"}],"rule":"Femininum; oft in 'um die Ecke' = in der Nähe.","example":"Der Laden ist gleich um die Ecke.","exampleEn":"The shop is just around the corner.","example2":"Das Sofa steht in der Ecke.","example2En":"The sofa is in the corner."},{"de":"egal","en":"doesn't matter, indifferent","pos":"adjective","plural":"","meanings":[{"en":"not mattering, indifferent","de":"unwichtig, gleichgültig"}],"rule":"Meist prädikativ gebraucht: 'Das ist mir egal.' + Dativ (wem?).","example":"Mir ist egal, was wir essen.","exampleEn":"I don't care what we eat.","example2":"Egal welche Farbe, Hauptsache es passt.","example2En":"Doesn't matter which color, as long as it fits."},{"de":"das Ehepaar","en":"married couple","pos":"noun","plural":"die Ehepaare","meanings":[{"en":"married couple","de":"zwei verheiratete Personen"}],"rule":"Neutrum, obwohl es Personen bezeichnet; Plural: die Ehepaare.","example":"Das Ehepaar wohnt seit zehn Jahren hier.","exampleEn":"The married couple has lived here for ten years.","example2":"Wir haben ein nettes Ehepaar kennengelernt.","example2En":"We met a nice married couple."},{"de":"der Ehepartner / die Ehepartnerin","en":"spouse","pos":"noun","plural":"die Ehepartner / die Ehepartnerinnen","meanings":[{"en":"spouse (husband/wife)","de":"Ehemann oder Ehefrau"}],"rule":"Maskulin/feminin je nach Geschlecht; Plural: die Ehepartner(innen).","example":"Sein Ehepartner arbeitet als Arzt.","exampleEn":"His spouse works as a doctor.","example2":"Beide Ehepartner müssen unterschreiben.","example2En":"Both spouses have to sign."},{"de":"die Eheschließung","en":"marriage; wedding ceremony","pos":"noun","plural":"die Eheschließungen","meanings":[{"en":"the legal act of getting married","de":"das Heiraten, die Hochzeit"}],"rule":"Formal/official word used e.g. on standesamt documents; compound of Ehe (marriage) + Schließung (closing/conclusion).","example":"Die Eheschließung findet am Standesamt statt.","exampleEn":"The marriage ceremony takes place at the registry office.","example2":"Zur Eheschließung braucht man Ausweis und Geburtsurkunde.","example2En":"For the marriage you need an ID card and a birth certificate."},{"de":"eigen","en":"own","pos":"adjective","plural":"","meanings":[{"en":"belonging to oneself","de":"jemandem selbst gehörend"}],"rule":"Usually follows a possessive determiner or an article signaling ownership: mein eigenes Auto, ein eigenes Zimmer, das eigene Haus (no comparison forms in this basic sense).","example":"Ich habe ein eigenes Zimmer.","exampleEn":"I have my own room.","example2":"Sie möchte eine eigene Wohnung haben.","example2En":"She wants to have her own apartment."},{"de":"die Einbauküche","en":"fitted kitchen","pos":"noun","plural":"die Einbauküchen","meanings":[{"en":"a kitchen with built-in units and appliances","de":"eine Küche mit fest eingebauten Möbeln und Geräten"}],"rule":"Compound: Einbau (built-in, fitted) + Küche (kitchen); often abbreviated EBK in classified ads.","example":"Die Wohnung hat eine moderne Einbauküche.","exampleEn":"The apartment has a modern fitted kitchen.","example2":"Eine Einbauküche ist teurer als einzelne Möbel.","example2En":"A fitted kitchen is more expensive than individual furniture."}]},{"id":"a2-06","title":"A2 · E (6)","level":"A2","words":[{"de":"eindecken","en":"to stock up (on)","pos":"verb","plural":"","meanings":[{"en":"to provide oneself/others with a supply of something","de":"sich mit etwas versorgen"}],"rule":"Trennbar: deckt ein, deckte ein, hat eingedeckt. Usually reflexive: sich mit etwas eindecken.","example":"Vor dem Sturm haben wir uns mit Lebensmitteln eingedeckt.","exampleEn":"Before the storm we stocked up on food.","example2":"Sie deckt sich im Herbst mit Brennholz ein.","example2En":"She stocks up on firewood in autumn."},{"de":"die Einfahrt","en":"driveway; entrance (for vehicles)","pos":"noun","plural":"die Einfahrten","meanings":[{"en":"a driveway or vehicle entrance to a property","de":"der Weg/Platz, wo Autos hineinfahren"},{"en":"the act of a vehicle entering","de":"das Hineinfahren"}],"rule":"Often seen on signs: \"Einfahrt freihalten\" (keep driveway clear).","example":"Bitte die Einfahrt nicht zuparken.","exampleEn":"Please don't block the driveway with parking.","example2":"Die Einfahrt in den Bahnhof verzögert sich.","example2En":"The train's entry into the station is delayed."},{"de":"einfarbig","en":"single-colored; plain","pos":"adjective","plural":"","meanings":[{"en":"having only one color, not patterned","de":"nur eine Farbe habend"}],"rule":"Opposite of gemustert (patterned) or mehrfarbig (multicolored); no irregular comparison.","example":"Ich trage gern einfarbige Hemden.","exampleEn":"I like to wear plain (single-colored) shirts.","example2":"Die Wand ist einfarbig blau gestrichen.","example2En":"The wall is painted a single color, blue."},{"de":"die Eingabe","en":"input; entry (of data)","pos":"noun","plural":"die Eingaben","meanings":[{"en":"data or information entered into a system","de":"Daten, die man in ein Gerät eingibt"}],"rule":"Related to the verb eingeben; common in computer/technology contexts.","example":"Bitte überprüfen Sie Ihre Eingabe.","exampleEn":"Please check your input.","example2":"Nach der Eingabe der PIN öffnet sich die Tür.","example2En":"After entering the PIN, the door opens."},{"de":"eingeben","en":"to enter, input (data)","pos":"verb","plural":"","meanings":[{"en":"to type or input information into a device","de":"Daten in ein Gerät eintippen"}],"rule":"Trennbar und unregelmäßig: gibt ein, gab ein, hat eingegeben.","example":"Geben Sie bitte Ihr Passwort ein.","exampleEn":"Please enter your password.","example2":"Er hat die Adresse ins Navi eingegeben.","example2En":"He entered the address into the GPS."},{"de":"der Einlass","en":"admission; entry (to a venue)","pos":"noun","plural":"die Einlässe","meanings":[{"en":"permission or the time to enter an event/place","de":"das Hineingehen-Dürfen bei einer Veranstaltung"}],"rule":"Common on tickets: \"Einlass ab 19 Uhr\" (admission from 7 pm).","example":"Der Einlass beginnt eine Stunde vor dem Konzert.","exampleEn":"Admission starts one hour before the concert.","example2":"Ohne Ticket gibt es keinen Einlass.","example2En":"Without a ticket there is no admission."},{"de":"einrichten","en":"to furnish, set up","pos":"verb","plural":"","meanings":[{"en":"to furnish a room or apartment","de":"ein Zimmer mit Möbeln ausstatten"},{"en":"(reflexive) to settle in / adapt to a situation","de":"sich an eine Situation gewöhnen"}],"rule":"Trennbar: richtet ein, richtete ein, hat eingerichtet. Reflexive use: sich einrichten (+ in/auf + Akk.).","example":"Wir haben unsere Wohnung neu eingerichtet.","exampleEn":"We have refurnished our apartment.","example2":"Wir müssen uns auf weniger Geld einrichten.","example2En":"We have to adjust to having less money."},{"de":"einsteigen","en":"to get on, board (a vehicle)","pos":"verb","plural":"","meanings":[{"en":"to get into a vehicle such as a bus, train or car","de":"in ein Fahrzeug hineingehen"}],"rule":"Trennbar, unregelmäßig, mit sein: steigt ein, stieg ein, ist eingestiegen.","example":"Bitte schnell einsteigen, der Zug fährt gleich ab.","exampleEn":"Please board quickly, the train is about to leave.","example2":"Er ist in den falschen Bus eingestiegen.","example2En":"He got on the wrong bus."},{"de":"der Eintritt","en":"entrance; admission fee","pos":"noun","plural":"die Eintritte","meanings":[{"en":"the act of entering a place","de":"das Hineingehen"},{"en":"the fee paid to enter","de":"der Preis, den man für den Eingang bezahlt"}],"rule":"Common phrase: \"Eintritt frei\" (free admission).","example":"Der Eintritt ins Museum kostet fünf Euro.","exampleEn":"Admission to the museum costs five euros.","example2":"Kinder haben freien Eintritt.","example2En":"Children get free admission."},{"de":"die Einweihungsparty","en":"housewarming party","pos":"noun","plural":"die Einweihungspartys","meanings":[{"en":"a party celebrating moving into a new home","de":"eine Feier zum Einzug in eine neue Wohnung"}],"rule":"Compound: Einweihung (inauguration) + Party; informal, everyday word.","example":"Wir feiern am Samstag unsere Einweihungsparty.","exampleEn":"We're celebrating our housewarming party on Saturday.","example2":"Zur Einweihungsparty bringen die Gäste oft Pflanzen mit.","example2En":"Guests often bring plants to a housewarming party."},{"de":"die Einweisung","en":"briefing; instruction","pos":"noun","plural":"die Einweisungen","meanings":[{"en":"an introduction or instruction on how to use/do something","de":"eine kurze Erklärung, wie man etwas macht"}],"rule":"Related to einweisen (to instruct/brief); often used for safety or equipment training.","example":"Vor der Arbeit gibt es eine kurze Einweisung.","exampleEn":"Before work there is a short briefing.","example2":"Die neue Mitarbeiterin bekommt eine Einweisung in die Maschine.","example2En":"The new employee gets instruction on the machine."},{"de":"das Einwohnermeldeamt","en":"residents' registration office","pos":"noun","plural":"die Einwohnermeldeämter","meanings":[{"en":"the government office where you register your address in Germany","de":"das Amt, bei dem man seinen Wohnsitz anmeldet"}],"rule":"Compound: Einwohner (resident) + Melde- (registration) + Amt (office); important A2 survival-German word.","example":"Nach dem Umzug muss man zum Einwohnermeldeamt gehen.","exampleEn":"After moving, you have to go to the residents' registration office.","example2":"Das Einwohnermeldeamt ist von 8 bis 12 Uhr geöffnet.","example2En":"The registration office is open from 8 to 12."},{"de":"die Einwurfzeit","en":"collection time (for mail)","pos":"noun","plural":"die Einwurfzeiten","meanings":[{"en":"the time by which mail must be posted for the next pickup","de":"die Zeit, bis zu der man einen Brief einwerfen muss"}],"rule":"Compound: Einwurf (posting/insertion) + Zeit; found printed on letterboxes/mailboxes.","example":"Die Einwurfzeit für den nächsten Tag ist 17 Uhr.","exampleEn":"The collection time for next-day delivery is 5 pm.","example2":"Schau auf dem Briefkasten nach der Einwurfzeit.","example2En":"Check the mailbox for the collection time."},{"de":"einzahlen","en":"to pay in, deposit (money)","pos":"verb","plural":"","meanings":[{"en":"to put money into a bank account","de":"Geld auf ein Konto bringen"}],"rule":"Trennbar: zahlt ein, zahlte ein, hat eingezahlt.","example":"Ich möchte Geld auf mein Konto einzahlen.","exampleEn":"I would like to deposit money into my account.","example2":"Er hat den Betrag am Automaten eingezahlt.","example2En":"He paid in the amount at the machine."},{"de":"einziehen","en":"to move in","pos":"verb","plural":"","meanings":[{"en":"to move into a new home","de":"in eine neue Wohnung ziehen"},{"en":"to be drawn in or absorbed (e.g. liquid)","de":"von etwas aufgenommen werden"}],"rule":"Trennbar, unregelmäßig, mit sein: zieht ein, zog ein, ist eingezogen.","example":"Nächste Woche ziehen wir in die neue Wohnung ein.","exampleEn":"Next week we're moving into the new apartment.","example2":"Die Creme zieht schnell in die Haut ein.","example2En":"The cream absorbs quickly into the skin."},{"de":"der Einzug","en":"moving in; entrance","pos":"noun","plural":"die Einzüge","meanings":[{"en":"moving into a home","de":"das Einziehen in eine Wohnung"},{"en":"entrance/parade (of people)","de":"das feierliche Eintreten, der Einmarsch (z. B. ins Stadion)"}],"rule":"Noun from 'einziehen' (trennbar). Often used with 'der Einzug in die Wohnung'.","example":"Der Einzug in die neue Wohnung war anstrengend.","exampleEn":"Moving into the new apartment was exhausting.","example2":"Beim Einzug der Mannschaft jubelten die Fans.","example2En":"When the team entered, the fans cheered."},{"de":"der Eiswürfel","en":"ice cube","pos":"noun","plural":"die Eiswürfel","meanings":[{"en":"ice cube","de":"gefrorenes Wasser in Würfelform"}],"rule":"Compound noun: Eis + Würfel. Takes 'der' like 'der Würfel'.","example":"Kannst du mir bitte ein paar Eiswürfel geben?","exampleEn":"Can you give me a few ice cubes, please?","example2":"Ich trinke meine Cola immer mit Eiswürfeln.","example2En":"I always drink my cola with ice cubes."},{"de":"die Elektrik","en":"electrical system/wiring","pos":"noun","plural":"","meanings":[{"en":"electrical system of a building/device","de":"die elektrischen Anlagen oder Leitungen"}],"rule":"Uncountable noun, no plural. Often used for house wiring or car electrics.","example":"Die Elektrik in der alten Wohnung ist kaputt.","exampleEn":"The wiring in the old apartment is broken.","example2":"Ein Elektriker hat die Elektrik im Haus geprüft.","example2En":"An electrician checked the house's electrical system."},{"de":"die Elektronik","en":"electronics","pos":"noun","plural":"","meanings":[{"en":"field of electronics / electronic devices","de":"elektronische Geräte oder das Fachgebiet"}],"rule":"Uncountable noun, no plural.","example":"Er interessiert sich sehr für Elektronik.","exampleEn":"He is very interested in electronics.","example2":"Die Elektronik des Fernsehers ist defekt.","example2En":"The TV's electronics are defective."},{"de":"der Elternabend","en":"parents' evening","pos":"noun","plural":"die Elternabende","meanings":[{"en":"school meeting for parents (evening)","de":"Treffen der Eltern in der Schule am Abend"}],"rule":"Compound: Eltern + Abend. General info meeting, not individual talks (compare Elternsprechtag).","example":"Am Elternabend spricht die Lehrerin über den Unterricht.","exampleEn":"At the parents' evening, the teacher talks about the lessons.","example2":"Wir haben morgen Elternabend in der Schule.","example2En":"We have a parents' evening at school tomorrow."},{"de":"der Elternsprechtag","en":"parent-teacher conference day","pos":"noun","plural":"die Elternsprechtage","meanings":[{"en":"day for individual parent-teacher talks","de":"Tag mit Einzelgesprächen zwischen Eltern und Lehrern"}],"rule":"Compound: Eltern + Sprech + Tag. Individual meetings, unlike the general Elternabend.","example":"Am Elternsprechtag spreche ich mit dem Lehrer meines Sohnes.","exampleEn":"On the parent-teacher conference day, I talk to my son's teacher.","example2":"Der Elternsprechtag findet einmal im Halbjahr statt.","example2En":"The parent-teacher conference day takes place once a semester."},{"de":"empfehlen","en":"to recommend","pos":"verb","plural":"","meanings":[{"en":"to recommend something to someone","de":"jemandem etwas raten, vorschlagen"}],"rule":"Irregular: empfiehlt, empfahl, hat empfohlen. + Dativ (person) + Akkusativ (thing).","example":"Kannst du mir ein gutes Restaurant empfehlen?","exampleEn":"Can you recommend a good restaurant to me?","example2":"Der Arzt empfiehlt mir mehr Sport.","example2En":"The doctor recommends more exercise to me."},{"de":"die Empfehlung","en":"recommendation","pos":"noun","plural":"die Empfehlungen","meanings":[{"en":"advice or suggestion","de":"ein Rat oder Vorschlag"}],"rule":"Noun from 'empfehlen'. Often with 'auf Empfehlung von...' (on the recommendation of...).","example":"Ich habe das Hotel auf Empfehlung meiner Freundin gebucht.","exampleEn":"I booked the hotel on my friend's recommendation.","example2":"Haben Sie eine Empfehlung für einen guten Arzt?","example2En":"Do you have a recommendation for a good doctor?"},{"de":"empfindlich","en":"sensitive","pos":"adjective","plural":"","meanings":[{"en":"easily hurt or irritated (person, skin)","de":"leicht reizbar oder verletzlich"}],"rule":"Regular comparison: empfindlich, empfindlicher, am empfindlichsten. Often used with 'gegen' (empfindlich gegen Kälte).","example":"Meine Haut ist sehr empfindlich gegen Sonne.","exampleEn":"My skin is very sensitive to sun.","example2":"Er ist sehr empfindlich, wenn man ihn kritisiert.","example2En":"He is very sensitive when someone criticizes him."},{"de":"das Ende","en":"end","pos":"noun","plural":"die Enden","meanings":[{"en":"the end of something (time, space)","de":"der letzte Teil oder Punkt von etwas"}],"rule":"Neuter noun. Common phrase: 'am Ende' (in the end / at the end).","example":"Der Film hat ein trauriges Ende.","exampleEn":"The movie has a sad ending.","example2":"Am Ende der Straße ist ein Supermarkt.","example2En":"At the end of the street there is a supermarket."},{"de":"die Energie","en":"energy","pos":"noun","plural":"die Energien","meanings":[{"en":"physical power/strength","de":"Kraft, Antrieb"},{"en":"power for machines/electricity","de":"Strom, Kraftquelle für Maschinen"}],"rule":"Feminine noun. Plural rarely used in everyday speech, usually singular.","example":"Nach dem Urlaub habe ich wieder viel Energie.","exampleEn":"After the vacation I have a lot of energy again.","example2":"Wir sparen Energie und schalten das Licht aus.","example2En":"We save energy and turn off the light."},{"de":"engagieren","en":"to commit oneself; to hire","pos":"verb","plural":"","meanings":[{"en":"to be actively involved (reflexive)","de":"sich aktiv für etwas einsetzen"},{"en":"to hire/employ someone","de":"jemanden einstellen"}],"rule":"Regular, weak verb: engagiert, engagierte, hat engagiert. Reflexive form 'sich engagieren' + für.","example":"Sie engagiert sich für den Tierschutz.","exampleEn":"She is actively involved in animal protection.","example2":"Die Firma hat einen neuen Trainer engagiert.","example2En":"The company hired a new coach."},{"de":"der Englischlehrer / die Englischlehrerin","en":"English teacher","pos":"noun","plural":"die Englischlehrer / die Englischlehrerinnen","meanings":[{"en":"teacher of English","de":"Lehrer/in für das Fach Englisch"}],"rule":"Compound: Englisch + Lehrer/in. Feminine form adds -in.","example":"Unser Englischlehrer kommt aus Kanada.","exampleEn":"Our English teacher is from Canada.","example2":"Die Englischlehrerin gibt uns viele Hausaufgaben.","example2En":"The English teacher gives us a lot of homework."},{"de":"der Enkel / die Enkelin","en":"grandson / granddaughter","pos":"noun","plural":"die Enkel / die Enkelinnen","meanings":[{"en":"grandchild (male/female)","de":"Kind des eigenen Kindes"}],"rule":"Feminine form adds -in. Also see 'das Enkelkind' for the neutral/general term.","example":"Mein Enkel besucht mich jeden Sonntag.","exampleEn":"My grandson visits me every Sunday.","example2":"Die Enkelin hilft der Oma im Garten.","example2En":"The granddaughter helps grandma in the garden."},{"de":"das Enkelkind","en":"grandchild","pos":"noun","plural":"die Enkelkinder","meanings":[{"en":"grandchild (general term)","de":"Kind des eigenen Kindes, unabhängig vom Geschlecht"}],"rule":"Neuter noun; gender-neutral term for grandson/granddaughter.","example":"Die Großeltern haben vier Enkelkinder.","exampleEn":"The grandparents have four grandchildren.","example2":"Am Wochenende spielt sie mit ihrem Enkelkind.","example2En":"On the weekend she plays with her grandchild."},{"de":"enthalten","en":"to contain","pos":"verb","plural":"","meanings":[{"en":"to contain/include something","de":"etwas in sich haben, einschließen"}],"rule":"Irregular: enthält, enthielt, hat enthalten. + Akkusativ. Also reflexive 'sich enthalten' (+ Gen., to abstain) but that sense is not A2.","example":"Der Kuchen enthält viel Zucker.","exampleEn":"The cake contains a lot of sugar.","example2":"Im Preis ist das Frühstück enthalten.","example2En":"Breakfast is included in the price."},{"de":"entlang","en":"along","pos":"preposition","plural":"","meanings":[{"en":"along (a path, river, road)","de":"parallel zu etwas, in Längsrichtung"}],"rule":"Can follow the noun with Akkusativ (den Fluss entlang) or precede it with Dativ/Genitiv (entlang dem Fluss); A2 learners mainly use the postposed form with Akkusativ.","example":"Wir gehen den Fluss entlang.","exampleEn":"We walk along the river.","example2":"Die Straße entlang stehen viele Bäume.","example2En":"There are many trees along the street."},{"de":"entscheiden","en":"to decide","pos":"verb","plural":"","meanings":[{"en":"to decide (about something)","de":"eine Entscheidung treffen"}],"rule":"Irregular: entscheidet, entschied, hat entschieden. Often reflexive 'sich entscheiden für/gegen'.","example":"Ich kann mich nicht entscheiden, welches Kleid ich kaufe.","exampleEn":"I can't decide which dress to buy.","example2":"Wir haben uns für die kleinere Wohnung entschieden.","example2En":"We decided on the smaller apartment."},{"de":"entschuldigen","en":"to excuse; to apologize","pos":"verb","plural":"","meanings":[{"en":"to apologize (oneself)","de":"sich für etwas entschuldigen"},{"en":"to excuse someone/something","de":"jemandem etwas nicht übelnehmen, einen Fehler tolerieren"}],"rule":"reflexiv: sich entschuldigen (bei + Dativ, für + Akkusativ); regelmäßig: entschuldigt, entschuldigte, hat entschuldigt","example":"Entschuldigen Sie bitte, wie spät ist es?","exampleEn":"Excuse me, please, what time is it?","example2":"Er hat sich für die Verspätung entschuldigt.","example2En":"He apologized for being late."},{"de":"entsorgen","en":"to dispose of","pos":"verb","plural":"","meanings":[{"en":"to dispose of waste properly","de":"Müll fachgerecht wegbringen"}],"rule":"regelmäßig: entsorgt, entsorgte, hat entsorgt; oft mit Müll/Abfall","example":"Wir entsorgen den Elektromüll im Recyclinghof.","exampleEn":"We dispose of the electronic waste at the recycling center.","example2":"Bitte entsorgen Sie die Batterien richtig.","example2En":"Please dispose of the batteries correctly."},{"de":"entspannen","en":"to relax","pos":"verb","plural":"","meanings":[{"en":"to relax (oneself)","de":"sich erholen, ruhig werden"}],"rule":"reflexiv: sich entspannen; auch nicht-reflexiv/transitiv: etwas entspannt jemanden/etwas; regelmäßig: entspannt, entspannte, hat entspannt","example":"Am Wochenende möchte ich mich richtig entspannen.","exampleEn":"On the weekend I want to really relax.","example2":"Ein warmes Bad entspannt den Körper.","example2En":"A warm bath relaxes the body."},{"de":"die Entspannung","en":"relaxation","pos":"noun","plural":"","meanings":[{"en":"relaxation, rest","de":"Erholung, Ruhe"}],"rule":"meist unzählbar, kein Plural; von entspannen","example":"Nach der Arbeit brauche ich Entspannung.","exampleEn":"After work I need relaxation.","example2":"Yoga hilft ihr bei der Entspannung.","example2En":"Yoga helps her with relaxation."},{"de":"der Entwurf","en":"draft; design","pos":"noun","plural":"die Entwürfe","meanings":[{"en":"a draft (text/document)","de":"erste Version eines Textes"},{"en":"a design/sketch","de":"Skizze, Plan"}],"rule":"Plural mit Umlaut: die Entwürfe; von entwerfen","example":"Sie schreibt einen Entwurf für den Brief.","exampleEn":"She is writing a draft of the letter.","example2":"Der Architekt zeigt seinen neuen Entwurf.","example2En":"The architect shows his new design."},{"de":"die Erdkunde","en":"geography","pos":"noun","plural":"","meanings":[{"en":"geography (school subject)","de":"Schulfach über die Erde"}],"rule":"unzählbar, kein Plural; Schulfach, auch 'Geografie' genannt","example":"In Erdkunde lernen wir über andere Länder.","exampleEn":"In geography we learn about other countries.","example2":"Erdkunde ist mein Lieblingsfach.","example2En":"Geography is my favorite subject."},{"de":"erfahren","en":"to learn/find out; experienced","pos":"verb","plural":"","meanings":[{"en":"to find out / learn (news)","de":"etwas Neues hören, herausfinden"},{"en":"(as adjective) experienced","de":"mit viel Erfahrung"}],"rule":"unregelmäßig: erfährt, erfuhr, hat erfahren; als Adjektiv (Partizip II): erfahren = mit viel Erfahrung, Steigerung: erfahrener, am erfahrensten","example":"Ich habe erst gestern von der Party erfahren.","exampleEn":"I only found out about the party yesterday.","example2":"Der erfahrene Lehrer hilft den neuen Kollegen.","example2En":"The experienced teacher helps the new colleagues."},{"de":"erfolgen","en":"to take place, to happen","pos":"verb","plural":"","meanings":[{"en":"to happen, take place (formal)","de":"geschehen, stattfinden"}],"rule":"regelmäßig: erfolgt, erfolgte, ist erfolgt; formelle Sprache, oft in Ämtern/Briefen","example":"Die Zahlung erfolgt per Überweisung.","exampleEn":"The payment is made by bank transfer.","example2":"Die Antwort erfolgt innerhalb von zwei Tagen.","example2En":"The reply will be given within two days."},{"de":"erforderlich","en":"required, necessary","pos":"adjective","plural":"","meanings":[{"en":"necessary, required","de":"notwendig"}],"rule":"meist nicht gesteigert (absolutes Adjektiv: etwas ist entweder erforderlich oder nicht); oft in Formularen/Amtssprache","example":"Für den Job sind gute Deutschkenntnisse erforderlich.","exampleEn":"Good German skills are required for the job.","example2":"Ein Reisepass ist für diese Reise erforderlich.","example2En":"A passport is required for this trip."},{"de":"erhalten","en":"to receive; to preserve","pos":"verb","plural":"","meanings":[{"en":"to receive (something)","de":"bekommen"},{"en":"to preserve, keep","de":"bewahren, nicht verändern"}],"rule":"unregelmäßig: erhält, erhielt, hat erhalten","example":"Ich habe gestern deinen Brief erhalten.","exampleEn":"I received your letter yesterday.","example2":"Wir wollen die alte Tradition erhalten.","example2En":"We want to preserve the old tradition."},{"de":"erlauben","en":"to allow, permit","pos":"verb","plural":"","meanings":[{"en":"to allow, give permission","de":"jemandem etwas gestatten"}],"rule":"regelmäßig: erlaubt, erlaubte, hat erlaubt; + Dativ der Person","example":"Meine Eltern erlauben mir, allein zu reisen.","exampleEn":"My parents allow me to travel alone.","example2":"Hier ist das Rauchen nicht erlaubt.","example2En":"Smoking is not allowed here."},{"de":"erledigen","en":"to take care of, complete","pos":"verb","plural":"","meanings":[{"en":"to complete/finish a task","de":"eine Aufgabe fertig machen"}],"rule":"regelmäßig: erledigt, erledigte, hat erledigt; oft mit Einkäufe, Aufgaben","example":"Ich muss noch ein paar Einkäufe erledigen.","exampleEn":"I still need to run a few errands.","example2":"Hast du die Hausaufgaben schon erledigt?","example2En":"Have you already finished your homework?"},{"de":"eröffnen","en":"to open (formally)","pos":"verb","plural":"","meanings":[{"en":"to open (a business, account, event)","de":"offiziell beginnen/öffnen"}],"rule":"regelmäßig: eröffnet, eröffnete, hat eröffnet; oft mit Konto, Geschäft, Ausstellung","example":"Die Bank hat mir ein neues Konto eröffnet.","exampleEn":"The bank opened a new account for me.","example2":"Morgen eröffnet das neue Restaurant.","example2En":"The new restaurant opens tomorrow."},{"de":"erreichen","en":"to reach; to achieve","pos":"verb","plural":"","meanings":[{"en":"to reach a place/person","de":"an ein Ziel kommen, jemanden kontaktieren"},{"en":"to achieve a goal","de":"ein Ziel erfolgreich schaffen"}],"rule":"regelmäßig: erreicht, erreichte, hat erreicht","example":"Wir haben den Bahnhof pünktlich erreicht.","exampleEn":"We reached the station on time.","example2":"Er hat sein Ziel endlich erreicht.","example2En":"He finally achieved his goal."},{"de":"erstatten","en":"to refund, reimburse","pos":"verb","plural":"","meanings":[{"en":"to refund/reimburse money","de":"Geld zurückzahlen"}],"rule":"regelmäßig: erstattet, erstattete, hat erstattet; oft mit Kosten, Geld; + Dativ der Person","example":"Die Firma erstattet mir die Reisekosten.","exampleEn":"The company reimburses me for travel costs.","example2":"Können Sie mir das Geld erstatten?","example2En":"Can you refund me the money?"},{"de":"erwarten","en":"to expect","pos":"verb","plural":"","meanings":[{"en":"to expect something/someone","de":"mit etwas rechnen"}],"rule":"regelmäßig: erwartet, erwartete, hat erwartet","example":"Wir erwarten morgen Besuch.","exampleEn":"We are expecting visitors tomorrow.","example2":"Sie erwartet ein Baby im Herbst.","example2En":"She is expecting a baby in autumn."},{"de":"erwischen","en":"to catch (informal)","pos":"verb","plural":"","meanings":[{"en":"to catch someone doing something / catch in time","de":"jemanden ertappen; etwas gerade noch schaffen"}],"rule":"regelmäßig: erwischt, erwischte, hat erwischt; umgangssprachlich","example":"Ich habe gerade noch den Bus erwischt.","exampleEn":"I just managed to catch the bus.","example2":"Der Lehrer hat ihn beim Spicken erwischt.","example2En":"The teacher caught him cheating."}]},{"id":"a2-07","title":"A2 · E–G (7)","level":"A2","words":[{"de":"etwa","en":"about, approximately","pos":"adverb","plural":"","meanings":[{"en":"approximately (with numbers)","de":"ungefähr"},{"en":"perhaps, by any chance (in questions)","de":"vielleicht, zufällig"}],"rule":"keine Steigerung; vor Zahlen = ungefähr, in Fragen = Überraschung/Vermutung","example":"Die Fahrt dauert etwa zwei Stunden.","exampleEn":"The trip takes about two hours.","example2":"Hast du das etwa vergessen?","example2En":"Did you perhaps forget that?"},{"de":"das Event","en":"event","pos":"noun","plural":"die Events","meanings":[{"en":"a (special) event/happening","de":"eine besondere Veranstaltung"}],"rule":"Englisches Lehnwort, im Deutschen sächlich: das Event. Wird oft für besondere, unterhaltsame Veranstaltungen benutzt.","example":"Am Wochenende gibt es ein großes Event in der Stadt.","exampleEn":"This weekend there is a big event in the city.","example2":"Das Konzert war ein tolles Event.","example2En":"The concert was a great event."},{"de":"das Fach","en":"subject; compartment","pos":"noun","plural":"die Fächer","meanings":[{"en":"school/study subject","de":"Schulfach, z. B. Mathematik"},{"en":"compartment, shelf","de":"kleiner Raum zum Ablegen, z. B. im Schrank"}],"rule":"Plural mit Umlaut: das Fach – die Fächer.","example":"Mathe ist mein Lieblingsfach.","exampleEn":"Math is my favorite subject.","example2":"Leg die Bücher ins Fach im Regal.","example2En":"Put the books in the compartment on the shelf."},{"de":"die Fachhochschule","en":"university of applied sciences","pos":"noun","plural":"die Fachhochschulen","meanings":[{"en":"university of applied sciences (FH)","de":"praxisorientierte Hochschule"}],"rule":"Zusammengesetztes Wort: Fach + Hochschule; Abkürzung FH.","example":"Sie studiert Informatik an einer Fachhochschule.","exampleEn":"She studies computer science at a university of applied sciences.","example2":"Die Fachhochschule bietet praktische Studiengänge an.","example2En":"The university of applied sciences offers practical degree programs."},{"de":"die Fachhochschulreife","en":"qualification for university of applied sciences","pos":"noun","plural":"","meanings":[{"en":"school qualification allowing entry to a Fachhochschule","de":"Schulabschluss für die Fachhochschule"}],"rule":"Meist unzählbar, kein Plural gebräuchlich; oft als 'Fachabi' abgekürzt.","example":"Nach der 12. Klasse hat er die Fachhochschulreife.","exampleEn":"After grade 12 he has the qualification for a university of applied sciences.","example2":"Mit der Fachhochschulreife kann man an einer FH studieren.","example2En":"With this qualification you can study at a university of applied sciences."},{"de":"der Fahrkartenschalter","en":"ticket counter","pos":"noun","plural":"die Fahrkartenschalter","meanings":[{"en":"ticket counter/window (at station)","de":"Schalter, an dem man Fahrkarten kauft"}],"rule":"Zusammensetzung: Fahrkarte + Schalter; Plural bleibt unverändert.","example":"Ich kaufe die Fahrkarte am Fahrkartenschalter.","exampleEn":"I buy the ticket at the ticket counter.","example2":"Der Fahrkartenschalter ist heute geschlossen.","example2En":"The ticket counter is closed today."},{"de":"der Fahrplan","en":"timetable, schedule","pos":"noun","plural":"die Fahrpläne","meanings":[{"en":"timetable for trains/buses","de":"Übersicht der Abfahrtszeiten"}],"rule":"Plural mit Umlaut: der Fahrplan – die Fahrpläne.","example":"Schau im Fahrplan nach, wann der Bus fährt.","exampleEn":"Check the timetable to see when the bus leaves.","example2":"Der neue Fahrplan gilt ab Montag.","example2En":"The new timetable is valid from Monday."},{"de":"der Fahrradhelm","en":"bicycle helmet","pos":"noun","plural":"die Fahrradhelme","meanings":[{"en":"helmet for cycling","de":"Schutzhelm für das Fahrrad"}],"rule":"Zusammensetzung: Fahrrad + Helm.","example":"Trag beim Radfahren immer einen Fahrradhelm.","exampleEn":"Always wear a bicycle helmet when cycling.","example2":"Er hat seinen Fahrradhelm zu Hause vergessen.","example2En":"He forgot his bicycle helmet at home."},{"de":"der Fahrradständer","en":"bicycle rack/stand","pos":"noun","plural":"die Fahrradständer","meanings":[{"en":"rack or stand for parking bicycles","de":"Gestell zum Abstellen von Fahrrädern"}],"rule":"Zusammensetzung: Fahrrad + Ständer; Plural bleibt gleich.","example":"Stell dein Fahrrad in den Fahrradständer.","exampleEn":"Put your bicycle in the bicycle rack.","example2":"Vor dem Bahnhof gibt es viele Fahrradständer.","example2En":"There are many bicycle racks in front of the station."},{"de":"die Familienkasse","en":"family benefits office","pos":"noun","plural":"die Familienkassen","meanings":[{"en":"office that pays child benefit (Kindergeld)","de":"Behörde, die Kindergeld auszahlt"}],"rule":"Zusammensetzung: Familie + Kasse.","example":"Sie beantragt das Kindergeld bei der Familienkasse.","exampleEn":"She applies for child benefit at the family benefits office.","example2":"Die Familienkasse hat den Antrag genehmigt.","example2En":"The family benefits office approved the application."},{"de":"das Familienmitglied","en":"family member","pos":"noun","plural":"die Familienmitglieder","meanings":[{"en":"a member of a family","de":"Person aus der Familie"}],"rule":"Zusammensetzung: Familie + Mitglied; Plural mit -er: das Familienmitglied – die Familienmitglieder.","example":"Jedes Familienmitglied hilft im Haushalt.","exampleEn":"Every family member helps with the household.","example2":"Wie viele Familienmitglieder habt ihr eingeladen?","example2En":"How many family members did you invite?"},{"de":"das Familienstammbuch","en":"family register book","pos":"noun","plural":"die Familienstammbücher","meanings":[{"en":"official booklet recording family/marriage data, given at marriage","de":"amtliches Dokument mit Familiendaten, das man bei der Hochzeit bekommt"}],"rule":"Zusammensetzung: Familie + Stammbuch; Plural mit Umlaut: das Familienstammbuch – die Familienstammbücher.","example":"Bei der Hochzeit bekommt man ein Familienstammbuch.","exampleEn":"You receive a family register book at the wedding.","example2":"Das Familienstammbuch enthält alle wichtigen Familiendaten.","example2En":"The family register book contains all important family data."},{"de":"fantastisch","en":"fantastic, great","pos":"adjective","plural":"","meanings":[{"en":"wonderful, great","de":"sehr gut, toll"}],"rule":"Regelmäßige Steigerung: fantastisch, fantastischer, am fantastischsten.","example":"Das Essen im Restaurant war fantastisch.","exampleEn":"The food at the restaurant was fantastic.","example2":"Wir hatten einen fantastischen Urlaub.","example2En":"We had a fantastic vacation."},{"de":"das Fast Food","en":"fast food","pos":"noun","plural":"","meanings":[{"en":"quickly prepared, inexpensive food","de":"schnelles, einfaches Essen"}],"rule":"Sächlich gebraucht ('das Fast Food'), meist ohne Artikel im Alltag; unzählbar, kein Plural.","example":"Er isst zu oft Fast Food.","exampleEn":"He eats fast food too often.","example2":"Fast Food ist nicht sehr gesund.","example2En":"Fast food is not very healthy."},{"de":"fehlen","en":"to be missing; to be absent","pos":"verb","plural":"","meanings":[{"en":"to be missing/lacking","de":"nicht vorhanden sein"},{"en":"to be absent (e.g. from school)","de":"nicht anwesend sein"}],"rule":"Regelmäßig; oft mit Dativ der Person: 'Mir fehlt Zeit.' Perfekt: hat gefehlt.","example":"Mir fehlt noch ein Euro für den Kaffee.","exampleEn":"I'm still missing one euro for the coffee.","example2":"Er hat heute in der Schule gefehlt.","example2En":"He was absent from school today."},{"de":"der Fernbus","en":"long-distance bus","pos":"noun","plural":"die Fernbusse","meanings":[{"en":"coach for long-distance travel","de":"Bus für lange Strecken zwischen Städten"}],"rule":"Zusammensetzung: fern + Bus; Plural: die Fernbusse.","example":"Wir fahren mit dem Fernbus nach Berlin.","exampleEn":"We are traveling to Berlin by long-distance bus.","example2":"Der Fernbus ist günstiger als der Zug.","example2En":"The long-distance bus is cheaper than the train."},{"de":"die Fernwärme","en":"district heating","pos":"noun","plural":"","meanings":[{"en":"centrally produced heating distributed to buildings","de":"Wärme aus einem zentralen Heizkraftwerk"}],"rule":"Unzählbares Wort, kein Plural.","example":"Unser Haus wird mit Fernwärme beheizt.","exampleEn":"Our house is heated with district heating.","example2":"Die Stadt baut das Fernwärmenetz aus.","example2En":"The city is expanding the district heating network."},{"de":"der Feuerlöscher","en":"fire extinguisher","pos":"noun","plural":"die Feuerlöscher","meanings":[{"en":"device to put out small fires","de":"Gerät zum Löschen eines Feuers"}],"rule":"Zusammensetzung: Feuer + löschen + -er; Plural bleibt gleich.","example":"Im Flur hängt ein Feuerlöscher.","exampleEn":"There is a fire extinguisher hanging in the hallway.","example2":"Bitte prüfen Sie regelmäßig den Feuerlöscher.","example2En":"Please check the fire extinguisher regularly."},{"de":"das Feuerzeug","en":"lighter","pos":"noun","plural":"die Feuerzeuge","meanings":[{"en":"small device for lighting fires/cigarettes","de":"kleines Gerät zum Anzünden"}],"rule":"Zusammensetzung: Feuer + Zeug.","example":"Hast du ein Feuerzeug für die Kerze?","exampleEn":"Do you have a lighter for the candle?","example2":"Er hat sein Feuerzeug verloren.","example2En":"He lost his lighter."},{"de":"die Filiale","en":"branch (of a shop/bank)","pos":"noun","plural":"die Filialen","meanings":[{"en":"branch office / branch store","de":"Zweigstelle eines Unternehmens"}],"rule":"Feminine noun; often used with Bank, Supermarkt, or Firma names.","example":"Die Bank hat eine Filiale in unserer Stadt.","exampleEn":"The bank has a branch in our city.","example2":"Ich kaufe immer in der Filiale in der Nähe ein.","example2En":"I always shop at the branch nearby."},{"de":"das Finanzamt","en":"tax office","pos":"noun","plural":"die Finanzämter","meanings":[{"en":"government tax authority office","de":"Behörde für Steuern"}],"rule":"Neuter noun; compound of Finanz + Amt; umlaut in plural (Ämter).","example":"Ich muss meine Steuererklärung zum Finanzamt schicken.","exampleEn":"I have to send my tax return to the tax office.","example2":"Das Finanzamt hat mir einen Brief geschickt.","example2En":"The tax office sent me a letter."},{"de":"fit","en":"fit, in good shape","pos":"adjective","plural":"","meanings":[{"en":"physically healthy and in good shape","de":"körperlich gesund und trainiert"}],"rule":"Regular comparison: fit, fitter, am fittesten.","example":"Ich mache Sport, um fit zu bleiben.","exampleEn":"I do sports to stay fit.","example2":"Er ist mit 60 Jahren noch sehr fit.","example2En":"At 60, he is still very fit."},{"de":"die Fitness","en":"fitness","pos":"noun","plural":"","meanings":[{"en":"physical fitness, good physical condition","de":"körperliche Leistungsfähigkeit"}],"rule":"Feminine noun, uncountable (no plural); often in compounds like Fitnessstudio.","example":"Für ihre Fitness geht sie dreimal pro Woche ins Fitnessstudio.","exampleEn":"For her fitness, she goes to the gym three times a week.","example2":"Gute Fitness ist wichtig für die Gesundheit.","example2En":"Good fitness is important for health."},{"de":"die Flamme","en":"flame","pos":"noun","plural":"die Flammen","meanings":[{"en":"a flame of fire","de":"das Feuer einer Kerze oder eines Herds"}],"rule":"Feminine noun; common in kitchen/cooking context.","example":"Die Kerze brennt mit einer kleinen Flamme.","exampleEn":"The candle burns with a small flame.","example2":"Stell den Topf auf kleine Flamme.","example2En":"Put the pot on a low flame."},{"de":"fliegen","en":"to fly","pos":"verb","plural":"","meanings":[{"en":"to travel by airplane","de":"mit dem Flugzeug reisen"},{"en":"(of birds/objects) to fly through the air","de":"sich durch die Luft bewegen"}],"rule":"Irregular: fliegt, flog, ist geflogen (movement, so with sein).","example":"Wir fliegen im Sommer nach Spanien.","exampleEn":"We are flying to Spain in the summer.","example2":"Der Vogel fliegt aus dem Fenster.","example2En":"The bird flies out of the window."},{"de":"fliehen","en":"to flee, to escape","pos":"verb","plural":"","meanings":[{"en":"to run away from danger","de":"vor Gefahr weglaufen"}],"rule":"Irregular: flieht, floh, ist geflohen (with sein).","example":"Die Familie ist vor dem Krieg geflohen.","exampleEn":"The family fled the war.","example2":"Viele Menschen fliehen aus ihrer Heimat.","example2En":"Many people flee their homeland."},{"de":"der Flipflop","en":"flip-flop","pos":"noun","plural":"die Flipflops","meanings":[{"en":"open sandal worn in summer (usually used in plural, as a pair)","de":"leichter Sommerschuh (meist im Plural, als Paar)"}],"rule":"Masculine noun (der Flipflop), borrowed from English; almost always used in the plural (die Flipflops) since worn in pairs.","example":"Im Sommer trage ich oft Flipflops.","exampleEn":"In summer I often wear flip-flops.","example2":"Meine Flipflops sind am Strand kaputtgegangen.","example2En":"My flip-flops broke at the beach."},{"de":"flirten","en":"to flirt","pos":"verb","plural":"","meanings":[{"en":"to behave playfully/romantically with someone","de":"jemandem verliebt/verspielt zeigen, dass man ihn mag"}],"rule":"Regular weak verb: flirtet, flirtete, hat geflirtet; often used with 'mit'.","example":"Er flirtet gern mit den Kolleginnen.","exampleEn":"He likes to flirt with his female colleagues.","example2":"Sie haben auf der Party miteinander geflirtet.","example2En":"They flirted with each other at the party."},{"de":"der Flohmarkt","en":"flea market","pos":"noun","plural":"die Flohmärkte","meanings":[{"en":"outdoor market selling used goods","de":"Markt für gebrauchte Sachen"}],"rule":"Masculine noun; compound of Floh + Markt; umlaut in plural.","example":"Am Samstag gehen wir auf den Flohmarkt.","exampleEn":"On Saturday we're going to the flea market.","example2":"Auf dem Flohmarkt habe ich einen alten Tisch gekauft.","example2En":"At the flea market I bought an old table."},{"de":"das Flugzeug","en":"airplane","pos":"noun","plural":"die Flugzeuge","meanings":[{"en":"aircraft for air travel","de":"Fahrzeug, das fliegt"}],"rule":"Neuter noun; compound of Flug + Zeug.","example":"Das Flugzeug startet um zehn Uhr.","exampleEn":"The airplane takes off at ten o'clock.","example2":"Wir fliegen mit einem großen Flugzeug nach New York.","example2En":"We're flying to New York on a big airplane."},{"de":"der Fluss","en":"river","pos":"noun","plural":"die Flüsse","meanings":[{"en":"a large natural stream of water","de":"großes fließendes Gewässer"}],"rule":"Masculine noun; umlaut in plural (Flüsse).","example":"Der Rhein ist ein langer Fluss.","exampleEn":"The Rhine is a long river.","example2":"Wir sind am Fluss spazieren gegangen.","example2En":"We took a walk by the river."},{"de":"folgen","en":"to follow","pos":"verb","plural":"","meanings":[{"en":"to go after someone/something","de":"hinter jemandem hergehen"},{"en":"to follow (e.g. on social media)","de":"jemandem online folgen"}],"rule":"Regular weak verb: folgt, folgte, ist gefolgt; governs Dativ (+ Dativ).","example":"Der Hund folgt seinem Besitzer überallhin.","exampleEn":"The dog follows its owner everywhere.","example2":"Ich folge ihr auf Instagram.","example2En":"I follow her on Instagram."},{"de":"folgend","en":"following, next","pos":"adjective","plural":"","meanings":[{"en":"coming next, mentioned afterward","de":"was danach kommt"}],"rule":"From the verb folgen; used before nouns like 'folgende Woche'.","example":"Bitte lesen Sie den folgenden Text.","exampleEn":"Please read the following text.","example2":"Am folgenden Tag war das Wetter besser.","example2En":"The following day the weather was better."},{"de":"formell","en":"formal","pos":"adjective","plural":"","meanings":[{"en":"official, following formal rules or style","de":"offiziell, nach festen Regeln"}],"rule":"Regular comparison: formell, formeller, am formellsten.","example":"Bei der Arbeit tragen wir formelle Kleidung.","exampleEn":"At work we wear formal clothing.","example2":"Das war ein sehr formelles Treffen.","example2En":"That was a very formal meeting."},{"de":"formulieren","en":"to formulate, to phrase","pos":"verb","plural":"","meanings":[{"en":"to express something in words","de":"etwas in Worte fassen"}],"rule":"Regular weak verb: formuliert, formulierte, hat formuliert.","example":"Kannst du die Frage anders formulieren?","exampleEn":"Can you phrase the question differently?","example2":"Sie hat ihre Kritik sehr höflich formuliert.","example2En":"She phrased her criticism very politely."},{"de":"fortgeschritten","en":"advanced","pos":"adjective","plural":"","meanings":[{"en":"at a high skill level, not a beginner","de":"nicht mehr Anfänger, mit viel Erfahrung"}],"rule":"Past participle of fortschreiten, used as adjective; common in course levels (Fortgeschrittene).","example":"Der Kurs ist für fortgeschrittene Lerner.","exampleEn":"The course is for advanced learners.","example2":"Sie hat fortgeschrittene Kenntnisse in Spanisch.","example2En":"She has advanced knowledge of Spanish."},{"de":"das Forum","en":"forum","pos":"noun","plural":"die Foren","meanings":[{"en":"an online discussion platform","de":"Website für Diskussionen"},{"en":"a place/event for public discussion","de":"Ort für öffentliche Diskussion"}],"rule":"Neuter noun; irregular Latin-origin plural: Foren.","example":"Ich habe eine Antwort in einem Forum im Internet gefunden.","exampleEn":"I found an answer in a forum on the internet.","example2":"Die Konferenz war ein Forum für neue Ideen.","example2En":"The conference was a forum for new ideas."},{"de":"der Fotograf / die Fotografin","en":"photographer","pos":"noun","plural":"die Fotografen / die Fotografinnen","meanings":[{"en":"person who takes photographs professionally","de":"jemand, der beruflich Fotos macht"}],"rule":"N-Deklination: der Fotograf, den/dem/des Fotografen (außer Nominativ Singular).","example":"Mein Bruder ist Fotograf von Beruf.","exampleEn":"My brother is a photographer by profession.","example2":"Die Fotografin macht Bilder von der Hochzeit.","example2En":"The photographer is taking pictures of the wedding."},{"de":"freiwillig","en":"voluntary","pos":"adjective","plural":"","meanings":[{"en":"done by free choice, not forced","de":"aus freiem Willen, nicht gezwungen"}],"rule":"Regelmäßige Steigerung: freiwillig, freiwilliger, am freiwilligsten.","example":"Er arbeitet freiwillig im Krankenhaus.","exampleEn":"He works voluntarily at the hospital.","example2":"Die Teilnahme am Kurs ist freiwillig.","example2En":"Participation in the course is voluntary."},{"de":"die Freizeit","en":"free time; leisure time","pos":"noun","plural":"","meanings":[{"en":"time not spent working","de":"Zeit ohne Arbeit oder Schule"}],"rule":"Meist unzählbar, kein Plural.","example":"Was machst du in deiner Freizeit?","exampleEn":"What do you do in your free time?","example2":"Ich habe im Moment wenig Freizeit.","example2En":"I have little free time at the moment."},{"de":"die Freizeitaktivität","en":"leisure activity","pos":"noun","plural":"die Freizeitaktivitäten","meanings":[{"en":"an activity done in free time","de":"eine Aktivität in der Freizeit"}],"rule":"Zusammengesetztes Nomen: Freizeit + Aktivität; Artikel wie das Grundwort 'die Aktivität'.","example":"Schwimmen ist meine liebste Freizeitaktivität.","exampleEn":"Swimming is my favorite leisure activity.","example2":"Die Schüler stellen verschiedene Freizeitaktivitäten vor.","example2En":"The students present different leisure activities."},{"de":"das Freizeitangebot","en":"leisure offer; range of leisure activities","pos":"noun","plural":"die Freizeitangebote","meanings":[{"en":"activities or facilities offered for leisure","de":"Angebot an Freizeitaktivitäten, z. B. in einer Stadt"}],"rule":"Zusammengesetztes Nomen: Freizeit + Angebot; Artikel 'das' wie 'das Angebot'.","example":"Die Stadt hat ein großes Freizeitangebot.","exampleEn":"The city has a wide range of leisure activities.","example2":"Das Hotel bietet ein tolles Freizeitangebot für Kinder.","example2En":"The hotel offers a great range of leisure activities for children."},{"de":"das Freizeitvergnügen","en":"leisure pleasure; pastime","pos":"noun","plural":"die Freizeitvergnügen","meanings":[{"en":"an enjoyable leisure activity","de":"eine angenehme Beschäftigung in der Freizeit"}],"rule":"Zusammengesetztes Nomen: Freizeit + Vergnügen; Plural bleibt unverändert.","example":"Radfahren ist ein beliebtes Freizeitvergnügen.","exampleEn":"Cycling is a popular leisure pastime.","example2":"Für viele ist Kochen ein echtes Freizeitvergnügen.","example2En":"For many, cooking is a real leisure pleasure."},{"de":"der Frisör / die Frisörin","en":"hairdresser","pos":"noun","plural":"die Frisöre / die Frisörinnen","meanings":[{"en":"person who cuts and styles hair","de":"jemand, der Haare schneidet und stylt"}],"rule":"Auch Schreibweise 'Friseur/Friseurin'; regelmäßige Pluralbildung.","example":"Ich habe morgen einen Termin beim Frisör.","exampleEn":"I have an appointment at the hairdresser's tomorrow.","example2":"Die Frisörin schneidet mir die Haare kurz.","example2En":"The hairdresser is cutting my hair short."},{"de":"frittieren","en":"to deep-fry","pos":"verb","plural":"","meanings":[{"en":"to cook food in hot oil","de":"in heißem Fett/Öl garen"}],"rule":"Regelmäßiges Verb: frittiert, frittierte, hat frittiert.","example":"Wir frittieren die Pommes selbst.","exampleEn":"We deep-fry the fries ourselves.","example2":"Der Fisch wird in Öl frittiert.","example2En":"The fish is deep-fried in oil."},{"de":"funktionieren","en":"to work; to function","pos":"verb","plural":"","meanings":[{"en":"to work properly (machine, device)","de":"richtig arbeiten (Gerät, Maschine)"},{"en":"to work out, go well (plan, system)","de":"gut ablaufen, gelingen (Plan, System)"}],"rule":"Regelmäßiges Verb: funktioniert, funktionierte, hat funktioniert.","example":"Der Fernseher funktioniert nicht mehr.","exampleEn":"The TV doesn't work anymore.","example2":"So funktioniert das neue System.","example2En":"This is how the new system works."},{"de":"die Gabel","en":"fork","pos":"noun","plural":"die Gabeln","meanings":[{"en":"eating utensil with prongs","de":"Essbesteck mit Zinken"}],"rule":"Feminin, regelmäßiger Plural auf -n.","example":"Kannst du mir bitte eine Gabel geben?","exampleEn":"Can you give me a fork, please?","example2":"Er isst den Salat mit Messer und Gabel.","example2En":"He eats the salad with a knife and fork."},{"de":"das Gas","en":"gas","pos":"noun","plural":"die Gase","meanings":[{"en":"gaseous substance used for heating/cooking","de":"gasförmiger Stoff zum Heizen/Kochen"}],"rule":"Neutrum; in der Bedeutung 'Erdgas' meist unzählbar.","example":"Wir kochen mit Gas.","exampleEn":"We cook with gas.","example2":"Die Gaspreise sind gestiegen.","example2En":"Gas prices have risen."},{"de":"Gassi gehen","en":"to walk the dog","pos":"phrase","plural":"","meanings":[{"en":"to take a dog for a walk","de":"mit dem Hund spazieren gehen"}],"rule":"Feste Wendung mit 'gehen': er geht Gassi, ist Gassi gegangen.","example":"Ich gehe jeden Abend mit dem Hund Gassi.","exampleEn":"I walk the dog every evening.","example2":"Kannst du heute Gassi gehen?","example2En":"Can you walk the dog today?"},{"de":"die Gastronomie","en":"gastronomy; catering industry","pos":"noun","plural":"","meanings":[{"en":"the restaurant and catering business","de":"Branche der Restaurants und Gaststätten"}],"rule":"Unzählbar, kein Plural.","example":"Er arbeitet seit zehn Jahren in der Gastronomie.","exampleEn":"He has worked in the catering industry for ten years.","example2":"Die Gastronomie hat in der Krise viel verloren.","example2En":"The restaurant industry lost a lot during the crisis."}]},{"id":"a2-08","title":"A2 · G (8)","level":"A2","words":[{"de":"gebraucht","en":"used; second-hand","pos":"adjective","plural":"","meanings":[{"en":"not new, previously owned","de":"nicht neu, schon benutzt"}],"rule":"Partizip II von 'gebrauchen' (benutzen) — nicht zu verwechseln mit dem gleich lautenden Partizip 'gebraucht' von 'brauchen' ('nötig haben'). In der Bedeutung 'gebraucht/second-hand' wird das Adjektiv kaum gesteigert (üblich ist 'neu' vs. 'gebraucht', nicht 'gebrauchter/am gebrauchtesten').","example":"Wir kaufen ein gebrauchtes Auto.","exampleEn":"We are buying a used car.","example2":"Die Bücher sind alle gebraucht, aber gut erhalten.","example2En":"The books are all second-hand but in good condition."},{"de":"die Gebühr","en":"fee; charge","pos":"noun","plural":"die Gebühren","meanings":[{"en":"money paid for a service","de":"Geld, das man für eine Leistung bezahlt"}],"rule":"Feminin, regelmäßiger Plural auf -en.","example":"Für die Anmeldung fällt eine Gebühr an.","exampleEn":"There is a fee for registration.","example2":"Die Parkgebühren sind sehr hoch.","example2En":"The parking fees are very high."},{"de":"die Geburt","en":"birth","pos":"noun","plural":"die Geburten","meanings":[{"en":"the act of being born","de":"das Geborenwerden"}],"rule":"Feminin, regelmäßiger Plural auf -en.","example":"Die Geburt ihres Sohnes war ein großes Glück.","exampleEn":"The birth of her son was a great joy.","example2":"Er war bei der Geburt dabei.","example2En":"He was present at the birth."},{"de":"das Geburtsdatum","en":"date of birth","pos":"noun","plural":"die Geburtsdaten","meanings":[{"en":"the date on which someone was born","de":"das Datum, an dem jemand geboren wurde"}],"rule":"Zusammengesetztes Nomen: Geburt + Datum; Plural wie 'Daten'.","example":"Bitte geben Sie Ihr Geburtsdatum an.","exampleEn":"Please state your date of birth.","example2":"Mein Geburtsdatum steht im Pass.","example2En":"My date of birth is in my passport."},{"de":"das Geburtsland","en":"country of birth","pos":"noun","plural":"die Geburtsländer","meanings":[{"en":"the country where someone was born","de":"das Land, in dem jemand geboren wurde"}],"rule":"Zusammengesetztes Nomen: Geburt + Land; Plural mit Umlaut: die Geburtsländer.","example":"Mein Geburtsland ist die Türkei.","exampleEn":"My country of birth is Turkey.","example2":"Sie besucht oft ihr Geburtsland.","example2En":"She often visits her country of birth."},{"de":"der Geburtsname","en":"birth name","pos":"noun","plural":"die Geburtsnamen","meanings":[{"en":"name given at birth (esp. before marriage)","de":"Name, den man bei der Geburt bekommen hat"}],"rule":"Compound noun: die Geburt + der Name; gender follows der Name.","example":"Ihr Geburtsname ist Meier, jetzt heißt sie Schmidt.","exampleEn":"Her birth name is Meier, now she is called Schmidt.","example2":"Bitte tragen Sie Ihren Geburtsnamen im Formular ein.","example2En":"Please enter your birth name on the form."},{"de":"der Geburtsort","en":"place of birth","pos":"noun","plural":"die Geburtsorte","meanings":[{"en":"town or city where someone was born","de":"Ort, an dem jemand geboren wurde"}],"rule":"Compound: die Geburt + der Ort; often required on official forms.","example":"Mein Geburtsort ist Hamburg.","exampleEn":"My place of birth is Hamburg.","example2":"Wo ist Ihr Geburtsort?","example2En":"Where is your place of birth?"},{"de":"die Geburtsurkunde","en":"birth certificate","pos":"noun","plural":"die Geburtsurkunden","meanings":[{"en":"official document certifying a birth","de":"amtliches Dokument, das die Geburt bestätigt"}],"rule":"Compound: die Geburt + die Urkunde.","example":"Ich brauche eine Kopie meiner Geburtsurkunde.","exampleEn":"I need a copy of my birth certificate.","example2":"Die Geburtsurkunde bekommt man beim Standesamt.","example2En":"You get the birth certificate at the registry office."},{"de":"das Gedicht","en":"poem","pos":"noun","plural":"die Gedichte","meanings":[{"en":"a piece of poetry","de":"literarischer Text in Versen"}],"rule":"Neuter noun with a Ge- prefix; there is no everyday verb 'gedichten' — the related verb is 'dichten' (to write poetry).","example":"Die Schüler lernen ein Gedicht auswendig.","exampleEn":"The students learn a poem by heart.","example2":"Er hat ihr ein Gedicht geschrieben.","example2En":"He wrote her a poem."},{"de":"gefährden","en":"to endanger","pos":"verb","plural":"","meanings":[{"en":"to put something/someone at risk","de":"in Gefahr bringen"}],"rule":"Regular weak verb: gefährdet, gefährdete, hat gefährdet; takes Akkusativ object.","example":"Rauchen gefährdet die Gesundheit.","exampleEn":"Smoking endangers your health.","example2":"Der Sturm gefährdet die Ernte.","example2En":"The storm is endangering the harvest."},{"de":"der Gegensatz","en":"contrast; opposite","pos":"noun","plural":"die Gegensätze","meanings":[{"en":"opposite or contrary","de":"das Gegenteil"},{"en":"contrast between things","de":"deutlicher Unterschied"}],"rule":"Often used with 'im Gegensatz zu' (+ Dativ) = 'in contrast to'.","example":"Im Gegensatz zu ihrer Schwester ist sie sehr ruhig.","exampleEn":"In contrast to her sister, she is very quiet.","example2":"Schwarz und Weiß sind ein starker Gegensatz.","example2En":"Black and white are a strong contrast."},{"de":"gehören","en":"to belong to","pos":"verb","plural":"","meanings":[{"en":"to be owned by someone","de":"jemandem als Eigentum zugeordnet sein"},{"en":"to be part of / belong with","de":"zu etwas zählen, dazugehören"}],"rule":"Regular verb + Dativ: gehört, gehörte, hat gehört; 'Das Buch gehört mir' = it's mine.","example":"Das Auto gehört meinem Vater.","exampleEn":"The car belongs to my father.","example2":"Diese Frage gehört nicht zum Thema.","example2En":"This question doesn't belong to the topic."},{"de":"der Geiger / die Geigerin","en":"violinist","pos":"noun","plural":"die Geiger / die Geigerinnen","meanings":[{"en":"a person who plays the violin","de":"jemand, der Geige spielt"}],"rule":"Agent noun from 'die Geige' (violin) + -er/-in.","example":"Der Geiger spielt heute Abend im Konzert.","exampleEn":"The violinist is playing in the concert tonight.","example2":"Sie ist eine bekannte Geigerin.","example2En":"She is a well-known violinist."},{"de":"der Geldautomat","en":"ATM, cash machine","pos":"noun","plural":"die Geldautomaten","meanings":[{"en":"machine for withdrawing cash","de":"Automat, an dem man Geld abheben kann"}],"rule":"Compound: das Geld + der Automat; weak masculine noun (den/dem/des Geldautomaten).","example":"Ich hebe am Geldautomaten Bargeld ab.","exampleEn":"I withdraw cash at the ATM.","example2":"Der Geldautomat ist gerade außer Betrieb.","example2En":"The ATM is currently out of order."},{"de":"die Geldbörse","en":"purse, wallet","pos":"noun","plural":"die Geldbörsen","meanings":[{"en":"small case for carrying money","de":"kleine Tasche für Geld"}],"rule":"Compound: das Geld + die Börse; synonym to der Geldbeutel/das Portemonnaie.","example":"Meine Geldbörse ist leer.","exampleEn":"My wallet is empty.","example2":"Sie hat ihre Geldbörse im Bus verloren.","example2En":"She lost her purse on the bus."},{"de":"das Geldstück","en":"coin","pos":"noun","plural":"die Geldstücke","meanings":[{"en":"a single piece of coin money","de":"eine Münze"}],"rule":"Compound: das Geld + das Stück; synonym die Münze.","example":"Er suchte ein Geldstück für den Parkautomaten.","exampleEn":"He looked for a coin for the parking meter.","example2":"Das Geldstück ist auf den Boden gefallen.","example2En":"The coin fell on the floor."},{"de":"gemischt","en":"mixed","pos":"adjective","plural":"","meanings":[{"en":"consisting of different types combined","de":"aus verschiedenen Dingen bestehend"}],"rule":"Past participle of 'mischen' used as adjective; regular comparison (gemischter, am gemischtesten) though rarely compared.","example":"Ich hätte gern einen gemischten Salat.","exampleEn":"I'd like a mixed salad.","example2":"Wir sind eine gemischte Gruppe aus Männern und Frauen.","example2En":"We are a mixed group of men and women."},{"de":"die Gemüselasagne","en":"vegetable lasagna","pos":"noun","plural":"die Gemüselasagnen","meanings":[{"en":"lasagna made with vegetables instead of meat","de":"Lasagne mit Gemüse statt Fleisch"}],"rule":"Compound: das Gemüse + die Lasagne; gender follows die Lasagne.","example":"Zum Mittagessen gibt es Gemüselasagne.","exampleEn":"For lunch there is vegetable lasagna.","example2":"Die Gemüselasagne schmeckt sehr gut.","example2En":"The vegetable lasagna tastes very good."},{"de":"genehmigen","en":"to approve, to permit","pos":"verb","plural":"","meanings":[{"en":"to officially allow or approve something","de":"offiziell erlauben"}],"rule":"Regular verb: genehmigt, genehmigte, hat genehmigt; often used passively 'genehmigt werden'.","example":"Der Chef hat meinen Urlaub genehmigt.","exampleEn":"The boss approved my vacation.","example2":"Der Bauantrag wurde genehmigt.","example2En":"The building application was approved."},{"de":"genial","en":"brilliant, ingenious","pos":"adjective","plural":"","meanings":[{"en":"extremely clever or outstanding","de":"sehr klug, außergewöhnlich gut"}],"rule":"Regular comparison: genial, genialer, am genialsten; colloquially also means 'awesome'.","example":"Das ist eine geniale Idee!","exampleEn":"That's a brilliant idea!","example2":"Einstein war ein genialer Wissenschaftler.","example2En":"Einstein was a brilliant scientist."},{"de":"genießen","en":"to enjoy","pos":"verb","plural":"","meanings":[{"en":"to take pleasure in something","de":"mit Freude erleben"}],"rule":"Irregular: genießt, genoss, hat genossen.","example":"Wir genießen den Urlaub am Meer.","exampleEn":"We are enjoying the vacation at the sea.","example2":"Er genießt die Ruhe am Abend.","example2En":"He enjoys the quiet in the evening."},{"de":"genug","en":"enough","pos":"adverb","plural":"","meanings":[{"en":"sufficient amount","de":"ausreichend"}],"rule":"Invariable; can follow noun/adjective: 'Geld genug' or precede: 'genug Geld'.","example":"Wir haben genug Zeit.","exampleEn":"We have enough time.","example2":"Ist das Essen genug für alle?","example2En":"Is the food enough for everyone?"},{"de":"gepunktet","en":"dotted, polka-dotted","pos":"adjective","plural":"","meanings":[{"en":"having a pattern of dots","de":"mit Punkten gemustert"}],"rule":"Adjective built from 'der Punkt' (dot) in a participle-like ge-...-t pattern; not related to the verb 'punkten' (to score points in sports). Regular comparison, rarely used.","example":"Sie trägt ein gepunktetes Kleid.","exampleEn":"She is wearing a polka-dotted dress.","example2":"Ich mag die gepunktete Bluse.","example2En":"I like the dotted blouse."},{"de":"das Gericht","en":"dish (food); court (law)","pos":"noun","plural":"die Gerichte","meanings":[{"en":"a dish/meal","de":"eine Speise"},{"en":"a court of law","de":"eine staatliche Institution, die über Recht entscheidet"}],"rule":"Two unrelated meanings share one word; context decides. Plural die Gerichte for both.","example":"Das Gericht mit Reis schmeckt sehr gut.","exampleEn":"The dish with rice tastes very good.","example2":"Er muss morgen vor Gericht erscheinen.","example2En":"He has to appear in court tomorrow."},{"de":"gesamt","en":"total; entire","pos":"adjective","plural":"","meanings":[{"en":"total, whole","de":"ganz, insgesamt"}],"rule":"Used attributively before a noun; no irregular comparison (rarely compared).","example":"Die gesamte Familie kommt zur Feier.","exampleEn":"The whole family is coming to the party.","example2":"Wie hoch sind die gesamten Kosten?","example2En":"How high are the total costs?"},{"de":"die Gesamtschule","en":"comprehensive school","pos":"noun","plural":"die Gesamtschulen","meanings":[{"en":"a comprehensive secondary school (combines school types)","de":"eine Schulform, die verschiedene Schularten vereint"}],"rule":"Compound noun: gesamt + Schule; gender follows die Schule.","example":"Meine Tochter geht auf eine Gesamtschule.","exampleEn":"My daughter goes to a comprehensive school.","example2":"An der Gesamtschule lernen Kinder mit unterschiedlichem Niveau zusammen.","example2En":"At the comprehensive school, children of different levels learn together."},{"de":"die Geschichte","en":"story; history","pos":"noun","plural":"die Geschichten","meanings":[{"en":"a story/tale","de":"eine Erzählung"},{"en":"history (the subject/past)","de":"die Vergangenheit, das Schulfach"}],"rule":"Plural die Geschichten is mainly used for 'stories'; 'history' as a subject is usually uncountable (kein Plural).","example":"Meine Oma erzählt gern Geschichten.","exampleEn":"My grandma likes to tell stories.","example2":"Er interessiert sich sehr für Geschichte.","example2En":"He is very interested in history."},{"de":"das Geschirr","en":"dishes, crockery","pos":"noun","plural":"","meanings":[{"en":"dishes/crockery used for eating","de":"Teller, Tassen und Besteck zum Essen"}],"rule":"Uncountable (Singularwort ohne Plural); used with waschen/spülen.","example":"Kannst du bitte das Geschirr spülen?","exampleEn":"Can you please wash the dishes?","example2":"Nach dem Essen räumen wir das Geschirr weg.","example2En":"After eating, we put the dishes away."},{"de":"das Geschlecht","en":"gender; sex","pos":"noun","plural":"die Geschlechter","meanings":[{"en":"biological sex / gender","de":"männlich oder weiblich"}],"rule":"Neuter noun; plural die Geschlechter used e.g. 'beide Geschlechter'.","example":"Bitte geben Sie Ihr Geschlecht im Formular an.","exampleEn":"Please state your gender on the form.","example2":"Das Geschlecht des Kindes ist noch nicht bekannt.","example2En":"The baby's sex is not yet known."},{"de":"gesondert","en":"separate","pos":"adjective","plural":"","meanings":[{"en":"separate, apart","de":"getrennt, extra"}],"rule":"Often used with werden/behandeln: 'gesondert behandeln' = treat separately; no irregular forms.","example":"Die Rechnung wird Ihnen gesondert zugeschickt.","exampleEn":"The invoice will be sent to you separately.","example2":"Dieser Fall muss gesondert geprüft werden.","example2En":"This case must be examined separately."},{"de":"gestalten","en":"to design, shape","pos":"verb","plural":"","meanings":[{"en":"to design/arrange something","de":"etwas planen und formen"}],"rule":"Regular weak verb: gestaltet, gestaltete, hat gestaltet; not separable.","example":"Wir gestalten die Party bunt und fröhlich.","exampleEn":"We are designing the party to be colorful and cheerful.","example2":"Sie hat ihr Zimmer sehr schön gestaltet.","example2En":"She has decorated her room very nicely."},{"de":"gestreift","en":"striped","pos":"adjective","plural":"","meanings":[{"en":"having stripes","de":"mit Streifen"}],"rule":"Past participle of streifen used as adjective; regular comparison possible but rarely used.","example":"Er trägt ein gestreiftes Hemd.","exampleEn":"He is wearing a striped shirt.","example2":"Die gestreifte Tasche gefällt mir gut.","example2En":"I like the striped bag."},{"de":"gesund","en":"healthy","pos":"adjective","plural":"","meanings":[{"en":"in good health / healthful","de":"nicht krank; gut für die Gesundheit"}],"rule":"Irregular comparison: gesund, gesünder, am gesündesten.","example":"Obst und Gemüse sind gesund.","exampleEn":"Fruit and vegetables are healthy.","example2":"Ich hoffe, du bist wieder gesund.","example2En":"I hope you are healthy again."},{"de":"gesundheitlich","en":"health-related","pos":"adjective","plural":"","meanings":[{"en":"concerning one's health","de":"die Gesundheit betreffend"}],"rule":"Usually used attributively, e.g. 'gesundheitliche Probleme'; no irregular comparison.","example":"Er hat gesundheitliche Probleme.","exampleEn":"He has health problems.","example2":"Aus gesundheitlichen Gründen kann sie nicht arbeiten.","example2En":"For health reasons she cannot work."},{"de":"gewinnen","en":"to win","pos":"verb","plural":"","meanings":[{"en":"to win a game/prize/competition","de":"einen Sieg oder Preis erhalten"}],"rule":"Irregular: gewinnt, gewann, hat gewonnen.","example":"Unsere Mannschaft hat das Spiel gewonnen.","exampleEn":"Our team won the game.","example2":"Sie hat im Lotto viel Geld gewonnen.","example2En":"She won a lot of money in the lottery."},{"de":"das Gipsbein","en":"leg in a cast","pos":"noun","plural":"die Gipsbeine","meanings":[{"en":"a leg in a plaster cast","de":"ein Bein mit Gips nach einem Bruch"}],"rule":"Compound: Gips (plaster) + Bein (leg); neuter like Bein.","example":"Nach dem Unfall hat er ein Gipsbein.","exampleEn":"After the accident he has a leg in a cast.","example2":"Mit dem Gipsbein kann sie nicht gut laufen.","example2En":"With the leg in a cast she can't walk well."},{"de":"die Girocard","en":"debit card","pos":"noun","plural":"die Girocards","meanings":[{"en":"a bank debit card for direct payment","de":"eine Bankkarte zum bargeldlosen Bezahlen"}],"rule":"Feminine loanword; often used at the checkout: 'mit Girocard bezahlen'.","example":"Ich bezahle mit meiner Girocard.","exampleEn":"I'll pay with my debit card.","example2":"Kann ich hier mit Girocard bezahlen?","example2En":"Can I pay by debit card here?"},{"de":"das Girokonto","en":"checking account","pos":"noun","plural":"die Girokonten","meanings":[{"en":"a current/checking bank account","de":"ein Bankkonto für den laufenden Zahlungsverkehr"}],"rule":"Compound with das Konto; plural die Girokonten (like Konten).","example":"Ich habe ein Girokonto bei der Sparkasse.","exampleEn":"I have a checking account at the savings bank.","example2":"Das Gehalt wird auf mein Girokonto überwiesen.","example2En":"My salary is transferred to my checking account."},{"de":"der Glascontainer","en":"glass recycling bin","pos":"noun","plural":"die Glascontainer","meanings":[{"en":"a public container for recycling glass","de":"ein Behälter zum Sammeln von Altglas"}],"rule":"Compound: Glas + Container; masculine like der Container; plural unchanged.","example":"Ich bringe die Flaschen zum Glascontainer.","exampleEn":"I'm taking the bottles to the glass recycling bin.","example2":"Der Glascontainer steht neben dem Supermarkt.","example2En":"The glass recycling bin is next to the supermarket."},{"de":"glatt","en":"smooth; slippery","pos":"adjective","plural":"","meanings":[{"en":"smooth (surface)","de":"nicht rau"},{"en":"slippery (e.g. ice, road)","de":"rutschig"}],"rule":"Irregular comparison: glatt, glatter, am glattesten (double t stays).","example":"Der Tisch hat eine glatte Oberfläche.","exampleEn":"The table has a smooth surface.","example2":"Vorsicht, die Straße ist glatt!","example2En":"Careful, the road is slippery!"},{"de":"die Glatze","en":"bald head","pos":"noun","plural":"die Glatzen","meanings":[{"en":"a bald head / baldness","de":"ein Kopf ohne Haare"}],"rule":"Common phrase: 'eine Glatze haben' = to be bald.","example":"Mein Opa hat eine Glatze.","exampleEn":"My grandpa is bald.","example2":"Er bekommt langsam eine Glatze.","example2En":"He is slowly going bald."},{"de":"das Glück","en":"luck; happiness","pos":"noun","plural":"","meanings":[{"en":"luck, good fortune","de":"Zufall, der positiv ist"},{"en":"happiness","de":"Gefühl von Freude und Zufriedenheit"}],"rule":"Uncountable noun, no plural. Common phrase: Glück haben (to be lucky).","example":"Wir hatten Glück mit dem Wetter.","exampleEn":"We were lucky with the weather.","example2":"Er lächelt vor Glück.","example2En":"He is smiling with happiness."},{"de":"der Glückspfennig","en":"lucky penny","pos":"noun","plural":"die Glückspfennige","meanings":[{"en":"lucky penny (charm for good luck)","de":"Münze, die Glück bringen soll"}],"rule":"Compound noun: Glück + Pfennig. Often given as a small good-luck gift.","example":"Zum Geburtstag bekam sie einen Glückspfennig.","exampleEn":"She got a lucky penny for her birthday.","example2":"Ein Glückspfennig soll Glück bringen.","example2En":"A lucky penny is supposed to bring good luck."},{"de":"das Gold","en":"gold","pos":"noun","plural":"","meanings":[{"en":"gold (the metal)","de":"gelbes Edelmetall"},{"en":"gold medal","de":"Medaille aus Gold"}],"rule":"Uncountable noun, no plural.","example":"Der Ring ist aus Gold.","exampleEn":"The ring is made of gold.","example2":"Sie hat Gold bei der Olympiade gewonnen.","example2En":"She won gold at the Olympics."},{"de":"googeln","en":"to google","pos":"verb","plural":"","meanings":[{"en":"to search for something on Google/the internet","de":"im Internet mit Google suchen"}],"rule":"Regular weak verb, but as an -eln verb it drops the e in the ich-form: ich google (not googele), du googelst, er/sie googelt; Präteritum googelte; Perfekt hat gegoogelt.","example":"Ich google das Wort schnell.","exampleEn":"I'll quickly google the word.","example2":"Er hat das Restaurant gegoogelt.","example2En":"He googled the restaurant."},{"de":"die Grafik","en":"graphic; diagram","pos":"noun","plural":"die Grafiken","meanings":[{"en":"graphic, illustration","de":"Bild oder Zeichnung"},{"en":"chart, diagram","de":"Darstellung von Daten"}],"rule":"Feminine noun, plural -en.","example":"Die Grafik zeigt die Verkaufszahlen pro Monat.","exampleEn":"The chart shows the sales figures per month.","example2":"Auf der Webseite ist eine bunte Grafik.","example2En":"There is a colorful graphic on the website."},{"de":"der Grafiker / die Grafikerin","en":"graphic designer","pos":"noun","plural":"die Grafiker / die Grafikerinnen","meanings":[{"en":"graphic designer","de":"Person, die beruflich Grafiken gestaltet"}],"rule":"Masculine -er / feminine -erin; plural same pattern.","example":"Er arbeitet als Grafiker bei einer Zeitung.","exampleEn":"He works as a graphic designer at a newspaper.","example2":"Die Grafikerin hat das Logo entworfen.","example2En":"The graphic designer designed the logo."},{"de":"griechisch","en":"Greek","pos":"adjective","plural":"","meanings":[{"en":"Greek (relating to Greece)","de":"aus Griechenland, zu Griechenland gehörend"}],"rule":"Lowercase adjective of nationality; noun form is Griechisch (the language) or der/die Grieche/Griechin (person).","example":"Wir essen heute griechisch.","exampleEn":"We're eating Greek food today.","example2":"Sie spricht ein bisschen Griechisch.","example2En":"She speaks a little Greek."},{"de":"der Grill","en":"grill; barbecue","pos":"noun","plural":"die Grills","meanings":[{"en":"grill, barbecue (the appliance)","de":"Gerät zum Grillen"}],"rule":"Masculine noun, plural -s.","example":"Wir haben einen neuen Grill gekauft.","exampleEn":"We bought a new grill.","example2":"Der Fisch liegt auf dem Grill.","example2En":"The fish is on the grill."},{"de":"die Grillkohle","en":"charcoal (for grilling)","pos":"noun","plural":"","meanings":[{"en":"charcoal used for barbecuing","de":"Kohle zum Grillen"}],"rule":"Uncountable noun, no plural.","example":"Wir brauchen noch Grillkohle.","exampleEn":"We still need charcoal.","example2":"Die Grillkohle ist fast verbrannt.","example2En":"The charcoal has almost burned up."}]},{"id":"a2-09","title":"A2 · G–H (9)","level":"A2","words":[{"de":"der Grillplatz","en":"barbecue area","pos":"noun","plural":"die Grillplätze","meanings":[{"en":"designated area for barbecuing (e.g. in a park)","de":"Ort im Freien zum Grillen"}],"rule":"Compound noun: Grill + Platz; plural with umlaut -plätze.","example":"Im Park gibt es einen öffentlichen Grillplatz.","exampleEn":"There is a public barbecue area in the park.","example2":"Der Grillplatz war am Wochenende voll.","example2En":"The barbecue area was full on the weekend."},{"de":"die Grillsoße","en":"barbecue sauce","pos":"noun","plural":"die Grillsoßen","meanings":[{"en":"sauce served with grilled food","de":"Soße für gegrilltes Fleisch"}],"rule":"Feminine noun, plural -n. Also spelled Grillsauce.","example":"Die Grillsoße schmeckt ein bisschen scharf.","exampleEn":"The barbecue sauce tastes a bit spicy.","example2":"Gib mir bitte die Grillsoße.","example2En":"Please pass me the barbecue sauce."},{"de":"die Grillzange","en":"barbecue tongs","pos":"noun","plural":"die Grillzangen","meanings":[{"en":"tongs used for turning food on the grill","de":"Zange zum Wenden von gegrilltem Essen"}],"rule":"Compound noun: Grill + Zange; plural -n.","example":"Wo ist die Grillzange?","exampleEn":"Where are the barbecue tongs?","example2":"Er wendet die Würstchen mit der Grillzange.","example2En":"He turns the sausages with the tongs."},{"de":"der Grund","en":"reason","pos":"noun","plural":"die Gründe","meanings":[{"en":"reason, cause","de":"Ursache für etwas"},{"en":"ground, bottom (of water, land)","de":"Boden, unterer Teil"}],"rule":"Masculine noun, plural -e with umlaut. Common phrase: aus diesem Grund (for this reason).","example":"Er hat keinen Grund für seine Entscheidung genannt.","exampleEn":"He gave no reason for his decision.","example2":"Das Boot sank auf den Grund des Sees.","example2En":"The boat sank to the bottom of the lake."},{"de":"die Grundschule","en":"primary school","pos":"noun","plural":"die Grundschulen","meanings":[{"en":"primary/elementary school","de":"Schule für Kinder ab 6 Jahren, erste Schule"}],"rule":"Feminine noun, plural -n. In Germany usually grades 1-4.","example":"Meine Tochter geht in die Grundschule.","exampleEn":"My daughter goes to primary school.","example2":"Die Grundschule ist nicht weit von hier.","example2En":"The primary school is not far from here."},{"de":"die Gulaschsuppe","en":"goulash soup","pos":"noun","plural":"die Gulaschsuppen","meanings":[{"en":"a hearty spiced meat-and-vegetable soup (goulash soup)","de":"kräftige Suppe mit Fleisch und Paprika"}],"rule":"Compound noun: Gulasch + Suppe; plural -n.","example":"Ich nehme eine Gulaschsuppe als Vorspeise.","exampleEn":"I'll have a goulash soup as a starter.","example2":"Die Gulaschsuppe war sehr scharf.","example2En":"The goulash soup was very spicy."},{"de":"der Gürtel","en":"belt","pos":"noun","plural":"die Gürtel","meanings":[{"en":"belt (worn around the waist)","de":"Band aus Leder oder Stoff um die Hüfte"}],"rule":"Masculine noun, plural unchanged (der Gürtel - die Gürtel).","example":"Der Gürtel ist zu groß für mich.","exampleEn":"The belt is too big for me.","example2":"Er trägt eine Hose ohne Gürtel.","example2En":"He wears trousers without a belt."},{"de":"das Gymnasium","en":"grammar school; academic secondary school","pos":"noun","plural":"die Gymnasien","meanings":[{"en":"academic secondary school leading to Abitur","de":"weiterführende Schule bis zum Abitur"}],"rule":"Neuter noun, irregular plural: die Gymnasien.","example":"Mein Sohn geht aufs Gymnasium.","exampleEn":"My son goes to grammar school.","example2":"Nach der Grundschule wechselte sie ins Gymnasium.","example2En":"After primary school she moved to grammar school."},{"de":"die Gymnastik","en":"gymnastics; exercise","pos":"noun","plural":"","meanings":[{"en":"gymnastics, physical exercise","de":"körperliche Übungen zur Fitness"}],"rule":"Uncountable noun, no plural.","example":"Jeden Morgen macht sie Gymnastik.","exampleEn":"Every morning she does exercise.","example2":"Der Gymnastikkurs findet im Sportzentrum statt.","example2En":"The gymnastics class takes place at the sports center."},{"de":"die Haarpflege","en":"hair care","pos":"noun","plural":"","meanings":[{"en":"care/products for hair","de":"Pflege der Haare"}],"rule":"Compound: Haar + Pflege; uncountable, no plural.","example":"Ich kaufe Shampoo für die Haarpflege.","exampleEn":"I'm buying shampoo for hair care.","example2":"Gute Haarpflege braucht Zeit.","example2En":"Good hair care takes time."},{"de":"das Halbjahr","en":"half-year; semester","pos":"noun","plural":"die Halbjahre","meanings":[{"en":"half of a year","de":"sechs Monate"},{"en":"school semester/term","de":"Schulhalbjahr"}],"rule":"Neuter compound noun: das Jahr → das Halbjahr.","example":"Im ersten Halbjahr hatte ich gute Noten.","exampleEn":"In the first half-year I had good grades.","example2":"Das Halbjahr endet im Januar.","example2En":"The semester ends in January."},{"de":"der Halt","en":"stop; hold/support","pos":"noun","plural":"die Halte","meanings":[{"en":"a stop (e.g. of a bus/train)","de":"das Anhalten, die Station"},{"en":"support, something to hold on to","de":"Stütze, Sicherheit"}],"rule":"Related to the verb 'halten'; masculine noun, plural rarely used.","example":"Der Zug hat in München einen kurzen Halt.","exampleEn":"The train has a short stop in Munich.","example2":"Sie sucht Halt an der Wand.","example2En":"She looks for support against the wall."},{"de":"das Handgelenk","en":"wrist","pos":"noun","plural":"die Handgelenke","meanings":[{"en":"the joint connecting hand and arm","de":"Gelenk zwischen Hand und Arm"}],"rule":"Compound: die Hand + das Gelenk = neuter.","example":"Mein Handgelenk tut weh.","exampleEn":"My wrist hurts.","example2":"Sie trägt eine Uhr am Handgelenk.","example2En":"She wears a watch on her wrist."},{"de":"handwerklich","en":"manual/craft-related","pos":"adjective","plural":"","meanings":[{"en":"relating to craft or manual skill","de":"das Handwerk betreffend"}],"rule":"From 'das Handwerk' (craft/trade); regular comparison.","example":"Er hat handwerkliches Geschick.","exampleEn":"He has manual/craft skills.","example2":"Die Möbel sind handwerklich gemacht.","example2En":"The furniture is handmade/crafted."},{"de":"das Hauptgericht","en":"main course","pos":"noun","plural":"die Hauptgerichte","meanings":[{"en":"the main dish of a meal","de":"wichtigstes Gericht einer Mahlzeit"}],"rule":"Compound: Haupt- (main) + Gericht (dish); neuter.","example":"Als Hauptgericht nehme ich Fisch.","exampleEn":"For the main course I'll have fish.","example2":"Das Hauptgericht kommt nach der Suppe.","example2En":"The main course comes after the soup."},{"de":"die Hauptschule","en":"secondary modern school","pos":"noun","plural":"die Hauptschulen","meanings":[{"en":"type of German lower secondary school","de":"Schultyp nach der Grundschule"}],"rule":"Feminine compound noun: Haupt- + Schule.","example":"Er geht auf die Hauptschule.","exampleEn":"He attends the Hauptschule (secondary modern school).","example2":"Nach der Hauptschule macht sie eine Ausbildung.","example2En":"After Hauptschule she starts vocational training."},{"de":"der Hausbewohner / die Hausbewohnerin","en":"resident (of a building)","pos":"noun","plural":"die Hausbewohner / die Hausbewohnerinnen","meanings":[{"en":"person living in a house/building","de":"Person, die in einem Haus wohnt"}],"rule":"Compound: Haus + Bewohner(in); masculine/feminine pair.","example":"Alle Hausbewohner trafen sich im Hof.","exampleEn":"All the building's residents met in the courtyard.","example2":"Die Hausbewohnerin hat den Brief bekommen.","example2En":"The resident (female) received the letter."},{"de":"der Hausmeister / die Hausmeisterin","en":"caretaker; janitor","pos":"noun","plural":"die Hausmeister / die Hausmeisterinnen","meanings":[{"en":"person who maintains a building","de":"Person, die ein Haus/Gebäude pflegt"}],"rule":"Compound: Haus + Meister(in); masculine/feminine pair.","example":"Der Hausmeister repariert die Heizung.","exampleEn":"The caretaker is repairing the heating.","example2":"Fragen Sie die Hausmeisterin nach dem Schlüssel.","example2En":"Ask the caretaker (female) for the key."},{"de":"das Hausmittel","en":"home remedy","pos":"noun","plural":"die Hausmittel","meanings":[{"en":"traditional home-based remedy","de":"einfaches Mittel aus dem Haushalt gegen Beschwerden"}],"rule":"Compound: Haus + Mittel; neuter.","example":"Tee mit Honig ist ein gutes Hausmittel gegen Husten.","exampleEn":"Tea with honey is a good home remedy for a cough.","example2":"Meine Oma kennt viele Hausmittel.","example2En":"My grandma knows many home remedies."},{"de":"die Hausordnung","en":"house rules","pos":"noun","plural":"die Hausordnungen","meanings":[{"en":"rules for residents of a building","de":"Regeln für die Bewohner eines Hauses"}],"rule":"Compound: Haus + Ordnung; feminine.","example":"In der Hausordnung steht: keine Musik nach 22 Uhr.","exampleEn":"The house rules say: no music after 10 pm.","example2":"Bitte lesen Sie die Hausordnung.","example2En":"Please read the house rules."},{"de":"die Hausregel","en":"house rule","pos":"noun","plural":"die Hausregeln","meanings":[{"en":"an individual rule of a household","de":"einzelne Regel im Haus/Haushalt"}],"rule":"Compound: Haus + Regel; feminine; often used in plural.","example":"Unsere Hausregel ist: Schuhe draußen ausziehen.","exampleEn":"Our house rule is: take off shoes outside.","example2":"Jede Familie hat eigene Hausregeln.","example2En":"Every family has its own house rules."},{"de":"die Hausreinigung","en":"house cleaning","pos":"noun","plural":"","meanings":[{"en":"cleaning of a house/building","de":"das Reinigen eines Hauses"}],"rule":"Compound: Haus + Reinigung; uncountable, no plural.","example":"Die Hausreinigung findet freitags statt.","exampleEn":"The house cleaning takes place on Fridays.","example2":"Wir bezahlen für die Hausreinigung extra.","example2En":"We pay extra for the house cleaning."},{"de":"die Hausverwaltung","en":"property management (company)","pos":"noun","plural":"die Hausverwaltungen","meanings":[{"en":"company/office managing a building","de":"Firma, die ein Haus verwaltet"}],"rule":"Compound: Haus + Verwaltung; feminine.","example":"Rufen Sie die Hausverwaltung an, wenn die Heizung kaputt ist.","exampleEn":"Call the property management if the heating is broken.","example2":"Die Hausverwaltung hat einen neuen Mieter gefunden.","example2En":"The property management found a new tenant."},{"de":"die Haut","en":"skin","pos":"noun","plural":"die Häute","meanings":[{"en":"the skin of a person/animal","de":"äußere Hülle des Körpers"}],"rule":"Feminine noun; irregular plural with umlaut: Haut → Häute.","example":"Nach dem Sonnenbad ist meine Haut rot.","exampleEn":"After sunbathing my skin is red.","example2":"Creme schützt die Haut.","example2En":"Cream protects the skin."},{"de":"die Hautpflege","en":"skin care","pos":"noun","plural":"","meanings":[{"en":"care/products for the skin","de":"Pflege der Haut"}],"rule":"Compound: Haut + Pflege; uncountable.","example":"Sie macht jeden Tag Hautpflege.","exampleEn":"She does skin care every day.","example2":"Hautpflege ist im Winter wichtig.","example2En":"Skin care is important in winter."},{"de":"die Hektik","en":"hectic rush; hustle","pos":"noun","plural":"","meanings":[{"en":"hurried, stressful activity","de":"große Eile und Unruhe"}],"rule":"Feminine, uncountable; often with 'in der Hektik' (in the rush).","example":"In der Hektik habe ich meinen Schlüssel vergessen.","exampleEn":"In the rush I forgot my key.","example2":"Morgens herrscht bei uns immer Hektik.","example2En":"There's always a hectic rush at our place in the morning."},{"de":"herausfinden","en":"to find out","pos":"verb","plural":"","meanings":[{"en":"to discover/learn information","de":"etwas entdecken, in Erfahrung bringen"}],"rule":"Trennbar: findet ... heraus, fand heraus, hat herausgefunden; often + Objekt/dass-Satz.","example":"Ich möchte herausfinden, wann der Bus fährt.","exampleEn":"I want to find out when the bus leaves.","example2":"Wir haben die Wahrheit herausgefunden.","example2En":"We found out the truth."},{"de":"heraussuchen","en":"to pick out, select","pos":"verb","plural":"","meanings":[{"en":"to search out / select something from a group","de":"etwas auswählen, finden"}],"rule":"trennbar: sucht ... heraus, suchte ... heraus, hat herausgesucht","example":"Ich suche mir ein schönes Kleid heraus.","exampleEn":"I'm picking out a nice dress.","example2":"Kannst du mir die passenden Fotos heraussuchen?","example2En":"Can you pick out the matching photos for me?"},{"de":"herein","en":"in, come in","pos":"adverb","plural":"","meanings":[{"en":"movement into a place (toward the speaker)","de":"nach drinnen (zum Sprecher hin)"}],"rule":"Oft als Ausruf: \"Herein!\" (= Come in!); wird auch in trennbaren Verben wie hereinkommen benutzt.","example":"Herein, die Tür ist offen!","exampleEn":"Come in, the door is open!","example2":"Der kalte Wind weht durchs Fenster herein.","example2En":"Cold wind is blowing in through the window."},{"de":"herrlich","en":"wonderful, splendid","pos":"adjective","plural":"","meanings":[{"en":"very beautiful or pleasant","de":"sehr schön, wunderbar"}],"rule":"Regelmäßige Steigerung: herrlich, herrlicher, am herrlichsten.","example":"Das Wetter ist heute herrlich.","exampleEn":"The weather is wonderful today.","example2":"Wir hatten einen herrlichen Urlaub am Meer.","example2En":"We had a wonderful vacation by the sea."},{"de":"herum","en":"around","pos":"adverb","plural":"","meanings":[{"en":"in a circle or around something","de":"rund um etwas herum"}],"rule":"Oft mit um...herum: um den Tisch herum; auch in trennbaren Verben wie herumlaufen.","example":"Die Kinder sitzen um den Tisch herum.","exampleEn":"The children are sitting around the table.","example2":"Er läuft den ganzen Tag im Park herum.","example2En":"He wanders around the park all day."},{"de":"herunterladen","en":"to download","pos":"verb","plural":"","meanings":[{"en":"to download a file from the internet","de":"eine Datei aus dem Internet laden"}],"rule":"trennbar: lädt ... herunter, lud ... herunter, hat heruntergeladen","example":"Ich lade die App auf mein Handy herunter.","exampleEn":"I'm downloading the app onto my phone.","example2":"Hast du das Dokument schon heruntergeladen?","example2En":"Have you already downloaded the document?"},{"de":"herzlich","en":"warm, cordial","pos":"adjective","plural":"","meanings":[{"en":"warm and sincere in feeling","de":"warmherzig, freundlich gemeint"}],"rule":"Regelmäßige Steigerung: herzlich, herzlicher, am herzlichsten. Oft in Grußformeln: herzliche Grüße, herzlichen Glückwunsch.","example":"Herzlichen Glückwunsch zum Geburtstag!","exampleEn":"Happy birthday! (lit. warm congratulations)","example2":"Wir haben die Gäste herzlich begrüßt.","example2En":"We warmly welcomed the guests."},{"de":"hiermit","en":"hereby","pos":"adverb","plural":"","meanings":[{"en":"by this means, with this (formal)","de":"mit diesem, dadurch (formell)"}],"rule":"Typisch in offiziellen Briefen und Erklärungen; formeller Stil.","example":"Hiermit bestätige ich den Termin.","exampleEn":"I hereby confirm the appointment.","example2":"Hiermit kündige ich meinen Vertrag.","example2En":"I hereby cancel my contract."},{"de":"hierzu","en":"for this, regarding this","pos":"adverb","plural":"","meanings":[{"en":"concerning this matter / for this purpose","de":"zu diesem Thema, für diesen Zweck"}],"rule":"Pronominaladverb aus hier + zu; steht oft am Satzanfang, verweist auf vorher Genanntes.","example":"Hierzu habe ich noch eine Frage.","exampleEn":"I still have a question about this.","example2":"Hierzu brauchen wir mehr Informationen.","example2En":"We need more information for this."},{"de":"hin","en":"there, away (movement from speaker)","pos":"adverb","plural":"","meanings":[{"en":"movement away from the speaker toward a place","de":"Richtung von hier weg"}],"rule":"Gegensatz zu her; oft in trennbaren Verben wie hinfahren, hingehen.","example":"Wo gehst du hin?","exampleEn":"Where are you going?","example2":"Zum Bahnhof will ich auch hin.","example2En":"I want to go to the train station, too."},{"de":"hinfahren","en":"to go/drive there","pos":"verb","plural":"","meanings":[{"en":"to travel (drive/go) to a place","de":"an einen Ort fahren"}],"rule":"trennbar: fährt ... hin, fuhr ... hin, ist hingefahren","example":"Wir fahren mit dem Auto hin.","exampleEn":"We're driving there by car.","example2":"Wann fahrt ihr zur Party hin?","example2En":"When are you going to the party?"},{"de":"die Hinfahrt","en":"the outward journey","pos":"noun","plural":"die Hinfahrten","meanings":[{"en":"the trip to a destination (as opposed to the return trip)","de":"die Fahrt zu einem Ort (Gegenteil von Rückfahrt)"}],"rule":"Zusammensetzung aus hin + Fahrt; Gegenteil: die Rückfahrt.","example":"Die Hinfahrt hat drei Stunden gedauert.","exampleEn":"The outward journey took three hours.","example2":"Auf der Hinfahrt haben wir Musik gehört.","example2En":"On the way there, we listened to music."},{"de":"hinfallen","en":"to fall down","pos":"verb","plural":"","meanings":[{"en":"to fall to the ground","de":"zu Boden fallen"}],"rule":"trennbar: fällt ... hin, fiel ... hin, ist hingefallen","example":"Das Kind ist auf dem Spielplatz hingefallen.","exampleEn":"The child fell down on the playground.","example2":"Pass auf, dass du nicht hinfällst!","example2En":"Watch out that you don't fall down!"},{"de":"hingehen","en":"to go there","pos":"verb","plural":"","meanings":[{"en":"to go to a place","de":"an einen Ort gehen"}],"rule":"trennbar: geht ... hin, ging ... hin, ist hingegangen","example":"Gehst du heute Abend zur Feier hin?","exampleEn":"Are you going to the party tonight?","example2":"Wir sind gestern zusammen hingegangen.","example2En":"We went there together yesterday."},{"de":"hoch","en":"high, tall","pos":"adjective","plural":"","meanings":[{"en":"having great height","de":"eine große Höhe habend"}],"rule":"Unregelmäßige Steigerung: hoch, höher, am höchsten. Vor Nomen wird aus hoch: hoher/hohe/hohes.","example":"Der Turm ist sehr hoch.","exampleEn":"The tower is very high.","example2":"Das ist ein hoher Berg.","example2En":"That is a high mountain."},{"de":"hochladen","en":"to upload","pos":"verb","plural":"","meanings":[{"en":"to upload a file to the internet","de":"eine Datei ins Internet laden"}],"rule":"trennbar: lädt ... hoch, lud ... hoch, hat hochgeladen","example":"Ich lade die Fotos auf die Webseite hoch.","exampleEn":"I'm uploading the photos to the website.","example2":"Hast du das Video schon hochgeladen?","example2En":"Have you already uploaded the video?"},{"de":"hochlegen","en":"to put up, elevate","pos":"verb","plural":"","meanings":[{"en":"to place something higher up / raise (e.g. one's legs)","de":"etwas nach oben legen, höher legen"}],"rule":"trennbar: legt ... hoch, legte ... hoch, hat hochgelegt","example":"Leg die Beine hoch, das hilft gegen die Schmerzen.","exampleEn":"Put your legs up, that helps with the pain.","example2":"Sie hat das Kissen auf den Stuhl hochgelegt.","example2En":"She put the pillow up on the chair."},{"de":"der Hof","en":"yard, courtyard; farm","pos":"noun","plural":"die Höfe","meanings":[{"en":"an enclosed outdoor area by a building","de":"ein umschlossener Platz vor/hinter einem Haus"},{"en":"a farm","de":"ein landwirtschaftlicher Betrieb"}],"rule":"Plural mit Umlaut: der Hof, die Höfe.","example":"Die Kinder spielen im Hof.","exampleEn":"The children are playing in the courtyard.","example2":"Meine Großeltern haben einen Hof auf dem Land.","example2En":"My grandparents have a farm in the countryside."},{"de":"hoffen","en":"to hope","pos":"verb","plural":"","meanings":[{"en":"to wish that something will happen","de":"wünschen, dass etwas passiert"}],"rule":"Regelmäßig: hofft, hoffte, hat gehofft; oft mit \"auf + Akkusativ\" oder \"dass\"-Satz.","example":"Ich hoffe auf gutes Wetter am Wochenende.","exampleEn":"I'm hoping for good weather this weekend.","example2":"Wir hoffen, dass alles gut geht.","example2En":"We hope that everything goes well."},{"de":"hoffentlich","en":"hopefully","pos":"adverb","plural":"","meanings":[{"en":"hopefully / I hope that","de":"drückt eine Hoffnung aus"}],"rule":"Satzadverb, steht meist am Satzanfang oder nach dem Verb; bezieht sich immer auf den ganzen Satz.","example":"Hoffentlich scheint morgen die Sonne.","exampleEn":"Hopefully the sun will shine tomorrow.","example2":"Das Taxi kommt hoffentlich pünktlich.","example2En":"Hopefully the taxi will arrive on time."},{"de":"höflich","en":"polite","pos":"adjective","plural":"","meanings":[{"en":"polite, courteous","de":"freundlich und respektvoll"}],"rule":"Regelmäßige Steigerung: höflich, höflicher, am höflichsten.","example":"Der Verkäufer war sehr höflich zu uns.","exampleEn":"The salesman was very polite to us.","example2":"Bitte antworte höflich auf die E-Mail.","example2En":"Please reply politely to the e-mail."},{"de":"holen","en":"to fetch, get","pos":"verb","plural":"","meanings":[{"en":"to go and get / fetch something","de":"etwas herbeibringen"}],"rule":"regelmäßig: holt, holte, hat geholt.","example":"Kannst du bitte das Brot vom Bäcker holen?","exampleEn":"Can you please get the bread from the bakery?","example2":"Ich hole schnell meine Jacke.","example2En":"I'll quickly get my jacket."},{"de":"das Holz","en":"wood","pos":"noun","plural":"die Hölzer","meanings":[{"en":"wood (material)","de":"Material aus Bäumen"}],"rule":"Meist unzählbar; Plural 'die Hölzer' nur für verschiedene Holzarten/-stücke.","example":"Der Tisch ist aus Holz.","exampleEn":"The table is made of wood.","example2":"Wir sammeln Holz für das Feuer.","example2En":"We're collecting wood for the fire."},{"de":"hübsch","en":"pretty, nice-looking","pos":"adjective","plural":"","meanings":[{"en":"pretty, attractive","de":"schön anzusehen"}],"rule":"Regelmäßige Steigerung: hübsch, hübscher, am hübschesten.","example":"Sie trägt ein hübsches Kleid.","exampleEn":"She is wearing a pretty dress.","example2":"Das ist eine hübsche kleine Wohnung.","example2En":"That's a nice little apartment."}]},{"id":"a2-10","title":"A2 · H–K (10)","level":"A2","words":[{"de":"das Hufeisen","en":"horseshoe","pos":"noun","plural":"die Hufeisen","meanings":[{"en":"horseshoe","de":"Eisen unter dem Pferdehuf"}],"rule":"Neutrum; Plural ohne Endungsänderung: die Hufeisen.","example":"Das Pferd bekommt ein neues Hufeisen.","exampleEn":"The horse is getting a new horseshoe.","example2":"Ein Hufeisen soll Glück bringen.","example2En":"A horseshoe is said to bring luck."},{"de":"die IBAN","en":"IBAN (bank account number)","pos":"noun","plural":"die IBANs","meanings":[{"en":"international bank account number","de":"internationale Kontonummer"}],"rule":"Abkürzung für 'International Bank Account Number'; feminines Genus wegen 'die Nummer'.","example":"Ich brauche Ihre IBAN für die Überweisung.","exampleEn":"I need your IBAN for the transfer.","example2":"Die IBAN steht auf der Bankkarte.","example2En":"The IBAN is printed on the bank card."},{"de":"indirekt","en":"indirect","pos":"adjective","plural":"","meanings":[{"en":"indirect, not direct","de":"nicht direkt"}],"rule":"Regelmäßige Steigerung: indirekt, indirekter, am indirektesten; Gegenteil von direkt.","example":"Das war eine indirekte Frage.","exampleEn":"That was an indirect question.","example2":"Wir sind auf einem indirekten Weg nach Hause gefahren.","example2En":"We drove home by an indirect route."},{"de":"der Informatiker / die Informatikerin","en":"computer scientist, IT specialist","pos":"noun","plural":"die Informatiker / die Informatikerinnen","meanings":[{"en":"computer scientist / IT professional","de":"Fachperson für Informatik"}],"rule":"Berufsbezeichnung; weibliche Form mit -in.","example":"Mein Bruder ist Informatiker bei einer großen Firma.","exampleEn":"My brother is a computer scientist at a big company.","example2":"Die Informatikerin repariert unseren Computer.","example2En":"The IT specialist is fixing our computer."},{"de":"informieren","en":"to inform","pos":"verb","plural":"","meanings":[{"en":"to inform someone (about something)","de":"jemandem Informationen geben"},{"en":"to inform oneself, find out","de":"sich Informationen holen"}],"rule":"regelmäßig: informiert, informierte, hat informiert; oft reflexiv 'sich informieren über + Akkusativ'.","example":"Der Lehrer informiert die Eltern über den Ausflug.","exampleEn":"The teacher informs the parents about the trip.","example2":"Ich möchte mich über den Kurs informieren.","example2En":"I would like to find out about the course."},{"de":"die Innenstadt","en":"city centre, downtown","pos":"noun","plural":"die Innenstädte","meanings":[{"en":"city centre, downtown area","de":"Zentrum einer Stadt"}],"rule":"Zusammensetzung aus 'innen' + 'Stadt'; Plural mit Umlaut: die Innenstädte.","example":"Wir fahren mit dem Bus in die Innenstadt.","exampleEn":"We are taking the bus to the city centre.","example2":"In der Innenstadt gibt es viele Geschäfte.","example2En":"There are many shops in the city centre."},{"de":"die Integration","en":"integration","pos":"noun","plural":"","meanings":[{"en":"integration (into society)","de":"Eingliederung in eine Gemeinschaft"}],"rule":"Unzählbares Abstraktum, kein Plural üblich.","example":"Die Sprache ist wichtig für die Integration.","exampleEn":"Language is important for integration.","example2":"Der Verein unterstützt die Integration von Familien.","example2En":"The association supports the integration of families."},{"de":"der Integrationskurs","en":"integration course","pos":"noun","plural":"die Integrationskurse","meanings":[{"en":"government-run integration course (language + civics)","de":"Kurs zum Deutschlernen und Kennenlernen der Gesellschaft"}],"rule":"Zusammensetzung Integration + Kurs; maskulin wie 'der Kurs'.","example":"Sie besucht gerade einen Integrationskurs.","exampleEn":"She is currently attending an integration course.","example2":"Der Integrationskurs dauert mehrere Monate.","example2En":"The integration course lasts several months."},{"de":"der Integrationsverein","en":"integration association","pos":"noun","plural":"die Integrationsvereine","meanings":[{"en":"association/club that supports integration","de":"Verein, der Integration fördert"}],"rule":"Zusammensetzung Integration + Verein; maskulin wie 'der Verein'.","example":"Der Integrationsverein organisiert ein Fest für alle Familien.","exampleEn":"The integration association is organizing a festival for all families.","example2":"Ich helfe ehrenamtlich im Integrationsverein.","example2En":"I volunteer at the integration association."},{"de":"interessieren","en":"to interest","pos":"verb","plural":"","meanings":[{"en":"to interest someone","de":"jemandes Interesse wecken"},{"en":"to be interested in something (sich interessieren für)","de":"Interesse an etwas haben"}],"rule":"regelmäßig: interessiert, interessierte, hat interessiert; reflexiv 'sich interessieren für + Akkusativ'.","example":"Musik interessiert mich sehr.","exampleEn":"Music interests me a lot.","example2":"Ich interessiere mich für Sport.","example2En":"I'm interested in sport."},{"de":"international","en":"international","pos":"adjective","plural":"","meanings":[{"en":"international","de":"zwischen mehreren Ländern"}],"rule":"Regelmäßige Steigerung, wird aber selten gesteigert (eher absolut gebraucht).","example":"Er arbeitet für eine internationale Firma.","exampleEn":"He works for an international company.","example2":"Das Festival ist international bekannt.","example2En":"The festival is internationally known."},{"de":"das Internet","en":"the internet","pos":"noun","plural":"","meanings":[{"en":"the internet","de":"weltweites Computernetzwerk"}],"rule":"Unzählbar, meist mit Artikel 'das Internet', oft mit Präposition 'im Internet'.","example":"Ich suche Informationen im Internet.","exampleEn":"I'm looking for information on the internet.","example2":"Ohne Internet kann ich nicht arbeiten.","example2En":"I can't work without the internet."},{"de":"der Internetzugang","en":"internet access","pos":"noun","plural":"die Internetzugänge","meanings":[{"en":"internet access / connection","de":"Möglichkeit, das Internet zu nutzen"}],"rule":"Zusammensetzung Internet + Zugang; maskulin wie 'der Zugang'.","example":"Das Hotel bietet kostenlosen Internetzugang.","exampleEn":"The hotel offers free internet access.","example2":"Wir haben zu Hause keinen schnellen Internetzugang.","example2En":"We don't have fast internet access at home."},{"de":"der Interviewpartner / die Interviewpartnerin","en":"interviewee, interview partner","pos":"noun","plural":"die Interviewpartner / die Interviewpartnerinnen","meanings":[{"en":"the person being interviewed (interviewee)","de":"Person, die in einem Interview befragt wird"}],"rule":"Compound noun: Interview + Partner/in; feminine form adds -in. Refers to the person being interviewed, not the interviewer (der Interviewer).","example":"Mein Interviewpartner hat viele interessante Antworten gegeben.","exampleEn":"My interview partner gave many interesting answers.","example2":"Die Journalistin sucht einen neuen Interviewpartner.","example2En":"The journalist is looking for a new interviewee."},{"de":"irgendwo","en":"somewhere","pos":"adverb","plural":"","meanings":[{"en":"at some unspecified place","de":"an einem unbestimmten Ort"}],"rule":"Indefinite place adverb; formed from irgend- + wo. Compare irgendwohin (direction).","example":"Ich habe meinen Schlüssel irgendwo verloren.","exampleEn":"I lost my key somewhere.","example2":"Er wartet bestimmt irgendwo auf uns.","example2En":"He's definitely waiting for us somewhere."},{"de":"jährlich","en":"yearly, annual","pos":"adjective","plural":"","meanings":[{"en":"happening once a year","de":"einmal im Jahr"}],"rule":"Regular adjective/adverb; no irregular comparison. Related to das Jahr.","example":"Wir fahren jährlich in den Urlaub.","exampleEn":"We go on vacation every year.","example2":"Die jährliche Miete steigt um zwei Prozent.","example2En":"The annual rent is rising by two percent."},{"de":"jederzeit","en":"anytime, at any time","pos":"adverb","plural":"","meanings":[{"en":"at any time, whenever you like","de":"immer, zu jeder Zeit"}],"rule":"Fixed compound of jeder + Zeit; no inflection.","example":"Sie können mich jederzeit anrufen.","exampleEn":"You can call me anytime.","example2":"Der Vertrag kann jederzeit gekündigt werden.","example2En":"The contract can be cancelled at any time."},{"de":"jemand","en":"someone, somebody","pos":"pronoun","plural":"","meanings":[{"en":"an unspecified person","de":"eine unbestimmte Person"}],"rule":"Indefinite pronoun; declines: jemand, jemanden (Akk.), jemandem (Dat.); opposite niemand.","example":"Hat jemand meinen Regenschirm gesehen?","exampleEn":"Has anyone seen my umbrella?","example2":"Ich möchte jemandem danken.","example2En":"I would like to thank someone."},{"de":"jeweils","en":"each time, respectively","pos":"adverb","plural":"","meanings":[{"en":"in each case, each time","de":"in jedem einzelnen Fall"}],"rule":"Often used with numbers/quantities, e.g. 'jeweils zwei Stück' = two pieces each.","example":"Die Kurse finden jeweils montags statt.","exampleEn":"The courses take place each Monday.","example2":"Die Teilnehmer bekommen jeweils ein Buch.","example2En":"The participants each get one book."},{"de":"jobben","en":"to work a (part-time/casual) job","pos":"verb","plural":"","meanings":[{"en":"to do casual or part-time work, especially as a student","de":"eine Nebentätigkeit oder einen Ferienjob ausüben"}],"rule":"Regular weak verb: jobbt, jobbte, hat gejobbt. From English 'job'.","example":"Im Sommer jobbe ich in einem Café.","exampleEn":"In summer I work a part-time job in a café.","example2":"Er hat als Student oft gejobbt.","example2En":"As a student he often worked casual jobs."},{"de":"der Junge","en":"boy","pos":"noun","plural":"die Jungen","meanings":[{"en":"a male child or youth","de":"männliches Kind oder männlicher Jugendlicher"}],"rule":"Weak masculine noun: den/dem/des Jungen in singular (except Nom.).","example":"Der kleine Junge spielt Fußball.","exampleEn":"The little boy is playing football.","example2":"Zwei Jungen warten vor der Schule.","example2En":"Two boys are waiting in front of the school."},{"de":"der Kabelsalat","en":"tangle of cables","pos":"noun","plural":"","meanings":[{"en":"a messy tangle of cables/wires","de":"ein Durcheinander von Kabeln"}],"rule":"Compound noun Kabel + Salat (informal); usually used only in singular.","example":"Hinter dem Fernseher ist ein richtiger Kabelsalat.","exampleEn":"Behind the TV there's a real tangle of cables.","example2":"Ich möchte den Kabelsalat endlich aufräumen.","example2En":"I finally want to sort out the cable mess."},{"de":"die Kamera","en":"camera","pos":"noun","plural":"die Kameras","meanings":[{"en":"a device for taking photos or video","de":"Gerät zum Fotografieren oder Filmen"}],"rule":"Feminine noun, plural in -s (foreign origin).","example":"Ich habe eine neue Kamera gekauft.","exampleEn":"I bought a new camera.","example2":"Die Kamera im Laden hat alles aufgenommen.","example2En":"The camera in the shop recorded everything."},{"de":"kariert","en":"checkered, checked","pos":"adjective","plural":"","meanings":[{"en":"having a check/plaid pattern","de":"mit einem Muster aus Karos"}],"rule":"Regular adjective, from das Karo (square); no irregular comparison.","example":"Er trägt ein kariertes Hemd.","exampleEn":"He is wearing a checkered shirt.","example2":"Ich schreibe lieber auf kariertem Papier.","example2En":"I prefer to write on squared paper."},{"de":"die Kategorie","en":"category","pos":"noun","plural":"die Kategorien","meanings":[{"en":"a group of things sharing characteristics","de":"eine Gruppe von ähnlichen Dingen"}],"rule":"Feminine noun; plural -n. Stress on the last syllable: Kategorie.","example":"In welche Kategorie passt dieses Produkt?","exampleEn":"Which category does this product fit into?","example2":"Es gibt verschiedene Kategorien im Wettbewerb.","example2En":"There are different categories in the competition."},{"de":"kaufmännisch","en":"commercial, business-related","pos":"adjective","plural":"","meanings":[{"en":"relating to trade, business or commerce","de":"den Handel oder die Wirtschaft betreffend"}],"rule":"Derived from der Kaufmann; often in 'kaufmännische Ausbildung'.","example":"Sie macht eine kaufmännische Ausbildung.","exampleEn":"She is doing a commercial apprenticeship.","example2":"Er arbeitet im kaufmännischen Bereich der Firma.","example2En":"He works in the commercial department of the company."},{"de":"der Kellerzugang","en":"access to the basement","pos":"noun","plural":"die Kellerzugänge","meanings":[{"en":"entrance or access to a cellar/basement","de":"Zugang oder Eingang zum Keller"}],"rule":"Compound noun Keller + Zugang; plural with umlaut like der Zugang → die Zugänge.","example":"Der Kellerzugang ist hinter dem Haus.","exampleEn":"The basement access is behind the house.","example2":"Bitte halten Sie den Kellerzugang frei.","example2En":"Please keep the basement access clear."},{"de":"die Kenntnisse","en":"knowledge, skills","pos":"noun","plural":"","meanings":[{"en":"knowledge or skills in a field","de":"Wissen oder Fähigkeiten in einem Bereich"}],"rule":"Plural-only in this meaning (singular die Kenntnis has a narrower sense: 'a piece of knowledge/awareness'); often in compounds like 'Deutschkenntnisse'.","example":"Für den Job braucht man gute Englischkenntnisse.","exampleEn":"For the job you need good English skills.","example2":"Sie hat gute Kenntnisse in der Buchhaltung.","example2En":"She has good knowledge of bookkeeping."},{"de":"das Kennwort","en":"password","pos":"noun","plural":"die Kennwörter","meanings":[{"en":"a secret word used to access something","de":"geheimes Wort zum Zugriff auf etwas"}],"rule":"Compound noun Kenn- + Wort; plural with umlaut like das Wort → die Wörter. Synonym: das Passwort.","example":"Ich habe mein Kennwort vergessen.","exampleEn":"I forgot my password.","example2":"Bitte geben Sie Ihr Kennwort ein.","example2En":"Please enter your password."},{"de":"kennzeichnen","en":"to mark, to label","pos":"verb","plural":"","meanings":[{"en":"to mark or label something clearly","de":"etwas deutlich markieren"},{"en":"to characterize, to be typical of","de":"typisch sein für etwas"}],"rule":"Regular weak verb, inseparable (kenn- is not separable here): kennzeichnet, kennzeichnete, hat gekennzeichnet.","example":"Bitte kennzeichnen Sie die gefährlichen Waren.","exampleEn":"Please mark the dangerous goods.","example2":"Geduld kennzeichnet eine gute Lehrerin.","example2En":"Patience characterizes a good teacher."},{"de":"die Kerze","en":"candle","pos":"noun","plural":"die Kerzen","meanings":[{"en":"candle","de":"Wachsstab mit Docht, der brennt"}],"rule":"Feminines Nomen; Plural auf -n.","example":"Sie zündet eine Kerze für den Geburtstagskuchen an.","exampleEn":"She lights a candle for the birthday cake.","example2":"Bei Stromausfall benutzen wir Kerzen.","example2En":"During a power outage we use candles."},{"de":"das Kindergeld","en":"child benefit","pos":"noun","plural":"","meanings":[{"en":"state payment to parents for children","de":"staatliche Geldleistung für Eltern mit Kindern"}],"rule":"Neutrum; nur Singular (unzählbar), kein Plural.","example":"Die Familie bekommt jeden Monat Kindergeld.","exampleEn":"The family receives child benefit every month.","example2":"Man muss das Kindergeld beim Amt beantragen.","example2En":"You have to apply for child benefit at the office."},{"de":"die Kindertagesstätte (Kita)","en":"daycare center","pos":"noun","plural":"die Kindertagesstätten","meanings":[{"en":"daycare / nursery for young children","de":"Einrichtung, die kleine Kinder tagsüber betreut"}],"rule":"Femininum; Abkürzung 'die Kita' ist im Alltag üblicher.","example":"Unser Sohn geht jeden Tag in die Kita.","exampleEn":"Our son goes to daycare every day.","example2":"Die Kindertagesstätte öffnet um sieben Uhr.","example2En":"The daycare center opens at seven o'clock."},{"de":"der Kinderwagen","en":"baby stroller","pos":"noun","plural":"die Kinderwagen","meanings":[{"en":"pram / stroller for a baby","de":"Wagen, in dem man ein Baby schiebt"}],"rule":"Maskulinum; Plural bleibt unverändert (wie Singular).","example":"Sie schiebt den Kinderwagen durch den Park.","exampleEn":"She pushes the stroller through the park.","example2":"Der Kinderwagen passt nicht in den Aufzug.","example2En":"The stroller doesn't fit in the elevator."},{"de":"die Kinokarte","en":"movie ticket","pos":"noun","plural":"die Kinokarten","meanings":[{"en":"ticket for the cinema","de":"Eintrittskarte für das Kino"}],"rule":"Femininum; Zusammensetzung aus Kino + Karte.","example":"Wir kaufen zwei Kinokarten für den neuen Film.","exampleEn":"We buy two movie tickets for the new film.","example2":"Die Kinokarte kostet zehn Euro.","example2En":"The movie ticket costs ten euros."},{"de":"klagen","en":"to complain; to sue","pos":"verb","plural":"","meanings":[{"en":"to complain","de":"sich beschweren"},{"en":"to sue / file a lawsuit","de":"vor Gericht gehen"}],"rule":"regelmäßig: klagt, klagte, hat geklagt; 'klagen über + Akk.' = sich beschweren.","example":"Er klagt oft über Kopfschmerzen.","exampleEn":"He often complains about headaches.","example2":"Die Firma will gegen den Nachbarn klagen.","example2En":"The company wants to sue the neighbor."},{"de":"die Klasse","en":"class; grade","pos":"noun","plural":"die Klassen","meanings":[{"en":"school class / grade","de":"Gruppe von Schülern oder Schulstufe"},{"en":"quality class / category","de":"Kategorie, z. B. bei Qualität"}],"rule":"Femininum; Plural -n.","example":"Meine Tochter ist in der dritten Klasse.","exampleEn":"My daughter is in third grade.","example2":"Das Hotel gehört zur höchsten Klasse.","example2En":"The hotel belongs to the highest class."},{"de":"die Klassenarbeit","en":"school test / exam","pos":"noun","plural":"die Klassenarbeiten","meanings":[{"en":"written test in school","de":"schriftliche Prüfung in der Schule"}],"rule":"Femininum; zusammengesetzt aus Klasse + Arbeit.","example":"Morgen schreiben wir eine Klassenarbeit in Mathe.","exampleEn":"Tomorrow we're writing a test in math.","example2":"Er hat die Klassenarbeit gut bestanden.","example2En":"He passed the test well."},{"de":"der Klassenlehrer / die Klassenlehrerin","en":"class teacher (male) / class teacher (female)","pos":"noun","plural":"die Klassenlehrer / die Klassenlehrerinnen","meanings":[{"en":"teacher responsible for a class","de":"Lehrer(in), der/die für eine Klasse verantwortlich ist"}],"rule":"Maskulines 'der Klassenlehrer' bleibt im Plural unverändert (die Klassenlehrer); feminines 'die Klassenlehrerin' bildet den Plural mit -innen (die Klassenlehrerinnen).","example":"Unser Klassenlehrer heißt Herr Schmidt.","exampleEn":"Our class teacher is Mr. Schmidt.","example2":"Die Klassenlehrerin spricht heute mit den Eltern.","example2En":"The class teacher is talking with the parents today."},{"de":"das Kleeblatt","en":"clover leaf","pos":"noun","plural":"die Kleeblätter","meanings":[{"en":"leaf of the clover plant","de":"Blatt der Kleepflanze"}],"rule":"Neutrum; Umlaut im Plural (Blatt → Blätter).","example":"Ein vierblättriges Kleeblatt bringt Glück.","exampleEn":"A four-leaf clover brings luck.","example2":"Im Garten wachsen viele Kleeblätter.","example2En":"Many clover leaves grow in the garden."},{"de":"das Kleingeld","en":"small change (coins)","pos":"noun","plural":"","meanings":[{"en":"coins / small change","de":"Münzen, kleine Geldbeträge"}],"rule":"Neutrum; unzählbar, kein Plural.","example":"Hast du Kleingeld für den Parkautomaten?","exampleEn":"Do you have small change for the parking meter?","example2":"Ich sammle mein Kleingeld in einer Dose.","example2En":"I collect my small change in a tin."},{"de":"die Kleinmöbel (Pl.)","en":"small furniture (items)","pos":"noun","plural":"(Plural)","meanings":[{"en":"small pieces of furniture","de":"kleine Möbelstücke"}],"rule":"Nur im Plural gebräuchlich; kein Singular üblich.","example":"Im Geschäft gibt es viele Kleinmöbel für die Küche.","exampleEn":"The store has a lot of small furniture for the kitchen.","example2":"Wir brauchen noch ein paar Kleinmöbel für das Bad.","example2En":"We still need some small furniture pieces for the bathroom."},{"de":"klicken","en":"to click","pos":"verb","plural":"","meanings":[{"en":"to click (mouse/button)","de":"eine Taste oder Maus betätigen"}],"rule":"regelmäßig: klickt, klickte, hat geklickt; oft mit 'auf + Akk.'","example":"Klicken Sie auf den Button, um fortzufahren.","exampleEn":"Click the button to continue.","example2":"Er klickte versehentlich auf den falschen Link.","example2En":"He accidentally clicked the wrong link."},{"de":"knackig","en":"crisp, crunchy","pos":"adjective","plural":"","meanings":[{"en":"crisp / crunchy (food)","de":"frisch und fest, knackt beim Essen"}],"rule":"regelmäßige Steigerung: knackig, knackiger, am knackigsten.","example":"Der Apfel ist schön knackig.","exampleEn":"The apple is nice and crisp.","example2":"Ich mag knackiges Gemüse im Salat.","example2En":"I like crunchy vegetables in the salad."},{"de":"die Kneipe","en":"pub, bar","pos":"noun","plural":"die Kneipen","meanings":[{"en":"pub / small bar","de":"gemütliches Lokal, in dem man Bier trinkt"}],"rule":"Femininum; Plural -n.","example":"Wir treffen uns heute Abend in der Kneipe.","exampleEn":"We're meeting at the pub tonight.","example2":"Die Kneipe um die Ecke hat gutes Bier.","example2En":"The pub around the corner has good beer."},{"de":"der Knöchel","en":"ankle","pos":"noun","plural":"die Knöchel","meanings":[{"en":"ankle","de":"Gelenk zwischen Bein und Fuß"}],"rule":"Maskulinum; Plural bleibt unverändert.","example":"Sie hat sich beim Laufen den Knöchel verletzt.","exampleEn":"She injured her ankle while running.","example2":"Der Knöchel ist geschwollen.","example2En":"The ankle is swollen."},{"de":"der Kommentar","en":"comment","pos":"noun","plural":"die Kommentare","meanings":[{"en":"comment / remark","de":"Meinung oder Anmerkung zu etwas"}],"rule":"Maskulinum; Plural -e.","example":"Er schreibt einen Kommentar unter das Foto.","exampleEn":"He writes a comment under the photo.","example2":"Bitte keinen Kommentar dazu!","example2En":"No comment on that, please!"},{"de":"die Kommode","en":"chest of drawers","pos":"noun","plural":"die Kommoden","meanings":[{"en":"chest of drawers / dresser","de":"Möbelstück mit mehreren Schubladen"}],"rule":"Femininum; Plural -n.","example":"Die Kommode steht im Schlafzimmer.","exampleEn":"The chest of drawers is in the bedroom.","example2":"Ich lege die Socken in die oberste Schublade der Kommode.","example2En":"I put the socks in the top drawer of the dresser."},{"de":"die Kommunikation","en":"communication","pos":"noun","plural":"","meanings":[{"en":"the exchange of information between people","de":"der Austausch von Informationen"}],"rule":"Usually uncountable (no plural in everyday use); from the verb 'kommunizieren'.","example":"Die Kommunikation zwischen den Kollegen ist wichtig.","exampleEn":"Communication between the colleagues is important.","example2":"Wir verbessern unsere Kommunikation per E-Mail.","example2En":"We are improving our communication by email."},{"de":"kommunizieren","en":"to communicate","pos":"verb","plural":"","meanings":[{"en":"to exchange information with someone","de":"Informationen austauschen"}],"rule":"Regular weak verb: kommuniziert, kommunizierte, hat kommuniziert.","example":"Wir kommunizieren oft per Telefon.","exampleEn":"We often communicate by phone.","example2":"Sie kommuniziert gern mit Kunden.","example2En":"She likes communicating with customers."}]},{"id":"a2-11","title":"A2 · K–L (11)","level":"A2","words":[{"de":"kompakt","en":"compact","pos":"adjective","plural":"","meanings":[{"en":"small and efficiently arranged","de":"klein und praktisch"}],"rule":"Regular comparison: kompakt, kompakter, am kompaktesten.","example":"Das Auto ist sehr kompakt.","exampleEn":"The car is very compact.","example2":"Ich brauche eine kompakte Kamera.","example2En":"I need a compact camera."},{"de":"das Kompliment","en":"compliment","pos":"noun","plural":"die Komplimente","meanings":[{"en":"a friendly remark of praise","de":"nettes Lob"}],"rule":"Neuter noun; common phrase: ein Kompliment machen.","example":"Er macht ihr ein Kompliment für das Kleid.","exampleEn":"He gives her a compliment on the dress.","example2":"Danke für das Kompliment!","example2En":"Thanks for the compliment!"},{"de":"kompliziert","en":"complicated","pos":"adjective","plural":"","meanings":[{"en":"difficult to understand or do","de":"schwer zu verstehen oder zu machen"}],"rule":"Regular comparison: kompliziert, komplizierter, am kompliziertesten.","example":"Die Anleitung ist kompliziert.","exampleEn":"The instructions are complicated.","example2":"Das Formular ist nicht kompliziert.","example2En":"The form is not complicated."},{"de":"das Konto","en":"bank account","pos":"noun","plural":"die Konten","meanings":[{"en":"an account at a bank","de":"ein Bankkonto"}],"rule":"Neuter noun; irregular plural 'die Konten' (not 'die Kontos').","example":"Ich habe ein Konto bei der Bank.","exampleEn":"I have an account at the bank.","example2":"Er überweist Geld auf mein Konto.","example2En":"He transfers money to my account."},{"de":"der Kontoauszug","en":"bank statement","pos":"noun","plural":"die Kontoauszüge","meanings":[{"en":"a printed record of transactions on a bank account","de":"eine Übersicht der Kontobewegungen"}],"rule":"Compound of Konto + Auszug; masculine, plural with umlaut: Kontoauszüge.","example":"Ich hole meinen Kontoauszug am Automaten.","exampleEn":"I get my bank statement from the machine.","example2":"Der Kontoauszug zeigt alle Zahlungen.","example2En":"The bank statement shows all payments."},{"de":"der Kontoinhaber / die Kontoinhaberin","en":"account holder","pos":"noun","plural":"die Kontoinhaber / die Kontoinhaberinnen","meanings":[{"en":"the person who owns a bank account","de":"die Person, der das Konto gehört"}],"rule":"Compound of Konto + Inhaber(in); masculine form also used generically.","example":"Der Kontoinhaber muss den Antrag unterschreiben.","exampleEn":"The account holder must sign the application.","example2":"Sie ist die Kontoinhaberin dieses Sparkontos.","example2En":"She is the holder of this savings account."},{"de":"die Kontonummer","en":"account number","pos":"noun","plural":"die Kontonummern","meanings":[{"en":"the number identifying a bank account","de":"die Nummer eines Kontos"}],"rule":"Compound of Konto + Nummer; feminine.","example":"Bitte geben Sie Ihre Kontonummer an.","exampleEn":"Please state your account number.","example2":"Ich habe die Kontonummer vergessen.","example2En":"I forgot the account number."},{"de":"der Kontostand","en":"account balance","pos":"noun","plural":"die Kontostände","meanings":[{"en":"the current amount of money in an account","de":"der aktuelle Geldbetrag auf dem Konto"}],"rule":"Compound of Konto + Stand; masculine, plural with umlaut.","example":"Ich prüfe meinen Kontostand online.","exampleEn":"I check my account balance online.","example2":"Der Kontostand ist niedrig.","example2En":"The account balance is low."},{"de":"die Kontoverbindung","en":"bank details","pos":"noun","plural":"die Kontoverbindungen","meanings":[{"en":"bank account details needed for a transfer","de":"die Bankdaten für eine Überweisung"}],"rule":"Compound of Konto + Verbindung; feminine.","example":"Bitte senden Sie mir Ihre Kontoverbindung.","exampleEn":"Please send me your bank details.","example2":"Die Kontoverbindung steht auf der Rechnung.","example2En":"The bank details are on the invoice."},{"de":"kontrollieren","en":"to check; to control","pos":"verb","plural":"","meanings":[{"en":"to check something carefully","de":"etwas genau prüfen"},{"en":"to control or supervise something","de":"etwas überwachen"}],"rule":"Regular weak verb: kontrolliert, kontrollierte, hat kontrolliert.","example":"Der Kontrolleur kontrolliert die Fahrkarten.","exampleEn":"The inspector checks the tickets.","example2":"Sie kontrolliert die Temperatur im Kühlschrank.","example2En":"She checks the temperature in the fridge."},{"de":"der Kopfhörer","en":"headphones","pos":"noun","plural":"die Kopfhörer","meanings":[{"en":"a device worn over the ears to listen to audio","de":"ein Gerät für die Ohren zum Musikhören"}],"rule":"Masculine noun; plural is identical to singular (like der Lehrer → die Lehrer); often used in plural like in English.","example":"Ich höre Musik mit Kopfhörern.","exampleEn":"I listen to music with headphones.","example2":"Meine Kopfhörer sind kaputt.","example2En":"My headphones are broken."},{"de":"kopieren","en":"to copy","pos":"verb","plural":"","meanings":[{"en":"to make a copy of something","de":"eine Kopie von etwas machen"}],"rule":"Regular weak verb: kopiert, kopierte, hat kopiert.","example":"Kannst du das Dokument kopieren?","exampleEn":"Can you copy the document?","example2":"Ich kopiere den Text in eine Datei.","example2En":"I'm copying the text into a file."},{"de":"der Korb","en":"basket","pos":"noun","plural":"die Körbe","meanings":[{"en":"a container made of woven material","de":"ein Behälter aus Geflecht"}],"rule":"Masculine noun; irregular plural with umlaut: die Körbe.","example":"Sie legt die Äpfel in den Korb.","exampleEn":"She puts the apples in the basket.","example2":"Ich nehme einen Korb zum Einkaufen.","example2En":"I take a basket for shopping."},{"de":"die Kosmetiktasche","en":"cosmetics bag","pos":"noun","plural":"die Kosmetiktaschen","meanings":[{"en":"a small bag for cosmetics and toiletries","de":"eine kleine Tasche für Kosmetikartikel"}],"rule":"Compound of Kosmetik + Tasche; feminine.","example":"Ich packe meine Kosmetiktasche für die Reise.","exampleEn":"I'm packing my cosmetics bag for the trip.","example2":"Die Kosmetiktasche liegt im Koffer.","example2En":"The cosmetics bag is in the suitcase."},{"de":"die Kostenerstattung","en":"reimbursement of costs","pos":"noun","plural":"die Kostenerstattungen","meanings":[{"en":"the repayment of money that was spent","de":"die Rückzahlung von ausgegebenem Geld"}],"rule":"Compound of Kosten + Erstattung; feminine.","example":"Ich beantrage die Kostenerstattung bei der Versicherung.","exampleEn":"I apply for cost reimbursement from the insurance.","example2":"Die Kostenerstattung dauert zwei Wochen.","example2En":"The reimbursement takes two weeks."},{"de":"kostenfrei","en":"free of charge","pos":"adjective","plural":"","meanings":[{"en":"not costing anything","de":"ohne Kosten"}],"rule":"Same meaning as \"kostenlos\"; often used in formal/official contexts (e.g. Hotline, Beratung). No irregular comparison.","example":"Die Beratung ist kostenfrei.","exampleEn":"The consultation is free of charge.","example2":"Sie können die Hotline kostenfrei anrufen.","example2En":"You can call the hotline free of charge."},{"de":"kostenlos","en":"free, without charge","pos":"adjective","plural":"","meanings":[{"en":"not costing money","de":"gratis, ohne Kosten"}],"rule":"Very common everyday word for \"free\"; no irregular comparison.","example":"Der Eintritt ins Museum ist heute kostenlos.","exampleEn":"Entry to the museum is free today.","example2":"Kinder unter sechs Jahren fahren kostenlos.","example2En":"Children under six ride for free."},{"de":"die Kostenübernahme","en":"cost coverage, assumption of costs","pos":"noun","plural":"die Kostenübernahmen","meanings":[{"en":"when an institution agrees to pay for something","de":"Übernahme der Kosten durch jemanden"}],"rule":"Compound noun: Kosten + Übernahme; often used with Krankenkasse (health insurance covering costs).","example":"Die Krankenkasse hat die Kostenübernahme für die Behandlung bestätigt.","exampleEn":"The health insurance confirmed it will cover the costs of the treatment.","example2":"Bitte schicken Sie uns die Kostenübernahme der Versicherung.","example2En":"Please send us the insurance's confirmation of cost coverage."},{"de":"die Kraft","en":"strength, power, force","pos":"noun","plural":"die Kräfte","meanings":[{"en":"physical strength","de":"körperliche Stärke"},{"en":"energy/vigor for doing something","de":"Energie, Vermögen etwas zu tun"}],"rule":"Feminine noun with umlaut plural (die Kraft -> die Kräfte). Common phrase: \"mit letzter Kraft\".","example":"Er hat nicht genug Kraft, um die Kiste zu tragen.","exampleEn":"He doesn't have enough strength to carry the box.","example2":"Nach der Krankheit fehlte ihr die Kraft für die Arbeit.","example2En":"After the illness she lacked the energy for work."},{"de":"die Krawatte","en":"necktie","pos":"noun","plural":"die Krawatten","meanings":[{"en":"a strip of cloth worn around the neck with a shirt","de":"Halsbekleidung zum Anzug"}],"rule":"Feminine noun, regular -n plural.","example":"Zum Vorstellungsgespräch trägt er eine blaue Krawatte.","exampleEn":"He wears a blue tie to the job interview.","example2":"Im Sommer lässt er die Krawatte oft zu Hause.","example2En":"In summer he often leaves the tie at home."},{"de":"das Kreditinstitut","en":"credit institution, bank","pos":"noun","plural":"die Kreditinstitute","meanings":[{"en":"formal term for a bank or financial institution","de":"Bank, Geldinstitut"}],"rule":"Neuter noun; formal/official word, more bureaucratic than \"Bank\".","example":"Die Überweisung erfolgt über ein deutsches Kreditinstitut.","exampleEn":"The transfer is made through a German credit institution.","example2":"Nicht jedes Kreditinstitut bietet kostenlose Konten an.","example2En":"Not every bank offers free accounts."},{"de":"die Kreditkarte","en":"credit card","pos":"noun","plural":"die Kreditkarten","meanings":[{"en":"a card used to pay and borrow money","de":"Zahlungskarte mit Kreditfunktion"}],"rule":"Feminine noun, regular -n plural; compound of Kredit + Karte.","example":"Kann ich mit Kreditkarte bezahlen?","exampleEn":"Can I pay by credit card?","example2":"Sie hat ihre Kreditkarte verloren.","example2En":"She lost her credit card."},{"de":"das Küchengerät","en":"kitchen appliance","pos":"noun","plural":"die Küchengeräte","meanings":[{"en":"a device used in the kitchen","de":"Gerät, das man in der Küche benutzt"}],"rule":"Neuter compound noun (Küche + Gerät), regular -e plural.","example":"Der Mixer ist ein praktisches Küchengerät.","exampleEn":"The blender is a practical kitchen appliance.","example2":"Wir brauchen noch ein paar Küchengeräte für die neue Wohnung.","example2En":"We still need a few kitchen appliances for the new apartment."},{"de":"die Küchenhilfe","en":"kitchen assistant, kitchen help","pos":"noun","plural":"die Küchenhilfen","meanings":[{"en":"a person who helps in a kitchen (restaurant)","de":"Person, die in der Küche hilft"}],"rule":"Feminine noun, regular -n plural; can refer to a person (job) regardless of the person's gender.","example":"Er arbeitet als Küchenhilfe in einem Restaurant.","exampleEn":"He works as a kitchen assistant in a restaurant.","example2":"Das Restaurant sucht eine Küchenhilfe für die Wochenenden.","example2En":"The restaurant is looking for kitchen help for weekends."},{"de":"kühlen","en":"to cool, to chill","pos":"verb","plural":"","meanings":[{"en":"to make something cold or colder","de":"kalt machen, kühl halten"}],"rule":"Regular weak verb: kühlt, kühlte, hat gekühlt. Takes an accusative object.","example":"Der Kühlschrank kühlt die Getränke.","exampleEn":"The fridge keeps the drinks cool.","example2":"Kühle die Wunde mit Eis.","example2En":"Cool the wound with ice."},{"de":"das Kulturcafé","en":"culture café","pos":"noun","plural":"die Kulturcafés","meanings":[{"en":"a café that also hosts cultural events (readings, exhibitions, concerts)","de":"Café mit kulturellem Programm, z. B. Lesungen oder Ausstellungen"}],"rule":"Neuter compound noun (Kultur + Café); plural takes -s like loanword \"Café\".","example":"Am Freitag gibt es eine Lesung im Kulturcafé.","exampleEn":"On Friday there is a reading at the culture café.","example2":"Das Kulturcafé in der Altstadt zeigt jeden Monat eine neue Ausstellung.","example2En":"The culture café in the old town shows a new exhibition every month."},{"de":"der Kumpel","en":"buddy, mate, pal","pos":"noun","plural":"die Kumpels","meanings":[{"en":"informal word for a close friend","de":"umgangssprachlich für guter Freund"}],"rule":"Masculine noun, colloquial; plural die Kumpels (also die Kumpel in some regions/miner sense).","example":"Er trifft sich heute mit seinen Kumpels zum Fußball.","exampleEn":"He's meeting his buddies to play football today.","example2":"Mein Kumpel hat mir beim Umzug geholfen.","example2En":"My buddy helped me move."},{"de":"die Kundenbetreuung","en":"customer service, customer support","pos":"noun","plural":"","meanings":[{"en":"the department/activity of helping and advising customers","de":"Betreuung und Beratung von Kunden"}],"rule":"Feminine noun, uncountable (no plural); compound of Kunde + Betreuung.","example":"Bei Fragen wenden Sie sich an unsere Kundenbetreuung.","exampleEn":"If you have questions, contact our customer service.","example2":"Sie arbeitet in der Kundenbetreuung eines Telefonanbieters.","example2En":"She works in customer support for a phone provider."},{"de":"die Kundennummer","en":"customer number","pos":"noun","plural":"die Kundennummern","meanings":[{"en":"a number identifying a customer in a company's system","de":"Nummer, die einen Kunden identifiziert"}],"rule":"Feminine noun, regular -n plural; compound of Kunde + Nummer.","example":"Bitte geben Sie Ihre Kundennummer an.","exampleEn":"Please state your customer number.","example2":"Ich finde meine Kundennummer auf der Rechnung.","example2En":"I can find my customer number on the invoice."},{"de":"die Kundenreferenz","en":"customer reference","pos":"noun","plural":"die Kundenreferenzen","meanings":[{"en":"a reference code or ID used to identify a customer transaction/contact","de":"Referenznummer oder -kennzeichen eines Kunden"}],"rule":"Feminine noun, regular -en plural; used in banking/business contexts (e.g. on forms, transfers).","example":"Geben Sie bei der Überweisung die Kundenreferenz an.","exampleEn":"Please enter the customer reference when making the transfer.","example2":"Die Kundenreferenz finden Sie oben rechts im Brief.","example2En":"You can find the customer reference at the top right of the letter."},{"de":"kündigen","en":"to cancel, to terminate, to give notice","pos":"verb","plural":"","meanings":[{"en":"to end a contract (job, lease, subscription)","de":"einen Vertrag beenden"},{"en":"to resign from a job / to fire someone","de":"eine Arbeitsstelle beenden (selbst oder als Arbeitgeber)"}],"rule":"Regular weak verb: kündigt, kündigte, hat gekündigt. Often with Dativ for the person (\"jemandem kündigen\") or Akkusativ for the thing (\"den Vertrag kündigen\").","example":"Ich möchte meinen Handyvertrag kündigen.","exampleEn":"I want to cancel my phone contract.","example2":"Der Chef hat ihm gekündigt.","example2En":"The boss fired him."},{"de":"die Kunst","en":"art","pos":"noun","plural":"die Künste","meanings":[{"en":"creative works such as painting, sculpture, music","de":"künstlerisches Schaffen, z. B. Malerei"},{"en":"a skill or ability to do something well","de":"Fertigkeit, etwas gut zu können"}],"rule":"Feminine noun with umlaut plural (die Kunst -> die Künste); singular usually uncountable in the art sense.","example":"Sie interessiert sich sehr für moderne Kunst.","exampleEn":"She is very interested in modern art.","example2":"Kochen ist auch eine Kunst.","example2En":"Cooking is an art too."},{"de":"die Kursgebühr","en":"course fee","pos":"noun","plural":"die Kursgebühren","meanings":[{"en":"the fee paid to attend a course","de":"Geld, das man für einen Kurs bezahlt"}],"rule":"Feminine noun, regular -en plural; compound of Kurs + Gebühr.","example":"Die Kursgebühr beträgt 150 Euro.","exampleEn":"The course fee is 150 euros.","example2":"Die Kursgebühren müssen vor Beginn bezahlt werden.","example2En":"The course fees must be paid before the start."},{"de":"kürzen","en":"to shorten; to cut (pay/text)","pos":"verb","plural":"","meanings":[{"en":"to shorten (a text, a stay)","de":"kürzer machen"},{"en":"to cut/reduce (money, pay)","de":"weniger zahlen, reduzieren"}],"rule":"regular weak verb: kürzt, kürzte, hat gekürzt","example":"Kannst du den Text bitte kürzen?","exampleEn":"Can you please shorten the text?","example2":"Die Firma hat sein Gehalt gekürzt.","example2En":"The company cut his salary."},{"de":"das Kurzprogramm","en":"short program / short course","pos":"noun","plural":"die Kurzprogramme","meanings":[{"en":"a brief version of a program or course","de":"ein kurzes Programm"}],"rule":"compound noun: kurz + Programm; neuter like das Programm","example":"Der Deutschkurs hat auch ein Kurzprogramm für Anfänger.","exampleEn":"The German course also has a short program for beginners.","example2":"Die Eisläuferin zeigt heute ihr Kurzprogramm.","example2En":"The figure skater is showing her short program today."},{"de":"der Laden","en":"shop, store","pos":"noun","plural":"die Läden","meanings":[{"en":"a small shop or store","de":"ein Geschäft"}],"rule":"irregular plural with umlaut: der Laden → die Läden","example":"Der Laden an der Ecke verkauft frisches Brot.","exampleEn":"The shop on the corner sells fresh bread.","example2":"Ich kaufe meine Milch immer in diesem Laden.","example2En":"I always buy my milk at this shop."},{"de":"der Laptop","en":"laptop","pos":"noun","plural":"die Laptops","meanings":[{"en":"a portable computer","de":"ein tragbarer Computer"}],"rule":"loanword from English; plural simply adds -s","example":"Mein Laptop ist sehr leicht und praktisch.","exampleEn":"My laptop is very light and practical.","example2":"Ich arbeite oft im Café mit meinem Laptop.","example2En":"I often work in the café with my laptop."},{"de":"die Laufbahn","en":"career, professional path","pos":"noun","plural":"die Laufbahnen","meanings":[{"en":"one's career or professional path","de":"der berufliche Werdegang"}],"rule":"compound: laufen (run) + Bahn (track/path); often used for career progress","example":"Sie hat eine erfolgreiche Laufbahn als Ärztin.","exampleEn":"She has a successful career as a doctor.","example2":"Nach der Ausbildung begann seine berufliche Laufbahn.","example2En":"After training, his professional career began."},{"de":"laufen","en":"to run; to walk; to work/function","pos":"verb","plural":"","meanings":[{"en":"to run or move on foot","de":"sich schnell zu Fuß bewegen"},{"en":"to function, to be in operation (machine, film)","de":"funktionieren, in Betrieb sein"}],"rule":"irregular verb: läuft, lief, ist gelaufen","example":"Er läuft jeden Morgen eine Stunde.","exampleEn":"He runs for an hour every morning.","example2":"Der Fernseher läuft schon seit zwei Stunden.","example2En":"The TV has been on for two hours already."},{"de":"der Lebenslauf","en":"curriculum vitae, résumé","pos":"noun","plural":"die Lebensläufe","meanings":[{"en":"a written summary of one's education and work experience","de":"eine schriftliche Übersicht über Ausbildung und Berufserfahrung"}],"rule":"compound: Leben + Lauf; always needed for a Bewerbung (job application)","example":"Bitte schicken Sie uns Ihren Lebenslauf.","exampleEn":"Please send us your CV.","example2":"Ich muss meinen Lebenslauf aktualisieren.","example2En":"I need to update my résumé."},{"de":"der Lebenspartner / die Lebenspartnerin","en":"life partner","pos":"noun","plural":"die Lebenspartner / die Lebenspartnerinnen","meanings":[{"en":"a person one lives with in a long-term relationship","de":"jemand, mit dem man zusammenlebt"}],"rule":"compound: Leben + Partner/in; used for both married and unmarried partners","example":"Mein Lebenspartner kocht sehr gern.","exampleEn":"My life partner loves to cook.","example2":"Sie stellte mir ihre Lebenspartnerin vor.","example2En":"She introduced me to her life partner."},{"de":"der Lebensweg","en":"path of life, life journey","pos":"noun","plural":"die Lebenswege","meanings":[{"en":"the course or journey of a person's life","de":"der Weg, den ein Leben nimmt"}],"rule":"compound: Leben + Weg; often used in a slightly formal or reflective way","example":"Jeder Mensch hat seinen eigenen Lebensweg.","exampleEn":"Every person has their own path in life.","example2":"Ihr Lebensweg war nicht immer einfach.","example2En":"Her life journey was not always easy."},{"de":"legen","en":"to lay, to put (flat)","pos":"verb","plural":"","meanings":[{"en":"to put or lay something down in a flat position","de":"etwas flach hinlegen"},{"en":"sich legen: to lie down (reflexive)","de":"sich hinlegen"}],"rule":"regular weak verb: legt, legte, hat gelegt; + Akkusativ; contrast with liegen (to lie/be located)","example":"Leg das Buch bitte auf den Tisch.","exampleEn":"Please put the book on the table.","example2":"Sie legt sich kurz aufs Bett.","example2En":"She lies down on the bed for a bit."},{"de":"die Lehre","en":"apprenticeship; teaching, lesson","pos":"noun","plural":"die Lehren","meanings":[{"en":"vocational apprenticeship/training","de":"berufliche Ausbildung"},{"en":"a lesson or teaching drawn from experience","de":"eine Lektion, eine Erkenntnis aus Erfahrung"}],"rule":"related to lehren (to teach); common phrase: eine Lehre machen","example":"Er macht eine Lehre als Elektriker.","exampleEn":"He is doing an apprenticeship as an electrician.","example2":"Das war eine wichtige Lehre für mich.","example2En":"That was an important lesson for me."},{"de":"das Lehrmaterial","en":"teaching material","pos":"noun","plural":"die Lehrmaterialien","meanings":[{"en":"materials used for teaching, such as books or worksheets","de":"Material zum Unterrichten"}],"rule":"compound: Lehr- + Material; often used in plural (Lehrmaterialien)","example":"Die Schule stellt kostenloses Lehrmaterial zur Verfügung.","exampleEn":"The school provides free teaching materials.","example2":"Das Lehrmaterial für den Kurs liegt im Sekretariat.","example2En":"The course materials are at the office."},{"de":"die Leidenschaft","en":"passion","pos":"noun","plural":"die Leidenschaften","meanings":[{"en":"a strong enthusiasm or love for something","de":"eine starke Begeisterung"}],"rule":"often used with für: Leidenschaft für etwas haben","example":"Musik ist seine große Leidenschaft.","exampleEn":"Music is his great passion.","example2":"Sie kocht mit viel Leidenschaft.","example2En":"She cooks with a lot of passion."},{"de":"leidtun","en":"to be sorry (about something)","pos":"verb","plural":"","meanings":[{"en":"to feel sorry, used impersonally: es tut mir leid","de":"Bedauern ausdrücken"}],"rule":"trennbar: tut ... leid, tat ... leid, hat leidgetan; used impersonally with Dativ: es tut mir leid","example":"Es tut mir leid, dass ich zu spät bin.","exampleEn":"I'm sorry that I'm late.","example2":"Der arme Mann tut mir wirklich leid.","example2En":"I really feel sorry for the poor man."},{"de":"leihen","en":"to lend; to borrow","pos":"verb","plural":"","meanings":[{"en":"to lend something to someone","de":"jemandem etwas geben, das zurückgegeben werden muss"},{"en":"sich etwas leihen: to borrow something","de":"sich etwas von jemandem ausleihen"}],"rule":"irregular verb: leiht, lieh, hat geliehen; + Dativ for the person","example":"Kannst du mir 20 Euro leihen?","exampleEn":"Can you lend me 20 euros?","example2":"Ich habe mir ein Buch aus der Bibliothek geliehen.","example2En":"I borrowed a book from the library."},{"de":"die Leistung","en":"performance, achievement","pos":"noun","plural":"die Leistungen","meanings":[{"en":"performance or achievement (school, work, sports)","de":"das, was jemand erreicht oder schafft"},{"en":"a service or benefit (e.g. insurance)","de":"eine Dienstleistung, z. B. von einer Versicherung"}],"rule":"related to leisten (to achieve, to perform); common in school/work contexts","example":"Seine Leistungen in Mathe sind sehr gut.","exampleEn":"His performance in math is very good.","example2":"Die Versicherung übernimmt diese Leistung nicht.","example2En":"The insurance does not cover this service."},{"de":"der Leser / die Leserin","en":"reader","pos":"noun","plural":"die Leser / die Leserinnen","meanings":[{"en":"a person who reads something, e.g. a book or newspaper","de":"jemand, der liest"}],"rule":"derived from lesen (to read); -in for feminine form","example":"Die Zeitung hat viele treue Leser.","exampleEn":"The newspaper has many loyal readers.","example2":"Als Leserin schreibt sie oft Briefe an die Redaktion.","example2En":"As a reader, she often writes letters to the editor."}]},{"id":"a2-12","title":"A2 · L–M (12)","level":"A2","words":[{"de":"der Lichtbildausweis","en":"photo ID","pos":"noun","plural":"die Lichtbildausweise","meanings":[{"en":"an official identity document with a photo","de":"ein Ausweis mit Foto"}],"rule":"compound: Lichtbild (photo) + Ausweis (ID); formal word, e.g. Personalausweis or Reisepass","example":"Bitte zeigen Sie einen gültigen Lichtbildausweis.","exampleEn":"Please show a valid photo ID.","example2":"Ohne Lichtbildausweis dürfen Sie nicht in die Prüfung.","example2En":"Without a photo ID you may not enter the exam."},{"de":"das Lieblingsfach","en":"favorite subject (school)","pos":"noun","plural":"die Lieblingsfächer","meanings":[{"en":"favorite school subject","de":"das Schulfach, das man am liebsten mag"}],"rule":"Compound noun: Lieblings- + das Fach; gender from Fach (das).","example":"Mathe ist mein Lieblingsfach.","exampleEn":"Math is my favorite subject.","example2":"Was ist dein Lieblingsfach in der Schule?","example2En":"What is your favorite subject at school?"},{"de":"die Lieblingsfarbe","en":"favorite color","pos":"noun","plural":"die Lieblingsfarben","meanings":[{"en":"the color one likes most","de":"die Farbe, die man am liebsten mag"}],"rule":"Compound noun: Lieblings- + die Farbe; gender from Farbe (die).","example":"Meine Lieblingsfarbe ist Blau.","exampleEn":"My favorite color is blue.","example2":"Welche Farbe ist deine Lieblingsfarbe?","example2En":"Which color is your favorite?"},{"de":"der Lieferant / die Lieferantin","en":"supplier; delivery person","pos":"noun","plural":"die Lieferanten / die Lieferantinnen","meanings":[{"en":"person or company that delivers/supplies goods","de":"jemand, der Waren liefert"}],"rule":"Weak masculine noun (der Lieferant, den/dem/des Lieferanten); feminine form with -in.","example":"Der Lieferant bringt die Pakete am Vormittag.","exampleEn":"The delivery person brings the packages in the morning.","example2":"Wir suchen einen neuen Lieferanten für Obst und Gemüse.","example2En":"We are looking for a new supplier for fruit and vegetables."},{"de":"liefern","en":"to deliver; to supply","pos":"verb","plural":"","meanings":[{"en":"to deliver goods","de":"Waren bringen"},{"en":"to supply / provide","de":"zur Verfügung stellen"}],"rule":"Regular weak verb: liefert, lieferte, hat geliefert.","example":"Der Supermarkt liefert die Ware bis vor die Tür.","exampleEn":"The supermarket delivers the goods right to the door.","example2":"Die Firma liefert Strom für die ganze Stadt.","example2En":"The company supplies electricity for the whole city."},{"de":"lockig","en":"curly","pos":"adjective","plural":"","meanings":[{"en":"having curls (hair)","de":"mit Locken"}],"rule":"Regular adjective, no irregular comparison: lockig, lockiger, am lockigsten. Used mainly to describe hair.","example":"Sie hat lockige Haare.","exampleEn":"She has curly hair.","example2":"Mein Bruder hatte als Kind sehr lockige Haare.","example2En":"My brother had very curly hair as a child."},{"de":"der Löffel","en":"spoon","pos":"noun","plural":"die Löffel","meanings":[{"en":"eating utensil for liquid/soft food","de":"Besteckteil zum Essen von Suppe"}],"rule":"Masculine noun; plural unchanged (der Löffel – die Löffel).","example":"Kannst du mir einen Löffel geben?","exampleEn":"Can you give me a spoon?","example2":"Ich esse die Suppe mit einem großen Löffel.","example2En":"I eat the soup with a big spoon."},{"de":"löschen","en":"to delete; to extinguish","pos":"verb","plural":"","meanings":[{"en":"to delete (a file, text)","de":"eine Datei entfernen"},{"en":"to extinguish (fire)","de":"ein Feuer ausmachen"}],"rule":"Regular weak verb: löscht, löschte, hat gelöscht.","example":"Ich habe die E-Mail aus Versehen gelöscht.","exampleEn":"I accidentally deleted the email.","example2":"Die Feuerwehr hat das Feuer schnell gelöscht.","example2En":"The fire department extinguished the fire quickly."},{"de":"lösen","en":"to solve; to loosen/detach","pos":"verb","plural":"","meanings":[{"en":"to solve (a problem, task)","de":"eine Lösung für eine Aufgabe finden"},{"en":"to loosen or detach something","de":"etwas lockern oder abtrennen"}],"rule":"Regular weak verb: löst, löste, hat gelöst.","example":"Er hat die Matheaufgabe schnell gelöst.","exampleEn":"He solved the math problem quickly.","example2":"Der Knoten lässt sich nicht lösen.","example2En":"The knot won't loosen."},{"de":"losfahren","en":"to set off, to depart (driving/riding)","pos":"verb","plural":"","meanings":[{"en":"to start a journey / depart","de":"mit dem Fahrzeug abfahren"}],"rule":"Trennbar (separable): fährt los, fuhr los, ist losgefahren.","example":"Wir fahren morgen früh um sechs Uhr los.","exampleEn":"We set off tomorrow at six in the morning.","example2":"Der Bus ist schon losgefahren.","example2En":"The bus has already departed."},{"de":"lückenlos","en":"complete, without gaps","pos":"adjective","plural":"","meanings":[{"en":"without any gaps or omissions, complete","de":"ohne Lücken, vollständig"}],"rule":"From die Lücke (gap) + -los; regular comparison: lückenlos, lückenloser, am lückenlosesten.","example":"Sie hat einen lückenlosen Lebenslauf.","exampleEn":"She has a complete résumé (no gaps).","example2":"Die Polizei will die Vorfälle lückenlos aufklären.","example2En":"The police want to clarify the incidents completely."},{"de":"die Lust","en":"desire, enjoyment; mood (to do something)","pos":"noun","plural":"","meanings":[{"en":"desire/inclination to do something","de":"Wunsch oder Freude, etwas zu tun"}],"rule":"Feminine noun, usually uncountable in this A2 sense; common phrase: Lust haben auf + Akkusativ / Lust haben, etwas zu tun.","example":"Hast du Lust, ins Kino zu gehen?","exampleEn":"Do you feel like going to the cinema?","example2":"Ich habe heute keine Lust zu kochen.","example2En":"I don't feel like cooking today."},{"de":"das Mädchen","en":"girl","pos":"noun","plural":"die Mädchen","meanings":[{"en":"female child or young girl","de":"weibliches Kind"}],"rule":"Neuter noun despite referring to a female (diminutive -chen is always neuter); plural unchanged.","example":"Das Mädchen spielt im Garten.","exampleEn":"The girl is playing in the garden.","example2":"In der Klasse sind zwölf Mädchen.","example2En":"There are twelve girls in the class."},{"de":"mailen","en":"to email","pos":"verb","plural":"","meanings":[{"en":"to send an email","de":"eine E-Mail schicken"}],"rule":"Regular weak verb (from English 'mail'): mailt, mailte, hat gemailt.","example":"Ich maile dir die Unterlagen heute Abend.","exampleEn":"I'll email you the documents tonight.","example2":"Kannst du mir bitte die Fotos mailen?","example2En":"Can you please email me the photos?"},{"de":"das Make-up","en":"makeup","pos":"noun","plural":"","meanings":[{"en":"cosmetics applied to the face","de":"Kosmetik fürs Gesicht"}],"rule":"Neuter loanword from English; usually uncountable, no plural in everyday use.","example":"Sie trägt nie viel Make-up.","exampleEn":"She never wears much makeup.","example2":"Er hilft ihr, das Make-up für die Feier aufzulegen.","example2En":"He helps her put on makeup for the party."},{"de":"der Makler / die Maklerin","en":"broker, real estate agent","pos":"noun","plural":"die Makler / die Maklerinnen","meanings":[{"en":"agent who mediates sales/rentals (esp. real estate)","de":"jemand, der Wohnungen oder Häuser vermittelt"}],"rule":"Masculine noun, plural unchanged; feminine form with -in.","example":"Wir haben die Wohnung über einen Makler gefunden.","exampleEn":"We found the apartment through a broker.","example2":"Die Maklerin zeigt uns heute drei Häuser.","example2En":"The real estate agent is showing us three houses today."},{"de":"malen","en":"to paint, to draw","pos":"verb","plural":"","meanings":[{"en":"to paint or draw (a picture)","de":"ein Bild mit Farbe oder Stift machen"}],"rule":"Regular weak verb: malt, malte, hat gemalt. Do not confuse with 'mahlen' (to grind).","example":"Das Kind malt ein Bild von seiner Familie.","exampleEn":"The child is drawing a picture of their family.","example2":"Sie malt gern mit Wasserfarben.","example2En":"She likes painting with watercolors."},{"de":"manche","en":"some, several","pos":"pronoun","plural":"","meanings":[{"en":"some (people/things), an indefinite number","de":"einige, nicht alle"}],"rule":"Declines like 'dieser'; used with or without a noun, e.g. manche Leute, manche sagen.","example":"Manche Leute mögen kein Fleisch.","exampleEn":"Some people don't like meat.","example2":"Manche finden das Wetter hier zu kalt.","example2En":"Some (people) think the weather here is too cold."},{"de":"mangelhaft","en":"deficient, poor (quality/grade)","pos":"adjective","plural":"","meanings":[{"en":"of poor quality, with defects","de":"mit Fehlern, nicht ausreichend"},{"en":"a poor/unsatisfactory school grade in Germany (Note 5)","de":"eine schlechte Schulnote (Note 5 im deutschen Notensystem)"}],"rule":"From der Mangel (lack) + -haft; regular comparison: mangelhaft, mangelhafter, am mangelhaftesten.","example":"Die Ware war mangelhaft und wir haben sie zurückgeschickt.","exampleEn":"The goods were defective, so we sent them back.","example2":"Er hat in Mathe die Note 'mangelhaft' bekommen.","example2En":"He got the grade 'mangelhaft' (a poor grade) in math."},{"de":"männlich","en":"male; masculine","pos":"adjective","plural":"","meanings":[{"en":"male (biological)","de":"vom Geschlecht her: Mann/Tier-männlich"},{"en":"masculine (grammar)","de":"grammatisches Geschlecht: der-Wörter"}],"rule":"No comparison irregularity; opposite: weiblich. Used for sex/gender of people/animals and for grammatical gender (der Artikel).","example":"Ist das Baby männlich oder weiblich?","exampleEn":"Is the baby male or female?","example2":"\"Der Tisch\" ist ein männliches Wort.","example2En":"\"Der Tisch\" is a masculine word."},{"de":"das Marketing","en":"marketing","pos":"noun","plural":"","meanings":[{"en":"marketing (business activity)","de":"Werbung und Verkaufsförderung"}],"rule":"Uncountable noun, no plural. Always with article das.","example":"Sie arbeitet im Marketing.","exampleEn":"She works in marketing.","example2":"Das Marketing für das neue Produkt ist wichtig.","example2En":"The marketing for the new product is important."},{"de":"die Massage","en":"massage","pos":"noun","plural":"die Massagen","meanings":[{"en":"massage (treatment)","de":"Behandlung durch Kneten des Körpers"}],"rule":"Feminine noun; plural regular: die Massagen.","example":"Ich brauche eine Massage.","exampleEn":"I need a massage.","example2":"Die Massage hat eine Stunde gedauert.","example2En":"The massage lasted one hour."},{"de":"massieren","en":"to massage","pos":"verb","plural":"","meanings":[{"en":"to massage someone/something","de":"kneten, den Körper behandeln"}],"rule":"Regular weak verb: massiert, massierte, hat massiert.","example":"Er massiert mir den Rücken.","exampleEn":"He massages my back.","example2":"Kannst du bitte meine Schultern massieren?","example2En":"Can you please massage my shoulders?"},{"de":"das Material","en":"material","pos":"noun","plural":"die Materialien","meanings":[{"en":"material (substance)","de":"Stoff, aus dem etwas gemacht wird"},{"en":"material (documents/supplies)","de":"Unterlagen, Werkzeuge für eine Aufgabe"}],"rule":"Neuter noun; plural die Materialien.","example":"Das Material ist sehr stabil.","exampleEn":"The material is very sturdy.","example2":"Ich brauche noch Material für den Kurs.","example2En":"I still need materials for the course."},{"de":"die Mathearbeit","en":"math test","pos":"noun","plural":"die Mathearbeiten","meanings":[{"en":"math exam/test (school)","de":"schriftliche Prüfung in Mathematik"}],"rule":"Feminine noun, compound of Mathe + Arbeit; plural die Mathearbeiten.","example":"Morgen schreiben wir eine Mathearbeit.","exampleEn":"Tomorrow we're writing a math test.","example2":"Die Mathearbeit war sehr schwer.","example2En":"The math test was very hard."},{"de":"die Maus","en":"mouse","pos":"noun","plural":"die Mäuse","meanings":[{"en":"mouse (animal)","de":"kleines Tier"},{"en":"mouse (computer device)","de":"Gerät für den Computer"}],"rule":"Feminine noun; irregular plural with umlaut: die Mäuse.","example":"Im Keller ist eine Maus.","exampleEn":"There's a mouse in the basement.","example2":"Meine Maus funktioniert nicht mehr.","example2En":"My (computer) mouse doesn't work anymore."},{"de":"die Meditation","en":"meditation","pos":"noun","plural":"die Meditationen","meanings":[{"en":"meditation (practice)","de":"ruhige Übung zur Entspannung"}],"rule":"Feminine noun; plural die Meditationen (often used singular/uncountable).","example":"Meditation hilft gegen Stress.","exampleEn":"Meditation helps against stress.","example2":"Sie macht jeden Morgen eine Meditation.","example2En":"She does a meditation every morning."},{"de":"die Mehrfachsteckdose","en":"power strip","pos":"noun","plural":"die Mehrfachsteckdosen","meanings":[{"en":"power strip / multi-socket outlet","de":"Steckdose mit mehreren Anschlüssen"}],"rule":"Feminine compound noun (mehrfach + Steckdose); plural die Mehrfachsteckdosen.","example":"Ich brauche eine Mehrfachsteckdose für die Lampen.","exampleEn":"I need a power strip for the lamps.","example2":"Die Mehrfachsteckdose hat sechs Anschlüsse.","example2En":"The power strip has six outlets."},{"de":"die Meinung","en":"opinion","pos":"noun","plural":"die Meinungen","meanings":[{"en":"opinion, view","de":"persönliche Ansicht zu einem Thema"}],"rule":"Feminine noun; common phrase: meiner Meinung nach (in my opinion).","example":"Meiner Meinung nach ist das richtig.","exampleEn":"In my opinion, that's correct.","example2":"Er hat immer eine andere Meinung.","example2En":"He always has a different opinion."},{"de":"meist","en":"mostly; most","pos":"adverb","plural":"","meanings":[{"en":"mostly, usually","de":"in den meisten Fällen"},{"en":"most (superlative of viel)","de":"die größte Menge/Anzahl"}],"rule":"Superlative form of viel; as adverb often \"meistens\". Comparison: viel, mehr, am meisten.","example":"Ich bin meist zu Hause.","exampleEn":"I'm mostly at home.","example2":"Die meisten Leute finden das gut.","example2En":"Most people find that good."},{"de":"melden","en":"to report","pos":"verb","plural":"","meanings":[{"en":"to report, notify (something)","de":"etwas offiziell mitteilen"},{"en":"sich melden – to get in touch / respond","de":"reflexiv: Kontakt aufnehmen, sich zu Wort melden"}],"rule":"Regular weak verb: meldet, meldete, hat gemeldet. Reflexive use: sich melden (bei + Dativ).","example":"Ich melde den Unfall der Polizei.","exampleEn":"I'm reporting the accident to the police.","example2":"Ich melde mich morgen bei dir.","example2En":"I'll get in touch with you tomorrow."},{"de":"die Menge","en":"amount, quantity","pos":"noun","plural":"die Mengen","meanings":[{"en":"amount, quantity","de":"Anzahl oder Masse von etwas"},{"en":"crowd (of people)","de":"viele Menschen an einem Ort"}],"rule":"Feminine noun; plural die Mengen. \"eine Menge\" also colloquially means \"a lot of\".","example":"Wir brauchen eine große Menge Wasser.","exampleEn":"We need a large amount of water.","example2":"Die Menge wartete vor dem Stadion.","example2En":"The crowd waited in front of the stadium."},{"de":"das Messer","en":"knife","pos":"noun","plural":"die Messer","meanings":[{"en":"knife","de":"Werkzeug zum Schneiden"}],"rule":"Neuter noun; plural unchanged: die Messer.","example":"Gib mir bitte das Messer.","exampleEn":"Please pass me the knife.","example2":"Das Messer ist sehr scharf.","example2En":"The knife is very sharp."},{"de":"mich","en":"me","pos":"pronoun","plural":"","meanings":[{"en":"me (accusative of ich)","de":"Akkusativform von ich"}],"rule":"Accusative personal pronoun, 1st person singular. Dative form is mir.","example":"Kannst du mich anrufen?","exampleEn":"Can you call me?","example2":"Er hat mich nicht gesehen.","example2En":"He didn't see me."},{"de":"der Mieter / die Mieterin","en":"tenant","pos":"noun","plural":"die Mieter / die Mieterinnen","meanings":[{"en":"tenant, renter","de":"Person, die eine Wohnung mietet"}],"rule":"Masculine der Mieter / feminine die Mieterin; plurals die Mieter / die Mieterinnen.","example":"Der Mieter zahlt jeden Monat die Miete.","exampleEn":"The tenant pays the rent every month.","example2":"Die Mieterin hat sich über die Heizung beschwert.","example2En":"The tenant (female) complained about the heating."},{"de":"das Mineralwasser","en":"mineral water","pos":"noun","plural":"die Mineralwässer","meanings":[{"en":"mineral water","de":"Wasser mit Mineralstoffen, oft mit Kohlensäure"}],"rule":"Neuter noun, usually uncountable; plural die Mineralwässer (with umlaut) used only for different brands/types.","example":"Ich trinke gern Mineralwasser.","exampleEn":"I like drinking mineral water.","example2":"Bringen Sie mir bitte eine Flasche Mineralwasser.","example2En":"Please bring me a bottle of mineral water."},{"de":"miserabel","en":"miserable, terrible","pos":"adjective","plural":"","meanings":[{"en":"very bad, terrible","de":"sehr schlecht"}],"rule":"No irregular comparison (miserabler, am miserabelsten - rarely used, often replaced by schrecklich). Strong negative adjective.","example":"Das Wetter heute ist miserabel.","exampleEn":"The weather today is terrible.","example2":"Ich fühle mich miserabel.","example2En":"I feel miserable."},{"de":"der Mitarbeiter / die Mitarbeiterin","en":"employee; colleague","pos":"noun","plural":"die Mitarbeiter / die Mitarbeiterinnen","meanings":[{"en":"employee (of a company)","de":"jemand, der in einer Firma arbeitet"},{"en":"colleague, team member","de":"Kollege/Kollegin im Team"}],"rule":"Compound of 'mit' + 'Arbeiter'; feminine form adds -in. Plural: die Mitarbeiter (m.), die Mitarbeiterinnen (f.).","example":"Frau Klein ist eine neue Mitarbeiterin in unserer Firma.","exampleEn":"Ms. Klein is a new employee at our company.","example2":"Die Firma hat 50 Mitarbeiter.","example2En":"The company has 50 employees."},{"de":"der Mitbewohner / die Mitbewohnerin","en":"roommate; flatmate","pos":"noun","plural":"die Mitbewohner / die Mitbewohnerinnen","meanings":[{"en":"person one shares a flat/house with","de":"Person, mit der man zusammen wohnt"}],"rule":"Compound: mit + Bewohner ('resident'). Feminine adds -in.","example":"Mein Mitbewohner kocht sehr gern.","exampleEn":"My roommate loves to cook.","example2":"Wir suchen eine neue Mitbewohnerin für die WG.","example2En":"We're looking for a new flatmate for the shared flat."},{"de":"mitfahren","en":"to ride/go along (as a passenger)","pos":"verb","plural":"","meanings":[{"en":"to travel along with someone (as a passenger)","de":"zusammen mit jemandem in einem Fahrzeug fahren, als Mitfahrer(in)"}],"rule":"trennbar: fährt mit, fuhr mit, ist mitgefahren. Typische Konstruktion: bei jemandem mitfahren (to catch a ride with someone).","example":"Kann ich bei dir mitfahren?","exampleEn":"Can I ride along with you?","example2":"Er ist bei seinem Kollegen mitgefahren.","example2En":"He rode along with his colleague."},{"de":"mitkommen","en":"to come along","pos":"verb","plural":"","meanings":[{"en":"to come along / accompany someone","de":"zusammen mit jemandem kommen"}],"rule":"trennbar: kommt mit, kam mit, ist mitgekommen.","example":"Kommst du heute Abend mit?","exampleEn":"Are you coming along tonight?","example2":"Sie ist leider nicht mitgekommen.","example2En":"Unfortunately she didn't come along."},{"de":"mitmachen","en":"to take part, join in","pos":"verb","plural":"","meanings":[{"en":"to participate, join in an activity","de":"an etwas teilnehmen"}],"rule":"trennbar: macht mit, machte mit, hat mitgemacht.","example":"Machst du bei dem Spiel mit?","exampleEn":"Are you joining in the game?","example2":"Alle Kinder haben beim Fest mitgemacht.","example2En":"All the children took part in the festival."},{"de":"mitnehmen","en":"to take along, take away","pos":"verb","plural":"","meanings":[{"en":"to take something/someone along","de":"etwas/jemanden mitbringen, mit sich nehmen"},{"en":"to take (food) away / to go","de":"zum Mitnehmen bestellen"}],"rule":"trennbar, unregelmäßig: nimmt mit, nahm mit, hat mitgenommen.","example":"Kannst du den Regenschirm mitnehmen?","exampleEn":"Can you take the umbrella with you?","example2":"Ich möchte die Pizza zum Mitnehmen bestellen.","example2En":"I'd like to order the pizza to take away."},{"de":"mitschreiben","en":"to take notes, write along","pos":"verb","plural":"","meanings":[{"en":"to take notes while someone speaks","de":"während des Sprechens Notizen machen"}],"rule":"trennbar, unregelmäßig: schreibt mit, schrieb mit, hat mitgeschrieben.","example":"Im Unterricht muss ich viel mitschreiben.","exampleEn":"In class I have to take a lot of notes.","example2":"Kannst du bitte mitschreiben, was er sagt?","example2En":"Can you please write down what he says?"},{"de":"die Mitteilung","en":"message, notice, announcement","pos":"noun","plural":"die Mitteilungen","meanings":[{"en":"a message or piece of information given to someone","de":"eine Nachricht oder Information"}],"rule":"From 'mitteilen' (to inform, tell). Feminine noun, plural -en.","example":"Ich habe eine wichtige Mitteilung für dich.","exampleEn":"I have an important message for you.","example2":"Die Schule hat eine Mitteilung an die Eltern geschickt.","example2En":"The school sent a notice to the parents."},{"de":"die Mittelschule","en":"secondary school (intermediate level)","pos":"noun","plural":"die Mittelschulen","meanings":[{"en":"type of secondary school (lower/intermediate track)","de":"eine weiterführende Schule (mittleres Niveau)"}],"rule":"Compound: Mittel- (middle) + Schule. Feminine, plural -n. Regional term (mainly Bavaria/Saxony); comparable schools elsewhere are called 'Realschule' or 'Hauptschule'.","example":"Mein Sohn geht auf die Mittelschule.","exampleEn":"My son goes to secondary school.","example2":"Nach der Grundschule wechseln viele Kinder in die Mittelschule.","example2En":"After primary school many children move to secondary school."},{"de":"mittlere","en":"middle, medium, average","pos":"adjective","plural":"","meanings":[{"en":"situated in the middle; medium in size/degree","de":"in der Mitte liegend, durchschnittlich"}],"rule":"Looks like a comparative but is actually the normal attributive form of 'mittel' (which is rarely used attributively): der mittlere Finger, die mittlere Größe. The bare form 'mittel' only appears predicatively/colloquially, e.g. 'Der Film war mittel' (so-so).","example":"Er ist von mittlerer Größe.","exampleEn":"He is of medium height.","example2":"Er hat ein mittleres Einkommen.","example2En":"He has an average income."},{"de":"mobil","en":"mobile","pos":"adjective","plural":"","meanings":[{"en":"able to move/travel easily","de":"beweglich, nicht ortsgebunden"},{"en":"relating to mobile phones/devices","de":"bezogen auf Mobiltelefone"}],"rule":"No irregular comparison: mobil, mobiler, am mobilsten.","example":"Mit dem Fahrrad bin ich sehr mobil.","exampleEn":"With the bike I'm very mobile.","example2":"Ich bin jederzeit unter meiner mobilen Nummer erreichbar.","example2En":"I'm always reachable at my mobile number."},{"de":"der Modedesigner / die Modedesignerin","en":"fashion designer","pos":"noun","plural":"die Modedesigner / die Modedesignerinnen","meanings":[{"en":"person who designs clothing/fashion","de":"jemand, der Kleidung entwirft"}],"rule":"Compound: Mode + Designer. Feminine adds -in.","example":"Sie möchte Modedesignerin werden.","exampleEn":"She wants to become a fashion designer.","example2":"Der Modedesigner zeigt seine neue Kollektion.","example2En":"The fashion designer is showing his new collection."},{"de":"das Modegeschäft","en":"clothing store, fashion shop","pos":"noun","plural":"die Modegeschäfte","meanings":[{"en":"a shop selling fashionable clothes","de":"ein Geschäft, in dem man Kleidung kauft"}],"rule":"Compound: Mode + Geschäft (neuter). Plural die Modegeschäfte.","example":"In der Stadt gibt es ein neues Modegeschäft.","exampleEn":"There's a new clothing store in town.","example2":"Ich kaufe meine Kleidung oft in diesem Modegeschäft.","example2En":"I often buy my clothes at this fashion shop."}]},{"id":"a2-13","title":"A2 · M–P (13)","level":"A2","words":[{"de":"der Modeschmuck","en":"costume jewelry","pos":"noun","plural":"","meanings":[{"en":"inexpensive, non-precious jewelry","de":"günstiger Schmuck ohne Edelsteine"}],"rule":"Compound: Mode + Schmuck. Masculine, uncountable (no plural).","example":"Die Kette ist nur Modeschmuck, kein echtes Gold.","exampleEn":"The necklace is just costume jewelry, not real gold.","example2":"Modeschmuck ist meistens billiger als echter Schmuck.","example2En":"Costume jewelry is usually cheaper than real jewelry."},{"de":"monatlich","en":"monthly","pos":"adjective","plural":"","meanings":[{"en":"happening once a month, per month","de":"jeden Monat, einmal im Monat"}],"rule":"Regular adjective/adverb, no irregular comparison; from 'Monat'.","example":"Die Miete bezahle ich monatlich.","exampleEn":"I pay the rent monthly.","example2":"Wir treffen uns zu einem monatlichen Meeting.","example2En":"We meet for a monthly meeting."},{"de":"die Müllabfuhr","en":"garbage collection; garbage truck service","pos":"noun","plural":"","meanings":[{"en":"the service that collects household waste","de":"der Dienst, der den Müll abholt"}],"rule":"Compound: Müll + Abfuhr. Feminine, usually no plural (uncountable as a service).","example":"Die Müllabfuhr kommt jeden Montag.","exampleEn":"The garbage collection comes every Monday.","example2":"Stell die Tonne vor die Tür, die Müllabfuhr kommt bald.","example2En":"Put the bin outside, the garbage truck is coming soon."},{"de":"die Münze","en":"coin","pos":"noun","plural":"die Münzen","meanings":[{"en":"a piece of metal money","de":"ein Geldstück aus Metall"}],"rule":"Feminine noun, plural -n.","example":"Ich habe keine Münzen für den Automaten.","exampleEn":"I don't have any coins for the machine.","example2":"Er sammelt alte Münzen.","example2En":"He collects old coins."},{"de":"der Muskel","en":"muscle","pos":"noun","plural":"die Muskeln","meanings":[{"en":"body tissue that produces movement","de":"Körpergewebe, das Bewegung erzeugt"}],"rule":"Masculine noun; weak declension: der Muskel, des Muskels, plural die Muskeln.","example":"Nach dem Sport tun mir die Muskeln weh.","exampleEn":"After exercise my muscles hurt.","example2":"Er trainiert seine Muskeln im Fitnessstudio.","example2En":"He trains his muscles at the gym."},{"de":"das Muster","en":"pattern; sample","pos":"noun","plural":"die Muster","meanings":[{"en":"pattern (design)","de":"das Design, die Verzierung"},{"en":"sample/example","de":"das Beispiel, die Probe"}],"rule":"Neutrum; Plural bleibt unverändert: das Muster – die Muster.","example":"Der Stoff hat ein schönes Muster.","exampleEn":"The fabric has a nice pattern.","example2":"Können Sie mir ein Muster schicken?","example2En":"Can you send me a sample?"},{"de":"die Nachbarschaft","en":"neighborhood","pos":"noun","plural":"die Nachbarschaften","meanings":[{"en":"neighborhood (area or the neighbors as a group)","de":"die Umgebung, die Nachbarn"}],"rule":"Femininum; von 'Nachbar' + Suffix '-schaft' (typisch feminin).","example":"Wir wohnen in einer ruhigen Nachbarschaft.","exampleEn":"We live in a quiet neighborhood.","example2":"Die ganze Nachbarschaft hat beim Fest mitgemacht.","example2En":"The whole neighborhood joined the festival."},{"de":"die Nachbereitung","en":"follow-up work; review","pos":"noun","plural":"die Nachbereitungen","meanings":[{"en":"reviewing/finishing work after an event or lesson","de":"das Aufarbeiten im Nachhinein"}],"rule":"Femininum; Gegenteil von 'Vorbereitung'.","example":"Die Nachbereitung des Kurses dauert eine Stunde.","exampleEn":"The follow-up work for the course takes one hour.","example2":"Nach dem Meeting ist noch Nachbereitung nötig.","example2En":"After the meeting some follow-up work is still needed."},{"de":"nachher","en":"afterwards","pos":"adverb","plural":"","meanings":[{"en":"afterwards, later","de":"später, danach"}],"rule":"Unveränderliches Adverb, kein Adjektiv (keine Steigerung).","example":"Ich rufe dich nachher an.","exampleEn":"I'll call you afterwards.","example2":"Wir gehen erst einkaufen, nachher kochen wir.","example2En":"We'll go shopping first, then cook afterwards."},{"de":"die Nachhilfe","en":"tutoring","pos":"noun","plural":"","meanings":[{"en":"private tutoring/extra lessons","de":"zusätzlicher Unterricht"}],"rule":"Femininum, meist unzählbar (kein Plural); oft in 'Nachhilfe geben/nehmen'.","example":"Mein Sohn bekommt Nachhilfe in Mathe.","exampleEn":"My son is getting tutoring in math.","example2":"Sie gibt Nachhilfe in Deutsch.","example2En":"She tutors German."},{"de":"die Nachricht","en":"message; news","pos":"noun","plural":"die Nachrichten","meanings":[{"en":"a message (e.g. text)","de":"die Mitteilung"},{"en":"the news (TV/radio)","de":"die Nachrichtensendung"}],"rule":"Femininum; Plural 'die Nachrichten' auch für 'news' (TV-Nachrichten).","example":"Ich habe dir eine Nachricht geschickt.","exampleEn":"I sent you a message.","example2":"Wir schauen um acht die Nachrichten.","example2En":"We watch the news at eight."},{"de":"nachschauen","en":"to look up; to check","pos":"verb","plural":"","meanings":[{"en":"to look something up (e.g. in a dictionary)","de":"nachsehen, kontrollieren"}],"rule":"trennbar: schaut ... nach, schaute nach, hat nachgeschaut.","example":"Ich muss das Wort im Wörterbuch nachschauen.","exampleEn":"I have to look up the word in the dictionary.","example2":"Schau bitte nach, ob die Tür zu ist.","example2En":"Please check whether the door is closed."},{"de":"der Nachtisch","en":"dessert","pos":"noun","plural":"die Nachtische","meanings":[{"en":"dessert","de":"die Süßspeise nach dem Essen"}],"rule":"Maskulinum; Synonym: das Dessert.","example":"Zum Nachtisch gibt es Eis.","exampleEn":"For dessert there is ice cream.","example2":"Isst du gern etwas Süßes als Nachtisch?","example2En":"Do you like something sweet for dessert?"},{"de":"nah","en":"near, close","pos":"adjective","plural":"","meanings":[{"en":"near/close in distance or relationship","de":"nicht weit entfernt"}],"rule":"Unregelmäßige Steigerung: nah, näher, am nächsten.","example":"Die Schule ist ganz nah.","exampleEn":"The school is very close.","example2":"Unsere Wohnung liegt nah am Park.","example2En":"Our apartment is close to the park."},{"de":"die Nähe","en":"proximity, vicinity","pos":"noun","plural":"","meanings":[{"en":"nearness, closeness","de":"die nahe Umgebung"}],"rule":"Femininum, kein Plural; oft in 'in der Nähe von'.","example":"Der Supermarkt ist in der Nähe.","exampleEn":"The supermarket is nearby.","example2":"Wir wohnen in der Nähe des Bahnhofs.","example2En":"We live near the train station."},{"de":"nähen","en":"to sew","pos":"verb","plural":"","meanings":[{"en":"to sew","de":"mit Nadel und Faden arbeiten"}],"rule":"Regelmäßig: näht, nähte, hat genäht.","example":"Meine Oma näht gern Kleider.","exampleEn":"My grandma likes to sew dresses.","example2":"Ich nähe mir eine neue Tasche.","example2En":"I'm sewing myself a new bag."},{"de":"nämlich","en":"namely; because","pos":"adverb","plural":"","meanings":[{"en":"namely (specifying)","de":"und zwar"},{"en":"because, the reason is","de":"denn, aus dem Grund"}],"rule":"Unveränderliches Adverb/Konjunktionaladverb; steht oft nach dem Verb.","example":"Ich komme später, ich bin nämlich noch bei der Arbeit.","exampleEn":"I'm coming later, because I'm still at work.","example2":"Wir brauchen zwei Dinge, nämlich Brot und Milch.","example2En":"We need two things, namely bread and milk."},{"de":"die Naturkosmetik","en":"natural cosmetics","pos":"noun","plural":"","meanings":[{"en":"cosmetics made from natural ingredients","de":"Kosmetik aus natürlichen Inhaltsstoffen"}],"rule":"Femininum, unzählbar (kein Plural).","example":"Sie kauft nur Naturkosmetik.","exampleEn":"She only buys natural cosmetics.","example2":"Naturkosmetik enthält keine künstlichen Duftstoffe.","example2En":"Natural cosmetics contain no artificial fragrances."},{"de":"das Navigationsgerät","en":"navigation device (GPS)","pos":"noun","plural":"die Navigationsgeräte","meanings":[{"en":"GPS navigation device","de":"das Gerät zur Routenführung"}],"rule":"Neutrum; Kurzform 'das Navi' (die Navis) ist im Alltag üblicher.","example":"Ich benutze im Auto ein Navigationsgerät.","exampleEn":"I use a navigation device in the car.","example2":"Das Navi zeigt uns den kürzesten Weg.","example2En":"The GPS shows us the shortest way."},{"de":"die Nebenwirkung","en":"side effect","pos":"noun","plural":"die Nebenwirkungen","meanings":[{"en":"side effect (usually of medicine)","de":"unerwünschte Wirkung eines Medikaments"}],"rule":"Femininum; oft im Plural bei Medikamenten: 'Nebenwirkungen'.","example":"Diese Tablette hat keine Nebenwirkungen.","exampleEn":"This pill has no side effects.","example2":"Lesen Sie den Beipackzettel wegen möglicher Nebenwirkungen.","example2En":"Read the package insert for possible side effects."},{"de":"der Neffe","en":"nephew","pos":"noun","plural":"die Neffen","meanings":[{"en":"nephew","de":"der Sohn des Bruders/der Schwester"}],"rule":"Maskulinum, schwache Deklination: den/dem/des Neffen (nicht 'Neffe' im Akkusativ).","example":"Mein Neffe ist fünf Jahre alt.","exampleEn":"My nephew is five years old.","example2":"Wir besuchen unseren Neffen am Sonntag.","example2En":"We're visiting our nephew on Sunday."},{"de":"nennen","en":"to name, to call","pos":"verb","plural":"","meanings":[{"en":"to name/call someone or something","de":"einen Namen geben, bezeichnen"},{"en":"to mention, state","de":"angeben, sagen"}],"rule":"Unregelmäßig: nennt, nannte, hat genannt.","example":"Sie nennt ihren Sohn immer 'Schatz'.","exampleEn":"She always calls her son 'sweetheart'.","example2":"Können Sie mir bitte Ihren Namen nennen?","example2En":"Could you please state your name?"},{"de":"nervös","en":"nervous","pos":"adjective","plural":"","meanings":[{"en":"nervous, anxious","de":"unruhig, aufgeregt"}],"rule":"Regelmäßige Steigerung: nervös, nervöser, am nervösesten.","example":"Vor der Prüfung war ich sehr nervös.","exampleEn":"I was very nervous before the exam.","example2":"Er wird nervös, wenn er fliegen muss.","example2En":"He gets nervous when he has to fly."},{"de":"der Newsletter","en":"newsletter","pos":"noun","plural":"die Newsletter","meanings":[{"en":"email newsletter","de":"regelmäßige E-Mail mit Infos/Neuigkeiten"}],"rule":"Maskulin, aus dem Englischen; Plural bleibt meist gleich: der/die Newsletter.","example":"Ich habe den Newsletter von der Firma abonniert.","exampleEn":"I subscribed to the company's newsletter.","example2":"Der Newsletter kommt jeden Freitag per E-Mail.","example2En":"The newsletter arrives every Friday by email."},{"de":"die Nichte","en":"niece","pos":"noun","plural":"die Nichten","meanings":[{"en":"niece","de":"Tochter des Bruders oder der Schwester"}],"rule":"Feminin; Gegenstück ist 'der Neffe' (Neffe).","example":"Meine Nichte ist erst fünf Jahre alt.","exampleEn":"My niece is only five years old.","example2":"Wir besuchen meine Nichte am Wochenende.","example2En":"We are visiting my niece this weekend."},{"de":"niemand","en":"nobody, no one","pos":"pronoun","plural":"","meanings":[{"en":"no person, nobody","de":"keine Person"}],"rule":"Indefinitpronomen; kann dekliniert werden (niemand/niemandem/niemanden), Alltag oft unverändert.","example":"Niemand war zu Hause.","exampleEn":"Nobody was home.","example2":"Ich kenne hier niemanden.","example2En":"I don't know anyone here."},{"de":"normal","en":"normal","pos":"adjective","plural":"","meanings":[{"en":"usual, typical","de":"üblich, gewöhnlich"}],"rule":"Regelmäßige Steigerung: normal, normaler, am normalsten.","example":"Das ist ein ganz normaler Tag.","exampleEn":"That's a completely normal day.","example2":"Ist es normal, dass der Bus so oft verspätet ist?","example2En":"Is it normal for the bus to be late so often?"},{"de":"normalerweise","en":"normally, usually","pos":"adverb","plural":"","meanings":[{"en":"usually, as a rule","de":"in der Regel, meistens"}],"rule":"Adverb, keine Steigerung; steht oft am Satzanfang oder nach dem Verb.","example":"Normalerweise stehe ich um sieben Uhr auf.","exampleEn":"I normally get up at seven o'clock.","example2":"Der Zug kommt normalerweise pünktlich.","example2En":"The train is usually on time."},{"de":"die Note","en":"grade, mark; (musical) note","pos":"noun","plural":"die Noten","meanings":[{"en":"school grade/mark","de":"Bewertung in der Schule"},{"en":"musical note","de":"Zeichen für einen Ton in der Musik"}],"rule":"Feminin; Plural 'Noten' auch für 'sheet music'.","example":"Sie hat eine gute Note in Mathe bekommen.","exampleEn":"She got a good grade in math.","example2":"Er kann die Noten auf dem Klavier lesen.","example2En":"He can read the notes on the piano."},{"de":"notieren","en":"to note down, to write down","pos":"verb","plural":"","meanings":[{"en":"to write down, jot down","de":"aufschreiben"}],"rule":"Regelmäßiges Verb: notiert, notierte, hat notiert.","example":"Ich notiere mir die Telefonnummer.","exampleEn":"I'm noting down the phone number.","example2":"Bitte notieren Sie den Termin im Kalender.","example2En":"Please note the appointment in the calendar."},{"de":"nötig","en":"necessary","pos":"adjective","plural":"","meanings":[{"en":"necessary, needed","de":"notwendig, erforderlich"}],"rule":"Regelmäßige Steigerung: nötig, nötiger, am nötigsten; oft mit 'sein' + Infinitiv.","example":"Ist es nötig, den Arzt anzurufen?","exampleEn":"Is it necessary to call the doctor?","example2":"Das ist nicht nötig, danke.","example2En":"That's not necessary, thanks."},{"de":"der Nulltarif","en":"free of charge (zero rate)","pos":"noun","plural":"","meanings":[{"en":"free of charge, no cost","de":"kostenlos, ohne Bezahlung"}],"rule":"Maskulin; meist in der festen Wendung 'zum Nulltarif' (kostenlos). Kein üblicher Plural.","example":"Kinder fahren zum Nulltarif mit dem Bus.","exampleEn":"Children ride the bus free of charge.","example2":"Das Parken ist hier leider nicht zum Nulltarif.","example2En":"Parking here is unfortunately not free."},{"de":"die Nummer","en":"number","pos":"noun","plural":"die Nummern","meanings":[{"en":"number (phone, size, etc.)","de":"Zahl, z. B. Telefonnummer"}],"rule":"Feminin; häufig in 'Telefonnummer', 'Hausnummer'.","example":"Kannst du mir deine Nummer geben?","exampleEn":"Can you give me your number?","example2":"Die Schuhe sind eine Nummer zu klein.","example2En":"The shoes are one size too small."},{"de":"nutzen","en":"to use","pos":"verb","plural":"","meanings":[{"en":"to use, make use of","de":"benutzen, verwenden"}],"rule":"Regelmäßiges Verb: nutzt, nutzte, hat genutzt; Akkusativobjekt.","example":"Wir nutzen den Computer für die Arbeit.","exampleEn":"We use the computer for work.","example2":"Er nutzt die Gelegenheit, um Deutsch zu üben.","example2En":"He uses the opportunity to practice German."},{"de":"ob","en":"whether, if","pos":"conjunction","plural":"","meanings":[{"en":"whether, if (in indirect questions)","de":"leitet indirekte Fragen ein"}],"rule":"Konjunktion, Verb steht am Satzende (Nebensatz).","example":"Ich weiß nicht, ob er kommt.","exampleEn":"I don't know whether he's coming.","example2":"Sie fragt, ob das Geschäft noch offen ist.","example2En":"She asks if the shop is still open."},{"de":"oben","en":"above, upstairs, at the top","pos":"adverb","plural":"","meanings":[{"en":"at the top, upstairs","de":"an höherer Stelle, im oberen Bereich"}],"rule":"Ortsadverb; Gegenteil 'unten'; Richtung: 'nach oben'.","example":"Das Badezimmer ist oben.","exampleEn":"The bathroom is upstairs.","example2":"Die Tasche steht oben auf dem Schrank.","example2En":"The bag is on top of the cupboard."},{"de":"die Oberschule","en":"secondary school","pos":"noun","plural":"die Oberschulen","meanings":[{"en":"secondary/upper school","de":"weiterführende Schule"}],"rule":"Feminin; regionaler Begriff, ähnlich wie 'Gymnasium' oder 'weiterführende Schule'.","example":"Meine Tochter geht auf die Oberschule.","exampleEn":"My daughter goes to secondary school.","example2":"Nach der Grundschule kommt die Oberschule.","example2En":"After primary school comes secondary school."},{"de":"der Ofen","en":"oven, stove","pos":"noun","plural":"die Öfen","meanings":[{"en":"oven","de":"Gerät zum Backen oder Heizen"}],"rule":"Maskulin; Plural mit Umlaut: die Öfen.","example":"Der Kuchen ist im Ofen.","exampleEn":"The cake is in the oven.","example2":"Im Winter heizen wir mit einem alten Ofen.","example2En":"In winter we heat with an old stove."},{"de":"der Ohrring","en":"earring","pos":"noun","plural":"die Ohrringe","meanings":[{"en":"earring","de":"Schmuck fürs Ohr"}],"rule":"Maskulin; zusammengesetzt aus 'Ohr' + 'Ring'.","example":"Sie trägt goldene Ohrringe.","exampleEn":"She is wearing gold earrings.","example2":"Ich habe einen Ohrring verloren.","example2En":"I lost one earring."},{"de":"olympisch","en":"Olympic","pos":"adjective","plural":"","meanings":[{"en":"Olympic","de":"zu den Olympischen Spielen gehörend"}],"rule":"Keine Steigerung üblich; großgeschrieben in der festen Wendung 'Olympische Spiele' (Eigenname), sonst klein wie in 'olympischer Rekord'.","example":"Die Olympischen Spiele finden alle vier Jahre statt.","exampleEn":"The Olympic Games take place every four years.","example2":"Er hat einen olympischen Rekord gebrochen.","example2En":"He broke an Olympic record."},{"de":"das Online-Banking","en":"online banking","pos":"noun","plural":"","meanings":[{"en":"online banking","de":"Bankgeschäfte über das Internet erledigen"}],"rule":"Neutrum; unzählbar, kein Plural.","example":"Ich mache meine Überweisungen per Online-Banking.","exampleEn":"I do my transfers via online banking.","example2":"Das Online-Banking ist rund um die Uhr verfügbar.","example2En":"Online banking is available around the clock."},{"de":"das Open-Air-Konzert","en":"open-air concert","pos":"noun","plural":"die Open-Air-Konzerte","meanings":[{"en":"outdoor music concert","de":"Konzert im Freien"}],"rule":"Zusammensetzung aus Englisch 'open air' und 'Konzert'; Plural mit -e.","example":"Im Sommer gehen wir oft zu einem Open-Air-Konzert.","exampleEn":"In summer we often go to an open-air concert.","example2":"Das Open-Air-Konzert war leider wegen Regen abgesagt.","example2En":"The open-air concert was unfortunately cancelled because of rain."},{"de":"die Option","en":"option; choice","pos":"noun","plural":"die Optionen","meanings":[{"en":"a choice or possibility","de":"Möglichkeit, Wahl"}],"rule":"Feminines Substantiv auf -ion, Plural immer -en.","example":"Wir haben mehrere Optionen für den Urlaub.","exampleEn":"We have several options for the vacation.","example2":"Diese Option ist leider zu teuer.","example2En":"This option is unfortunately too expensive."},{"de":"ordnungsgemäß","en":"in an orderly manner; properly","pos":"adjective","plural":"","meanings":[{"en":"done correctly according to rules/regulations","de":"den Vorschriften entsprechend, vorschriftsmäßig"}],"rule":"Keine unregelmäßige Steigerung; wird meist adverbial gebraucht, oft mit Verben wie 'entsorgen', 'lagern', 'durchführen'.","example":"Bitte stellen Sie die Kisten ordnungsgemäß ins Lager.","exampleEn":"Please place the boxes properly in the storage room.","example2":"Der Müll muss ordnungsgemäß entsorgt werden.","example2En":"The waste must be disposed of properly."},{"de":"die Parfümerie","en":"perfume shop","pos":"noun","plural":"die Parfümerien","meanings":[{"en":"a shop selling perfumes and cosmetics","de":"Geschäft für Parfüm und Kosmetik"}],"rule":"Feminines Substantiv auf -ie, Plural -ien.","example":"Ich kaufe mein Parfüm immer in dieser Parfümerie.","exampleEn":"I always buy my perfume at this perfume shop.","example2":"Die Parfümerie in der Innenstadt hat heute geschlossen.","example2En":"The perfume shop downtown is closed today."},{"de":"passieren","en":"to happen","pos":"verb","plural":"","meanings":[{"en":"to happen, occur","de":"geschehen"},{"en":"to pass (a place, e.g. formal/technical)","de":"vorbeikommen an etwas"}],"rule":"Perfekt mit sein: ist passiert; meist unpersönlich: 'Was ist passiert?'","example":"Was ist gestern passiert?","exampleEn":"What happened yesterday?","example2":"Der Unfall ist an der Kreuzung passiert.","example2En":"The accident happened at the intersection."},{"de":"das Pech","en":"bad luck","pos":"noun","plural":"","meanings":[{"en":"bad luck, misfortune","de":"Unglück"}],"rule":"Unzählbar, kein Plural; oft in 'Pech haben'.","example":"Ich habe heute Pech gehabt, mein Auto ist kaputt.","exampleEn":"I had bad luck today, my car broke down.","example2":"So ein Pech, dass es regnet!","example2En":"What bad luck that it's raining!"},{"de":"die Personalabteilung","en":"human resources department","pos":"noun","plural":"die Personalabteilungen","meanings":[{"en":"the HR department of a company","de":"Abteilung für Personalfragen"}],"rule":"Zusammensetzung aus 'Personal' + 'Abteilung'; Plural -en.","example":"Bitte wenden Sie sich an die Personalabteilung.","exampleEn":"Please contact the human resources department.","example2":"Die Personalabteilung bearbeitet meinen Vertrag.","example2En":"The HR department is processing my contract."},{"de":"der Personalausweis","en":"identity card","pos":"noun","plural":"die Personalausweise","meanings":[{"en":"official ID card","de":"amtliches Ausweisdokument"}],"rule":"Maskulines Substantiv, Plural -e.","example":"Zeigen Sie bitte Ihren Personalausweis.","exampleEn":"Please show your identity card.","example2":"Ich habe meinen Personalausweis verloren.","example2En":"I lost my identity card."},{"de":"das Personalbüro","en":"personnel office","pos":"noun","plural":"die Personalbüros","meanings":[{"en":"office handling personnel matters","de":"Büro für Personalfragen"}],"rule":"Neutrales Substantiv, Plural -s (wie 'Büro').","example":"Das Personalbüro ist im dritten Stock.","exampleEn":"The personnel office is on the third floor.","example2":"Ich habe einen Termin im Personalbüro.","example2En":"I have an appointment at the personnel office."}]},{"id":"a2-14","title":"A2 · P–R (14)","level":"A2","words":[{"de":"der Personalleiter / die Personalleiterin","en":"head of human resources","pos":"noun","plural":"die Personalleiter / die Personalleiterinnen","meanings":[{"en":"person in charge of HR department","de":"Leiter/in der Personalabteilung"}],"rule":"Maskulin -leiter, feminin -leiterin; Plural maskulin bleibt gleich (der Leiter -> die Leiter).","example":"Der Personalleiter hat das Bewerbungsgespräch geführt.","exampleEn":"The head of HR conducted the job interview.","example2":"Die Personalleiterin entscheidet über neue Stellen.","example2En":"The head of HR decides on new positions."},{"de":"persönlich","en":"personal; in person","pos":"adjective","plural":"","meanings":[{"en":"private, individual","de":"privat, individuell"},{"en":"in person, face to face","de":"selbst, direkt"}],"rule":"Regelmäßige Steigerung: persönlich, persönlicher, am persönlichsten (selten gesteigert).","example":"Das ist eine persönliche Frage.","exampleEn":"That's a personal question.","example2":"Ich möchte Sie gern persönlich kennenlernen.","example2En":"I would like to meet you in person."},{"de":"die Pfanne","en":"frying pan","pos":"noun","plural":"die Pfannen","meanings":[{"en":"pan used for frying","de":"Kochgeschirr zum Braten"}],"rule":"Feminines Substantiv, Plural -n.","example":"Ich brate das Ei in der Pfanne.","exampleEn":"I fry the egg in the pan.","example2":"Die Pfanne ist noch sehr heiß.","example2En":"The pan is still very hot."},{"de":"der Pfennig","en":"pfennig (old German coin)","pos":"noun","plural":"die Pfennige","meanings":[{"en":"former small German currency unit","de":"alte deutsche Münze, 1/100 Mark"}],"rule":"Maskulines Substantiv, Plural -e; heute historisch, ersetzt durch Cent.","example":"Früher kostete ein Brötchen nur wenige Pfennige.","exampleEn":"In the past a roll only cost a few pfennigs.","example2":"Meine Oma sammelt alte Pfennige.","example2En":"My grandma collects old pfennigs."},{"de":"die Pflicht","en":"duty, obligation","pos":"noun","plural":"die Pflichten","meanings":[{"en":"a moral or legal obligation","de":"Verpflichtung"}],"rule":"Feminines Substantiv, Plural -en.","example":"Pünktlich zu sein ist meine Pflicht.","exampleEn":"Being punctual is my duty.","example2":"Er hat viele Pflichten im Haushalt.","example2En":"He has many duties in the household."},{"de":"die Physik","en":"physics","pos":"noun","plural":"","meanings":[{"en":"the science of physics","de":"Naturwissenschaft"}],"rule":"Unzählbar, kein Plural; Schulfach.","example":"Physik ist mein Lieblingsfach.","exampleEn":"Physics is my favorite subject.","example2":"Wir haben heute drei Stunden Physik.","example2En":"We have three hours of physics today."},{"de":"das Pilates","en":"Pilates","pos":"noun","plural":"","meanings":[{"en":"exercise method for core strength and flexibility","de":"Fitnesstraining für Rumpf und Beweglichkeit"}],"rule":"Unzählbar, kein Artikel im Alltag nötig; als Substantiv neutrum.","example":"Ich mache jeden Dienstag Pilates.","exampleEn":"I do Pilates every Tuesday.","example2":"Pilates stärkt die Rückenmuskulatur.","example2En":"Pilates strengthens the back muscles."},{"de":"der Pilot / die Pilotin","en":"pilot","pos":"noun","plural":"die Piloten / die Pilotinnen","meanings":[{"en":"person who flies an aircraft","de":"Flugzeugführer/in"}],"rule":"Maskulin -n-Deklination (der Pilot, den/dem/des Piloten); feminin -in.","example":"Der Pilot landet das Flugzeug sicher.","exampleEn":"The pilot lands the airplane safely.","example2":"Sie möchte Pilotin werden.","example2En":"She wants to become a pilot."},{"de":"die PIN","en":"PIN (personal identification number)","pos":"noun","plural":"die PINs","meanings":[{"en":"secret numeric code for cards/devices","de":"Geheimzahl für Karte oder Handy"}],"rule":"Feminines Substantiv (die PIN), Plural -s; oft ohne Artikel im Alltag genannt.","example":"Bitte geben Sie Ihre PIN ein.","exampleEn":"Please enter your PIN.","example2":"Ich habe meine PIN vergessen.","example2En":"I forgot my PIN."},{"de":"planmäßig","en":"as scheduled; on time","pos":"adjective","plural":"","meanings":[{"en":"as scheduled/planned","de":"wie geplant"}],"rule":"Adjective/adverb, no irregular comparison; often used with trains/flights/plans.","example":"Der Zug kommt planmäßig um 9 Uhr an.","exampleEn":"The train arrives on schedule at 9 o'clock.","example2":"Der Flug startet planmäßig.","example2En":"The flight departs as scheduled."},{"de":"die Planung","en":"planning","pos":"noun","plural":"die Planungen","meanings":[{"en":"the act of planning","de":"das Planen"}],"rule":"Feminine noun formed from planen + -ung; -ung nouns are always feminine.","example":"Die Planung der Reise dauert lange.","exampleEn":"Planning the trip takes a long time.","example2":"Wir sind noch in der Planung.","example2En":"We are still in the planning stage."},{"de":"plötzlich","en":"suddenly","pos":"adjective","plural":"","meanings":[{"en":"happening suddenly, unexpectedly","de":"auf einmal, unerwartet"}],"rule":"Adjective/adverb, no comparison forms typically used; often at sentence start.","example":"Plötzlich fing es an zu regnen.","exampleEn":"Suddenly it started to rain.","example2":"Er wurde plötzlich krank.","example2En":"He suddenly became ill."},{"de":"der Poetry-Slam","en":"poetry slam","pos":"noun","plural":"die Poetry-Slams","meanings":[{"en":"a spoken-word poetry competition","de":"ein Dichterwettstreit mit Vortrag"}],"rule":"Loanword from English; masculine article 'der' commonly used: der Poetry-Slam.","example":"Am Freitag gehen wir zum Poetry-Slam.","exampleEn":"On Friday we're going to the poetry slam.","example2":"Sie liest ihr Gedicht beim Poetry-Slam.","example2En":"She reads her poem at the poetry slam."},{"de":"die Politik","en":"politics; policy","pos":"noun","plural":"","meanings":[{"en":"politics (the field)","de":"das politische Geschehen"},{"en":"a policy","de":"eine bestimmte Strategie"}],"rule":"Feminine noun, usually uncountable (no plural).","example":"Er interessiert sich sehr für Politik.","exampleEn":"He is very interested in politics.","example2":"Die Politik der Firma hat sich geändert.","example2En":"The company's policy has changed."},{"de":"der Polizist / die Polizistin","en":"police officer","pos":"noun","plural":"die Polizisten / die Polizistinnen","meanings":[{"en":"a member of the police","de":"ein Mitglied der Polizei"}],"rule":"Masculine noun follows -n/-en weak declension; feminine adds -in.","example":"Der Polizist hilft uns bei der Suche.","exampleEn":"The police officer helps us search.","example2":"Die Polizistin kontrolliert die Ausweise.","example2En":"The policewoman checks the IDs."},{"de":"preiswert","en":"good value; inexpensive","pos":"adjective","plural":"","meanings":[{"en":"cheap for good quality, good value","de":"günstig, gutes Preis-Leistungs-Verhältnis"}],"rule":"Regular comparison: preiswert, preiswerter, am preiswertesten.","example":"Das Hotel ist sehr preiswert.","exampleEn":"The hotel is very good value.","example2":"Ich suche ein preiswertes Fahrrad.","example2En":"I'm looking for an inexpensive bicycle."},{"de":"prima","en":"great; fine","pos":"adjective","plural":"","meanings":[{"en":"great, excellent (informal)","de":"sehr gut, toll"}],"rule":"Indeclinable adjective, no endings change; no comparison forms.","example":"Das Essen schmeckt prima!","exampleEn":"The food tastes great!","example2":"Prima, das passt gut.","example2En":"Great, that works well."},{"de":"privat","en":"private","pos":"adjective","plural":"","meanings":[{"en":"not public, personal","de":"nicht öffentlich, persönlich"}],"rule":"Regular adjective; comparison rarely used: privat, privater, am privatesten.","example":"Das ist meine private Adresse.","exampleEn":"That's my private address.","example2":"Wir treffen uns privat, nicht im Büro.","example2En":"We're meeting privately, not at the office."},{"de":"professionell","en":"professional","pos":"adjective","plural":"","meanings":[{"en":"done with skill, expertise","de":"fachmännisch, mit Können"}],"rule":"Regular comparison: professionell, professioneller, am professionellsten.","example":"Sie arbeitet sehr professionell.","exampleEn":"She works very professionally.","example2":"Er ist ein professioneller Fotograf.","example2En":"He is a professional photographer."},{"de":"das Programm","en":"program; schedule","pos":"noun","plural":"die Programme","meanings":[{"en":"a schedule of events","de":"ein Ablaufplan"},{"en":"a computer program","de":"ein Computerprogramm"}],"rule":"Neuter noun.","example":"Wir haben ein volles Programm heute.","exampleEn":"We have a full schedule today.","example2":"Er installiert ein neues Programm.","example2En":"He is installing a new program."},{"de":"Prost","en":"cheers!","pos":"other","plural":"","meanings":[{"en":"toast said before drinking","de":"Trinkspruch"}],"rule":"Interjection, invariable, used when clinking glasses.","example":"Prost! Auf deine Gesundheit!","exampleEn":"Cheers! To your health!","example2":"Alle sagten Prost und tranken.","example2En":"Everyone said cheers and drank."},{"de":"das Protokoll","en":"minutes; report; protocol","pos":"noun","plural":"die Protokolle","meanings":[{"en":"written minutes of a meeting","de":"schriftliche Aufzeichnung einer Besprechung"},{"en":"official record (e.g. police report)","de":"amtlicher Bericht"}],"rule":"Neuter noun; common phrase: Protokoll führen (to take minutes).","example":"Wer führt heute das Protokoll?","exampleEn":"Who is taking the minutes today?","example2":"Die Polizei hat ein Protokoll geschrieben.","example2En":"The police wrote up a report."},{"de":"die Prüfung","en":"exam; test","pos":"noun","plural":"die Prüfungen","meanings":[{"en":"an examination/test","de":"ein Test, eine Kontrolle des Wissens"}],"rule":"Feminine noun from prüfen + -ung; common: eine Prüfung bestehen (to pass an exam).","example":"Morgen habe ich eine wichtige Prüfung.","exampleEn":"Tomorrow I have an important exam.","example2":"Sie hat die Prüfung bestanden.","example2En":"She passed the exam."},{"de":"das Prüfungstraining","en":"exam preparation/practice","pos":"noun","plural":"","meanings":[{"en":"practice/training for an exam","de":"Üben für eine Prüfung"}],"rule":"Neuter compound noun (Prüfung + Training); usually no plural.","example":"Das Prüfungstraining hilft uns sehr.","exampleEn":"The exam practice helps us a lot.","example2":"Wir machen jede Woche Prüfungstraining.","example2En":"We do exam practice every week."},{"de":"der Quatsch","en":"nonsense","pos":"noun","plural":"","meanings":[{"en":"nonsense, silly talk","de":"Unsinn"}],"rule":"Masculine noun, uncountable; informal, common exclamation: So ein Quatsch!","example":"Das ist doch Quatsch!","exampleEn":"That's nonsense!","example2":"Mach keinen Quatsch!","example2En":"Don't be silly / don't mess around!"},{"de":"die Radtour","en":"bike tour/ride","pos":"noun","plural":"die Radtouren","meanings":[{"en":"a trip/tour by bicycle","de":"eine Tour mit dem Fahrrad"}],"rule":"Feminine compound noun (Rad + Tour).","example":"Am Sonntag machen wir eine Radtour.","exampleEn":"On Sunday we're going on a bike ride.","example2":"Die Radtour war 30 Kilometer lang.","example2En":"The bike tour was 30 kilometers long."},{"de":"der Rat","en":"advice","pos":"noun","plural":"","meanings":[{"en":"advice, counsel","de":"ein Vorschlag, eine Empfehlung"}],"rule":"Masculine noun; in the sense 'advice' it is normally uncountable (no plural); for multiple pieces of advice use 'die Ratschläge' (from der Ratschlag), not a plural of Rat itself.","example":"Kannst du mir einen Rat geben?","exampleEn":"Can you give me some advice?","example2":"Ich brauche deinen Rat.","example2En":"I need your advice."},{"de":"der Ratschlag","en":"piece of advice","pos":"noun","plural":"die Ratschläge","meanings":[{"en":"advice, suggestion","de":"ein Tipp, den man jemandem gibt"}],"rule":"Immer mit Artikel 'der'; oft in der Wendung 'jemandem einen Ratschlag geben'.","example":"Mein Vater hat mir einen guten Ratschlag gegeben.","exampleEn":"My father gave me a good piece of advice.","example2":"Kannst du mir einen Ratschlag geben?","example2En":"Can you give me a piece of advice?"},{"de":"reagieren","en":"to react","pos":"verb","plural":"","meanings":[{"en":"to react, respond (to something)","de":"auf etwas antworten oder handeln"}],"rule":"Regelmäßiges Verb; + auf + Akkusativ: 'auf etwas reagieren'. Perfekt: hat reagiert.","example":"Sie hat schnell auf die Frage reagiert.","exampleEn":"She reacted quickly to the question.","example2":"Er reagiert nicht auf meine E-Mails.","example2En":"He doesn't respond to my emails."},{"de":"der Realschulabschluss","en":"intermediate secondary school diploma","pos":"noun","plural":"die Realschulabschlüsse","meanings":[{"en":"school-leaving certificate from a Realschule","de":"das Zeugnis am Ende der Realschule"}],"rule":"Zusammensetzung aus 'Realschule' + 'Abschluss'; der Artikel richtet sich nach 'Abschluss' (der).","example":"Er hat seinen Realschulabschluss mit guten Noten gemacht.","exampleEn":"He got his intermediate school diploma with good grades.","example2":"Für die Ausbildung braucht man mindestens einen Realschulabschluss.","example2En":"For the apprenticeship you need at least an intermediate school diploma."},{"de":"die Realschule","en":"intermediate secondary school","pos":"noun","plural":"die Realschulen","meanings":[{"en":"type of German secondary school (between Hauptschule and Gymnasium)","de":"eine weiterführende Schule in Deutschland"}],"rule":"Feminines Substantiv; Schulform im deutschen Schulsystem.","example":"Meine Tochter geht auf die Realschule.","exampleEn":"My daughter goes to the Realschule.","example2":"Nach der Grundschule wechselte er auf die Realschule.","example2En":"After primary school he moved to the Realschule."},{"de":"die Rechnung","en":"invoice, bill","pos":"noun","plural":"die Rechnungen","meanings":[{"en":"invoice, bill","de":"ein Dokument, das zeigt, was man bezahlen muss"},{"en":"calculation (math)","de":"eine Aufgabe in Mathematik"}],"rule":"Feminines Substantiv; 'eine Rechnung bezahlen' = to pay a bill.","example":"Ich muss noch die Rechnung für das Hotel bezahlen.","exampleEn":"I still have to pay the hotel bill.","example2":"Die Rechnung ist ganz einfach: 5 mal 3 ist 15.","example2En":"The calculation is very simple: 5 times 3 is 15."},{"de":"der Rechnungsbetrag","en":"invoice amount","pos":"noun","plural":"die Rechnungsbeträge","meanings":[{"en":"the total amount to be paid on an invoice","de":"die Summe, die man laut Rechnung zahlen muss"}],"rule":"Zusammensetzung aus 'Rechnung' + 'Betrag'; Artikel 'der' wie 'der Betrag'.","example":"Bitte überweisen Sie den Rechnungsbetrag bis zum 10. des Monats.","exampleEn":"Please transfer the invoice amount by the 10th of the month.","example2":"Der Rechnungsbetrag liegt bei 250 Euro.","example2En":"The invoice amount is 250 euros."},{"de":"die Rechnungsnummer","en":"invoice number","pos":"noun","plural":"die Rechnungsnummern","meanings":[{"en":"the identification number of an invoice","de":"die Nummer, mit der man eine Rechnung erkennt"}],"rule":"Zusammensetzung aus 'Rechnung' + 'Nummer'; Artikel 'die' wie 'die Nummer'.","example":"Geben Sie bitte die Rechnungsnummer bei der Reklamation an.","exampleEn":"Please state the invoice number when making a complaint.","example2":"Die Rechnungsnummer finden Sie oben rechts.","example2En":"You will find the invoice number at the top right."},{"de":"die Rede","en":"speech","pos":"noun","plural":"die Reden","meanings":[{"en":"speech, talk","de":"ein öffentlicher Vortrag"}],"rule":"Feminines Substantiv; 'eine Rede halten' = to give a speech.","example":"Der Bürgermeister hat eine lange Rede gehalten.","exampleEn":"The mayor gave a long speech.","example2":"Sie musste bei der Hochzeit eine Rede halten.","example2En":"She had to give a speech at the wedding."},{"de":"die Regel","en":"rule","pos":"noun","plural":"die Regeln","meanings":[{"en":"rule, regulation","de":"eine Vorschrift, die man befolgen muss"}],"rule":"Feminines Substantiv; 'in der Regel' = usually.","example":"Im Klassenzimmer gibt es klare Regeln.","exampleEn":"There are clear rules in the classroom.","example2":"In der Regel komme ich pünktlich zur Arbeit.","example2En":"As a rule, I come to work on time."},{"de":"der Regen","en":"rain","pos":"noun","plural":"","meanings":[{"en":"rain","de":"Wasser, das vom Himmel fällt"}],"rule":"Maskulines Substantiv, meist unzählbar, kein Plural im Alltag.","example":"Heute regnet es, nimm einen Schirm gegen den Regen mit.","exampleEn":"It's raining today, take an umbrella against the rain.","example2":"Nach dem Regen kam die Sonne raus.","example2En":"After the rain the sun came out."},{"de":"der Regenschirm","en":"umbrella","pos":"noun","plural":"die Regenschirme","meanings":[{"en":"umbrella","de":"ein Gegenstand, der vor Regen schützt"}],"rule":"Zusammensetzung aus 'Regen' + 'Schirm'; Artikel 'der' wie 'der Schirm'.","example":"Ich habe meinen Regenschirm zu Hause vergessen.","exampleEn":"I forgot my umbrella at home.","example2":"Nimm einen Regenschirm mit, es soll regnen.","example2En":"Take an umbrella, it's supposed to rain."},{"de":"die Regie","en":"direction (film/theatre)","pos":"noun","plural":"","meanings":[{"en":"direction (of a film, play, etc.)","de":"die künstlerische Leitung bei Film oder Theater"}],"rule":"Feminines Substantiv, meist ohne Plural; 'Regie führen' = to direct.","example":"Der Film läuft unter der Regie von Wim Wenders.","exampleEn":"The film is directed by Wim Wenders.","example2":"Sie führt Regie bei dem neuen Theaterstück.","example2En":"She is directing the new play."},{"de":"reich","en":"rich","pos":"adjective","plural":"","meanings":[{"en":"rich, wealthy","de":"mit viel Geld oder Besitz"}],"rule":"Regelmäßige Steigerung: reich, reicher, am reichsten.","example":"Seine Familie ist sehr reich.","exampleEn":"His family is very rich.","example2":"Diese Region ist reich an Bodenschätzen.","example2En":"This region is rich in natural resources."},{"de":"reichlich","en":"plentiful, plenty of","pos":"adjective","plural":"","meanings":[{"en":"plentiful, ample; generously","de":"in großer Menge, mehr als genug"}],"rule":"Adjektiv/Adverb; Komparation (reichlicher, am reichlichsten) ist möglich, wird aber selten genutzt.","example":"Wir hatten reichlich Zeit für die Prüfung.","exampleEn":"We had plenty of time for the exam.","example2":"Es gab reichlich Essen auf der Party.","example2En":"There was plenty of food at the party."},{"de":"der Reichtum","en":"wealth","pos":"noun","plural":"die Reichtümer","meanings":[{"en":"wealth, riches","de":"großer Besitz an Geld oder Wertvollem"}],"rule":"Maskulines Substantiv; Plural 'die Reichtümer' meist im Sinn von 'Schätze'.","example":"Der Reichtum des Landes kommt vom Öl.","exampleEn":"The country's wealth comes from oil.","example2":"Er hat seinen Reichtum durch harte Arbeit aufgebaut.","example2En":"He built his wealth through hard work."},{"de":"die Reihenfolge","en":"order, sequence","pos":"noun","plural":"die Reihenfolgen","meanings":[{"en":"order, sequence","de":"die Ordnung, in der etwas kommt"}],"rule":"Feminines Substantiv; 'in der richtigen Reihenfolge' = in the correct order.","example":"Bitte bringen Sie die Karten in die richtige Reihenfolge.","exampleEn":"Please put the cards in the correct order.","example2":"Die Reihenfolge der Namen ist alphabetisch.","example2En":"The order of the names is alphabetical."},{"de":"die Reinigungsarbeiten","en":"cleaning work","pos":"noun","plural":"","meanings":[{"en":"cleaning work, cleaning operations","de":"Arbeiten, bei denen etwas sauber gemacht wird"}],"rule":"Nur im Plural gebräuchlich (Pluraletantum); zusammengesetzt aus 'Reinigung' + 'Arbeiten'.","example":"Wegen Reinigungsarbeiten ist das Schwimmbad heute geschlossen.","exampleEn":"Due to cleaning work, the swimming pool is closed today.","example2":"Die Reinigungsarbeiten im Bahnhof dauern bis Mittag.","example2En":"The cleaning work at the station lasts until noon."},{"de":"die Reisemöglichkeit","en":"travel option","pos":"noun","plural":"die Reisemöglichkeiten","meanings":[{"en":"option or possibility for travel","de":"eine Möglichkeit, irgendwohin zu reisen"}],"rule":"Zusammensetzung aus 'Reise' + 'Möglichkeit'; Artikel 'die' wie 'die Möglichkeit'.","example":"Es gibt viele Reisemöglichkeiten nach Berlin.","exampleEn":"There are many travel options to Berlin.","example2":"Welche Reisemöglichkeit ist am günstigsten?","example2En":"Which travel option is the cheapest?"},{"de":"reisen","en":"to travel","pos":"verb","plural":"","meanings":[{"en":"to travel","de":"eine Reise machen"}],"rule":"Perfekt mit sein: ist gereist. Regelmäßig (schwach).","example":"Wir reisen im Sommer nach Italien.","exampleEn":"We are travelling to Italy in summer.","example2":"Er reist gern mit dem Zug.","example2En":"He likes to travel by train."},{"de":"der Reisepass","en":"passport","pos":"noun","plural":"die Reisepässe","meanings":[{"en":"passport","de":"amtliches Dokument für Auslandsreisen"}],"rule":"Maskulin; zusammengesetzt aus 'Reise' + 'Pass'. Umlaut im Plural: Pässe.","example":"Hast du deinen Reisepass dabei?","exampleEn":"Do you have your passport with you?","example2":"Mein Reisepass ist noch drei Jahre gültig.","example2En":"My passport is still valid for three years."},{"de":"das Reiseziel","en":"travel destination","pos":"noun","plural":"die Reiseziele","meanings":[{"en":"destination (of a trip)","de":"Ort, den man bereisen will"}],"rule":"Neutrum; Kompositum aus 'Reise' + 'Ziel'.","example":"Unser Reiseziel ist Spanien.","exampleEn":"Our travel destination is Spain.","example2":"Welches Reiseziel gefällt dir am besten?","example2En":"Which destination do you like best?"},{"de":"reizen","en":"to irritate; to stimulate/tempt","pos":"verb","plural":"","meanings":[{"en":"to irritate (skin, eyes)","de":"unangenehm reagieren lassen"},{"en":"to tempt, appeal to","de":"Lust machen auf etwas"}],"rule":"Regelmäßig (schwach): reizt, reizte, hat gereizt.","example":"Der Rauch reizt meine Augen.","exampleEn":"The smoke irritates my eyes.","example2":"Die Idee reizt mich sehr.","example2En":"The idea really appeals to me."},{"de":"die Religion","en":"religion","pos":"noun","plural":"die Religionen","meanings":[{"en":"religion","de":"Glaube an eine höhere Macht"}],"rule":"Feminin; Fremdwort aus dem Lateinischen.","example":"In der Schule haben wir Religion als Fach.","exampleEn":"At school we have religion as a subject.","example2":"Welche Religion hat er?","example2En":"What is his religion?"}]},{"id":"a2-15","title":"A2 · R–S (15)","level":"A2","words":[{"de":"die Rente","en":"pension","pos":"noun","plural":"die Renten","meanings":[{"en":"pension (retirement income)","de":"Geld, das man nach der Arbeit bekommt"}],"rule":"Feminin; oft in 'in Rente gehen' = to retire.","example":"Meine Oma bekommt jeden Monat ihre Rente.","exampleEn":"My grandma gets her pension every month.","example2":"Mein Opa geht nächstes Jahr in Rente.","example2En":"My grandpa is retiring next year."},{"de":"reservieren","en":"to reserve, to book","pos":"verb","plural":"","meanings":[{"en":"to reserve, book (a table, room, seat)","de":"einen Platz im Voraus bestellen"}],"rule":"Regelmäßig (schwach): reserviert, reservierte, hat reserviert.","example":"Ich möchte einen Tisch für zwei Personen reservieren.","exampleEn":"I would like to reserve a table for two.","example2":"Haben Sie das Zimmer schon reserviert?","example2En":"Have you already booked the room?"},{"de":"die Reservierung","en":"reservation, booking","pos":"noun","plural":"die Reservierungen","meanings":[{"en":"reservation, booking","de":"das Reservieren, die gebuchte Sache"}],"rule":"Feminin; Nomen zu 'reservieren'.","example":"Ich habe eine Reservierung für 20 Uhr.","exampleEn":"I have a reservation for 8 pm.","example2":"Die Reservierung ist auf meinen Namen.","example2En":"The reservation is under my name."},{"de":"der Respekt","en":"respect","pos":"noun","plural":"","meanings":[{"en":"respect","de":"Achtung vor einer Person"}],"rule":"Maskulin; unzählbar, kein Plural. Oft mit 'vor + Dativ'.","example":"Wir haben großen Respekt vor unserem Lehrer.","exampleEn":"We have great respect for our teacher.","example2":"Zeig etwas mehr Respekt!","example2En":"Show a bit more respect!"},{"de":"der Restaurantfachmann / die Restaurantfachfrau","en":"restaurant specialist (trained server)","pos":"noun","plural":"die Restaurantfachleute","meanings":[{"en":"qualified restaurant professional (waiter/waitress with training)","de":"ausgebildete Fachkraft im Restaurant"}],"rule":"Maskulin/Feminin; Ausbildungsberuf. Plural meist 'Restaurantfachleute'.","example":"Er macht eine Ausbildung zum Restaurantfachmann.","exampleEn":"He is training to become a restaurant specialist.","example2":"Die Restaurantfachfrau berät die Gäste bei der Weinauswahl.","example2En":"The restaurant specialist advises guests on wine selection."},{"de":"der Restmüll","en":"residual waste (general trash)","pos":"noun","plural":"","meanings":[{"en":"general/residual waste (non-recyclable)","de":"Müll, der nicht recycelt wird"}],"rule":"Maskulin; unzählbar, kein Plural. Gegensatz zu Biomüll, Papiermüll.","example":"Die Tonne für Restmüll ist grau.","exampleEn":"The bin for residual waste is grey.","example2":"Bitte wirf keine Batterien in den Restmüll.","example2En":"Please do not throw batteries in the residual waste."},{"de":"der Rettungswagen","en":"ambulance","pos":"noun","plural":"die Rettungswagen","meanings":[{"en":"ambulance","de":"Fahrzeug für Notfälle mit Verletzten oder Kranken"}],"rule":"Maskulin; Plural unverändert (der/die Rettungswagen).","example":"Der Rettungswagen kam schnell zum Unfallort.","exampleEn":"The ambulance arrived quickly at the accident scene.","example2":"Ruf sofort einen Rettungswagen!","example2En":"Call an ambulance immediately!"},{"de":"rhythmisch","en":"rhythmic","pos":"adjective","plural":"","meanings":[{"en":"rhythmic","de":"mit einem regelmäßigen Rhythmus"}],"rule":"Regelmäßige Steigerung: rhythmisch, rhythmischer, am rhythmischsten.","example":"Die Musik hat einen rhythmischen Takt.","exampleEn":"The music has a rhythmic beat.","example2":"Sie tanzt sehr rhythmisch.","example2En":"She dances very rhythmically."},{"de":"die Richtung","en":"direction","pos":"noun","plural":"die Richtungen","meanings":[{"en":"direction","de":"Weg, in den man geht oder fährt"}],"rule":"Feminin; 'Richtung' + Ort ohne Artikel wirkt wie eine Präposition (der Bus fährt Richtung Zentrum). Mit Artikel: 'in Richtung + Genitiv' (in Richtung des Zentrums).","example":"Gehen Sie in diese Richtung.","exampleEn":"Go in this direction.","example2":"Der Bus fährt in Richtung Stadtzentrum.","example2En":"The bus goes in the direction of the city center."},{"de":"die Rolle","en":"role; roll","pos":"noun","plural":"die Rollen","meanings":[{"en":"role (in a film, play, situation)","de":"Funktion oder Part in einer Geschichte"},{"en":"roll (of something, e.g. tape, toilet paper)","de":"aufgerolltes Material"}],"rule":"Feminin. 'eine Rolle spielen' = to play a role / to matter.","example":"Sie spielt die Hauptrolle im Film.","exampleEn":"She plays the lead role in the film.","example2":"Kannst du eine Rolle Toilettenpapier kaufen?","example2En":"Can you buy a roll of toilet paper?"},{"de":"die Rückenmuskulatur","en":"back muscles","pos":"noun","plural":"","meanings":[{"en":"back muscles (muscular system of the back)","de":"Muskeln im Rücken"}],"rule":"Feminin; unzählbar, kein Plural. Kompositum aus 'Rücken' + 'Muskulatur'.","example":"Schwimmen stärkt die Rückenmuskulatur.","exampleEn":"Swimming strengthens the back muscles.","example2":"Meine Rückenmuskulatur tut nach dem Sport weh.","example2En":"My back muscles hurt after exercise."},{"de":"die Rückfahrt","en":"return journey (trip back)","pos":"noun","plural":"die Rückfahrten","meanings":[{"en":"return trip, journey back (by vehicle)","de":"Fahrt zurück zum Ausgangspunkt"}],"rule":"Feminin; Gegensatz zu 'Hinfahrt'.","example":"Die Rückfahrt dauert zwei Stunden.","exampleEn":"The return journey takes two hours.","example2":"Wir haben ein Ticket für Hin- und Rückfahrt gekauft.","example2En":"We bought a round-trip ticket."},{"de":"die Rückfrage","en":"follow-up question","pos":"noun","plural":"die Rückfragen","meanings":[{"en":"follow-up/clarifying question","de":"Frage zur Klärung"}],"rule":"Feminin; oft 'bei Rückfragen' = if you have any questions.","example":"Bei Rückfragen können Sie mich anrufen.","exampleEn":"If you have any questions, you can call me.","example2":"Ich habe noch eine Rückfrage zum Vertrag.","example2En":"I still have a follow-up question about the contract."},{"de":"der Saal","en":"hall","pos":"noun","plural":"die Säle","meanings":[{"en":"a large room for events","de":"großer Raum für Veranstaltungen"}],"rule":"Plural mit Umlaut: der Saal, die Säle.","example":"Die Party findet im großen Saal statt.","exampleEn":"The party takes place in the big hall.","example2":"Im Saal sitzen hundert Leute.","example2En":"A hundred people are sitting in the hall."},{"de":"das Schach","en":"chess","pos":"noun","plural":"","meanings":[{"en":"the board game chess","de":"ein Brettspiel"}],"rule":"Uncountable noun, always singular; used with spielen: Schach spielen.","example":"Mein Opa spielt gern Schach.","exampleEn":"My grandpa likes to play chess.","example2":"Kannst du Schach spielen?","example2En":"Can you play chess?"},{"de":"schaffen","en":"to manage / to create","pos":"verb","plural":"","meanings":[{"en":"to manage to do something","de":"etwas erfolgreich tun"},{"en":"to create","de":"herstellen, erschaffen"}],"rule":"Regular in the 'manage' sense (schafft, schaffte, geschafft); as 'create' it is irregular (schafft, schuf, geschaffen), but A2 mostly uses the regular 'manage to' meaning.","example":"Ich schaffe die Prüfung bestimmt.","exampleEn":"I'll definitely manage to pass the exam.","example2":"Wir haben die Arbeit heute geschafft.","example2En":"We finished the work today."},{"de":"der Schaffner / die Schaffnerin","en":"conductor (train/bus)","pos":"noun","plural":"die Schaffner / die Schaffnerinnen","meanings":[{"en":"person who checks tickets on a train or bus","de":"Person, die im Zug oder Bus Fahrkarten kontrolliert"}],"rule":"Agent noun with -er suffix, regular (strong) masculine declension: der Schaffner, des Schaffners; feminine adds -in, plural -innen.","example":"Der Schaffner kontrolliert die Fahrkarten.","exampleEn":"The conductor checks the tickets.","example2":"Die Schaffnerin war sehr freundlich.","example2En":"The (female) conductor was very friendly."},{"de":"der Schafskäse","en":"sheep's cheese / feta","pos":"noun","plural":"","meanings":[{"en":"cheese made from sheep's milk","de":"Käse aus Schafsmilch"}],"rule":"Uncountable noun, no plural.","example":"Im Salat ist Schafskäse.","exampleEn":"There's sheep's cheese in the salad.","example2":"Ich mag Schafskäse mit Tomaten.","example2En":"I like sheep's cheese with tomatoes."},{"de":"scharf","en":"sharp / spicy","pos":"adjective","plural":"","meanings":[{"en":"spicy (of food)","de":"stark gewürzt"},{"en":"sharp (of a blade)","de":"schneidend, gut geschliffen"}],"rule":"Comparison: scharf, schärfer, am schärfsten (Umlaut in comparative).","example":"Das Curry ist sehr scharf.","exampleEn":"The curry is very spicy.","example2":"Das Messer ist scharf.","example2En":"The knife is sharp."},{"de":"das Schaubild","en":"diagram / chart","pos":"noun","plural":"die Schaubilder","meanings":[{"en":"a diagram or chart showing information","de":"grafische Darstellung von Informationen"}],"rule":"Compound noun: schauen + Bild; plural adds -er.","example":"Das Schaubild zeigt die Zahlen von 2020.","exampleEn":"The chart shows the figures from 2020.","example2":"Sehen Sie sich das Schaubild genau an.","example2En":"Look at the diagram carefully."},{"de":"schauen","en":"to look","pos":"verb","plural":"","meanings":[{"en":"to look, to watch","de":"blicken, sehen"}],"rule":"Regular weak verb: schaut, schaute, geschaut. Common southern-German alternative to 'sehen/gucken'.","example":"Schau mal aus dem Fenster!","exampleEn":"Look out the window!","example2":"Wir schauen heute Abend einen Film.","example2En":"We're watching a movie tonight."},{"de":"das Schaufenster","en":"shop window","pos":"noun","plural":"die Schaufenster","meanings":[{"en":"a display window of a shop","de":"Fenster eines Geschäfts zum Präsentieren von Waren"}],"rule":"Compound: schauen + Fenster; plural = singular (like Fenster).","example":"Sie schaut die Kleider im Schaufenster an.","exampleEn":"She's looking at the clothes in the shop window.","example2":"Das Schaufenster ist schön dekoriert.","example2En":"The shop window is nicely decorated."},{"de":"der Schein","en":"note (money) / certificate","pos":"noun","plural":"die Scheine","meanings":[{"en":"a banknote","de":"Geldschein"},{"en":"a certificate","de":"Bescheinigung, Zeugnis"}],"rule":"Plural regular -e; often in compounds: Geldschein, Führerschein.","example":"Hast du einen Zehn-Euro-Schein?","exampleEn":"Do you have a ten-euro note?","example2":"Er hat den Schein für den Kurs bekommen.","example2En":"He got the certificate for the course."},{"de":"schick","en":"chic / stylish","pos":"adjective","plural":"","meanings":[{"en":"stylish, elegant","de":"elegant, modisch"}],"rule":"Regular comparison: schick, schicker, am schicksten.","example":"Das ist ein schickes Kleid.","exampleEn":"That's a stylish dress.","example2":"Du siehst heute sehr schick aus.","example2En":"You look very stylish today."},{"de":"schieben","en":"to push","pos":"verb","plural":"","meanings":[{"en":"to push something","de":"etwas mit Kraft bewegen"}],"rule":"Irregular: schiebt, schob, hat geschoben.","example":"Kannst du das Fahrrad schieben?","exampleEn":"Can you push the bike?","example2":"Er schob den Wagen aus der Garage.","example2En":"He pushed the car out of the garage."},{"de":"das Schild","en":"sign","pos":"noun","plural":"die Schilder","meanings":[{"en":"a sign or notice board","de":"Tafel mit Information"}],"rule":"Note: das Schild (sign, neuter) vs. der Schild (shield, masculine) - different genders, different meanings.","example":"Das Schild zeigt den Weg zum Bahnhof.","exampleEn":"The sign shows the way to the station.","example2":"An der Tür hängt ein Schild.","example2En":"There is a sign on the door."},{"de":"schlachten","en":"to slaughter","pos":"verb","plural":"","meanings":[{"en":"to kill an animal for meat","de":"ein Tier für Fleisch töten"}],"rule":"Regular weak verb: schlachtet, schlachtete, geschlachtet.","example":"Der Bauer schlachtet ein Schwein.","exampleEn":"The farmer slaughters a pig.","example2":"Früher hat man die Tiere selbst geschlachtet.","example2En":"In the past, people slaughtered the animals themselves."},{"de":"schlafen gehen","en":"to go to bed","pos":"phrase","plural":"","meanings":[{"en":"to go to sleep / go to bed","de":"sich schlafen legen"}],"rule":"Fixed verb + infinitive construction (not a true separable verb); only 'gehen' is conjugated: ich gehe schlafen; perfect tense uses sein: ist schlafen gegangen.","example":"Ich gehe jetzt schlafen.","exampleEn":"I'm going to bed now.","example2":"Die Kinder sind schon schlafen gegangen.","example2En":"The children have already gone to bed."},{"de":"schlagen","en":"to hit / to beat","pos":"verb","plural":"","meanings":[{"en":"to hit, strike","de":"mit Kraft treffen"},{"en":"to beat (in a game/sport)","de":"besiegen"}],"rule":"Irregular: schlägt, schlug, hat geschlagen.","example":"Er schlägt den Nagel in die Wand.","exampleEn":"He hammers the nail into the wall.","example2":"Unsere Mannschaft hat den Gegner geschlagen.","example2En":"Our team beat the opponent."},{"de":"schlank","en":"slim","pos":"adjective","plural":"","meanings":[{"en":"slim, slender (of a person)","de":"dünn, nicht dick"}],"rule":"Regular comparison: schlank, schlanker, am schlanksten.","example":"Sie ist sehr schlank.","exampleEn":"She is very slim.","example2":"Er möchte schlanker werden.","example2En":"He wants to become slimmer."},{"de":"schließlich","en":"finally / after all","pos":"adverb","plural":"","meanings":[{"en":"finally, in the end","de":"am Ende, zuletzt"},{"en":"after all (giving a reason)","de":"immerhin, denn schließlich"}],"rule":"Not gradable; often used as a connector at the start or middle of a sentence.","example":"Schließlich hat er die Antwort gefunden.","exampleEn":"Finally he found the answer.","example2":"Du musst helfen, schließlich bist du sein Bruder.","example2En":"You have to help, after all you're his brother."},{"de":"die Schmerztablette","en":"painkiller (pill)","pos":"noun","plural":"die Schmerztabletten","meanings":[{"en":"a tablet taken to relieve pain","de":"eine Tablette gegen Schmerzen"}],"rule":"Compound noun: Schmerz + Tablette; takes die like Tablette.","example":"Ich habe Kopfschmerzen und nehme eine Schmerztablette.","exampleEn":"I have a headache and I'm taking a painkiller.","example2":"Hast du eine Schmerztablette für mich?","example2En":"Do you have a painkiller for me?"},{"de":"der Schmuck","en":"jewelry","pos":"noun","plural":"","meanings":[{"en":"jewelry, ornaments worn on the body","de":"Ringe, Ketten, Ohrringe usw."}],"rule":"Uncountable noun, no plural form (used only in singular).","example":"Sie trägt gern goldenen Schmuck.","exampleEn":"She likes to wear gold jewelry.","example2":"Der Schmuck war ein Geschenk von ihrer Oma.","example2En":"The jewelry was a gift from her grandmother."},{"de":"das Schnäppchen","en":"bargain","pos":"noun","plural":"die Schnäppchen","meanings":[{"en":"something bought cheaply, a bargain","de":"ein günstiger Kauf"}],"rule":"Diminutive noun (-chen), always neuter; plural same as singular.","example":"Die Jacke war ein echtes Schnäppchen.","exampleEn":"The jacket was a real bargain.","example2":"Im Ausverkauf findet man oft Schnäppchen.","example2En":"You often find bargains during the sale."},{"de":"das Schnitzel","en":"schnitzel (breaded cutlet)","pos":"noun","plural":"die Schnitzel","meanings":[{"en":"a thin breaded and fried cutlet of meat","de":"ein paniertes, gebratenes Stück Fleisch"}],"rule":"Neuter noun; plural identical to singular.","example":"Wir bestellen Schnitzel mit Pommes.","exampleEn":"We're ordering schnitzel with fries.","example2":"Das Schnitzel war sehr lecker.","example2En":"The schnitzel was very tasty."},{"de":"der Schnupperkurs","en":"trial course, taster session","pos":"noun","plural":"die Schnupperkurse","meanings":[{"en":"a short introductory/trial course to try something out","de":"ein kurzer Kurs zum Ausprobieren"}],"rule":"Compound noun: schnuppern (to sniff/try out) + Kurs; masculine.","example":"Ich mache einen Schnupperkurs im Yogastudio.","exampleEn":"I'm doing a trial course at the yoga studio.","example2":"Der Schnupperkurs ist kostenlos.","example2En":"The taster session is free."},{"de":"der Schnurrbart","en":"mustache","pos":"noun","plural":"die Schnurrbärte","meanings":[{"en":"facial hair above the upper lip","de":"Bart über der Oberlippe"}],"rule":"Compound noun: Schnurr + Bart, masculine like Bart.","example":"Mein Opa hat einen grauen Schnurrbart.","exampleEn":"My grandpa has a gray mustache.","example2":"Er rasiert sich nie den Schnurrbart ab.","example2En":"He never shaves off his mustache."},{"de":"schonen","en":"to protect, to go easy on","pos":"verb","plural":"","meanings":[{"en":"to spare/protect something from harm","de":"vorsichtig mit etwas umgehen"},{"en":"(reflexive) to take it easy, rest","de":"sich ausruhen, sich nicht anstrengen"}],"rule":"Regular weak verb; also used reflexively: sich schonen.","example":"Nach der Operation muss er sich schonen.","exampleEn":"After the operation he has to take it easy.","example2":"Diese Creme schont die Haut.","example2En":"This cream is gentle on the skin."},{"de":"der Schornsteinfeger / die Schornsteinfegerin","en":"chimney sweep","pos":"noun","plural":"die Schornsteinfeger / die Schornsteinfegerinnen","meanings":[{"en":"a person who cleans chimneys professionally","de":"jemand, der beruflich Schornsteine reinigt"}],"rule":"Compound noun: Schornstein + Feger; feminine adds -in.","example":"Der Schornsteinfeger kommt einmal im Jahr.","exampleEn":"The chimney sweep comes once a year.","example2":"Ein Schornsteinfeger bringt angeblich Glück.","example2En":"A chimney sweep is said to bring good luck."},{"de":"schrecklich","en":"terrible, awful","pos":"adjective","plural":"","meanings":[{"en":"very bad, terrible","de":"sehr schlimm"},{"en":"(colloquial) very, extremely (intensifier)","de":"sehr (umgangssprachlich als Verstärkung)"}],"rule":"Regular comparison: schrecklich, schrecklicher, am schrecklichsten.","example":"Das Wetter war heute schrecklich.","exampleEn":"The weather was terrible today.","example2":"Ich bin schrecklich müde.","example2En":"I'm terribly tired."},{"de":"der Schrei","en":"scream, shout","pos":"noun","plural":"die Schreie","meanings":[{"en":"a loud cry, scream","de":"ein lauter Ruf"}],"rule":"Related to the verb schreien; masculine noun.","example":"Plötzlich hörte ich einen lauten Schrei.","exampleEn":"Suddenly I heard a loud scream.","example2":"Ihr Schrei weckte das ganze Haus.","example2En":"Her scream woke up the whole house."},{"de":"die Schuhgröße","en":"shoe size","pos":"noun","plural":"die Schuhgrößen","meanings":[{"en":"the size number of shoes","de":"die Größenangabe bei Schuhen"}],"rule":"Compound noun: Schuh + Größe; feminine like Größe.","example":"Welche Schuhgröße hast du?","exampleEn":"What shoe size do you have?","example2":"Meine Schuhgröße ist 42.","example2En":"My shoe size is 42."},{"de":"die Schulform","en":"type of school","pos":"noun","plural":"die Schulformen","meanings":[{"en":"a category/type of school (e.g. Gymnasium, Realschule)","de":"eine Art von Schule"}],"rule":"Compound noun: Schule + Form; feminine like Form.","example":"In Deutschland gibt es verschiedene Schulformen.","exampleEn":"In Germany there are different types of schools.","example2":"Welche Schulform besucht dein Kind?","example2En":"Which type of school does your child attend?"},{"de":"der Schulleiter / die Schulleiterin","en":"school principal","pos":"noun","plural":"die Schulleiter / die Schulleiterinnen","meanings":[{"en":"the head/director of a school","de":"der Chef/die Chefin einer Schule"}],"rule":"Compound: Schule + Leiter (leader); feminine adds -in.","example":"Der Schulleiter begrüßt die neuen Schüler.","exampleEn":"The principal welcomes the new students.","example2":"Die Schulleiterin hat heute eine Rede gehalten.","example2En":"The principal gave a speech today."},{"de":"die Schulpflicht","en":"compulsory schooling","pos":"noun","plural":"","meanings":[{"en":"legal requirement to attend school","de":"die Pflicht, zur Schule zu gehen"}],"rule":"Uncountable noun, no plural; compound: Schule + Pflicht.","example":"In Deutschland gilt die Schulpflicht ab sechs Jahren.","exampleEn":"In Germany, compulsory schooling applies from age six.","example2":"Die Schulpflicht dauert meistens neun Jahre.","example2En":"Compulsory schooling usually lasts nine years."},{"de":"das Schulsystem","en":"school system","pos":"noun","plural":"die Schulsysteme","meanings":[{"en":"the overall system of education/schools in a country","de":"das System der Schulen in einem Land"}],"rule":"Compound noun: Schule + System; neuter like System.","example":"Das Schulsystem in Deutschland ist kompliziert.","exampleEn":"The school system in Germany is complicated.","example2":"Jedes Bundesland hat ein etwas anderes Schulsystem.","example2En":"Every federal state has a slightly different school system."},{"de":"die Schulzeit","en":"school days, time at school","pos":"noun","plural":"","meanings":[{"en":"the period of one's life spent at school","de":"die Zeit, in der man zur Schule geht"}],"rule":"Usually uncountable (no plural); compound: Schule + Zeit.","example":"Ich denke oft an meine Schulzeit zurück.","exampleEn":"I often think back to my school days.","example2":"Wir sind seit der Schulzeit befreundet.","example2En":"We've been friends since our school days."},{"de":"die Schüssel","en":"bowl","pos":"noun","plural":"die Schüsseln","meanings":[{"en":"a round container for food or liquids","de":"ein rundes Gefäß für Essen"}],"rule":"Feminine noun; plural adds -n.","example":"Sie mischt den Salat in einer großen Schüssel.","exampleEn":"She mixes the salad in a large bowl.","example2":"Stell die Schüssel bitte in den Schrank.","example2En":"Please put the bowl in the cupboard."},{"de":"schwarzfahren","en":"to ride without a ticket, fare-dodge","pos":"verb","plural":"","meanings":[{"en":"to use public transport without a valid ticket","de":"ohne gültigen Fahrschein fahren"}],"rule":"Trennbar (separable) und irregular: fährt schwarz, fuhr schwarz, ist schwarzgefahren.","example":"Er ist schwarzgefahren und musste eine Strafe zahlen.","exampleEn":"He rode without a ticket and had to pay a fine.","example2":"Schwarzfahren ist in Deutschland verboten.","example2En":"Fare-dodging is illegal in Germany."},{"de":"die Schwellung","en":"swelling","pos":"noun","plural":"die Schwellungen","meanings":[{"en":"swelling (medical)","de":"das Anschwellen, z. B. nach einer Verletzung"}],"rule":"Von \"schwellen\" (anschwellen); häufig im medizinischen Kontext.","example":"Nach dem Sturz hatte er eine Schwellung am Knie.","exampleEn":"After the fall he had a swelling on his knee.","example2":"Die Schwellung geht mit Eis schneller zurück.","example2En":"The swelling goes down faster with ice."}]},{"id":"a2-16","title":"A2 · S (16)","level":"A2","words":[{"de":"die Schwiegereltern","en":"parents-in-law","pos":"noun","plural":"die Schwiegereltern","meanings":[{"en":"parents-in-law","de":"die Eltern des Ehepartners"}],"rule":"Nur im Plural gebräuchlich (Vater/Mutter des Ehepartners); vgl. Schwiegervater, Schwiegermutter.","example":"Am Sonntag essen wir bei meinen Schwiegereltern.","exampleEn":"On Sunday we're eating at my in-laws' place.","example2":"Meine Schwiegereltern wohnen in Hamburg.","example2En":"My parents-in-law live in Hamburg."},{"de":"schwierig","en":"difficult","pos":"adjective","plural":"","meanings":[{"en":"difficult, hard","de":"nicht einfach"}],"rule":"Regelmäßige Steigerung: schwierig, schwieriger, am schwierigsten.","example":"Die Prüfung war sehr schwierig.","exampleEn":"The exam was very difficult.","example2":"Er ist im Moment ein schwieriger Kollege.","example2En":"He's a difficult colleague right now."},{"de":"segeln","en":"to sail","pos":"verb","plural":"","meanings":[{"en":"to sail","de":"mit einem Segelboot fahren"}],"rule":"Regelmäßig; Perfekt meist mit \"sein\" bei Bewegung: ist gesegelt (mit \"haben\" wenn die Tätigkeit selbst betont wird).","example":"Wir segeln jedes Wochenende auf dem See.","exampleEn":"We go sailing on the lake every weekend.","example2":"Letzten Sommer sind wir nach Dänemark gesegelt.","example2En":"Last summer we sailed to Denmark."},{"de":"seit","en":"since; for (time)","pos":"preposition","plural":"","meanings":[{"en":"since (a point in time)","de":"ab einem bestimmten Zeitpunkt"},{"en":"for (a duration)","de":"eine Zeitdauer lang, bis jetzt"}],"rule":"+ Dativ; temporale Präposition, oft mit Präsens für andauernde Handlungen: \"Ich wohne seit 2020 hier.\"","example":"Ich lerne seit drei Jahren Deutsch.","exampleEn":"I have been learning German for three years.","example2":"Seit dem Unfall fährt sie kein Auto mehr.","example2En":"Since the accident she hasn't driven a car anymore."},{"de":"das Sekretariat","en":"office (administrative); secretariat","pos":"noun","plural":"die Sekretariate","meanings":[{"en":"administrative office","de":"Büro für Verwaltungsaufgaben, z. B. in Schule oder Firma"}],"rule":"Neutrum; typisch in Schule/Universität/Firma.","example":"Das Zeugnis bekommst du im Sekretariat.","exampleEn":"You get the certificate at the office.","example2":"Das Sekretariat ist von 8 bis 12 Uhr geöffnet.","example2En":"The office is open from 8 to 12."},{"de":"selber","en":"myself/yourself/etc. (oneself)","pos":"adverb","plural":"","meanings":[{"en":"oneself, personally (emphasizing the subject)","de":"ich/du/er usw. selbst, ohne fremde Hilfe"}],"rule":"Umgangssprachliche Variante von \"selbst\"; unveränderlich, steht meist nach dem Bezugswort.","example":"Das habe ich selber gemacht.","exampleEn":"I made that myself.","example2":"Kannst du das nicht selber tragen?","example2En":"Can't you carry that yourself?"},{"de":"selbst","en":"oneself; even","pos":"adverb","plural":"","meanings":[{"en":"oneself, personally","de":"ohne fremde Hilfe, persönlich"},{"en":"even (emphasizing something unexpected)","de":"sogar"}],"rule":"Unveränderlich; als Betonungswort direkt nach dem Bezugswort, als \"sogar\" meist am Satzanfang oder vor dem betonten Wort.","example":"Ich repariere das Fahrrad selbst.","exampleEn":"I'll repair the bike myself.","example2":"Selbst meine Oma benutzt ein Smartphone.","example2En":"Even my grandma uses a smartphone."},{"de":"das Semester","en":"semester","pos":"noun","plural":"die Semester","meanings":[{"en":"semester (academic term)","de":"Studienhalbjahr an der Universität"}],"rule":"Neutrum; Plural bleibt gleich: das Semester, die Semester.","example":"Im Wintersemester habe ich fünf Kurse.","exampleEn":"In the winter semester I have five courses.","example2":"Sie ist jetzt im dritten Semester.","example2En":"She is now in her third semester."},{"de":"der Senior / die Seniorin","en":"senior citizen","pos":"noun","plural":"die Senioren / die Seniorinnen","meanings":[{"en":"senior citizen, elderly person","de":"älterer Mensch, meist im Ruhestand"}],"rule":"Movierte Form auf -in; im Alltag oft im Plural \"Senioren\" für ältere Menschen allgemein.","example":"Der Bus bringt die Senioren zum Einkaufszentrum.","exampleEn":"The bus takes the senior citizens to the shopping center.","example2":"Meine Nachbarin ist Seniorin und geht jeden Tag spazieren.","example2En":"My neighbor is a senior citizen and goes for a walk every day."},{"de":"separat","en":"separate","pos":"adjective","plural":"","meanings":[{"en":"separate, apart","de":"getrennt, für sich allein"}],"rule":"Regelmäßige Steigerung: separat, separater, am separatesten (selten gesteigert).","example":"Die Kinder schlafen in einem separaten Zimmer.","exampleEn":"The children sleep in a separate room.","example2":"Bitte schicken Sie die Rechnung separat.","example2En":"Please send the invoice separately."},{"de":"der Serviceschalter","en":"service counter","pos":"noun","plural":"die Serviceschalter","meanings":[{"en":"service counter/desk","de":"Schalter für Kundenservice, z. B. am Bahnhof oder Flughafen"}],"rule":"Zusammensetzung aus Service + Schalter; Plural unverändert.","example":"Am Serviceschalter kann man die Fahrkarte umtauschen.","exampleEn":"You can exchange the ticket at the service counter.","example2":"Der Serviceschalter ist gleich neben dem Eingang.","example2En":"The service counter is right next to the entrance."},{"de":"setzen","en":"to put, to sit down","pos":"verb","plural":"","meanings":[{"en":"to put, place (something)","de":"etwas an eine Stelle stellen/legen"},{"en":"to sit down (reflexive: sich setzen)","de":"sich hinsetzen"}],"rule":"Regelmäßig: setzt, setzte, hat gesetzt; reflexiv \"sich setzen\" = sich hinsetzen.","example":"Sie setzt die Tasse auf den Tisch.","exampleEn":"She puts the cup on the table.","example2":"Setz dich bitte auf den Stuhl.","example2En":"Please sit down on the chair."},{"de":"die Shorts","en":"shorts","pos":"noun","plural":"die Shorts","meanings":[{"en":"shorts (short trousers)","de":"kurze Hose"}],"rule":"Nur Plural gebräuchlich, wie \"die Hose\" im Singular für ein Kleidungsstück; kein Artikel im Singular.","example":"Im Sommer trage ich gern Shorts.","exampleEn":"In summer I like wearing shorts.","example2":"Die Shorts sind mir zu eng.","example2En":"The shorts are too tight for me."},{"de":"sich ärgern","en":"to be annoyed, to get angry","pos":"verb","plural":"","meanings":[{"en":"to feel annoyed or angry about something","de":"wütend oder verärgert sein"}],"rule":"Reflexive verb: sich ärgern über + Akkusativ; also transitive 'jemanden ärgern' = to annoy someone; regular weak verb (ärgert, ärgerte, hat geärgert).","example":"Ich ärgere mich über den Stau.","exampleEn":"I am annoyed about the traffic jam.","example2":"Mein kleiner Bruder ärgert mich oft.","example2En":"My little brother often annoys me."},{"de":"die Sicherheit","en":"safety, security","pos":"noun","plural":"die Sicherheiten","meanings":[{"en":"safety, security","de":"Zustand ohne Gefahr"},{"en":"certainty, confidence","de":"Gewissheit, Selbstbewusstsein"}],"rule":"Femininum; Plural \"die Sicherheiten\" meist im Finanzkontext (Kreditsicherheiten); sonst meist unzählbar.","example":"Die Sicherheit der Passagiere hat oberste Priorität.","exampleEn":"Passenger safety has top priority.","example2":"Er beantwortet die Frage mit großer Sicherheit.","example2En":"He answers the question with great confidence."},{"de":"der Sieg","en":"victory","pos":"noun","plural":"die Siege","meanings":[{"en":"victory, win","de":"Erfolg in einem Wettkampf"}],"rule":"Maskulinum; Gegenteil: die Niederlage. Häufig mit \"gegen\": Sieg gegen einen Gegner.","example":"Das Team feiert den Sieg im Finale.","exampleEn":"The team celebrates the victory in the final.","example2":"Nach dem Sieg gab es ein großes Fest.","example2En":"After the victory there was a big celebration."},{"de":"das Silber","en":"silver","pos":"noun","plural":"","meanings":[{"en":"silver (metal)","de":"edles graues Metall"},{"en":"silver medal","de":"zweiter Platz bei einem Wettbewerb"}],"rule":"Neutrum, Stoffname, kein Plural üblich.","example":"Der Ring ist aus Silber.","exampleEn":"The ring is made of silver.","example2":"Sie hat bei der Olympiade Silber gewonnen.","example2En":"She won silver at the Olympics."},{"de":"sinken","en":"to sink, to fall","pos":"verb","plural":"","meanings":[{"en":"to sink (go down in water)","de":"unter die Oberfläche gehen"},{"en":"to decrease, fall (level, price, number)","de":"weniger werden"}],"rule":"Unregelmäßig: sinkt, sank, ist gesunken (mit sein); intransitiv.","example":"Das Schiff sank langsam ins Meer.","exampleEn":"The ship slowly sank into the sea.","example2":"Die Preise für Benzin sind gesunken.","example2En":"Gasoline prices have fallen."},{"de":"die Situation","en":"situation","pos":"noun","plural":"die Situationen","meanings":[{"en":"situation, circumstances","de":"Lage, Umstände"}],"rule":"Feminine noun; plural with -en.","example":"Die Situation im Büro ist im Moment schwierig.","exampleEn":"The situation at the office is difficult at the moment.","example2":"Er hat in jeder Situation Ruhe bewahrt.","example2En":"He stayed calm in every situation."},{"de":"das Smartphone","en":"smartphone","pos":"noun","plural":"die Smartphones","meanings":[{"en":"smartphone","de":"modernes Mobiltelefon"}],"rule":"Neuter noun (English loanword); plural with -s.","example":"Mein Smartphone ist leider kaputt.","exampleEn":"Unfortunately my smartphone is broken.","example2":"Kinder sollten nicht zu lange am Smartphone spielen.","example2En":"Children shouldn't play on the smartphone for too long."},{"de":"der Snack","en":"snack","pos":"noun","plural":"die Snacks","meanings":[{"en":"snack, small quick meal","de":"kleine Zwischenmahlzeit"}],"rule":"Masculine noun (English loanword); plural with -s.","example":"Ich kaufe mir einen Snack für die Reise.","exampleEn":"I'm buying myself a snack for the trip.","example2":"Am Kiosk gibt es viele Snacks.","example2En":"There are many snacks at the kiosk."},{"de":"sogar","en":"even","pos":"adverb","plural":"","meanings":[{"en":"even (emphasizing something surprising)","de":"selbst, auch"}],"rule":"Used to emphasize something unexpected; position flexible in the sentence.","example":"Er hat sogar am Sonntag gearbeitet.","exampleEn":"He even worked on Sunday.","example2":"Sogar meine Oma benutzt ein Smartphone.","example2En":"Even my grandma uses a smartphone."},{"de":"sondern","en":"but (rather)","pos":"conjunction","plural":"","meanings":[{"en":"but rather, on the contrary (after a negation)","de":"vielmehr, im Gegenteil"}],"rule":"Only used after a negative clause with 'nicht' or 'kein'; pairs with 'nicht nur ... sondern auch'.","example":"Das ist kein Tee, sondern Kaffee.","exampleEn":"That's not tea, but coffee.","example2":"Sie kommt nicht heute, sondern morgen.","example2En":"She's not coming today, but tomorrow."},{"de":"sorgen","en":"to take care of; to worry","pos":"verb","plural":"","meanings":[{"en":"to take care of, ensure (sorgen für + Akk.)","de":"sich kümmern um"},{"en":"to worry (sich sorgen um + Akk.)","de":"sich Sorgen machen"}],"rule":"'sorgen für' + Akkusativ = to provide/ensure; reflexive 'sich sorgen um' + Akk. = to worry about. Regular weak verb.","example":"Die Eltern sorgen für ihre Kinder.","exampleEn":"The parents take care of their children.","example2":"Sie sorgt sich um ihren kranken Vater.","example2En":"She worries about her sick father."},{"de":"sorgfältig","en":"careful, thorough","pos":"adjective","plural":"","meanings":[{"en":"careful, thorough, diligent","de":"genau, gewissenhaft"}],"rule":"Regular comparison: sorgfältig, sorgfältiger, am sorgfältigsten.","example":"Bitte arbeiten Sie sorgfältig.","exampleEn":"Please work carefully.","example2":"Er hat den Text sorgfältig korrigiert.","example2En":"He corrected the text carefully."},{"de":"der Sozialpädagoge / die Sozialpädagogin","en":"social worker, social education worker","pos":"noun","plural":"die Sozialpädagogen / die Sozialpädagoginnen","meanings":[{"en":"social education worker, social worker","de":"Fachkraft für soziale Arbeit"}],"rule":"Masculine weak noun (der Sozialpädagoge, den/dem/des Sozialpädagogen); feminine form with -in.","example":"Der Sozialpädagoge hilft Jugendlichen in der Schule.","exampleEn":"The social worker helps young people at school.","example2":"Die Sozialpädagogin arbeitet in einem Jugendzentrum.","example2En":"The social worker (female) works in a youth center."},{"de":"sparen","en":"to save (money/resources)","pos":"verb","plural":"","meanings":[{"en":"to save money","de":"Geld zurücklegen"},{"en":"to save, economize on (sparen an/mit)","de":"sparsam umgehen mit"}],"rule":"Regular weak verb; often with 'für' (sparen für ein Auto) or 'an/mit' (Energie sparen).","example":"Wir sparen für den Urlaub.","exampleEn":"We are saving up for our vacation.","example2":"Man kann viel Strom sparen.","example2En":"You can save a lot of electricity."},{"de":"das Sparkonto","en":"savings account","pos":"noun","plural":"die Sparkonten","meanings":[{"en":"savings account","de":"Bankkonto zum Sparen"}],"rule":"Neuter noun; plural die Sparkonten (also colloquially die Sparkontos).","example":"Ich habe ein Sparkonto bei der Bank.","exampleEn":"I have a savings account at the bank.","example2":"Auf dem Sparkonto gibt es Zinsen.","example2En":"The savings account earns interest."},{"de":"das Sparschwein","en":"piggy bank","pos":"noun","plural":"die Sparschweine","meanings":[{"en":"piggy bank","de":"Behälter zum Sparen von Münzen"}],"rule":"Neuter compound noun (sparen + Schwein); plural with -e.","example":"Mein Sohn wirft jeden Tag Münzen ins Sparschwein.","exampleEn":"My son puts coins in the piggy bank every day.","example2":"Das Sparschwein ist schon fast voll.","example2En":"The piggy bank is almost full already."},{"de":"spätestens","en":"at the latest","pos":"adverb","plural":"","meanings":[{"en":"at the latest","de":"nicht später als"}],"rule":"Superlative adverb from 'spät'; often combined with a time expression.","example":"Bitte melden Sie sich spätestens bis Freitag.","exampleEn":"Please get in touch by Friday at the latest.","example2":"Wir müssen spätestens um acht Uhr losfahren.","example2En":"We have to leave by eight o'clock at the latest."},{"de":"der Spaziergang","en":"walk, stroll","pos":"noun","plural":"die Spaziergänge","meanings":[{"en":"walk, stroll","de":"kurzer Ausflug zu Fuß"}],"rule":"Masculine compound noun (spazieren + Gang); plural with umlaut -e (Gang → Gänge).","example":"Wir machen einen Spaziergang im Park.","exampleEn":"We're going for a walk in the park.","example2":"Nach dem Essen mache ich gern einen Spaziergang.","example2En":"After eating I like to take a walk."},{"de":"speichern","en":"to save (data), to store","pos":"verb","plural":"","meanings":[{"en":"to save (a file/data)","de":"(Daten) sichern"},{"en":"to store (e.g. food, energy)","de":"lagern, aufbewahren"}],"rule":"Regular weak verb; commonly used for saving computer files (Datei speichern).","example":"Hast du das Dokument schon gespeichert?","exampleEn":"Have you already saved the document?","example2":"Der Akku speichert die Energie der Sonne.","example2En":"The battery stores the sun's energy."},{"de":"spezial","en":"special (only in compounds)","pos":"other","plural":"","meanings":[{"en":"special- (bound combining form used only in compound nouns)","de":"besonder-, speziell (nur als Wortbildungselement)"}],"rule":"Not an inflectable adjective: 'spezial' cannot stand alone attributively (*ein spezial Angebot is wrong) or predicatively. It only occurs as the first part of compound nouns, e.g. Spezialangebot, Spezialgebiet, Spezialwerkzeug. For free adjective use, use 'speziell' instead.","example":"Das ist ein Spezialangebot für Studenten.","exampleEn":"That's a special offer for students.","example2":"Er hat ein Spezialwerkzeug benutzt.","example2En":"He used a special tool."},{"de":"speziell","en":"special, specific","pos":"adjective","plural":"","meanings":[{"en":"special, particular","de":"besonder, eigens"},{"en":"specifically, especially (adverbial use)","de":"besonders, eigens"}],"rule":"Regular comparison: speziell, spezieller, am speziellsten; can be used attributively and adverbially.","example":"Ich suche einen speziellen Termin beim Arzt.","exampleEn":"I'm looking for a specific appointment with the doctor.","example2":"Das Geschenk ist speziell für dich.","example2En":"The gift is especially for you."},{"de":"der Spiegel","en":"mirror","pos":"noun","plural":"die Spiegel","meanings":[{"en":"mirror","de":"Gegenstand zum Sich-Anschauen"}],"rule":"Masculine noun; plural unchanged (der Spiegel - die Spiegel).","example":"Sie schaut in den Spiegel.","exampleEn":"She looks in the mirror.","example2":"Im Badezimmer hängt ein großer Spiegel.","example2En":"There's a big mirror hanging in the bathroom."},{"de":"das Spielfeld","en":"playing field, pitch","pos":"noun","plural":"die Spielfelder","meanings":[{"en":"playing field, pitch, court","de":"Fläche für ein Sportspiel"}],"rule":"Neuter compound noun (Spiel + Feld); plural with -er, no umlaut (the 'e' in Feld cannot take an umlaut): das Feld → die Felder.","example":"Die Spieler laufen auf das Spielfeld.","exampleEn":"The players run onto the playing field.","example2":"Das Spielfeld ist nass vom Regen.","example2En":"The pitch is wet from the rain."},{"de":"die Spielwaren","en":"toys (retail category)","pos":"noun","plural":"(Plural)","meanings":[{"en":"toys (goods sold in a shop)","de":"Waren zum Spielen, im Geschäft"}],"rule":"Usually used only in plural, often in compounds like Spielwarengeschäft (toy shop).","example":"Wir kaufen das Geschenk im Spielwarengeschäft.","exampleEn":"We buy the gift at the toy shop.","example2":"Die Spielwaren liegen im ersten Stock.","example2En":"The toys are on the first floor."},{"de":"das Spielzeug","en":"toy","pos":"noun","plural":"die Spielzeuge","meanings":[{"en":"a toy / toys (general term)","de":"Gegenstand zum Spielen, besonders für Kinder"}],"rule":"Often used as an uncountable collective noun (kein Plural nötig): \"viel Spielzeug\".","example":"Das Kind hat viel Spielzeug im Zimmer.","exampleEn":"The child has a lot of toys in the room.","example2":"Er bekommt ein neues Spielzeug zum Geburtstag.","example2En":"He gets a new toy for his birthday."},{"de":"die Sportart","en":"type of sport","pos":"noun","plural":"die Sportarten","meanings":[{"en":"a particular sport/discipline","de":"eine bestimmte Art von Sport, z. B. Fußball, Tennis"}],"rule":"Compound: Sport + Art. Always feminine like Art.","example":"Fußball ist meine Lieblingssportart.","exampleEn":"Football is my favorite sport.","example2":"Welche Sportart machst du?","example2En":"Which sport do you do?"},{"de":"das Sportergebnis","en":"sports result/score","pos":"noun","plural":"die Sportergebnisse","meanings":[{"en":"the result or score of a sports event","de":"das Resultat eines Sportwettkampfs"}],"rule":"Compound: Sport + Ergebnis (neuter, like Ergebnis).","example":"Hast du das Sportergebnis vom Spiel gehört?","exampleEn":"Did you hear the score of the match?","example2":"Die Sportergebnisse stehen in der Zeitung.","example2En":"The sports results are in the newspaper."},{"de":"der Sportplatz","en":"sports ground/field","pos":"noun","plural":"die Sportplätze","meanings":[{"en":"an outdoor area for playing sports","de":"ein Platz, auf dem man Sport treibt"}],"rule":"Compound: Sport + Platz (masculine, like Platz); plural with Umlaut.","example":"Wir treffen uns auf dem Sportplatz.","exampleEn":"We're meeting at the sports field.","example2":"Der Sportplatz liegt neben der Schule.","example2En":"The sports ground is next to the school."},{"de":"der Sportunterricht","en":"physical education class","pos":"noun","plural":"","meanings":[{"en":"PE class at school","de":"Schulfach, in dem man Sport macht"}],"rule":"Uncountable, no plural. Compound: Sport + Unterricht.","example":"Heute haben wir Sportunterricht.","exampleEn":"Today we have PE class.","example2":"Er mag den Sportunterricht sehr gern.","example2En":"He really likes PE class."},{"de":"der Sportverein","en":"sports club","pos":"noun","plural":"die Sportvereine","meanings":[{"en":"a club for practicing sports","de":"ein Verein, in dem man gemeinsam Sport macht"}],"rule":"Compound: Sport + Verein (masculine, like Verein).","example":"Ich bin Mitglied in einem Sportverein.","exampleEn":"I'm a member of a sports club.","example2":"Der Sportverein trainiert dreimal die Woche.","example2En":"The sports club trains three times a week."},{"de":"die Staatsangehörigkeit","en":"nationality/citizenship","pos":"noun","plural":"die Staatsangehörigkeiten","meanings":[{"en":"legal citizenship of a country","de":"die Zugehörigkeit zu einem Staat"}],"rule":"Formal word often asked for on official forms; answer with \"deutsch\", \"türkisch\" etc.","example":"Welche Staatsangehörigkeit hast du?","exampleEn":"What is your nationality?","example2":"Sie hat die deutsche Staatsangehörigkeit.","example2En":"She has German citizenship."},{"de":"städtisch","en":"municipal/urban","pos":"adjective","plural":"","meanings":[{"en":"belonging to a city/town, run by the municipality","de":"zur Stadt gehörend, von der Stadt"}],"rule":"Regular comparison: städtisch, städtischer, am städtischsten (rarely compared).","example":"Das ist eine städtische Bibliothek.","exampleEn":"That is a municipal library.","example2":"Die städtischen Behörden haben entschieden.","example2En":"The city authorities have decided."},{"de":"ständig","en":"constant(ly)","pos":"adjective","plural":"","meanings":[{"en":"happening all the time, continuous","de":"immer wieder, ohne Unterbrechung"}],"rule":"Regular comparison: ständig, ständiger, am ständigsten (rarely compared, since it already expresses a continuous state). Also used as adverb.","example":"Er ist ständig müde.","exampleEn":"He is constantly tired.","example2":"Sie ruft mich ständig an.","example2En":"She calls me all the time."},{"de":"stärken","en":"to strengthen","pos":"verb","plural":"","meanings":[{"en":"to make stronger (physically or figuratively)","de":"stärker machen"}],"rule":"Regular weak verb: stärkt, stärkte, hat gestärkt.","example":"Sport stärkt den Körper.","exampleEn":"Sport strengthens the body.","example2":"Die Pause hat ihn gestärkt.","example2En":"The break strengthened him."},{"de":"starten","en":"to start/take off","pos":"verb","plural":"","meanings":[{"en":"to begin something","de":"mit etwas beginnen"},{"en":"to take off (plane)","de":"abheben (Flugzeug)"}],"rule":"Regular weak verb: startet, startete. Perfekt with sein when intransitive/describing motion (das Flugzeug ist gestartet, das Rennen ist gestartet); with haben when transitive (er hat den Computer gestartet).","example":"Das Rennen startet um 10 Uhr.","exampleEn":"The race starts at 10 o'clock.","example2":"Das Flugzeug ist pünktlich gestartet.","example2En":"The plane took off on time."},{"de":"die Startseite","en":"homepage","pos":"noun","plural":"die Startseiten","meanings":[{"en":"the homepage of a website or browser","de":"die erste Seite einer Website"}],"rule":"Compound: Start + Seite (feminine, like Seite).","example":"Ich öffne zuerst die Startseite.","exampleEn":"I open the homepage first.","example2":"Die Startseite zeigt die neuesten Nachrichten.","example2En":"The homepage shows the latest news."},{"de":"die Station","en":"station/stop","pos":"noun","plural":"die Stationen","meanings":[{"en":"a stop on public transport","de":"eine Haltestelle"},{"en":"a ward/department in a hospital","de":"eine Abteilung im Krankenhaus"}],"rule":"Note: for train station use Bahnhof; Station is more for stops/wards.","example":"An der nächsten Station steigen wir aus.","exampleEn":"We get off at the next stop.","example2":"Mein Vater liegt auf Station 3.","example2En":"My father is in ward 3."}]},{"id":"a2-17","title":"A2 · S–T (17)","level":"A2","words":[{"de":"statt","en":"instead of","pos":"preposition","plural":"","meanings":[{"en":"instead of, in place of","de":"anstelle von"}],"rule":"Preposition + Genitiv: statt des Kaffees. In spoken German often + Dativ.","example":"Ich trinke Tee statt Kaffee.","exampleEn":"I drink tea instead of coffee.","example2":"Statt zu telefonieren, schreibt sie eine E-Mail.","example2En":"Instead of calling, she writes an email."},{"de":"das Steak","en":"steak","pos":"noun","plural":"die Steaks","meanings":[{"en":"a grilled or fried piece of meat","de":"ein gebratenes Stück Fleisch"}],"rule":"Loanword from English; neuter gender, plural with -s.","example":"Er bestellt ein Steak mit Salat.","exampleEn":"He orders a steak with salad.","example2":"Das Steak schmeckt sehr gut.","example2En":"The steak tastes very good."},{"de":"die Steckdose","en":"electrical socket/outlet","pos":"noun","plural":"die Steckdosen","meanings":[{"en":"a socket for plugging in electrical devices","de":"der Anschluss in der Wand für Strom"}],"rule":"Compound: stecken + Dose (feminine, like Dose).","example":"Der Stecker passt nicht in die Steckdose.","exampleEn":"The plug doesn't fit into the socket.","example2":"Die Steckdose ist neben dem Bett.","example2En":"The socket is next to the bed."},{"de":"stecken","en":"to put/stick; to be (located)","pos":"verb","plural":"","meanings":[{"en":"to put something into a narrow space","de":"etwas in etwas hineintun"},{"en":"to be stuck/located somewhere","de":"sich irgendwo befinden"}],"rule":"Regular weak verb as transitive (steckt, steckte, hat gesteckt); as intransitive meaning 'to be located' also weak.","example":"Sie steckt den Schlüssel in die Tasche.","exampleEn":"She puts the key into her bag.","example2":"Wo steckt mein Handy?","example2En":"Where is my phone?"},{"de":"stehlen","en":"to steal","pos":"verb","plural":"","meanings":[{"en":"to steal","de":"jemandem etwas wegnehmen, ohne zu fragen"}],"rule":"unregelmäßig: er stiehlt, stahl, hat gestohlen","example":"Jemand hat mein Fahrrad gestohlen.","exampleEn":"Someone stole my bike.","example2":"Er wurde verhaftet, weil er Geld gestohlen hat.","example2En":"He was arrested because he stole money."},{"de":"steigen","en":"to climb; to rise","pos":"verb","plural":"","meanings":[{"en":"to climb / get in or out (of a vehicle)","de":"nach oben gehen, einsteigen/aussteigen"},{"en":"to rise (prices, numbers)","de":"mehr werden"}],"rule":"unregelmäßig: er steigt, stieg, ist gestiegen (mit sein)","example":"Wir steigen in den Bus.","exampleEn":"We are getting on the bus.","example2":"Die Preise steigen jedes Jahr.","example2En":"Prices rise every year."},{"de":"die Stelle","en":"place; job position","pos":"noun","plural":"die Stellen","meanings":[{"en":"place/spot","de":"ein bestimmter Ort"},{"en":"job position","de":"eine Arbeitsstelle"}],"rule":"feminin, Plural: die Stellen","example":"An dieser Stelle ist die Straße sehr eng.","exampleEn":"At this spot the street is very narrow.","example2":"Sie hat eine neue Stelle als Sekretärin gefunden.","example2En":"She found a new job as a secretary."},{"de":"das Stellenangebot","en":"job offer / job vacancy","pos":"noun","plural":"die Stellenangebote","meanings":[{"en":"job offer / job posting","de":"eine angebotene Arbeitsstelle"}],"rule":"neutrum, Zusammensetzung aus Stelle + Angebot","example":"Ich habe ein interessantes Stellenangebot in der Zeitung gesehen.","exampleEn":"I saw an interesting job offer in the newspaper.","example2":"Auf der Internetseite gibt es viele Stellenangebote.","example2En":"There are many job vacancies on the website."},{"de":"die Stellensuche","en":"job search","pos":"noun","plural":"","meanings":[{"en":"job search","de":"die Suche nach einer Arbeitsstelle"}],"rule":"feminin, meist ohne Plural","example":"Die Stellensuche dauert oft mehrere Monate.","exampleEn":"The job search often takes several months.","example2":"Er ist seit der Stellensuche sehr gestresst.","example2En":"He has been very stressed since starting his job search."},{"de":"der Stellplatz","en":"parking space / pitch","pos":"noun","plural":"die Stellplätze","meanings":[{"en":"parking space","de":"ein Platz zum Parken"},{"en":"pitch (for a caravan/tent on a campsite)","de":"ein Platz auf dem Campingplatz"}],"rule":"maskulin, Plural: die Stellplätze","example":"Das Haus hat einen eigenen Stellplatz für das Auto.","exampleEn":"The house has its own parking space for the car.","example2":"Wir haben einen Stellplatz auf dem Campingplatz reserviert.","example2En":"We reserved a pitch at the campsite."},{"de":"die Steuer","en":"tax","pos":"noun","plural":"die Steuern","meanings":[{"en":"tax","de":"Geld, das man an den Staat zahlen muss"}],"rule":"feminin (die Steuer = tax); Achtung: das Steuer = steering wheel, anderes Wort!","example":"Wir müssen jedes Jahr Steuern zahlen.","exampleEn":"We have to pay taxes every year.","example2":"Die Steuer auf Benzin ist sehr hoch.","example2En":"The tax on petrol is very high."},{"de":"der Stiefel","en":"boot","pos":"noun","plural":"die Stiefel","meanings":[{"en":"boot (footwear)","de":"ein hoher Schuh"}],"rule":"maskulin, Plural: die Stiefel (unverändert)","example":"Im Winter trage ich warme Stiefel.","exampleEn":"In winter I wear warm boots.","example2":"Ihre neuen Stiefel sind aus Leder.","example2En":"Her new boots are made of leather."},{"de":"die Störung","en":"disturbance; malfunction","pos":"noun","plural":"die Störungen","meanings":[{"en":"disturbance / interruption","de":"etwas, das stört"},{"en":"malfunction / technical fault","de":"ein technisches Problem"}],"rule":"feminin, Plural: die Störungen; von \"stören\"","example":"Entschuldigen Sie die Störung!","exampleEn":"Sorry to disturb you!","example2":"Es gibt eine Störung im Internet.","example2En":"There is a fault with the internet."},{"de":"stoßen","en":"to push; to bump","pos":"verb","plural":"","meanings":[{"en":"to push / shove","de":"mit Kraft schieben"},{"en":"to bump into / knock against","de":"sich gegen etwas stoßen"}],"rule":"unregelmäßig: er stößt, stieß, hat gestoßen; reflexiv sich stoßen (z.B. sich den Kopf stoßen) bildet das Perfekt ebenfalls mit haben: hat sich gestoßen","example":"Er hat die Tür aufgestoßen und ist hinausgegangen.","exampleEn":"He pushed the door open and went out.","example2":"Ich habe mich am Tisch gestoßen.","example2En":"I bumped into the table."},{"de":"die Strafe","en":"punishment; penalty/fine","pos":"noun","plural":"die Strafen","meanings":[{"en":"punishment","de":"eine Konsequenz für falsches Verhalten"},{"en":"fine/penalty","de":"eine Geldstrafe"}],"rule":"feminin, Plural: die Strafen","example":"Für zu schnelles Fahren gibt es eine Strafe.","exampleEn":"There is a penalty for speeding.","example2":"Er musste eine hohe Strafe bezahlen.","example2En":"He had to pay a high fine."},{"de":"das Straßenfest","en":"street festival","pos":"noun","plural":"die Straßenfeste","meanings":[{"en":"street festival/party","de":"ein Fest auf der Straße"}],"rule":"neutrum, Zusammensetzung aus Straße + Fest","example":"Am Wochenende ist ein Straßenfest in unserer Stadt.","exampleEn":"There is a street festival in our town this weekend.","example2":"Wir haben beim Straßenfest viele Nachbarn getroffen.","example2En":"We met many neighbors at the street festival."},{"de":"die Strecke","en":"route; distance","pos":"noun","plural":"die Strecken","meanings":[{"en":"route","de":"ein Weg von A nach B"},{"en":"distance","de":"die Länge eines Weges"}],"rule":"feminin, Plural: die Strecken","example":"Diese Strecke fahren wir jeden Tag mit dem Bus.","exampleEn":"We take this route by bus every day.","example2":"Die Strecke bis zum Bahnhof ist sehr kurz.","example2En":"The distance to the train station is very short."},{"de":"streng","en":"strict","pos":"adjective","plural":"","meanings":[{"en":"strict","de":"nicht locker, mit festen Regeln"}],"rule":"regelmäßige Steigerung: streng, strenger, am strengsten","example":"Unser Lehrer ist sehr streng.","exampleEn":"Our teacher is very strict.","example2":"In der Schule gelten strenge Regeln.","example2En":"Strict rules apply at school."},{"de":"die Struktur","en":"structure","pos":"noun","plural":"die Strukturen","meanings":[{"en":"structure/organization","de":"der Aufbau von etwas"}],"rule":"feminin, Plural: die Strukturen","example":"Der Text hat eine klare Struktur.","exampleEn":"The text has a clear structure.","example2":"Die Struktur des Unternehmens hat sich verändert.","example2En":"The company's structure has changed."},{"de":"surfen","en":"to surf","pos":"verb","plural":"","meanings":[{"en":"to surf the internet","de":"im Internet nach Informationen suchen"},{"en":"to surf (on water)","de":"auf einem Brett auf Wellen fahren"}],"rule":"regelmäßig: surft, surfte, hat gesurft","example":"Er surft jeden Abend im Internet.","exampleEn":"He surfs the internet every evening.","example2":"Im Urlaub haben wir surfen gelernt.","example2En":"On vacation we learned to surf."},{"de":"die Süßigkeiten","en":"sweets / candy","pos":"noun","plural":"die Süßigkeiten","meanings":[{"en":"sweets/candy","de":"süße Lebensmittel wie Schokolade oder Bonbons"}],"rule":"feminin, meist nur im Plural verwendet","example":"Kinder lieben Süßigkeiten.","exampleEn":"Children love sweets.","example2":"Er isst zu viele Süßigkeiten.","example2En":"He eats too much candy."},{"de":"das Symbol","en":"symbol; icon","pos":"noun","plural":"die Symbole","meanings":[{"en":"symbol (sign with meaning)","de":"ein Zeichen mit besonderer Bedeutung"},{"en":"icon (on a screen)","de":"ein kleines Bildzeichen am Computer"}],"rule":"neutrum, Plural: die Symbole","example":"Das rote Herz ist ein Symbol für Liebe.","exampleEn":"The red heart is a symbol of love.","example2":"Klicken Sie auf das Symbol, um die App zu öffnen.","example2En":"Click the icon to open the app."},{"de":"sympathisch","en":"likeable, nice","pos":"adjective","plural":"","meanings":[{"en":"likeable, pleasant (of a person)","de":"nett, angenehm"}],"rule":"Comparative regular: sympathisch, sympathischer, am sympathischsten. Describes people, not things. False friend: does NOT mean 'sympathetic' (= mitfühlend in German).","example":"Mein neuer Kollege ist sehr sympathisch.","exampleEn":"My new colleague is very likeable.","example2":"Ich finde die Frau aus dem Kurs sehr sympathisch.","example2En":"I find the woman from the course very likeable."},{"de":"die Tagesordnung","en":"agenda","pos":"noun","plural":"die Tagesordnungen","meanings":[{"en":"agenda (of a meeting)","de":"Liste der Themen für eine Besprechung"}],"rule":"Compound noun: der Tag + die Ordnung → feminine.","example":"Wir haben vier Punkte auf der Tagesordnung.","exampleEn":"We have four items on the agenda.","example2":"Die Tagesordnung für die Sitzung liegt auf dem Tisch.","example2En":"The agenda for the meeting is on the table."},{"de":"die TAN","en":"transaction number (TAN)","pos":"noun","plural":"die TANs","meanings":[{"en":"one-time code for online banking transactions","de":"Code für Online-Überweisungen"}],"rule":"Abbreviation for 'Transaktionsnummer'; feminine like 'die Nummer'.","example":"Bitte geben Sie Ihre TAN ein.","exampleEn":"Please enter your TAN.","example2":"Ohne TAN kann ich die Überweisung nicht bestätigen.","example2En":"Without a TAN I can't confirm the transfer."},{"de":"der Tango","en":"tango (dance)","pos":"noun","plural":"die Tangos","meanings":[{"en":"tango, a dance","de":"ein Tanz aus Argentinien"}],"rule":"Loanword from Spanish; masculine, plural with -s.","example":"Sie tanzen sehr gut Tango.","exampleEn":"They dance the tango very well.","example2":"Am Samstag lernen wir den Tango.","example2En":"On Saturday we're learning the tango."},{"de":"der Tänzer / die Tänzerin","en":"dancer","pos":"noun","plural":"die Tänzer / die Tänzerinnen","meanings":[{"en":"a person who dances","de":"jemand, der tanzt"}],"rule":"Agent noun from 'tanzen'; feminine adds -in.","example":"Er ist ein professioneller Tänzer.","exampleEn":"He is a professional dancer.","example2":"Die Tänzerin übt jeden Tag drei Stunden.","example2En":"The dancer practices three hours every day."},{"de":"der Tanzkurs","en":"dance class","pos":"noun","plural":"die Tanzkurse","meanings":[{"en":"a course to learn dancing","de":"ein Kurs, um Tanzen zu lernen"}],"rule":"Compound: tanzen + der Kurs → masculine.","example":"Wir machen zusammen einen Tanzkurs.","exampleEn":"We're taking a dance class together.","example2":"Der Tanzkurs beginnt um 19 Uhr.","example2En":"The dance class starts at 7 pm."},{"de":"die Taste","en":"key, button","pos":"noun","plural":"die Tasten","meanings":[{"en":"a key on a keyboard or button on a device","de":"Knopf an Tastatur oder Gerät"}],"rule":"Feminine noun; common in compounds like Starttaste.","example":"Drücken Sie diese Taste, um zu starten.","exampleEn":"Press this key to start.","example2":"Die Taste am Fernseher funktioniert nicht.","example2En":"The button on the TV doesn't work."},{"de":"der Täter / die Täterin","en":"perpetrator, offender","pos":"noun","plural":"die Täter / die Täterinnen","meanings":[{"en":"a person who commits a crime","de":"jemand, der eine Straftat begeht"}],"rule":"From 'die Tat' (act/deed); feminine adds -in.","example":"Die Polizei sucht noch den Täter.","exampleEn":"The police are still looking for the perpetrator.","example2":"Die Täterin wurde am Bahnhof festgenommen.","example2En":"The offender was arrested at the train station."},{"de":"das Tattoo","en":"tattoo","pos":"noun","plural":"die Tattoos","meanings":[{"en":"a permanent drawing on the skin","de":"ein Bild auf der Haut"}],"rule":"Loanword; neuter, plural with -s.","example":"Er hat ein Tattoo am Arm.","exampleEn":"He has a tattoo on his arm.","example2":"Sie möchte sich ein neues Tattoo machen lassen.","example2En":"She wants to get a new tattoo."},{"de":"tauschen","en":"to exchange, swap","pos":"verb","plural":"","meanings":[{"en":"to exchange/swap something with someone","de":"etwas gegen etwas anderes geben"}],"rule":"Regular weak verb: tauscht, tauschte, hat getauscht. Often used with 'gegen' or 'mit'.","example":"Kannst du mit mir den Platz tauschen?","exampleEn":"Can you swap seats with me?","example2":"Wir haben unsere Bücher getauscht.","example2En":"We exchanged our books."},{"de":"das Team","en":"team","pos":"noun","plural":"die Teams","meanings":[{"en":"a group of people working together","de":"eine Gruppe, die zusammenarbeitet"}],"rule":"Loanword from English; neuter, plural with -s.","example":"Unser Team gewinnt oft.","exampleEn":"Our team wins often.","example2":"Er arbeitet gern im Team.","example2En":"He likes working in a team."},{"de":"das Teelicht","en":"tealight (candle)","pos":"noun","plural":"die Teelichter","meanings":[{"en":"a small, round candle in a metal case","de":"eine kleine runde Kerze"}],"rule":"Compound: der Tee + das Licht → neuter.","example":"Sie stellt ein Teelicht auf den Tisch.","exampleEn":"She puts a tealight on the table.","example2":"Wir haben viele Teelichter für die Party gekauft.","example2En":"We bought many tealights for the party."},{"de":"der Teenager","en":"teenager","pos":"noun","plural":"die Teenager","meanings":[{"en":"a young person aged 13-19","de":"eine Person zwischen 13 und 19 Jahren"}],"rule":"Loanword from English; masculine, plural unchanged.","example":"Mein Sohn ist jetzt ein Teenager.","exampleEn":"My son is a teenager now.","example2":"Viele Teenager nutzen soziale Medien.","example2En":"Many teenagers use social media."},{"de":"der Teil","en":"part","pos":"noun","plural":"die Teile","meanings":[{"en":"a part or piece of something","de":"ein Stück von etwas"}],"rule":"Masculine in general use; can also be neuter (das Teil) informally for a component/gadget.","example":"Das ist nur ein Teil des Problems.","exampleEn":"That's only part of the problem.","example2":"Wir haben den Kuchen in acht Teile geschnitten.","example2En":"We cut the cake into eight pieces."},{"de":"die Teilnahme","en":"participation","pos":"noun","plural":"","meanings":[{"en":"the act of taking part in something","de":"das Mitmachen bei etwas"}],"rule":"Noun from 'teilnehmen'; uncountable, usually used with 'an' + Dativ (Teilnahme am Kurs).","example":"Die Teilnahme am Kurs ist kostenlos.","exampleEn":"Participation in the course is free.","example2":"Vielen Dank für Ihre Teilnahme.","example2En":"Thank you very much for your participation."},{"de":"die Teilnahmebescheinigung","en":"certificate of participation","pos":"noun","plural":"die Teilnahmebescheinigungen","meanings":[{"en":"a document confirming that someone took part in a course","de":"ein Dokument, das die Teilnahme an einem Kurs bestätigt"}],"rule":"Compound: die Teilnahme + die Bescheinigung → feminine.","example":"Am Ende des Kurses bekommen Sie eine Teilnahmebescheinigung.","exampleEn":"At the end of the course you get a certificate of participation.","example2":"Ich brauche die Teilnahmebescheinigung für meinen Arbeitgeber.","example2En":"I need the certificate of participation for my employer."},{"de":"teilnehmen","en":"to take part, participate","pos":"verb","plural":"","meanings":[{"en":"to take part in something","de":"bei etwas mitmachen"}],"rule":"Trennbar (separable): nimmt teil, nahm teil, hat teilgenommen. + an + Dativ.","example":"Ich nehme am Deutschkurs teil.","exampleEn":"I'm taking part in the German course.","example2":"Er hat am Wettbewerb teilgenommen.","example2En":"He took part in the competition."},{"de":"die Teilzeit","en":"part-time","pos":"noun","plural":"","meanings":[{"en":"working fewer hours than a full-time job","de":"eine Arbeit mit weniger Stunden als Vollzeit"}],"rule":"Uncountable; often used as 'in Teilzeit arbeiten' or compound 'Teilzeitjob'.","example":"Sie arbeitet in Teilzeit.","exampleEn":"She works part-time.","example2":"Ich suche eine Stelle in Teilzeit.","example2En":"I'm looking for a part-time job."},{"de":"die Teilzeitstelle","en":"part-time job","pos":"noun","plural":"die Teilzeitstellen","meanings":[{"en":"a job with reduced working hours","de":"eine Arbeitsstelle mit weniger als der vollen Stundenzahl"}],"rule":"Compound noun: Teilzeit (part-time) + Stelle (job/position); gender follows die Stelle.","example":"Sie sucht eine Teilzeitstelle im Büro.","exampleEn":"She is looking for a part-time job in an office.","example2":"Nach der Geburt arbeitet er nur noch in Teilzeit.","example2En":"After the birth he only works part-time now."},{"de":"telefonisch","en":"by phone","pos":"adjective","plural":"","meanings":[{"en":"done or reachable by telephone","de":"per Telefon"}],"rule":"Used mainly as an adverb/adjective with contact-related nouns; no irregular comparison.","example":"Bitte melden Sie sich telefonisch bei uns.","exampleEn":"Please contact us by phone.","example2":"Der Termin wurde telefonisch bestätigt.","example2En":"The appointment was confirmed by phone."},{"de":"die Temperatur","en":"temperature","pos":"noun","plural":"die Temperaturen","meanings":[{"en":"degree of heat or cold","de":"Wärmegrad"}],"rule":"Feminine noun ending in -ur; often used with 'messen' or 'steigt/sinkt'.","example":"Die Temperatur steigt heute auf 25 Grad.","exampleEn":"The temperature rises to 25 degrees today.","example2":"Der Arzt misst die Temperatur des Patienten.","example2En":"The doctor measures the patient's temperature."},{"de":"die Terminplanung","en":"scheduling; appointment planning","pos":"noun","plural":"die Terminplanungen","meanings":[{"en":"organizing appointments and dates","de":"das Planen von Terminen"}],"rule":"Compound of Termin (appointment) + Planung (planning); often work-related, plural rarely used.","example":"Die Terminplanung übernimmt meine Kollegin.","exampleEn":"My colleague handles the scheduling.","example2":"Gute Terminplanung spart viel Zeit.","example2En":"Good scheduling saves a lot of time."},{"de":"der Test","en":"test","pos":"noun","plural":"die Tests","meanings":[{"en":"an examination or trial to check something","de":"eine Prüfung oder Überprüfung"}],"rule":"Masculine noun; plural Tests (from English), pronounced with final -s.","example":"Morgen schreiben wir einen Test in Deutsch.","exampleEn":"Tomorrow we're writing a test in German.","example2":"Der Test zeigt, ob das Gerät funktioniert.","example2En":"The test shows whether the device works."},{"de":"das Theater","en":"theater","pos":"noun","plural":"die Theater","meanings":[{"en":"a building or art form for stage plays","de":"ein Gebäude oder eine Kunstform für Bühnenstücke"},{"en":"(informal) a fuss or drama","de":"(umgangssprachlich) viel Aufregung ohne Grund"}],"rule":"Neuter noun; plural unchanged (die Theater). Informal sense 'Theater machen' = to make a fuss.","example":"Wir gehen heute Abend ins Theater.","exampleEn":"We're going to the theater tonight.","example2":"Mach doch nicht so ein Theater!","example2En":"Don't make such a fuss!"},{"de":"das Thema","en":"topic","pos":"noun","plural":"die Themen","meanings":[{"en":"subject of discussion or writing","de":"Gegenstand eines Gesprächs oder Textes"}],"rule":"Neuter noun with Greek origin; irregular plural die Themen (not Themas).","example":"Das Thema der Diskussion ist Umweltschutz.","exampleEn":"The topic of the discussion is environmental protection.","example2":"Wir sprechen heute über ein neues Thema.","example2En":"Today we're talking about a new topic."},{"de":"die Theorie","en":"theory","pos":"noun","plural":"die Theorien","meanings":[{"en":"an idea or system explaining something","de":"ein Gedankensystem zur Erklärung von etwas"}],"rule":"Feminine noun ending in -ie, stress on the final syllable; often paired with 'Praxis'.","example":"In der Theorie klingt der Plan gut.","exampleEn":"In theory, the plan sounds good.","example2":"Wir lernen zuerst die Theorie, dann die Praxis.","example2En":"We first learn the theory, then the practice."},{"de":"die Therapie","en":"therapy","pos":"noun","plural":"die Therapien","meanings":[{"en":"medical or psychological treatment","de":"medizinische oder psychologische Behandlung"}],"rule":"Feminine noun ending in -ie; often with 'machen' or 'beginnen'.","example":"Er macht seit einem Monat eine Therapie.","exampleEn":"He has been in therapy for a month.","example2":"Die Therapie hilft ihr bei den Schmerzen.","example2En":"The therapy helps her with the pain."},{"de":"die Tiefgarage","en":"underground parking garage","pos":"noun","plural":"die Tiefgaragen","meanings":[{"en":"a parking garage below ground level","de":"eine Garage unter der Erde"}],"rule":"Compound: tief (deep) + Garage; gender follows die Garage.","example":"Wir parken das Auto in der Tiefgarage.","exampleEn":"We park the car in the underground garage.","example2":"Die Tiefgarage ist rund um die Uhr geöffnet.","example2En":"The underground garage is open around the clock."}]},{"id":"a2-18","title":"A2 · T–U (18)","level":"A2","words":[{"de":"das Tier","en":"animal","pos":"noun","plural":"die Tiere","meanings":[{"en":"a living creature, not human or plant","de":"ein Lebewesen, kein Mensch und keine Pflanze"}],"rule":"Neuter noun; common plural die Tiere.","example":"Im Zoo gibt es viele verschiedene Tiere.","exampleEn":"There are many different animals at the zoo.","example2":"Hast du zu Hause ein Tier?","example2En":"Do you have a pet (animal) at home?"},{"de":"der Tierpfleger / die Tierpflegerin","en":"animal keeper; zookeeper","pos":"noun","plural":"die Tierpfleger / die Tierpflegerinnen","meanings":[{"en":"a person who cares for animals professionally","de":"eine Person, die beruflich Tiere pflegt"}],"rule":"Compound Tier + Pfleger; female form adds -in.","example":"Der Tierpfleger füttert die Löwen im Zoo.","exampleEn":"The zookeeper feeds the lions at the zoo.","example2":"Sie arbeitet als Tierpflegerin in einer Tierklinik.","example2En":"She works as an animal keeper in a veterinary clinic."},{"de":"tippen","en":"to type; to tap","pos":"verb","plural":"","meanings":[{"en":"to write using a keyboard","de":"mit der Tastatur schreiben"},{"en":"to tap lightly with a finger","de":"leicht mit dem Finger berühren"}],"rule":"Regular weak verb: tippt, tippte, hat getippt.","example":"Sie tippt den Text schnell in den Computer.","exampleEn":"She types the text quickly into the computer.","example2":"Er hat ihr auf die Schulter getippt.","example2En":"He tapped her on the shoulder."},{"de":"der Tippfehler","en":"typo","pos":"noun","plural":"die Tippfehler","meanings":[{"en":"a small mistake made while typing","de":"ein kleiner Fehler beim Tippen"}],"rule":"Compound: tippen + Fehler; plural unchanged (der/die Tippfehler).","example":"In der E-Mail ist ein Tippfehler.","exampleEn":"There's a typo in the email.","example2":"Ich korrigiere schnell die Tippfehler im Text.","example2En":"I'm quickly correcting the typos in the text."},{"de":"die Tischdecke","en":"tablecloth","pos":"noun","plural":"die Tischdecken","meanings":[{"en":"a cloth covering a table","de":"ein Tuch, das einen Tisch bedeckt"}],"rule":"Compound: Tisch + Decke; gender follows die Decke.","example":"Sie legt eine weiße Tischdecke auf den Tisch.","exampleEn":"She puts a white tablecloth on the table.","example2":"Die Tischdecke ist beim Essen schmutzig geworden.","example2En":"The tablecloth got dirty during the meal."},{"de":"die Tischdekoration","en":"table decoration","pos":"noun","plural":"die Tischdekorationen","meanings":[{"en":"decorative items arranged on a table","de":"Dekoration, die auf dem Tisch angeordnet wird"}],"rule":"Compound: Tisch + Dekoration; often used for parties or celebrations.","example":"Für die Feier kaufen wir eine schöne Tischdekoration.","exampleEn":"For the party we're buying nice table decorations.","example2":"Blumen sind eine beliebte Tischdekoration.","example2En":"Flowers are a popular table decoration."},{"de":"der Tischler / die Tischlerin","en":"carpenter; joiner","pos":"noun","plural":"die Tischler / die Tischlerinnen","meanings":[{"en":"a craftsperson who makes things from wood","de":"ein Handwerker, der aus Holz Dinge herstellt"}],"rule":"From Tisch (table); female form adds -in.","example":"Der Tischler baut einen neuen Schrank.","exampleEn":"The carpenter is building a new cupboard.","example2":"Sie hat eine Ausbildung als Tischlerin gemacht.","example2En":"She trained as a carpenter."},{"de":"der Toaster","en":"toaster","pos":"noun","plural":"die Toaster","meanings":[{"en":"an appliance for toasting bread","de":"ein Gerät zum Rösten von Brot"}],"rule":"Masculine loanword from English; plural unchanged (die Toaster).","example":"Der Toaster ist kaputt, das Brot wird nicht braun.","exampleEn":"The toaster is broken, the bread doesn't turn brown.","example2":"Ich mache mir morgens Toast im Toaster.","example2En":"In the morning I make toast in the toaster."},{"de":"die Tonne","en":"ton; bin/barrel","pos":"noun","plural":"die Tonnen","meanings":[{"en":"unit of weight (1000 kg)","de":"Gewichtseinheit (1000 kg)"},{"en":"large container/bin for waste","de":"großer Behälter, z. B. für Müll"}],"rule":"Feminine noun; die Tonne, die Tonnen. Context decides meaning (weight vs. container).","example":"Der Laster transportiert zehn Tonnen Kies.","exampleEn":"The truck is carrying ten tons of gravel.","example2":"Wirf das Papier in die blaue Tonne.","example2En":"Throw the paper into the blue bin."},{"de":"der Trainer / die Trainerin","en":"coach, trainer","pos":"noun","plural":"die Trainer / die Trainerinnen","meanings":[{"en":"sports coach or fitness trainer","de":"Person, die Sportler trainiert"}],"rule":"Masculine der Trainer, feminine die Trainerin; plural die Trainer/die Trainerinnen.","example":"Unser Trainer ist sehr streng.","exampleEn":"Our coach is very strict.","example2":"Die Trainerin zeigt uns neue Übungen.","example2En":"The coach (female) shows us new exercises."},{"de":"trainieren","en":"to train, to practise","pos":"verb","plural":"","meanings":[{"en":"to exercise physically","de":"Sport treiben, üben"},{"en":"to coach/train someone","de":"jemanden ausbilden"}],"rule":"Regular weak verb: trainiert, trainierte, hat trainiert.","example":"Ich trainiere dreimal pro Woche im Fitnessstudio.","exampleEn":"I train three times a week at the gym.","example2":"Er trainiert die Jugendmannschaft.","example2En":"He coaches the youth team."},{"de":"das Training","en":"training, practice","pos":"noun","plural":"die Trainings","meanings":[{"en":"physical/sports practice session","de":"regelmäßige Übung, z. B. im Sport"}],"rule":"Neuter noun; das Training, die Trainings (sometimes used uncountable, no plural needed).","example":"Das Training beginnt um 18 Uhr.","exampleEn":"Training starts at 6 p.m.","example2":"Nach dem Training bin ich immer müde.","example2En":"After training I'm always tired."},{"de":"träumen","en":"to dream","pos":"verb","plural":"","meanings":[{"en":"to dream while sleeping","de":"im Schlaf träumen"},{"en":"to dream/wish for something (daydream)","de":"sich etwas wünschen"}],"rule":"Regular weak verb: träumt, träumte, hat geträumt. 'von + Dativ' = to dream of/about.","example":"Ich habe von meiner Familie geträumt.","exampleEn":"I dreamed about my family.","example2":"Sie träumt von einer Reise nach Japan.","example2En":"She dreams of a trip to Japan."},{"de":"traurig","en":"sad","pos":"adjective","plural":"","meanings":[{"en":"feeling or showing sadness","de":"unglücklich, nicht fröhlich"}],"rule":"Regular comparison: traurig, trauriger, am traurigsten.","example":"Er ist traurig, weil sein Hund krank ist.","exampleEn":"He is sad because his dog is sick.","example2":"Das ist eine traurige Geschichte.","example2En":"That is a sad story."},{"de":"der Treffpunkt","en":"meeting point","pos":"noun","plural":"die Treffpunkte","meanings":[{"en":"agreed place where people meet","de":"vereinbarter Ort zum Treffen"}],"rule":"Masculine noun; compound of treffen + Punkt. der Treffpunkt, die Treffpunkte.","example":"Der Treffpunkt ist vor dem Bahnhof.","exampleEn":"The meeting point is in front of the station.","example2":"Wir haben einen Treffpunkt für morgen vereinbart.","example2En":"We agreed on a meeting point for tomorrow."},{"de":"treiben","en":"to do (sport); to drift","pos":"verb","plural":"","meanings":[{"en":"to do/practise (a sport)","de":"eine Tätigkeit ausüben, z. B. Sport treiben"},{"en":"to drift, to be carried along","de":"sich ohne eigene Kraft bewegen"}],"rule":"Irregular: treibt, trieb, hat/ist getrieben (hat + Sport treiben; ist when about drifting). Common phrase: Sport treiben.","example":"Ich treibe jeden Tag Sport.","exampleEn":"I do sports every day.","example2":"Das Boot ist auf dem See getrieben.","example2En":"The boat drifted on the lake."},{"de":"trennen","en":"to separate, to split up","pos":"verb","plural":"","meanings":[{"en":"to separate/divide things","de":"etwas auseinandernehmen, teilen"},{"en":"sich trennen: to break up/separate (people)","de":"sich von jemandem trennen"}],"rule":"Regular weak verb: trennt, trennte, hat getrennt. Reflexive 'sich trennen (von + Dativ)' = to break up with.","example":"Bitte trennen Sie den Müll.","exampleEn":"Please separate the waste/recycling.","example2":"Meine Eltern haben sich letztes Jahr getrennt.","example2En":"My parents separated last year."},{"de":"die Treppe","en":"stairs, staircase","pos":"noun","plural":"die Treppen","meanings":[{"en":"set of steps between floors","de":"Stufen, die nach oben/unten führen"}],"rule":"Feminine noun; die Treppe, die Treppen.","example":"Die Treppe führt in den ersten Stock.","exampleEn":"The stairs lead to the first floor.","example2":"Sei vorsichtig auf der Treppe!","example2En":"Be careful on the stairs!"},{"de":"das Treppenhaus","en":"stairwell, staircase (of a building)","pos":"noun","plural":"die Treppenhäuser","meanings":[{"en":"the enclosed area containing the staircase in a building","de":"Bereich im Gebäude mit der Treppe"}],"rule":"Neuter compound noun (die Treppe + das Haus); das Treppenhaus, die Treppenhäuser.","example":"Das Fahrrad steht im Treppenhaus.","exampleEn":"The bicycle is in the stairwell.","example2":"Im Treppenhaus ist es sehr dunkel.","example2En":"It's very dark in the stairwell."},{"de":"der Trick","en":"trick","pos":"noun","plural":"die Tricks","meanings":[{"en":"a clever technique or method","de":"cleverer Kniff, Methode"},{"en":"a magic trick or prank","de":"Zaubertrick, Streich"}],"rule":"Masculine noun; der Trick, die Tricks (from English, common loanword).","example":"Kennst du einen Trick zum Deutschlernen?","exampleEn":"Do you know a trick for learning German?","example2":"Der Zauberer zeigt einen neuen Trick.","example2En":"The magician shows a new trick."},{"de":"trotzdem","en":"nevertheless, anyway","pos":"adverb","plural":"","meanings":[{"en":"despite that, still","de":"obwohl das so ist, dennoch"}],"rule":"Adverb used to connect two contrasting ideas; often triggers inversion: 'Es regnet, trotzdem gehe ich raus.'","example":"Es regnet, trotzdem gehe ich spazieren.","exampleEn":"It's raining, but I'm going for a walk anyway.","example2":"Er war krank, trotzdem ist er zur Arbeit gegangen.","example2En":"He was sick, but he went to work anyway."},{"de":"turnen","en":"to do gymnastics","pos":"verb","plural":"","meanings":[{"en":"to practise gymnastics","de":"gymnastische Übungen machen"}],"rule":"Regular weak verb: turnt, turnte, hat geturnt.","example":"Die Kinder turnen in der Sporthalle.","exampleEn":"The children do gymnastics in the gym.","example2":"Sie turnt seit drei Jahren im Verein.","example2En":"She has been doing gymnastics in a club for three years."},{"de":"die Tüte","en":"bag, paper/plastic bag","pos":"noun","plural":"die Tüten","meanings":[{"en":"small bag made of paper or plastic","de":"kleiner Beutel aus Papier oder Plastik"}],"rule":"Feminine noun; die Tüte, die Tüten.","example":"Ich brauche eine Tüte für die Äpfel.","exampleEn":"I need a bag for the apples.","example2":"Sie trägt die Einkäufe in einer Tüte.","example2En":"She carries the groceries in a bag."},{"de":"die Übelkeit","en":"nausea","pos":"noun","plural":"","meanings":[{"en":"feeling of sickness/wanting to vomit","de":"Gefühl, sich übergeben zu müssen"}],"rule":"Feminine noun, usually uncountable; die Übelkeit (no plural).","example":"Sie hat Übelkeit und Kopfschmerzen.","exampleEn":"She has nausea and a headache.","example2":"Nach der Fahrt spürte ich starke Übelkeit.","example2En":"After the ride I felt strong nausea."},{"de":"üben","en":"to practise","pos":"verb","plural":"","meanings":[{"en":"to practise/train a skill","de":"eine Fähigkeit trainieren"}],"rule":"Regular weak verb: übt, übte, hat geübt.","example":"Ich übe jeden Tag Klavier.","exampleEn":"I practise piano every day.","example2":"Wir üben die neuen Wörter zusammen.","example2En":"We practise the new words together."},{"de":"der Überfall","en":"assault, raid, robbery","pos":"noun","plural":"die Überfälle","meanings":[{"en":"a sudden violent attack or robbery","de":"plötzlicher, gewaltsamer Angriff, z. B. Raubüberfall"}],"rule":"Masculine noun; der Überfall, die Überfälle. Related verb: überfallen (jemanden überfallen).","example":"Die Polizei ermittelt wegen eines Überfalls auf die Bank.","exampleEn":"The police are investigating a bank robbery.","example2":"Bei dem Überfall wurde niemand verletzt.","example2En":"No one was injured in the assault."},{"de":"überfallen","en":"to attack; to raid","pos":"verb","plural":"","meanings":[{"en":"to attack someone suddenly","de":"plötzlich angreifen"},{"en":"to rob (a bank, shop)","de":"ausrauben"}],"rule":"untrennbar, unregelmäßig: überfällt, überfiel, hat überfallen; + Akkusativ","example":"Zwei Männer haben die Bank überfallen.","exampleEn":"Two men robbed the bank.","example2":"Ein Mann hat sie nachts auf der Straße überfallen.","example2En":"A man attacked her on the street at night."},{"de":"überlasten","en":"to overload","pos":"verb","plural":"","meanings":[{"en":"to put too much weight/load on something","de":"zu stark belasten"},{"en":"to overburden a person","de":"jemanden zu sehr beanspruchen"}],"rule":"untrennbar, regelmäßig: überlastet, überlastete, hat überlastet; + Akkusativ","example":"Bitte den Aufzug nicht überlasten.","exampleEn":"Please do not overload the elevator.","example2":"Die viele Arbeit überlastet die Mitarbeiter.","example2En":"The heavy workload is overburdening the employees."},{"de":"übernehmen","en":"to take over; to take on","pos":"verb","plural":"","meanings":[{"en":"to take over (a job, business, task)","de":"eine Aufgabe/Firma übernehmen"},{"en":"sich übernehmen: to overexert oneself","de":"sich zu viel zumuten"}],"rule":"untrennbar, unregelmäßig: übernimmt, übernahm, hat übernommen; + Akkusativ; reflexiv: sich übernehmen","example":"Meine Tochter übernimmt den Familienbetrieb.","exampleEn":"My daughter is taking over the family business.","example2":"Er hat sich mit der Arbeit übernommen.","example2En":"He overexerted himself with the work."},{"de":"die Überraschung","en":"surprise","pos":"noun","plural":"die Überraschungen","meanings":[{"en":"an unexpected event or gift","de":"etwas Unerwartetes"}],"rule":"feminin; von überraschen abgeleitet","example":"Das Geschenk war eine schöne Überraschung.","exampleEn":"The gift was a lovely surprise.","example2":"Zur Überraschung aller hat er gewonnen.","example2En":"To everyone's surprise, he won."},{"de":"die Überschrift","en":"heading; headline","pos":"noun","plural":"die Überschriften","meanings":[{"en":"a title above a text or article","de":"Titel über einem Text"}],"rule":"feminin; steht über einem Text (Zeitungsartikel, Kapitel)","example":"Der Artikel hat eine lange Überschrift.","exampleEn":"The article has a long headline.","example2":"Lies zuerst die Überschrift.","example2En":"First read the heading."},{"de":"übersenden","en":"to send (formally)","pos":"verb","plural":"","meanings":[{"en":"to send something, esp. by post/mail (formal)","de":"etwas schicken (formell)"}],"rule":"untrennbar, unregelmäßig: übersendet, übersandte/übersendete, hat übersandt/übersendet; + Dativ (Person) + Akkusativ (Sache)","example":"Wir übersenden Ihnen die Unterlagen per Post.","exampleEn":"We are sending you the documents by mail.","example2":"Bitte übersenden Sie uns eine Kopie des Vertrags.","example2En":"Please send us a copy of the contract."},{"de":"die Übersiedlung","en":"relocation; move","pos":"noun","plural":"die Übersiedlungen","meanings":[{"en":"moving to a new (often distant) place to live","de":"Umzug an einen neuen Wohnort"}],"rule":"feminin; formeller als Umzug, oft bei Wohnortwechsel ins Ausland","example":"Nach der Übersiedlung nach Berlin war alles neu.","exampleEn":"After the move to Berlin everything was new.","example2":"Die Übersiedlung der Familie dauerte Monate.","example2En":"The family's relocation took months."},{"de":"die Überwachungskamera","en":"surveillance camera","pos":"noun","plural":"die Überwachungskameras","meanings":[{"en":"a camera used to monitor an area for security","de":"Kamera zur Kontrolle eines Bereichs"}],"rule":"feminin; Kompositum aus Überwachung + Kamera","example":"Im Supermarkt hängt eine Überwachungskamera.","exampleEn":"There is a surveillance camera in the supermarket.","example2":"Die Überwachungskamera hat den Dieb gefilmt.","example2En":"The surveillance camera filmed the thief."},{"de":"überweisen","en":"to transfer (money); to refer (a patient)","pos":"verb","plural":"","meanings":[{"en":"to transfer money to an account","de":"Geld auf ein Konto schicken"},{"en":"to refer a patient to a specialist","de":"einen Patienten an einen Arzt verweisen"}],"rule":"untrennbar, unregelmäßig: überweist, überwies, hat überwiesen; + Akkusativ (Geld/Patient) + an/auf","example":"Ich überweise dir das Geld heute noch.","exampleEn":"I'll transfer you the money today.","example2":"Der Arzt hat mich an einen Facharzt überwiesen.","example2En":"The doctor referred me to a specialist."},{"de":"die Überweisung","en":"bank transfer; referral","pos":"noun","plural":"die Überweisungen","meanings":[{"en":"a transfer of money","de":"das Überweisen von Geld"},{"en":"a referral to a specialist doctor","de":"Verweis an einen Facharzt"}],"rule":"feminin; von überweisen abgeleitet","example":"Die Überweisung dauert zwei Werktage.","exampleEn":"The bank transfer takes two working days.","example2":"Ich brauche eine Überweisung zum Augenarzt.","example2En":"I need a referral to the eye doctor."},{"de":"das Überweisungsformular","en":"bank transfer form","pos":"noun","plural":"die Überweisungsformulare","meanings":[{"en":"a paper form used to make a bank transfer","de":"Formular für eine Banküberweisung"}],"rule":"neutral; Kompositum aus Überweisung + Formular","example":"Füllen Sie bitte das Überweisungsformular aus.","exampleEn":"Please fill out the bank transfer form.","example2":"Das Überweisungsformular liegt am Schalter.","example2En":"The transfer form is at the counter."},{"de":"übrigens","en":"by the way","pos":"adverb","plural":"","meanings":[{"en":"used to add an extra remark","de":"nebenbei bemerkt"}],"rule":"unveränderlich; leitet oft einen neuen, zusätzlichen Gedanken ein","example":"Übrigens, hast du meine Nachricht bekommen?","exampleEn":"By the way, did you get my message?","example2":"Das Restaurant ist übrigens sehr gut.","example2En":"The restaurant, by the way, is very good."},{"de":"umfangreich","en":"extensive; comprehensive","pos":"adjective","plural":"","meanings":[{"en":"large in scope or content","de":"sehr groß, viel umfassend"}],"rule":"regelmäßige Steigerung: umfangreich, umfangreicher, am umfangreichsten","example":"Das Buch hat ein umfangreiches Register.","exampleEn":"The book has an extensive index.","example2":"Die Renovierung war sehr umfangreich.","example2En":"The renovation was very extensive."},{"de":"die Umfrage","en":"survey; poll","pos":"noun","plural":"die Umfragen","meanings":[{"en":"a survey of people's opinions","de":"Befragung von Personen zu einem Thema"}],"rule":"feminin; oft mit machen: eine Umfrage machen","example":"Wir machen eine Umfrage zur Kundenzufriedenheit.","exampleEn":"We are conducting a customer satisfaction survey.","example2":"Laut einer Umfrage sind viele Leute zufrieden.","example2En":"According to a survey, many people are satisfied."},{"de":"die Umkleide","en":"changing room","pos":"noun","plural":"die Umkleiden","meanings":[{"en":"a room to change clothes, e.g. in a shop or gym","de":"Raum zum Umziehen"}],"rule":"feminin; Kurzform von Umkleidekabine/Umkleideraum","example":"Die Umkleide ist links neben der Kasse.","exampleEn":"The changing room is to the left of the checkout.","example2":"In der Umkleide kannst du die Hose anprobieren.","example2En":"You can try on the trousers in the changing room."},{"de":"umknicken","en":"to sprain (ankle); to fold over","pos":"verb","plural":"","meanings":[{"en":"to twist one's ankle","de":"sich den Fuß verdrehen"},{"en":"to bend/fold over (an object)","de":"etwas Dünnes umbiegen"}],"rule":"trennbar: knickt ... um, knickte um, ist/hat umgeknickt (Person: ist; Gegenstand: hat)","example":"Ich bin beim Joggen umgeknickt.","exampleEn":"I twisted my ankle while jogging.","example2":"Er hat die Ecke der Seite umgeknickt.","example2En":"He folded over the corner of the page."},{"de":"umschreiben","en":"to rewrite","pos":"verb","plural":"","meanings":[{"en":"to rewrite a text","de":"einen Text neu/anders schreiben"}],"rule":"trennbar (um·schreiben, betont auf 'um'): schreibt um, schrieb um, hat umgeschrieben; Achtung: umschreíben (untrennbar) = paraphrasieren, anderes Wort","example":"Ich muss den Brief noch einmal umschreiben.","exampleEn":"I still have to rewrite the letter.","example2":"Sie hat den Aufsatz komplett umgeschrieben.","example2En":"She rewrote the essay completely."},{"de":"umsteigen","en":"to change (trains/buses)","pos":"verb","plural":"","meanings":[{"en":"to change from one train/bus to another","de":"von einem Zug/Bus in einen anderen wechseln"}],"rule":"trennbar: steigt ... um, stieg um, ist umgestiegen; + in + Akkusativ","example":"In München müssen wir umsteigen.","exampleEn":"We have to change trains in Munich.","example2":"Sie ist in den Bus 12 umgestiegen.","example2En":"She changed to bus number 12."},{"de":"die Umwelt","en":"environment","pos":"noun","plural":"","meanings":[{"en":"the natural world (nature, ecology)","de":"die Natur, in der wir leben"}],"rule":"Usually used in singular, uncountable (no plural). Common in compounds: der Umweltschutz, umweltfreundlich.","example":"Wir müssen die Umwelt schützen.","exampleEn":"We have to protect the environment.","example2":"Plastiktüten sind schlecht für die Umwelt.","example2En":"Plastic bags are bad for the environment."},{"de":"umziehen","en":"to move (house); to change clothes","pos":"verb","plural":"","meanings":[{"en":"to move to a new home","de":"in eine neue Wohnung ziehen"},{"en":"to change one's clothes (sich umziehen)","de":"sich andere Kleidung anziehen"}],"rule":"trennbar: zieht ... um, zog um, ist umgezogen (move house). Reflexive 'sich umziehen' (change clothes) uses 'haben' in Perfekt: hat sich umgezogen.","example":"Wir ziehen nächsten Monat nach Berlin um.","exampleEn":"We are moving to Berlin next month.","example2":"Ich muss mich noch umziehen, bevor wir gehen.","example2En":"I still need to change clothes before we leave."},{"de":"der Umzug","en":"move, relocation","pos":"noun","plural":"die Umzüge","meanings":[{"en":"the act of moving house","de":"das Umziehen in eine neue Wohnung"}],"rule":"Related to the verb 'umziehen'. Can also mean a parade/procession, but in this deck focus on 'moving house'.","example":"Der Umzug hat den ganzen Tag gedauert.","exampleEn":"The move took the whole day.","example2":"Für den Umzug brauchen wir viele Kartons.","example2En":"We need a lot of boxes for the move."},{"de":"der Umzugskarton","en":"moving box","pos":"noun","plural":"die Umzugskartons","meanings":[{"en":"a cardboard box used for moving house","de":"ein Karton, in den man Sachen für den Umzug packt"}],"rule":"Compound noun: Umzug + Karton. Plural takes -s like 'Karton(s)'.","example":"Ich packe meine Bücher in einen Umzugskarton.","exampleEn":"I'm packing my books into a moving box.","example2":"Wir brauchen noch zehn Umzugskartons.","example2En":"We still need ten more moving boxes."},{"de":"unbürokratisch","en":"unbureaucratic, uncomplicated","pos":"adjective","plural":"","meanings":[{"en":"done without complicated formalities","de":"ohne viel Bürokratie, einfach und schnell"}],"rule":"Negation of 'bürokratisch' with prefix 'un-'. Regular comparison: unbürokratisch, unbürokratischer, am unbürokratischsten.","example":"Die Beratung war schnell und unbürokratisch.","exampleEn":"The consultation was quick and uncomplicated.","example2":"Können Sie mir unbürokratisch helfen?","example2En":"Can you help me without a lot of red tape?"},{"de":"unfair","en":"unfair","pos":"adjective","plural":"","meanings":[{"en":"not fair or just","de":"nicht gerecht"}],"rule":"Negation of 'fair' with 'un-'. Regular comparison: unfair, unfairer, am unfairsten.","example":"Das Spiel war sehr unfair.","exampleEn":"The game was very unfair.","example2":"Ich finde die Regel unfair.","example2En":"I think the rule is unfair."}]},{"id":"a2-19","title":"A2 · U–V (19)","level":"A2","words":[{"de":"ungarisch","en":"Hungarian","pos":"adjective","plural":"","meanings":[{"en":"relating to Hungary or the Hungarian language","de":"aus Ungarn, die Sprache Ungarns betreffend"}],"rule":"Adjectives of nationality are lowercase in German: ungarisch. The noun for the country is 'Ungarn' and the language is 'Ungarisch' (capitalized when used as a noun, e.g. after 'sprechen').","example":"Sie spricht sehr gut Ungarisch.","exampleEn":"She speaks Hungarian very well.","example2":"Er mag die ungarische Küche.","example2En":"He likes Hungarian cuisine."},{"de":"ungenügend","en":"insufficient, inadequate","pos":"adjective","plural":"","meanings":[{"en":"not good enough, failing (grade)","de":"nicht ausreichend, schlecht"}],"rule":"Negation of 'genügend'. Also used as the worst German school grade (6 = ungenügend). Regular comparison, rarely used in comparative/superlative.","example":"Seine Deutschkenntnisse sind noch ungenügend.","exampleEn":"His German skills are still insufficient.","example2":"Er hat in der Prüfung die Note 'ungenügend' bekommen.","example2En":"He got the grade 'insufficient' on the exam."},{"de":"die Uniform","en":"uniform","pos":"noun","plural":"die Uniformen","meanings":[{"en":"special clothing worn by members of an organization","de":"einheitliche Kleidung, z. B. bei der Polizei"}],"rule":"Feminine noun; regular plural -en.","example":"Der Polizist trägt eine Uniform.","exampleEn":"The police officer wears a uniform.","example2":"In dieser Schule tragen die Kinder Uniformen.","example2En":"At this school, the children wear uniforms."},{"de":"unprofessionell","en":"unprofessional","pos":"adjective","plural":"","meanings":[{"en":"not showing the skill or standards expected","de":"nicht professionell, unsachgemäß"}],"rule":"Negation of 'professionell' with 'un-'. Regular comparison: unprofessionell, unprofessioneller, am unprofessionellsten.","example":"Der Kellner war ziemlich unprofessionell.","exampleEn":"The waiter was quite unprofessional.","example2":"Das Foto sieht sehr unprofessionell aus.","example2En":"The photo looks very unprofessional."},{"de":"unsympathisch","en":"unlikeable, unpleasant (person)","pos":"adjective","plural":"","meanings":[{"en":"not likeable, causing dislike","de":"nicht sympathisch, unangenehm"}],"rule":"Negation of 'sympathisch'. Note: 'sympathisch' is a false friend, it means 'likeable', not 'sympathetic'. Regular comparison.","example":"Der neue Kollege ist mir unsympathisch.","exampleEn":"I don't like the new colleague (he seems unlikeable to me).","example2":"Sein Verhalten fand ich sehr unsympathisch.","example2En":"I found his behavior very off-putting."},{"de":"unten","en":"below, downstairs, at the bottom","pos":"adverb","plural":"","meanings":[{"en":"in a lower position, downstairs","de":"an einer tiefer liegenden Stelle, im unteren Stockwerk"}],"rule":"Adverb of place, not declined. Opposite: oben. Often with 'da unten', 'nach unten' (movement) vs 'unten' (location).","example":"Die Küche ist unten.","exampleEn":"The kitchen is downstairs.","example2":"Warten Sie bitte unten am Eingang.","example2En":"Please wait downstairs at the entrance."},{"de":"unterhalten","en":"to entertain; to converse, chat","pos":"verb","plural":"","meanings":[{"en":"to entertain someone","de":"jemandem Spaß oder Freude bereiten"},{"en":"to have a conversation (sich unterhalten)","de":"sich mit jemandem sprechen, plaudern"}],"rule":"Untrennbar (inseparable, no 'ge-' in Perfekt): unterhält, unterhielt, hat unterhalten. Reflexive form 'sich unterhalten' (+ mit + Dativ) = to chat/converse.","example":"Der Clown unterhält die Kinder.","exampleEn":"The clown entertains the children.","example2":"Wir haben uns lange über die Reise unterhalten.","example2En":"We talked for a long time about the trip."},{"de":"die Unterlagen","en":"documents, papers","pos":"noun","plural":"die Unterlagen","meanings":[{"en":"official papers or documents needed for something","de":"Dokumente, Papiere, die man braucht"}],"rule":"Used almost only in plural (Plural). Common in job applications: Bewerbungsunterlagen.","example":"Bitte bringen Sie alle Unterlagen mit.","exampleEn":"Please bring all the documents with you.","example2":"Ich habe die Unterlagen für die Bewerbung noch nicht fertig.","example2En":"I haven't finished the application documents yet."},{"de":"unternehmen","en":"to undertake, to do (an activity)","pos":"verb","plural":"","meanings":[{"en":"to do something, especially for leisure","de":"etwas machen, z. B. in der Freizeit"}],"rule":"Untrennbar (inseparable): unternimmt, unternahm, hat unternommen. Often used as 'etwas unternehmen' = to do something together/take action.","example":"Am Wochenende wollen wir etwas unternehmen.","exampleEn":"We want to do something on the weekend.","example2":"Die Firma hat nichts gegen das Problem unternommen.","example2En":"The company did nothing about the problem."},{"de":"der Unterschied","en":"difference","pos":"noun","plural":"die Unterschiede","meanings":[{"en":"a way in which two things are not the same","de":"das, worin sich zwei Dinge unterscheiden"}],"rule":"Masculine noun; regular plural -e. Common phrase: 'im Unterschied zu' (in contrast to).","example":"Es gibt einen großen Unterschied zwischen den beiden Produkten.","exampleEn":"There is a big difference between the two products.","example2":"Was ist der Unterschied zwischen 'der' und 'die'?","example2En":"What's the difference between 'der' and 'die'?"},{"de":"unterschreiben","en":"to sign","pos":"verb","plural":"","meanings":[{"en":"to write one's signature on a document","de":"seinen Namen auf ein Dokument schreiben"}],"rule":"Untrennbar (inseparable, no 'ge-'): unterschreibt, unterschrieb, hat unterschrieben.","example":"Bitte unterschreiben Sie hier.","exampleEn":"Please sign here.","example2":"Er hat den Vertrag noch nicht unterschrieben.","example2En":"He hasn't signed the contract yet."},{"de":"unterstützen","en":"to support","pos":"verb","plural":"","meanings":[{"en":"to help or assist someone, e.g. financially or morally","de":"jemandem helfen, jemanden fördern"}],"rule":"Untrennbar (inseparable, no 'ge-'): unterstützt, unterstützte, hat unterstützt. Takes a direct object (+ Akkusativ).","example":"Meine Eltern unterstützen mich finanziell.","exampleEn":"My parents support me financially.","example2":"Kannst du mich bei dem Projekt unterstützen?","example2En":"Can you support me with the project?"},{"de":"die Unterwäsche","en":"underwear","pos":"noun","plural":"","meanings":[{"en":"underwear","de":"Kleidung, die man direkt auf der Haut trägt, unter der anderen Kleidung"}],"rule":"Nur Singular (uncountable), kein Plural.","example":"Ich kaufe neue Unterwäsche im Kaufhaus.","exampleEn":"I'm buying new underwear at the department store.","example2":"Die Unterwäsche liegt im obersten Schubfach.","example2En":"The underwear is in the top drawer."},{"de":"unterwegs","en":"on the way; out and about","pos":"adverb","plural":"","meanings":[{"en":"on the way / traveling","de":"nicht zu Hause, auf dem Weg irgendwohin"}],"rule":"Unveränderlich (keine Steigerung); oft mit 'sein': unterwegs sein.","example":"Ich bin gerade unterwegs zur Arbeit.","exampleEn":"I'm on my way to work right now.","example2":"Er ist viel geschäftlich unterwegs.","example2En":"He travels a lot for business."},{"de":"unzufrieden","en":"dissatisfied","pos":"adjective","plural":"","meanings":[{"en":"not satisfied, discontent","de":"nicht zufrieden"}],"rule":"Regelmäßige Steigerung: unzufrieden, unzufriedener, am unzufriedensten; oft mit 'mit + Dativ'.","example":"Sie ist unzufrieden mit ihrem neuen Job.","exampleEn":"She is dissatisfied with her new job.","example2":"Die Kunden waren unzufrieden mit dem Service.","example2En":"The customers were dissatisfied with the service."},{"de":"die Urkunde","en":"certificate, document","pos":"noun","plural":"die Urkunden","meanings":[{"en":"official certificate/document","de":"amtliches Dokument, z. B. Zeugnis oder Bescheinigung"}],"rule":"Femininum; oft in Verbindung mit Prüfungen, Heirat, Geburt (Geburtsurkunde).","example":"Er hat für den Kurs eine Urkunde bekommen.","exampleEn":"He received a certificate for the course.","example2":"Die Heiratsurkunde liegt im Schrank.","example2En":"The marriage certificate is in the cabinet."},{"de":"das Vanilleeis","en":"vanilla ice cream","pos":"noun","plural":"","meanings":[{"en":"vanilla-flavored ice cream","de":"Eis mit Vanillegeschmack"}],"rule":"Neutrum, meist nur Singular (uncountable).","example":"Ich nehme eine Kugel Vanilleeis, bitte.","exampleEn":"I'll have a scoop of vanilla ice cream, please.","example2":"Die Kinder lieben Vanilleeis mit Schokosoße.","example2En":"The children love vanilla ice cream with chocolate sauce."},{"de":"die Variante","en":"variant, version","pos":"noun","plural":"die Varianten","meanings":[{"en":"a different version of something","de":"eine andere Form oder Möglichkeit von etwas"}],"rule":"Femininum; oft mit 'von' oder als Adjektiv-Kompositum (Menüvariante).","example":"Das Restaurant bietet eine vegetarische Variante des Gerichts.","exampleEn":"The restaurant offers a vegetarian variant of the dish.","example2":"Welche Variante gefällt dir besser?","example2En":"Which variant do you like better?"},{"de":"die Vase","en":"vase","pos":"noun","plural":"die Vasen","meanings":[{"en":"container for flowers","de":"Gefäß für Blumen"}],"rule":"Femininum; Aussprache: VA-se, Betonung auf der ersten Silbe mit langem 'a' [ˈvaːzə].","example":"Ich stelle die Blumen in eine Vase.","exampleEn":"I'm putting the flowers in a vase.","example2":"Die Vase ist aus Glas und sehr zerbrechlich.","example2En":"The vase is made of glass and very fragile."},{"de":"der Vegetarier / die Vegetarierin","en":"vegetarian (person)","pos":"noun","plural":"die Vegetarier / die Vegetarierinnen","meanings":[{"en":"a person who doesn't eat meat","de":"eine Person, die kein Fleisch isst"}],"rule":"Maskulinum/Femininum-Paar; Plural bei beiden auf -innen bzw. unverändert im Maskulinum.","example":"Mein Bruder ist Vegetarier.","exampleEn":"My brother is a vegetarian.","example2":"Als Vegetarierin isst sie kein Fleisch und keinen Fisch.","example2En":"As a vegetarian, she eats no meat and no fish."},{"de":"vegetarisch","en":"vegetarian","pos":"adjective","plural":"","meanings":[{"en":"without meat","de":"ohne Fleisch"}],"rule":"Regelmäßige Adjektivendungen; keine Steigerung üblich.","example":"Ich esse gern vegetarisch.","exampleEn":"I like to eat vegetarian food.","example2":"Das Restaurant hat viele vegetarische Gerichte.","example2En":"The restaurant has many vegetarian dishes."},{"de":"die Verabredung","en":"appointment, date (arranged meeting)","pos":"noun","plural":"die Verabredungen","meanings":[{"en":"an arranged meeting or date","de":"ein vereinbartes Treffen"}],"rule":"Femininum; kann romantisches Date oder normales Treffen bedeuten (nicht für Arzttermine - dort sagt man 'Termin').","example":"Ich habe heute Abend eine Verabredung mit Freunden.","exampleEn":"I have a get-together with friends tonight.","example2":"Er hat seine Verabredung mit seinem Freund vergessen.","example2En":"He forgot his meeting with his friend."},{"de":"die Verabschiedung","en":"farewell, send-off","pos":"noun","plural":"die Verabschiedungen","meanings":[{"en":"act of saying goodbye / farewell event","de":"das Verabschieden, Abschiedsfeier"}],"rule":"Femininum; oft für eine offizielle Abschiedsfeier (Verabschiedung eines Kollegen).","example":"Am Freitag ist die Verabschiedung unseres Chefs.","exampleEn":"Our boss's farewell event is on Friday.","example2":"Die Verabschiedung am Bahnhof war sehr emotional.","example2En":"The farewell at the train station was very emotional."},{"de":"veranstalten","en":"to organize, to hold (an event)","pos":"verb","plural":"","meanings":[{"en":"to organize an event","de":"ein Fest, eine Feier o. Ä. organisieren"}],"rule":"Regelmäßig, nicht trennbar: veranstaltet, veranstaltete, hat veranstaltet.","example":"Wir veranstalten am Samstag eine Party.","exampleEn":"We're organizing a party on Saturday.","example2":"Die Schule veranstaltet jedes Jahr ein Sommerfest.","example2En":"The school organizes a summer festival every year."},{"de":"die Veranstaltung","en":"event","pos":"noun","plural":"die Veranstaltungen","meanings":[{"en":"organized event","de":"ein organisiertes Ereignis, z. B. Fest oder Konzert"}],"rule":"Femininum; häufig mit Adjektiven wie kulturell, öffentlich kombiniert.","example":"Die Veranstaltung findet im Stadtpark statt.","exampleEn":"The event takes place in the city park.","example2":"Wir haben Karten für die Veranstaltung gekauft.","example2En":"We bought tickets for the event."},{"de":"der Veranstaltungshinweis","en":"event notice, event announcement","pos":"noun","plural":"die Veranstaltungshinweise","meanings":[{"en":"a notice/announcement about an event","de":"ein Hinweis auf eine Veranstaltung"}],"rule":"Maskulinum; Kompositum aus Veranstaltung + Hinweis; oft in Zeitungen oder Online-Kalendern.","example":"In der Zeitung steht ein Veranstaltungshinweis zum Stadtfest.","exampleEn":"There's an event notice about the city festival in the newspaper.","example2":"Schau mal auf der Webseite nach dem Veranstaltungshinweis.","example2En":"Check the website for the event notice."},{"de":"der Veranstaltungstipp","en":"event tip, event recommendation","pos":"noun","plural":"die Veranstaltungstipps","meanings":[{"en":"a recommendation about an event worth attending","de":"eine Empfehlung für eine Veranstaltung"}],"rule":"Maskulinum; Kompositum aus Veranstaltung + Tipp; Plural mit -s.","example":"Hast du einen Veranstaltungstipp für das Wochenende?","exampleEn":"Do you have an event tip for the weekend?","example2":"Der Veranstaltungstipp der Woche ist ein Jazzkonzert.","example2En":"This week's event tip is a jazz concert."},{"de":"verbessern","en":"to improve, to correct","pos":"verb","plural":"","meanings":[{"en":"to make something better","de":"etwas besser machen"},{"en":"to correct a mistake","de":"einen Fehler korrigieren"}],"rule":"Regelmäßig, nicht trennbar: verbessert, verbesserte, hat verbessert; oft reflexiv: sich verbessern.","example":"Ich möchte mein Deutsch verbessern.","exampleEn":"I want to improve my German.","example2":"Der Lehrer hat meinen Fehler im Text verbessert.","example2En":"The teacher corrected my mistake in the text."},{"de":"die Verbindung","en":"connection","pos":"noun","plural":"die Verbindungen","meanings":[{"en":"a connection (transport, phone, internet)","de":"eine Verkehrs-, Telefon- oder Internetverbindung"},{"en":"a relationship/link between people or things","de":"eine Beziehung oder ein Zusammenhang"}],"rule":"Femininum; häufig: Zugverbindung, Telefonverbindung, in Verbindung stehen mit + Dativ.","example":"Die Zugverbindung nach Berlin ist sehr gut.","exampleEn":"The train connection to Berlin is very good.","example2":"Die Verbindung zum Internet ist gerade schlecht.","example2En":"The internet connection is bad right now."},{"de":"verboten","en":"forbidden; prohibited","pos":"adjective","plural":"","meanings":[{"en":"forbidden, not allowed","de":"nicht erlaubt"}],"rule":"Partizip II von 'verbieten' (verbietet, verbot, hat verboten); oft als Prädikativ: 'X ist verboten.'","example":"Rauchen ist hier verboten.","exampleEn":"Smoking is forbidden here.","example2":"Parken verboten!","example2En":"No parking!"},{"de":"der Verbrauchszähler","en":"consumption meter (e.g. electricity/water meter)","pos":"noun","plural":"die Verbrauchszähler","meanings":[{"en":"a meter that measures usage (electricity, water, gas)","de":"Gerät, das den Verbrauch misst"}],"rule":"Kompositum aus 'Verbrauch' (consumption) + 'Zähler' (meter) – NICHT 'Verbraucher' (consumer), da es den Verbrauch misst, nicht die Nutzer zählt; Plural bleibt unverändert wie bei 'der Zähler'.","example":"Der Verbrauchszähler zeigt den Stromverbrauch an.","exampleEn":"The consumption meter shows the electricity usage.","example2":"Bitte notieren Sie den Stand des Verbrauchszählers.","example2En":"Please note down the reading of the consumption meter."},{"de":"verbringen","en":"to spend (time)","pos":"verb","plural":"","meanings":[{"en":"to spend time (somewhere/doing something)","de":"Zeit an einem Ort oder mit etwas verbringen"}],"rule":"unregelmäßig: verbringt, verbrachte, hat verbracht; + Akkusativ (Zeitangabe)","example":"Wir verbringen den Urlaub am Meer.","exampleEn":"We are spending our vacation by the sea.","example2":"Sie verbringt viel Zeit mit ihren Freunden.","example2En":"She spends a lot of time with her friends."},{"de":"verehrt","en":"esteemed; dear (formal address)","pos":"adjective","plural":"","meanings":[{"en":"esteemed, respected, dear","de":"sehr geschätzt, hochgeachtet"}],"rule":"Partizip II von 'verehren' (to admire/revere), adjektivisch gebraucht; nimmt normale Adjektivendungen an, z. B. 'der verehrte Gast' (Singular mit Artikel) oder 'Sehr verehrte Damen und Herren' (formelle Anrede, Plural ohne Artikel).","example":"Sehr verehrte Damen und Herren, herzlich willkommen!","exampleEn":"Dear ladies and gentlemen, welcome!","example2":"Der verehrte Gast wurde herzlich begrüßt.","example2En":"The esteemed guest was warmly welcomed."},{"de":"vereinbaren","en":"to agree on; to arrange","pos":"verb","plural":"","meanings":[{"en":"to agree on / arrange (e.g. an appointment)","de":"etwas gemeinsam festlegen"}],"rule":"regelmäßig: vereinbart, vereinbarte, hat vereinbart; + Akkusativ","example":"Wir vereinbaren einen Termin beim Arzt.","exampleEn":"We are arranging an appointment with the doctor.","example2":"Können wir ein Treffen vereinbaren?","example2En":"Can we arrange a meeting?"},{"de":"die Vergangenheit","en":"the past","pos":"noun","plural":"","meanings":[{"en":"the past (time before now)","de":"die Zeit vor der Gegenwart"}],"rule":"meist unzählbar, kein Plural im Alltagsgebrauch","example":"In der Vergangenheit war das anders.","exampleEn":"In the past, it was different.","example2":"Er spricht selten über seine Vergangenheit.","example2En":"He rarely talks about his past."},{"de":"das Verhalten","en":"behavior; conduct","pos":"noun","plural":"","meanings":[{"en":"the way someone acts; behavior","de":"die Art, wie jemand handelt"}],"rule":"unzählbares Nomen (kein Plural im Alltag), von 'sich verhalten'","example":"Das Verhalten des Kindes war sehr höflich.","exampleEn":"The child's behavior was very polite.","example2":"Sein Verhalten im Straßenverkehr ist vorbildlich.","example2En":"His behavior in traffic is exemplary."},{"de":"verlegen","en":"to mislay; to postpone/move (a date)","pos":"verb","plural":"","meanings":[{"en":"to mislay, misplace (an object)","de":"etwas nicht mehr finden, weil man es weggelegt hat"},{"en":"to postpone, move (an appointment/date)","de":"einen Termin auf einen anderen Zeitpunkt legen"}],"rule":"regelmäßig: verlegt, verlegte, hat verlegt; + Akkusativ. Achtung: 'verlegen' kann auch Adjektiv sein (= peinlich berührt).","example":"Ich habe meinen Schlüssel verlegt.","exampleEn":"I've mislaid my keys.","example2":"Wir haben den Termin auf Montag verlegt.","example2En":"We moved the appointment to Monday."},{"de":"verlieren","en":"to lose","pos":"verb","plural":"","meanings":[{"en":"to lose (an object)","de":"etwas nicht mehr haben, weil es weg ist"},{"en":"to lose (a game/competition)","de":"bei einem Spiel nicht gewinnen"}],"rule":"unregelmäßig: verliert, verlor, hat verloren; + Akkusativ","example":"Ich habe meinen Schlüssel verloren.","exampleEn":"I lost my key.","example2":"Unsere Mannschaft hat das Spiel verloren.","example2En":"Our team lost the game."},{"de":"vermeiden","en":"to avoid","pos":"verb","plural":"","meanings":[{"en":"to avoid (something)","de":"etwas nicht tun oder nicht geschehen lassen"}],"rule":"unregelmäßig: vermeidet, vermied, hat vermieden; + Akkusativ","example":"Wir sollten Stress vermeiden.","exampleEn":"We should avoid stress.","example2":"Er vermeidet es, allein zu reisen.","example2En":"He avoids traveling alone."},{"de":"die Vermeidung","en":"avoidance","pos":"noun","plural":"","meanings":[{"en":"the act of avoiding something","de":"das Vermeiden von etwas"}],"rule":"unzählbares Nomen, von 'vermeiden'; oft in 'zur Vermeidung von...'","example":"Die Vermeidung von Müll ist wichtig für die Umwelt.","exampleEn":"Avoiding waste is important for the environment.","example2":"Zur Vermeidung von Fehlern sollten Sie die Anleitung lesen.","example2En":"To avoid mistakes, you should read the instructions."},{"de":"vermieten","en":"to rent out; to let","pos":"verb","plural":"","meanings":[{"en":"to rent out (a property) to someone","de":"jemandem eine Wohnung/ein Haus gegen Bezahlung überlassen"}],"rule":"regelmäßig: vermietet, vermietete, hat vermietet; + Akkusativ (+ an + Akkusativ)","example":"Wir vermieten unsere Wohnung für den Sommer.","exampleEn":"We are renting out our apartment for the summer.","example2":"Er vermietet Zimmer an Studenten.","example2En":"He rents out rooms to students."},{"de":"der Vermieter / die Vermieterin","en":"landlord / landlady","pos":"noun","plural":"die Vermieter / die Vermieterinnen","meanings":[{"en":"a person who rents out property","de":"jemand, der eine Wohnung oder ein Haus vermietet"}],"rule":"Gegensatz zu 'Mieter/in' (tenant); weibliche Form mit Endung -in","example":"Der Vermieter hat die Miete erhöht.","exampleEn":"The landlord raised the rent.","example2":"Ich habe mit meiner Vermieterin telefoniert.","example2En":"I spoke with my landlady on the phone."},{"de":"vermitteln","en":"to arrange/provide; to mediate; to convey","pos":"verb","plural":"","meanings":[{"en":"to arrange, provide (e.g. a job, contact, apartment)","de":"etwas organisieren und weitergeben, z. B. eine Wohnung"},{"en":"to convey, impart (knowledge/information)","de":"Wissen oder Informationen weitergeben"}],"rule":"regelmäßig: vermittelt, vermittelte, hat vermittelt; oft + Dativ (Person) + Akkusativ (Sache), z. B. 'jemandem etwas vermitteln'.","example":"Die Agentur vermittelt Wohnungen.","exampleEn":"The agency arranges apartments.","example2":"Der Lehrer vermittelt den Schülern neues Wissen.","example2En":"The teacher conveys new knowledge to the students."},{"de":"die Verpackung","en":"packaging","pos":"noun","plural":"die Verpackungen","meanings":[{"en":"material used to wrap or contain a product","de":"Material, in das eine Ware eingepackt ist"}],"rule":"von 'verpacken'; regelmäßiger Plural auf -en","example":"Die Verpackung ist aus Plastik.","exampleEn":"The packaging is made of plastic.","example2":"Bitte entsorgen Sie die Verpackung richtig.","example2En":"Please dispose of the packaging properly."},{"de":"verpassen","en":"to miss (a train, chance)","pos":"verb","plural":"","meanings":[{"en":"to miss (a train, bus, opportunity)","de":"etwas nicht mehr erreichen oder nutzen"}],"rule":"regelmäßig: verpasst, verpasste, hat verpasst; + Akkusativ","example":"Ich habe den Bus verpasst.","exampleEn":"I missed the bus.","example2":"Verpass nicht die Chance!","example2En":"Don't miss the chance!"},{"de":"verrückt","en":"crazy; insane","pos":"adjective","plural":"","meanings":[{"en":"crazy, mentally unusual","de":"geistig ungewöhnlich, wahnsinnig"},{"en":"wild, amazing (informal)","de":"sehr aufregend oder ungewöhnlich (umgangssprachlich)"}],"rule":"regelmäßige Steigerung: verrückt, verrückter, am verrücktesten","example":"Er ist total verrückt nach Fußball.","exampleEn":"He is totally crazy about soccer.","example2":"Das war eine verrückte Party.","example2En":"That was a wild party."},{"de":"verschlafen","en":"to oversleep","pos":"verb","plural":"","meanings":[{"en":"to sleep longer than intended","de":"zu lange schlafen"}],"rule":"unregelmäßig: verschläft, verschlief, hat verschlafen","example":"Ich habe heute verschlafen und den Bus verpasst.","exampleEn":"I overslept today and missed the bus.","example2":"Bitte stell einen Wecker, damit du nicht verschläfst.","example2En":"Please set an alarm so you don't oversleep."},{"de":"verschreiben","en":"to prescribe","pos":"verb","plural":"","meanings":[{"en":"to prescribe (medicine)","de":"ein Medikament aufschreiben"}],"rule":"unregelmäßig: verschreibt, verschrieb, hat verschrieben; + Dativ (jemandem etwas verschreiben)","example":"Der Arzt hat mir Tabletten verschrieben.","exampleEn":"The doctor prescribed me tablets.","example2":"Können Sie mir ein stärkeres Medikament verschreiben?","example2En":"Can you prescribe me a stronger medicine?"},{"de":"die Versicherung","en":"insurance","pos":"noun","plural":"die Versicherungen","meanings":[{"en":"insurance (company or policy)","de":"Schutz gegen Schäden gegen Bezahlung"}],"rule":"feminin: die Versicherung","example":"Ich habe eine Versicherung für mein Auto.","exampleEn":"I have insurance for my car.","example2":"Die Versicherung zahlt die Reparatur.","example2En":"The insurance pays for the repair."},{"de":"der Versicherungsnehmer / die Versicherungsnehmerin","en":"policyholder","pos":"noun","plural":"die Versicherungsnehmer / die Versicherungsnehmerinnen","meanings":[{"en":"person who holds an insurance policy","de":"Person, die eine Versicherung abgeschlossen hat"}],"rule":"maskulin/feminin: der Versicherungsnehmer / die Versicherungsnehmerin","example":"Als Versicherungsnehmer müssen Sie den Schaden melden.","exampleEn":"As the policyholder, you must report the damage.","example2":"Die Versicherungsnehmerin hat ihre Adresse geändert.","example2En":"The policyholder changed her address."}]},{"id":"a2-20","title":"A2 · V–W (20)","level":"A2","words":[{"de":"der Versicherungstarif","en":"insurance rate/plan","pos":"noun","plural":"die Versicherungstarife","meanings":[{"en":"pricing plan of an insurance policy","de":"Preisplan einer Versicherung"}],"rule":"maskulin: der Versicherungstarif","example":"Wir vergleichen verschiedene Versicherungstarife.","exampleEn":"We are comparing different insurance rates.","example2":"Dieser Versicherungstarif ist günstiger.","example2En":"This insurance plan is cheaper."},{"de":"die Verspannung","en":"tension (muscle)","pos":"noun","plural":"die Verspannungen","meanings":[{"en":"muscle tension/stiffness","de":"verhärtete Muskeln"}],"rule":"feminin: die Verspannung","example":"Ich habe Verspannungen im Rücken.","exampleEn":"I have tension in my back.","example2":"Die Massage hilft gegen Verspannungen.","example2En":"The massage helps against muscle tension."},{"de":"verspätet","en":"late; delayed","pos":"adjective","plural":"","meanings":[{"en":"delayed, arriving later than planned","de":"später als geplant"}],"rule":"regelmäßig: verspätet, verspäteter, am verspätetsten; oft mit Zügen/Flügen","example":"Der Zug ist verspätet angekommen.","exampleEn":"The train arrived late.","example2":"Wegen des Nebels gab es einen verspäteten Abflug.","example2En":"Due to the fog, there was a delayed departure."},{"de":"die Verspätung","en":"delay","pos":"noun","plural":"die Verspätungen","meanings":[{"en":"delay (of transport)","de":"zu spätes Ankommen"}],"rule":"feminin: die Verspätung","example":"Der Bus hat zehn Minuten Verspätung.","exampleEn":"The bus is ten minutes late.","example2":"Entschuldigung für die Verspätung.","example2En":"Sorry for the delay."},{"de":"der Versuch","en":"attempt; experiment","pos":"noun","plural":"die Versuche","meanings":[{"en":"an attempt or try","de":"das Probieren"},{"en":"a scientific experiment","de":"wissenschaftliches Experiment"}],"rule":"maskulin: der Versuch","example":"Das war mein erster Versuch, Deutsch zu sprechen.","exampleEn":"That was my first attempt to speak German.","example2":"Die Schüler machen einen Versuch im Chemieunterricht.","example2En":"The students do an experiment in chemistry class."},{"de":"verteilen","en":"to distribute","pos":"verb","plural":"","meanings":[{"en":"to hand out/distribute something","de":"etwas an mehrere Personen geben"}],"rule":"regelmäßig: verteilt, verteilte, hat verteilt","example":"Der Lehrer verteilt die Arbeitsblätter.","exampleEn":"The teacher distributes the worksheets.","example2":"Wir haben die Aufgaben im Team verteilt.","example2En":"We distributed the tasks within the team."},{"de":"der Vertrieb","en":"sales; distribution","pos":"noun","plural":"die Vertriebe","meanings":[{"en":"sales department or distribution of goods","de":"Verkauf und Verteilung von Waren"}],"rule":"maskulin: der Vertrieb; oft als Firmenabteilung","example":"Sie arbeitet im Vertrieb einer großen Firma.","exampleEn":"She works in sales at a large company.","example2":"Der Vertrieb der neuen Produkte läuft gut.","example2En":"The distribution of the new products is going well."},{"de":"verwenden","en":"to use","pos":"verb","plural":"","meanings":[{"en":"to use something","de":"etwas benutzen"}],"rule":"regelmäßig/unregelmäßig: verwendet, verwendete (auch verwandte), hat verwendet (auch verwandt)","example":"Ich verwende diese App jeden Tag.","exampleEn":"I use this app every day.","example2":"Welches Material hast du verwendet?","example2En":"Which material did you use?"},{"de":"der Verwendungszweck","en":"purpose of use","pos":"noun","plural":"die Verwendungszwecke","meanings":[{"en":"the purpose for which something is used","de":"Grund, warum man etwas benutzt"}],"rule":"maskulin: der Verwendungszweck; oft bei Überweisungen","example":"Bitte geben Sie den Verwendungszweck bei der Überweisung an.","exampleEn":"Please state the purpose when making the transfer.","example2":"Der Verwendungszweck des Geldes war unklar.","example2En":"The purpose of the money was unclear."},{"de":"der Vokabeltest","en":"vocabulary test","pos":"noun","plural":"die Vokabeltests","meanings":[{"en":"a test of vocabulary words","de":"Test über Wörter"}],"rule":"maskulin: der Vokabeltest","example":"Morgen schreiben wir einen Vokabeltest.","exampleEn":"Tomorrow we're writing a vocabulary test.","example2":"Ich habe den Vokabeltest gut bestanden.","example2En":"I passed the vocabulary test well."},{"de":"der Volleyball","en":"volleyball (sport/ball)","pos":"noun","plural":"die Volleybälle","meanings":[{"en":"the sport of volleyball","de":"Ballsport"},{"en":"the ball used in volleyball","de":"der Ball für dieses Spiel"}],"rule":"maskulin: der Volleyball","example":"Wir spielen jeden Freitag Volleyball.","exampleEn":"We play volleyball every Friday.","example2":"Kannst du mir bitte den Volleyball zuwerfen?","example2En":"Can you please throw me the volleyball?"},{"de":"das Volleyballspiel","en":"volleyball game/match","pos":"noun","plural":"die Volleyballspiele","meanings":[{"en":"a match of volleyball","de":"ein Spiel im Volleyball"}],"rule":"neutral: das Volleyballspiel","example":"Das Volleyballspiel hat zwei Stunden gedauert.","exampleEn":"The volleyball match lasted two hours.","example2":"Wir haben das Volleyballspiel knapp verloren.","example2En":"We narrowly lost the volleyball game."},{"de":"vollständig","en":"complete","pos":"adjective","plural":"","meanings":[{"en":"complete, whole, with nothing missing","de":"ganz, ohne dass etwas fehlt"}],"rule":"regelmäßig: vollständig, vollständiger, am vollständigsten","example":"Bitte füllen Sie das Formular vollständig aus.","exampleEn":"Please fill out the form completely.","example2":"Die Liste ist noch nicht vollständig.","example2En":"The list is not yet complete."},{"de":"die Vollzeit","en":"full-time","pos":"noun","plural":"","meanings":[{"en":"full-time work","de":"volle Arbeitszeit"}],"rule":"feminin: die Vollzeit; oft in Vollzeit arbeiten","example":"Ich arbeite Vollzeit in einem Büro.","exampleEn":"I work full-time in an office.","example2":"Die Stelle wird in Vollzeit angeboten.","example2En":"The position is offered full-time."},{"de":"die Vollzeitstelle","en":"full-time position","pos":"noun","plural":"die Vollzeitstellen","meanings":[{"en":"a job with full working hours (as opposed to part-time)","de":"eine Arbeitsstelle mit voller Arbeitszeit"}],"rule":"Compound noun: voll + Zeit + Stelle; gender from die Stelle. Opposite: die Teilzeitstelle.","example":"Ich suche eine Vollzeitstelle als Verkäuferin.","exampleEn":"I'm looking for a full-time position as a salesperson.","example2":"Nach dem Studium hat er eine Vollzeitstelle gefunden.","example2En":"After his studies he found a full-time job."},{"de":"die Voraussetzung","en":"requirement, precondition","pos":"noun","plural":"die Voraussetzungen","meanings":[{"en":"condition that must be fulfilled","de":"Bedingung, die erfüllt sein muss"}],"rule":"Often used with 'für' + Akkusativ: die Voraussetzung für einen Job.","example":"Gute Deutschkenntnisse sind eine Voraussetzung für die Stelle.","exampleEn":"Good German skills are a requirement for the job.","example2":"Welche Voraussetzungen muss ich für den Kurs erfüllen?","example2En":"What requirements do I have to meet for the course?"},{"de":"vorbeikommen","en":"to come by, to drop in","pos":"verb","plural":"","meanings":[{"en":"to visit someone briefly / pass by","de":"jemanden kurz besuchen, an etwas vorbeigehen"}],"rule":"Trennbar: kommt vorbei, kam vorbei, ist vorbeigekommen. Often with 'bei' + Dativ.","example":"Kannst du heute Abend bei mir vorbeikommen?","exampleEn":"Can you come by my place tonight?","example2":"Wir sind am Rathaus vorbeigekommen.","example2En":"We passed by the town hall."},{"de":"vorbereiten","en":"to prepare","pos":"verb","plural":"","meanings":[{"en":"to get something/someone ready","de":"etwas für später fertig machen"},{"en":"to prepare oneself (reflexive)","de":"sich auf etwas vorbereiten"}],"rule":"Trennbar: bereitet vor, bereitete vor, hat vorbereitet. Reflexiv mit 'sich' + auf + Akkusativ möglich.","example":"Ich bereite das Abendessen vor.","exampleEn":"I'm preparing dinner.","example2":"Sie bereitet sich auf die Prüfung vor.","example2En":"She is preparing for the exam."},{"de":"die Vorbereitung","en":"preparation","pos":"noun","plural":"die Vorbereitungen","meanings":[{"en":"the act of preparing","de":"das Vorbereiten"}],"rule":"Oft mit 'für' oder 'auf' + Akkusativ: die Vorbereitung auf die Prüfung.","example":"Die Vorbereitung auf das Gespräch war schwierig.","exampleEn":"The preparation for the interview was difficult.","example2":"Wir treffen letzte Vorbereitungen für die Party.","example2En":"We're making last preparations for the party."},{"de":"vorhanden","en":"available, existing","pos":"adjective","plural":"","meanings":[{"en":"present, in existence at a place","de":"da, verfügbar"}],"rule":"No comparison typically used in this meaning; often with sein: vorhanden sein.","example":"Parkplätze sind leider nicht vorhanden.","exampleEn":"Unfortunately there are no parking spaces available.","example2":"Im Büro ist ein Drucker vorhanden.","example2En":"There is a printer available in the office."},{"de":"die Vorkenntnisse","en":"prior knowledge, prerequisite knowledge","pos":"noun","plural":"die Vorkenntnisse","meanings":[{"en":"knowledge or skills one already has before starting something","de":"Kenntnisse, die man schon vorher hat"}],"rule":"Meist nur im Plural verwendet: Vorkenntnisse haben/besitzen. (Singular 'die Vorkenntnis' ist selten.)","example":"Für den Kurs sind keine Vorkenntnisse nötig.","exampleEn":"No prior knowledge is needed for the course.","example2":"Er hat gute Vorkenntnisse in Englisch.","example2En":"He has good prior knowledge of English."},{"de":"die Vorlage","en":"template, form; presentation (document)","pos":"noun","plural":"die Vorlagen","meanings":[{"en":"a template or model to copy from","de":"ein Muster zum Nachmachen"},{"en":"the act of presenting a document","de":"das Zeigen/Vorlegen eines Dokuments"}],"rule":"Von 'vorlegen' abgeleitet. Oft: gegen Vorlage des Ausweises.","example":"Ich nutze eine Vorlage für den Lebenslauf.","exampleEn":"I'm using a template for the résumé.","example2":"Der Eintritt ist nur gegen Vorlage der Karte möglich.","example2En":"Entry is only possible upon presentation of the ticket."},{"de":"die Vorlesung","en":"lecture (university)","pos":"noun","plural":"die Vorlesungen","meanings":[{"en":"a university lecture","de":"ein Unterricht an der Universität"}],"rule":"Typisch mit 'besuchen' oder 'halten': eine Vorlesung besuchen.","example":"Die Vorlesung beginnt um neun Uhr.","exampleEn":"The lecture starts at nine o'clock.","example2":"Ich besuche heute zwei Vorlesungen.","example2En":"I'm attending two lectures today."},{"de":"der Vorschlag","en":"suggestion, proposal","pos":"noun","plural":"die Vorschläge","meanings":[{"en":"an idea proposed to others","de":"eine Idee, die man anbietet"}],"rule":"Von 'vorschlagen' abgeleitet. Kollokation: einen Vorschlag machen.","example":"Das ist ein guter Vorschlag.","exampleEn":"That's a good suggestion.","example2":"Ich mache dir einen Vorschlag für den Urlaub.","example2En":"I'll make you a suggestion for the vacation."},{"de":"die Vorschrift","en":"regulation, rule","pos":"noun","plural":"die Vorschriften","meanings":[{"en":"an official rule that must be followed","de":"eine offizielle Regel"}],"rule":"Oft im Plural: Vorschriften einhalten/befolgen.","example":"Hier gelten strenge Vorschriften.","exampleEn":"Strict regulations apply here.","example2":"Man muss die Vorschriften der Firma beachten.","example2En":"You have to follow the company's rules."},{"de":"die Vorsicht","en":"caution, care","pos":"noun","plural":"","meanings":[{"en":"careful behavior to avoid danger","de":"vorsichtiges Verhalten"}],"rule":"Uncountable; often as interjection: Vorsicht! Also: mit Vorsicht.","example":"Vorsicht, die Straße ist glatt!","exampleEn":"Careful, the road is slippery!","example2":"Bitte mit Vorsicht behandeln.","example2En":"Please handle with care."},{"de":"das Vorstellungsgespräch","en":"job interview","pos":"noun","plural":"die Vorstellungsgespräche","meanings":[{"en":"an interview for a job application","de":"ein Gespräch mit dem Arbeitgeber vor der Einstellung"}],"rule":"Kollokation: ein Vorstellungsgespräch haben/führen.","example":"Morgen habe ich ein Vorstellungsgespräch.","exampleEn":"Tomorrow I have a job interview.","example2":"Sie hat sich gut auf das Vorstellungsgespräch vorbereitet.","example2En":"She prepared well for the job interview."},{"de":"der Vorteil","en":"advantage","pos":"noun","plural":"die Vorteile","meanings":[{"en":"a benefit or positive aspect","de":"ein positiver Aspekt"}],"rule":"Gegenteil: der Nachteil. Kollokation: Vorteile und Nachteile.","example":"Ein Vorteil der Stelle ist das gute Gehalt.","exampleEn":"An advantage of the job is the good salary.","example2":"Welche Vorteile hat das Fahrrad gegenüber dem Auto?","example2En":"What advantages does the bike have over the car?"},{"de":"der Vortrag","en":"talk, lecture, presentation","pos":"noun","plural":"die Vorträge","meanings":[{"en":"a spoken presentation on a topic","de":"eine Rede über ein Thema"}],"rule":"Kollokation: einen Vortrag halten.","example":"Der Professor hält einen Vortrag über Klimawandel.","exampleEn":"The professor is giving a talk on climate change.","example2":"Ich habe den Vortrag sehr interessant gefunden.","example2En":"I found the presentation very interesting."},{"de":"während","en":"during; while","pos":"preposition","plural":"","meanings":[{"en":"during (preposition + Genitiv)","de":"innerhalb eines Zeitraums"},{"en":"while (conjunction, contrast)","de":"in der Zeit, in der; im Gegensatz dazu"}],"rule":"Als Präposition + Genitiv: während des Tages. Als Konjunktion leitet Nebensatz ein: Während ich arbeite, schläft er.","example":"Während der Pause trinke ich einen Kaffee.","exampleEn":"During the break I drink a coffee.","example2":"Während sie liest, hört er Musik.","example2En":"While she reads, he listens to music."},{"de":"wandern","en":"to hike","pos":"verb","plural":"","meanings":[{"en":"to walk long distances in nature for leisure","de":"längere Strecken in der Natur zu Fuß gehen"}],"rule":"Regelmäßig; Perfekt mit 'sein': ist gewandert (Bewegung/Ortswechsel).","example":"Am Wochenende wandern wir in den Bergen.","exampleEn":"On the weekend we're hiking in the mountains.","example2":"Wir sind sechs Stunden gewandert.","example2En":"We hiked for six hours."},{"de":"der Wanderschuh","en":"hiking boot","pos":"noun","plural":"die Wanderschuhe","meanings":[{"en":"a sturdy boot for hiking","de":"ein fester Schuh zum Wandern"}],"rule":"Kompositum: wandern + Schuh; meist im Plural verwendet.","example":"Ich brauche neue Wanderschuhe für die Tour.","exampleEn":"I need new hiking boots for the tour.","example2":"Meine Wanderschuhe sind sehr bequem.","example2En":"My hiking boots are very comfortable."},{"de":"die Wärmflasche","en":"hot water bottle","pos":"noun","plural":"die Wärmflaschen","meanings":[{"en":"hot water bottle","de":"Gummiflasche mit warmem Wasser gegen Kälte/Schmerzen"}],"rule":"Feminine noun (die), compound of Wärme + Flasche.","example":"Bei Bauchschmerzen legt sie eine Wärmflasche auf den Bauch.","exampleEn":"When she has a stomach ache, she puts a hot water bottle on her belly.","example2":"Im Winter nehme ich eine Wärmflasche mit ins Bett.","example2En":"In winter I take a hot water bottle to bed."},{"de":"die Webseite","en":"website","pos":"noun","plural":"die Webseiten","meanings":[{"en":"website / web page","de":"Seite im Internet"}],"rule":"Feminine noun (die); also written \"Website\".","example":"Die Webseite der Firma ist sehr informativ.","exampleEn":"The company's website is very informative.","example2":"Ich habe die Öffnungszeiten auf der Webseite gefunden.","example2En":"I found the opening hours on the website."},{"de":"der Wecker","en":"alarm clock","pos":"noun","plural":"die Wecker","meanings":[{"en":"alarm clock","de":"Uhr, die klingelt, um jemanden zu wecken"}],"rule":"Masculine noun (der); from wecken (to wake).","example":"Mein Wecker klingelt jeden Morgen um sechs Uhr.","exampleEn":"My alarm clock rings every morning at six.","example2":"Ich habe den Wecker auf halb sieben gestellt.","example2En":"I set the alarm clock for half past six."},{"de":"wegen","en":"because of","pos":"preposition","plural":"","meanings":[{"en":"because of, due to","de":"aus einem bestimmten Grund"}],"rule":"Governs Genitiv (formal) or Dativ (colloquial): \"wegen des Regens\" / \"wegen dem Regen\".","example":"Wegen des schlechten Wetters bleiben wir zu Hause.","exampleEn":"Because of the bad weather, we're staying home.","example2":"Er kam wegen der Prüfung zu spät.","example2En":"He came late because of the exam."},{"de":"weggehen","en":"to leave, to go out","pos":"verb","plural":"","meanings":[{"en":"to leave / go away","de":"einen Ort verlassen"},{"en":"to go out (socially)","de":"ausgehen, z. B. abends"}],"rule":"Trennbar: geht weg, ging weg, ist weggegangen. Perfekt mit \"sein\".","example":"Er ist schon vor einer Stunde weggegangen.","exampleEn":"He already left an hour ago.","example2":"Am Samstag gehen wir mit Freunden weg.","example2En":"On Saturday we're going out with friends."},{"de":"weglaufen","en":"to run away","pos":"verb","plural":"","meanings":[{"en":"to run away","de":"schnell weggehen, fliehen"}],"rule":"Trennbar und unregelmäßig: läuft weg, lief weg, ist weggelaufen. Perfekt mit \"sein\".","example":"Der Hund ist vor dem lauten Feuerwerk weggelaufen.","exampleEn":"The dog ran away from the loud fireworks.","example2":"Das Kind lief einfach weg, als es die Spritze sah.","example2En":"The child simply ran away when it saw the injection."},{"de":"weiblich","en":"female","pos":"adjective","plural":"","meanings":[{"en":"female, feminine","de":"das Geschlecht betreffend, nicht männlich"}],"rule":"No irregular comparison; regular: weiblich, weiblicher, am weiblichsten.","example":"Auf dem Formular muss man \"männlich\" oder \"weiblich\" ankreuzen.","exampleEn":"On the form you have to tick \"male\" or \"female\".","example2":"Die weiblichen Angestellten arbeiten meist im Büro.","example2En":"The female employees mostly work in the office."},{"de":"weil","en":"because","pos":"conjunction","plural":"","meanings":[{"en":"because","de":"gibt einen Grund an"}],"rule":"Subordinating conjunction: verb moves to the end of the clause.","example":"Ich bleibe zu Hause, weil ich krank bin.","exampleEn":"I'm staying home because I'm sick.","example2":"Sie lernt Deutsch, weil sie in Deutschland arbeiten möchte.","example2En":"She is learning German because she wants to work in Germany."},{"de":"die Weiterbildung","en":"further training, continuing education","pos":"noun","plural":"die Weiterbildungen","meanings":[{"en":"further/continuing education, professional training","de":"Kurs oder Training, um neue Kenntnisse zu erwerben"}],"rule":"Feminine noun (die); from weiterbilden (sich).","example":"Meine Firma bezahlt eine Weiterbildung im Bereich Computer.","exampleEn":"My company pays for further training in computing.","example2":"Er macht eine Weiterbildung, um Chef zu werden.","example2En":"He's doing further training to become a manager."},{"de":"weiterhin","en":"still, continuing","pos":"adverb","plural":"","meanings":[{"en":"still, continuing to (do sth)","de":"auch in Zukunft, wie bisher"}],"rule":"No inflection; often with a verb to express continuation, e.g. \"weiterhin arbeiten\".","example":"Ich wünsche dir weiterhin viel Erfolg.","exampleEn":"I wish you continued success.","example2":"Sie wohnt weiterhin in derselben Stadt.","example2En":"She still lives in the same city."},{"de":"die Welt","en":"world","pos":"noun","plural":"die Welten","meanings":[{"en":"the world, earth","de":"die ganze Erde; alle Länder und Menschen"}],"rule":"Feminine noun (die); often used in the singular without plural in everyday speech.","example":"Er möchte die ganze Welt bereisen.","exampleEn":"He wants to travel the whole world.","example2":"Diese Nachricht kam aus aller Welt.","example2En":"This news came from all over the world."},{"de":"wenig","en":"little, few","pos":"adjective","plural":"","meanings":[{"en":"little (amount)","de":"eine kleine Menge"},{"en":"few (number)","de":"eine kleine Anzahl"}],"rule":"Regular comparison: wenig, weniger, am wenigsten. Uninflected before uncountable nouns (\"wenig Zeit\"), but inflects before plural countable nouns (\"wenige Leute\").","example":"Ich habe heute wenig Zeit.","exampleEn":"I have little time today.","example2":"Es waren nur wenige Leute im Raum.","example2En":"There were only few people in the room."},{"de":"die Werbeagentur","en":"advertising agency","pos":"noun","plural":"die Werbeagenturen","meanings":[{"en":"advertising agency","de":"Firma, die Werbung für andere Firmen macht"}],"rule":"Feminine noun (die); compound of Werbung + Agentur.","example":"Sie arbeitet seit zwei Jahren bei einer Werbeagentur.","exampleEn":"She has worked at an advertising agency for two years.","example2":"Die Werbeagentur hat eine neue Kampagne entwickelt.","example2En":"The advertising agency developed a new campaign."},{"de":"der Werbeflyer","en":"advertising flyer","pos":"noun","plural":"die Werbeflyer","meanings":[{"en":"promotional flyer/leaflet","de":"kleines Werbeblatt mit Informationen"}],"rule":"Masculine noun (der); plural unchanged (like Flyer).","example":"Vor dem Geschäft verteilte jemand Werbeflyer.","exampleEn":"Someone was handing out advertising flyers in front of the shop.","example2":"Ich habe den Werbeflyer gleich weggeworfen.","example2En":"I threw the advertising flyer away right away."},{"de":"der Werbetexter / die Werbetexterin","en":"copywriter","pos":"noun","plural":"die Werbetexter / die Werbetexterinnen","meanings":[{"en":"copywriter (person who writes advertising texts)","de":"Person, die Texte für Werbung schreibt"}],"rule":"Masculine der Werbetexter, feminine die Werbetexterin (+in).","example":"Als Werbetexter schreibt er kurze, originelle Slogans.","exampleEn":"As a copywriter, he writes short, original slogans.","example2":"Die Werbetexterin hat den Text für die neue Anzeige geschrieben.","example2En":"The copywriter wrote the text for the new ad."},{"de":"werfen","en":"to throw","pos":"verb","plural":"","meanings":[{"en":"to throw","de":"etwas mit der Hand durch die Luft schleudern"}],"rule":"Unregelmäßig: wirft, warf, hat geworfen.","example":"Der Junge wirft den Ball ins Tor.","exampleEn":"The boy throws the ball into the goal.","example2":"Sie warf die alte Zeitung in den Müll.","example2En":"She threw the old newspaper in the trash."},{"de":"die Wettervorhersage","en":"weather forecast","pos":"noun","plural":"die Wettervorhersagen","meanings":[{"en":"weather forecast","de":"Voraussage, wie das Wetter wird"}],"rule":"Feminine noun (die); compound of Wetter + Vorhersage.","example":"Laut Wettervorhersage regnet es morgen.","exampleEn":"According to the weather forecast, it will rain tomorrow.","example2":"Ich schaue jeden Abend die Wettervorhersage im Fernsehen.","example2En":"I watch the weather forecast on TV every evening."},{"de":"wiederholen","en":"to repeat","pos":"verb","plural":"","meanings":[{"en":"to repeat (say/do again)","de":"noch einmal sagen oder tun"},{"en":"to review/revise (e.g. for a test)","de":"Lernstoff noch einmal durchgehen"}],"rule":"Untrennbar (Betonung auf -hol-): wiederholt, wiederholte, hat wiederholt. Kein \"ge-\" im Partizip.","example":"Können Sie bitte den Satz wiederholen?","exampleEn":"Could you please repeat the sentence?","example2":"Vor der Prüfung wiederholt sie den ganzen Wortschatz.","example2En":"Before the exam she reviews all the vocabulary."}]},{"id":"a2-21","title":"A2 · W–Z (21)","level":"A2","words":[{"de":"wirklich","en":"really; truly","pos":"adverb","plural":"","meanings":[{"en":"really, in fact","de":"tatsächlich"},{"en":"truly, genuinely","de":"echt"}],"rule":"Adverb, no comparison forms; often used to emphasize a statement.","example":"Bist du wirklich krank?","exampleEn":"Are you really sick?","example2":"Das Essen war wirklich lecker.","example2En":"The food was really delicious."},{"de":"die Wirtschaft","en":"economy; pub","pos":"noun","plural":"die Wirtschaften","meanings":[{"en":"economy","de":"Ökonomie eines Landes"},{"en":"pub, tavern (regional)","de":"Gaststätte"}],"rule":"Feminine noun; two very different meanings depending on context.","example":"Die Wirtschaft in Deutschland wächst langsam.","exampleEn":"The economy in Germany is growing slowly.","example2":"Wir treffen uns in der Wirtschaft um die Ecke.","example2En":"We're meeting at the pub around the corner."},{"de":"wohl","en":"probably; well","pos":"adverb","plural":"","meanings":[{"en":"probably","de":"wahrscheinlich"},{"en":"well (fixed phrases)","de":"gut, z. B. sich wohlfühlen"}],"rule":"Modal particle/adverb; common in 'sich wohl fühlen' (to feel well).","example":"Er ist wohl noch im Büro.","exampleEn":"He's probably still at the office.","example2":"Ich fühle mich hier sehr wohl.","example2En":"I feel very comfortable here."},{"de":"die Wohngemeinschaft","en":"shared flat, flatshare","pos":"noun","plural":"die Wohngemeinschaften","meanings":[{"en":"shared flat (people living together)","de":"mehrere Personen wohnen zusammen in einer Wohnung"}],"rule":"Feminine noun, often abbreviated 'WG'.","example":"Ich wohne in einer Wohngemeinschaft mit drei Studenten.","exampleEn":"I live in a shared flat with three students.","example2":"Die Wohngemeinschaft sucht einen neuen Mitbewohner.","example2En":"The flatshare is looking for a new flatmate."},{"de":"die Wohnungsbesichtigung","en":"flat viewing","pos":"noun","plural":"die Wohnungsbesichtigungen","meanings":[{"en":"viewing/inspection of an apartment before renting","de":"Besichtigung einer Wohnung vor der Miete"}],"rule":"Feminine compound noun: Wohnung + Besichtigung.","example":"Morgen habe ich eine Wohnungsbesichtigung.","exampleEn":"Tomorrow I have a flat viewing.","example2":"Bei der Wohnungsbesichtigung waren viele Interessenten.","example2En":"There were many interested people at the flat viewing."},{"de":"wunderbar","en":"wonderful","pos":"adjective","plural":"","meanings":[{"en":"wonderful, marvelous","de":"sehr schön, herrlich"}],"rule":"Regular comparison: wunderbar, wunderbarer, am wunderbarsten.","example":"Das Wetter heute ist wunderbar.","exampleEn":"The weather today is wonderful.","example2":"Wir hatten einen wunderbaren Urlaub.","example2En":"We had a wonderful vacation."},{"de":"wundervoll","en":"wonderful, marvelous","pos":"adjective","plural":"","meanings":[{"en":"wonderful, marvelous","de":"sehr schön, wunderbar"}],"rule":"Regular comparison: wundervoll, wundervoller, am wundervollsten; near synonym of 'wunderbar'.","example":"Das war ein wundervoller Abend.","exampleEn":"That was a wonderful evening.","example2":"Sie hat eine wundervolle Stimme.","example2En":"She has a wonderful voice."},{"de":"der Wunsch","en":"wish","pos":"noun","plural":"die Wünsche","meanings":[{"en":"wish, desire","de":"etwas, das man gern möchte"}],"rule":"Masculine noun; verb form 'wünschen' (to wish); plural umlauts to Wünsche.","example":"Hast du noch einen Wunsch für deinen Geburtstag?","exampleEn":"Do you have another wish for your birthday?","example2":"Mein größter Wunsch ist ein eigenes Haus.","example2En":"My biggest wish is my own house."},{"de":"das Würstchen","en":"little sausage, hot dog sausage","pos":"noun","plural":"die Würstchen","meanings":[{"en":"small sausage","de":"kleine Wurst"}],"rule":"Neuter noun (diminutive of 'die Wurst', -chen nouns are always neuter); plural is unchanged.","example":"Zum Grillen kaufen wir Würstchen.","exampleEn":"We're buying sausages for the barbecue.","example2":"Das Kind isst ein Würstchen mit Brot.","example2En":"The child is eating a sausage with bread."},{"de":"das Yoga","en":"yoga","pos":"noun","plural":"","meanings":[{"en":"yoga (exercise/practice)","de":"Entspannungs- und Bewegungsübungen"}],"rule":"Neuter noun (also used as 'der Yoga' in some dialects, but 'das Yoga' is standard); uncountable, no plural.","example":"Sie macht jeden Morgen Yoga.","exampleEn":"She does yoga every morning.","example2":"Yoga hilft mir, mich zu entspannen.","example2En":"Yoga helps me relax."},{"de":"der Zähler","en":"meter; counter","pos":"noun","plural":"die Zähler","meanings":[{"en":"meter (e.g. electricity, water)","de":"Gerät, das etwas misst und zählt"},{"en":"numerator (in a fraction)","de":"obere Zahl in einem Bruch, z. B. die 3 in 3/4"}],"rule":"Masculine noun; from verb 'zählen' (to count); plural unchanged.","example":"Der Techniker liest den Zähler ab.","exampleEn":"The technician reads the meter.","example2":"Bitte notieren Sie den Stand des Zählers.","example2En":"Please note the meter reading."},{"de":"der Zahlungsempfänger / die Zahlungsempfängerin","en":"payee","pos":"noun","plural":"die Zahlungsempfänger / die Zahlungsempfängerinnen","meanings":[{"en":"person or entity receiving a payment","de":"Person, die Geld bekommt"}],"rule":"Compound noun: Zahlung + Empfänger; masculine/feminine pair; often appears on bank forms.","example":"Bitte geben Sie den Namen des Zahlungsempfängers an.","exampleEn":"Please provide the name of the payee.","example2":"Der Zahlungsempfänger hat das Geld noch nicht erhalten.","example2En":"The payee has not yet received the money."},{"de":"das Zeitmanagement","en":"time management","pos":"noun","plural":"","meanings":[{"en":"organizing and planning how to divide time between tasks","de":"planvoller Umgang mit der eigenen Zeit"}],"rule":"Neuter noun, loanword from English; uncountable, no plural.","example":"Gutes Zeitmanagement ist im Beruf wichtig.","exampleEn":"Good time management is important at work.","example2":"Sie hat einen Kurs für Zeitmanagement besucht.","example2En":"She attended a course on time management."},{"de":"die Zeitschrift","en":"magazine","pos":"noun","plural":"die Zeitschriften","meanings":[{"en":"magazine, periodical","de":"regelmäßig erscheinendes Heft mit Artikeln"}],"rule":"Feminine noun; different from 'die Zeitung' (newspaper).","example":"Ich lese gern Zeitschriften über Reisen.","exampleEn":"I like reading travel magazines.","example2":"Die Zeitschrift erscheint einmal im Monat.","example2En":"The magazine is published once a month."},{"de":"der Zeitungsartikel","en":"newspaper article","pos":"noun","plural":"die Zeitungsartikel","meanings":[{"en":"article published in a newspaper","de":"Text in einer Zeitung"}],"rule":"Masculine compound noun: Zeitung + Artikel; plural unchanged.","example":"Er hat einen interessanten Zeitungsartikel gelesen.","exampleEn":"He read an interesting newspaper article.","example2":"Der Zeitungsartikel handelt von Klimaschutz.","example2En":"The newspaper article is about climate protection."},{"de":"zeitweise","en":"temporarily, at times","pos":"adverb","plural":"","meanings":[{"en":"temporarily, occasionally, at times","de":"manchmal, nicht dauernd"}],"rule":"Adverb, no comparison; synonym: manchmal, vorübergehend.","example":"Es regnet heute zeitweise.","exampleEn":"It's raining on and off today.","example2":"Zeitweise war die Straße gesperrt.","example2En":"The road was temporarily closed."},{"de":"das Zertifikat","en":"certificate","pos":"noun","plural":"die Zertifikate","meanings":[{"en":"official document certifying a qualification","de":"offizielles Dokument, das eine Qualifikation bestätigt"}],"rule":"Neuter noun, loanword from Latin/English.","example":"Sie hat ein Zertifikat für Deutschkenntnisse.","exampleEn":"She has a certificate for German language skills.","example2":"Nach dem Kurs bekommen Sie ein Zertifikat.","example2En":"After the course you get a certificate."},{"de":"der Zeuge / die Zeugin","en":"witness","pos":"noun","plural":"die Zeugen / die Zeuginnen","meanings":[{"en":"person who witnesses an event, e.g. an accident or crime","de":"Person, die etwas gesehen hat"}],"rule":"Masculine weak noun (der Zeuge, den/dem/des Zeugen); feminine form Zeugin.","example":"Der Zeuge hat den Unfall genau gesehen.","exampleEn":"The witness saw the accident clearly.","example2":"Die Polizei sucht Zeugen für den Diebstahl.","example2En":"The police are looking for witnesses to the theft."},{"de":"das Zeugnis","en":"report card; certificate","pos":"noun","plural":"die Zeugnisse","meanings":[{"en":"school report card","de":"schulische Beurteilung mit Noten"},{"en":"certificate (e.g. work reference)","de":"Bescheinigung, z. B. Arbeitszeugnis"}],"rule":"Neuter noun; plural die Zeugnisse. Common in 'Schulzeugnis' (report card) and 'Arbeitszeugnis' (work reference).","example":"Am Ende des Schuljahres bekommen die Kinder ihr Zeugnis.","exampleEn":"At the end of the school year the children get their report card.","example2":"Er braucht ein Zeugnis von seinem alten Arbeitgeber.","example2En":"He needs a reference from his old employer."},{"de":"der Zoo","en":"zoo","pos":"noun","plural":"die Zoos","meanings":[{"en":"zoo","de":"Tierpark"}],"rule":"Masculine noun; plural die Zoos. Often used with 'in den Zoo gehen'.","example":"Am Sonntag gehen wir mit den Kindern in den Zoo.","exampleEn":"On Sunday we're going to the zoo with the kids.","example2":"Im Zoo kann man viele Tiere sehen.","example2En":"At the zoo you can see many animals."},{"de":"zubereiten","en":"to prepare (food)","pos":"verb","plural":"","meanings":[{"en":"to prepare food/a meal","de":"kochen, fertig machen"}],"rule":"Trennbar: bereitet ... zu, bereitete ... zu, hat zubereitet. Usually + Akkusativ (ein Gericht zubereiten).","example":"Sie bereitet das Abendessen zu.","exampleEn":"She is preparing dinner.","example2":"Kannst du den Salat zubereiten?","example2En":"Can you prepare the salad?"},{"de":"die Zucchini","en":"zucchini; courgette","pos":"noun","plural":"die Zucchini","meanings":[{"en":"zucchini/courgette (vegetable)","de":"Gemüse, ähnlich wie Gurke"}],"rule":"Feminine noun; singular and plural are the same: die Zucchini.","example":"Ich kaufe zwei Zucchini für die Suppe.","exampleEn":"I'm buying two zucchini for the soup.","example2":"Die Zucchini schmeckt gut gebraten.","example2En":"Zucchini tastes good fried."},{"de":"zufrieden","en":"satisfied; content","pos":"adjective","plural":"","meanings":[{"en":"satisfied, content","de":"nicht unzufrieden, glücklich mit etwas"}],"rule":"Often used with 'mit + Dativ': zufrieden mit etwas/jemandem. Regular comparison: zufrieden, zufriedener, am zufriedensten.","example":"Ich bin mit meiner neuen Arbeit zufrieden.","exampleEn":"I am satisfied with my new job.","example2":"Der Chef war mit unserer Arbeit sehr zufrieden.","example2En":"The boss was very satisfied with our work."},{"de":"der Zugang","en":"access; entrance","pos":"noun","plural":"die Zugänge","meanings":[{"en":"access, way in","de":"Möglichkeit, an einen Ort zu kommen"},{"en":"access to a system/resource","de":"Zugriff, z. B. zum Internet"}],"rule":"Masculine noun; plural die Zugänge. Often with 'Zugang zu + Dativ'.","example":"Der Zugang zum Gebäude ist nur mit Karte möglich.","exampleEn":"Access to the building is only possible with a card.","example2":"Wir haben keinen Zugang zum Internet.","example2En":"We have no access to the internet."},{"de":"zuhören","en":"to listen (to)","pos":"verb","plural":"","meanings":[{"en":"to listen attentively","de":"aufmerksam hören"}],"rule":"Trennbar: hört ... zu, hörte ... zu, hat zugehört. Governs Dativ: jemandem zuhören.","example":"Bitte hör mir zu!","exampleEn":"Please listen to me!","example2":"Die Schüler hören dem Lehrer aufmerksam zu.","example2En":"The students listen attentively to the teacher."},{"de":"die Zulassungsstelle","en":"vehicle registration office","pos":"noun","plural":"die Zulassungsstellen","meanings":[{"en":"office where vehicles are registered","de":"Amt, bei dem man ein Auto anmeldet"}],"rule":"Feminine noun; plural die Zulassungsstellen. Compound of 'Zulassung' (registration) + 'Stelle' (office).","example":"Ich muss mein neues Auto bei der Zulassungsstelle anmelden.","exampleEn":"I have to register my new car at the vehicle registration office.","example2":"Die Zulassungsstelle hat vormittags geöffnet.","example2En":"The registration office is open in the mornings."},{"de":"zuletzt","en":"last; finally","pos":"adverb","plural":"","meanings":[{"en":"last (in a sequence), finally","de":"als Letztes, am Ende"}],"rule":"Undeclined adverb. Used for sequence ('zuerst ... zuletzt' = first ... finally) and for time ('zuletzt' = the last time, like 'zum letzten Mal'): 'Wann hast du sie zuletzt gesehen?' = 'When did you last see her?'","example":"Zuerst kochen wir, zuletzt räumen wir die Küche auf.","exampleEn":"First we cook, finally we clean up the kitchen.","example2":"Wann hast du sie zuletzt gesehen?","example2En":"When did you see her last?"},{"de":"zurückgeben","en":"to give back; to return","pos":"verb","plural":"","meanings":[{"en":"to return an item","de":"etwas zurückbringen"}],"rule":"Trennbar und unregelmäßig: gibt ... zurück, gab ... zurück, hat zurückgegeben. + Akkusativ (+ Dativ der Person).","example":"Ich muss der Bibliothek das Buch zurückgeben.","exampleEn":"I have to return the book to the library.","example2":"Er gibt mir mein Geld zurück.","example2En":"He gives me back my money."},{"de":"zuschauen","en":"to watch; to look on","pos":"verb","plural":"","meanings":[{"en":"to watch, observe","de":"beobachten, zusehen"}],"rule":"Trennbar: schaut ... zu, schaute ... zu, hat zugeschaut. Governs Dativ: jemandem/etwas zuschauen.","example":"Die Kinder schauen den Vögeln zu.","exampleEn":"The children are watching the birds.","example2":"Darf ich dir beim Kochen zuschauen?","example2En":"May I watch you cook?"},{"de":"zuständig","en":"responsible; in charge","pos":"adjective","plural":"","meanings":[{"en":"responsible, in charge of something official","de":"verantwortlich für etwas (offiziell)"}],"rule":"Often with 'für + Akkusativ': zuständig für etwas. Regular comparison.","example":"Wer ist hier für die Anmeldung zuständig?","exampleEn":"Who is responsible for registration here?","example2":"Frau Meier ist für diese Abteilung zuständig.","example2En":"Ms. Meier is in charge of this department."},{"de":"zuverlässig","en":"reliable; dependable","pos":"adjective","plural":"","meanings":[{"en":"reliable, dependable","de":"verlässlich, auf den man sich verlassen kann"}],"rule":"Regular comparison: zuverlässig, zuverlässiger, am zuverlässigsten.","example":"Mein Kollege ist sehr zuverlässig.","exampleEn":"My colleague is very reliable.","example2":"Der Bus kommt zuverlässig jeden Morgen um acht.","example2En":"The bus reliably comes every morning at eight."},{"de":"zuzüglich","en":"plus; in addition to","pos":"preposition","plural":"","meanings":[{"en":"plus, additional to (costs)","de":"zusätzlich zu, plus (bei Kosten)"}],"rule":"Formal preposition + Genitiv (often used with prices): Preis zuzüglich Versandkosten.","example":"Der Preis beträgt 50 Euro zuzüglich Versandkosten.","exampleEn":"The price is 50 euros plus shipping costs.","example2":"Die Miete ist 600 Euro zuzüglich Nebenkosten.","example2En":"The rent is 600 euros plus utilities."},{"de":"zwischendurch","en":"in between; occasionally","pos":"adverb","plural":"","meanings":[{"en":"in between, at intervals","de":"ab und zu, zwischen zwei Handlungen"}],"rule":"No case or article needed; used for short breaks or occasional actions.","example":"Ich esse zwischendurch gern einen Apfel.","exampleEn":"I like to eat an apple in between meals.","example2":"Wir machen zwischendurch eine kurze Pause.","example2En":"We take a short break every now and then."}]},{"id":"b1-01","title":"B1 · A (1)","level":"B1","words":[{"de":"abdecken","en":"to cover; to cover (costs/needs)","pos":"verb","plural":"","meanings":[{"en":"to cover something (physically)","de":"etwas zudecken/bedecken"},{"en":"to cover (costs, needs, a topic)","de":"Kosten oder Bedarf decken"}],"rule":"trennbar: deckt ... ab, deckte ab, hat abgedeckt","example":"Die Versicherung deckt den Schaden ab.","exampleEn":"The insurance covers the damage.","example2":"Er deckt das Dach mit einer Plane ab.","example2En":"He covers the roof with a tarp."},{"de":"abdrehen","en":"to turn off; to turn away","pos":"verb","plural":"","meanings":[{"en":"to turn off (gas, water, a device)","de":"etwas ausschalten/abstellen"},{"en":"to turn/veer away (direction)","de":"die Richtung ändern"}],"rule":"trennbar: dreht ... ab, drehte ab, hat abgedreht","example":"Bitte dreh das Gas ab!","exampleEn":"Please turn off the gas!","example2":"Das Flugzeug dreht nach Norden ab.","example2En":"The plane veers off to the north."},{"de":"der Abfall","en":"waste, rubbish","pos":"noun","plural":"die Abfälle","meanings":[{"en":"waste/rubbish/trash","de":"Müll"},{"en":"decline, decrease","de":"Rückgang, Verringerung"}],"rule":"maskulin; meist Singular für 'Müll', Plural 'Abfälle' bei mehreren Arten/Mengen","example":"Wirf den Abfall in die Tonne.","exampleEn":"Throw the rubbish in the bin.","example2":"Es gab einen Abfall der Temperatur.","example2En":"There was a drop in temperature."},{"de":"der Abflug","en":"departure (of a flight)","pos":"noun","plural":"die Abflüge","meanings":[{"en":"flight departure","de":"Start eines Flugzeugs"}],"rule":"maskulin; Gegenteil von 'Ankunft'","example":"Der Abflug ist um 9 Uhr.","exampleEn":"The departure is at 9 o'clock.","example2":"Wir müssen zwei Stunden vor Abflug am Flughafen sein.","example2En":"We must be at the airport two hours before departure."},{"de":"das Abgas","en":"exhaust fume, emission","pos":"noun","plural":"die Abgase","meanings":[{"en":"exhaust gas/emission","de":"Gas aus Motor oder Industrie"}],"rule":"neutrum; meist im Plural 'Abgase' verwendet","example":"Die Abgase der Autos belasten die Luft.","exampleEn":"Car exhaust fumes pollute the air.","example2":"Neue Filter reduzieren die Abgase.","example2En":"New filters reduce the emissions."},{"de":"abhängig","en":"dependent","pos":"adjective","plural":"","meanings":[{"en":"dependent on something/someone","de":"nicht unabhängig, auf etwas angewiesen"}],"rule":"+ von + Dativ (abhängig von); Gegenteil: unabhängig","example":"Der Erfolg ist abhängig vom Wetter.","exampleEn":"The success depends on the weather.","example2":"Er ist von seinen Eltern finanziell abhängig.","example2En":"He is financially dependent on his parents."},{"de":"abheften","en":"to file (documents)","pos":"verb","plural":"","meanings":[{"en":"to file away (paperwork)","de":"Papiere in einer Mappe ablegen"}],"rule":"trennbar: heftet ... ab, heftete ab, hat abgeheftet","example":"Sie heftet die Rechnungen ab.","exampleEn":"She files the invoices.","example2":"Kannst du diese Briefe abheften?","example2En":"Can you file these letters?"},{"de":"abnehmen","en":"to lose weight; to take off/remove; to decrease","pos":"verb","plural":"","meanings":[{"en":"to lose weight","de":"weniger wiegen"},{"en":"to take off/remove something","de":"etwas wegnehmen"},{"en":"to decrease","de":"weniger werden"}],"rule":"trennbar, unregelmäßig: nimmt ... ab, nahm ab, hat abgenommen","example":"Sie hat fünf Kilo abgenommen.","exampleEn":"She has lost five kilos.","example2":"Er nimmt den Hörer ab.","example2En":"He picks up the receiver."},{"de":"die Absage","en":"refusal, cancellation, rejection","pos":"noun","plural":"die Absagen","meanings":[{"en":"a rejection/decline (e.g. to an invitation, application)","de":"negative Antwort, Ablehnung"},{"en":"cancellation of an event","de":"Stornierung einer Veranstaltung"}],"rule":"feminin; Gegenteil: die Zusage","example":"Ich habe eine Absage auf meine Bewerbung bekommen.","exampleEn":"I got a rejection for my application.","example2":"Wegen des Regens kam es zur Absage der Veranstaltung.","example2En":"Due to the rain, the event was cancelled."},{"de":"abschicken","en":"to send off (a letter/email)","pos":"verb","plural":"","meanings":[{"en":"to send off/mail something","de":"etwas per Post oder E-Mail senden"}],"rule":"trennbar: schickt ... ab, schickte ab, hat abgeschickt","example":"Ich habe die Bewerbung schon abgeschickt.","exampleEn":"I already sent off the application.","example2":"Schick die E-Mail bitte heute noch ab.","example2En":"Please send the email off today."},{"de":"absichtlich","en":"intentional, on purpose","pos":"adjective","plural":"","meanings":[{"en":"done on purpose, deliberate","de":"mit Absicht, nicht aus Versehen"}],"rule":"Gegenteil: versehentlich, unabsichtlich","example":"Er hat das absichtlich gemacht.","exampleEn":"He did that on purpose.","example2":"Das war keine absichtliche Beleidigung.","example2En":"That was not an intentional insult."},{"de":"absolvieren","en":"to complete, to graduate from","pos":"verb","plural":"","meanings":[{"en":"to complete (training, studies, a course)","de":"eine Ausbildung oder Prüfung erfolgreich beenden"}],"rule":"nicht trennbar, kein 'ge-' im Partizip: absolviert, absolvierte, hat absolviert","example":"Sie hat ihr Studium erfolgreich absolviert.","exampleEn":"She successfully completed her studies.","example2":"Er muss noch ein Praktikum absolvieren.","example2En":"He still has to complete an internship."},{"de":"absprechen","en":"to agree on, to arrange (together)","pos":"verb","plural":"","meanings":[{"en":"to agree on/coordinate something with others","de":"etwas gemeinsam vereinbaren"}],"rule":"trennbar, oft reflexiv 'sich absprechen (mit + Dativ)'; unregelmäßig: spricht ... ab, sprach ab, hat abgesprochen","example":"Wir müssen den Termin noch absprechen.","exampleEn":"We still need to agree on the appointment.","example2":"Sie sprechen sich mit den Kollegen ab.","example2En":"They coordinate with their colleagues."},{"de":"der Abstellplatz","en":"parking space, storage space","pos":"noun","plural":"die Abstellplätze","meanings":[{"en":"a designated space for parking or storing something","de":"Platz zum Parken oder Abstellen von Gegenständen"}],"rule":"maskulin; oft für Fahrräder oder Autos","example":"Das Fahrrad steht auf dem Abstellplatz.","exampleEn":"The bike is in the storage space.","example2":"Die Wohnung hat einen eigenen Abstellplatz für das Auto.","example2En":"The apartment has its own parking space for the car."},{"de":"der Abteilungsleiter / die Abteilungsleiterin","en":"department head, department manager","pos":"noun","plural":"die Abteilungsleiter / die Abteilungsleiterinnen","meanings":[{"en":"head of a department","de":"Person, die eine Abteilung leitet"}],"rule":"maskulin/feminin; weibliche Form mit -in","example":"Der Abteilungsleiter hat das Meeting geleitet.","exampleEn":"The department head led the meeting.","example2":"Sie ist Abteilungsleiterin im Personalbüro.","example2En":"She is the department manager in the HR office."},{"de":"das Abwasser","en":"wastewater, sewage","pos":"noun","plural":"die Abwässer","meanings":[{"en":"used/dirty water, sewage","de":"gebrauchtes, schmutziges Wasser"}],"rule":"neutrum; meist Singular verwendet, Plural 'Abwässer' bei verschiedenen Arten","example":"Das Abwasser wird in der Kläranlage gereinigt.","exampleEn":"The wastewater is treated at the sewage plant.","example2":"Die Fabrik leitet ihr Abwasser in den Fluss.","example2En":"The factory discharges its wastewater into the river."},{"de":"abwechslungsreich","en":"varied, full of variety","pos":"adjective","plural":"","meanings":[{"en":"varied, diverse, not monotonous","de":"mit viel Abwechslung, nicht eintönig"}],"rule":"Gegenteil: eintönig, langweilig","example":"Mein Job ist sehr abwechslungsreich.","exampleEn":"My job is very varied.","example2":"Wir hatten einen abwechslungsreichen Urlaub.","example2En":"We had a varied vacation."},{"de":"die Abwicklung","en":"processing, handling, settlement","pos":"noun","plural":"die Abwicklungen","meanings":[{"en":"the handling/processing of a transaction or task","de":"die Durchführung oder Erledigung eines Vorgangs"}],"rule":"feminin; oft in Geschäftskontexten (Abwicklung eines Auftrags)","example":"Die Abwicklung des Auftrags dauert drei Tage.","exampleEn":"Processing the order takes three days.","example2":"Die Bank kümmert sich um die Abwicklung der Zahlung.","example2En":"The bank takes care of the settlement of the payment."},{"de":"achten","en":"to pay attention; to respect","pos":"verb","plural":"","meanings":[{"en":"to pay attention to, watch out for","de":"auf etwas achten = aufpassen"},{"en":"to respect, esteem someone","de":"jemanden respektieren"}],"rule":"'achten auf' + Akkusativ = aufpassen; 'jemanden achten' = respektieren. Regelmäßig: achtet, achtete, hat geachtet.","example":"Achte auf den Verkehr, bevor du die Straße überquerst.","exampleEn":"Watch out for traffic before you cross the street.","example2":"Die Kollegen achten ihn sehr, weil er immer fair ist.","example2En":"The colleagues respect him a lot because he is always fair."},{"de":"die AGB","en":"general terms and conditions","pos":"noun","plural":"","meanings":[{"en":"the standard contractual terms of a company","de":"Allgemeine Geschäftsbedingungen"}],"rule":"Abkürzung für 'Allgemeine Geschäftsbedingungen'; wird nur im Plural benutzt: 'die AGB'.","example":"Bitte lesen Sie die AGB, bevor Sie bestellen.","exampleEn":"Please read the terms and conditions before you order.","example2":"Mit dem Klick akzeptieren Sie unsere AGB.","example2En":"By clicking, you accept our terms and conditions."},{"de":"aktiv","en":"active","pos":"adjective","plural":"","meanings":[{"en":"physically or socially active, engaged","de":"tätig, nicht passiv"}],"rule":"Regelmäßige Steigerung: aktiv, aktiver, am aktivsten.","example":"Meine Oma ist auch mit 80 noch sehr aktiv.","exampleEn":"My grandma is still very active even at 80.","example2":"Er ist aktives Mitglied im Sportverein.","example2En":"He is an active member of the sports club."},{"de":"akzeptieren","en":"to accept","pos":"verb","plural":"","meanings":[{"en":"to accept, agree to","de":"annehmen, zustimmen"}],"rule":"Regelmäßig: akzeptiert, akzeptierte, hat akzeptiert. Oft mit Akkusativ.","example":"Der Laden akzeptiert nur Bargeld.","exampleEn":"The shop only accepts cash.","example2":"Ich akzeptiere deine Entscheidung.","example2En":"I accept your decision."},{"de":"der Alkohol","en":"alcohol","pos":"noun","plural":"","meanings":[{"en":"alcohol (as a drink or substance)","de":"alkoholisches Getränk oder Stoff"}],"rule":"Meist unzählbar, kein Plural im Alltagsgebrauch.","example":"Er trinkt keinen Alkohol mehr.","exampleEn":"He doesn't drink alcohol anymore.","example2":"Alkohol am Steuer ist verboten.","example2En":"Drinking alcohol while driving is forbidden."},{"de":"allerdings","en":"however, though","pos":"adverb","plural":"","meanings":[{"en":"however, but (restricting a statement)","de":"aber, jedoch"}],"rule":"Adverb, steht oft im Mittelfeld oder am Satzanfang mit Inversion: 'Allerdings hat er recht.'","example":"Das Restaurant ist gut, allerdings etwas teuer.","exampleEn":"The restaurant is good, though a bit expensive.","example2":"Ich komme mit, allerdings erst später.","example2En":"I'll come along, but only later."},{"de":"die Allergie","en":"allergy","pos":"noun","plural":"die Allergien","meanings":[{"en":"an allergic reaction to a substance","de":"Überempfindlichkeit gegen einen Stoff"}],"rule":"'Allergie gegen' + Akkusativ: eine Allergie gegen Nüsse.","example":"Sie hat eine Allergie gegen Katzenhaare.","exampleEn":"She has an allergy to cat hair.","example2":"Im Frühling werden viele Allergien schlimmer.","example2En":"Many allergies get worse in spring."},{"de":"allergisch","en":"allergic","pos":"adjective","plural":"","meanings":[{"en":"having an allergic reaction to something","de":"überempfindlich gegen etwas"}],"rule":"'allergisch gegen' + Akkusativ: allergisch gegen Pollen.","example":"Ich bin allergisch gegen Erdnüsse.","exampleEn":"I am allergic to peanuts.","example2":"Bist du allergisch gegen Hausstaub?","example2En":"Are you allergic to house dust?"},{"de":"der Alliierte / die Alliierte","en":"ally; the Allies (pl.)","pos":"noun","plural":"die Alliierten","meanings":[{"en":"a member of an alliance, especially the Allies of WWII","de":"Mitglied eines Bündnisses, besonders die Siegermächte des Zweiten Weltkriegs"}],"rule":"Substantiviertes Adjektiv, dekliniert wie ein Adjektiv: der Alliierte, ein Alliierter, die Alliierten.","example":"Nach 1945 teilten die Alliierten Deutschland in Zonen.","exampleEn":"After 1945 the Allies divided Germany into zones.","example2":"Die Alliierten befreiten viele Länder.","example2En":"The Allies liberated many countries."},{"de":"der Altenpfleger / die Altenpflegerin","en":"geriatric nurse, elderly caregiver","pos":"noun","plural":"die Altenpfleger / die Altenpflegerinnen","meanings":[{"en":"a person trained to care for elderly people","de":"Fachkraft, die alte Menschen pflegt"}],"rule":"Berufsbezeichnung; weibliche Form mit -in: die Altenpflegerin.","example":"Mein Bruder arbeitet als Altenpfleger im Seniorenheim.","exampleEn":"My brother works as a geriatric nurse in the nursing home.","example2":"Altenpflegerinnen haben einen anstrengenden, aber wichtigen Beruf.","example2En":"Geriatric nurses have a demanding but important job."},{"de":"das Alter","en":"age","pos":"noun","plural":"","meanings":[{"en":"a person's age in years","de":"wie viele Jahre jemand alt ist"},{"en":"old age, later stage of life","de":"das hohe Lebensalter"}],"rule":"Meist unzählbar; 'im Alter von' + Jahreszahl = at the age of.","example":"In welchem Alter bist du in die Schule gekommen?","exampleEn":"At what age did you start school?","example2":"Im Alter wird man oft ruhiger.","example2En":"In old age one often becomes calmer."},{"de":"das Altöl","en":"waste oil, used oil","pos":"noun","plural":"","meanings":[{"en":"used motor or engine oil to be disposed of","de":"gebrauchtes Motoröl zur Entsorgung"}],"rule":"Unzählbar, kein Plural. Wird oft im Kontext von Recycling benutzt.","example":"Altöl darf man nicht in den Abfluss schütten.","exampleEn":"You must not pour waste oil down the drain.","example2":"Die Werkstatt sammelt das Altöl in speziellen Behältern.","example2En":"The garage collects the waste oil in special containers."},{"de":"das Altpapier","en":"waste paper, paper for recycling","pos":"noun","plural":"","meanings":[{"en":"used paper collected for recycling","de":"gebrauchtes Papier zum Recyceln"}],"rule":"Unzählbar, kein Plural.","example":"Zeitungen gehören ins Altpapier.","exampleEn":"Newspapers belong in the paper recycling.","example2":"Am Mittwoch wird das Altpapier abgeholt.","example2En":"The waste paper is collected on Wednesday."},{"de":"das Aluminium","en":"aluminium","pos":"noun","plural":"","meanings":[{"en":"the light metal aluminium","de":"leichtes Metall"}],"rule":"Unzählbar, kein Plural.","example":"Die Dose besteht aus Aluminium.","exampleEn":"The can is made of aluminium.","example2":"Aluminium lässt sich gut recyceln.","example2En":"Aluminium can be recycled well."},{"de":"amtlich","en":"official","pos":"adjective","plural":"","meanings":[{"en":"official, from an authority","de":"von einer Behörde stammend, offiziell"}],"rule":"Regelmäßige Steigerung; oft mit Dokumenten/Behörden verbunden: amtliches Kennzeichen.","example":"Ich brauche eine amtliche Bescheinigung.","exampleEn":"I need an official certificate.","example2":"Das Auto hat noch kein amtliches Kennzeichen.","example2En":"The car doesn't have an official license plate yet."},{"de":"die Amtssprache","en":"official language","pos":"noun","plural":"die Amtssprachen","meanings":[{"en":"the language officially used by a state or organization","de":"offiziell anerkannte Sprache eines Staates"}],"rule":"Zusammensetzung aus 'Amt' + 'Sprache'.","example":"Deutsch ist die Amtssprache in Österreich.","exampleEn":"German is the official language in Austria.","example2":"Die EU hat viele Amtssprachen.","example2En":"The EU has many official languages."},{"de":"der Anbau","en":"cultivation; extension (building)","pos":"noun","plural":"die Anbauten","meanings":[{"en":"the growing of crops or plants","de":"das Anpflanzen von Pflanzen"},{"en":"an extension added to a building","de":"zusätzlicher Gebäudeteil"}],"rule":"Zwei Bedeutungen: Landwirtschaft (meist Singular, kein Plural) oder Bauwesen (Plural: die Anbauten).","example":"Der Anbau von Gemüse braucht viel Wasser.","exampleEn":"Growing vegetables requires a lot of water.","example2":"Wir planen einen Anbau an unser Haus.","example2En":"We are planning an extension to our house."},{"de":"andauernd","en":"continuous, constant","pos":"adjective","plural":"","meanings":[{"en":"happening continuously or repeatedly, without stopping","de":"ständig, ohne Unterbrechung"}],"rule":"Von 'andauern' (dauern, anhalten) abgeleitetes Adjektiv/Adverb; oft mit negativem Unterton (Genervtsein).","example":"Das andauernde Klingeln nervt mich.","exampleEn":"The constant ringing annoys me.","example2":"Sie beschwert sich andauernd über das Wetter.","example2En":"She constantly complains about the weather."},{"de":"anerkennen","en":"to recognize; to acknowledge","pos":"verb","plural":"","meanings":[{"en":"to officially recognize (a qualification, status)","de":"offiziell akzeptieren"},{"en":"to acknowledge/appreciate (effort, achievement)","de":"würdigen, schätzen"}],"rule":"trennbar: erkennt an, Präteritum: erkannte an, Perfekt: hat anerkannt (untrennbares -erkenn- bleibt zusammen im Partizip: anerkannt, kein 'ge-')","example":"Der Arbeitgeber erkennt mein Diplom aus dem Ausland an.","exampleEn":"My employer recognizes my diploma from abroad.","example2":"Der Chef hat ihre gute Arbeit anerkannt.","example2En":"The boss acknowledged her good work."},{"de":"die Anerkennung","en":"recognition; appreciation","pos":"noun","plural":"die Anerkennungen","meanings":[{"en":"official recognition (of a qualification)","de":"offizielle Bestätigung"},{"en":"appreciation, praise","de":"Würdigung, Lob"}],"rule":"von 'anerkennen' abgeleitetes Nomen; oft mit 'finden' (Anerkennung finden) oder 'bekommen'","example":"Die Anerkennung ihres Abschlusses hat drei Monate gedauert.","exampleEn":"The recognition of her degree took three months.","example2":"Er bekam viel Anerkennung für sein Projekt.","example2En":"He received a lot of appreciation for his project."},{"de":"anfahren","en":"to start moving; to drive into (crash); to snap at someone","pos":"verb","plural":"","meanings":[{"en":"to set off / start driving","de":"losfahren"},{"en":"to hit/crash into (with a vehicle)","de":"mit dem Fahrzeug gegen etwas fahren"},{"en":"to yell at / snap at someone","de":"jemanden grob ansprechen"}],"rule":"trennbar; fährt an, fuhr an, ist/hat angefahren (bei intransitivem 'losfahren': ist angefahren; bei transitivem 'anfahren' im Sinne von 'hit' und bei 'anschreien' mit Akkusativobjekt: hat angefahren)","example":"Der Bus fuhr langsam an.","exampleEn":"The bus slowly started moving.","example2":"Der Chef hat ihn wegen des Fehlers angefahren.","example2En":"The boss snapped at him because of the mistake."},{"de":"der Anfang","en":"beginning, start","pos":"noun","plural":"die Anfänge","meanings":[{"en":"beginning, start","de":"Beginn"}],"rule":"Ausdruck: am Anfang (at the beginning); Gegenteil: das Ende","example":"Am Anfang war der Kurs sehr schwer.","exampleEn":"At the beginning, the course was very difficult.","example2":"Wir haben am Anfang des Monats die Miete bezahlt.","example2En":"We paid the rent at the beginning of the month."},{"de":"anfangs","en":"at first, initially","pos":"adverb","plural":"","meanings":[{"en":"at first, in the beginning","de":"zu Beginn, am Anfang"}],"rule":"Adverb, kein Artikel nötig; ähnlich wie 'am Anfang', aber steht direkt als Adverb im Satz","example":"Anfangs verstand ich kein Wort Deutsch.","exampleEn":"At first, I didn't understand a word of German.","example2":"Anfangs war die Arbeit stressig, jetzt ist es besser.","example2En":"Initially the job was stressful, now it's better."},{"de":"anfassen","en":"to touch; to grab hold of","pos":"verb","plural":"","meanings":[{"en":"to touch (with hands)","de":"berühren"}],"rule":"trennbar: fasst an, fasste an, hat angefasst","example":"Bitte die Bilder im Museum nicht anfassen.","exampleEn":"Please don't touch the pictures in the museum.","example2":"Er hat vorsichtig die heiße Pfanne angefasst.","example2En":"He carefully touched the hot pan."},{"de":"angenehm","en":"pleasant, comfortable","pos":"adjective","plural":"","meanings":[{"en":"pleasant, agreeable","de":"wohltuend, nett"}],"rule":"regelmäßige Steigerung: angenehm, angenehmer, am angenehmsten; Gegenteil: unangenehm","example":"Das Wetter heute ist sehr angenehm.","exampleEn":"The weather today is very pleasant.","example2":"Es war ein angenehmes Gespräch mit ihr.","example2En":"It was a pleasant conversation with her."},{"de":"anheben","en":"to lift up; to raise (prices, wages)","pos":"verb","plural":"","meanings":[{"en":"to lift up physically","de":"hochheben"},{"en":"to raise (prices, salaries)","de":"erhöhen"}],"rule":"trennbar: hebt an, hob an, hat angehoben","example":"Zu zweit konnten sie den Schrank anheben.","exampleEn":"Together, the two of them managed to lift the cabinet.","example2":"Die Firma hat die Gehälter angehoben.","example2En":"The company raised the salaries."},{"de":"ankündigen","en":"to announce","pos":"verb","plural":"","meanings":[{"en":"to announce beforehand","de":"im Voraus mitteilen"}],"rule":"trennbar: kündigt an, kündigte an, hat angekündigt","example":"Der Lehrer hat die Prüfung schon letzte Woche angekündigt.","exampleEn":"The teacher already announced the exam last week.","example2":"Die Firma kündigt neue Produkte an.","example2En":"The company is announcing new products."},{"de":"die Anlage","en":"facility, plant; attachment (email); investment","pos":"noun","plural":"die Anlagen","meanings":[{"en":"facility, installation, plant","de":"Einrichtung, technisches System"},{"en":"attachment (to a letter/email)","de":"Beilage, beigefügtes Dokument"},{"en":"investment (of money)","de":"Geldanlage"}],"rule":"mehrdeutiges Nomen; im Geschäftsbrief: 'siehe Anlage' = see attachment","example":"Die Firma hat eine neue Anlage zur Stromproduktion gebaut.","exampleEn":"The company built a new plant for electricity production.","example2":"Bitte beachten Sie die Anlage zu dieser E-Mail.","example2En":"Please note the attachment to this email."},{"de":"anmachen","en":"to switch on; to flirt with someone (informal)","pos":"verb","plural":"","meanings":[{"en":"to switch on (light, device)","de":"einschalten"},{"en":"to flirt with / hit on someone (umgangssprachlich)","de":"flirten mit jemandem"}],"rule":"trennbar: macht an, machte an, hat angemacht; 'einschalten' ist neutral, die Bedeutung 'flirten' ist umgangssprachlich","example":"Kannst du bitte das Licht anmachen?","exampleEn":"Can you please turn on the light?","example2":"Ein Typ hat sie in der Bar angemacht.","example2En":"A guy hit on her at the bar."},{"de":"die Annahme","en":"assumption; acceptance","pos":"noun","plural":"die Annahmen","meanings":[{"en":"assumption, presumption","de":"Vermutung"},{"en":"acceptance (of an offer, package)","de":"das Annehmen"}],"rule":"von 'annehmen' abgeleitet; 'in der Annahme, dass...' = assuming that...","example":"Meine Annahme war falsch.","exampleEn":"My assumption was wrong.","example2":"Die Annahme des Pakets erfolgt am Schalter.","example2En":"The acceptance of the package takes place at the counter."},{"de":"annullieren","en":"to cancel, to annul","pos":"verb","plural":"","meanings":[{"en":"to declare invalid, to cancel (a flight, contract, order)","de":"für ungültig erklären, stornieren"}],"rule":"regelmäßig: annulliert, annullierte, hat annulliert; wird häufig im Passiv verwendet (wird annulliert / ist annulliert worden)","example":"Die Fluggesellschaft hat den Flug wegen des Sturms annulliert.","exampleEn":"The airline cancelled the flight because of the storm.","example2":"Die Bestellung ist annulliert worden.","example2En":"The order has been annulled."},{"de":"die Anprobe","en":"fitting (of clothes)","pos":"noun","plural":"die Anproben","meanings":[{"en":"trying on clothes, fitting","de":"das Anprobieren von Kleidung"}],"rule":"Nomen zu 'anprobieren'; typisch im Geschäft/beim Schneider","example":"Die Anprobe des Hochzeitskleides dauerte eine Stunde.","exampleEn":"The fitting of the wedding dress took an hour.","example2":"Haben Sie einen Termin für die Anprobe?","example2En":"Do you have an appointment for the fitting?"}]},{"id":"b1-02","title":"B1 · A (2)","level":"B1","words":[{"de":"anprobieren","en":"to try on (clothes)","pos":"verb","plural":"","meanings":[{"en":"to try on clothes/shoes","de":"Kleidung testen, ob sie passt"}],"rule":"trennbar: probiert an, probierte an, hat anprobiert","example":"Ich möchte dieses Kleid anprobieren.","exampleEn":"I would like to try on this dress.","example2":"Er hat drei Paar Schuhe anprobiert.","example2En":"He tried on three pairs of shoes."},{"de":"anrechnen","en":"to count towards; to charge for","pos":"verb","plural":"","meanings":[{"en":"to credit/count something towards a total","de":"berücksichtigen, gutschreiben"},{"en":"to charge someone for something","de":"in Rechnung stellen"}],"rule":"trennbar: rechnet an, rechnete an, hat angerechnet; oft mit Dativ der Person (jemandem etwas anrechnen)","example":"Das Praktikum wird mir auf das Studium angerechnet.","exampleEn":"The internship will be counted towards my studies.","example2":"Der Kellner hat uns das Wasser nicht angerechnet.","example2En":"The waiter didn't charge us for the water."},{"de":"anschauen","en":"to look at, to watch","pos":"verb","plural":"","meanings":[{"en":"to look at, view","de":"ansehen, betrachten"}],"rule":"trennbar: schaut an, schaute an, hat angeschaut; süddeutsch/österreichisch häufiger als 'ansehen'","example":"Wir haben uns gestern einen Film angeschaut.","exampleEn":"We watched a movie yesterday.","example2":"Schau dir das mal an!","example2En":"Take a look at this!"},{"de":"ansehen","en":"to look at; to regard as","pos":"verb","plural":"","meanings":[{"en":"to look at / watch","de":"anschauen, betrachten"},{"en":"to regard as, consider","de":"betrachten als, halten für"}],"rule":"trennbar: sieht an, sah an, hat angesehen; oft reflexiv 'sich (Dat.) etwas ansehen'","example":"Wir sehen uns heute Abend einen Film an.","exampleEn":"We're watching a movie tonight.","example2":"Sie sehen ihn als Experten an.","example2En":"They regard him as an expert."},{"de":"anstatt","en":"instead of","pos":"preposition","plural":"","meanings":[{"en":"instead of","de":"statt"}],"rule":"+ Genitiv (anstatt des/der...); auch als Konjunktion mit 'zu' + Infinitiv","example":"Anstatt zu telefonieren, schreibt er lieber E-Mails.","exampleEn":"Instead of calling, he prefers writing emails.","example2":"Ich nehme den Bus anstatt des Autos.","example2En":"I take the bus instead of the car."},{"de":"ansteckend","en":"contagious, infectious","pos":"adjective","plural":"","meanings":[{"en":"contagious, infectious (illness)","de":"übertragbar (Krankheit)"},{"en":"infectious (mood, laughter)","de":"mitreißend"}],"rule":"Adjektiv, regelmäßige Steigerung: ansteckend, ansteckender, am ansteckendsten","example":"Die Grippe ist sehr ansteckend.","exampleEn":"The flu is very contagious.","example2":"Ihr Lachen ist ansteckend.","example2En":"Her laughter is infectious."},{"de":"die Anstellung","en":"employment, job","pos":"noun","plural":"die Anstellungen","meanings":[{"en":"employment, job","de":"Arbeitsstelle, Beschäftigung"}],"rule":"feminin, die Anstellungen; oft 'eine feste Anstellung'","example":"Sie hat endlich eine feste Anstellung gefunden.","exampleEn":"She has finally found a permanent job.","example2":"Nach dem Studium suchte er eine Anstellung als Ingenieur.","example2En":"After his studies he looked for a job as an engineer."},{"de":"der Anstoß","en":"kickoff; impetus","pos":"noun","plural":"die Anstöße","meanings":[{"en":"kickoff (sports)","de":"Beginn eines Fußballspiels"},{"en":"impetus, stimulus","de":"Anregung, Impuls"}],"rule":"maskulin, die Anstöße; feste Wendung: 'den Anstoß geben zu'","example":"Der Anstoß erfolgt um 15 Uhr.","exampleEn":"Kickoff is at 3 pm.","example2":"Sein Vortrag gab den Anstoß zu vielen neuen Ideen.","example2En":"His talk gave the impetus for many new ideas."},{"de":"anstreichen","en":"to paint; to mark","pos":"verb","plural":"","meanings":[{"en":"to paint (a wall/surface)","de":"mit Farbe bemalen"},{"en":"to mark/underline (an error)","de":"markieren, kennzeichnen"}],"rule":"trennbar: streicht an, strich an, hat angestrichen","example":"Wir haben das Zimmer neu angestrichen.","exampleEn":"We repainted the room.","example2":"Der Lehrer strich die Fehler im Text rot an.","example2En":"The teacher marked the mistakes in the text in red."},{"de":"anstrengend","en":"exhausting, strenuous","pos":"adjective","plural":"","meanings":[{"en":"exhausting, strenuous","de":"ermüdend, kräftezehrend"}],"rule":"Adjektiv, regelmäßig gesteigert: anstrengend, anstrengender, am anstrengendsten","example":"Die Wanderung war sehr anstrengend.","exampleEn":"The hike was very exhausting.","example2":"Ein Tag mit kleinen Kindern kann anstrengend sein.","example2En":"A day with small children can be exhausting."},{"de":"die Anzeigetafel","en":"scoreboard, display board","pos":"noun","plural":"die Anzeigetafeln","meanings":[{"en":"scoreboard, display board","de":"Tafel mit Informationen/Ergebnissen"}],"rule":"feminin, die Anzeigetafeln","example":"Das Ergebnis steht auf der Anzeigetafel.","exampleEn":"The score is shown on the scoreboard.","example2":"Am Bahnhof zeigt die Anzeigetafel die Abfahrtszeiten.","example2En":"At the station, the display board shows departure times."},{"de":"die Arbeitskraft","en":"worker; workforce, manpower","pos":"noun","plural":"die Arbeitskräfte","meanings":[{"en":"worker, employee","de":"Person, die arbeitet"},{"en":"working capacity, manpower","de":"Fähigkeit zu arbeiten"}],"rule":"feminin, die Arbeitskräfte; als Person zählbar, als Fähigkeit meist Singular","example":"Die Firma stellt drei neue Arbeitskräfte ein.","exampleEn":"The company is hiring three new workers.","example2":"Die körperliche Arbeitskraft lässt im Alter nach.","example2En":"Physical work capacity declines with age."},{"de":"die Arbeitslosigkeit","en":"unemployment","pos":"noun","plural":"","meanings":[{"en":"unemployment","de":"Zustand ohne Arbeit"}],"rule":"feminin, Singularwort (kein Plural)","example":"Die Arbeitslosigkeit ist in diesem Jahr gestiegen.","exampleEn":"Unemployment has risen this year.","example2":"Langzeitige Arbeitslosigkeit belastet viele Familien.","example2En":"Long-term unemployment burdens many families."},{"de":"die Arbeitsstelle","en":"job, workplace","pos":"noun","plural":"die Arbeitsstellen","meanings":[{"en":"job, workplace","de":"Ort/Stelle, an der man arbeitet"}],"rule":"feminin, die Arbeitsstellen; Synonym zu 'Arbeitsplatz'","example":"Er hat eine neue Arbeitsstelle in Berlin.","exampleEn":"He has a new job in Berlin.","example2":"Sie pendelt jeden Tag zu ihrer Arbeitsstelle.","example2En":"She commutes to her workplace every day."},{"de":"die Arbeitsweise","en":"way of working, method","pos":"noun","plural":"die Arbeitsweisen","meanings":[{"en":"way of working, method","de":"Methode, wie man arbeitet"}],"rule":"feminin, die Arbeitsweisen","example":"Die Arbeitsweise der Firma hat sich verändert.","exampleEn":"The company's way of working has changed.","example2":"Jeder Lehrer hat seine eigene Arbeitsweise.","example2En":"Every teacher has their own working method."},{"de":"die Arbeitszeit","en":"working hours","pos":"noun","plural":"die Arbeitszeiten","meanings":[{"en":"working hours","de":"Zeit, in der man arbeitet"}],"rule":"feminin, die Arbeitszeiten","example":"Die Arbeitszeit beträgt 40 Stunden pro Woche.","exampleEn":"Working hours are 40 hours per week.","example2":"Nach der Arbeitszeit geht er joggen.","example2En":"After work he goes jogging."},{"de":"der Ärger","en":"anger; trouble","pos":"noun","plural":"","meanings":[{"en":"anger, annoyance","de":"Wut, Verärgerung"},{"en":"trouble, hassle","de":"Schwierigkeiten, Probleme"}],"rule":"maskulin, nur Singular (kein Plural); 'Ärger haben/machen'","example":"Er hatte Ärger mit seinem Chef.","exampleEn":"He had trouble with his boss.","example2":"Ich konnte meinen Ärger kaum verbergen.","example2En":"I could hardly hide my anger."},{"de":"ärgerlich","en":"annoying; annoyed","pos":"adjective","plural":"","meanings":[{"en":"annoying","de":"unangenehm, störend"},{"en":"annoyed","de":"verärgert"}],"rule":"Adjektiv: über etwas (Akk.) ärgerlich sein (Sache/Ereignis), auf jemanden (Akk.) ärgerlich sein (Person); regelmäßig gesteigert","example":"Es ist ärgerlich, dass der Bus schon wieder zu spät kommt.","exampleEn":"It's annoying that the bus is late again.","example2":"Sie war sehr ärgerlich über den Fehler.","example2En":"She was very annoyed about the mistake."},{"de":"die Art","en":"kind, type; manner","pos":"noun","plural":"die Arten","meanings":[{"en":"kind, type","de":"Sorte, Gattung"},{"en":"manner, way","de":"Weise, Verhaltensweise"}],"rule":"feminin, die Arten; 'auf diese Art' = in this way","example":"Das ist eine seltene Art von Vogel.","exampleEn":"That's a rare kind of bird.","example2":"Mir gefällt seine freundliche Art.","example2En":"I like his friendly manner."},{"de":"die Artikelnummer","en":"item/article number","pos":"noun","plural":"die Artikelnummern","meanings":[{"en":"item/article number","de":"Nummer zur Identifikation eines Produkts"}],"rule":"feminin, die Artikelnummern; oft abgekürzt 'Art.-Nr.'","example":"Bitte geben Sie die Artikelnummer an.","exampleEn":"Please state the item number.","example2":"Die Artikelnummer finden Sie auf der Verpackung.","example2En":"You can find the article number on the packaging."},{"de":"ärztlich","en":"medical","pos":"adjective","plural":"","meanings":[{"en":"medical (relating to a doctor)","de":"vom Arzt, den Arzt betreffend"}],"rule":"Adjektiv, Bezug zu 'Arzt'; nicht steigerbar in dieser Bedeutung","example":"Er braucht ein ärztliches Attest.","exampleEn":"He needs a doctor's certificate.","example2":"Nach dem Unfall war eine ärztliche Untersuchung nötig.","example2En":"After the accident a medical examination was necessary."},{"de":"die Assistenz","en":"assistance; support","pos":"noun","plural":"","meanings":[{"en":"assistance/support (help given)","de":"die Hilfe, Unterstützung"},{"en":"assistant role/position","de":"die Position als Assistent(in)"}],"rule":"Often used in job titles/compounds (Assistenz der Geschäftsführung); usually uncountable, no plural.","example":"Sie arbeitet in der Assistenz der Geschäftsführung.","exampleEn":"She works as an assistant to the management.","example2":"Er braucht Assistenz bei der täglichen Pflege.","example2En":"He needs assistance with daily care."},{"de":"der Astronaut / die Astronautin","en":"astronaut","pos":"noun","plural":"die Astronauten / die Astronautinnen","meanings":[{"en":"astronaut","de":"jemand, der ins Weltall fliegt"}],"rule":"Weak masculine noun: der Astronaut, den/dem/des Astronauten.","example":"Der Astronaut ist zur Raumstation geflogen.","exampleEn":"The astronaut flew to the space station.","example2":"Sie möchte später Astronautin werden.","example2En":"She wants to become an astronaut later."},{"de":"das Asyl","en":"asylum","pos":"noun","plural":"","meanings":[{"en":"asylum (political protection)","de":"Schutz vor politischer Verfolgung"}],"rule":"Uncountable; common phrase: Asyl beantragen (to apply for asylum).","example":"Die Familie hat Asyl beantragt.","exampleEn":"The family applied for asylum.","example2":"Er bekam politisches Asyl in Deutschland.","example2En":"He was granted political asylum in Germany."},{"de":"die Atmung","en":"breathing; respiration","pos":"noun","plural":"","meanings":[{"en":"breathing/respiration","de":"das Atmen"}],"rule":"Uncountable noun derived from the verb \"atmen\" (to breathe).","example":"Die Atmung wird bei Stress schneller.","exampleEn":"Breathing gets faster under stress.","example2":"Der Arzt hat die Atmung des Patienten kontrolliert.","example2En":"The doctor checked the patient's breathing."},{"de":"atmungsaktiv","en":"breathable","pos":"adjective","plural":"","meanings":[{"en":"breathable (fabric/material)","de":"lässt Luft und Feuchtigkeit durch"}],"rule":"Regular comparison (rarely used comparatively); typically describes clothing/textiles.","example":"Die Jacke ist atmungsaktiv und wasserdicht.","exampleEn":"The jacket is breathable and waterproof.","example2":"Sportschuhe sollten atmungsaktiv sein.","example2En":"Sports shoes should be breathable."},{"de":"aufdrehen","en":"to turn on; to turn up","pos":"verb","plural":"","meanings":[{"en":"to turn on/open (tap, gas)","de":"öffnen, andrehen"},{"en":"to turn up (volume)","de":"lauter stellen"}],"rule":"Trennbar: dreht ... auf, drehte ... auf, hat aufgedreht.","example":"Kannst du den Wasserhahn aufdrehen?","exampleEn":"Can you turn on the tap?","example2":"Er hat die Musik voll aufgedreht.","example2En":"He turned the music up loud."},{"de":"aufkommen","en":"to arise; to be liable for","pos":"verb","plural":"","meanings":[{"en":"to arise/come up (wind, feeling, doubt)","de":"entstehen"},{"en":"to pay for/be liable for (+für)","de":"bezahlen, haften für"}],"rule":"Trennbar, irregular: kommt auf, kam auf, ist aufgekommen; \"aufkommen für\" + Akk.","example":"Plötzlich kam starker Wind auf.","exampleEn":"Suddenly strong wind came up.","example2":"Die Versicherung kommt für den Schaden auf.","example2En":"The insurance covers/pays for the damage."},{"de":"aufmachen","en":"to open","pos":"verb","plural":"","meanings":[{"en":"to open","de":"öffnen"},{"en":"to open/set up (a shop), colloquial","de":"eröffnen"}],"rule":"Trennbar: macht auf, machte auf, hat aufgemacht.","example":"Mach bitte die Tür auf.","exampleEn":"Please open the door.","example2":"Sie haben letztes Jahr ein neues Café aufgemacht.","example2En":"They opened a new café last year."},{"de":"aufmerksam","en":"attentive","pos":"adjective","plural":"","meanings":[{"en":"attentive","de":"konzentriert, achtsam"},{"en":"pointing out/noticing (jemanden auf etwas aufmerksam machen)","de":"hinweisend"}],"rule":"Regular comparison: aufmerksam, aufmerksamer, am aufmerksamsten; fixed phrase \"jemanden auf etwas aufmerksam machen\" = to point sth out to sb.","example":"Die Schüler waren sehr aufmerksam im Unterricht.","exampleEn":"The students were very attentive in class.","example2":"Er machte mich auf den Fehler aufmerksam.","example2En":"He pointed out the mistake to me."},{"de":"die Aufregung","en":"excitement; agitation","pos":"noun","plural":"","meanings":[{"en":"excitement/agitation","de":"Nervosität, Erregung"}],"rule":"Uncountable noun from \"sich aufregen\" (to get upset/excited).","example":"Vor der Prüfung war die Aufregung groß.","exampleEn":"Before the exam the excitement/nervousness was great.","example2":"In der Aufregung hat sie ihren Schlüssel vergessen.","example2En":"In the excitement she forgot her key."},{"de":"der Aufruf","en":"call; appeal","pos":"noun","plural":"die Aufrufe","meanings":[{"en":"call/appeal (public request)","de":"öffentliche Bitte"},{"en":"calling up (name, number)","de":"Namensaufruf"}],"rule":"Noun from \"aufrufen\" (to call up/call for).","example":"Die Organisation startete einen Aufruf zur Blutspende.","exampleEn":"The organization launched an appeal for blood donations.","example2":"Beim Aufruf Ihres Namens gehen Sie bitte zum Schalter.","example2En":"When your name is called, please go to the counter."},{"de":"aufschreiben","en":"to write down","pos":"verb","plural":"","meanings":[{"en":"to write down/note","de":"notieren"}],"rule":"Trennbar, irregular: schreibt auf, schrieb auf, hat aufgeschrieben.","example":"Ich schreibe mir die Telefonnummer auf.","exampleEn":"I'm writing down the phone number.","example2":"Der Kellner hat unsere Bestellung aufgeschrieben.","example2En":"The waiter wrote down our order."},{"de":"aufteilen","en":"to divide up; to split","pos":"verb","plural":"","meanings":[{"en":"to divide up/split","de":"teilen, verteilen"}],"rule":"Trennbar: teilt auf, teilte auf, hat aufgeteilt; often + in + Akk.","example":"Wir haben die Arbeit unter uns aufgeteilt.","exampleEn":"We divided the work among ourselves.","example2":"Die Wohnung wurde in zwei kleinere Wohnungen aufgeteilt.","example2En":"The apartment was split into two smaller apartments."},{"de":"die Aufteilung","en":"division; distribution","pos":"noun","plural":"die Aufteilungen","meanings":[{"en":"division/distribution","de":"das Aufteilen"}],"rule":"Noun derived from the verb \"aufteilen\".","example":"Die Aufteilung der Kosten war fair.","exampleEn":"The division of costs was fair.","example2":"Über die Aufteilung des Erbes gab es Streit.","example2En":"There was a dispute over the division of the inheritance."},{"de":"der Auftrag","en":"order; assignment","pos":"noun","plural":"die Aufträge","meanings":[{"en":"order (commercial)","de":"Bestellung"},{"en":"assignment/task","de":"Aufgabe"}],"rule":"Common phrase: einen Auftrag erteilen/bekommen (to place/receive an order).","example":"Die Firma hat einen großen Auftrag bekommen.","exampleEn":"The company received a big order.","example2":"Ich habe den Auftrag, das Zimmer aufzuräumen.","example2En":"I have the task of tidying up the room."},{"de":"die Auftragsnummer","en":"order number","pos":"noun","plural":"die Auftragsnummern","meanings":[{"en":"order number","de":"Nummer eines Auftrags"}],"rule":"Compound noun: Auftrag + Nummer; takes gender of Nummer (die).","example":"Bitte geben Sie Ihre Auftragsnummer an.","exampleEn":"Please state your order number.","example2":"Die Auftragsnummer finden Sie auf der Rechnung.","example2En":"You'll find the order number on the invoice."},{"de":"der Ausgang","en":"exit; outcome","pos":"noun","plural":"die Ausgänge","meanings":[{"en":"exit","de":"Tür oder Weg nach draußen"},{"en":"outcome/result","de":"Ergebnis"}],"rule":"Also seen in compounds like Notausgang (emergency exit).","example":"Der Ausgang ist links neben der Kasse.","exampleEn":"The exit is on the left next to the checkout.","example2":"Der Ausgang des Spiels war ungewiss.","example2En":"The outcome of the game was uncertain."},{"de":"ausgewogen","en":"balanced","pos":"adjective","plural":"","meanings":[{"en":"balanced, well-proportioned","de":"im Gleichgewicht, harmonisch"}],"rule":"regular comparison: ausgewogen, ausgewogener, am ausgewogensten; often used with Ernährung (diet) or Mischung.","example":"Für ein gesundes Leben braucht man eine ausgewogene Ernährung.","exampleEn":"For a healthy life you need a balanced diet.","example2":"Der Bericht war sehr ausgewogen und zeigte beide Seiten.","example2En":"The report was very balanced and showed both sides."},{"de":"ausliefern","en":"to deliver; to hand over","pos":"verb","plural":"","meanings":[{"en":"to deliver (goods)","de":"liefern, zustellen"},{"en":"to hand over (a person)","de":"übergeben, preisgeben"}],"rule":"trennbar: liefert ... aus, lieferte ... aus, hat ausgeliefert.","example":"Die Firma liefert die Bestellung morgen aus.","exampleEn":"The company will deliver the order tomorrow.","example2":"Der Verbrecher wurde der Polizei ausgeliefert.","example2En":"The criminal was handed over to the police."},{"de":"die Ausnahme","en":"exception","pos":"noun","plural":"die Ausnahmen","meanings":[{"en":"exception, exemption","de":"etwas, das von der Regel abweicht"}],"rule":"common phrase: eine Ausnahme machen (to make an exception).","example":"Heute mache ich eine Ausnahme und esse Schokolade.","exampleEn":"Today I'll make an exception and eat chocolate.","example2":"Jede Regel hat ihre Ausnahme.","example2En":"Every rule has its exception."},{"de":"ausparken","en":"to park out / to pull out of a parking space","pos":"verb","plural":"","meanings":[{"en":"to drive a car out of a parking space","de":"aus einer Parklücke herausfahren"}],"rule":"trennbar: parkt ... aus, parkte ... aus, hat ausgeparkt.","example":"Ich muss vorsichtig ausparken, die Straße ist eng.","exampleEn":"I have to pull out carefully, the street is narrow.","example2":"Kannst du mir helfen auszuparken?","example2En":"Can you help me pull out of the parking space?"},{"de":"ausprobieren","en":"to try out","pos":"verb","plural":"","meanings":[{"en":"to try out, test","de":"testen, probieren"}],"rule":"trennbar: probiert ... aus, probierte ... aus, hat ausprobiert.","example":"Ich möchte das neue Restaurant ausprobieren.","exampleEn":"I want to try out the new restaurant.","example2":"Probier doch mal die App aus, sie ist praktisch.","example2En":"Just try the app out, it's practical."},{"de":"ausschalten","en":"to switch off","pos":"verb","plural":"","meanings":[{"en":"to turn off (a device)","de":"abschalten, ausmachen"}],"rule":"trennbar: schaltet ... aus, schaltete ... aus, hat ausgeschaltet.","example":"Bitte schalte das Licht aus, bevor du gehst.","exampleEn":"Please switch off the light before you leave.","example2":"Er hat sein Handy während des Films ausgeschaltet.","example2En":"He switched off his phone during the film."},{"de":"ausschlafen","en":"to sleep in; to get enough sleep","pos":"verb","plural":"","meanings":[{"en":"to sleep until fully rested","de":"lange und genug schlafen"}],"rule":"trennbar, irregular: schläft ... aus, schlief ... aus, hat ausgeschlafen.","example":"Am Wochenende kann ich endlich mal ausschlafen.","exampleEn":"On the weekend I can finally sleep in.","example2":"Bist du ausgeschlafen oder noch müde?","example2En":"Did you get enough sleep or are you still tired?"},{"de":"der Außenspiegel","en":"side mirror (of a car)","pos":"noun","plural":"die Außenspiegel","meanings":[{"en":"exterior mirror of a vehicle","de":"Spiegel außen am Auto"}],"rule":"compound noun: außen + Spiegel; gender follows der Spiegel.","example":"Vor dem Abbiegen schaue ich immer in den Außenspiegel.","exampleEn":"Before turning I always check the side mirror.","example2":"Der Außenspiegel ist beim Parken abgebrochen.","example2En":"The side mirror broke off while parking."},{"de":"die Ausstattung","en":"equipment, furnishing","pos":"noun","plural":"die Ausstattungen","meanings":[{"en":"equipment, furnishing, features","de":"das, womit etwas ausgestattet ist"}],"rule":"often used for cars, apartments, hotel rooms describing included features.","example":"Das Auto hat eine gute Ausstattung mit Klimaanlage und Navi.","exampleEn":"The car has good equipment with air conditioning and navigation.","example2":"Die Ausstattung der Wohnung ist einfach, aber modern.","example2En":"The furnishing of the apartment is simple but modern."},{"de":"ausstellen","en":"to exhibit; to issue (a document)","pos":"verb","plural":"","meanings":[{"en":"to exhibit, display","de":"präsentieren, zeigen"},{"en":"to issue (a certificate, invoice)","de":"ein Dokument erstellen und geben"}],"rule":"trennbar: stellt ... aus, stellte ... aus, hat ausgestellt.","example":"Die Bilder werden im Museum ausgestellt.","exampleEn":"The paintings are being exhibited in the museum.","example2":"Der Arzt hat mir eine Krankschreibung ausgestellt.","example2En":"The doctor issued me a sick note."},{"de":"die Auswahl","en":"selection, choice","pos":"noun","plural":"die Auswahlen","meanings":[{"en":"selection, range of choice","de":"Angebot, aus dem man wählen kann"}],"rule":"often used with 'eine große/kleine Auswahl an + Dativ'.","example":"Der Supermarkt hat eine große Auswahl an Käse.","exampleEn":"The supermarket has a large selection of cheese.","example2":"Bitte triff eine Auswahl aus den drei Angeboten.","example2En":"Please make a choice from the three offers."},{"de":"der Auswanderer","en":"emigrant","pos":"noun","plural":"die Auswanderer","meanings":[{"en":"person who emigrates","de":"jemand, der sein Land verlässt, um woanders zu leben"}],"rule":"feminine form: die Auswanderin (plural: die Auswanderinnen) — parallel to der Wanderer / die Wanderin, not 'Auswandererin'.","example":"Viele Auswanderer verließen im 19. Jahrhundert Europa.","exampleEn":"Many emigrants left Europe in the 19th century.","example2":"Der Auswanderer schickte Briefe an seine Familie zu Hause.","example2En":"The emigrant sent letters to his family back home."}]},{"id":"b1-03","title":"B1 · A–B (3)","level":"B1","words":[{"de":"die Auswanderung","en":"emigration","pos":"noun","plural":"die Auswanderungen","meanings":[{"en":"act of emigrating","de":"das Verlassen des eigenen Landes, um woanders zu leben"}],"rule":"opposite of Einwanderung (immigration).","example":"Die Auswanderung nach Amerika war für viele ein großer Schritt.","exampleEn":"Emigration to America was a big step for many.","example2":"Nach der Auswanderung musste die Familie eine neue Sprache lernen.","example2En":"After emigrating, the family had to learn a new language."},{"de":"der Auszug","en":"move-out; excerpt","pos":"noun","plural":"die Auszüge","meanings":[{"en":"moving out (of an apartment)","de":"das Verlassen einer Wohnung"},{"en":"excerpt, extract (from a text)","de":"Teil eines Textes"}],"rule":"related verb: ausziehen; compound: Kontoauszug (bank statement).","example":"Der Auszug aus der alten Wohnung war stressig.","exampleEn":"Moving out of the old apartment was stressful.","example2":"Wir lesen heute einen Auszug aus dem Roman.","example2En":"Today we're reading an excerpt from the novel."},{"de":"der Autofahrer / die Autofahrerin","en":"driver (of a car)","pos":"noun","plural":"die Autofahrer / die Autofahrerinnen","meanings":[{"en":"person who drives a car","de":"jemand, der Auto fährt"}],"rule":"compound: Auto + Fahrer; feminine adds -in.","example":"Der Autofahrer hielt an der roten Ampel.","exampleEn":"The driver stopped at the red light.","example2":"Viele Autofahrerinnen nutzen jetzt ein Navigationsgerät.","example2En":"Many female drivers now use a navigation device."},{"de":"die Automarke","en":"car brand","pos":"noun","plural":"die Automarken","meanings":[{"en":"brand/make of a car","de":"Hersteller eines Autos"}],"rule":"compound: Auto + Marke.","example":"Welche Automarke findest du am zuverlässigsten?","exampleEn":"Which car brand do you find the most reliable?","example2":"BMW und Audi sind bekannte deutsche Automarken.","example2En":"BMW and Audi are well-known German car brands."},{"de":"das Autorennen","en":"car race","pos":"noun","plural":"die Autorennen","meanings":[{"en":"motor race, car racing event","de":"ein Wettbewerb, bei dem Autos möglichst schnell fahren"}],"rule":"compound: Auto + Rennen (neuter, follows das Rennen).","example":"Am Sonntag schauen wir uns das Autorennen im Fernsehen an.","exampleEn":"On Sunday we're watching the car race on TV.","example2":"Das Autorennen wurde wegen Regen verschoben.","example2En":"The car race was postponed because of rain."},{"de":"das Autoteil","en":"car part","pos":"noun","plural":"die Autoteile","meanings":[{"en":"component of a car","de":"ein Teil eines Autos"}],"rule":"compound: Auto + Teil (neuter, follows das Teil).","example":"Wir bestellen die Autoteile online.","exampleEn":"We order the car parts online.","example2":"Der Mechaniker musste ein defektes Autoteil austauschen.","example2En":"The mechanic had to replace a defective car part."},{"de":"die Autoversicherung","en":"car insurance","pos":"noun","plural":"die Autoversicherungen","meanings":[{"en":"insurance policy for a car","de":"Versicherung für ein Auto"}],"rule":"Compound noun: Auto + Versicherung; takes the article of Versicherung (die).","example":"Die Autoversicherung kostet jedes Jahr mehr.","exampleEn":"The car insurance costs more every year.","example2":"Ohne Autoversicherung darfst du nicht fahren.","example2En":"You are not allowed to drive without car insurance."},{"de":"der Bachelor","en":"bachelor's degree","pos":"noun","plural":"die Bachelors","meanings":[{"en":"first academic degree at university","de":"erster akademischer Abschluss"}],"rule":"Plural is 'die Bachelors' (English-style -s plural, as in Duden); no article change, always der Bachelor.","example":"Sie hat ihren Bachelor in Biologie gemacht.","exampleEn":"She got her bachelor's degree in biology.","example2":"Nach dem Bachelor will er einen Master machen.","example2En":"After the bachelor's degree he wants to do a master's."},{"de":"das Balkongeländer","en":"balcony railing","pos":"noun","plural":"die Balkongeländer","meanings":[{"en":"railing around a balcony","de":"Geländer um einen Balkon"}],"rule":"Compound: Balkon + Geländer; neuter like Geländer.","example":"Das Balkongeländer ist ganz rostig.","exampleEn":"The balcony railing is completely rusty.","example2":"Bitte lehn dich nicht so weit über das Balkongeländer.","example2En":"Please don't lean so far over the balcony railing."},{"de":"der Bankeinzug","en":"direct debit / bank withdrawal","pos":"noun","plural":"die Bankeinzüge","meanings":[{"en":"automatic payment taken from a bank account","de":"automatische Abbuchung vom Konto"}],"rule":"Compound: Bank + Einzug; often used as 'per Bankeinzug bezahlen'.","example":"Ich bezahle meine Miete per Bankeinzug.","exampleEn":"I pay my rent by direct debit.","example2":"Der Bankeinzug erfolgt jeweils am Monatsersten.","example2En":"The direct debit takes place on the first of every month."},{"de":"die Bearbeitung","en":"processing; editing","pos":"noun","plural":"die Bearbeitungen","meanings":[{"en":"processing of a request/document","de":"das Bearbeiten eines Antrags o. Ä."},{"en":"editing/adaptation of a text or work","de":"das Überarbeiten eines Textes/Werkes"}],"rule":"Noun from the verb bearbeiten; often in 'in Bearbeitung' (being processed).","example":"Ihr Antrag ist noch in Bearbeitung.","exampleEn":"Your application is still being processed.","example2":"Das Buch ist eine Bearbeitung des Originaltextes.","example2En":"The book is an adaptation of the original text."},{"de":"bedenklich","en":"worrying, questionable","pos":"adjective","plural":"","meanings":[{"en":"causing concern or doubt","de":"besorgniserregend, fragwürdig"}],"rule":"Regular comparison: bedenklich, bedenklicher, am bedenklichsten.","example":"Sein Gesundheitszustand ist bedenklich.","exampleEn":"His state of health is worrying.","example2":"Ich finde diese Entwicklung bedenklich.","example2En":"I find this development questionable."},{"de":"die Bedingung","en":"condition","pos":"noun","plural":"die Bedingungen","meanings":[{"en":"requirement that must be fulfilled","de":"Voraussetzung, die erfüllt werden muss"},{"en":"(often plural) circumstances","de":"Umstände, z. B. Arbeitsbedingungen"}],"rule":"Common phrase: unter der Bedingung, dass ...","example":"Eine Bedingung für den Job ist gutes Englisch.","exampleEn":"A condition for the job is good English.","example2":"Die Arbeitsbedingungen in der Firma sind gut.","example2En":"The working conditions at the company are good."},{"de":"befestigen","en":"to fasten, attach","pos":"verb","plural":"","meanings":[{"en":"to fix something firmly in place","de":"etwas fest anbringen"}],"rule":"Regular weak verb: befestigt, befestigte, hat befestigt; often + an/auf + Dativ.","example":"Er befestigt das Regal an der Wand.","exampleEn":"He attaches the shelf to the wall.","example2":"Die Schrauben befestigen das Schild sicher.","example2En":"The screws fasten the sign securely."},{"de":"befragen","en":"to question, interview, survey","pos":"verb","plural":"","meanings":[{"en":"to ask someone questions, especially formally","de":"jemandem Fragen stellen, z. B. bei einer Umfrage"}],"rule":"Regular weak verb: befragt, befragte, hat befragt; + Akkusativ (jemanden befragen).","example":"Die Forscher befragten 500 Personen.","exampleEn":"The researchers surveyed 500 people.","example2":"Die Polizei hat den Zeugen befragt.","example2En":"The police questioned the witness."},{"de":"begeistern","en":"to enthuse, thrill","pos":"verb","plural":"","meanings":[{"en":"to fill someone with enthusiasm","de":"jemanden sehr erfreuen, mitreißen"},{"en":"sich begeistern (für) = to be enthusiastic about","de":"sich für etwas sehr interessieren"}],"rule":"Regular weak verb: begeistert, begeisterte, hat begeistert; often reflexive: sich begeistern für + Akkusativ.","example":"Der Film hat alle Zuschauer begeistert.","exampleEn":"The film thrilled all the viewers.","example2":"Sie begeistert sich schon lange für Musik.","example2En":"She has been enthusiastic about music for a long time."},{"de":"beglaubigen","en":"to certify, authenticate","pos":"verb","plural":"","meanings":[{"en":"to officially confirm a document is genuine/a correct copy","de":"amtlich bestätigen, dass etwas echt/korrekt ist"}],"rule":"Regular weak verb: beglaubigt, beglaubigte, hat beglaubigt; often with 'lassen': eine Kopie beglaubigen lassen (have a copy certified).","example":"Ich musste meine Kopie beim Amt beglaubigen lassen.","exampleEn":"I had to get my copy certified at the office.","example2":"Ein Notar beglaubigt das Dokument.","example2En":"A notary certifies the document."},{"de":"die Beglaubigung","en":"certification, authentication","pos":"noun","plural":"die Beglaubigungen","meanings":[{"en":"official confirmation that a document is genuine/correct","de":"amtliche Bestätigung der Echtheit eines Dokuments"}],"rule":"Noun from beglaubigen; often 'eine Beglaubigung brauchen/beantragen'.","example":"Für den Antrag brauchen Sie eine Beglaubigung.","exampleEn":"For the application you need a certification.","example2":"Die Beglaubigung kostet zehn Euro.","example2En":"The certification costs ten euros."},{"de":"die Begleitperson","en":"companion, escort","pos":"noun","plural":"die Begleitpersonen","meanings":[{"en":"a person who accompanies someone else","de":"eine Person, die jemanden begleitet"}],"rule":"Compound: Begleit- + Person; used e.g. in tickets/appointments for someone accompanying a person.","example":"Kinder brauchen für die Fahrt eine Begleitperson.","exampleEn":"Children need a companion for the trip.","example2":"Er durfte eine Begleitperson zum Arzttermin mitbringen.","example2En":"He was allowed to bring a companion to the doctor's appointment."},{"de":"behalten","en":"to keep","pos":"verb","plural":"","meanings":[{"en":"to keep, retain something","de":"etwas nicht weggeben, bei sich behalten"},{"en":"to keep in mind/memory","de":"sich an etwas erinnern"}],"rule":"Irregular: er behält, behielt, hat behalten (no 'ge-' prefix since be- is inseparable).","example":"Du kannst den Stift behalten.","exampleEn":"You can keep the pen.","example2":"Ich kann mir seinen Namen einfach nicht behalten.","example2En":"I simply cannot remember his name."},{"de":"der Behälter","en":"container","pos":"noun","plural":"die Behälter","meanings":[{"en":"a container for holding things","de":"Gefäß zum Aufbewahren von Dingen"}],"rule":"Plural unchanged: der Behälter, die Behälter.","example":"Der Behälter ist voller Wasser.","exampleEn":"The container is full of water.","example2":"Wirf die Batterien in den Behälter.","example2En":"Throw the batteries into the container."},{"de":"behaupten","en":"to claim, assert","pos":"verb","plural":"","meanings":[{"en":"to state something as true (often disputable)","de":"etwas als wahr darstellen, ohne Beweis"},{"en":"sich behaupten = to assert/hold one's own","de":"sich durchsetzen, standhalten"}],"rule":"Regular weak verb: behauptet, behauptete, hat behauptet.","example":"Er behauptet, dass er nichts wusste.","exampleEn":"He claims he knew nothing.","example2":"Die Firma konnte sich am Markt behaupten.","example2En":"The company managed to hold its own in the market."},{"de":"beherrschen","en":"to master, control","pos":"verb","plural":"","meanings":[{"en":"to have mastered a skill or language","de":"etwas sehr gut können"},{"en":"to control/dominate","de":"kontrollieren, dominieren"}],"rule":"Regular weak verb: beherrscht, beherrschte, hat beherrscht; sich beherrschen = to control oneself.","example":"Sie beherrscht drei Fremdsprachen.","exampleEn":"She has mastered three foreign languages.","example2":"Er konnte sich vor Wut kaum beherrschen.","example2En":"He could hardly control himself out of anger."},{"de":"beilegen","en":"to enclose; to settle","pos":"verb","plural":"","meanings":[{"en":"to enclose something with a letter/document","de":"etwas einem Brief/Dokument hinzufügen"},{"en":"to settle a dispute","de":"einen Streit beenden"}],"rule":"Trennbar: legt bei, legte bei, hat beigelegt.","example":"Bitte legen Sie eine Kopie Ihres Ausweises bei.","exampleEn":"Please enclose a copy of your ID.","example2":"Die beiden Firmen haben den Streit beigelegt.","example2En":"The two companies settled the dispute."},{"de":"belasten","en":"to burden; to strain","pos":"verb","plural":"","meanings":[{"en":"to put a physical or financial load on something","de":"eine Last auf etwas legen (z.B. Konto)"},{"en":"to cause emotional/mental strain","de":"psychisch oder emotional schwer machen"}],"rule":"regelmäßig: belastet, belastete, hat belastet. Oft mit Akkusativ: jemanden/etwas belasten.","example":"Die hohen Kosten belasten unser Budget stark.","exampleEn":"The high costs put a heavy strain on our budget.","example2":"Der Streit mit ihrer Familie belastet sie sehr.","example2En":"The argument with her family weighs heavily on her."},{"de":"die Belastung","en":"burden; strain; load","pos":"noun","plural":"die Belastungen","meanings":[{"en":"a physical or financial load","de":"eine Last, z.B. finanziell"},{"en":"emotional or mental stress","de":"psychischer Druck"}],"rule":"Nomen zu 'belasten'; oft mit Genitiv oder 'für': die Belastung für die Familie.","example":"Die finanzielle Belastung durch die Miete ist hoch.","exampleEn":"The financial burden of the rent is high.","example2":"Die Prüfungen waren eine große Belastung für sie.","example2En":"The exams were a great strain for her."},{"de":"beleidigen","en":"to insult","pos":"verb","plural":"","meanings":[{"en":"to say something offensive to someone","de":"jemanden verbal verletzen"}],"rule":"regelmäßig: beleidigt, beleidigte, hat beleidigt. + Akkusativ: jemanden beleidigen.","example":"Er hat seinen Kollegen vor allen beleidigt.","exampleEn":"He insulted his colleague in front of everyone.","example2":"Ich wollte dich nicht beleidigen, das tut mir leid.","example2En":"I didn't mean to insult you, I'm sorry."},{"de":"die Beleidigung","en":"insult","pos":"noun","plural":"die Beleidigungen","meanings":[{"en":"an offensive remark or act","de":"eine verletzende Äußerung"}],"rule":"Nomen zu 'beleidigen'; kann auch juristischer Begriff sein (Straftat).","example":"Das war eine klare Beleidigung.","exampleEn":"That was a clear insult.","example2":"Er hat ihn wegen Beleidigung angezeigt.","example2En":"He reported him to the police for insult, a criminal offense in Germany."},{"de":"beliebt","en":"popular","pos":"adjective","plural":"","meanings":[{"en":"liked by many people","de":"von vielen Leuten gemocht"}],"rule":"+ bei: beliebt bei den Kollegen. Komparation regelmäßig: beliebter, am beliebtesten.","example":"Sie ist bei ihren Schülern sehr beliebt.","exampleEn":"She is very popular with her students.","example2":"Dieses Restaurant ist sehr beliebt.","example2En":"This restaurant is very popular."},{"de":"benötigen","en":"to need; to require","pos":"verb","plural":"","meanings":[{"en":"to need something","de":"etwas brauchen"}],"rule":"regelmäßig: benötigt, benötigte, hat benötigt. formeller als 'brauchen', + Akkusativ.","example":"Für den Antrag benötigen Sie Ihren Personalausweis.","exampleEn":"For the application you need your ID card.","example2":"Wir benötigen mehr Zeit für das Projekt.","example2En":"We need more time for the project."},{"de":"das Benzin","en":"petrol; gasoline","pos":"noun","plural":"","meanings":[{"en":"fuel used for cars","de":"Kraftstoff für Autos"}],"rule":"unzählbar, kein Plural.","example":"Das Auto braucht bald Benzin.","exampleEn":"The car needs petrol soon.","example2":"Benzin ist in letzter Zeit teurer geworden.","example2En":"Petrol has become more expensive recently."},{"de":"beobachten","en":"to observe; to watch","pos":"verb","plural":"","meanings":[{"en":"to watch someone/something carefully over time","de":"aufmerksam anschauen"}],"rule":"regelmäßig: beobachtet, beobachtete, hat beobachtet. + Akkusativ.","example":"Die Polizei hat das Haus tagelang beobachtet.","exampleEn":"The police observed the house for days.","example2":"Ich habe beobachtet, dass er sich verändert hat.","example2En":"I have observed that he has changed."},{"de":"berechtigt","en":"justified; entitled","pos":"adjective","plural":"","meanings":[{"en":"having the right to do something","de":"ein Recht auf etwas habend"},{"en":"justified, valid (of a claim/criticism)","de":"gerechtfertigt, begründet"}],"rule":"oft mit 'zu': berechtigt zu etwas; Partizip von 'berechtigen'.","example":"Nur Mitarbeiter sind berechtigt, den Raum zu betreten.","exampleEn":"Only employees are entitled to enter the room.","example2":"Seine Kritik war völlig berechtigt.","example2En":"His criticism was entirely justified."},{"de":"bereits","en":"already","pos":"adverb","plural":"","meanings":[{"en":"already (by this time)","de":"schon"}],"rule":"Synonym für 'schon', etwas formeller, oft in schriftlicher Sprache.","example":"Er ist bereits um sechs Uhr aufgestanden.","exampleEn":"He already got up at six o'clock.","example2":"Wir haben die Tickets bereits gekauft.","example2En":"We have already bought the tickets."},{"de":"berufen","en":"to appoint; to cite/refer to","pos":"verb","plural":"","meanings":[{"en":"to appoint someone to a position","de":"jemanden in ein Amt einsetzen"},{"en":"sich berufen auf: to refer to/invoke something","de":"sich auf etwas beziehen"}],"rule":"unregelmäßig: beruft, berief, hat berufen. Reflexiv: sich berufen auf + Akkusativ.","example":"Sie wurde zur Professorin berufen.","exampleEn":"She was appointed professor.","example2":"Er berief sich auf seine Rechte.","example2En":"He invoked his rights."},{"de":"die Berufsbezeichnung","en":"job title","pos":"noun","plural":"die Berufsbezeichnungen","meanings":[{"en":"official name of a profession","de":"offizieller Name eines Berufs"}],"rule":"Kompositum: der Beruf + die Bezeichnung.","example":"Ingenieur ist eine geschützte Berufsbezeichnung.","exampleEn":"Engineer is a protected job title.","example2":"Welche Berufsbezeichnung steht auf deiner Visitenkarte?","example2En":"Which job title is on your business card?"},{"de":"die Berufserfahrung","en":"work experience","pos":"noun","plural":"die Berufserfahrungen","meanings":[{"en":"practical experience gained in a job","de":"praktische Erfahrung im Beruf"}],"rule":"Kompositum: der Beruf + die Erfahrung; oft im Singular verwendet.","example":"Für diese Stelle brauchen Sie mindestens drei Jahre Berufserfahrung.","exampleEn":"For this position you need at least three years of work experience.","example2":"Sie hat viel Berufserfahrung im Marketing.","example2En":"She has a lot of work experience in marketing."},{"de":"das Berufsleben","en":"working life","pos":"noun","plural":"","meanings":[{"en":"the period/context of one's professional career","de":"die Zeit, in der man arbeitet"}],"rule":"Kompositum: der Beruf + das Leben; meist Singular, kein Plural.","example":"Nach dem Studium beginnt das Berufsleben.","exampleEn":"After graduation, working life begins.","example2":"Sie ist seit zehn Jahren im Berufsleben.","example2En":"She has been in working life for ten years."},{"de":"die Berufstätigkeit","en":"employment; professional activity","pos":"noun","plural":"die Berufstätigkeiten","meanings":[{"en":"the fact/state of being employed","de":"das Ausüben eines Berufs"}],"rule":"Kompositum: der Beruf + die Tätigkeit; oft Singular.","example":"Neben ihrer Berufstätigkeit studiert sie abends.","exampleEn":"Besides her job, she studies in the evenings.","example2":"Die Berufstätigkeit von Frauen ist heute selbstverständlich.","example2En":"Women's employment is taken for granted today."},{"de":"die Besatzungszone","en":"occupation zone","pos":"noun","plural":"die Besatzungszonen","meanings":[{"en":"a territory controlled by occupying forces (historical, e.g. post-WWII Germany)","de":"ein von Besatzungsmächten kontrolliertes Gebiet"}],"rule":"Kompositum: die Besatzung + die Zone; historischer Begriff (Nachkriegsdeutschland 1945-1949).","example":"Nach 1945 wurde Deutschland in vier Besatzungszonen geteilt.","exampleEn":"After 1945 Germany was divided into four occupation zones.","example2":"Die amerikanische Besatzungszone lag im Süden.","example2En":"The American occupation zone was in the south."},{"de":"beschädigen","en":"to damage","pos":"verb","plural":"","meanings":[{"en":"to cause physical damage to an object","de":"etwas kaputt machen"}],"rule":"regelmäßig: beschädigt, beschädigte, hat beschädigt. + Akkusativ.","example":"Beim Transport wurde das Paket beschädigt.","exampleEn":"The package was damaged during transport.","example2":"Der Sturm hat das Dach beschädigt.","example2En":"The storm damaged the roof."},{"de":"beschädigt","en":"damaged","pos":"adjective","plural":"","meanings":[{"en":"damaged, broken","de":"kaputt, mit Schaden"}],"rule":"Partizip II von 'beschädigen'; wird oft als Adjektiv vor Nomen benutzt (das beschädigte Auto).","example":"Das Paket kam beschädigt an.","exampleEn":"The package arrived damaged.","example2":"Sie hat einen beschädigten Koffer bekommen.","example2En":"She got a damaged suitcase."},{"de":"bescheinigen","en":"to certify, to confirm in writing","pos":"verb","plural":"","meanings":[{"en":"to confirm/certify officially","de":"schriftlich bestätigen"}],"rule":"regelmäßig; bescheinigt, bescheinigte, hat bescheinigt; + Dativ (Person) + Akkusativ (Sache) – jemandem etwas bescheinigen (z. B. 'Der Arzt bescheinigt ihm die Krankheit.').","example":"Der Arzt bescheinigt ihm die Krankheit.","exampleEn":"The doctor certifies his illness.","example2":"Die Firma bescheinigt den Erhalt der Zahlung.","example2En":"The company confirms receipt of the payment."},{"de":"beschimpfen","en":"to insult, to verbally abuse","pos":"verb","plural":"","meanings":[{"en":"to call someone bad names","de":"jemanden böse Wörter nennen"}],"rule":"regelmäßig; beschimpft, beschimpfte, hat beschimpft; + Akkusativ","example":"Er hat seinen Nachbarn beschimpft.","exampleEn":"He insulted his neighbor.","example2":"Bitte beschimpf mich nicht so!","example2En":"Please don't insult me like that!"},{"de":"die Beschimpfung","en":"insult, verbal abuse","pos":"noun","plural":"die Beschimpfungen","meanings":[{"en":"an insulting remark or act","de":"böse Äußerung, Beleidigung"}],"rule":"Nomen von 'beschimpfen'; oft im Plural für mehrere Beleidigungen benutzt.","example":"Die Beschimpfung des Kollegen war nicht in Ordnung.","exampleEn":"The insulting of the colleague was not okay.","example2":"Bei dem Streit gab es viele Beschimpfungen.","example2En":"There were many insults during the argument."},{"de":"beschweren","en":"to complain; to weigh down","pos":"verb","plural":"","meanings":[{"en":"(sich beschweren) to complain","de":"sich reflexiv: Kritik äußern"},{"en":"to weigh down, make heavy","de":"schwer machen"}],"rule":"regelmäßig; beschwert, beschwerte, hat beschwert; 'sich beschweren' + über + Akkusativ (reflexiv)","example":"Sie hat sich über den Lärm beschwert.","exampleEn":"She complained about the noise.","example2":"Steine beschweren das Zelt bei Wind.","example2En":"Stones weigh down the tent in the wind."},{"de":"besiegen","en":"to defeat, to beat","pos":"verb","plural":"","meanings":[{"en":"to win against someone","de":"jemanden im Wettkampf/Krieg schlagen"},{"en":"to overcome (a feeling, difficulty)","de":"etwas überwinden (z. B. eine Angst)"}],"rule":"regelmäßig; besiegt, besiegte, hat besiegt; + Akkusativ","example":"Unsere Mannschaft hat das andere Team besiegt.","exampleEn":"Our team defeated the other team.","example2":"Er wollte seine Angst besiegen.","example2En":"He wanted to overcome his fear."},{"de":"das Besprechungszimmer","en":"meeting room","pos":"noun","plural":"die Besprechungszimmer","meanings":[{"en":"room used for meetings","de":"Raum für Besprechungen"}],"rule":"Kompositum aus 'Besprechung' + 'Zimmer' (mit Fugen-s); sächlich wie 'das Zimmer'.","example":"Das Meeting findet im Besprechungszimmer statt.","exampleEn":"The meeting takes place in the meeting room.","example2":"Können Sie das Besprechungszimmer reservieren?","example2En":"Can you reserve the meeting room?"},{"de":"die Bestellhotline","en":"order hotline, phone ordering line","pos":"noun","plural":"die Bestellhotlines","meanings":[{"en":"phone number for placing orders","de":"Telefonnummer zum Bestellen"}],"rule":"Kompositum aus dem Verbstamm 'bestell-' (von 'bestellen') + 'Hotline'; weiblich wie 'die Hotline'.","example":"Rufen Sie unsere Bestellhotline an, um zu bestellen.","exampleEn":"Call our order hotline to place an order.","example2":"Die Bestellhotline ist von 8 bis 18 Uhr erreichbar.","example2En":"The order hotline is available from 8 am to 6 pm."},{"de":"der Betrag","en":"amount (of money)","pos":"noun","plural":"die Beträge","meanings":[{"en":"a sum of money","de":"eine Geldsumme"}],"rule":"maskulin; Plural mit Umlaut: die Beträge.","example":"Bitte überweisen Sie den Betrag bis Freitag.","exampleEn":"Please transfer the amount by Friday.","example2":"Der Betrag auf der Rechnung ist falsch.","example2En":"The amount on the invoice is wrong."}]},{"id":"b1-04","title":"B1 · B–D (4)","level":"B1","words":[{"de":"betreten","en":"to enter, to step onto","pos":"verb","plural":"","meanings":[{"en":"to walk into / step onto a place","de":"einen Ort betreten, hineingehen"}],"rule":"unregelmäßig; betritt, betrat, hat betreten; + Akkusativ; untrennbares Präfix 'be-', deshalb kein 'ge-' im Partizip II (hat betreten, nicht 'gebetreten').","example":"Bitte den Rasen nicht betreten!","exampleEn":"Please do not step on the lawn!","example2":"Er betrat vorsichtig das dunkle Zimmer.","example2En":"He carefully entered the dark room."},{"de":"die Betriebswirtschaft","en":"business administration/economics","pos":"noun","plural":"","meanings":[{"en":"academic field of business management","de":"Wissenschaft der Unternehmensführung"}],"rule":"weiblich; meist unzählbar, kein Plural; oft abgekürzt BWL.","example":"Sie studiert Betriebswirtschaft an der Uni.","exampleEn":"She studies business administration at university.","example2":"Er hat einen Abschluss in Betriebswirtschaft.","example2En":"He has a degree in business administration."},{"de":"betrunken","en":"drunk","pos":"adjective","plural":"","meanings":[{"en":"intoxicated by alcohol","de":"vom Alkohol berauscht"}],"rule":"Partizip II von 'sich betrinken'; wird als Adjektiv verwendet, Steigerung mit -er/-sten selten gebraucht.","example":"Er war zu betrunken zum Autofahren.","exampleEn":"He was too drunk to drive.","example2":"Auf der Party waren viele Leute betrunken.","example2En":"Many people were drunk at the party."},{"de":"beurteilen","en":"to judge, to assess","pos":"verb","plural":"","meanings":[{"en":"to evaluate or form an opinion about something","de":"über etwas ein Urteil bilden"}],"rule":"regelmäßig; beurteilt, beurteilte, hat beurteilt; + Akkusativ; untrennbar.","example":"Der Chef beurteilt die Arbeit der Mitarbeiter.","exampleEn":"The boss evaluates the employees' work.","example2":"Man sollte einen Menschen nicht nach dem ersten Eindruck beurteilen.","example2En":"One shouldn't judge a person by the first impression."},{"de":"der Beutel","en":"bag, pouch","pos":"noun","plural":"die Beutel","meanings":[{"en":"a small bag or pouch","de":"kleiner Sack, Tüte"}],"rule":"maskulin; Plural ohne Endung: die Beutel.","example":"Sie packt die Äpfel in einen Beutel.","exampleEn":"She puts the apples in a bag.","example2":"Der Kaffee ist als Beutel erhältlich.","example2En":"The coffee is available as a bag (sachet)."},{"de":"die Bevölkerung","en":"population","pos":"noun","plural":"die Bevölkerungen","meanings":[{"en":"the people living in a place","de":"die Einwohner eines Landes/Gebiets"}],"rule":"weiblich; meist Singular benutzt, Plural selten (für verschiedene Bevölkerungen/Länder).","example":"Die Bevölkerung der Stadt wächst schnell.","exampleEn":"The city's population is growing fast.","example2":"Ein großer Teil der Bevölkerung ist dagegen.","example2En":"A large part of the population is against it."},{"de":"das Bewerbungsschreiben","en":"cover letter, application letter","pos":"noun","plural":"die Bewerbungsschreiben","meanings":[{"en":"written letter accompanying a job application","de":"schriftliche Bewerbung um eine Stelle"}],"rule":"Kompositum aus 'Bewerbung' + 'Schreiben' (mit Fugen-s); sächlich; Plural ohne Endung.","example":"Er schreibt ein Bewerbungsschreiben für die Stelle.","exampleEn":"He writes a cover letter for the position.","example2":"Das Bewerbungsschreiben sollte kurz und klar sein.","example2En":"The cover letter should be short and clear."},{"de":"der Bewohner / die Bewohnerin","en":"resident, inhabitant","pos":"noun","plural":"die Bewohner / die Bewohnerinnen","meanings":[{"en":"a person who lives in a place","de":"eine Person, die an einem Ort wohnt"}],"rule":"maskulin/feminin; Plural: die Bewohner / die Bewohnerinnen; von 'bewohnen' abgeleitet.","example":"Die Bewohner des Hauses beschweren sich über den Lärm.","exampleEn":"The residents of the building are complaining about the noise.","example2":"Die neue Bewohnerin hat sich noch nicht vorgestellt.","example2En":"The new resident hasn't introduced herself yet."},{"de":"bewusst","en":"conscious, aware; deliberate","pos":"adjective","plural":"","meanings":[{"en":"aware of something","de":"sich einer Sache klar sein"},{"en":"deliberate, intentional","de":"absichtlich"}],"rule":"regelmäßige Steigerung: bewusst, bewusster, am bewusstesten; oft mit 'sich etwas bewusst sein' (Dativ der Person + Genitiv der Sache, umgangssprachlich auch + Akk.)","example":"Mir ist bewusst, dass ich einen Fehler gemacht habe.","exampleEn":"I am aware that I made a mistake.","example2":"Er hat die Frage bewusst nicht beantwortet.","example2En":"He deliberately did not answer the question."},{"de":"der Bezahlvorgang","en":"payment process","pos":"noun","plural":"die Bezahlvorgänge","meanings":[{"en":"the process of paying (e.g. online or at a till)","de":"der Vorgang, bei dem man bezahlt"}],"rule":"Compound noun: bezahlen + Vorgang; takes the gender of Vorgang (der).","example":"Der Bezahlvorgang im Online-Shop dauert nur wenige Sekunden.","exampleEn":"The payment process in the online shop only takes a few seconds.","example2":"Bitte schließen Sie den Bezahlvorgang an der Kasse ab.","example2En":"Please complete the payment process at the checkout."},{"de":"der Biergarten","en":"beer garden","pos":"noun","plural":"die Biergärten","meanings":[{"en":"an outdoor area, typically with tables under trees, where beer and food are served","de":"ein Freiluftlokal, in dem man Bier trinkt"}],"rule":"Compound: Bier + Garten; plural umlauts like Garten → Gärten.","example":"Im Sommer treffen wir uns oft im Biergarten.","exampleEn":"In summer we often meet at the beer garden.","example2":"Der Biergarten hat heute bis 23 Uhr geöffnet.","example2En":"The beer garden is open until 11 p.m. today."},{"de":"der Bilanzbuchhalter / die Bilanzbuchhalterin","en":"certified accountant; balance sheet accountant","pos":"noun","plural":"die Bilanzbuchhalter/innen","meanings":[{"en":"a qualified accountant who prepares financial statements/balance sheets","de":"ein Fachmann/eine Fachfrau, der/die Bilanzen erstellt"}],"rule":"Compound: Bilanz + Buchhalter; feminine form adds -in.","example":"Der Bilanzbuchhalter prüft am Jahresende alle Zahlen.","exampleEn":"The accountant checks all the figures at the end of the year.","example2":"Sie arbeitet als Bilanzbuchhalterin in einer großen Firma.","example2En":"She works as an accountant at a large company."},{"de":"bio","en":"organic","pos":"adjective","plural":"","meanings":[{"en":"organic, produced without artificial chemicals","de":"biologisch angebaut oder hergestellt"}],"rule":"Indeclinable colloquial short form of 'biologisch'; often used as an adjective before nouns: Bio-Gemüse.","example":"Kaufst du das Gemüse bio oder normal?","exampleEn":"Do you buy the vegetables organic or regular?","example2":"Das Brot hier ist alles bio.","example2En":"The bread here is all organic."},{"de":"biologisch","en":"biological; organic","pos":"adjective","plural":"","meanings":[{"en":"relating to biology","de":"die Biologie betreffend"},{"en":"organically grown/produced","de":"ohne künstliche Chemikalien hergestellt"}],"rule":"Regular comparison: biologisch, biologischer, am biologischsten (rarely compared in practice).","example":"Im Unterricht lernen wir den biologischen Aufbau der Zelle.","exampleEn":"In class we're learning about the biological structure of the cell.","example2":"Wir kaufen nur biologisches Obst.","example2En":"We only buy organic fruit."},{"de":"das Bioprodukt","en":"organic product","pos":"noun","plural":"die Bioprodukte","meanings":[{"en":"a food or item produced organically","de":"ein biologisch hergestelltes Produkt"}],"rule":"Compound: Bio + Produkt; neuter like Produkt.","example":"Bioprodukte sind im Supermarkt oft teurer.","exampleEn":"Organic products are often more expensive at the supermarket.","example2":"Sie kauft nur Bioprodukte aus der Region.","example2En":"She only buys organic products from the region."},{"de":"bisher","en":"so far, until now","pos":"adverb","plural":"","meanings":[{"en":"up to the present time","de":"bis zum jetzigen Zeitpunkt"}],"rule":"Often combined with Perfekt or Präsens; synonym: bis jetzt.","example":"Bisher hat mir das Restaurant gut gefallen.","exampleEn":"So far I've liked the restaurant.","example2":"Wir haben bisher keine Antwort bekommen.","example2En":"We haven't received an answer so far."},{"de":"der Blinker","en":"turn signal, indicator","pos":"noun","plural":"die Blinker","meanings":[{"en":"the light on a vehicle that signals a turn","de":"das Licht am Auto, das eine Richtungsänderung anzeigt"}],"rule":"From blinken (to flash); plural unchanged (der Blinker – die Blinker).","example":"Vergiss nicht, den Blinker zu setzen, bevor du abbiegst.","exampleEn":"Don't forget to use the turn signal before you turn.","example2":"Der Blinker am Auto ist kaputt.","example2En":"The car's turn signal is broken."},{"de":"bloß","en":"just, only; bare","pos":"adjective","plural":"","meanings":[{"en":"used as an intensifying particle meaning 'just/only' (often in questions or warnings)","de":"eine verstärkende Partikel, z. B. in Fragen"},{"en":"bare, mere","de":"nackt, unbedeckt"}],"rule":"As adjective: der bloße Gedanke (the mere thought); as particle it's uninflected and adds emphasis, e.g. in warnings: 'Mach das bloß nicht!'","example":"Was soll ich bloß tun?","exampleEn":"What on earth should I do?","example2":"Er stand mit bloßen Füßen im Gras.","example2En":"He stood barefoot in the grass."},{"de":"der Blumentopf","en":"flowerpot","pos":"noun","plural":"die Blumentöpfe","meanings":[{"en":"a container for growing a plant","de":"ein Gefäß, in dem eine Pflanze wächst"}],"rule":"Compound: Blume + Topf; plural umlauts like Topf → Töpfe.","example":"Sie stellt die Blumentöpfe auf den Balkon.","exampleEn":"She puts the flowerpots on the balcony.","example2":"Der Blumentopf ist beim Transport zerbrochen.","example2En":"The flowerpot broke during the move."},{"de":"bohren","en":"to drill","pos":"verb","plural":"","meanings":[{"en":"to make a hole using a drill or similar tool","de":"mit einem Werkzeug ein Loch machen"}],"rule":"Regular weak verb: bohrt, bohrte, hat gebohrt.","example":"Er bohrt ein Loch in die Wand.","exampleEn":"He's drilling a hole in the wall.","example2":"Der Zahnarzt musste leider bohren.","example2En":"Unfortunately the dentist had to drill."},{"de":"die Bordkarte","en":"boarding pass","pos":"noun","plural":"die Bordkarten","meanings":[{"en":"a document/ticket allowing boarding of a plane","de":"das Dokument, mit dem man ins Flugzeug einsteigen darf"}],"rule":"Compound: Bord + Karte; feminine like Karte.","example":"Zeigen Sie bitte Ihre Bordkarte am Gate.","exampleEn":"Please show your boarding pass at the gate.","example2":"Ich habe meine Bordkarte auf dem Handy gespeichert.","example2En":"I saved my boarding pass on my phone."},{"de":"das Boxen","en":"boxing","pos":"noun","plural":"","meanings":[{"en":"the sport of boxing","de":"der Kampfsport mit den Fäusten"}],"rule":"Substantivized infinitive of 'boxen'; neuter, uncountable, no plural.","example":"Boxen ist ein anstrengender Sport.","exampleEn":"Boxing is an exhausting sport.","example2":"Er geht zweimal pro Woche zum Boxen.","example2En":"He goes boxing twice a week."},{"de":"bremsen","en":"to brake","pos":"verb","plural":"","meanings":[{"en":"to slow down or stop a vehicle","de":"ein Fahrzeug langsamer machen oder anhalten"},{"en":"to slow down or hinder a process figuratively","de":"etwas verlangsamen oder hemmen"}],"rule":"Regular weak verb: bremst, bremste, hat gebremst.","example":"Der Fahrer musste plötzlich bremsen.","exampleEn":"The driver had to brake suddenly.","example2":"Die hohen Kosten bremsen das Wachstum der Firma.","example2En":"The high costs are slowing the company's growth."},{"de":"das Briefpapier","en":"stationery, letter paper","pos":"noun","plural":"","meanings":[{"en":"paper used for writing letters","de":"Papier, auf dem man Briefe schreibt"}],"rule":"Compound: Brief + Papier; neuter, uncountable, no plural.","example":"Sie schreibt den Brief auf schönem Briefpapier.","exampleEn":"She writes the letter on nice stationery.","example2":"Die Firma hat eigenes Briefpapier mit Logo.","example2En":"The company has its own letterhead with a logo."},{"de":"der Bundeskanzler / die Bundeskanzlerin","en":"federal chancellor","pos":"noun","plural":"die Bundeskanzler/innen","meanings":[{"en":"the head of government in Germany or Austria","de":"der Regierungschef/die Regierungschefin in Deutschland oder Österreich"}],"rule":"Compound: Bund(es) + Kanzler; feminine form adds -in.","example":"Der Bundeskanzler hält heute eine wichtige Rede.","exampleEn":"The federal chancellor is giving an important speech today.","example2":"Sie war die erste Bundeskanzlerin Deutschlands.","example2En":"She was Germany's first female chancellor."},{"de":"die Bundesrepublik (BRD)","en":"Federal Republic (of Germany)","pos":"noun","plural":"die Bundesrepubliken","meanings":[{"en":"the official name of the German state","de":"der offizielle Name des deutschen Staates"}],"rule":"Compound: Bund(es) + Republik; feminine like Republik; often used as 'die Bundesrepublik Deutschland'.","example":"Die Bundesrepublik Deutschland wurde 1949 gegründet.","exampleEn":"The Federal Republic of Germany was founded in 1949.","example2":"Er lebt seit zehn Jahren in der Bundesrepublik.","example2En":"He has lived in the Federal Republic for ten years."},{"de":"der Bürger / die Bürgerin","en":"citizen","pos":"noun","plural":"die Bürger/innen","meanings":[{"en":"a person who has legal rights and duties within a state or city","de":"eine Person mit Rechten und Pflichten in einem Staat oder einer Stadt"}],"rule":"Feminine form adds -in; related word: Bürgermeister (mayor).","example":"Jeder Bürger hat das Recht zu wählen.","exampleEn":"Every citizen has the right to vote.","example2":"Die Bürgerinnen und Bürger protestierten gegen die neue Regel.","example2En":"The citizens protested against the new rule."},{"de":"der Bürgerkrieg","en":"civil war","pos":"noun","plural":"die Bürgerkriege","meanings":[{"en":"civil war","de":"bewaffneter Konflikt innerhalb eines Landes"}],"rule":"Zusammensetzung aus 'Bürger' + 'Krieg'; maskulin wie 'der Krieg'.","example":"In dem Land herrscht seit Jahren Bürgerkrieg.","exampleEn":"There has been civil war in the country for years.","example2":"Viele Menschen sind wegen des Bürgerkriegs geflohen.","example2En":"Many people fled because of the civil war."},{"de":"der Büroalltag","en":"everyday office life","pos":"noun","plural":"","meanings":[{"en":"everyday routine in an office","de":"typischer Arbeitstag im Büro"}],"rule":"Zusammensetzung 'Büro' + 'Alltag'; meist ohne Plural verwendet.","example":"Der Büroalltag ist oft stressig.","exampleEn":"Everyday office life is often stressful.","example2":"Sie beschreibt ihren typischen Büroalltag.","example2En":"She describes her typical office routine."},{"de":"der Büroassistent / die Büroassistentin","en":"office assistant","pos":"noun","plural":"die Büroassistenten / die Büroassistentinnen","meanings":[{"en":"person assisting with office tasks","de":"Person, die im Büro unterstützende Aufgaben erledigt"}],"rule":"Maskuline Form auf -ent, feminine Form mit -in.","example":"Der Büroassistent kümmert sich um die Post.","exampleEn":"The office assistant takes care of the mail.","example2":"Sie arbeitet als Büroassistentin in einer Anwaltskanzlei.","example2En":"She works as an office assistant at a law firm."},{"de":"das Büromaterial","en":"office supplies","pos":"noun","plural":"die Büromaterialien","meanings":[{"en":"supplies used in an office (paper, pens, etc.)","de":"Dinge, die man im Büro braucht, z. B. Papier, Stifte"}],"rule":"Meist im Singular als Sammelbegriff verwendet; sächlich wie 'das Material'.","example":"Wir müssen neues Büromaterial bestellen.","exampleEn":"We need to order new office supplies.","example2":"Das Büromaterial liegt im Schrank.","example2En":"The office supplies are in the cabinet."},{"de":"der Büroraum","en":"office room","pos":"noun","plural":"die Büroräume","meanings":[{"en":"a room used as an office","de":"Raum, der als Büro genutzt wird"}],"rule":"Zusammensetzung 'Büro' + 'Raum'; maskulin wie 'der Raum'.","example":"Der Büroraum ist klein, aber hell.","exampleEn":"The office room is small but bright.","example2":"Wir suchen einen neuen Büroraum für die Firma.","example2En":"We are looking for a new office space for the company."},{"de":"die Bürozeit","en":"office hours","pos":"noun","plural":"die Bürozeiten","meanings":[{"en":"hours during which an office is open","de":"Zeit, in der ein Büro geöffnet ist"}],"rule":"Meist im Plural 'die Bürozeiten' verwendet.","example":"Die Bürozeiten sind von 9 bis 17 Uhr.","exampleEn":"Office hours are from 9 to 5.","example2":"Außerhalb der Bürozeit erreichen Sie uns nicht.","example2En":"You cannot reach us outside office hours."},{"de":"das Callcenter","en":"call center","pos":"noun","plural":"die Callcenter","meanings":[{"en":"office handling telephone calls (service/sales)","de":"Büro, in dem Telefonanrufe bearbeitet werden"}],"rule":"Englisches Lehnwort, sächlich; Plural bleibt oft unverändert.","example":"Er arbeitet in einem Callcenter für Kundenservice.","exampleEn":"He works at a call center for customer service.","example2":"Das Callcenter ist rund um die Uhr erreichbar.","example2En":"The call center is reachable around the clock."},{"de":"der Camper / die Camperin","en":"camper (person)","pos":"noun","plural":"die Camper / die Camperinnen","meanings":[{"en":"a person who goes camping","de":"Person, die campt"}],"rule":"Maskulin auf -er, feminin mit -in; nicht zu verwechseln mit 'der Camper' (Wohnmobil), das ugs. auch vorkommt.","example":"Die Camper haben ihr Zelt am See aufgebaut.","exampleEn":"The campers set up their tent by the lake.","example2":"Als Camperin liebt sie das Leben in der Natur.","example2En":"As a camper, she loves life in nature."},{"de":"der Campingplatz","en":"campsite","pos":"noun","plural":"die Campingplätze","meanings":[{"en":"a site for camping","de":"Platz, auf dem man zelten oder campen kann"}],"rule":"Zusammensetzung 'Camping' + 'Platz'; maskulin wie 'der Platz'.","example":"Der Campingplatz liegt direkt am Meer.","exampleEn":"The campsite is right by the sea.","example2":"Wir haben einen Stellplatz auf dem Campingplatz reserviert.","example2En":"We reserved a spot at the campsite."},{"de":"das Catering","en":"catering","pos":"noun","plural":"","meanings":[{"en":"providing food and drinks for an event","de":"Lieferung von Speisen und Getränken für eine Veranstaltung"}],"rule":"Englisches Lehnwort, sächlich, unzählbar (kein Plural).","example":"Das Catering für die Hochzeit war hervorragend.","exampleEn":"The catering for the wedding was excellent.","example2":"Die Firma bietet Catering für Geschäftsessen an.","example2En":"The company offers catering for business dinners."},{"de":"der Check-in-Schalter","en":"check-in counter","pos":"noun","plural":"die Check-in-Schalter","meanings":[{"en":"counter at an airport for checking in","de":"Schalter am Flughafen für das Einchecken"}],"rule":"Zusammensetzung aus dem Lehnwort 'Check-in' + 'Schalter'; maskulin wie 'der Schalter'.","example":"Der Check-in-Schalter öffnet zwei Stunden vor dem Flug.","exampleEn":"The check-in counter opens two hours before the flight.","example2":"Wir standen lange am Check-in-Schalter.","example2En":"We stood at the check-in counter for a long time."},{"de":"die Chemikalie","en":"chemical (substance)","pos":"noun","plural":"die Chemikalien","meanings":[{"en":"a chemical substance","de":"chemischer Stoff"}],"rule":"Feminin; meist im Plural 'die Chemikalien' verwendet.","example":"Im Labor werden verschiedene Chemikalien gelagert.","exampleEn":"Various chemicals are stored in the lab.","example2":"Diese Chemikalie ist giftig.","example2En":"This chemical is toxic."},{"de":"der Chip","en":"crisp / chip","pos":"noun","plural":"die Chips","meanings":[{"en":"a thin fried slice of potato (snack, usually plural)","de":"dünne, frittierte Kartoffelscheibe (Snack, meist im Plural verwendet)"}],"rule":"Maskulin: der Chip, Plural die Chips; wird fast immer im Plural benutzt ('Chips essen'). Nicht feminin, wie man beim Hören des Plurals vermuten könnte.","example":"Wir essen am Abend gern Chips vor dem Fernseher.","exampleEn":"We like to eat chips/crisps in front of the TV in the evening.","example2":"Kannst du eine Tüte Chips mitbringen?","example2En":"Can you bring a bag of chips/crisps?"},{"de":"der Container","en":"container","pos":"noun","plural":"die Container","meanings":[{"en":"a large box for storage or transport","de":"großer Behälter zum Lagern oder Transportieren"},{"en":"a large bin for waste/recycling","de":"großer Abfallbehälter"}],"rule":"Englisches Lehnwort, maskulin; Plural bleibt unverändert.","example":"Der Container wird mit dem Kran auf das Schiff gehoben.","exampleEn":"The container is lifted onto the ship by crane.","example2":"Das alte Papier gehört in den blauen Container.","example2En":"The old paper goes in the blue recycling bin."},{"de":"das Dach","en":"roof","pos":"noun","plural":"die Dächer","meanings":[{"en":"the covering on top of a building","de":"oberer Abschluss eines Gebäudes"}],"rule":"Sächlich, unregelmäßiger Plural mit Umlaut: das Dach – die Dächer.","example":"Das Dach des Hauses ist aus Ziegeln.","exampleEn":"The roof of the house is made of tiles.","example2":"Bei dem Sturm wurde das Dach beschädigt.","example2En":"The roof was damaged in the storm."},{"de":"daneben","en":"next to it / beside it","pos":"adverb","plural":"","meanings":[{"en":"next to/beside a place or thing","de":"örtlich: neben etwas/jemandem"},{"en":"in addition to that / besides","de":"zusätzlich, außerdem"}],"rule":"Lokaladverb; auch übertragen als 'daneben' = falsch/schief im Sinne von 'danebenliegen'.","example":"Das Café ist neben der Bank, direkt daneben ist die Post.","exampleEn":"The café is next to the bank, right beside it is the post office.","example2":"Er arbeitet Vollzeit und studiert daneben.","example2En":"He works full-time and studies besides that."},{"de":"der Datenschutz","en":"data protection","pos":"noun","plural":"","meanings":[{"en":"protection of personal data/privacy","de":"Schutz persönlicher Daten vor Missbrauch"}],"rule":"Zusammensetzung 'Daten' + 'Schutz'; maskulin, Singularwort ohne Plural.","example":"Die Firma achtet streng auf den Datenschutz.","exampleEn":"The company pays close attention to data protection.","example2":"Der Datenschutz wurde durch das Leck verletzt.","example2En":"Data protection was violated by the leak."},{"de":"die DDR (Deutsche Demokratische Republik)","en":"GDR (German Democratic Republic)","pos":"noun","plural":"","meanings":[{"en":"former East German state (1949–1990)","de":"ehemaliger ostdeutscher Staat (1949–1990)"}],"rule":"Eigenname, feminin ('die DDR'); nur Singular, historischer Begriff.","example":"Meine Großeltern sind in der DDR aufgewachsen.","exampleEn":"My grandparents grew up in the GDR.","example2":"Die DDR existierte von 1949 bis 1990.","example2En":"The GDR existed from 1949 to 1990."},{"de":"der Deckel","en":"lid, cover","pos":"noun","plural":"die Deckel","meanings":[{"en":"lid/cover (of a pot, jar, box)","de":"Abdeckung für Topf, Glas oder Dose"}],"rule":"Der Plural bleibt unverändert: der Deckel – die Deckel.","example":"Leg bitte den Deckel auf den Topf.","exampleEn":"Please put the lid on the pot.","example2":"Der Deckel vom Glas ist zu fest.","example2En":"The lid of the jar is too tight."},{"de":"demnächst","en":"soon, shortly","pos":"adverb","plural":"","meanings":[{"en":"in the near future","de":"bald, in naher Zukunft"}],"rule":"Zeitadverb, steht oft am Satzanfang oder nach dem Verb.","example":"Wir ziehen demnächst in eine neue Wohnung um.","exampleEn":"We are moving to a new apartment soon.","example2":"Der Film kommt demnächst ins Kino.","example2En":"The movie is coming to theaters shortly."},{"de":"die Demokratie","en":"democracy","pos":"noun","plural":"die Demokratien","meanings":[{"en":"system of government by the people","de":"Staatsform, in der das Volk mitbestimmt"}],"rule":"Femininum auf -ie, Betonung auf -tie; Plural die Demokratien (für verschiedene Länder/Formen).","example":"Deutschland ist eine Demokratie.","exampleEn":"Germany is a democracy.","example2":"Viele Menschen kämpfen für mehr Demokratie.","example2En":"Many people fight for more democracy."},{"de":"demokratisch","en":"democratic","pos":"adjective","plural":"","meanings":[{"en":"relating to or based on democracy","de":"nach den Prinzipien der Demokratie"}],"rule":"Regelmäßige Steigerung: demokratisch, demokratischer, am demokratischsten.","example":"Die Wahlen waren frei und demokratisch.","exampleEn":"The elections were free and democratic.","example2":"Wir treffen die Entscheidung demokratisch.","example2En":"We make the decision democratically."},{"de":"die Demonstration","en":"demonstration, protest","pos":"noun","plural":"die Demonstrationen","meanings":[{"en":"public protest march","de":"öffentlicher Protest, bei dem Menschen auf die Straße gehen"}],"rule":"Umgangssprachlich oft kurz 'Demo'.","example":"Am Samstag findet eine große Demonstration statt.","exampleEn":"There is a big demonstration on Saturday.","example2":"Viele Studenten nahmen an der Demonstration teil.","example2En":"Many students took part in the demonstration."}]},{"id":"b1-05","title":"B1 · D–E (5)","level":"B1","words":[{"de":"der/die Freiwillige","en":"volunteer","pos":"noun","plural":"die Freiwilligen","meanings":[{"en":"a person who does something voluntarily, unpaid","de":"eine Person, die etwas freiwillig und meist unbezahlt tut"}],"rule":"Adjective noun (nominalized adjective): declines like an adjective, e.g. 'ein Freiwilliger', 'die Freiwillige', plural 'die Freiwilligen'.","example":"Viele Freiwillige helfen nach der Flut beim Aufräumen.","exampleEn":"Many volunteers are helping clean up after the flood.","example2":"Sie arbeitet als Freiwillige im Krankenhaus.","example2En":"She works as a volunteer at the hospital."},{"de":"deswegen","en":"therefore, that's why","pos":"adverb","plural":"","meanings":[{"en":"for that reason","de":"aus diesem Grund, deshalb"}],"rule":"Konjunktionaladverb: Verb steht direkt danach (Position 2), z.B. 'Es regnet, deswegen bleibe ich zu Hause.'","example":"Der Bus kam zu spät, deswegen habe ich den Zug verpasst.","exampleEn":"The bus came too late, that's why I missed the train.","example2":"Ich bin krank, deswegen gehe ich heute nicht arbeiten.","example2En":"I'm sick, so I'm not going to work today."},{"de":"die Detektivgeschichte","en":"detective story","pos":"noun","plural":"die Detektivgeschichten","meanings":[{"en":"a story about solving a crime","de":"Geschichte, in der ein Fall gelöst wird"}],"rule":"Zusammensetzung aus 'Detektiv' + 'Geschichte'; Genus vom Grundwort 'die Geschichte'.","example":"Er liest gern spannende Detektivgeschichten.","exampleEn":"He likes reading exciting detective stories.","example2":"Die Detektivgeschichte endet mit einer Überraschung.","example2En":"The detective story ends with a surprise."},{"de":"der Diabetiker / die Diabetikerin","en":"diabetic (person)","pos":"noun","plural":"die Diabetiker / die Diabetikerinnen","meanings":[{"en":"a person who has diabetes","de":"Person, die an Diabetes (Zuckerkrankheit) leidet"}],"rule":"Bewegungsform: Diabetiker (m) / Diabetikerin (f); Plural analog.","example":"Mein Vater ist Diabetiker und muss auf Zucker achten.","exampleEn":"My father is diabetic and has to watch his sugar.","example2":"Diabetiker sollten regelmäßig ihren Blutzucker messen.","example2En":"Diabetics should check their blood sugar regularly."},{"de":"das Diagramm","en":"diagram, chart","pos":"noun","plural":"die Diagramme","meanings":[{"en":"a graphic representation of data","de":"grafische Darstellung von Zahlen oder Daten"}],"rule":"Neutrum, Plural auf -e.","example":"Das Diagramm zeigt die Verkaufszahlen des letzten Jahres.","exampleEn":"The diagram shows last year's sales figures.","example2":"Bitte zeichnen Sie ein Diagramm für Ihre Präsentation.","example2En":"Please draw a diagram for your presentation."},{"de":"dicht","en":"dense, tight-sealed; closed","pos":"adjective","plural":"","meanings":[{"en":"densely packed, close together","de":"eng, nah beieinander"},{"en":"sealed, not leaking","de":"undurchlässig, wasserdicht"}],"rule":"Regelmäßige Steigerung: dicht, dichter, am dichtesten.","example":"Im Wald stehen die Bäume sehr dicht.","exampleEn":"The trees in the forest stand very close together.","example2":"Das Fenster ist nicht dicht, es zieht.","example2En":"The window doesn't seal well, there's a draft."},{"de":"die/der Bekannte","en":"acquaintance","pos":"noun","plural":"die Bekannten","meanings":[{"en":"a person one knows (not a close friend)","de":"eine Person, die man kennt"}],"rule":"Adjektivdeklination: 'der/die Bekannte', 'ein Bekannter / eine Bekannte' – dekliniert wie ein Adjektiv.","example":"Ich habe gestern eine alte Bekannte getroffen.","exampleEn":"Yesterday I met an old acquaintance.","example2":"Er hat viele Bekannte, aber wenige echte Freunde.","example2En":"He has many acquaintances but few real friends."},{"de":"der Diebstahl","en":"theft","pos":"noun","plural":"die Diebstähle","meanings":[{"en":"the act of stealing","de":"das Stehlen fremden Eigentums"}],"rule":"Plural mit Umlaut: der Diebstahl – die Diebstähle.","example":"Er wurde wegen Diebstahls angezeigt.","exampleEn":"He was reported for theft.","example2":"In der Stadt gab es mehrere Diebstähle.","example2En":"There were several thefts in the city."},{"de":"die Dienstleistung","en":"service","pos":"noun","plural":"die Dienstleistungen","meanings":[{"en":"a service provided (not a physical product)","de":"Leistung, die für andere erbracht wird, z. B. Beratung, Reparatur"}],"rule":"Oft im Plural in wirtschaftlichem Kontext: Dienstleistungen anbieten.","example":"Die Firma bietet verschiedene Dienstleistungen an.","exampleEn":"The company offers various services.","example2":"Der Dienstleistungssektor wächst stark.","example2En":"The service sector is growing strongly."},{"de":"die Dienstreise","en":"business trip","pos":"noun","plural":"die Dienstreisen","meanings":[{"en":"a trip made for work purposes","de":"Reise, die man beruflich unternimmt"}],"rule":"Zusammensetzung aus 'Dienst' + 'Reise'; Genus vom Grundwort 'die Reise'.","example":"Mein Chef ist diese Woche auf Dienstreise.","exampleEn":"My boss is on a business trip this week.","example2":"Ich muss nächsten Monat eine Dienstreise nach Berlin machen.","example2En":"I have to go on a business trip to Berlin next month."},{"de":"die Diskussion","en":"discussion","pos":"noun","plural":"die Diskussionen","meanings":[{"en":"a conversation exchanging views, often argumentative","de":"Gespräch, bei dem verschiedene Meinungen ausgetauscht werden"}],"rule":"Kollokation: eine Diskussion führen / eine Diskussion über etwas.","example":"Es gab eine lange Diskussion über das neue Gesetz.","exampleEn":"There was a long discussion about the new law.","example2":"Bitte führt die Diskussion ruhig und sachlich.","example2En":"Please keep the discussion calm and objective."},{"de":"die Dokumentation (Doku)","en":"documentary; documentation","pos":"noun","plural":"die Dokumentationen","meanings":[{"en":"a factual film/report on a topic","de":"Film oder Bericht über ein Thema, z. B. im Fernsehen"},{"en":"written records documenting a process","de":"schriftliche Aufzeichnung eines Vorgangs"}],"rule":"Umgangssprachliche Kurzform: die Doku.","example":"Heute Abend läuft eine Doku über den Klimawandel.","exampleEn":"Tonight there's a documentary about climate change.","example2":"Die Dokumentation des Projekts muss vollständig sein.","example2En":"The documentation of the project must be complete."},{"de":"der Döner","en":"doner kebab","pos":"noun","plural":"die Döner","meanings":[{"en":"Turkish-style sandwich with grilled meat in flatbread","de":"gefülltes Fladenbrot mit gegrilltem Fleisch"}],"rule":"Plural unverändert: der Döner – die Döner.","example":"Ich hole uns zwei Döner zum Mittagessen.","exampleEn":"I'll get us two doner kebabs for lunch.","example2":"Der Döner an der Ecke schmeckt wirklich gut.","example2En":"The doner kebab place on the corner tastes really good."},{"de":"doof","en":"silly, dumb, annoying","pos":"adjective","plural":"","meanings":[{"en":"stupid, silly (informal)","de":"dumm, blöd (umgangssprachlich)"},{"en":"annoying, unpleasant","de":"unangenehm, ärgerlich"}],"rule":"Umgangssprachlich; regelmäßige Steigerung: doof, doofer, am doofsten.","example":"Das war echt eine doofe Idee.","exampleEn":"That was really a silly idea.","example2":"So ein doofes Wetter heute!","example2En":"What annoying weather today!"},{"de":"das Doppelbett","en":"double bed","pos":"noun","plural":"die Doppelbetten","meanings":[{"en":"a bed for two people","de":"Bett für zwei Personen"}],"rule":"Zusammensetzung aus 'doppel-' + 'das Bett'; Genus vom Grundwort.","example":"Das Hotelzimmer hat ein großes Doppelbett.","exampleEn":"The hotel room has a large double bed.","example2":"Wir möchten ein Zimmer mit Doppelbett buchen.","example2En":"We would like to book a room with a double bed."},{"de":"doppelt","en":"double; twice","pos":"adjective","plural":"","meanings":[{"en":"double (amount/size)","de":"zweifach"},{"en":"twice (as much)","de":"zweimal"}],"rule":"Adjective/adverb; often used with 'so viel/so groß': 'doppelt so groß'.","example":"Die doppelte Portion kostet fünf Euro mehr.","exampleEn":"The double portion costs five euros more.","example2":"Ich musste doppelt so lange warten wie sonst.","example2En":"I had to wait twice as long as usual."},{"de":"das Doppelzimmer","en":"double room","pos":"noun","plural":"die Doppelzimmer","meanings":[{"en":"hotel room for two people","de":"Zimmer für zwei Personen"}],"rule":"Neuter compound noun (der/das Zimmer is neuter); abbreviated 'DZ' in hotel bookings.","example":"Wir hätten gern ein Doppelzimmer mit Meerblick.","exampleEn":"We'd like a double room with a sea view.","example2":"Das Doppelzimmer kostet 90 Euro pro Nacht.","example2En":"The double room costs 90 euros per night."},{"de":"das Dorf","en":"village","pos":"noun","plural":"die Dörfer","meanings":[{"en":"small rural settlement","de":"kleiner Ort auf dem Land"}],"rule":"Neuter noun with umlaut plural: Dorf → Dörfer.","example":"Meine Großeltern wohnen in einem kleinen Dorf.","exampleEn":"My grandparents live in a small village.","example2":"Im Dorf gibt es nur einen Supermarkt.","example2En":"There's only one supermarket in the village."},{"de":"dramatisch","en":"dramatic","pos":"adjective","plural":"","meanings":[{"en":"tense/serious (situation)","de":"sehr ernst, spannungsgeladen"},{"en":"theatrical, exaggerated","de":"übertrieben, theatralisch"}],"rule":"Regular adjective; comparison: dramatisch, dramatischer, am dramatischsten.","example":"Die Lage im Krankenhaus war sehr dramatisch.","exampleEn":"The situation in the hospital was very dramatic.","example2":"Musst du immer so dramatisch reagieren?","example2En":"Do you always have to react so dramatically?"},{"de":"dran sein","en":"to be someone's turn","pos":"phrase","plural":"","meanings":[{"en":"to have one's turn (waiting, games)","de":"an der Reihe sein"}],"rule":"Colloquial fixed phrase with sein; 'dran' = short for 'daran'. Präteritum: war dran, Perfekt: ist dran gewesen.","example":"Warte kurz, du bist gleich dran.","exampleEn":"Wait a moment, it's almost your turn.","example2":"Wer ist als Nächster dran?","example2En":"Who's next in line?"},{"de":"drinnen","en":"inside, indoors","pos":"adverb","plural":"","meanings":[{"en":"in an interior space (opposite of draußen)","de":"im Inneren eines Raumes"}],"rule":"Adverb of place, no article/declension; opposite: draußen.","example":"Es regnet, bleiben wir lieber drinnen.","exampleEn":"It's raining, let's stay inside instead.","example2":"Drinnen ist es viel wärmer als draußen.","example2En":"It's much warmer inside than outside."},{"de":"dumm","en":"stupid, dumb","pos":"adjective","plural":"","meanings":[{"en":"unintelligent","de":"nicht klug"},{"en":"annoying, unfortunate (situation)","de":"ärgerlich, blöd"}],"rule":"Irregular comparison with umlaut: dumm, dümmer, am dümmsten.","example":"Das war eine dumme Frage, tut mir leid.","exampleEn":"That was a stupid question, sorry.","example2":"So ein dummer Zufall, dass wir uns verpasst haben!","example2En":"What a silly coincidence that we missed each other!"},{"de":"durchlässig","en":"permeable, porous","pos":"adjective","plural":"","meanings":[{"en":"allowing liquid/light etc. to pass through","de":"Wasser, Licht o.Ä. durchlassend"}],"rule":"Regular adjective; from 'durchlassen' (to let through).","example":"Der Boden hier ist sehr durchlässig für Regenwasser.","exampleEn":"The soil here is very permeable to rainwater.","example2":"Die Jacke ist wasserdicht, aber luftdurchlässig.","example2En":"The jacket is waterproof but breathable (air-permeable)."},{"de":"der Durchschnitt","en":"average","pos":"noun","plural":"die Durchschnitte","meanings":[{"en":"arithmetic mean/average value","de":"Mittelwert"}],"rule":"Masculine noun; common phrase 'im Durchschnitt' = on average.","example":"Im Durchschnitt arbeite ich acht Stunden am Tag.","exampleEn":"On average I work eight hours a day.","example2":"Sein Notendurchschnitt hat sich verbessert.","example2En":"His grade average has improved."},{"de":"durchschnittlich","en":"average; on average","pos":"adjective","plural":"","meanings":[{"en":"average (adjective)","de":"im Mittel liegend"},{"en":"on average (adverb)","de":"im Durchschnitt"}],"rule":"Adjective and adverb from 'Durchschnitt'; regular comparison.","example":"Die durchschnittliche Miete ist im letzten Jahr gestiegen.","exampleEn":"The average rent has risen in the last year.","example2":"Wir verdienen durchschnittlich 2500 Euro im Monat.","example2En":"We earn on average 2,500 euros a month."},{"de":"die DVD","en":"DVD","pos":"noun","plural":"die DVDs","meanings":[{"en":"digital video disc","de":"digitale Videoscheibe"}],"rule":"Feminine noun (die Disc/Scheibe); plural simply adds -s.","example":"Hast du diesen Film auf DVD?","exampleEn":"Do you have this film on DVD?","example2":"Wir haben den ganzen Abend DVDs geschaut.","example2En":"We watched DVDs all evening."},{"de":"ebenso","en":"just as, likewise","pos":"adverb","plural":"","meanings":[{"en":"just as (comparison)","de":"genauso"},{"en":"likewise, similarly","de":"ebenfalls"}],"rule":"Often paired with 'wie': 'ebenso ... wie'.","example":"Sie ist ebenso nett wie ihre Schwester.","exampleEn":"She is just as nice as her sister.","example2":"Er kam zu spät, und sein Kollege ebenso.","example2En":"He arrived late, and so did his colleague."},{"de":"ehemalig","en":"former","pos":"adjective","plural":"","meanings":[{"en":"former, ex-","de":"früher, vorherig"}],"rule":"Only used attributively before a noun (not predicative).","example":"Mein ehemaliger Chef hat mich angerufen.","exampleEn":"My former boss called me.","example2":"Das Gebäude war eine ehemalige Fabrik.","example2En":"The building was a former factory."},{"de":"eher","en":"rather; sooner","pos":"adverb","plural":"","meanings":[{"en":"rather, more likely (preference)","de":"vielmehr, lieber"},{"en":"sooner, earlier (comparative of bald)","de":"früher"}],"rule":"Irregular comparative of 'bald' (bald – eher – am ehesten), not of 'früh'; also common expressing preference: 'eher ... als'.","example":"Ich würde eher zu Hause bleiben als ins Kino gehen.","exampleEn":"I'd rather stay home than go to the cinema.","example2":"Kannst du morgen eher kommen, um acht statt um neun?","example2En":"Can you come earlier tomorrow, at eight instead of nine?"},{"de":"ehrlich","en":"honest","pos":"adjective","plural":"","meanings":[{"en":"truthful, sincere","de":"aufrichtig, wahrheitsgemäß"}],"rule":"Regular adjective; common phrase 'ehrlich gesagt' = honestly speaking.","example":"Sei bitte ehrlich zu mir.","exampleEn":"Please be honest with me.","example2":"Ehrlich gesagt, der Film hat mir nicht gefallen.","example2En":"Honestly, I didn't like the film."},{"de":"der Eierkarton","en":"egg carton","pos":"noun","plural":"die Eierkartons","meanings":[{"en":"box for carrying/storing eggs","de":"Verpackung für Eier"}],"rule":"Masculine (der Karton); compound of Ei(er) + Karton; plural with -s.","example":"Kannst du einen Eierkarton aus dem Supermarkt mitbringen?","exampleEn":"Can you bring an egg carton from the supermarket?","example2":"Der Eierkarton ist leer, wir brauchen neue Eier.","example2En":"The egg carton is empty, we need new eggs."},{"de":"die Eierschale","en":"eggshell","pos":"noun","plural":"die Eierschalen","meanings":[{"en":"the hard outer shell of an egg","de":"harte Hülle eines Eis"}],"rule":"Feminine (die Schale); compound of Ei(er) + Schale. Idiom: 'wie auf Eierschalen gehen' = to walk on eggshells.","example":"Wirf die Eierschalen bitte in den Biomüll.","exampleEn":"Please throw the eggshells into the organic waste.","example2":"Seit dem Streit geht er bei ihr wie auf Eierschalen.","example2En":"Since the argument, he's been walking on eggshells around her."},{"de":"das Eigentum","en":"property, ownership","pos":"noun","plural":"","meanings":[{"en":"something owned; possession","de":"Besitz"},{"en":"legal ownership","de":"rechtlicher Besitzanspruch"}],"rule":"Neuter, uncountable noun (no plural); compare 'Eigentümer/in' = owner.","example":"Diese Wohnung ist mein Eigentum.","exampleEn":"This apartment is my property.","example2":"Das Fahrrad gehört nicht mir, es ist fremdes Eigentum.","example2En":"The bike isn't mine, it's someone else's property."},{"de":"eigenverantwortlich","en":"on one's own responsibility; independently","pos":"adjective","plural":"","meanings":[{"en":"acting on one's own responsibility, independently","de":"selbstständig, auf eigene Verantwortung"}],"rule":"Adjective/adverb, no irregular comparison typical (often used without comparative forms); common in job contexts: 'eigenverantwortlich arbeiten'.","example":"In dieser Stelle arbeiten Sie sehr eigenverantwortlich.","exampleEn":"In this job you work very independently, on your own responsibility.","example2":"Die neue Mitarbeiterin plant ihre Projekte eigenverantwortlich.","example2En":"The new employee plans her projects on her own responsibility."},{"de":"eilig","en":"urgent; in a hurry","pos":"adjective","plural":"","meanings":[{"en":"needing to be done quickly, urgent","de":"dringend, muss schnell erledigt werden"},{"en":"in a hurry (of a person)","de":"in Eile, schnell unterwegs"}],"rule":"Regular comparison: eilig, eiliger, am eiligsten. Common phrase: 'es eilig haben' (to be in a hurry).","example":"Das ist eine eilige Angelegenheit, bitte kümmern Sie sich sofort darum.","exampleEn":"This is an urgent matter, please take care of it right away.","example2":"Entschuldigung, ich habe es eilig. Wir sprechen später.","example2En":"Sorry, I'm in a hurry. We'll talk later."},{"de":"einbrechen","en":"to break in (burglary); to fall through/collapse","pos":"verb","plural":"","meanings":[{"en":"to break into a building to steal","de":"gewaltsam in ein Gebäude eindringen, um zu stehlen"},{"en":"to collapse, fall through (e.g. ice)","de":"plötzlich zusammenbrechen, z. B. Eis"}],"rule":"Trennbar: bricht ein, brach ein, ist eingebrochen. With 'in + Akk.' for the burglary sense.","example":"Letzte Nacht sind Einbrecher in das Geschäft eingebrochen.","exampleEn":"Last night burglars broke into the shop.","example2":"Der Junge ist auf dem See ins Eis eingebrochen.","example2En":"The boy fell through the ice on the lake."},{"de":"der Einbrecher / die Einbrecherin","en":"burglar","pos":"noun","plural":"die Einbrecher / die Einbrecherinnen","meanings":[{"en":"a person who breaks into buildings to steal","de":"jemand, der einbricht, um zu stehlen"}],"rule":"Derived from 'einbrechen'; masculine form also used generically.","example":"Die Polizei hat den Einbrecher noch in der Nacht gefasst.","exampleEn":"The police caught the burglar that very night.","example2":"Eine Einbrecherin wurde von der Nachbarin beobachtet.","example2En":"A female burglar was spotted by the neighbor."},{"de":"der Einbruch","en":"burglary; onset (e.g. of darkness/winter)","pos":"noun","plural":"die Einbrüche","meanings":[{"en":"a burglary, break-in","de":"das gewaltsame Eindringen, um zu stehlen"},{"en":"the sudden onset of something (darkness, winter)","de":"der plötzliche Beginn, z. B. bei Einbruch der Dunkelheit"}],"rule":"Noun from 'einbrechen'; fixed phrase 'bei Einbruch der Dunkelheit' = at nightfall.","example":"Bei dem Einbruch wurde viel Schmuck gestohlen.","exampleEn":"A lot of jewelry was stolen in the burglary.","example2":"Wir müssen vor Einbruch der Dunkelheit zu Hause sein.","example2En":"We have to be home before nightfall."},{"de":"einchecken","en":"to check in","pos":"verb","plural":"","meanings":[{"en":"to check in at an airport or hotel","de":"sich am Flughafen oder Hotel anmelden"}],"rule":"Trennbar: checkt ein, checkte ein, hat eingecheckt.","example":"Wir müssen zwei Stunden vor dem Abflug einchecken.","exampleEn":"We have to check in two hours before departure.","example2":"Sie hat online für den Flug eingecheckt.","example2En":"She checked in online for the flight."},{"de":"einfallen","en":"to occur to someone; to invade","pos":"verb","plural":"","meanings":[{"en":"to come to mind, occur to someone","de":"jemandem plötzlich in den Sinn kommen"},{"en":"to invade (a country, militarily)","de":"militärisch in ein Land eindringen"}],"rule":"Trennbar: fällt ein, fiel ein, ist eingefallen. + Dativ for the 'come to mind' sense: 'mir fällt ein...'","example":"Mir fällt gerade sein Name nicht ein.","exampleEn":"I can't think of his name right now.","example2":"Die Truppen sind in das Nachbarland eingefallen.","example2En":"The troops invaded the neighboring country."},{"de":"einführen","en":"to introduce; to import","pos":"verb","plural":"","meanings":[{"en":"to introduce (a system, person, product)","de":"etwas Neues bekannt machen oder einsetzen"},{"en":"to import goods","de":"Waren aus dem Ausland ins Land bringen"}],"rule":"Trennbar: führt ein, führte ein, hat eingeführt.","example":"Die Firma hat ein neues Bewertungssystem eingeführt.","exampleEn":"The company introduced a new rating system.","example2":"Deutschland führt viele Rohstoffe aus dem Ausland ein.","example2En":"Germany imports many raw materials from abroad."},{"de":"eingehen","en":"to arrive (mail/goods); to shrink; to agree to/accept (a risk)","pos":"verb","plural":"","meanings":[{"en":"to arrive, come in (letters, orders)","de":"ankommen, z. B. Post oder Bestellungen"},{"en":"to shrink (fabric)","de":"kleiner werden, z. B. Stoff beim Waschen"},{"en":"to enter into, agree to (a risk, contract)","de":"etwas eingehen, z. B. ein Risiko oder einen Vertrag"}],"rule":"Trennbar: geht ein, ging ein, ist eingegangen. 'auf etwas eingehen' = to respond to/address something.","example":"Ihre Bewerbung ist gestern bei uns eingegangen.","exampleEn":"Your application arrived here yesterday.","example2":"Der Pullover ist beim Waschen eingegangen.","example2En":"The sweater shrank in the wash."},{"de":"einhalten","en":"to keep, comply with (rules, deadlines)","pos":"verb","plural":"","meanings":[{"en":"to keep, adhere to (a rule, deadline, promise)","de":"sich an etwas halten, z. B. Regeln oder Termine"}],"rule":"Trennbar: hält ein, hielt ein, hat eingehalten. + Akkusativ.","example":"Bitte halten Sie die Lieferfrist ein.","exampleEn":"Please meet the delivery deadline.","example2":"Er hält sich immer an die Regeln.","example2En":"He always complies with the rules."},{"de":"das Einkommen","en":"income","pos":"noun","plural":"die Einkommen","meanings":[{"en":"money earned, income","de":"das Geld, das jemand verdient"}],"rule":"Neuter noun from 'einkommen'; plural form identical to singular; often used with adjectives: monatliches Einkommen.","example":"Ihr monatliches Einkommen liegt über dem Durchschnitt.","exampleEn":"Her monthly income is above average.","example2":"Das Einkommen der Familie reicht kaum zum Leben.","example2En":"The family's income is barely enough to live on."},{"de":"einlegen","en":"to insert; to pickle/preserve","pos":"verb","plural":"","meanings":[{"en":"to insert, put in (e.g. a disc, a break)","de":"etwas hineinlegen, z. B. eine Pause einlegen"},{"en":"to pickle, preserve (food)","de":"Lebensmittel in Flüssigkeit haltbar machen"}],"rule":"Trennbar: legt ein, legte ein, hat eingelegt. Fixed phrase: 'eine Pause einlegen' = to take a break.","example":"Wir sollten jetzt eine kurze Pause einlegen.","exampleEn":"We should take a short break now.","example2":"Meine Oma legt jedes Jahr Gurken ein.","example2En":"My grandma pickles cucumbers every year."},{"de":"einparken","en":"to park (into a space)","pos":"verb","plural":"","meanings":[{"en":"to park a vehicle into a parking space","de":"ein Fahrzeug in eine Parklücke fahren"}],"rule":"Trennbar: parkt ein, parkte ein, hat eingeparkt.","example":"Er kann sehr gut rückwärts einparken.","exampleEn":"He can park backwards very well.","example2":"Die Parklücke war zu klein zum Einparken.","example2En":"The parking space was too small to park in."},{"de":"einreichen","en":"to submit, hand in","pos":"verb","plural":"","meanings":[{"en":"to submit an application or document","de":"ein Dokument offiziell abgeben"}],"rule":"Trennbar: reicht ein, reichte ein, hat eingereicht. + Akkusativ, often with 'bei': etwas bei jemandem einreichen.","example":"Sie müssen die Unterlagen bis Freitag einreichen.","exampleEn":"You have to submit the documents by Friday.","example2":"Er hat seinen Urlaubsantrag beim Chef eingereicht.","example2En":"He submitted his vacation request to his boss."},{"de":"einschalten","en":"to switch on; to bring in, call in","pos":"verb","plural":"","meanings":[{"en":"to switch on (a device)","de":"ein Gerät anmachen"},{"en":"to call in, involve (a person/authority)","de":"jemanden zur Hilfe hinzuziehen, z. B. einen Anwalt"}],"rule":"Trennbar: schaltet ein, schaltete ein, hat eingeschaltet.","example":"Kannst du bitte den Fernseher einschalten?","exampleEn":"Can you please switch on the TV?","example2":"Bei Problemen haben sie einen Anwalt eingeschaltet.","example2En":"They called in a lawyer when problems arose."},{"de":"einschlafen","en":"to fall asleep","pos":"verb","plural":"","meanings":[{"en":"to fall asleep","de":"in den Schlaf fallen"}],"rule":"Trennbar: schläft ein, schlief ein, ist eingeschlafen.","example":"Das Baby ist schnell eingeschlafen.","exampleEn":"The baby fell asleep quickly.","example2":"Ich bin gestern Abend vor dem Fernseher eingeschlafen.","example2En":"I fell asleep in front of the TV last night."},{"de":"einschreiben","en":"to send by registered mail; to enroll/register","pos":"verb","plural":"","meanings":[{"en":"to send something as registered mail","de":"einen Brief als Einschreiben verschicken"},{"en":"to enroll, register (e.g. at university, oneself)","de":"sich für etwas anmelden, z. B. an einer Universität"}],"rule":"Trennbar: schreibt ein, schrieb ein, hat eingeschrieben. Reflexive 'sich einschreiben' for enrollment.","example":"Ich habe den Brief einschreiben lassen, damit er sicher ankommt.","exampleEn":"I had the letter sent by registered mail so that it arrives safely.","example2":"Sie hat sich für das Sommersemester eingeschrieben.","example2En":"She enrolled for the summer semester."}]},{"id":"b1-06","title":"B1 · E (6)","level":"B1","words":[{"de":"einseitig","en":"one-sided; unilateral","pos":"adjective","plural":"","meanings":[{"en":"one-sided, unbalanced","de":"nur eine Seite betreffend, nicht ausgewogen"},{"en":"unilateral (decision, action)","de":"nur von einer Partei ausgehend"}],"rule":"Regular comparison: einseitig, einseitiger, am einseitigsten.","example":"Seine Ernährung ist ziemlich einseitig.","exampleEn":"His diet is quite one-sided.","example2":"Die Firma hat den Vertrag einseitig gekündigt.","example2En":"The company unilaterally terminated the contract."},{"de":"einsetzen","en":"to insert; to use/deploy; (sich) to stand up for","pos":"verb","plural":"","meanings":[{"en":"to insert, put in","de":"etwas an eine Stelle setzen/stecken"},{"en":"to use, employ, deploy","de":"etwas/jemanden für einen Zweck verwenden"},{"en":"sich einsetzen: to support, advocate for","de":"sich für etwas engagieren"}],"rule":"trennbar: setzt ... ein, setzte ein, hat eingesetzt; mit 'für' + Akkusativ bei 'sich einsetzen für'","example":"Bitte setzen Sie das fehlende Wort ein.","exampleEn":"Please insert the missing word.","example2":"Sie setzt sich für Umweltschutz ein.","example2En":"She stands up for environmental protection."},{"de":"einsperren","en":"to lock up, to imprison","pos":"verb","plural":"","meanings":[{"en":"to lock someone/something in/up","de":"jemanden/etwas irgendwo einschließen"}],"rule":"trennbar: sperrt ... ein, sperrte ein, hat eingesperrt","example":"Der Hund wurde im Garten eingesperrt.","exampleEn":"The dog was locked up in the garden.","example2":"Die Polizei hat den Dieb eingesperrt.","example2En":"The police locked up the thief."},{"de":"einstellen","en":"to hire; to adjust/set; to stop/discontinue","pos":"verb","plural":"","meanings":[{"en":"to hire, employ someone","de":"jemanden für eine Arbeit anstellen"},{"en":"to adjust, set (a device)","de":"ein Gerät regulieren"},{"en":"to stop, discontinue","de":"etwas beenden"}],"rule":"trennbar: stellt ... ein, stellte ein, hat eingestellt; reflexiv 'sich einstellen auf' + Akkusativ = sich anpassen","example":"Die Firma hat zehn neue Mitarbeiter eingestellt.","exampleEn":"The company hired ten new employees.","example2":"Kannst du den Wecker richtig einstellen?","example2En":"Can you set the alarm clock correctly?"},{"de":"die Einstiegszeit","en":"boarding time","pos":"noun","plural":"die Einstiegszeiten","meanings":[{"en":"the time during which passengers board a vehicle","de":"die Zeit, in der man in ein Fahrzeug einsteigt"}],"rule":"zusammengesetzt aus 'Einstieg' (Nomen zu 'einsteigen') + 'Zeit'; meist im Zusammenhang mit Bus, Zug oder Flugzeug","example":"Die Einstiegszeit für den Bus beginnt fünf Minuten vor der Abfahrt.","exampleEn":"The boarding time for the bus starts five minutes before departure.","example2":"Bitte beachten Sie die Einstiegszeiten am Bahnsteig.","example2En":"Please note the boarding times on the platform."},{"de":"das Eintrittsdatum","en":"date of entry, start date","pos":"noun","plural":"die Eintrittsdaten","meanings":[{"en":"the date on which someone starts (e.g. a job)","de":"das Datum, an dem man z. B. eine Arbeit beginnt"}],"rule":"zusammengesetzt aus 'Eintritt' + 'Datum'; oft auf Formularen bei Arbeitsverträgen","example":"Bitte geben Sie Ihr Eintrittsdatum im Vertrag an.","exampleEn":"Please state your start date in the contract.","example2":"Das Eintrittsdatum in den Verein war der 1. Januar.","example2En":"The date of entry into the club was January 1st."},{"de":"die Einwanderung","en":"immigration","pos":"noun","plural":"die Einwanderungen","meanings":[{"en":"the act of immigrating into a country","de":"das dauerhafte Zuziehen in ein Land"}],"rule":"von 'einwandern' abgeleitetes Nomen; Gegenteil: die Auswanderung","example":"Die Einwanderung nach Deutschland hat zugenommen.","exampleEn":"Immigration to Germany has increased.","example2":"Das Land hat neue Gesetze zur Einwanderung beschlossen.","example2En":"The country has passed new immigration laws."},{"de":"das Einzelzimmer","en":"single room","pos":"noun","plural":"die Einzelzimmer","meanings":[{"en":"a hotel room for one person","de":"ein Zimmer für eine Person"}],"rule":"Abkürzung: EZ; Gegenteil: das Doppelzimmer (DZ)","example":"Ich hätte gern ein Einzelzimmer mit Dusche.","exampleEn":"I would like a single room with a shower.","example2":"Das Einzelzimmer kostet 60 Euro pro Nacht.","example2En":"The single room costs 60 euros per night."},{"de":"das Eishockey","en":"ice hockey","pos":"noun","plural":"","meanings":[{"en":"ice hockey, a team sport played on ice","de":"eine Mannschaftssportart auf dem Eis"}],"rule":"unzählbar, kein Plural; Sportart-Neutrum wie viele Sportarten auf -hockey","example":"Er spielt seit Jahren Eishockey im Verein.","exampleEn":"He has been playing ice hockey in a club for years.","example2":"Das Eishockeyspiel war sehr spannend.","example2En":"The ice hockey game was very exciting."},{"de":"der Eiskunstlauf","en":"figure skating","pos":"noun","plural":"","meanings":[{"en":"figure skating, an artistic ice sport","de":"eine künstlerische Sportart auf dem Eis"}],"rule":"unzählbar, kein Plural; maskulin","example":"Sie trainiert jeden Tag Eiskunstlauf.","exampleEn":"She trains figure skating every day.","example2":"Im Fernsehen läuft heute ein Eiskunstlauf-Wettbewerb.","example2En":"There is a figure skating competition on TV today."},{"de":"das Eiweiß","en":"egg white; protein","pos":"noun","plural":"die Eiweiße","meanings":[{"en":"egg white","de":"der weiße Teil des Eis"},{"en":"protein (nutrient)","de":"ein wichtiger Nährstoff, z. B. in Fleisch oder Bohnen"}],"rule":"bei der Bedeutung 'Nährstoff' meist unzählbar (kein Plural); bei 'Eiweiß vom Ei' zählbar möglich","example":"Trenne das Eiweiß vom Eigelb.","exampleEn":"Separate the egg white from the yolk.","example2":"Fleisch enthält viel Eiweiß.","example2En":"Meat contains a lot of protein."},{"de":"das Elektroauto","en":"electric car","pos":"noun","plural":"die Elektroautos","meanings":[{"en":"a car powered by electricity","de":"ein Auto mit Elektromotor statt Benzinmotor"}],"rule":"zusammengesetzt aus 'Elektro-' + 'Auto'; Plural auf -s wie bei 'Auto'","example":"Wir haben uns ein Elektroauto gekauft.","exampleEn":"We bought an electric car.","example2":"Elektroautos brauchen keine Tankstelle, sondern eine Ladestation.","example2En":"Electric cars don't need a gas station, but a charging station."},{"de":"emotional","en":"emotional","pos":"adjective","plural":"","meanings":[{"en":"relating to feelings, emotional","de":"die Gefühle betreffend"}],"rule":"regelmäßige Steigerung: emotional, emotionaler, am emotionalsten","example":"Der Abschied war sehr emotional.","exampleEn":"The farewell was very emotional.","example2":"Sie reagiert immer sehr emotional auf Kritik.","example2En":"She always reacts very emotionally to criticism."},{"de":"der Empfang","en":"reception; reception desk; signal reception","pos":"noun","plural":"die Empfänge","meanings":[{"en":"reception desk (e.g. in a hotel)","de":"die Anmeldung, z. B. im Hotel"},{"en":"reception, welcome (event)","de":"eine feierliche Begrüßung"},{"en":"signal reception","de":"der Radio- oder Handyempfang"}],"rule":"maskulin; von 'empfangen' abgeleitet","example":"Bitte melden Sie sich am Empfang.","exampleEn":"Please check in at the reception desk.","example2":"Hier im Keller habe ich keinen Empfang.","example2En":"I have no reception here in the basement."},{"de":"empfangen","en":"to receive; to welcome","pos":"verb","plural":"","meanings":[{"en":"to receive (a signal, a letter, a guest)","de":"etwas bekommen, z. B. ein Signal"},{"en":"to welcome, greet someone formally","de":"jemanden begrüßen"}],"rule":"unregelmäßig: empfängt, empfing, hat empfangen; nicht trennbar","example":"Wir empfangen hier über 50 Fernsehsender.","exampleEn":"We can receive over 50 TV channels here.","example2":"Der Bürgermeister empfing die Gäste persönlich.","example2En":"The mayor personally welcomed the guests."},{"de":"enden","en":"to end, finish","pos":"verb","plural":"","meanings":[{"en":"to come to an end, finish","de":"aufhören, zu Ende sein"}],"rule":"regelmäßig: endet, endete, hat geendet; intransitiv","example":"Der Film endet mit einem Happy End.","exampleEn":"The movie ends with a happy ending.","example2":"Die Veranstaltung endete um 22 Uhr.","example2En":"The event ended at 10 p.m."},{"de":"die Energiekosten","en":"energy costs","pos":"noun","plural":"","meanings":[{"en":"costs for electricity, gas, heating etc.","de":"die Kosten für Strom, Gas oder Heizung"}],"rule":"nur im Plural gebräuchlich","example":"Die Energiekosten sind in diesem Jahr stark gestiegen.","exampleEn":"Energy costs have risen sharply this year.","example2":"Mit einer neuen Heizung sparen wir Energiekosten.","example2En":"With a new heating system we save on energy costs."},{"de":"das Energiesparhaus","en":"energy-efficient house","pos":"noun","plural":"die Energiesparhäuser","meanings":[{"en":"a house built to consume little energy","de":"ein Haus, das wenig Energie verbraucht"}],"rule":"zusammengesetzt aus 'Energie' + 'sparen' + 'Haus'; Plural wie 'Haus' -> Häuser","example":"Sie wohnen in einem modernen Energiesparhaus.","exampleEn":"They live in a modern energy-efficient house.","example2":"Ein Energiesparhaus braucht wenig Heizöl.","example2En":"An energy-efficient house needs little heating oil."},{"de":"die Energiesparlampe","en":"energy-saving lamp/bulb","pos":"noun","plural":"die Energiesparlampen","meanings":[{"en":"a light bulb that uses less electricity","de":"eine Glühbirne mit geringem Stromverbrauch"}],"rule":"zusammengesetzt aus 'Energie' + 'sparen' + 'Lampe'","example":"Wir haben alle Glühbirnen durch Energiesparlampen ersetzt.","exampleEn":"We replaced all light bulbs with energy-saving lamps.","example2":"Eine Energiesparlampe hält viel länger als eine normale Glühbirne.","example2En":"An energy-saving lamp lasts much longer than a normal bulb."},{"de":"die Energieverschwendung","en":"energy waste","pos":"noun","plural":"","meanings":[{"en":"wasteful use of energy","de":"unnötiger, verschwenderischer Verbrauch von Energie"}],"rule":"Uncountable compound noun (Energie + Verschwendung); usually no plural.","example":"Das Licht brennt den ganzen Tag – das ist reine Energieverschwendung.","exampleEn":"The light is on all day – that's pure energy waste.","example2":"Wir wollen die Energieverschwendung in unserem Büro reduzieren.","example2En":"We want to reduce energy waste in our office."},{"de":"englischsprachig","en":"English-speaking","pos":"adjective","plural":"","meanings":[{"en":"English-speaking / in English","de":"auf Englisch sprechend oder geschrieben"}],"rule":"No irregular comparison; used attributively, e.g. 'englischsprachige Länder'.","example":"Sie hat einen englischsprachigen Roman gelesen.","exampleEn":"She read a novel written in English.","example2":"Kanada hat sowohl englischsprachige als auch französischsprachige Regionen.","example2En":"Canada has both English-speaking and French-speaking regions."},{"de":"entnehmen","en":"to take out / to gather (from)","pos":"verb","plural":"","meanings":[{"en":"to take something out (of a container etc.)","de":"etwas aus etwas herausnehmen"},{"en":"to gather/infer (from a text)","de":"aus einem Text oder einer Aussage schließen"}],"rule":"Irregular (nimmt-type): entnimmt, entnahm, hat entnommen. Governs Akkusativ (Sache) + Dativ (Quelle): etwas (Akk) einer Sache/einem Ort (Dat) entnehmen.","example":"Bitte entnehmen Sie dem Umschlag das Formular.","exampleEn":"Please take the form out of the envelope.","example2":"Dem Bericht kann man entnehmen, dass die Zahlen gestiegen sind.","example2En":"From the report one can gather that the figures have risen."},{"de":"die Entscheidung","en":"decision","pos":"noun","plural":"die Entscheidungen","meanings":[{"en":"a decision","de":"das Entscheiden, ein Beschluss"}],"rule":"Common collocation: eine Entscheidung treffen (to make a decision).","example":"Wir müssen heute eine wichtige Entscheidung treffen.","exampleEn":"We have to make an important decision today.","example2":"Seine Entscheidung, die Stadt zu verlassen, hat alle überrascht.","example2En":"His decision to leave the city surprised everyone."},{"de":"entspannend","en":"relaxing","pos":"adjective","plural":"","meanings":[{"en":"relaxing, soothing","de":"beruhigend, Stress abbauend"}],"rule":"Present participle of 'entspannen' used as adjective; regular comparison (entspannender, am entspannendsten).","example":"Ein Spaziergang im Wald ist sehr entspannend.","exampleEn":"A walk in the forest is very relaxing.","example2":"Nach der Arbeit finde ich ein warmes Bad entspannend.","example2En":"After work I find a warm bath relaxing."},{"de":"entsprechen","en":"to correspond to / to meet (requirements)","pos":"verb","plural":"","meanings":[{"en":"to correspond to, match","de":"mit etwas übereinstimmen"},{"en":"to meet/fulfil (expectations, requirements)","de":"Erwartungen oder Anforderungen erfüllen"}],"rule":"Irregular, + Dativ: entspricht, entsprach, hat entsprochen.","example":"Das Ergebnis entspricht nicht unseren Erwartungen.","exampleEn":"The result does not correspond to our expectations.","example2":"Die Wohnung entspricht genau meinen Vorstellungen.","example2En":"The apartment matches exactly what I had in mind."},{"de":"entstehen","en":"to arise, come into being","pos":"verb","plural":"","meanings":[{"en":"to arise, originate, be created","de":"neu gebildet werden, entwickeln"}],"rule":"Irregular, intransitive, Perfekt with 'sein': entsteht, entstand, ist entstanden.","example":"Durch den Unfall ist ein großer Schaden entstanden.","exampleEn":"A great deal of damage resulted from the accident.","example2":"So entstehen neue Ideen im Team.","example2En":"That's how new ideas arise in the team."},{"de":"enttäuschen","en":"to disappoint","pos":"verb","plural":"","meanings":[{"en":"to disappoint","de":"jemandes Erwartungen nicht erfüllen"}],"rule":"Regular weak verb; the adjective/participle 'enttäuscht' is often combined with 'von' (+ Dativ): 'enttäuscht sein von' = to be disappointed by/in.","example":"Der Film hat mich sehr enttäuscht.","exampleEn":"The movie disappointed me a lot.","example2":"Ich will meine Eltern nicht enttäuschen.","example2En":"I don't want to disappoint my parents."},{"de":"die Enttäuschung","en":"disappointment","pos":"noun","plural":"die Enttäuschungen","meanings":[{"en":"disappointment","de":"das Gefühl, wenn Erwartungen nicht erfüllt werden"}],"rule":"Derived from enttäuschen; countable noun.","example":"Das verlorene Spiel war eine große Enttäuschung für die Mannschaft.","exampleEn":"The lost game was a big disappointment for the team.","example2":"Er konnte seine Enttäuschung kaum verbergen.","example2En":"He could hardly hide his disappointment."},{"de":"entwickeln","en":"to develop","pos":"verb","plural":"","meanings":[{"en":"to develop (a product, idea)","de":"etwas Neues schaffen oder verbessern"},{"en":"to develop, evolve (reflexive: sich entwickeln)","de":"sich verändern, wachsen"}],"rule":"Regular weak verb; reflexive form 'sich entwickeln' = to evolve/grow.","example":"Die Firma hat ein neues Produkt entwickelt.","exampleEn":"The company developed a new product.","example2":"Das Kind hat sich in den letzten Jahren gut entwickelt.","example2En":"The child has developed well in recent years."},{"de":"das Erdbeben","en":"earthquake","pos":"noun","plural":"die Erdbeben","meanings":[{"en":"earthquake","de":"eine starke Erschütterung der Erde"}],"rule":"Compound: Erde + Beben; plural same as singular form.","example":"Gestern gab es ein schweres Erdbeben in der Region.","exampleEn":"Yesterday there was a severe earthquake in the region.","example2":"Nach dem Erdbeben wurden viele Häuser zerstört.","example2En":"After the earthquake, many houses were destroyed."},{"de":"die Erde","en":"earth, ground; the Earth (planet)","pos":"noun","plural":"","meanings":[{"en":"soil, ground","de":"der Boden"},{"en":"the planet Earth","de":"der Planet, auf dem wir leben"}],"rule":"Usually uncountable / used with definite article 'die Erde'; capitalised when meaning the planet.","example":"Die Pflanze braucht mehr Erde im Topf.","exampleEn":"The plant needs more soil in the pot.","example2":"Die Erde dreht sich um die Sonne.","example2En":"The Earth revolves around the sun."},{"de":"die Erderwärmung","en":"global warming","pos":"noun","plural":"","meanings":[{"en":"global warming","de":"der Anstieg der Durchschnittstemperatur auf der Erde"}],"rule":"Compound noun, uncountable, no plural.","example":"Die Erderwärmung führt zu häufigeren Wetterextremen.","exampleEn":"Global warming leads to more frequent extreme weather.","example2":"Wissenschaftler warnen seit Jahren vor der Erderwärmung.","example2En":"Scientists have been warning about global warming for years."},{"de":"das Ereignis","en":"event","pos":"noun","plural":"die Ereignisse","meanings":[{"en":"an event, occurrence","de":"etwas, das geschieht oder passiert"}],"rule":"Neuter noun; plural adds -se.","example":"Die Hochzeit war ein besonderes Ereignis für die ganze Familie.","exampleEn":"The wedding was a special event for the whole family.","example2":"In den Nachrichten wurde über das aktuelle Ereignis berichtet.","example2En":"The news reported on the current event."},{"de":"erfolgreich","en":"successful","pos":"adjective","plural":"","meanings":[{"en":"successful","de":"mit Erfolg, gelungen"}],"rule":"Regular comparison: erfolgreicher, am erfolgreichsten.","example":"Sie ist eine erfolgreiche Geschäftsfrau.","exampleEn":"She is a successful businesswoman.","example2":"Das Projekt wurde erfolgreich abgeschlossen.","example2En":"The project was completed successfully."},{"de":"die Ergänzung","en":"addition, supplement","pos":"noun","plural":"die Ergänzungen","meanings":[{"en":"an addition, supplement, completion","de":"etwas, das hinzugefügt wird, um etwas vollständig zu machen"}],"rule":"Derived from 'ergänzen' (to add/complete); countable noun.","example":"Als Ergänzung zum Kurs empfehle ich dieses Buch.","exampleEn":"As a supplement to the course, I recommend this book.","example2":"Die neuen Mitarbeiter sind eine gute Ergänzung für unser Team.","example2En":"The new employees are a good addition to our team."},{"de":"das Ergebnis","en":"result","pos":"noun","plural":"die Ergebnisse","meanings":[{"en":"result, outcome","de":"das, was am Ende herauskommt"}],"rule":"Neuter noun; plural adds -se; common collocation: zu einem Ergebnis kommen.","example":"Das Ergebnis der Prüfung war sehr gut.","exampleEn":"The exam result was very good.","example2":"Wir sind zu einem klaren Ergebnis gekommen.","example2En":"We reached a clear conclusion."},{"de":"der Erhalt","en":"receipt; preservation","pos":"noun","plural":"","meanings":[{"en":"receipt (of something, formal)","de":"das Empfangen von etwas"},{"en":"preservation, maintenance","de":"das Bewahren, Erhalten von etwas"}],"rule":"Masculine, uncountable noun; common formal phrase 'nach Erhalt Ihrer Nachricht'.","example":"Bitte bestätigen Sie den Erhalt der Ware.","exampleEn":"Please confirm receipt of the goods.","example2":"Der Verein setzt sich für den Erhalt des alten Gebäudes ein.","example2En":"The association is committed to preserving the old building."},{"de":"erhältlich","en":"available; obtainable","pos":"adjective","plural":"","meanings":[{"en":"available (for purchase)","de":"verfügbar, zu kaufen"}],"rule":"Meist prädikativ nach 'sein' verwendet (z. B. 'ist erhältlich'); kaum gesteigert.","example":"Das Produkt ist nur online erhältlich.","exampleEn":"The product is only available online.","example2":"Dieses Medikament ist rezeptfrei erhältlich.","example2En":"This medicine is available without a prescription."},{"de":"erhöhen","en":"to raise; to increase","pos":"verb","plural":"","meanings":[{"en":"to increase (prices, amount, rate)","de":"größer machen, steigern"},{"en":"to raise physically (height)","de":"höher machen"}],"rule":"Regelmäßig: erhöht, erhöhte, hat erhöht; + Akkusativ.","example":"Die Firma erhöht die Preise ab Januar.","exampleEn":"The company is raising prices from January.","example2":"Er hat das Bett um zehn Zentimeter erhöht.","example2En":"He raised the bed by ten centimeters."},{"de":"erinnern","en":"to remind; to remember","pos":"verb","plural":"","meanings":[{"en":"to remind someone of something (+Akk + an+Akk)","de":"jemanden an etwas denken lassen"},{"en":"sich erinnern = to remember (+an+Akk)","de":"sich an etwas zurückerinnern"}],"rule":"Regelmäßig: erinnert, erinnerte, hat erinnert. 'jemanden an etwas erinnern' vs. reflexiv 'sich an etwas erinnern'.","example":"Kannst du mich morgen an den Termin erinnern?","exampleEn":"Can you remind me about the appointment tomorrow?","example2":"Ich erinnere mich gut an meine Kindheit.","example2En":"I remember my childhood well."},{"de":"die Erinnerung","en":"memory; reminder","pos":"noun","plural":"die Erinnerungen","meanings":[{"en":"memory, recollection","de":"das, woran man sich erinnert"},{"en":"reminder (e.g. notice)","de":"Hinweis, der an etwas erinnert"}],"rule":"Feminin; mit 'an' + Akkusativ ('Erinnerung an den Urlaub').","example":"Ich habe schöne Erinnerungen an den Urlaub.","exampleEn":"I have nice memories of the vacation.","example2":"Die E-Mail ist nur eine Erinnerung an den Termin.","example2En":"The email is just a reminder of the appointment."},{"de":"erkennen","en":"to recognize; to realize","pos":"verb","plural":"","meanings":[{"en":"to recognize (a person or thing)","de":"wiedererkennen"},{"en":"to realize, detect (a problem, fact)","de":"bemerken, feststellen"}],"rule":"Unregelmäßig: erkennt, erkannte, hat erkannt; + Akkusativ.","example":"Ich habe ihn sofort erkannt.","exampleEn":"I recognized him immediately.","example2":"Der Arzt hat die Krankheit früh erkannt.","example2En":"The doctor detected the illness early."},{"de":"die Erklärung","en":"explanation; declaration","pos":"noun","plural":"die Erklärungen","meanings":[{"en":"explanation","de":"das Erklären, Begründung"},{"en":"(official) declaration, statement","de":"offizielle Aussage"}],"rule":"Feminin; von 'erklären' abgeleitet.","example":"Der Lehrer gab eine klare Erklärung.","exampleEn":"The teacher gave a clear explanation.","example2":"Die Regierung gab eine offizielle Erklärung ab.","example2En":"The government issued an official declaration."},{"de":"die Erlaubnis","en":"permission","pos":"noun","plural":"die Erlaubnisse","meanings":[{"en":"permission, authorization","de":"das Erlauben, Genehmigung"}],"rule":"Feminin; meist im Singular verwendet, oft ohne Artikel nach 'ohne' ('ohne Erlaubnis').","example":"Ich brauche die Erlaubnis meiner Eltern.","exampleEn":"I need my parents' permission.","example2":"Ohne Erlaubnis darfst du hier nicht parken.","example2En":"You are not allowed to park here without permission."},{"de":"erleben","en":"to experience","pos":"verb","plural":"","meanings":[{"en":"to experience, go through (an event, feeling)","de":"etwas persönlich mitmachen"}],"rule":"Regelmäßig: erlebt, erlebte, hat erlebt; + Akkusativ.","example":"Wir haben im Urlaub viel Schönes erlebt.","exampleEn":"We experienced many wonderful things on vacation.","example2":"Sie hat eine schwierige Zeit erlebt.","example2En":"She went through a difficult time."},{"de":"erleichtern","en":"to make easier; to relieve","pos":"verb","plural":"","meanings":[{"en":"to facilitate, make easier","de":"einfacher machen"},{"en":"to relieve (of worry, burden)","de":"von einer Last befreien"}],"rule":"Regelmäßig: erleichtert, erleichterte, hat erleichtert; + Akkusativ.","example":"Der neue Computer erleichtert die Arbeit.","exampleEn":"The new computer makes the work easier.","example2":"Das Gespräch hat ihn sehr erleichtert.","example2En":"The conversation was a great relief to him."},{"de":"ernähren","en":"to feed; to nourish","pos":"verb","plural":"","meanings":[{"en":"to feed, provide for someone","de":"jemanden mit Nahrung versorgen"},{"en":"sich ernähren = to eat, live on (+von)","de":"sich mit Nahrung versorgen"}],"rule":"Regelmäßig: ernährt, ernährte, hat ernährt; reflexiv 'sich ernähren von +Dativ'.","example":"Sie ernährt ihre Familie mit ihrem Gehalt.","exampleEn":"She supports her family with her salary.","example2":"Er ernährt sich gesund.","example2En":"He eats healthily."},{"de":"die Ernährung","en":"nutrition; diet","pos":"noun","plural":"","meanings":[{"en":"nutrition, diet","de":"die Art, wie man sich ernährt"}],"rule":"Feminin, uncountable (kein Plural im Alltagsgebrauch).","example":"Gesunde Ernährung ist wichtig für den Körper.","exampleEn":"Healthy nutrition is important for the body.","example2":"Der Arzt empfiehlt eine ausgewogene Ernährung.","example2En":"The doctor recommends a balanced diet."},{"de":"die Erstellung","en":"creation; preparation (of a document)","pos":"noun","plural":"","meanings":[{"en":"creation, preparation (e.g. of a document, plan)","de":"das Erstellen, Anfertigen"}],"rule":"Feminin, meist Singular; von 'erstellen' abgeleitet.","example":"Die Erstellung des Berichts dauert zwei Wochen.","exampleEn":"Preparing the report takes two weeks.","example2":"Für die Erstellung der Rechnung brauchen wir Ihre Adresse.","example2En":"We need your address to create the invoice."},{"de":"erwähnen","en":"to mention","pos":"verb","plural":"","meanings":[{"en":"to mention, refer to briefly","de":"kurz sagen, nennen"}],"rule":"Regelmäßig: erwähnt, erwähnte, hat erwähnt; + Akkusativ.","example":"Er hat das Problem in der Besprechung erwähnt.","exampleEn":"He mentioned the problem in the meeting.","example2":"Sie hat nebenbei erwähnt, dass sie umzieht.","example2En":"She mentioned in passing that she is moving."}]},{"id":"b1-07","title":"B1 · E–F (7)","level":"B1","words":[{"de":"eskalieren","en":"to escalate","pos":"verb","plural":"","meanings":[{"en":"to escalate, intensify (a conflict, situation)","de":"sich verschärfen, schlimmer werden"}],"rule":"Regelmäßig, intransitiv mit 'sein': eskaliert, eskalierte, ist eskaliert.","example":"Der Streit ist schnell eskaliert.","exampleEn":"The argument escalated quickly.","example2":"Die Situation an der Grenze eskaliert weiter.","example2En":"The situation at the border keeps escalating."},{"de":"der Esser / die Esserin","en":"eater","pos":"noun","plural":"die Esser / die Esserinnen","meanings":[{"en":"eater (person who eats, usually with an adjective)","de":"jemand, der isst (meist mit Adjektiv)"}],"rule":"Wird meist mit Adjektiv gebraucht, z. B. 'ein guter/schlechter Esser'.","example":"Mein Sohn ist ein schlechter Esser.","exampleEn":"My son is a poor eater.","example2":"Sie ist eine langsame Esserin.","example2En":"She is a slow eater."},{"de":"die Euroeinführung","en":"introduction of the euro","pos":"noun","plural":"die Euroeinführungen","meanings":[{"en":"the introduction of the euro currency","de":"die Einführung des Euro als Währung"}],"rule":"Feminin, meist im Singular gebraucht (historisches Einzelereignis).","example":"Die Euroeinführung fand 2002 statt.","exampleEn":"The introduction of the euro took place in 2002.","example2":"Viele Menschen erinnern sich noch an die Euroeinführung.","example2En":"Many people still remember the introduction of the euro."},{"de":"die Europäische Union (EU)","en":"the European Union","pos":"noun","plural":"","meanings":[{"en":"the European Union, a political and economic union of European states","de":"der Zusammenschluss europäischer Staaten"}],"rule":"Feminin, Eigenname; kein Plural; Abkürzung 'die EU'.","example":"Deutschland ist Mitglied der Europäischen Union.","exampleEn":"Germany is a member of the European Union.","example2":"Die EU hat 27 Mitgliedsstaaten.","example2En":"The EU has 27 member states."},{"de":"eventuell","en":"possibly; if applicable","pos":"adverb","plural":"","meanings":[{"en":"possibly, perhaps","de":"vielleicht, möglicherweise"}],"rule":"Adverb, often modifies a whole sentence; not to be confused with English 'eventually' (= schließlich), a classic false friend.","example":"Ich komme eventuell etwas später.","exampleEn":"I might come a bit later.","example2":"Eventuell müssen wir den Termin verschieben.","example2En":"We may possibly have to postpone the appointment."},{"de":"exotisch","en":"exotic","pos":"adjective","plural":"","meanings":[{"en":"exotic, unusual/foreign","de":"fremdartig, ungewöhnlich"}],"rule":"Regular adjective, no irregular comparison (exotischer, am exotischsten).","example":"Im Urlaub haben wir exotische Früchte probiert.","exampleEn":"On vacation we tried exotic fruits.","example2":"Bali klingt für viele wie ein exotisches Reiseziel.","example2En":"Bali sounds like an exotic travel destination to many."},{"de":"der Experte / die Expertin","en":"expert","pos":"noun","plural":"die Experten / die Expertinnen","meanings":[{"en":"expert, specialist","de":"Fachmann/Fachfrau"}],"rule":"Weak masculine noun: den/dem/des Experten (except nominative).","example":"Er ist ein Experte für Klimafragen.","exampleEn":"He is an expert on climate issues.","example2":"Die Expertin erklärte die Ergebnisse der Studie.","example2En":"The expert explained the results of the study."},{"de":"die Fähigkeit","en":"ability, skill","pos":"noun","plural":"die Fähigkeiten","meanings":[{"en":"ability, skill, capability","de":"Können, Talent"}],"rule":"Feminine noun ending in -keit, always die; often used with 'zu + Infinitiv' or 'die Fähigkeit, etwas zu tun'.","example":"Sie hat die Fähigkeit, gut zuzuhören.","exampleEn":"She has the ability to listen well.","example2":"Teamarbeit erfordert soziale Fähigkeiten.","example2En":"Teamwork requires social skills."},{"de":"die Fahrerseite","en":"driver's side","pos":"noun","plural":"die Fahrerseiten","meanings":[{"en":"the driver's side (of a vehicle)","de":"die Seite des Autos, auf der der Fahrer sitzt"}],"rule":"Compound noun: der Fahrer + die Seite → die Fahrerseite.","example":"Die Tür auf der Fahrerseite klemmt.","exampleEn":"The door on the driver's side is jammed.","example2":"Das Auto wurde an der Fahrerseite beschädigt.","example2En":"The car was damaged on the driver's side."},{"de":"fair","en":"fair","pos":"adjective","plural":"","meanings":[{"en":"fair, just","de":"gerecht, anständig"}],"rule":"Regular adjective (fairer, am fairsten); often used in phrases like 'fairer Preis', 'fair spielen'.","example":"Der Preis für das Fahrrad war fair.","exampleEn":"The price for the bike was fair.","example2":"Wir sollten alle Mitarbeiter fair behandeln.","example2En":"We should treat all employees fairly."},{"de":"falls","en":"in case, if","pos":"conjunction","plural":"","meanings":[{"en":"in case, if (conditional)","de":"für den Fall, dass; wenn"}],"rule":"Subordinating conjunction, sends the verb to the end of the clause, e.g. 'falls es regnet'.","example":"Falls es regnet, bleiben wir zu Hause.","exampleEn":"In case it rains, we'll stay home.","example2":"Ruf mich an, falls du Hilfe brauchst.","example2En":"Call me if you need help."},{"de":"der Fan","en":"fan","pos":"noun","plural":"die Fans","meanings":[{"en":"fan (admirer/supporter)","de":"Anhänger, Bewunderer"}],"rule":"Masculine noun (loanword from English); plural simply adds -s.","example":"Er ist ein großer Fan von diesem Fußballverein.","exampleEn":"He is a big fan of this football club.","example2":"Die Fans warteten stundenlang auf ihr Idol.","example2En":"The fans waited for hours for their idol."},{"de":"die Fantasie","en":"imagination, fantasy","pos":"noun","plural":"die Fantasien","meanings":[{"en":"imagination, creative fantasy","de":"Vorstellungskraft, Einbildungskraft"},{"en":"a fantasy/daydream (specific imagined idea)","de":"eine erfundene Vorstellung"}],"rule":"Feminine noun; also spelled 'Phantasie' in older texts, but 'Fantasie' is current standard spelling.","example":"Kinder haben oft eine lebhafte Fantasie.","exampleEn":"Children often have a vivid imagination.","example2":"Das ist nur eine Fantasie von ihm, keine Realität.","example2En":"That's just a fantasy of his, not reality."},{"de":"färben","en":"to dye, to color","pos":"verb","plural":"","meanings":[{"en":"to dye or color something","de":"einer Sache eine Farbe geben"}],"rule":"Regular weak verb: färbt, färbte, hat gefärbt.","example":"Sie hat sich die Haare rot gefärbt.","exampleEn":"She dyed her hair red.","example2":"Die Blätter färben sich im Herbst gelb.","example2En":"The leaves turn yellow in autumn."},{"de":"das Fax","en":"fax","pos":"noun","plural":"die Faxe","meanings":[{"en":"a fax (document or machine)","de":"ein per Faxgerät gesendetes Dokument"}],"rule":"Neuter noun; can also mean the machine in everyday speech, though 'Faxgerät' is more precise.","example":"Bitte schicken Sie mir das Formular per Fax.","exampleEn":"Please send me the form by fax.","example2":"Ich habe gerade ein Fax vom Finanzamt bekommen.","example2En":"I just received a fax from the tax office."},{"de":"das Fertiggericht","en":"ready meal, convenience food","pos":"noun","plural":"die Fertiggerichte","meanings":[{"en":"a ready-made/pre-prepared meal","de":"ein bereits zubereitetes Essen zum Aufwärmen"}],"rule":"Compound: fertig (ready) + das Gericht (dish) → das Fertiggericht.","example":"Am Abend esse ich oft ein Fertiggericht aus dem Supermarkt.","exampleEn":"In the evening I often eat a ready meal from the supermarket.","example2":"Fertiggerichte enthalten häufig viel Salz.","example2En":"Ready meals often contain a lot of salt."},{"de":"die Festanstellung","en":"permanent employment","pos":"noun","plural":"die Festanstellungen","meanings":[{"en":"a permanent job/position","de":"eine unbefristete Arbeitsstelle"}],"rule":"Compound: fest + die Anstellung; contrasts with 'befristete Stelle' (temporary job).","example":"Nach dem Praktikum bekam sie eine Festanstellung.","exampleEn":"After the internship she got a permanent position.","example2":"Er sucht schon lange eine Festanstellung.","example2En":"He has been looking for a permanent job for a long time."},{"de":"festkleben","en":"to stick firmly, to glue on","pos":"verb","plural":"","meanings":[{"en":"to be/become firmly stuck to something","de":"fest an etwas kleben"},{"en":"to glue something firmly in place","de":"etwas fest ankleben"}],"rule":"Trennbar (separable): klebt fest, klebte fest. Intransitive (to be stuck): ist festgeklebt, e.g. 'Der Zettel ist festgeklebt.' Transitive (to glue something on): hat festgeklebt, e.g. 'Er hat den Zettel festgeklebt.'","example":"Der Kaugummi ist am Schuh festgeklebt.","exampleEn":"The chewing gum is stuck firmly to the shoe.","example2":"Er hat das Poster an der Wand festgeklebt.","example2En":"He glued the poster firmly to the wall."},{"de":"festlegen","en":"to determine, to set, to fix","pos":"verb","plural":"","meanings":[{"en":"to determine/set something (e.g. a date, rule)","de":"etwas bestimmen, verbindlich entscheiden"},{"en":"sich festlegen: to commit oneself","de":"sich verbindlich entscheiden"}],"rule":"Trennbar (separable): legt fest, legte fest, hat festgelegt; reflexive form 'sich festlegen auf + Akkusativ'.","example":"Wir müssen einen Termin für das Treffen festlegen.","exampleEn":"We need to set a date for the meeting.","example2":"Er will sich noch nicht auf einen Plan festlegen.","example2En":"He doesn't want to commit to a plan yet."},{"de":"fett","en":"fatty, greasy; bold","pos":"adjective","plural":"","meanings":[{"en":"fatty, greasy (food)","de":"reich an Fett"},{"en":"bold (typeface)","de":"fett gedruckt"}],"rule":"Regular adjective (fetter, am fettesten); 'fett gedruckt' or 'fett' alone = bold text.","example":"Das Essen im Imbiss war mir zu fett.","exampleEn":"The food at the snack bar was too greasy for me.","example2":"Wichtige Wörter sind im Text fett markiert.","example2En":"Important words are marked in bold in the text."},{"de":"finanziell","en":"financial","pos":"adjective","plural":"","meanings":[{"en":"financial, relating to money","de":"das Geld betreffend"}],"rule":"Regular adjective, no irregular comparison; often used adverbially: 'finanziell unterstützen'.","example":"Die Firma hat finanzielle Probleme.","exampleEn":"The company has financial problems.","example2":"Meine Eltern unterstützen mich finanziell beim Studium.","example2En":"My parents support me financially during my studies."},{"de":"das Finanzwesen","en":"finance (sector), financial system","pos":"noun","plural":"","meanings":[{"en":"the finance sector/system as a whole","de":"der Bereich von Geld, Banken und Wirtschaft"}],"rule":"Uncountable neuter noun (no plural); often used in professional/academic contexts, e.g. 'im Finanzwesen arbeiten'.","example":"Sie arbeitet im Finanzwesen einer großen Bank.","exampleEn":"She works in the finance department of a large bank.","example2":"Er hat Finanzwesen studiert.","example2En":"He studied finance."},{"de":"der Firmensitz","en":"company headquarters","pos":"noun","plural":"die Firmensitze","meanings":[{"en":"registered office / headquarters of a company","de":"Ort, an dem eine Firma offiziell registriert ist"}],"rule":"Compound noun: die Firma + der Sitz; takes the article of Sitz (der).","example":"Der Firmensitz des Unternehmens ist in München.","exampleEn":"The company's headquarters is in Munich.","example2":"Die Firma hat ihren Firmensitz nach Berlin verlegt.","example2En":"The company moved its headquarters to Berlin."},{"de":"fix","en":"fixed; quick","pos":"adjective","plural":"","meanings":[{"en":"fixed, set (e.g. price, idea)","de":"fest, unveränderlich"},{"en":"quick, fast (colloquial)","de":"schnell, flink"}],"rule":"No irregular comparison; in colloquial use 'fix' often means quick/fast ('mach fix!').","example":"Wir haben einen fixen Termin vereinbart.","exampleEn":"We agreed on a fixed appointment.","example2":"Mach das bitte fix, wir haben keine Zeit mehr.","example2En":"Please do that quickly, we have no more time."},{"de":"fleischfrei","en":"meat-free","pos":"adjective","plural":"","meanings":[{"en":"containing no meat","de":"ohne Fleisch"}],"rule":"No irregular comparison; often used for dishes/menus.","example":"Im Restaurant gibt es auch fleischfreie Gerichte.","exampleEn":"The restaurant also has meat-free dishes.","example2":"Sie isst seit einem Jahr fleischfrei.","example2En":"She has been eating meat-free for a year."},{"de":"fleischlos","en":"meatless","pos":"adjective","plural":"","meanings":[{"en":"without meat","de":"ohne Fleisch"}],"rule":"Synonym of 'fleischfrei'; no irregular comparison.","example":"Am Montag kochen wir immer fleischlos.","exampleEn":"On Mondays we always cook without meat.","example2":"Eine fleischlose Ernährung ist gesund.","example2En":"A meatless diet is healthy."},{"de":"fließend","en":"fluent; flowing","pos":"adjective","plural":"","meanings":[{"en":"fluent (language)","de":"ohne Schwierigkeiten, flüssig"},{"en":"flowing (liquid)","de":"strömend, laufend"}],"rule":"Present participle of 'fließen' used as adjective; no irregular comparison.","example":"Sie spricht fließend Deutsch.","exampleEn":"She speaks German fluently.","example2":"Das Zimmer hat fließendes Wasser.","example2En":"The room has running water."},{"de":"der Flüchtling","en":"refugee","pos":"noun","plural":"die Flüchtlinge","meanings":[{"en":"a person fleeing war, persecution or disaster","de":"jemand, der aus seinem Land fliehen musste"}],"rule":"Always masculine noun even for women; from 'fliehen' (to flee).","example":"Viele Flüchtlinge kamen in die Stadt.","exampleEn":"Many refugees came to the city.","example2":"Die Gemeinde hilft den Flüchtlingen bei der Wohnungssuche.","example2En":"The community helps the refugees find housing."},{"de":"der Flug","en":"flight","pos":"noun","plural":"die Flüge","meanings":[{"en":"a journey by aircraft","de":"Reise mit dem Flugzeug"}],"rule":"From 'fliegen' (fliegt, flog, ist geflogen); masculine noun.","example":"Der Flug nach Rom dauert zwei Stunden.","exampleEn":"The flight to Rome takes two hours.","example2":"Wir haben einen günstigen Flug gebucht.","example2En":"We booked a cheap flight."},{"de":"der Flugbegleiter / die Flugbegleiterin","en":"flight attendant","pos":"noun","plural":"die Flugbegleiter / die Flugbegleiterinnen","meanings":[{"en":"crew member who assists passengers on a plane","de":"Person, die Passagiere im Flugzeug betreut"}],"rule":"Compound of Flug + Begleiter/in; add -in for feminine form.","example":"Der Flugbegleiter bringt uns etwas zu trinken.","exampleEn":"The flight attendant brings us something to drink.","example2":"Die Flugbegleiterin erklärt die Sicherheitsregeln.","example2En":"The flight attendant explains the safety rules."},{"de":"der Fluggast","en":"airline passenger","pos":"noun","plural":"die Fluggäste","meanings":[{"en":"a passenger travelling by plane","de":"Passagier, der fliegt"}],"rule":"Compound of Flug + Gast; masculine noun used for both genders.","example":"Alle Fluggäste müssen ihren Ausweis zeigen.","exampleEn":"All airline passengers must show their ID.","example2":"Der Fluggast wartet am Gate.","example2En":"The passenger is waiting at the gate."},{"de":"die Fluggesellschaft","en":"airline (company)","pos":"noun","plural":"die Fluggesellschaften","meanings":[{"en":"a company that operates flights","de":"Firma, die Flüge anbietet"}],"rule":"Compound noun: Flug + Gesellschaft; takes article of Gesellschaft (die).","example":"Die Fluggesellschaft hat den Flug gestrichen.","exampleEn":"The airline cancelled the flight.","example2":"Welche Fluggesellschaft fliegt nach Athen?","example2En":"Which airline flies to Athens?"},{"de":"der Föhn","en":"hairdryer; warm alpine wind","pos":"noun","plural":"die Föhne","meanings":[{"en":"a hairdryer","de":"Gerät zum Trocknen der Haare"},{"en":"a warm dry wind coming down mountains (Alps)","de":"warmer, trockener Fallwind in den Alpen"}],"rule":"Masculine noun; also the verb 'föhnen' means to blow-dry hair.","example":"Ich trockne meine Haare mit dem Föhn.","exampleEn":"I dry my hair with the hairdryer.","example2":"Heute weht ein warmer Föhn von den Bergen.","example2En":"Today a warm foehn wind is blowing from the mountains."},{"de":"fordern","en":"to demand","pos":"verb","plural":"","meanings":[{"en":"to demand, to insist on something","de":"etwas nachdrücklich verlangen"}],"rule":"Regular weak verb: fordert, forderte, hat gefordert. Not reflexive, not separable. Don't confuse with 'fördern' (to promote/support).","example":"Die Mitarbeiter fordern mehr Gehalt.","exampleEn":"The employees are demanding more salary.","example2":"Der Chef fordert pünktliches Erscheinen.","example2En":"The boss demands punctual arrival."},{"de":"fördern","en":"to promote, to support","pos":"verb","plural":"","meanings":[{"en":"to promote, support, encourage (e.g. a person, talent, project)","de":"jemanden/etwas unterstützen, voranbringen"},{"en":"to extract (e.g. coal, oil) - technical use","de":"Rohstoffe aus der Erde holen"}],"rule":"Regular weak verb: fördert, förderte, hat gefördert. Not to be confused with 'fordern' (to demand).","example":"Die Schule fördert besonders begabte Schüler.","exampleEn":"The school supports especially gifted students.","example2":"In der Region wird seit Jahren Kohle gefördert.","example2En":"Coal has been mined in the region for years."},{"de":"die Formalität","en":"formality","pos":"noun","plural":"die Formalitäten","meanings":[{"en":"an official procedure or requirement","de":"vorgeschriebene Regel, amtliche Vorschrift"}],"rule":"Usually used in plural: 'die Formalitäten erledigen' (to deal with the formalities).","example":"Bei der Einreise müssen wir einige Formalitäten erledigen.","exampleEn":"At entry we need to complete a few formalities.","example2":"Die Anmeldung ist nur eine Formalität.","example2En":"The registration is just a formality."},{"de":"förmlich","en":"formal","pos":"adjective","plural":"","meanings":[{"en":"formal, polite in a stiff/official way","de":"steif, offiziell, nicht locker"}],"rule":"No irregular comparison; don't confuse with 'formell' (also formal, near-synonym).","example":"Er hat mich sehr förmlich begrüßt.","exampleEn":"He greeted me very formally.","example2":"Im Brief benutzte sie einen förmlichen Ton.","example2En":"In the letter she used a formal tone."},{"de":"die Formulierung","en":"wording, phrasing","pos":"noun","plural":"die Formulierungen","meanings":[{"en":"the specific way something is expressed in words","de":"die Art, wie etwas ausgedrückt wird"}],"rule":"From verb 'formulieren' (to formulate); feminine noun ending in -ung.","example":"Die Formulierung des Satzes ist unklar.","exampleEn":"The wording of the sentence is unclear.","example2":"Bitte wählen Sie eine höflichere Formulierung.","example2En":"Please choose a more polite phrasing."},{"de":"der Förster / die Försterin","en":"forester, forest ranger","pos":"noun","plural":"die Förster / die Försterinnen","meanings":[{"en":"a person who manages and protects a forest","de":"Person, die einen Wald pflegt und betreut"}],"rule":"Add -in for the feminine form; related to 'der Forst' (forest).","example":"Der Förster kontrolliert regelmäßig den Wald.","exampleEn":"The forester regularly inspects the forest.","example2":"Die Försterin zeigt den Kindern die Tiere im Wald.","example2En":"The forest ranger shows the children the animals in the forest."},{"de":"die Fortbildung","en":"further training, professional development","pos":"noun","plural":"die Fortbildungen","meanings":[{"en":"training to improve or update professional skills","de":"Kurs oder Training zur beruflichen Weiterqualifizierung"}],"rule":"From 'sich fortbilden' (to continue one's education); feminine noun.","example":"Meine Firma bietet regelmäßige Fortbildungen an.","exampleEn":"My company offers regular training courses.","example2":"Er macht eine Fortbildung im Bereich IT.","example2En":"He is doing further training in IT."},{"de":"die Fotokopie","en":"photocopy","pos":"noun","plural":"die Fotokopien","meanings":[{"en":"a copied reproduction of a document","de":"eine kopierte Seite eines Dokuments"}],"rule":"Compound of Foto + Kopie; makes plural with -n. Verb 'fotokopieren' = to photocopy.","example":"Kannst du bitte eine Fotokopie von meinem Ausweis machen?","exampleEn":"Can you please make a photocopy of my ID?","example2":"Die Fotokopie des Vertrags liegt im Ordner.","example2En":"The photocopy of the contract is in the folder."},{"de":"die Fremdsprache","en":"foreign language","pos":"noun","plural":"die Fremdsprachen","meanings":[{"en":"a language other than one's native language","de":"eine Sprache, die nicht die Muttersprache ist"}],"rule":"Compound: fremd (foreign) + Sprache (language); regular feminine noun, plural -n.","example":"Englisch ist meine erste Fremdsprache.","exampleEn":"English is my first foreign language.","example2":"Er lernt seit einem Jahr eine neue Fremdsprache.","example2En":"He has been learning a new foreign language for a year."},{"de":"die Freude","en":"joy, pleasure","pos":"noun","plural":"","meanings":[{"en":"a feeling of great happiness","de":"ein Gefühl von großem Glück"}],"rule":"Usually uncountable in this sense; 'Freude an/über etwas haben' = to take joy in something. Feminine noun.","example":"Die Kinder hatten große Freude am Geschenk.","exampleEn":"The children were delighted with the gift.","example2":"Es ist mir eine Freude, dich wiederzusehen.","example2En":"It is a pleasure for me to see you again."},{"de":"der Freundeskreis","en":"circle of friends","pos":"noun","plural":"die Freundeskreise","meanings":[{"en":"a group of people who are friends with each other","de":"eine Gruppe von Menschen, die miteinander befreundet sind"}],"rule":"Compound: Freund(e) + Kreis; masculine noun, plural -e.","example":"Er hat einen großen Freundeskreis.","exampleEn":"He has a large circle of friends.","example2":"In meinem Freundeskreis sprechen wir oft über Politik.","example2En":"In my circle of friends we often talk about politics."},{"de":"der Frieden","en":"peace","pos":"noun","plural":"","meanings":[{"en":"a state without war or conflict","de":"ein Zustand ohne Krieg oder Konflikt"}],"rule":"Usually uncountable; masculine noun. 'Frieden schließen' = to make peace.","example":"Die beiden Länder leben seit Jahrzehnten in Frieden.","exampleEn":"The two countries have lived in peace for decades.","example2":"Die beiden Staaten schlossen nach langen Verhandlungen endlich Frieden.","example2En":"The two states finally made peace after long negotiations."},{"de":"friedlich","en":"peaceful","pos":"adjective","plural":"","meanings":[{"en":"calm and without violence or conflict","de":"ruhig und ohne Gewalt oder Konflikt"}],"rule":"Regular adjective, comparison: friedlich, friedlicher, am friedlichsten.","example":"Die Demonstration verlief friedlich.","exampleEn":"The demonstration proceeded peacefully.","example2":"Sie führen ein friedliches Leben auf dem Land.","example2En":"They lead a peaceful life in the countryside."},{"de":"die Frist","en":"deadline, time limit","pos":"noun","plural":"die Fristen","meanings":[{"en":"a fixed period of time by which something must be done","de":"ein festgelegter Zeitraum, in dem etwas erledigt werden muss"}],"rule":"Feminine noun, plural -en. Common phrase: 'eine Frist einhalten' (to meet a deadline).","example":"Die Frist für die Anmeldung endet am Freitag.","exampleEn":"The deadline for registration ends on Friday.","example2":"Bitte zahlen Sie die Rechnung innerhalb der Frist.","example2En":"Please pay the invoice within the deadline."},{"de":"fristgerecht","en":"on time, within the deadline","pos":"adjective","plural":"","meanings":[{"en":"done within the required time limit","de":"innerhalb der vorgeschriebenen Frist erledigt"}],"rule":"Compound adjective from Frist + gerecht; often used adverbially before a verb.","example":"Bitte reichen Sie die Unterlagen fristgerecht ein.","exampleEn":"Please submit the documents on time.","example2":"Er hat die Miete fristgerecht bezahlt.","example2En":"He paid the rent within the deadline."},{"de":"fristlos","en":"without notice, immediate (dismissal)","pos":"adjective","plural":"","meanings":[{"en":"happening immediately, without the usual notice period","de":"ohne die übliche Kündigungsfrist"}],"rule":"Compound: Frist + -los (without); mostly used with 'kündigen' (fristlose Kündigung = dismissal without notice).","example":"Er wurde fristlos entlassen.","exampleEn":"He was dismissed without notice.","example2":"Der Vermieter hat den Mietvertrag fristlos gekündigt.","example2En":"The landlord terminated the lease without notice."},{"de":"die Frisur","en":"hairstyle","pos":"noun","plural":"die Frisuren","meanings":[{"en":"the way someone's hair is cut or styled","de":"die Art, wie jemandes Haare geschnitten oder gestylt sind"}],"rule":"Feminine noun, plural -en.","example":"Sie hat sich eine neue Frisur machen lassen.","exampleEn":"She had a new hairstyle done.","example2":"Seine Frisur passt gut zu seinem Gesicht.","example2En":"His hairstyle suits his face well."}]},{"id":"b1-08","title":"B1 · F–H (8)","level":"B1","words":[{"de":"der Frust","en":"frustration","pos":"noun","plural":"","meanings":[{"en":"a feeling of being annoyed or discouraged","de":"ein Gefühl von Ärger oder Enttäuschung"}],"rule":"Informal shortened form of 'Frustration'; masculine noun, uncountable.","example":"Nach der Absage war der Frust groß.","exampleEn":"After the rejection, the frustration was great.","example2":"Sie hat ihren Frust beim Joggen abgebaut.","example2En":"She worked off her frustration by jogging."},{"de":"frustriert","en":"frustrated","pos":"adjective","plural":"","meanings":[{"en":"feeling annoyed or discouraged because of failure or obstacles","de":"verärgert oder entmutigt wegen Misserfolgs oder Hindernissen"}],"rule":"Past participle of 'frustrieren' used as adjective; regular comparison.","example":"Er ist frustriert, weil das Projekt nicht funktioniert.","exampleEn":"He is frustrated because the project isn't working.","example2":"Nach dem verlorenen Spiel waren alle frustriert.","example2En":"After the lost game, everyone was frustrated."},{"de":"führen","en":"to lead; to run/manage; to carry (goods)","pos":"verb","plural":"","meanings":[{"en":"to lead or guide someone/something","de":"jemanden oder etwas leiten oder anführen"},{"en":"to manage or run a business or organization","de":"ein Geschäft oder eine Organisation leiten"},{"en":"to stock/carry (of a shop)","de":"eine Ware im Sortiment haben"}],"rule":"Regular weak verb: führt, führte, hat geführt. Often + Akkusativ; 'ein Geschäft führen' = to run a shop.","example":"Der Guide führt die Touristen durch die Stadt.","exampleEn":"The guide leads the tourists through the city.","example2":"Dieser Laden führt keine Bio-Produkte.","example2En":"This shop doesn't carry organic products."},{"de":"das Führungszeugnis","en":"certificate of good conduct","pos":"noun","plural":"die Führungszeugnisse","meanings":[{"en":"an official document showing a person has no criminal record","de":"ein amtliches Dokument, das belegt, dass jemand nicht vorbestraft ist"}],"rule":"Compound: Führung + Zeugnis; neuter noun, often required 'polizeiliches Führungszeugnis' for job applications.","example":"Für die Stelle braucht sie ein polizeiliches Führungszeugnis.","exampleEn":"For the job she needs a certificate of good conduct.","example2":"Er hat das Führungszeugnis beim Amt beantragt.","example2En":"He applied for the certificate of good conduct at the office."},{"de":"furchtbar","en":"terrible, awful","pos":"adjective","plural":"","meanings":[{"en":"very bad or unpleasant","de":"sehr schlecht oder unangenehm"},{"en":"used colloquially to intensify (extremely)","de":"umgangssprachlich verstärkend: sehr"}],"rule":"Regular adjective, comparison: furchtbar, furchtbarer, am furchtbarsten; often used as intensifying adverb ('furchtbar müde').","example":"Das Wetter war heute furchtbar.","exampleEn":"The weather was terrible today.","example2":"Ich bin furchtbar müde.","example2En":"I am terribly tired."},{"de":"der Fußballclub","en":"football club","pos":"noun","plural":"die Fußballclubs","meanings":[{"en":"a club organized around playing football","de":"ein Verein, der Fußball spielt"}],"rule":"Compound: Fußball + Club; masculine noun, plural -s (loanword Club). Also spelled 'Fußballklub'.","example":"Mein Sohn spielt in einem Fußballclub.","exampleEn":"My son plays in a football club.","example2":"Der Fußballclub sucht neue Mitglieder.","example2En":"The football club is looking for new members."},{"de":"füttern","en":"to feed (an animal or baby)","pos":"verb","plural":"","meanings":[{"en":"to give food to an animal or a baby","de":"einem Tier oder Baby Futter/Essen geben"}],"rule":"Regular weak verb: füttert, fütterte, hat gefüttert. + Akkusativ.","example":"Sie füttert jeden Morgen die Katze.","exampleEn":"She feeds the cat every morning.","example2":"Er füttert das Baby mit einem Löffel.","example2En":"He feeds the baby with a spoon."},{"de":"der Gang","en":"walk/gait; corridor; gear (car)","pos":"noun","plural":"die Gänge","meanings":[{"en":"way of walking","de":"die Art zu gehen"},{"en":"corridor/hallway","de":"der Flur"},{"en":"gear in a car","de":"die Schaltstufe im Auto"}],"rule":"Masculine noun; plural die Gänge. Common in fixed phrases: 'in Gang setzen' (to start something), 'den ersten Gang einlegen' (to put it in first gear).","example":"Der Gang zum Bahnhof dauert zehn Minuten.","exampleEn":"The walk to the station takes ten minutes.","example2":"Bitte leg den zweiten Gang ein.","example2En":"Please put it into second gear."},{"de":"garantieren","en":"to guarantee","pos":"verb","plural":"","meanings":[{"en":"to guarantee something","de":"für etwas sicher einstehen"}],"rule":"Regular weak verb; garantiert, garantierte, hat garantiert. Often used with 'für' + Akkusativ: garantieren für etwas.","example":"Der Hersteller garantiert die Qualität des Produkts.","exampleEn":"The manufacturer guarantees the quality of the product.","example2":"Ich kann dir nicht garantieren, dass alles klappt.","example2En":"I can't guarantee you that everything will work out."},{"de":"der Gastarbeiter / die Gastarbeiterin","en":"guest worker (foreign labor migrant)","pos":"noun","plural":"die Gastarbeiter / die Gastarbeiterinnen","meanings":[{"en":"a foreign worker, especially historical migrant labor in Germany","de":"ein ausländischer Arbeitnehmer"}],"rule":"Compound of Gast + Arbeiter; historical term from the 1950s-70s German labor migration programs.","example":"Viele Gastarbeiter kamen in den 1960er-Jahren nach Deutschland.","exampleEn":"Many guest workers came to Germany in the 1960s.","example2":"Seine Großmutter war Gastarbeiterin in einer Fabrik.","example2En":"His grandmother was a guest worker in a factory."},{"de":"das Gate","en":"gate (airport)","pos":"noun","plural":"die Gates","meanings":[{"en":"airport boarding gate","de":"der Flugsteig"}],"rule":"Neuter loanword from English; plural die Gates. Common in airport/travel context.","example":"Der Flug nach Berlin startet an Gate 12.","exampleEn":"The flight to Berlin departs from gate 12.","example2":"Wir müssen noch schnell zum Gate laufen.","example2En":"We still have to hurry to the gate."},{"de":"der Gebrauchtwagen","en":"used car","pos":"noun","plural":"die Gebrauchtwagen","meanings":[{"en":"a second-hand car","de":"ein bereits benutztes Auto"}],"rule":"Compound noun: gebraucht (used) + Wagen (car); masculine, plural unchanged (die Gebrauchtwagen).","example":"Er hat einen günstigen Gebrauchtwagen gekauft.","exampleEn":"He bought a cheap used car.","example2":"Der Gebrauchtwagenhändler bietet eine Garantie an.","example2En":"The used-car dealer offers a warranty."},{"de":"der Gedanke","en":"thought, idea","pos":"noun","plural":"die Gedanken","meanings":[{"en":"a thought or idea","de":"eine Idee im Kopf"}],"rule":"Masculine, irregular (n-declension): Akkusativ/Dativ den/dem Gedanken, Genitiv des Gedankens; plural die Gedanken.","example":"Ich kann meine Gedanken nicht ordnen.","exampleEn":"I can't organize my thoughts.","example2":"Das ist ein guter Gedanke!","example2En":"That's a good idea!"},{"de":"die Geduld","en":"patience","pos":"noun","plural":"","meanings":[{"en":"the ability to wait calmly","de":"die Fähigkeit, ruhig zu warten"}],"rule":"Feminine, uncountable noun (no plural). Common phrase: Geduld haben (to have patience).","example":"Hab noch etwas Geduld, es dauert nicht mehr lange.","exampleEn":"Have a little more patience, it won't take much longer.","example2":"Mit Kindern braucht man viel Geduld.","example2En":"You need a lot of patience with children."},{"de":"geduldig","en":"patient","pos":"adjective","plural":"","meanings":[{"en":"able to wait calmly without complaint","de":"mit Geduld, ruhig wartend"}],"rule":"Regular adjective, regular comparison: geduldig, geduldiger, am geduldigsten.","example":"Die Lehrerin ist sehr geduldig mit den Schülern.","exampleEn":"The teacher is very patient with the students.","example2":"Sei geduldig, das Essen ist gleich fertig.","example2En":"Be patient, the food will be ready soon."},{"de":"das Gefühl","en":"feeling, emotion","pos":"noun","plural":"die Gefühle","meanings":[{"en":"an emotion","de":"eine Emotion"},{"en":"a sense/intuition about something","de":"eine Vorahnung oder Ahnung"}],"rule":"Neuter noun; plural die Gefühle. Common phrase: ein gutes/schlechtes Gefühl haben.","example":"Sie zeigt ihre Gefühle nicht gern.","exampleEn":"She doesn't like to show her feelings.","example2":"Ich habe das Gefühl, dass etwas nicht stimmt.","example2En":"I have a feeling that something is wrong."},{"de":"der Gegenstand","en":"object, item; subject/topic","pos":"noun","plural":"die Gegenstände","meanings":[{"en":"a physical object","de":"ein Ding, eine Sache"},{"en":"the subject or topic of discussion","de":"das Thema einer Diskussion"}],"rule":"Masculine noun; plural die Gegenstände. In formal contexts: Gegenstand der Diskussion (subject of discussion).","example":"Bitte legen Sie alle Gegenstände auf den Tisch.","exampleEn":"Please put all objects on the table.","example2":"Das war der Gegenstand unseres Gesprächs.","example2En":"That was the subject of our conversation."},{"de":"der Gegenvorschlag","en":"counterproposal","pos":"noun","plural":"die Gegenvorschläge","meanings":[{"en":"an alternative proposal made in response to another","de":"ein alternativer Vorschlag als Antwort auf einen anderen"}],"rule":"Compound: Gegen- (counter-) + Vorschlag (proposal); masculine, plural die Gegenvorschläge.","example":"Die Kollegin machte einen Gegenvorschlag zum Zeitplan.","exampleEn":"The colleague made a counterproposal to the schedule.","example2":"Wir sollten über seinen Gegenvorschlag nachdenken.","example2En":"We should think about his counterproposal."},{"de":"der Gegner / die Gegnerin","en":"opponent, adversary","pos":"noun","plural":"die Gegner / die Gegnerinnen","meanings":[{"en":"a person who opposes or competes against someone","de":"jemand, der gegen jemanden kämpft oder konkurriert"}],"rule":"Masculine/feminine pair noun; plural die Gegner / die Gegnerinnen. Used in sports, debates, politics.","example":"Im Finale trifft er auf einen starken Gegner.","exampleEn":"In the final he faces a strong opponent.","example2":"Sie ist eine entschiedene Gegnerin dieses Plans.","example2En":"She is a firm opponent of this plan."},{"de":"das Gehalt","en":"salary","pos":"noun","plural":"die Gehälter","meanings":[{"en":"the fixed monthly pay from an employer","de":"das monatliche Einkommen von der Arbeit"}],"rule":"Neuter noun; irregular plural die Gehälter (umlaut). Do not confuse with 'der Gehalt' (content/proportion, e.g. Fettgehalt), which is a different, masculine word.","example":"Ihr Gehalt wurde dieses Jahr erhöht.","exampleEn":"Her salary was raised this year.","example2":"Das Gehalt wird am Monatsende überwiesen.","example2En":"The salary is transferred at the end of the month."},{"de":"die Gehaltsvorstellung","en":"salary expectation","pos":"noun","plural":"die Gehaltsvorstellungen","meanings":[{"en":"the salary an applicant expects or requests","de":"das gewünschte Gehalt eines Bewerbers"}],"rule":"Compound: Gehalt + Vorstellung; feminine, plural die Gehaltsvorstellungen. Typical in job applications: 'Bitte geben Sie Ihre Gehaltsvorstellung an.'","example":"Bitte nennen Sie Ihre Gehaltsvorstellung im Anschreiben.","exampleEn":"Please state your salary expectation in the cover letter.","example2":"Seine Gehaltsvorstellung war dem Chef zu hoch.","example2En":"His salary expectation was too high for the boss."},{"de":"die Gemeinsamkeit","en":"common ground, similarity","pos":"noun","plural":"die Gemeinsamkeiten","meanings":[{"en":"something two people or things have in common","de":"etwas, das zwei Personen oder Dinge gemeinsam haben"}],"rule":"Feminine noun; plural die Gemeinsamkeiten. Often used: Gemeinsamkeiten haben/finden.","example":"Die beiden Freunde haben viele Gemeinsamkeiten.","exampleEn":"The two friends have a lot in common.","example2":"Wir suchten nach Gemeinsamkeiten zwischen den Kulturen.","example2En":"We looked for similarities between the cultures."},{"de":"der Gemeinschaftsraum","en":"common room, shared space","pos":"noun","plural":"die Gemeinschaftsräume","meanings":[{"en":"a shared room used by a group, e.g. in a dorm or building","de":"ein gemeinsam genutzter Raum"}],"rule":"Compound: Gemeinschaft + Raum; masculine, plural die Gemeinschaftsräume.","example":"Im Wohnheim gibt es einen Gemeinschaftsraum mit Küche.","exampleEn":"There is a common room with a kitchen in the dorm.","example2":"Abends treffen sich die Bewohner im Gemeinschaftsraum.","example2En":"In the evening the residents meet in the common room."},{"de":"der Gemüsehändler / die Gemüsehändlerin","en":"vegetable seller, greengrocer","pos":"noun","plural":"die Gemüsehändler / die Gemüsehändlerinnen","meanings":[{"en":"a person who sells vegetables","de":"jemand, der Gemüse verkauft"}],"rule":"Compound: Gemüse + Händler/Händlerin; plural die Gemüsehändler / die Gemüsehändlerinnen.","example":"Der Gemüsehändler auf dem Markt hat frisches Obst.","exampleEn":"The greengrocer at the market has fresh fruit.","example2":"Ich kaufe mein Gemüse immer bei der Gemüsehändlerin nebenan.","example2En":"I always buy my vegetables from the greengrocer next door."},{"de":"das Gepäck","en":"luggage, baggage","pos":"noun","plural":"","meanings":[{"en":"bags and suitcases for travel","de":"Koffer und Taschen für die Reise"}],"rule":"Neuter, uncountable noun (no plural). Common compounds: Handgepäck (carry-on), Gepäckaufgabe (baggage check-in).","example":"Wir müssen unser Gepäck am Schalter aufgeben.","exampleEn":"We have to check in our luggage at the counter.","example2":"Er hat sein Gepäck am Flughafen verloren.","example2En":"He lost his luggage at the airport."},{"de":"die Gepäckausgabe","en":"baggage claim","pos":"noun","plural":"die Gepäckausgaben","meanings":[{"en":"place where luggage is returned to passengers","de":"Ort, an dem man sein Gepäck nach dem Flug/der Fahrt abholt"}],"rule":"Zusammensetzung aus 'Gepäck' + 'Ausgabe'; meist am Flughafen oder Bahnhof.","example":"Wir warten am Flughafen auf die Gepäckausgabe.","exampleEn":"We are waiting at the airport for baggage claim.","example2":"Die Koffer kommen erst nach 20 Minuten zur Gepäckausgabe.","example2En":"The suitcases only arrive at baggage claim after 20 minutes."},{"de":"das Gepäckband","en":"baggage carousel","pos":"noun","plural":"die Gepäckbänder","meanings":[{"en":"conveyor belt that carries luggage to passengers","de":"Förderband, auf dem das Gepäck ankommt"}],"rule":"Zusammensetzung aus 'Gepäck' + 'Band'; Plural mit Umlaut: die Gepäckbänder.","example":"Mein Koffer dreht sich schon auf dem Gepäckband.","exampleEn":"My suitcase is already going around on the baggage carousel.","example2":"Stell dich nicht zu nah ans Gepäckband.","example2En":"Don't stand too close to the baggage carousel."},{"de":"der Geruch","en":"smell; odor","pos":"noun","plural":"die Gerüche","meanings":[{"en":"smell/odor (neutral or pleasant)","de":"das, was man riecht"},{"en":"bad smell/stench","de":"unangenehmer Geruch"}],"rule":"Plural mit Umlaut: die Gerüche; von 'riechen' abgeleitet.","example":"Der Geruch von frischem Brot kommt aus der Küche.","exampleEn":"The smell of fresh bread is coming from the kitchen.","example2":"Im Treppenhaus hängt ein seltsamer Geruch.","example2En":"There's a strange smell in the stairwell."},{"de":"die Geschäftsbedingungen","en":"terms and conditions","pos":"noun","plural":"die Geschäftsbedingungen","meanings":[{"en":"contractual terms of a company (often 'Allgemeine Geschäftsbedingungen', AGB)","de":"vertragliche Bedingungen eines Unternehmens"}],"rule":"Nur Plural gebräuchlich; oft als Abkürzung AGB (Allgemeine Geschäftsbedingungen).","example":"Bitte lesen Sie unsere Geschäftsbedingungen, bevor Sie bestellen.","exampleEn":"Please read our terms and conditions before you order.","example2":"Mit dem Klick akzeptieren Sie die Geschäftsbedingungen.","example2En":"By clicking, you accept the terms and conditions."},{"de":"der Geschäftsführer / die Geschäftsführerin","en":"managing director; CEO","pos":"noun","plural":"die Geschäftsführer / die Geschäftsführerinnen","meanings":[{"en":"person who manages/runs a company","de":"Person, die eine Firma leitet"}],"rule":"Movierung mit -in für die weibliche Form; abgeleitet von 'Geschäft' + 'führen'.","example":"Der Geschäftsführer hat die neue Strategie vorgestellt.","exampleEn":"The managing director presented the new strategy.","example2":"Frau Klein ist seit einem Jahr Geschäftsführerin der Firma.","example2En":"Ms. Klein has been the managing director of the company for a year."},{"de":"die Geschäftsführung","en":"management; executive board","pos":"noun","plural":"die Geschäftsführungen","meanings":[{"en":"act of managing a business","de":"das Leiten eines Unternehmens"},{"en":"the management team/leadership of a company","de":"die Leitung einer Firma als Personengruppe"}],"rule":"Meist Singular verwendet, auch wenn mehrere Personen gemeint sind.","example":"Die Geschäftsführung trifft sich jeden Montag.","exampleEn":"The management meets every Monday.","example2":"Er ist seit Jahren in der Geschäftsführung tätig.","example2En":"He has worked in management for years."},{"de":"der Geschmack","en":"taste; flavor","pos":"noun","plural":"die Geschmäcker","meanings":[{"en":"flavor of food or drink","de":"wie etwas schmeckt"},{"en":"personal taste/preference (style)","de":"persönlicher Stil oder Vorliebe"}],"rule":"Plural mit Umlaut: die Geschmäcker; von 'schmecken' abgeleitet.","example":"Die Suppe hat einen leicht scharfen Geschmack.","exampleEn":"The soup has a slightly spicy taste.","example2":"Das ist nicht mein Geschmack, aber schön gemacht.","example2En":"That's not my taste, but it's well made."},{"de":"gesetzlich","en":"legal; statutory","pos":"adjective","plural":"","meanings":[{"en":"required or defined by law","de":"vom Gesetz vorgeschrieben oder geregelt"}],"rule":"Keine unregelmäßige Steigerung; oft in Verbindung mit Substantiven wie 'gesetzliche Pflicht', 'gesetzlicher Feiertag'.","example":"Der 1. Mai ist ein gesetzlicher Feiertag.","exampleEn":"May 1st is a legal holiday.","example2":"Arbeitnehmer haben ein gesetzliches Recht auf Urlaub.","example2En":"Employees have a legal right to vacation."},{"de":"gestattet sein","en":"to be permitted/allowed","pos":"phrase","plural":"","meanings":[{"en":"to be officially permitted","de":"erlaubt sein"}],"rule":"Formelles Register, oft auf Schildern; 'gestattet' ist Partizip II von 'gestatten' (+ Dativ der Person).","example":"Hier ist das Rauchen nicht gestattet.","exampleEn":"Smoking is not permitted here.","example2":"Der Zutritt ist nur Mitarbeitern gestattet.","example2En":"Entry is only permitted for employees."},{"de":"das Gesundheitszeugnis","en":"health certificate","pos":"noun","plural":"die Gesundheitszeugnisse","meanings":[{"en":"official document confirming good health, often required for work with food","de":"amtliches Dokument, das die Gesundheit bestätigt, z. B. für Arbeit mit Lebensmitteln"}],"rule":"Zusammensetzung aus 'Gesundheit' + 'Zeugnis'; oft im Gastgewerbe nötig (§43 Infektionsschutzgesetz).","example":"Für die Arbeit in der Küche braucht sie ein Gesundheitszeugnis.","exampleEn":"For work in the kitchen, she needs a health certificate.","example2":"Das Gesundheitszeugnis ist beim Gesundheitsamt zu beantragen.","example2En":"The health certificate must be applied for at the health department."},{"de":"das Getreide","en":"grain; cereal","pos":"noun","plural":"","meanings":[{"en":"cereal crops such as wheat, rye, oats","de":"Pflanzen wie Weizen, Roggen, Hafer"}],"rule":"Unzählbar, kein Plural; Kollektivbegriff für Feldfrüchte wie Weizen und Roggen.","example":"Das Getreide wird im Sommer geerntet.","exampleEn":"The grain is harvested in summer.","example2":"Brot wird aus Getreide hergestellt.","example2En":"Bread is made from grain."},{"de":"gewährleisten","en":"to guarantee; to ensure","pos":"verb","plural":"","meanings":[{"en":"to guarantee something (formal)","de":"formell: sicherstellen, garantieren"}],"rule":"Regelmäßig, untrennbar: gewährleistet, gewährleistete, hat gewährleistet; formelles Register (kein trennbares Verb, kein 'ge-' im Partizip).","example":"Der Hersteller gewährleistet die Sicherheit des Produkts.","exampleEn":"The manufacturer guarantees the safety of the product.","example2":"Wir können einen pünktlichen Beginn leider nicht gewährleisten.","example2En":"Unfortunately, we cannot guarantee a punctual start."},{"de":"die Gewohnheit","en":"habit","pos":"noun","plural":"die Gewohnheiten","meanings":[{"en":"a regular, repeated behavior","de":"etwas, das man regelmäßig tut"}],"rule":"Von 'gewohnt sein' abgeleitet; feste Wendung: 'aus Gewohnheit'.","example":"Er trinkt aus Gewohnheit jeden Morgen Kaffee.","exampleEn":"He drinks coffee every morning out of habit.","example2":"Schlechte Gewohnheiten sind schwer zu ändern.","example2En":"Bad habits are hard to change."},{"de":"das Gewürz","en":"spice; seasoning","pos":"noun","plural":"die Gewürze","meanings":[{"en":"substance used to flavor food","de":"etwas, das Speisen würzt, z. B. Pfeffer, Salz"}],"rule":"Von 'würzen' abgeleitet; regelmäßiger Plural die Gewürze.","example":"Pfeffer und Salz sind die wichtigsten Gewürze.","exampleEn":"Pepper and salt are the most important spices.","example2":"Das Gericht braucht noch etwas mehr Gewürz.","example2En":"The dish needs a bit more seasoning."},{"de":"giftig","en":"poisonous; toxic","pos":"adjective","plural":"","meanings":[{"en":"harmful if eaten, touched or inhaled","de":"gefährlich, weil es Gift enthält"},{"en":"figuratively: spiteful, venomous (words, remarks)","de":"übertragen: bösartig, gehässig (z. B. eine Bemerkung)"}],"rule":"Keine unregelmäßige Steigerung: giftig, giftiger, am giftigsten.","example":"Dieser Pilz ist giftig und darf nicht gegessen werden.","exampleEn":"This mushroom is poisonous and must not be eaten.","example2":"Sie machte eine giftige Bemerkung über ihren Kollegen.","example2En":"She made a spiteful remark about her colleague."},{"de":"gleichzeitig","en":"simultaneous; at the same time","pos":"adjective","plural":"","meanings":[{"en":"happening at the same time","de":"zur selben Zeit (geschehend)"}],"rule":"Wird oft als Adverb gebraucht; keine unregelmäßige Steigerung.","example":"Sie kann nicht telefonieren und gleichzeitig kochen.","exampleEn":"She can't talk on the phone and cook at the same time.","example2":"Beide Ereignisse fanden gleichzeitig statt.","example2En":"Both events took place simultaneously."},{"de":"glutenfrei","en":"gluten-free","pos":"adjective","plural":"","meanings":[{"en":"containing no gluten","de":"ohne Gluten (Klebereiweiß in Getreide)"}],"rule":"Zusammensetzung aus 'Gluten' + '-frei'; keine unregelmäßige Steigerung.","example":"Sie isst nur glutenfreies Brot.","exampleEn":"She only eats gluten-free bread.","example2":"Gibt es hier auch glutenfreie Nudeln?","example2En":"Do you also have gluten-free pasta here?"},{"de":"das Golf","en":"golf","pos":"noun","plural":"","meanings":[{"en":"the sport of golf","de":"Ballsportart auf dem Golfplatz"}],"rule":"Unzählbar, kein Plural; Achtung: 'der Golf' bedeutet dagegen 'gulf/bay' (Genus unterscheidet die Bedeutung).","example":"Am Wochenende spielt er gern Golf.","exampleEn":"He likes to play golf on weekends.","example2":"Sie hat einen Kurs genommen, um Golf zu lernen.","example2En":"She took a course to learn golf."},{"de":"die Grenze","en":"border; limit","pos":"noun","plural":"die Grenzen","meanings":[{"en":"border (between countries)","de":"Landesgrenze"},{"en":"limit (of ability, tolerance)","de":"das Äußerste, Limit"}],"rule":"Feminine noun, plural -n. 'an der Grenze' (at the border); 'an seine Grenzen kommen' (to reach one's limits).","example":"Wir fahren morgen über die Grenze nach Polen.","exampleEn":"Tomorrow we're driving across the border into Poland.","example2":"Irgendwann sind auch meine Kräfte an ihre Grenzen gekommen.","example2En":"At some point even my strength reached its limits."},{"de":"gründen","en":"to found, to establish","pos":"verb","plural":"","meanings":[{"en":"to found/establish (a company, organization)","de":"etwas neu schaffen, ins Leben rufen"}],"rule":"Regular weak verb: gründet, gründete, hat gegründet. Often with Akkusativ: eine Firma gründen.","example":"Die beiden Freunde haben zusammen eine Firma gegründet.","exampleEn":"The two friends founded a company together.","example2":"1949 wurde die Bundesrepublik Deutschland gegründet.","example2En":"In 1949 the Federal Republic of Germany was founded."},{"de":"grundsätzlich","en":"fundamental(ly); in principle","pos":"adjective","plural":"","meanings":[{"en":"fundamental/basic","de":"im Prinzip, im Grunde"},{"en":"as a rule, generally","de":"generell, prinzipiell"}],"rule":"Regular adjective/adverb, no irregular comparison. Often used as a sentence adverb: 'Grundsätzlich bin ich einverstanden.'","example":"Das ist eine grundsätzliche Frage, die wir klären müssen.","exampleEn":"That is a fundamental question we need to clarify.","example2":"Ich trinke grundsätzlich keinen Alkohol.","example2En":"As a rule, I don't drink alcohol."},{"de":"der Gutschein","en":"voucher, coupon","pos":"noun","plural":"die Gutscheine","meanings":[{"en":"voucher / gift certificate","de":"ein Papier, mit dem man etwas kostenlos oder billiger bekommt"}],"rule":"Masculine noun, plural -e. Compound: Geschenkgutschein (gift voucher).","example":"Zum Geburtstag hat sie mir einen Gutschein für das Kino geschenkt.","exampleEn":"For my birthday she gave me a voucher for the cinema.","example2":"Diesen Gutschein kann man nur online einlösen.","example2En":"This voucher can only be redeemed online."},{"de":"die Haftpflicht","en":"liability","pos":"noun","plural":"","meanings":[{"en":"legal liability (for damages)","de":"gesetzliche Pflicht, für einen Schaden zu zahlen"}],"rule":"Feminine noun, usually uncountable. In everyday speech, 'Haftpflicht' is often used as a short form of 'Haftpflichtversicherung'.","example":"Der Verursacher eines Unfalls trägt die Haftpflicht für den entstandenen Schaden.","exampleEn":"The person who caused the accident bears liability for the resulting damage.","example2":"Die Haftpflicht des Mieters ist im Vertrag geregelt.","example2En":"The tenant's liability is regulated in the contract."},{"de":"die Haftpflichtversicherung","en":"liability insurance","pos":"noun","plural":"die Haftpflichtversicherungen","meanings":[{"en":"liability insurance","de":"eine Versicherung, die für Schäden zahlt, die man anderen zufügt"}],"rule":"Feminine noun, plural -en. Common types: Kfz-Haftpflichtversicherung (car), Privathaftpflichtversicherung (personal).","example":"Jeder Autobesitzer braucht eine Haftpflichtversicherung.","exampleEn":"Every car owner needs liability insurance.","example2":"Meine Haftpflichtversicherung hat den Schaden am fremden Auto bezahlt.","example2En":"My liability insurance paid for the damage to the other car."},{"de":"der Hagel","en":"hail","pos":"noun","plural":"","meanings":[{"en":"hail (ice pellets falling as precipitation)","de":"kleine Eiskörner, die bei einem Gewitter vom Himmel fallen"}],"rule":"Masculine noun, uncountable (no plural). Related verb: hageln (es hagelt).","example":"Gestern gab es ein Gewitter mit starkem Hagel.","exampleEn":"Yesterday there was a thunderstorm with heavy hail.","example2":"Der Hagel hat viele Autos beschädigt.","example2En":"The hail damaged many cars."}]},{"id":"b1-09","title":"B1 · H–J (9)","level":"B1","words":[{"de":"die Halbpension","en":"half board","pos":"noun","plural":"","meanings":[{"en":"half board (breakfast + one main meal included)","de":"Übernachtung mit Frühstück und einer weiteren Mahlzeit"}],"rule":"Feminine noun, usually uncountable; common hotel abbreviation 'HP'. Contrast with Vollpension (full board).","example":"Wir haben das Hotelzimmer mit Halbpension gebucht.","exampleEn":"We booked the hotel room with half board.","example2":"Bei HP bekommt man Frühstück und Abendessen.","example2En":"With half board you get breakfast and dinner."},{"de":"hämmern","en":"to hammer","pos":"verb","plural":"","meanings":[{"en":"to hammer (hit with a hammer)","de":"mit einem Hammer schlagen"},{"en":"to pound, throb (heart, pain)","de":"heftig und laut schlagen"}],"rule":"Regular weak verb: hämmert, hämmerte, hat gehämmert.","example":"Der Nachbar hämmert schon seit einer Stunde an der Wand.","exampleEn":"The neighbor has been hammering on the wall for an hour already.","example2":"Nach dem Lauf hämmerte ihr Herz.","example2En":"After the run her heart was pounding."},{"de":"der Handball","en":"handball","pos":"noun","plural":"die Handbälle","meanings":[{"en":"handball (the sport / the ball)","de":"eine Ballsportart mit den Händen"}],"rule":"Masculine noun, plural -bälle (like Ball, Bälle). Common collocation: 'Handball spielen' (to play handball).","example":"Mein Sohn spielt jeden Dienstag Handball im Verein.","exampleEn":"My son plays handball at the club every Tuesday.","example2":"Sie hat sich beim Handball am Finger verletzt.","example2En":"She injured her finger while playing handball."},{"de":"das Handgepäck","en":"hand luggage, carry-on","pos":"noun","plural":"","meanings":[{"en":"hand luggage / carry-on baggage","de":"Gepäck, das man im Flugzeug bei sich trägt"}],"rule":"Neuter noun, uncountable. Common in travel contexts: 'nur Handgepäck'.","example":"Ich reise nur mit Handgepäck, um Zeit zu sparen.","exampleEn":"I travel with only hand luggage to save time.","example2":"Am Flughafen wurde mein Handgepäck kontrolliert.","example2En":"At the airport my carry-on was checked."},{"de":"die Handlung","en":"action; plot","pos":"noun","plural":"die Handlungen","meanings":[{"en":"action, act, deed","de":"das, was jemand tut"},{"en":"plot (of a book/film)","de":"die Geschichte in einem Buch oder Film"}],"rule":"Feminine noun, plural -en. Related to the verb handeln (to act).","example":"Seine schnelle Handlung hat dem Verletzten das Leben gerettet.","exampleEn":"His quick action saved the injured person's life.","example2":"Die Handlung des Films spielt im 19. Jahrhundert.","example2En":"The film's plot is set in the 19th century."},{"de":"der Handwerker / die Handwerkerin","en":"craftsman, tradesperson","pos":"noun","plural":"die Handwerker / die Handwerkerinnen","meanings":[{"en":"craftsman/tradesperson (e.g. plumber, electrician, carpenter)","de":"jemand, der ein handwerkliches Gewerbe ausübt"}],"rule":"Masculine noun der Handwerker, feminine die Handwerkerin, plural die Handwerker / die Handwerkerinnen.","example":"Wir haben einen Handwerker für die Reparatur der Heizung bestellt.","exampleEn":"We called a tradesman to repair the heating.","example2":"Die Handwerkerin hat die neuen Fliesen im Bad verlegt.","example2En":"The craftswoman laid the new tiles in the bathroom."},{"de":"hart","en":"hard","pos":"adjective","plural":"","meanings":[{"en":"hard (physical firmness)","de":"fest, nicht weich"},{"en":"hard, tough (difficult, harsh)","de":"schwierig, streng"}],"rule":"Irregular comparison: hart, härter, am härtesten.","example":"Das Brot ist schon ganz hart geworden.","exampleEn":"The bread has already gone quite hard.","example2":"Er hat eine harte Kindheit gehabt.","example2En":"He had a hard childhood."},{"de":"der Hartweizen","en":"durum wheat","pos":"noun","plural":"","meanings":[{"en":"durum wheat (used for pasta)","de":"eine harte Weizensorte, aus der Nudeln gemacht werden"}],"rule":"Masculine noun, usually uncountable. Common in food labeling: 'Hartweizengrieß'.","example":"Gute Pasta wird aus Hartweizen hergestellt.","exampleEn":"Good pasta is made from durum wheat.","example2":"Auf der Packung steht: 100 % Hartweizen.","example2En":"The package says: 100% durum wheat."},{"de":"die Haselnuss","en":"hazelnut","pos":"noun","plural":"die Haselnüsse","meanings":[{"en":"hazelnut","de":"die Frucht des Haselnussstrauchs"}],"rule":"Feminine noun, plural with umlaut, like Nuss → Nüsse.","example":"Im Herbst sammeln die Kinder Haselnüsse im Wald.","exampleEn":"In autumn the children collect hazelnuts in the forest.","example2":"Diese Schokolade enthält gemahlene Haselnüsse.","example2En":"This chocolate contains ground hazelnuts."},{"de":"häufig","en":"frequent(ly)","pos":"adjective","plural":"","meanings":[{"en":"frequent, common","de":"oft vorkommend"}],"rule":"Regular adjective/adverb, no irregular comparison (häufig, häufiger, am häufigsten). Similar to 'oft' but more formal.","example":"Kopfschmerzen sind eine häufige Nebenwirkung dieses Medikaments.","exampleEn":"Headaches are a frequent side effect of this medication.","example2":"Er ist in letzter Zeit häufig krank.","example2En":"He has been frequently ill lately."},{"de":"der Hauptgrund","en":"main reason","pos":"noun","plural":"die Hauptgründe","meanings":[{"en":"main reason","de":"der wichtigste Grund für etwas"}],"rule":"Masculine noun, plural -e (like Grund, Gründe). Compound of Haupt- (main) + Grund (reason).","example":"Der Hauptgrund für seinen Umzug war der neue Job.","exampleEn":"The main reason for his move was the new job.","example2":"Was war der Hauptgrund für eure Entscheidung?","example2En":"What was the main reason for your decision?"},{"de":"die Hauptstadt","en":"capital city","pos":"noun","plural":"die Hauptstädte","meanings":[{"en":"capital city of a country/state","de":"wichtigste Stadt eines Landes"}],"rule":"Compound: Haupt- (main) + Stadt; genitive: der Hauptstadt.","example":"Berlin ist die Hauptstadt von Deutschland.","exampleEn":"Berlin is the capital of Germany.","example2":"Welche Stadt ist die Hauptstadt von Österreich?","example2En":"Which city is the capital of Austria?"},{"de":"der Haushalt","en":"household; budget","pos":"noun","plural":"die Haushalte","meanings":[{"en":"household (home and its members)","de":"Wohnung/Familie und ihr Leben zusammen"},{"en":"budget (of a state, family, etc.)","de":"geplante Einnahmen und Ausgaben"}],"rule":"Also used as 'den Haushalt machen' = to do the housework.","example":"In unserem Haushalt leben vier Personen.","exampleEn":"Four people live in our household.","example2":"Die Regierung plant den Haushalt für nächstes Jahr.","example2En":"The government is planning next year's budget."},{"de":"die Heimat","en":"home country; homeland","pos":"noun","plural":"","meanings":[{"en":"the place/country one feels is home","de":"Land oder Ort, wo man sich zu Hause fühlt"}],"rule":"Usually uncountable, no plural; emotional word, stronger than 'Land'.","example":"Meine Heimat ist ein kleines Dorf in Bayern.","exampleEn":"My home is a small village in Bavaria.","example2":"Nach zehn Jahren im Ausland vermisst sie ihre Heimat.","example2En":"After ten years abroad, she misses her homeland."},{"de":"das Heimweh","en":"homesickness","pos":"noun","plural":"","meanings":[{"en":"longing to be back home","de":"Sehnsucht nach zu Hause"}],"rule":"Uncountable; used with 'haben': Heimweh haben (nach + Dativ).","example":"Im ersten Monat hatte er starkes Heimweh.","exampleEn":"In the first month he was very homesick.","example2":"Sie bekommt Heimweh, wenn sie zu lange verreist ist.","example2En":"She gets homesick when she travels for too long."},{"de":"heizen","en":"to heat","pos":"verb","plural":"","meanings":[{"en":"to heat a room/house","de":"Wärme erzeugen, warm machen"}],"rule":"Regular weak verb: heizt, heizte, hat geheizt.","example":"Im Winter heizen wir die Wohnung mit Gas.","exampleEn":"In winter we heat the apartment with gas.","example2":"Bitte heiz nicht so viel, das kostet Geld.","example2En":"Please don't heat so much, it costs money."},{"de":"die Heizkosten","en":"heating costs","pos":"noun","plural":"","meanings":[{"en":"costs for heating a home","de":"Kosten fürs Heizen"}],"rule":"Plural-only noun (like 'Kosten'), built from heizen + Kosten; no singular form is used.","example":"Die Heizkosten sind in diesem Winter stark gestiegen.","exampleEn":"Heating costs have risen sharply this winter.","example2":"Wir sparen Heizkosten, indem wir die Fenster gut isolieren.","example2En":"We save on heating costs by insulating the windows well."},{"de":"die Herausforderung","en":"challenge","pos":"noun","plural":"die Herausforderungen","meanings":[{"en":"a demanding task or situation","de":"schwierige Aufgabe, die Mühe kostet"}],"rule":"From 'herausfordern' (to challenge); often with 'eine Herausforderung sein für + Akk'.","example":"Die neue Stelle ist eine große Herausforderung für mich.","exampleEn":"The new job is a big challenge for me.","example2":"Er sucht immer neue Herausforderungen im Beruf.","example2En":"He always looks for new challenges at work."},{"de":"herkommen","en":"to come from; to come here","pos":"verb","plural":"","meanings":[{"en":"to originate from (a place)","de":"woher stammen"},{"en":"to come to this place","de":"hierher kommen"}],"rule":"Trennbar: kommt her, kam her, ist hergekommen.","example":"Wo kommst du eigentlich her?","exampleEn":"Where do you actually come from?","example2":"Komm bitte her, ich möchte dir etwas zeigen.","example2En":"Please come here, I want to show you something."},{"de":"das Herkunftsland","en":"country of origin","pos":"noun","plural":"die Herkunftsländer","meanings":[{"en":"the country a person or product comes from","de":"Land, aus dem jemand/etwas stammt"}],"rule":"Compound: Herkunft (origin) + Land.","example":"Sein Herkunftsland ist Syrien.","exampleEn":"His country of origin is Syria.","example2":"Auf der Verpackung steht das Herkunftsland des Produkts.","example2En":"The product's country of origin is stated on the packaging."},{"de":"herstellen","en":"to manufacture, produce","pos":"verb","plural":"","meanings":[{"en":"to manufacture/produce goods","de":"produzieren, fertigen"},{"en":"to establish (contact, connection)","de":"aufbauen, schaffen (z.B. Kontakt)"}],"rule":"Trennbar: stellt her, stellte her, hat hergestellt.","example":"Diese Firma stellt Autoteile her.","exampleEn":"This company manufactures car parts.","example2":"Wir müssen den Kontakt zum Kunden wieder herstellen.","example2En":"We need to re-establish contact with the customer."},{"de":"die Herstellung","en":"manufacture, production","pos":"noun","plural":"die Herstellungen","meanings":[{"en":"the process of producing/manufacturing something","de":"das Produzieren, Fertigen"}],"rule":"Noun from 'herstellen'; often used in singular; genitive: der Herstellung.","example":"Die Herstellung des Produkts dauert zwei Wochen.","exampleEn":"The manufacture of the product takes two weeks.","example2":"Bei der Herstellung wird viel Energie verbraucht.","example2En":"A lot of energy is used during production."},{"de":"das Herz","en":"heart","pos":"noun","plural":"die Herzen","meanings":[{"en":"the organ that pumps blood","de":"Organ, das Blut pumpt"},{"en":"figurative: feelings, inner self","de":"Gefühl, Inneres eines Menschen"}],"rule":"Irregular declension: des Herzens (genitive), dem Herzen (dative), das Herz (accusative).","example":"Ihr Herz schlägt sehr schnell nach dem Sport.","exampleEn":"Her heart beats very fast after sports.","example2":"Er hat ein gutes Herz und hilft gern anderen.","example2En":"He has a good heart and likes to help others."},{"de":"hierher","en":"to here, over here","pos":"adverb","plural":"","meanings":[{"en":"movement towards the speaker's location","de":"an diesen Ort (Richtung zum Sprecher)"}],"rule":"Directional adverb, used with verbs of motion: komm hierher!","example":"Komm bitte hierher, ich brauche deine Hilfe.","exampleEn":"Please come here, I need your help.","example2":"Wie bist du hierher gekommen?","example2En":"How did you get here?"},{"de":"hilfsbereit","en":"helpful, willing to help","pos":"adjective","plural":"","meanings":[{"en":"always ready to help others","de":"immer bereit zu helfen"}],"rule":"Compound adjective: Hilfe + bereit; regular comparison: hilfsbereiter, am hilfsbereitesten.","example":"Meine Nachbarn sind sehr hilfsbereit.","exampleEn":"My neighbors are very helpful.","example2":"Er ist immer hilfsbereit, wenn jemand Probleme hat.","example2En":"He is always ready to help when someone has problems."},{"de":"historisch","en":"historical","pos":"adjective","plural":"","meanings":[{"en":"relating to history","de":"die Geschichte betreffend"},{"en":"historic, of great importance","de":"bedeutsam, epochal"}],"rule":"Regular comparison: historischer, am historischsten.","example":"Die Altstadt hat viele historische Gebäude.","exampleEn":"The old town has many historical buildings.","example2":"Das war ein historischer Moment für das Land.","example2En":"That was a historic moment for the country."},{"de":"das Hochwasser","en":"flood, high water","pos":"noun","plural":"die Hochwasser","meanings":[{"en":"flooding caused by rising water levels","de":"stark angestiegenes Wasser, Überschwemmung"}],"rule":"Compound: hoch + Wasser; plural rarely used, mostly singular.","example":"Nach dem starken Regen gab es Hochwasser in der Stadt.","exampleEn":"After the heavy rain there was flooding in the city.","example2":"Das Hochwasser hat viele Häuser beschädigt.","example2En":"The flood damaged many houses."},{"de":"der Hörer / die Hörerin","en":"listener; (phone) receiver","pos":"noun","plural":"die Hörer / die Hörerinnen","meanings":[{"en":"a person who listens (e.g. radio listener)","de":"Person, die zuhört, z.B. Radiohörer"},{"en":"telephone receiver/handset","de":"Teil des Telefons zum Sprechen und Hören"}],"rule":"Person noun der/die from 'hören'; 'der Hörer' also means phone receiver (no feminine form for that sense).","example":"Viele Hörer riefen bei der Radiosendung an.","exampleEn":"Many listeners called in during the radio show.","example2":"Sie nahm den Hörer ab und sagte 'Hallo'.","example2En":"She picked up the receiver and said 'Hello'."},{"de":"der Horrorfilm","en":"horror film","pos":"noun","plural":"die Horrorfilme","meanings":[{"en":"a film intended to frighten viewers","de":"Film, der Angst machen soll"}],"rule":"Compound: Horror + Film; regular masculine noun.","example":"Ich schaue gern Horrorfilme am Abend.","exampleEn":"I like watching horror films in the evening.","example2":"Dieser Horrorfilm ist mir zu gruselig.","example2En":"This horror film is too scary for me."},{"de":"das Hostel","en":"hostel","pos":"noun","plural":"die Hostels","meanings":[{"en":"cheap accommodation for travelers","de":"billige Unterkunft für Reisende"}],"rule":"Neutrum; oft im Kontext von Jugendherbergen/Reisen; Plural mit -s.","example":"Wir haben ein billiges Hostel in der Nähe des Bahnhofs gefunden.","exampleEn":"We found a cheap hostel near the train station.","example2":"Im Hostel teilen wir uns ein Zimmer mit anderen Reisenden.","example2En":"At the hostel we share a room with other travelers."},{"de":"der Hügel","en":"hill","pos":"noun","plural":"die Hügel","meanings":[{"en":"hill (small elevation of land)","de":"kleine Erhebung im Gelände"}],"rule":"Maskulin; Plural unverändert (der Hügel – die Hügel).","example":"Von dem Hügel aus hat man eine schöne Aussicht auf das Dorf.","exampleEn":"From the hill you have a nice view of the village.","example2":"Wir sind auf den Hügel gewandert.","example2En":"We hiked up the hill."},{"de":"die Hülsenfrucht","en":"legume, pulse","pos":"noun","plural":"die Hülsenfrüchte","meanings":[{"en":"legume/pulse (e.g. beans, lentils)","de":"Pflanze mit Hülsen, z. B. Bohnen, Linsen"}],"rule":"Femininum; Plural die Hülsenfrüchte; häufig in Ernährungs-/Gesundheitsthemen.","example":"Linsen und Bohnen sind gesunde Hülsenfrüchte.","exampleEn":"Lentils and beans are healthy legumes.","example2":"Der Arzt empfiehlt, mehr Hülsenfrüchte zu essen.","example2En":"The doctor recommends eating more legumes."},{"de":"hygienisch","en":"hygienic","pos":"adjective","plural":"","meanings":[{"en":"hygienic, clean and healthy","de":"sauber und gesundheitlich unbedenklich"}],"rule":"Regelmäßige Steigerung: hygienisch, hygienischer, am hygienischsten.","example":"In diesem Restaurant ist alles sehr hygienisch.","exampleEn":"Everything in this restaurant is very hygienic.","example2":"Im Krankenhaus muss das Personal besonders hygienisch arbeiten.","example2En":"In the hospital, the staff must work especially hygienically."},{"de":"das Impressum","en":"legal notice, imprint","pos":"noun","plural":"die Impressen","meanings":[{"en":"legal notice/imprint on a website or publication","de":"gesetzlich vorgeschriebene Angaben zum Herausgeber"}],"rule":"Neutrum; Plural selten gebraucht (die Impressen); typisch bei Websites/Zeitschriften.","example":"Im Impressum findet man die Adresse des Unternehmens.","exampleEn":"In the legal notice you can find the company's address.","example2":"Jede Website braucht in Deutschland ein Impressum.","example2En":"In Germany every website needs a legal notice."},{"de":"indem","en":"by (doing something)","pos":"conjunction","plural":"","meanings":[{"en":"by means of, by (doing sth.) — introduces the way something is done","de":"drückt aus, wie/wodurch etwas geschieht"}],"rule":"Leitet Nebensatz ein, Verb steht am Ende; beschreibt Mittel/Methode.","example":"Ich lerne Deutsch, indem ich jeden Tag Vokabeln übe.","exampleEn":"I learn German by practicing vocabulary every day.","example2":"Er spart Geld, indem er seltener essen geht.","example2En":"He saves money by going out to eat less often."},{"de":"individuell","en":"individual, personal","pos":"adjective","plural":"","meanings":[{"en":"individual, personalized","de":"auf eine einzelne Person bezogen, persönlich"}],"rule":"Regelmäßige Steigerung: individuell, individueller, am individuellsten.","example":"Jeder Kunde bekommt eine individuelle Beratung.","exampleEn":"Every customer gets individual advice.","example2":"Die Kurse lassen sich individuell anpassen.","example2En":"The courses can be adapted individually."},{"de":"die Industrie","en":"industry","pos":"noun","plural":"die Industrien","meanings":[{"en":"industry (economic sector)","de":"Wirtschaftszweig der Produktion"}],"rule":"Femininum; Plural die Industrien (z. B. verschiedene Branchen).","example":"Die Autoindustrie ist wichtig für Deutschland.","exampleEn":"The car industry is important for Germany.","example2":"In dieser Region gibt es viel Industrie.","example2En":"There is a lot of industry in this region."},{"de":"industriell","en":"industrial","pos":"adjective","plural":"","meanings":[{"en":"industrial, related to industry","de":"die Industrie betreffend"}],"rule":"Beziehungsadjektiv (industriell vs. nicht-industriell); in der Regel nicht steigerbar.","example":"Die Produkte werden industriell hergestellt.","exampleEn":"The products are manufactured industrially.","example2":"Die Stadt hat sich zu einem industriellen Zentrum entwickelt.","example2En":"The city has developed into an industrial center."},{"de":"das Inlineskaten","en":"inline skating","pos":"noun","plural":"","meanings":[{"en":"inline skating (sport/activity)","de":"Sportart mit Inlineskates"}],"rule":"Neutrum, substantiviertes Verb; unzählbar, kein Plural.","example":"Im Sommer gehen wir oft Inlineskaten im Park.","exampleEn":"In summer we often go inline skating in the park.","example2":"Inlineskaten ist ein gutes Training für die Beine.","example2En":"Inline skating is good training for your legs."},{"de":"innerhalb","en":"within, inside of","pos":"preposition","plural":"","meanings":[{"en":"within (a period of time)","de":"innerhalb eines Zeitraums"},{"en":"inside (a place)","de":"im Inneren eines Ortes"}],"rule":"Präposition + Genitiv (innerhalb des Monats); bei Substantiven ohne erkennbaren Genitiv oder im Plural oft mit 'von' + Dativ (innerhalb von zwei Wochen).","example":"Bitte antworten Sie innerhalb einer Woche.","exampleEn":"Please reply within a week.","example2":"Innerhalb des Gebäudes darf man nicht rauchen.","example2En":"You are not allowed to smoke inside the building."},{"de":"insofern","en":"in that respect, to that extent","pos":"adverb","plural":"","meanings":[{"en":"in that respect, to that extent","de":"in dieser Hinsicht, in diesem Sinn"}],"rule":"Oft mit 'als' kombiniert (insofern als ...); leitet Einschränkung/Begründung ein.","example":"Der Plan ist gut, insofern er realistisch ist.","exampleEn":"The plan is good, insofar as it is realistic.","example2":"Insofern hast du recht.","example2En":"In that respect, you are right."},{"de":"die Instandhaltung","en":"maintenance","pos":"noun","plural":"die Instandhaltungen","meanings":[{"en":"maintenance, upkeep (of machines, buildings)","de":"Pflege und Reparatur von Anlagen oder Gebäuden"}],"rule":"Femininum; Plural selten, meist im Singular verwendet.","example":"Die Instandhaltung der Maschinen kostet viel Geld.","exampleEn":"The maintenance of the machines costs a lot of money.","example2":"Die Firma ist für die Instandhaltung der Gebäude zuständig.","example2En":"The company is responsible for the maintenance of the buildings."},{"de":"die Institution","en":"institution","pos":"noun","plural":"die Institutionen","meanings":[{"en":"institution (organization, establishment)","de":"öffentliche oder soziale Einrichtung"}],"rule":"Femininum; Plural die Institutionen.","example":"Die Universität ist eine wichtige Institution der Stadt.","exampleEn":"The university is an important institution in the city.","example2":"Viele staatliche Institutionen sind heute online erreichbar.","example2En":"Many state institutions can now be reached online."},{"de":"intern","en":"internal","pos":"adjective","plural":"","meanings":[{"en":"internal (within an organization or group)","de":"innerhalb einer Organisation, nicht öffentlich"}],"rule":"Kategorisches Adjektiv (intern vs. extern); in der Regel nicht steigerbar.","example":"Das ist eine interne Angelegenheit der Firma.","exampleEn":"That is an internal matter of the company.","example2":"Die Mitarbeiter bekommen die Informationen intern per E-Mail.","example2En":"The employees receive the information internally by email."},{"de":"inzwischen","en":"meanwhile, by now","pos":"adverb","plural":"","meanings":[{"en":"meanwhile, in the meantime","de":"in der Zwischenzeit"},{"en":"by now, already","de":"bis jetzt, mittlerweile"}],"rule":"Zeitadverb; oft mit Perfekt/Präsens kombiniert.","example":"Koch das Wasser auf, ich decke inzwischen den Tisch.","exampleEn":"Boil the water, meanwhile I'll set the table.","example2":"Er wohnt inzwischen schon seit fünf Jahren in Berlin.","example2En":"By now he has been living in Berlin for five years."},{"de":"irgendwann","en":"someday, at some point","pos":"adverb","plural":"","meanings":[{"en":"someday, sometime, at some point","de":"zu einem unbestimmten Zeitpunkt"}],"rule":"Unbestimmtes Zeitadverb; kann sich auf Zukunft oder Vergangenheit beziehen.","example":"Irgendwann möchte ich nach Australien reisen.","exampleEn":"Someday I want to travel to Australia.","example2":"Wir haben uns irgendwann letztes Jahr kennengelernt.","example2En":"We met at some point last year."},{"de":"irgendwelche","en":"some, any (kind of)","pos":"pronoun","plural":"","meanings":[{"en":"some, any (unspecified, plural/uncountable)","de":"unbestimmte, nicht genauer bezeichnete"}],"rule":"Unbestimmtes Pronomen, Pluralform von irgendein(e); wird dekliniert (irgendwelchen, irgendwelcher...).","example":"Hast du irgendwelche Fragen dazu?","exampleEn":"Do you have any questions about it?","example2":"Ruf mich an, wenn es irgendwelche Probleme gibt.","example2En":"Call me if there are any problems."},{"de":"irgendwer","en":"someone (or other)","pos":"pronoun","plural":"","meanings":[{"en":"someone, anyone (unspecified)","de":"eine beliebige, nicht genannte Person"}],"rule":"Indefinite pronoun formed from irgend- + wer; declines like wer: irgendwer (Nom.), irgendwen (Akk.), irgendwem (Dat.). Synonym: irgendjemand (slightly more formal/common register).","example":"Irgendwer hat meine Tasche mitgenommen.","exampleEn":"Someone took my bag.","example2":"Frag doch irgendwen, der hier arbeitet.","example2En":"Just ask someone who works here."},{"de":"irgendwie","en":"somehow","pos":"adverb","plural":"","meanings":[{"en":"somehow, in some way","de":"auf eine nicht genau bestimmte Weise"},{"en":"kind of, sort of (vague impression)","de":"irgendwie (umgangssprachlich: ein bisschen)"}],"rule":"Common filler word in spoken German to soften a statement; not separable, no conjugation.","example":"Wir schaffen das schon irgendwie.","exampleEn":"We'll manage it somehow.","example2":"Das Essen schmeckt irgendwie komisch.","example2En":"The food tastes kind of strange."},{"de":"jahrelang","en":"for years","pos":"adjective","plural":"","meanings":[{"en":"lasting for years","de":"über viele Jahre dauernd"}],"rule":"Can be used as attributive adjective or adverb; no irregular comparison (rarely compared).","example":"Sie haben jahrelang zusammengearbeitet.","exampleEn":"They worked together for years.","example2":"Nach jahrelanger Pause spielt er wieder Fußball.","example2En":"After a years-long break he plays football again."}]},{"id":"b1-10","title":"B1 · J–K (10)","level":"B1","words":[{"de":"das Jahrhundert","en":"century","pos":"noun","plural":"die Jahrhunderte","meanings":[{"en":"a period of 100 years","de":"Zeitraum von 100 Jahren"}],"rule":"Neuter noun, compound of Jahr + Hundert.","example":"Das Gebäude ist aus dem 19. Jahrhundert.","exampleEn":"The building is from the 19th century.","example2":"Im letzten Jahrhundert hat sich viel verändert.","example2En":"A lot has changed in the last century."},{"de":"das Jahrzehnt","en":"decade","pos":"noun","plural":"die Jahrzehnte","meanings":[{"en":"a period of 10 years","de":"Zeitraum von 10 Jahren"}],"rule":"Neuter noun formed from Jahr + zehn (ten) with the suffix -t; not related to the unrelated word 'Zehnt' (tithe).","example":"In den letzten Jahrzehnten hat sich die Technik stark verändert.","exampleEn":"Technology has changed a lot in the last decades.","example2":"Das war das erfolgreichste Jahrzehnt seiner Karriere.","example2En":"That was the most successful decade of his career."},{"de":"die Jobbezeichnung","en":"job title","pos":"noun","plural":"die Jobbezeichnungen","meanings":[{"en":"the official name of a job/position","de":"offizieller Name einer Stelle oder Tätigkeit"}],"rule":"Feminine noun, compound of Job + Bezeichnung.","example":"Wie lautet deine genaue Jobbezeichnung?","exampleEn":"What is your exact job title?","example2":"Die Jobbezeichnung steht im Arbeitsvertrag.","example2En":"The job title is stated in the employment contract."},{"de":"der Jude / die Jüdin","en":"Jewish person","pos":"noun","plural":"die Juden / die Jüdinnen","meanings":[{"en":"a person of Jewish faith or identity","de":"Person jüdischen Glaubens oder jüdischer Herkunft"}],"rule":"Masculine weak noun (der Jude, den/dem/des Juden); feminine die Jüdin, plural die Jüdinnen.","example":"Er ist als Jude in Berlin aufgewachsen.","exampleEn":"He grew up as a Jew in Berlin.","example2":"Die Jüdin erzählte von ihrer Familiengeschichte.","example2En":"The Jewish woman talked about her family history."},{"de":"die Jugendherberge","en":"youth hostel","pos":"noun","plural":"die Jugendherbergen","meanings":[{"en":"a cheap place to stay overnight, often for young travelers/groups","de":"günstige Übernachtungsmöglichkeit, oft für Jugendliche/Gruppen"}],"rule":"Feminine noun, compound of Jugend + Herberge.","example":"Wir übernachten in einer Jugendherberge am See.","exampleEn":"We are staying overnight in a youth hostel by the lake.","example2":"Die Jugendherberge bietet günstige Zimmer für Gruppen.","example2En":"The youth hostel offers cheap rooms for groups."},{"de":"der Kaffeefilter","en":"coffee filter","pos":"noun","plural":"die Kaffeefilter","meanings":[{"en":"paper/reusable filter for making coffee","de":"Filter zum Aufbrühen von Kaffee"}],"rule":"Masculine noun, compound of Kaffee + Filter.","example":"Wir haben keine Kaffeefilter mehr zu Hause.","exampleEn":"We don't have any coffee filters left at home.","example2":"Leg einen neuen Kaffeefilter in die Maschine.","example2En":"Put a new coffee filter in the machine."},{"de":"der Kamm","en":"comb","pos":"noun","plural":"die Kämme","meanings":[{"en":"a tool for tidying hair","de":"Gerät zum Ordnen der Haare"}],"rule":"Masculine noun with umlaut plural.","example":"Sie kämmt sich die Haare mit einem Kamm.","exampleEn":"She combs her hair with a comb.","example2":"Hast du einen Kamm dabei?","example2En":"Do you have a comb with you?"},{"de":"der Kandidat / die Kandidatin","en":"candidate","pos":"noun","plural":"die Kandidaten / die Kandidatinnen","meanings":[{"en":"someone applying for a job or running in an election","de":"Person, die sich bewirbt oder zur Wahl antritt"}],"rule":"Masculine weak noun (der Kandidat, den/dem/des Kandidaten); feminine die Kandidatin.","example":"Der Kandidat hat die Prüfung bestanden.","exampleEn":"The candidate passed the exam.","example2":"Drei Kandidatinnen bewerben sich um die Stelle.","example2En":"Three female candidates are applying for the position."},{"de":"die Kaskoversicherung","en":"comprehensive car insurance","pos":"noun","plural":"die Kaskoversicherungen","meanings":[{"en":"insurance covering damage to one's own vehicle","de":"Versicherung, die Schäden am eigenen Fahrzeug abdeckt"}],"rule":"Feminine noun, compound of Kasko + Versicherung.","example":"Für das neue Auto braucht er eine Kaskoversicherung.","exampleEn":"He needs comprehensive insurance for the new car.","example2":"Die Kaskoversicherung zahlt auch bei selbst verschuldeten Unfällen.","example2En":"The comprehensive insurance also pays for accidents you caused yourself."},{"de":"der Katalog","en":"catalogue","pos":"noun","plural":"die Kataloge","meanings":[{"en":"a printed or online list of products/items","de":"gedrucktes oder digitales Verzeichnis von Waren"}],"rule":"Masculine noun, regular plural with -e.","example":"Sie bestellt die Möbel aus einem Katalog.","exampleEn":"She orders the furniture from a catalogue.","example2":"Der neue Katalog liegt im Briefkasten.","example2En":"The new catalogue is in the mailbox."},{"de":"der Kauf","en":"purchase","pos":"noun","plural":"die Käufe","meanings":[{"en":"the act of buying something","de":"das Erwerben einer Ware gegen Geld"}],"rule":"Masculine noun with umlaut plural; related verb kaufen.","example":"Der Kauf des Hauses war eine gute Entscheidung.","exampleEn":"The purchase of the house was a good decision.","example2":"Beim Kauf sollte man den Preis vergleichen.","example2En":"When buying, you should compare the price."},{"de":"die Kaufbestätigung","en":"purchase confirmation","pos":"noun","plural":"die Kaufbestätigungen","meanings":[{"en":"written confirmation that a purchase was made","de":"schriftlicher Nachweis über einen getätigten Kauf"}],"rule":"Feminine noun, compound of Kauf + Bestätigung.","example":"Bitte bewahren Sie die Kaufbestätigung auf.","exampleEn":"Please keep the purchase confirmation.","example2":"Die Kaufbestätigung wurde ihm per E-Mail geschickt.","example2En":"The purchase confirmation was sent to him by email."},{"de":"der Käufer / die Käuferin","en":"buyer","pos":"noun","plural":"die Käufer / die Käuferinnen","meanings":[{"en":"a person who buys something","de":"Person, die etwas kauft"}],"rule":"Masculine noun derived from kaufen; feminine die Käuferin.","example":"Der Käufer zahlt den Betrag in bar.","exampleEn":"The buyer pays the amount in cash.","example2":"Die Käuferin prüft das Auto vor dem Kauf.","example2En":"The buyer (female) checks the car before the purchase."},{"de":"der Kaufvertrag","en":"purchase contract","pos":"noun","plural":"die Kaufverträge","meanings":[{"en":"a legal contract for buying/selling something","de":"rechtlicher Vertrag über Kauf und Verkauf einer Sache"}],"rule":"Masculine noun, compound of Kauf + Vertrag, umlaut plural.","example":"Beide unterschreiben den Kaufvertrag.","exampleEn":"Both sign the purchase contract.","example2":"Im Kaufvertrag stehen alle wichtigen Bedingungen.","example2En":"All important terms are in the purchase contract."},{"de":"kaum","en":"hardly, scarcely","pos":"adverb","plural":"","meanings":[{"en":"hardly, barely (almost not)","de":"fast nicht"},{"en":"no sooner ... than (temporal contrast in 'kaum ... als/da')","de":"kaum ... als/da: unmittelbar danach geschah etwas anderes"}],"rule":"Common adverb of degree, often with a negative/limiting sense: kaum + Verb. In the temporal construction 'kaum ... als/da', kaum triggers inversion (verb right after kaum), e.g. 'Kaum war sie zu Hause, klingelte das Telefon.'","example":"Er hat kaum Zeit für Hobbys.","exampleEn":"He hardly has time for hobbies.","example2":"Kaum war sie zu Hause, klingelte das Telefon.","example2En":"Hardly had she gotten home when the phone rang."},{"de":"der Kilometer","en":"kilometer","pos":"noun","plural":"die Kilometer","meanings":[{"en":"unit of distance (1000 m)","de":"Längeneinheit, 1000 Meter"}],"rule":"Plural unverändert: der Kilometer, die Kilometer. Abkürzung: km. Als Maßeinheit bleibt die Form nach Zahlen gleich: zwei Kilometer (nicht 'Kilometers').","example":"Der Bahnhof ist zwei Kilometer von hier entfernt.","exampleEn":"The train station is two kilometers from here.","example2":"Wir sind heute zehn Kilometer gelaufen.","example2En":"We walked ten kilometers today."},{"de":"die Kindheit","en":"childhood","pos":"noun","plural":"","meanings":[{"en":"the period of being a child","de":"die Zeit, in der man ein Kind ist"}],"rule":"Meist nur im Singular verwendet (uncountable). Oft mit Präpositionen: in meiner Kindheit.","example":"Sie hat eine glückliche Kindheit gehabt.","exampleEn":"She had a happy childhood.","example2":"In seiner Kindheit hat er oft auf dem Land gelebt.","example2En":"In his childhood he often lived in the countryside."},{"de":"kippen","en":"to tip over; to tilt","pos":"verb","plural":"","meanings":[{"en":"to tip over / fall sideways","de":"umfallen, aus dem Gleichgewicht geraten"},{"en":"to tilt / pour out by tilting","de":"etwas schräg stellen und ausleeren"}],"rule":"Regelmäßig: kippt, kippte, ist/hat gekippt. Intransitiv (umfallen) mit 'sein', transitiv (etwas kippen) mit 'haben'. Nicht mit 'umkippen' (trennbares Verb) verwechseln.","example":"Pass auf, die Leiter kippt gleich!","exampleEn":"Careful, the ladder is about to tip over!","example2":"Er hat das Wasser aus dem Eimer gekippt.","example2En":"He tipped the water out of the bucket."},{"de":"klettern","en":"to climb","pos":"verb","plural":"","meanings":[{"en":"to climb (using hands and feet)","de":"mit Händen und Füßen nach oben steigen"}],"rule":"Regelmäßig: klettert, kletterte, ist geklettert (Bewegungsverb mit 'sein').","example":"Die Kinder klettern gern auf Bäume.","exampleEn":"The children like climbing trees.","example2":"Wir sind am Wochenende in den Bergen geklettert.","example2En":"We went climbing in the mountains at the weekend."},{"de":"das Klima","en":"climate","pos":"noun","plural":"die Klimas","meanings":[{"en":"the typical weather of a region","de":"das typische Wetter einer Region über lange Zeit"},{"en":"atmosphere/mood (figurative)","de":"die Stimmung, Atmosphäre"}],"rule":"Meist im Singular verwendet. Plural im Alltag 'die Klimas', fachsprachlich 'die Klimate'.","example":"In Spanien ist das Klima wärmer als in Deutschland.","exampleEn":"The climate in Spain is warmer than in Germany.","example2":"Im Büro herrscht ein sehr gutes Klima.","example2En":"There is a very good atmosphere in the office."},{"de":"der Klimawandel","en":"climate change","pos":"noun","plural":"","meanings":[{"en":"long-term change in global climate patterns","de":"die langfristige Veränderung des Klimas"}],"rule":"Meist nur Singular verwendet. Zusammensetzung aus Klima + Wandel.","example":"Der Klimawandel ist eines der größten Probleme unserer Zeit.","exampleEn":"Climate change is one of the biggest problems of our time.","example2":"Viele Länder wollen etwas gegen den Klimawandel tun.","example2En":"Many countries want to take action against climate change."},{"de":"klug","en":"clever, intelligent","pos":"adjective","plural":"","meanings":[{"en":"intelligent, smart","de":"intelligent, schlau"}],"rule":"Komparation regelmäßig: klug, klüger, am klügsten (Umlaut!).","example":"Sie ist eine sehr kluge Studentin.","exampleEn":"She is a very clever student.","example2":"Das war keine kluge Entscheidung.","example2En":"That wasn't a smart decision."},{"de":"das Kochbuch","en":"cookbook","pos":"noun","plural":"die Kochbücher","meanings":[{"en":"a book with recipes","de":"ein Buch mit Rezepten"}],"rule":"Zusammensetzung aus kochen + Buch; Plural wie Buch → Bücher.","example":"Ich habe mir ein neues Kochbuch gekauft.","exampleEn":"I bought myself a new cookbook.","example2":"Das Rezept steht in meinem alten Kochbuch.","example2En":"The recipe is in my old cookbook."},{"de":"der Kofferraum","en":"car trunk/boot","pos":"noun","plural":"die Kofferräume","meanings":[{"en":"the storage compartment of a car","de":"der Stauraum im Auto für Gepäck"}],"rule":"Zusammensetzung aus Koffer + Raum; Plural wie Raum → Räume.","example":"Leg die Taschen bitte in den Kofferraum.","exampleEn":"Please put the bags in the trunk.","example2":"Der Kofferraum ist voll mit Einkäufen.","example2En":"The trunk is full of groceries."},{"de":"komfortabel","en":"comfortable","pos":"adjective","plural":"","meanings":[{"en":"providing comfort and convenience","de":"bequem, mit viel Komfort"}],"rule":"Regelmäßig: komfortabel, komfortabler, am komfortabelsten (bei Deklination entfällt das zweite e: ein komfortables Auto).","example":"Das Hotelzimmer war sehr komfortabel.","exampleEn":"The hotel room was very comfortable.","example2":"Wir suchen ein komfortables Auto für die lange Fahrt.","example2En":"We are looking for a comfortable car for the long drive."},{"de":"der Kommentator / die Kommentatorin","en":"commentator","pos":"noun","plural":"die Kommentatoren / die Kommentatorinnen","meanings":[{"en":"a person who gives commentary, e.g. on TV/radio","de":"jemand, der z. B. im Fernsehen ein Ereignis kommentiert"}],"rule":"Maskulines Substantiv auf -or: Plural mit Betonungsverschiebung: der Kommentator, die Kommentatoren.","example":"Der Kommentator beschreibt das Fußballspiel im Radio.","exampleEn":"The commentator describes the football match on the radio.","example2":"Die Kommentatorin war bei den Olympischen Spielen sehr beliebt.","example2En":"The commentator was very popular at the Olympic Games."},{"de":"der Kommissar / die Kommissarin","en":"police inspector/commissioner","pos":"noun","plural":"die Kommissare / die Kommissarinnen","meanings":[{"en":"a senior police officer investigating crimes","de":"ein hoher Polizeibeamter, der Verbrechen aufklärt"}],"rule":"Maskulin -e Plural: der Kommissar, die Kommissare.","example":"Der Kommissar ermittelt in einem Mordfall.","exampleEn":"The inspector is investigating a murder case.","example2":"Die Kommissarin hat den Täter schnell gefasst.","example2En":"The inspector caught the culprit quickly."},{"de":"die Kommunikationsstärke","en":"strong communication skills","pos":"noun","plural":"","meanings":[{"en":"the ability to communicate well","de":"die Fähigkeit, gut zu kommunizieren"}],"rule":"Nur Singular; häufig in Bewerbungen/Stellenanzeigen verwendet.","example":"Für diese Stelle ist Kommunikationsstärke sehr wichtig.","exampleEn":"Strong communication skills are very important for this job.","example2":"Sie überzeugt im Vorstellungsgespräch durch ihre Kommunikationsstärke.","example2En":"She impresses in the job interview with her strong communication skills."},{"de":"kommunikativ","en":"communicative","pos":"adjective","plural":"","meanings":[{"en":"good at communicating, sociable","de":"gesprächsbereit, gut im Umgang mit anderen"}],"rule":"Regelmäßige Steigerung: kommunikativ, kommunikativer, am kommunikativsten.","example":"Er ist sehr kommunikativ und redet gern mit Kunden.","exampleEn":"He is very communicative and likes talking to customers.","example2":"Für den Job sucht man eine kommunikative Person.","example2En":"For the job they are looking for a communicative person."},{"de":"die Komödie","en":"comedy","pos":"noun","plural":"die Komödien","meanings":[{"en":"a funny film, play, or book","de":"ein lustiges Theaterstück oder ein lustiger Film"}],"rule":"Feminin, Plural auf -n: die Komödie, die Komödien.","example":"Wir haben gestern eine lustige Komödie im Kino gesehen.","exampleEn":"We saw a funny comedy at the cinema yesterday.","example2":"Das Theater spielt diese Woche eine bekannte Komödie.","example2En":"This week the theater is performing a well-known comedy."},{"de":"der Konferenzraum","en":"conference room","pos":"noun","plural":"die Konferenzräume","meanings":[{"en":"a room used for meetings/conferences","de":"ein Raum für Besprechungen und Konferenzen"}],"rule":"Zusammensetzung aus Konferenz + Raum; Plural wie Raum → Räume.","example":"Das Meeting findet im Konferenzraum im ersten Stock statt.","exampleEn":"The meeting takes place in the conference room on the first floor.","example2":"Der Konferenzraum ist mit einem Beamer ausgestattet.","example2En":"The conference room is equipped with a projector."},{"de":"der Konflikt","en":"conflict","pos":"noun","plural":"die Konflikte","meanings":[{"en":"a serious disagreement or clash","de":"ein ernster Streit oder Gegensatz"}],"rule":"Maskulin, Plural auf -e: der Konflikt, die Konflikte.","example":"Zwischen den Kollegen gibt es einen Konflikt wegen der Arbeitszeiten.","exampleEn":"There is a conflict between the colleagues about working hours.","example2":"Man sollte Konflikte offen ansprechen und lösen.","example2En":"One should address and resolve conflicts openly."},{"de":"der König / die Königin","en":"king / queen","pos":"noun","plural":"die Könige / die Königinnen","meanings":[{"en":"male/female monarch ruling a kingdom","de":"der Herrscher / die Herrscherin eines Königreichs"}],"rule":"Maskulin Plural auf -e: der König, die Könige (kein zusätzlicher Umlaut, da der Stammvokal ö schon im Singular steht); feminin Plural auf -nen: die Königin, die Königinnen.","example":"Der König lebt in einem großen Schloss.","exampleEn":"The king lives in a large castle.","example2":"Die Königin hat gestern eine wichtige Rede gehalten.","example2En":"The queen gave an important speech yesterday."},{"de":"die Konservendose","en":"tin can","pos":"noun","plural":"die Konservendosen","meanings":[{"en":"a sealed metal can for preserved food","de":"eine Dose aus Metall für haltbar gemachte Lebensmittel"}],"rule":"Compound: Konserve (preserve) + Dose (can/tin); feminine like Dose.","example":"Ich habe noch eine Konservendose mit Bohnen im Schrank.","exampleEn":"I still have a can of beans in the cupboard.","example2":"Öffne bitte die Konservendose mit dem Dosenöffner.","example2En":"Please open the tin can with the can opener."},{"de":"die Kontaktdaten","en":"contact details","pos":"noun","plural":"die Kontaktdaten","meanings":[{"en":"information such as address, phone, email for reaching someone","de":"Adresse, Telefonnummer, E-Mail usw. zum Erreichen einer Person"}],"rule":"Used only in plural (Pluraletantum); compound of Kontakt + Daten.","example":"Bitte geben Sie Ihre Kontaktdaten auf dem Formular an.","exampleEn":"Please give your contact details on the form.","example2":"Ich habe seine Kontaktdaten verloren.","example2En":"I lost his contact details."},{"de":"die Kopie","en":"copy","pos":"noun","plural":"die Kopien","meanings":[{"en":"a reproduction/duplicate of a document","de":"ein Duplikat eines Dokuments"}],"rule":"Feminine noun; often used with 'eine Kopie machen/erstellen'.","example":"Kannst du mir eine Kopie von dem Vertrag machen?","exampleEn":"Can you make me a copy of the contract?","example2":"Ich brauche eine Kopie meines Passes.","example2En":"I need a copy of my passport."},{"de":"der Kopierer","en":"photocopier","pos":"noun","plural":"die Kopierer","meanings":[{"en":"a machine that makes copies of documents","de":"ein Gerät, das Dokumente kopiert"}],"rule":"Masculine noun; derived from kopieren (to copy).","example":"Der Kopierer im Büro ist schon wieder kaputt.","exampleEn":"The photocopier in the office is broken again.","example2":"Kannst du die Seiten am Kopierer kopieren?","example2En":"Can you copy the pages on the copier?"},{"de":"korrekt","en":"correct","pos":"adjective","plural":"","meanings":[{"en":"free of errors, right","de":"richtig, fehlerfrei"},{"en":"proper, appropriate in behavior","de":"angemessen, ordentlich"}],"rule":"Regular comparison: korrekt, korrekter, am korrektesten.","example":"Ihre Antwort war völlig korrekt.","exampleEn":"Her answer was completely correct.","example2":"Er hat sich immer sehr korrekt verhalten.","example2En":"He always behaved very properly."},{"de":"die Kosmetik","en":"cosmetics","pos":"noun","plural":"","meanings":[{"en":"beauty products and skincare","de":"Schönheitsprodukte und Hautpflege"}],"rule":"Uncountable feminine noun, no plural.","example":"Sie kauft ihre Kosmetik immer in der Drogerie.","exampleEn":"She always buys her cosmetics at the drugstore.","example2":"Er interessiert sich nicht für Kosmetik.","example2En":"He isn't interested in cosmetics."},{"de":"krachen","en":"to crash, to bang","pos":"verb","plural":"","meanings":[{"en":"to make a loud crashing noise","de":"einen lauten Knall machen"},{"en":"(colloquial) to have a fight/argument","de":"(umgangssprachlich) sich streiten"}],"rule":"Regular weak verb: kracht, krachte, hat gekracht. Can take 'sein' when describing movement/collision (ist gekracht).","example":"Der Donner krachte laut über dem Haus.","exampleEn":"The thunder crashed loudly over the house.","example2":"Die beiden Autos sind ineinander gekracht.","example2En":"The two cars crashed into each other."},{"de":"der Kratzer","en":"scratch","pos":"noun","plural":"die Kratzer","meanings":[{"en":"a small mark or cut on a surface","de":"eine kleine Beschädigung auf einer Oberfläche"}],"rule":"Masculine noun; plural same as singular form.","example":"Das Auto hat einen Kratzer an der Tür.","exampleEn":"The car has a scratch on the door.","example2":"Ich habe mir einen Kratzer am Arm geholt.","example2En":"I got a scratch on my arm."},{"de":"der Krieg","en":"war","pos":"noun","plural":"die Kriege","meanings":[{"en":"an armed conflict between states or groups","de":"ein bewaffneter Konflikt zwischen Staaten oder Gruppen"}],"rule":"Masculine noun; common expression 'im Krieg' (in the war).","example":"Der Krieg dauerte mehrere Jahre.","exampleEn":"The war lasted several years.","example2":"Viele Menschen mussten wegen des Krieges fliehen.","example2En":"Many people had to flee because of the war."},{"de":"das Kriegsende","en":"end of the war","pos":"noun","plural":"die Kriegsenden","meanings":[{"en":"the point when a war stops","de":"der Zeitpunkt, an dem ein Krieg endet"}],"rule":"Compound: Krieg + Ende; gender follows Ende (das).","example":"Nach dem Kriegsende kehrten viele Soldaten nach Hause zurück.","exampleEn":"After the end of the war, many soldiers returned home.","example2":"Das Kriegsende wurde 1945 gefeiert.","example2En":"The end of the war was celebrated in 1945."},{"de":"der Krimi","en":"crime novel/movie","pos":"noun","plural":"die Krimis","meanings":[{"en":"a detective or crime story (book, film, or TV show)","de":"eine Kriminalgeschichte (Buch, Film oder Serie)"}],"rule":"Masculine short form of Kriminalroman/Kriminalfilm; informal.","example":"Abends lese ich gern einen guten Krimi.","exampleEn":"In the evening I like to read a good crime novel.","example2":"Im Fernsehen läuft heute ein spannender Krimi.","example2En":"There's an exciting crime show on TV today."},{"de":"die Krippe","en":"manger; nursery/daycare","pos":"noun","plural":"die Krippen","meanings":[{"en":"a feeding trough, especially the nativity manger","de":"ein Futtertrog, besonders die Weihnachtskrippe"},{"en":"a daycare facility for very young children","de":"eine Betreuungseinrichtung für Kleinkinder"}],"rule":"Feminine noun; 'Kinderkrippe' is the common word for baby daycare.","example":"Zu Weihnachten stellen wir eine Krippe unter den Baum.","exampleEn":"At Christmas we put a nativity manger under the tree.","example2":"Unser Sohn geht seit einem Monat in die Krippe.","example2En":"Our son has been going to daycare for a month."},{"de":"der Kritiker / die Kritikerin","en":"critic","pos":"noun","plural":"die Kritiker / die Kritikerinnen","meanings":[{"en":"a person who reviews or judges art, books, films, etc.","de":"eine Person, die Kunst, Bücher, Filme usw. beurteilt"}],"rule":"Masculine/feminine pair; from Kritik (criticism/review).","example":"Der Kritiker hat den neuen Film sehr gelobt.","exampleEn":"The critic praised the new film highly.","example2":"Die Kritikerin schrieb eine negative Rezension über das Buch.","example2En":"The critic wrote a negative review of the book."},{"de":"kulinarisch","en":"culinary","pos":"adjective","plural":"","meanings":[{"en":"relating to cooking or food","de":"das Kochen oder Essen betreffend"}],"rule":"No irregular comparison; often used as 'kulinarische Genüsse' (culinary delights).","example":"Die Stadt ist für ihre kulinarischen Spezialitäten bekannt.","exampleEn":"The city is known for its culinary specialties.","example2":"Wir hatten ein kulinarisches Erlebnis im neuen Restaurant.","example2En":"We had a culinary experience at the new restaurant."},{"de":"die Kundenbefragung","en":"customer survey","pos":"noun","plural":"die Kundenbefragungen","meanings":[{"en":"a survey to gather customer opinions","de":"eine Umfrage zur Meinung von Kunden"}],"rule":"Compound: Kunde + Befragung; feminine like Befragung.","example":"Die Firma führt regelmäßig eine Kundenbefragung durch.","exampleEn":"The company regularly conducts a customer survey.","example2":"Die Ergebnisse der Kundenbefragung waren sehr positiv.","example2En":"The results of the customer survey were very positive."},{"de":"kundenfreundlich","en":"customer-friendly","pos":"adjective","plural":"","meanings":[{"en":"friendly and helpful towards customers","de":"freundlich und hilfsbereit gegenüber Kunden"}],"rule":"Compound adjective: Kunde + freundlich; regular comparison.","example":"Der Verkäufer war sehr kundenfreundlich.","exampleEn":"The salesperson was very customer-friendly.","example2":"Das Unternehmen legt Wert auf kundenfreundlichen Service.","example2En":"The company values customer-friendly service."},{"de":"die Kündigung","en":"notice of termination; resignation/dismissal","pos":"noun","plural":"die Kündigungen","meanings":[{"en":"formal termination of a contract, job, or lease","de":"die formale Beendigung eines Vertrags, einer Stelle oder einer Wohnung"}],"rule":"From kündigen (to terminate/give notice); feminine noun.","example":"Er hat seine Kündigung zum Monatsende eingereicht.","exampleEn":"He submitted his resignation effective end of the month.","example2":"Die Kündigung der Wohnung muss schriftlich erfolgen.","example2En":"The termination of the apartment lease must be in writing."}]},{"id":"b1-11","title":"B1 · K–M (11)","level":"B1","words":[{"de":"der Kunststoff","en":"plastic; synthetic material","pos":"noun","plural":"die Kunststoffe","meanings":[{"en":"plastic / synthetic material","de":"künstlich hergestelltes Material"}],"rule":"Zusammensetzung aus 'Kunst' + 'Stoff'; oft in Komposita wie 'Kunststoffflasche'.","example":"Die Flasche ist aus Kunststoff.","exampleEn":"The bottle is made of plastic.","example2":"Kunststoff lässt sich gut recyceln.","example2En":"Plastic can be recycled well."},{"de":"kuscheln","en":"to cuddle, to snuggle","pos":"verb","plural":"","meanings":[{"en":"to cuddle / snuggle","de":"zärtlich eng beieinander liegen"}],"rule":"regelmäßig; oft reflexiv: sich kuscheln (an jemanden).","example":"Das Kind kuschelt sich an seine Mutter.","exampleEn":"The child snuggles up to its mother.","example2":"Wir kuscheln gern auf dem Sofa.","example2En":"We like to cuddle on the sofa."},{"de":"die Lage","en":"location; situation","pos":"noun","plural":"die Lagen","meanings":[{"en":"location / position","de":"Ort, wo sich etwas befindet"},{"en":"situation","de":"Zustand, Umstände"}],"rule":"Feminines Nomen; 'in guter Lage' = gut gelegen.","example":"Die Wohnung hat eine zentrale Lage.","exampleEn":"The apartment has a central location.","example2":"Die wirtschaftliche Lage ist schwierig.","example2En":"The economic situation is difficult."},{"de":"das Lager","en":"warehouse; camp","pos":"noun","plural":"die Lager","meanings":[{"en":"warehouse / storage","de":"Ort zum Aufbewahren von Waren"},{"en":"camp","de":"Zeltplatz oder Unterkunft, z. B. für Flüchtlinge"}],"rule":"Neutrales Nomen; Plural bleibt 'die Lager' (unverändert).","example":"Die Ware ist im Lager.","exampleEn":"The goods are in the warehouse.","example2":"Die Flüchtlinge leben in einem Lager.","example2En":"The refugees live in a camp."},{"de":"das Lagerfeuer","en":"campfire","pos":"noun","plural":"die Lagerfeuer","meanings":[{"en":"campfire","de":"Feuer im Freien, z. B. beim Zelten"}],"rule":"Kompositum aus 'Lager' + 'Feuer'; neutral.","example":"Wir haben am Lagerfeuer gesungen.","exampleEn":"We sang around the campfire.","example2":"Das Lagerfeuer brannte die ganze Nacht.","example2En":"The campfire burned all night."},{"de":"laktosefrei","en":"lactose-free","pos":"adjective","plural":"","meanings":[{"en":"lactose-free","de":"ohne Laktose (Milchzucker)"}],"rule":"Adjektiv, keine unregelmäßige Steigerung üblich.","example":"Ich trinke laktosefreie Milch.","exampleEn":"I drink lactose-free milk.","example2":"Das Restaurant bietet auch laktosefreie Gerichte an.","example2En":"The restaurant also offers lactose-free dishes."},{"de":"landen","en":"to land","pos":"verb","plural":"","meanings":[{"en":"to land (aircraft, boat)","de":"auf dem Boden ankommen"},{"en":"to end up somewhere","de":"an einem bestimmten Ort ankommen"}],"rule":"Perfekt mit 'sein': ist gelandet; regelmäßig.","example":"Das Flugzeug landet um 18 Uhr.","exampleEn":"The plane lands at 6 pm.","example2":"Er ist im Gefängnis gelandet.","example2En":"He ended up in prison."},{"de":"die Langeweile","en":"boredom","pos":"noun","plural":"","meanings":[{"en":"boredom","de":"Gefühl, wenn nichts Interessantes passiert"}],"rule":"Feminines Nomen, kein Plural; 'vor Langeweile' ist eine feste Wendung.","example":"Aus Langeweile hat er ferngesehen.","exampleEn":"Out of boredom he watched TV.","example2":"Die Kinder hatten große Langeweile.","example2En":"The children were very bored."},{"de":"langfristig","en":"long-term","pos":"adjective","plural":"","meanings":[{"en":"long-term","de":"über einen langen Zeitraum"}],"rule":"Gegensatz: kurzfristig; regelmäßige Steigerung.","example":"Langfristig lohnt sich die Investition.","exampleEn":"In the long term, the investment pays off.","example2":"Wir planen langfristig.","example2En":"We plan long-term."},{"de":"der Lärm","en":"noise","pos":"noun","plural":"","meanings":[{"en":"noise","de":"laute, störende Geräusche"}],"rule":"Maskulines Nomen, kein Plural; 'Lärm machen'.","example":"Der Lärm von der Baustelle stört mich.","exampleEn":"The noise from the construction site bothers me.","example2":"Bitte macht nicht so viel Lärm!","example2En":"Please don't make so much noise!"},{"de":"die Laune","en":"mood","pos":"noun","plural":"die Launen","meanings":[{"en":"mood","de":"momentane Gemütsverfassung"}],"rule":"Feminines Nomen; 'gute/schlechte Laune haben'.","example":"Heute hat sie gute Laune.","exampleEn":"Today she is in a good mood.","example2":"Unser Chef hat im Büro oft schlechte Laune.","example2En":"Our boss is often in a bad mood at the office."},{"de":"die Lautsprecherdurchsage","en":"loudspeaker announcement","pos":"noun","plural":"die Lautsprecherdurchsagen","meanings":[{"en":"announcement over loudspeakers","de":"Mitteilung, die über Lautsprecher gemacht wird"}],"rule":"Kompositum aus 'Lautsprecher' + 'Durchsage'; feminin.","example":"Am Bahnhof hörten wir eine Lautsprecherdurchsage.","exampleEn":"At the station we heard a loudspeaker announcement.","example2":"Die Lautsprecherdurchsage kündigte die Verspätung an.","example2En":"The loudspeaker announcement announced the delay."},{"de":"lebhaft","en":"lively, vivid","pos":"adjective","plural":"","meanings":[{"en":"lively (person, place)","de":"voller Energie, aktiv"},{"en":"vivid (memory, imagination)","de":"sehr klar und intensiv"}],"rule":"Regelmäßige Steigerung: lebhaft, lebhafter, am lebhaftesten.","example":"Das Kind ist sehr lebhaft.","exampleEn":"The child is very lively.","example2":"Ich erinnere mich noch lebhaft daran.","example2En":"I still remember it vividly."},{"de":"die Leichtathletik","en":"athletics, track and field","pos":"noun","plural":"","meanings":[{"en":"athletics / track and field","de":"Sportarten wie Laufen, Springen, Werfen"}],"rule":"Feminines Nomen, kein Plural.","example":"Er treibt gern Leichtathletik.","exampleEn":"He likes doing athletics.","example2":"Die Leichtathletik-Weltmeisterschaft findet im Sommer statt.","example2En":"The athletics world championship takes place in summer."},{"de":"leiden","en":"to suffer","pos":"verb","plural":"","meanings":[{"en":"to suffer (from an illness)","de":"unter etwas Negativem leiden, z. B. einer Krankheit"},{"en":"to not be able to stand someone","de":"jemanden nicht mögen (jemanden nicht leiden können)"}],"rule":"unregelmäßig: leidet, litt, hat gelitten; + unter/an + Dativ.","example":"Sie leidet unter Kopfschmerzen.","exampleEn":"She suffers from headaches.","example2":"Ich kann ihn nicht leiden.","example2En":"I can't stand him."},{"de":"die Leine","en":"leash; line, rope","pos":"noun","plural":"die Leinen","meanings":[{"en":"leash (for a dog)","de":"Band, um ein Tier zu führen"},{"en":"line, rope","de":"Schnur, z. B. Wäscheleine"}],"rule":"Feminines Nomen; 'den Hund an die Leine nehmen'.","example":"Der Hund muss an der Leine bleiben.","exampleEn":"The dog must stay on the leash.","example2":"Sie hängt die Wäsche auf die Leine.","example2En":"She hangs the laundry on the line."},{"de":"leistungsgerecht","en":"performance-based","pos":"adjective","plural":"","meanings":[{"en":"performance-based / commensurate with performance","de":"entsprechend der erbrachten Leistung"}],"rule":"Kompositum aus 'Leistung' + 'gerecht'; oft in 'leistungsgerechte Bezahlung'.","example":"Die Firma zahlt leistungsgerechte Gehälter.","exampleEn":"The company pays performance-based salaries.","example2":"Er wünscht sich eine leistungsgerechte Bezahlung.","example2En":"He wishes for pay commensurate with performance."},{"de":"leiten","en":"to lead, to manage","pos":"verb","plural":"","meanings":[{"en":"to lead / manage / direct","de":"die Verantwortung für etwas haben"},{"en":"to conduct (electricity, heat)","de":"etwas, z. B. Strom, weiterleiten"}],"rule":"regelmäßig; + Akkusativ.","example":"Sie leitet die Abteilung seit zwei Jahren.","exampleEn":"She has been managing the department for two years.","example2":"Metall leitet Strom gut.","example2En":"Metal conducts electricity well."},{"de":"lenken","en":"to steer; to guide/direct","pos":"verb","plural":"","meanings":[{"en":"to steer (a vehicle)","de":"ein Fahrzeug steuern"},{"en":"to direct/guide (attention, traffic)","de":"lenken = leiten, führen"}],"rule":"regelmäßig: lenkt, lenkte, hat gelenkt. Oft mit Akkusativ: etwas lenken.","example":"Er lenkt das Auto vorsichtig durch die engen Straßen.","exampleEn":"He steers the car carefully through the narrow streets.","example2":"Die Lehrerin versucht, die Aufmerksamkeit der Schüler auf das Thema zu lenken.","example2En":"The teacher tries to direct the students' attention to the topic."},{"de":"der Leuchtturm","en":"lighthouse","pos":"noun","plural":"die Leuchttürme","meanings":[{"en":"lighthouse","de":"Turm mit Licht für Schiffe"}],"rule":"Zusammensetzung aus 'leuchten' + 'Turm'; Plural mit Umlaut: die Leuchttürme.","example":"Der Leuchtturm zeigt den Schiffen den Weg in den Hafen.","exampleEn":"The lighthouse shows ships the way into the harbor.","example2":"Wir sind auf den Leuchtturm gestiegen und hatten eine tolle Aussicht.","example2En":"We climbed the lighthouse and had a great view."},{"de":"die Lieblingsbeschäftigung","en":"favorite activity/pastime","pos":"noun","plural":"die Lieblingsbeschäftigungen","meanings":[{"en":"favorite hobby/pastime","de":"Hobby, das man am liebsten macht"}],"rule":"Zusammensetzung: Lieblings- + Beschäftigung; Genus vom Grundwort 'die Beschäftigung'.","example":"Lesen ist meine Lieblingsbeschäftigung am Wochenende.","exampleEn":"Reading is my favorite activity on weekends.","example2":"Was ist deine Lieblingsbeschäftigung in der Freizeit?","example2En":"What is your favorite pastime in your free time?"},{"de":"lieferbar","en":"available; deliverable","pos":"adjective","plural":"","meanings":[{"en":"available for delivery/in stock","de":"kann geliefert werden"}],"rule":"Adjektiv aus 'liefern' + '-bar'; oft mit 'sofort' oder 'ab Lager' kombiniert.","example":"Das Modell ist leider nicht mehr lieferbar.","exampleEn":"Unfortunately, that model is no longer available.","example2":"Die Ware ist sofort lieferbar.","example2En":"The item is available for immediate delivery."},{"de":"die Lieferbedingung","en":"delivery condition/term","pos":"noun","plural":"die Lieferbedingungen","meanings":[{"en":"terms/conditions of delivery","de":"Bedingung, unter der geliefert wird"}],"rule":"Meist im Plural verwendet: die Lieferbedingungen (allgemeine Geschäftsbedingungen).","example":"Bitte lesen Sie die Lieferbedingungen vor der Bestellung.","exampleEn":"Please read the delivery terms before ordering.","example2":"Unsere Lieferbedingungen finden Sie auf der Rechnung.","example2En":"You can find our delivery conditions on the invoice."},{"de":"die Lieferung","en":"delivery; shipment","pos":"noun","plural":"die Lieferungen","meanings":[{"en":"delivery/shipment of goods","de":"das Liefern von Waren"}],"rule":"Nominalisierung von 'liefern'; oft mit 'kostenlose Lieferung', 'Lieferung erfolgt...'.","example":"Die Lieferung kommt morgen zwischen 9 und 12 Uhr.","exampleEn":"The delivery arrives tomorrow between 9 and 12.","example2":"Bei Bestellungen über 50 Euro ist die Lieferung kostenlos.","example2En":"For orders over 50 euros, delivery is free."},{"de":"die Luft","en":"air","pos":"noun","plural":"","meanings":[{"en":"air (the gas we breathe)","de":"Gasgemisch, das wir atmen"}],"rule":"Meist unzählbar, kein Plural im Alltagsgebrauch (Fachplural 'Lüfte' selten).","example":"Nach dem Regen ist die Luft angenehm frisch.","exampleEn":"After the rain, the air is pleasantly fresh.","example2":"Mach bitte das Fenster auf, ich brauche frische Luft.","example2En":"Please open the window, I need fresh air."},{"de":"luftdurchlässig","en":"air-permeable; breathable","pos":"adjective","plural":"","meanings":[{"en":"allowing air to pass through","de":"lässt Luft durch"}],"rule":"Zusammensetzung aus 'Luft' + 'durchlässig'; häufig bei Stoffen/Materialien.","example":"Der Sportstoff ist besonders luftdurchlässig.","exampleEn":"The sports fabric is especially breathable.","example2":"Eine luftdurchlässige Matratze verhindert Schwitzen.","example2En":"An air-permeable mattress prevents sweating."},{"de":"lüften","en":"to air out; to ventilate","pos":"verb","plural":"","meanings":[{"en":"to air out a room","de":"frische Luft in einen Raum lassen"}],"rule":"regelmäßig: lüftet, lüftete, hat gelüftet. Nicht trennbar (Vorsicht: das verwandte Verb 'durchlüften' ist meist untrennbar: durchlüftet, nicht durchgelüftet).","example":"Wir sollten jeden Morgen kurz das Zimmer lüften.","exampleEn":"We should briefly air out the room every morning.","example2":"Nach dem Kochen lüftet sie immer die Küche.","example2En":"After cooking, she always ventilates the kitchen."},{"de":"das Magazin","en":"magazine (publication)","pos":"noun","plural":"die Magazine","meanings":[{"en":"magazine (periodical)","de":"regelmäßig erscheinende Zeitschrift"},{"en":"storeroom/warehouse","de":"Lagerraum"}],"rule":"Genus: das Magazin (Neutrum); Plural: die Magazine.","example":"Sie liest jeden Monat ein neues Magazin über Fotografie.","exampleEn":"She reads a new photography magazine every month.","example2":"Die Waren wurden im Magazin des Geschäfts gelagert.","example2En":"The goods were stored in the shop's storeroom."},{"de":"der Manager / die Managerin","en":"manager","pos":"noun","plural":"die Manager / die Managerinnen","meanings":[{"en":"manager (business)","de":"Person, die ein Unternehmen oder einen Bereich leitet"}],"rule":"Maskulin: der Manager, Plural die Manager; feminin: die Managerin, Plural die Managerinnen.","example":"Der Manager trifft sich heute mit wichtigen Kunden.","exampleEn":"The manager is meeting with important clients today.","example2":"Die Managerin hat das Projekt erfolgreich geleitet.","example2En":"The manager (female) led the project successfully."},{"de":"die Mannschaft","en":"team (sports/crew)","pos":"noun","plural":"die Mannschaften","meanings":[{"en":"sports team","de":"Gruppe von Sportlern, die zusammen spielt"},{"en":"crew (ship, etc.)","de":"Besatzung"}],"rule":"Genus: die Mannschaft; Plural die Mannschaften.","example":"Unsere Mannschaft hat das Spiel gestern gewonnen.","exampleEn":"Our team won the game yesterday.","example2":"Die Mannschaft des Schiffes bestand aus zwanzig Leuten.","example2En":"The ship's crew consisted of twenty people."},{"de":"der Maschinenbau","en":"mechanical engineering","pos":"noun","plural":"","meanings":[{"en":"mechanical engineering (field of study/industry)","de":"Fachgebiet, das sich mit dem Bau von Maschinen beschäftigt"}],"rule":"Unzählbar, kein Plural; oft als Studienfach: Maschinenbau studieren.","example":"Mein Bruder studiert Maschinenbau an der Technischen Universität.","exampleEn":"My brother is studying mechanical engineering at the technical university.","example2":"Der Maschinenbau ist eine wichtige Branche in Deutschland.","example2En":"Mechanical engineering is an important industry in Germany."},{"de":"die Massentierhaltung","en":"factory farming","pos":"noun","plural":"","meanings":[{"en":"intensive/factory farming of animals","de":"Haltung sehr vieler Tiere auf engem Raum"}],"rule":"Zusammensetzung: Massen- + Tierhaltung; unzählbar, kein Plural.","example":"Viele Menschen kritisieren die Massentierhaltung.","exampleEn":"Many people criticize factory farming.","example2":"Das Fleisch aus Massentierhaltung ist oft billiger.","example2En":"Meat from factory farming is often cheaper."},{"de":"massiv","en":"solid; massive/severe","pos":"adjective","plural":"","meanings":[{"en":"solid (material, no hollow inside)","de":"fest, nicht hohl"},{"en":"massive/serious (problem, criticism)","de":"sehr stark, gravierend"}],"rule":"Regelmäßige Steigerung: massiv, massiver, am massivsten.","example":"Der Tisch ist aus massivem Holz gebaut.","exampleEn":"The table is built of solid wood.","example2":"Es gab massive Proteste gegen die neue Regelung.","example2En":"There were massive protests against the new regulation."},{"de":"die Matratze","en":"mattress","pos":"noun","plural":"die Matratzen","meanings":[{"en":"mattress","de":"Unterlage zum Schlafen auf dem Bett"}],"rule":"Genus: die Matratze; Plural: die Matratzen.","example":"Die neue Matratze ist viel bequemer als die alte.","exampleEn":"The new mattress is much more comfortable than the old one.","example2":"Wir sollten die Matratze alle acht Jahre wechseln.","example2En":"We should replace the mattress every eight years."},{"de":"die Mauer","en":"wall (outdoor/freestanding)","pos":"noun","plural":"die Mauern","meanings":[{"en":"wall (freestanding, e.g. garden wall, city wall)","de":"freistehende Wand, z. B. aus Stein"}],"rule":"Genus: die Mauer; Plural die Mauern. Unterschied zu 'die Wand' (Innenwand eines Raumes).","example":"Die alte Mauer umgibt den ganzen Garten.","exampleEn":"The old wall surrounds the whole garden.","example2":"Die Berliner Mauer fiel im Jahr 1989.","example2En":"The Berlin Wall fell in 1989."},{"de":"der Mauerbau","en":"building of the (Berlin) Wall","pos":"noun","plural":"","meanings":[{"en":"the construction of the Berlin Wall in 1961","de":"der Bau der Berliner Mauer 1961"}],"rule":"Kompositum aus Mauer + Bau; meist ohne Plural, historischer Begriff (1961).","example":"Der Mauerbau begann am 13. August 1961.","exampleEn":"The building of the Wall began on 13 August 1961.","example2":"Viele Familien wurden durch den Mauerbau getrennt.","example2En":"Many families were separated by the building of the Wall."},{"de":"der Mauerfall","en":"fall of the (Berlin) Wall","pos":"noun","plural":"","meanings":[{"en":"the fall of the Berlin Wall in 1989","de":"der Fall der Berliner Mauer 1989"}],"rule":"Kompositum aus Mauer + Fall; meist ohne Plural, historischer Begriff (1989).","example":"Der Mauerfall war ein wichtiges Ereignis der deutschen Geschichte.","exampleEn":"The fall of the Wall was an important event in German history.","example2":"Seit dem Mauerfall ist Berlin wieder eine Stadt.","example2En":"Since the fall of the Wall, Berlin has been one city again."},{"de":"meckern","en":"to grumble, complain","pos":"verb","plural":"","meanings":[{"en":"to complain / grumble about something","de":"sich beschweren, nörgeln"}],"rule":"regelmäßig (schwach): meckert, meckerte, hat gemeckert; oft mit 'über + Akkusativ'.","example":"Er meckert immer über das Wetter.","exampleEn":"He always grumbles about the weather.","example2":"Meckere nicht so viel, sondern hilf mir lieber!","example2En":"Stop complaining so much and help me instead!"},{"de":"die Medizin","en":"medicine (science / medication)","pos":"noun","plural":"die Medizinen","meanings":[{"en":"the field of medicine","de":"die Wissenschaft von Krankheiten und Heilung"},{"en":"a medicine, a drug","de":"das Medikament"}],"rule":"Als Fachbereich meist Singular ohne Plural; als 'Medikament' zählbar (die Medizinen).","example":"Sie studiert Medizin an der Universität.","exampleEn":"She is studying medicine at university.","example2":"Nimm die Medizin dreimal täglich nach dem Essen.","example2En":"Take the medicine three times a day after meals."},{"de":"der Meerblick","en":"sea view","pos":"noun","plural":"","meanings":[{"en":"a view of the sea","de":"der Blick aufs Meer"}],"rule":"Kompositum aus Meer + Blick; meist ohne Plural, oft in Hotelbeschreibungen.","example":"Wir haben ein Zimmer mit Meerblick gebucht.","exampleEn":"We booked a room with a sea view.","example2":"Von der Terrasse aus hat man einen tollen Meerblick.","example2En":"From the terrace you have a great sea view."},{"de":"das Meerschweinchen","en":"guinea pig","pos":"noun","plural":"die Meerschweinchen","meanings":[{"en":"a guinea pig (small pet rodent)","de":"ein kleines Haustier, ein Nagetier"}],"rule":"Diminutiv auf -chen, daher sächlich (das); Plural = Singular.","example":"Meine Tochter hat zwei Meerschweinchen als Haustiere.","exampleEn":"My daughter has two guinea pigs as pets.","example2":"Das Meerschweinchen frisst gern frisches Gemüse.","example2En":"The guinea pig likes to eat fresh vegetables."},{"de":"die Mehrheit","en":"majority","pos":"noun","plural":"die Mehrheiten","meanings":[{"en":"the majority (of people/votes)","de":"der größere Teil, mehr als die Hälfte"}],"rule":"Oft mit Genitiv oder 'von': die Mehrheit der Wähler.","example":"Die Mehrheit der Bürger hat für das neue Gesetz gestimmt.","exampleEn":"The majority of citizens voted for the new law.","example2":"Bei der Wahl gewann die Partei die absolute Mehrheit.","example2En":"In the election, the party won an absolute majority."},{"de":"die Mehrkosten","en":"extra costs","pos":"noun","plural":"","meanings":[{"en":"additional/extra costs","de":"zusätzliche Kosten"}],"rule":"Nur im Plural gebräuchlich; kein Singular.","example":"Die Renovierung verursachte unerwartete Mehrkosten.","exampleEn":"The renovation caused unexpected extra costs.","example2":"Wer trägt die Mehrkosten für den Versand?","example2En":"Who bears the extra costs for shipping?"},{"de":"mehrmals","en":"several times","pos":"adverb","plural":"","meanings":[{"en":"more than once, repeatedly","de":"mehrere Male, öfter"}],"rule":"Unveränderliches Adverb, keine Steigerung nötig.","example":"Ich habe ihn mehrmals angerufen, aber er hat nicht abgehoben.","exampleEn":"I called him several times, but he didn't pick up.","example2":"Sie hat den Text mehrmals gelesen, bevor sie ihn verstanden hat.","example2En":"She read the text several times before understanding it."},{"de":"meistern","en":"to master, cope with","pos":"verb","plural":"","meanings":[{"en":"to master / successfully deal with a difficult task","de":"eine schwierige Aufgabe erfolgreich bewältigen"}],"rule":"regelmäßig (schwach): meistert, meisterte, hat gemeistert; + Akkusativ.","example":"Sie hat alle Schwierigkeiten mit viel Geduld gemeistert.","exampleEn":"She mastered all difficulties with a lot of patience.","example2":"Er versucht, die neue Sprache schnell zu meistern.","example2En":"He is trying to master the new language quickly."},{"de":"die Mentalität","en":"mentality","pos":"noun","plural":"die Mentalitäten","meanings":[{"en":"a way of thinking typical of a person or group","de":"die typische Denkweise einer Person oder Gruppe"}],"rule":"Meist Singular, Plural möglich bei Vergleich mehrerer Mentalitäten.","example":"Die Mentalität der Menschen ist von Land zu Land unterschiedlich.","exampleEn":"People's mentality differs from country to country.","example2":"Er hat eine sehr optimistische Mentalität.","example2En":"He has a very optimistic mentality."},{"de":"merken","en":"to notice; to remember","pos":"verb","plural":"","meanings":[{"en":"to notice, realize something","de":"etwas bemerken, wahrnehmen"},{"en":"sich (Dat.) etwas merken: to memorize, keep in mind","de":"sich etwas einprägen"}],"rule":"regelmäßig (schwach): merkt, merkte, hat gemerkt; reflexiv 'sich etwas merken' + Akkusativ, Dativ-Reflexivpronomen.","example":"Ich habe gemerkt, dass etwas nicht stimmt.","exampleEn":"I noticed that something was wrong.","example2":"Kannst du dir diese Nummer merken?","example2En":"Can you remember this number?"},{"de":"das Metall","en":"metal","pos":"noun","plural":"die Metalle","meanings":[{"en":"metal (material)","de":"ein hartes, glänzendes Material wie Eisen oder Gold"}],"rule":"Sächlich; Plural 'die Metalle' bezeichnet verschiedene Metallarten.","example":"Der Ring besteht aus einem seltenen Metall.","exampleEn":"The ring is made of a rare metal.","example2":"Eisen und Gold sind bekannte Metalle.","example2En":"Iron and gold are well-known metals."},{"de":"die Mieterhöhung","en":"rent increase","pos":"noun","plural":"die Mieterhöhungen","meanings":[{"en":"an increase in rent","de":"eine Erhöhung der Miete"}],"rule":"Kompositum aus Miete + Erhöhung.","example":"Der Vermieter hat uns eine Mieterhöhung angekündigt.","exampleEn":"The landlord announced a rent increase to us.","example2":"Viele Mieter protestieren gegen die geplante Mieterhöhung.","example2En":"Many tenants are protesting against the planned rent increase."},{"de":"der Mietspiegel","en":"local rent index","pos":"noun","plural":"die Mietspiegel","meanings":[{"en":"an official table showing average local rents","de":"eine Übersicht über ortsübliche Mieten"}],"rule":"Kompositum aus Miete + Spiegel; amtlicher Begriff aus dem Mietrecht.","example":"Der Vermieter orientiert sich am örtlichen Mietspiegel.","exampleEn":"The landlord goes by the local rent index.","example2":"Laut Mietspiegel ist die Miete hier zu hoch.","example2En":"According to the rent index, the rent here is too high."}]},{"id":"b1-12","title":"B1 · M–N (12)","level":"B1","words":[{"de":"der Mietvertrag","en":"tenancy agreement, lease","pos":"noun","plural":"die Mietverträge","meanings":[{"en":"a rental contract","de":"ein Vertrag zwischen Mieter und Vermieter"}],"rule":"Kompositum aus Miete + Vertrag; Plural mit Umlaut: Mietverträge.","example":"Wir haben gestern den Mietvertrag unterschrieben.","exampleEn":"We signed the lease yesterday.","example2":"Im Mietvertrag steht die Kündigungsfrist.","example2En":"The notice period is stated in the tenancy agreement."},{"de":"die Migration","en":"migration","pos":"noun","plural":"die Migrationen","meanings":[{"en":"the movement of people to live in another country/region","de":"die Wanderung von Menschen in ein anderes Land"}],"rule":"Meist Singular gebraucht, besonders im gesellschaftlichen/politischen Kontext.","example":"Migration ist ein wichtiges Thema in der Politik.","exampleEn":"Migration is an important topic in politics.","example2":"Viele Städte sind durch Migration vielfältiger geworden.","example2En":"Many cities have become more diverse through migration."},{"de":"der Milchkarton","en":"milk carton","pos":"noun","plural":"die Milchkartons","meanings":[{"en":"a carton/package for milk","de":"eine Verpackung für Milch"}],"rule":"Kompositum aus Milch + Karton; Plural auf -s (Fremdwort Karton).","example":"Bitte wirf den leeren Milchkarton in den Gelben Sack.","exampleEn":"Please throw the empty milk carton into the recycling bag.","example2":"Im Kühlschrank steht noch ein voller Milchkarton.","example2En":"There's still a full carton of milk in the fridge."},{"de":"der Milchzucker","en":"lactose","pos":"noun","plural":"","meanings":[{"en":"lactose (sugar found in milk)","de":"der natürliche Zucker in der Milch"}],"rule":"Kompositum aus Milch + Zucker; meist unzählbar, kein Plural.","example":"Ich vertrage keinen Milchzucker, deshalb trinke ich laktosefreie Milch.","exampleEn":"I can't tolerate lactose, so I drink lactose-free milk.","example2":"Auf der Verpackung steht, wie viel Milchzucker enthalten ist.","example2En":"The packaging shows how much lactose it contains."},{"de":"die Million","en":"million","pos":"noun","plural":"die Millionen","meanings":[{"en":"one million (1,000,000)","de":"die Zahl 1.000.000"}],"rule":"Anders als 'hundert' oder 'tausend' bekommt 'Million' nach einer Zahl ab 2 die Plural-Endung -en: zwei Millionen, drei Millionen Euro.","example":"In dieser Stadt leben über eine Million Menschen.","exampleEn":"More than one million people live in this city.","example2":"Er hat im Lotto zwei Millionen Euro gewonnen.","example2En":"He won two million euros in the lottery."},{"de":"der Millionär / die Millionärin","en":"millionaire","pos":"noun","plural":"die Millionäre / die Millionärinnen","meanings":[{"en":"a person who has at least a million euros/dollars","de":"eine Person mit sehr viel Geld (über eine Million)"}],"rule":"Weibliche Form mit -in: die Millionärin.","example":"Er wurde durch seine Erfindung zum Millionär.","exampleEn":"He became a millionaire thanks to his invention.","example2":"Die Millionärin spendet jedes Jahr viel Geld für wohltätige Zwecke.","example2En":"The (female) millionaire donates a lot of money to charity every year."},{"de":"die Minderheit","en":"minority","pos":"noun","plural":"die Minderheiten","meanings":[{"en":"a small part of a group; an ethnic/social minority","de":"ein kleinerer Teil einer Gruppe"}],"rule":"Gegenteil von die Mehrheit.","example":"In diesem Stadtteil leben viele ethnische Minderheiten.","exampleEn":"Many ethnic minorities live in this district.","example2":"Bei der Abstimmung war er leider in der Minderheit.","example2En":"Unfortunately, he was in the minority in the vote."},{"de":"mitdenken","en":"to think along; to follow attentively and anticipate","pos":"verb","plural":"","meanings":[{"en":"to think along with someone / follow actively and anticipate","de":"aktiv mitüberlegen, aufmerksam folgen"}],"rule":"trennbar: denkt ... mit, dachte ... mit, hat mitgedacht.","example":"Im Team ist es wichtig, dass jeder mitdenkt.","exampleEn":"In a team it's important that everyone thinks along.","example2":"Der neue Kollege hat gut mitgedacht und einen Fehler entdeckt.","example2En":"The new colleague paid close attention and spotted a mistake."},{"de":"miteinander","en":"with each other, together","pos":"adverb","plural":"","meanings":[{"en":"with one another, together","de":"gemeinsam, einer mit dem anderen"}],"rule":"Wechselseitige Handlung von mindestens zwei Personen; oft mit Verben wie sprechen, arbeiten, leben.","example":"Die beiden Nachbarn reden schon lange nicht mehr miteinander.","exampleEn":"The two neighbors haven't spoken to each other in a long time.","example2":"Wir wollen den Abend miteinander verbringen.","example2En":"We want to spend the evening together."},{"de":"miterleben","en":"to witness, to live through (something firsthand)","pos":"verb","plural":"","meanings":[{"en":"to witness/experience something personally as it happens","de":"etwas persönlich erleben, dabei sein"}],"rule":"trennbar: erlebt ... mit, erlebte ... mit, hat miterlebt.","example":"Meine Großeltern haben den Krieg als Kinder miterlebt.","exampleEn":"My grandparents experienced the war as children.","example2":"Ich konnte die Geburt meines Neffen live miterleben.","example2En":"I got to witness my nephew's birth live."},{"de":"mitreden","en":"to join the conversation, to have a say","pos":"verb","plural":"","meanings":[{"en":"to join in a discussion; to have a say in a decision","de":"sich an einem Gespräch beteiligen; eine Meinung äußern dürfen"}],"rule":"trennbar: redet ... mit, redete ... mit, hat mitgeredet.","example":"Bei diesem Thema kann ich leider nicht mitreden.","exampleEn":"Unfortunately I can't join in on this topic.","example2":"Die Mitarbeiter wollen bei wichtigen Entscheidungen mitreden.","example2En":"The employees want to have a say in important decisions."},{"de":"das Mittelfeld","en":"midfield","pos":"noun","plural":"die Mittelfelder","meanings":[{"en":"midfield (in football/sports)","de":"der mittlere Bereich eines Spielfelds"},{"en":"middle position/rank (in a ranking)","de":"ein mittlerer Platz in einer Rangliste"}],"rule":"Kompositum aus Mitte(l) + Feld; im Sport meist Singular.","example":"Er spielt im Mittelfeld und verteilt die Bälle.","exampleEn":"He plays in midfield and distributes the balls.","example2":"Unsere Mannschaft liegt in der Tabelle nur im Mittelfeld.","example2En":"Our team is only in the middle of the table."},{"de":"mittelständisch","en":"medium-sized (business)","pos":"adjective","plural":"","meanings":[{"en":"relating to small and medium-sized enterprises","de":"zum Mittelstand gehörend, mittelgroß (Unternehmen)"}],"rule":"Wird fast nur für Firmen/Betriebe verwendet, von 'der Mittelstand' abgeleitet.","example":"Er arbeitet in einem mittelständischen Unternehmen.","exampleEn":"He works at a medium-sized company.","example2":"Viele mittelständische Betriebe bilden selbst aus.","example2En":"Many medium-sized businesses train apprentices themselves."},{"de":"mitten","en":"in the middle","pos":"adverb","plural":"","meanings":[{"en":"in the middle/midst of (place or time)","de":"in der Mitte von etwas"}],"rule":"Immer mit Präposition: mitten in, mitten auf, mitten durch.","example":"Das Haus steht mitten im Wald.","exampleEn":"The house is right in the middle of the forest.","example2":"Er rief mich mitten in der Nacht an.","example2En":"He called me in the middle of the night."},{"de":"die Moderation","en":"hosting, presenting (of a show/discussion)","pos":"noun","plural":"die Moderationen","meanings":[{"en":"the act of hosting/presenting a TV or radio show, event, or discussion","de":"das Leiten einer Sendung, Diskussion oder Veranstaltung"}],"rule":"Von moderieren abgeleitet; oft mit Genitiv: die Moderation der Sendung.","example":"Die Moderation der Talkshow übernimmt eine bekannte Journalistin.","exampleEn":"A well-known journalist will host the talk show.","example2":"Seine Moderation des Abends kam beim Publikum gut an.","example2En":"His hosting of the evening was well received by the audience."},{"de":"die Modernisierung","en":"modernization","pos":"noun","plural":"die Modernisierungen","meanings":[{"en":"the process of making something more modern","de":"der Prozess, etwas moderner bzw. zeitgemäßer zu machen"}],"rule":"Von modernisieren abgeleitet.","example":"Die Modernisierung der Küche hat viel Geld gekostet.","exampleEn":"Modernizing the kitchen cost a lot of money.","example2":"Das Unternehmen investiert in die Modernisierung seiner Maschinen.","example2En":"The company is investing in modernizing its machines."},{"de":"moralisch","en":"moral","pos":"adjective","plural":"","meanings":[{"en":"relating to moral principles, ethical","de":"die Moral betreffend, sittlich"}],"rule":"Keine unregelmäßige Steigerung: moralisch, moralischer, am moralischsten.","example":"Er hat sich moralisch korrekt verhalten.","exampleEn":"He behaved in a morally correct way.","example2":"Das ist eine moralische Frage, keine rechtliche.","example2En":"That's a moral question, not a legal one."},{"de":"der Mord","en":"murder","pos":"noun","plural":"die Morde","meanings":[{"en":"murder, homicide","de":"das vorsätzliche Töten eines Menschen"}],"rule":"Oft mit Präposition an: der Mord an einer Person.","example":"Die Polizei ermittelt in einem Mordfall.","exampleEn":"The police are investigating a murder case.","example2":"Der Mord an dem Politiker schockierte das ganze Land.","example2En":"The murder of the politician shocked the whole country."},{"de":"motiviert","en":"motivated","pos":"adjective","plural":"","meanings":[{"en":"feeling enthusiastic and willing to do something","de":"voller Motivation, engagiert"}],"rule":"Partizip II von motivieren, als Adjektiv verwendet; regelmäßige Steigerung.","example":"Die neuen Kollegen sind sehr motiviert.","exampleEn":"The new colleagues are very motivated.","example2":"Nach dem Gespräch mit dem Chef war sie wieder motiviert.","example2En":"After talking with the boss, she was motivated again."},{"de":"der Motor","en":"engine, motor","pos":"noun","plural":"die Motoren","meanings":[{"en":"engine/motor (of a vehicle or machine)","de":"der Antrieb eines Fahrzeugs oder einer Maschine"}],"rule":"Fremdwort auf -or bildet den Plural auf -en (wie Doktor–Doktoren, Traktor–Traktoren): der Motor – die Motoren.","example":"Der Motor springt bei kaltem Wetter schlecht an.","exampleEn":"The engine starts badly in cold weather.","example2":"Der Mechaniker repariert den Motor des Autos.","example2En":"The mechanic is repairing the car's engine."},{"de":"die Motorhaube","en":"car hood/bonnet","pos":"noun","plural":"die Motorhauben","meanings":[{"en":"the hood/bonnet covering a car's engine","de":"die Abdeckung über dem Motor eines Autos"}],"rule":"Kompositum aus Motor + Haube.","example":"Er öffnete die Motorhaube, um den Ölstand zu prüfen.","exampleEn":"He opened the hood to check the oil level.","example2":"Auf der Motorhaube lag eine dünne Schicht Schnee.","example2En":"There was a thin layer of snow on the car's hood."},{"de":"der Motorradfahrer / die Motorradfahrerin","en":"motorcyclist","pos":"noun","plural":"die Motorradfahrer / die Motorradfahrerinnen","meanings":[{"en":"person who rides a motorcycle","de":"Person, die Motorrad fährt"}],"rule":"Compound of Motorrad + Fahrer/in; plural same as singular for masculine form (der Motorradfahrer, die Motorradfahrer).","example":"Der Motorradfahrer trägt immer einen Helm.","exampleEn":"The motorcyclist always wears a helmet.","example2":"Auf der Landstraße war eine Motorradfahrerin unterwegs.","example2En":"A female motorcyclist was riding on the country road."},{"de":"die Mülltonne","en":"garbage bin","pos":"noun","plural":"die Mülltonnen","meanings":[{"en":"large bin for household waste","de":"großer Behälter für Müll"}],"rule":"Compound noun: der Müll + die Tonne; gender follows die Tonne.","example":"Stell die Mülltonne an die Straße.","exampleEn":"Put the garbage bin out by the street.","example2":"Die Mülltonne ist schon wieder voll.","example2En":"The garbage bin is already full again."},{"de":"die Mülltrennung","en":"waste separation","pos":"noun","plural":"","meanings":[{"en":"sorting waste into different categories for recycling","de":"getrenntes Sammeln von Müll nach Materialart"}],"rule":"Uncountable noun; compound of Müll + Trennung.","example":"In Deutschland ist Mülltrennung sehr wichtig.","exampleEn":"Waste separation is very important in Germany.","example2":"Die Mülltrennung funktioniert bei uns noch nicht gut.","example2En":"Waste separation doesn't work well at our place yet."},{"de":"musikalisch","en":"musical","pos":"adjective","plural":"","meanings":[{"en":"having musical talent/ability","de":"begabt für Musik"},{"en":"relating to music","de":"die Musik betreffend"}],"rule":"Regular adjective, no irregular comparison (musikalischer, am musikalischsten).","example":"Sie ist sehr musikalisch und spielt drei Instrumente.","exampleEn":"She is very musical and plays three instruments.","example2":"Das Konzert war ein musikalisches Highlight.","example2En":"The concert was a musical highlight."},{"de":"die Muttersprache","en":"native language, mother tongue","pos":"noun","plural":"die Muttersprachen","meanings":[{"en":"the first language one learns","de":"die Sprache, die man von klein auf lernt"}],"rule":"Compound of Mutter + Sprache; often used with von/als: Deutsch als Muttersprache.","example":"Meine Muttersprache ist Arabisch.","exampleEn":"My native language is Arabic.","example2":"Er spricht Englisch wie seine Muttersprache.","example2En":"He speaks English as if it were his native language."},{"de":"nachdem","en":"after (that)","pos":"conjunction","plural":"","meanings":[{"en":"subordinating conjunction: after something happened","de":"zeitlich danach: nachdem etwas geschehen ist"}],"rule":"The nachdem-clause must be one tense step 'earlier' than the main clause: Perfekt + Präsens/Präteritum, or Plusquamperfekt + Präteritum, e.g. 'Nachdem ich gegessen hatte, ging ich spazieren.'","example":"Nachdem er gefrühstückt hatte, ging er zur Arbeit.","exampleEn":"After he had had breakfast, he went to work.","example2":"Nachdem sie angekommen ist, ruft sie mich an.","example2En":"After she arrives, she'll call me."},{"de":"nachdenken","en":"to think about, to reflect","pos":"verb","plural":"","meanings":[{"en":"to think carefully about something","de":"über etwas gründlich nachdenken"}],"rule":"Trennbar: denkt ... nach, dachte ... nach, hat nachgedacht; + über + Akkusativ.","example":"Ich muss über dein Angebot nachdenken.","exampleEn":"I have to think about your offer.","example2":"Er dachte lange über die Frage nach.","example2En":"He thought about the question for a long time."},{"de":"nachdenklich","en":"thoughtful, pensive","pos":"adjective","plural":"","meanings":[{"en":"deep in thought, reflective","de":"in Gedanken versunken"}],"rule":"Regular adjective (nachdenklicher, am nachdenklichsten); related to nachdenken.","example":"Nach dem Gespräch war sie sehr nachdenklich.","exampleEn":"After the conversation she was very thoughtful.","example2":"Er schaute nachdenklich aus dem Fenster.","example2En":"He looked pensively out of the window."},{"de":"die Nachkriegszeit","en":"postwar period","pos":"noun","plural":"","meanings":[{"en":"the period after a war, especially after WWII in Germany","de":"die Zeit nach einem Krieg"}],"rule":"Uncountable, compound of nach + Krieg + Zeit; usually used with 'die Nachkriegszeit'.","example":"In der Nachkriegszeit gab es wenig zu essen.","exampleEn":"In the postwar period there was little to eat.","example2":"Meine Großeltern haben die Nachkriegszeit noch erlebt.","example2En":"My grandparents still experienced the postwar period."},{"de":"die Nachnahme","en":"cash on delivery","pos":"noun","plural":"die Nachnahmen","meanings":[{"en":"payment method where you pay upon delivery","de":"Bezahlung bei Lieferung der Ware"}],"rule":"Often used in the fixed phrase 'per Nachnahme' (by cash on delivery).","example":"Ich habe das Paket per Nachnahme bezahlt.","exampleEn":"I paid for the package by cash on delivery.","example2":"Nachnahme ist bei diesem Shop nicht möglich.","example2En":"Cash on delivery is not possible with this shop."},{"de":"nachsehen","en":"to check, to look up; to watch someone go","pos":"verb","plural":"","meanings":[{"en":"to check/look something up","de":"etwas kontrollieren oder überprüfen"},{"en":"to watch someone leave, to gaze after someone","de":"jemandem mit den Augen folgen, während er sich entfernt"}],"rule":"Trennbar und unregelmäßig: sieht ... nach, sah ... nach, hat nachgesehen.","example":"Ich sehe kurz nach, ob die Tür zu ist.","exampleEn":"I'll quickly check whether the door is closed.","example2":"Sie sah dem Zug lange nach.","example2En":"She watched the train go for a long time."},{"de":"der Nachteil","en":"disadvantage","pos":"noun","plural":"die Nachteile","meanings":[{"en":"a negative aspect or drawback","de":"ein negativer Aspekt einer Sache"}],"rule":"Opposite of der Vorteil; often used with 'Vor- und Nachteile'.","example":"Das hat auch einen großen Nachteil.","exampleEn":"That also has a big disadvantage.","example2":"Wir haben die Vor- und Nachteile verglichen.","example2En":"We compared the advantages and disadvantages."},{"de":"der Nährstoff","en":"nutrient","pos":"noun","plural":"die Nährstoffe","meanings":[{"en":"substance that provides nourishment","de":"Stoff, der den Körper ernährt"}],"rule":"Compound of nähren + Stoff; often plural: Nährstoffe.","example":"Obst enthält viele wichtige Nährstoffe.","exampleEn":"Fruit contains many important nutrients.","example2":"Der Körper braucht verschiedene Nährstoffe.","example2En":"The body needs various nutrients."},{"de":"das Nahrungsmittel","en":"food, foodstuff","pos":"noun","plural":"die Nahrungsmittel","meanings":[{"en":"any substance eaten as food","de":"etwas, das man isst"}],"rule":"Compound of Nahrung + Mittel; plural same as singular form.","example":"Gesunde Nahrungsmittel sind wichtig für den Körper.","exampleEn":"Healthy foods are important for the body.","example2":"Die Preise für Nahrungsmittel sind gestiegen.","example2En":"Food prices have risen."},{"de":"naschen","en":"to snack on sweets, to nibble","pos":"verb","plural":"","meanings":[{"en":"to eat small amounts of sweets/treats","de":"kleine Mengen Süßigkeiten essen"}],"rule":"Regular weak verb: nascht, naschte, hat genascht; often + von.","example":"Die Kinder naschen gern Schokolade.","exampleEn":"The children like to snack on chocolate.","example2":"Sie hat heimlich von der Torte genascht.","example2En":"She secretly nibbled some of the cake."},{"de":"der Nationalsozialismus","en":"National Socialism, Nazism","pos":"noun","plural":"","meanings":[{"en":"the ideology and regime of the Nazi party in Germany (1933–1945)","de":"die Ideologie und Herrschaft der NSDAP in Deutschland"}],"rule":"Uncountable abstract noun for the Nazi ideology/regime (1933–1945); always singular; not a proper name, just capitalized like all German nouns.","example":"Im Geschichtsunterricht sprechen wir über den Nationalsozialismus.","exampleEn":"In history class we talk about National Socialism.","example2":"Der Nationalsozialismus begann 1933 in Deutschland.","example2En":"National Socialism began in Germany in 1933."},{"de":"die NATO","en":"NATO","pos":"noun","plural":"","meanings":[{"en":"North Atlantic Treaty Organization, a military alliance","de":"ein Verteidigungsbündnis westlicher Staaten"}],"rule":"Abbreviation, always used with feminine article die; no plural.","example":"Deutschland ist Mitglied der NATO.","exampleEn":"Germany is a member of NATO.","example2":"Die NATO wurde 1949 gegründet.","example2En":"NATO was founded in 1949."},{"de":"die Naturkatastrophe","en":"natural disaster","pos":"noun","plural":"die Naturkatastrophen","meanings":[{"en":"a natural event causing great damage, e.g. earthquake, flood","de":"ein Naturereignis mit großem Schaden, z. B. Erdbeben, Überschwemmung"}],"rule":"Compound of Natur + Katastrophe.","example":"Das Erdbeben war eine schlimme Naturkatastrophe.","exampleEn":"The earthquake was a terrible natural disaster.","example2":"Nach der Naturkatastrophe kam viel Hilfe aus dem Ausland.","example2En":"After the natural disaster, a lot of help came from abroad."},{"de":"das Naturprodukt","en":"natural product","pos":"noun","plural":"die Naturprodukte","meanings":[{"en":"a product made from natural materials, not artificial","de":"ein Produkt aus natürlichen Stoffen, nicht künstlich"}],"rule":"Neutrum, weil 'das Produkt' neutrum ist; Kompositum aus Natur + Produkt.","example":"Im Bioladen kauft sie nur Naturprodukte.","exampleEn":"At the organic shop she only buys natural products.","example2":"Diese Seife ist ein reines Naturprodukt.","example2En":"This soap is a pure natural product."},{"de":"der Nebel","en":"fog; mist","pos":"noun","plural":"die Nebel","meanings":[{"en":"fog, mist in the air","de":"feine Wassertröpfchen in der Luft, die die Sicht verschlechtern"}],"rule":"Maskulin; oft mit 'dichter Nebel' (thick fog) oder 'im Nebel' (in the fog).","example":"Heute Morgen lag dichter Nebel über der Stadt.","exampleEn":"This morning thick fog lay over the city.","example2":"Bei Nebel sollte man langsam fahren.","example2En":"You should drive slowly in fog."},{"de":"nebenbei","en":"on the side; incidentally","pos":"adverb","plural":"","meanings":[{"en":"in addition to the main activity, as a side thing","de":"zusätzlich zur Hauptsache, nicht als Hauptbeschäftigung"},{"en":"by the way, incidentally","de":"beiläufig gesagt"}],"rule":"Unveränderliches Adverb; steht oft vor dem Verb oder am Satzende.","example":"Er studiert und arbeitet nebenbei als Kellner.","exampleEn":"He studies and works as a waiter on the side.","example2":"Nebenbei bemerkt, das Essen war ausgezeichnet.","example2En":"By the way, the food was excellent."},{"de":"neblig","en":"foggy; misty","pos":"adjective","plural":"","meanings":[{"en":"covered with or full of fog","de":"mit Nebel bedeckt"}],"rule":"Regelmäßige Komparation: neblig, nebliger, am nebligsten.","example":"Heute ist es sehr neblig, man sieht kaum etwas.","exampleEn":"Today it's very foggy, you can hardly see anything.","example2":"Im Herbst sind die Morgen oft neblig.","example2En":"In autumn the mornings are often foggy."},{"de":"neugierig","en":"curious","pos":"adjective","plural":"","meanings":[{"en":"eager to know or learn something","de":"interessiert daran, etwas Neues zu erfahren"}],"rule":"Regelmäßige Komparation: neugierig, neugieriger, am neugierigsten; oft mit 'auf + Akkusativ'.","example":"Die Kinder sind neugierig auf das neue Spielzeug.","exampleEn":"The children are curious about the new toy.","example2":"Sei nicht so neugierig, das geht dich nichts an!","example2En":"Don't be so nosy, that's none of your business!"},{"de":"der Neuwagen","en":"new car","pos":"noun","plural":"die Neuwagen","meanings":[{"en":"a brand-new, unused car","de":"ein neues, noch nicht gefahrenes Auto"}],"rule":"Maskulin; Gegenteil: der Gebrauchtwagen.","example":"Er hat sich einen Neuwagen gekauft.","exampleEn":"He bought himself a new car.","example2":"Neuwagen sind teurer als Gebrauchtwagen.","example2En":"New cars are more expensive than used cars."},{"de":"die Niederlage","en":"defeat; loss","pos":"noun","plural":"die Niederlagen","meanings":[{"en":"a loss in a competition, game or war","de":"eine verlorene Auseinandersetzung, z. B. im Sport oder Krieg"}],"rule":"Femininum; Gegenteil: der Sieg (victory).","example":"Die Mannschaft musste eine bittere Niederlage hinnehmen.","exampleEn":"The team had to accept a bitter defeat.","example2":"Nach der Niederlage war die Stimmung schlecht.","example2En":"After the defeat the mood was bad."},{"de":"das Niveau","en":"level; standard","pos":"noun","plural":"die Niveaus","meanings":[{"en":"a level or standard of quality, skill or knowledge","de":"ein Grad an Qualität, Können oder Wissen"}],"rule":"Neutrum; aus dem Französischen, Aussprache 'Niwoh'; oft 'auf hohem/niedrigem Niveau'.","example":"Sein Deutsch ist schon auf einem hohen Niveau.","exampleEn":"His German is already at a high level.","example2":"Der Kurs ist für Anfänger, das Niveau ist nicht hoch.","example2En":"The course is for beginners, the level isn't high."},{"de":"die Notunterkunft","en":"emergency shelter","pos":"noun","plural":"die Notunterkünfte","meanings":[{"en":"temporary accommodation in an emergency","de":"eine vorübergehende Unterkunft in einer Notsituation"}],"rule":"Femininum; Kompositum aus Not + Unterkunft.","example":"Nach der Flut fanden viele Menschen in einer Notunterkunft Platz.","exampleEn":"After the flood many people found space in an emergency shelter.","example2":"Die Stadt hat eine Notunterkunft für Obdachlose eingerichtet.","example2En":"The city set up an emergency shelter for the homeless."},{"de":"das Nummernschild","en":"license plate","pos":"noun","plural":"die Nummernschilder","meanings":[{"en":"the plate on a vehicle showing its registration number","de":"das Schild am Auto mit dem amtlichen Kennzeichen"}],"rule":"Neutrum; Kompositum aus Nummer + Schild.","example":"Die Polizei hat sich das Nummernschild des Autos notiert.","exampleEn":"The police noted down the car's license plate.","example2":"Das Nummernschild war völlig verschmutzt.","example2En":"The license plate was completely dirty."},{"de":"die Nuss","en":"nut","pos":"noun","plural":"die Nüsse","meanings":[{"en":"a hard-shelled edible fruit/seed (e.g. walnut, hazelnut)","de":"eine essbare Frucht mit harter Schale"}],"rule":"Femininum; Plural mit Umlaut: die Nüsse.","example":"Sie isst gern Nüsse als gesunden Snack.","exampleEn":"She likes to eat nuts as a healthy snack.","example2":"Der Kuchen wird mit gehackten Nüssen bestreut.","example2En":"The cake is sprinkled with chopped nuts."}]},{"id":"b1-13","title":"B1 · O–Q (13)","level":"B1","words":[{"de":"objektiv","en":"objective","pos":"adjective","plural":"","meanings":[{"en":"based on facts, not influenced by personal feelings","de":"sachlich, ohne persönliche Meinung"}],"rule":"Regelmäßige Komparation: objektiv, objektiver, am objektivsten; Gegenteil: subjektiv.","example":"Der Journalist versucht, objektiv zu berichten.","exampleEn":"The journalist tries to report objectively.","example2":"Es ist schwer, in dieser Sache objektiv zu bleiben.","example2En":"It's hard to stay objective in this matter."},{"de":"die Obstschale","en":"fruit bowl","pos":"noun","plural":"die Obstschalen","meanings":[{"en":"a bowl used to hold fruit","de":"eine Schale, in der Obst aufbewahrt wird"}],"rule":"Femininum; Kompositum aus Obst + Schale.","example":"Auf dem Tisch steht eine Obstschale mit Äpfeln und Bananen.","exampleEn":"There's a fruit bowl with apples and bananas on the table.","example2":"Er stellte die Obstschale in die Küche.","example2En":"He put the fruit bowl in the kitchen."},{"de":"obwohl","en":"although","pos":"conjunction","plural":"","meanings":[{"en":"despite the fact that","de":"trotz der Tatsache, dass"}],"rule":"Subjunktion, verb-letzte Stellung im Nebensatz: 'Obwohl es regnet, gehen wir spazieren.'","example":"Obwohl es regnet, gehen wir spazieren.","exampleEn":"Although it's raining, we're going for a walk.","example2":"Sie kam zur Arbeit, obwohl sie krank war.","example2En":"She came to work although she was sick."},{"de":"offen","en":"open; frank","pos":"adjective","plural":"","meanings":[{"en":"not closed; accessible","de":"nicht geschlossen"},{"en":"honest and direct in speech","de":"ehrlich und direkt im Gespräch"}],"rule":"Regelmäßige Komparation: offen, offener, am offensten.","example":"Das Fenster ist die ganze Nacht offen geblieben.","exampleEn":"The window stayed open all night.","example2":"Sie hat offen über ihre Probleme gesprochen.","example2En":"She spoke openly about her problems."},{"de":"offenbar","en":"apparently; evidently","pos":"adverb","plural":"","meanings":[{"en":"apparently, as it seems","de":"anscheinend, wie es scheint"}],"rule":"Unveränderliches Adverb, ähnlich wie 'anscheinend'; oft am Satzanfang oder nach dem Verb.","example":"Er ist offenbar nicht gekommen.","exampleEn":"He apparently didn't come.","example2":"Offenbar hat sie den Termin vergessen.","example2En":"She apparently forgot the appointment."},{"de":"die Öffnung","en":"opening","pos":"noun","plural":"die Öffnungen","meanings":[{"en":"a gap or hole allowing access or passage","de":"eine Lücke oder ein Loch, durch das man hindurchgehen kann"},{"en":"the act of opening something","de":"das Öffnen von etwas"}],"rule":"Femininum; von 'öffnen' abgeleitetes Nomen auf -ung.","example":"Durch die Öffnung in der Wand sieht man den Garten.","exampleEn":"Through the opening in the wall you can see the garden.","example2":"Die Öffnung des neuen Museums war ein großes Ereignis.","example2En":"The opening of the new museum was a big event."},{"de":"der Oldtimer","en":"vintage car","pos":"noun","plural":"die Oldtimer","meanings":[{"en":"a classic, historic car","de":"ein altes, klassisches Auto"}],"rule":"Maskulin; Pseudoanglizismus, im Englischen nicht für Autos üblich.","example":"Auf der Messe wurden viele seltene Oldtimer ausgestellt.","exampleEn":"Many rare vintage cars were exhibited at the fair.","example2":"Sein Großvater besitzt einen Oldtimer aus den 1960er Jahren.","example2En":"His grandfather owns a vintage car from the 1960s."},{"de":"der Onlineeinkauf","en":"online purchase","pos":"noun","plural":"die Onlineeinkäufe","meanings":[{"en":"purchase made over the internet","de":"Kauf im Internet"}],"rule":"Compound noun: online + Einkauf; gender follows der Einkauf.","example":"Der Onlineeinkauf spart mir viel Zeit.","exampleEn":"Online shopping saves me a lot of time.","example2":"Bei diesem Onlineeinkauf gab es Rabatt.","example2En":"There was a discount on this online purchase."},{"de":"der Onlineshop","en":"online shop, online store","pos":"noun","plural":"die Onlineshops","meanings":[{"en":"a website where you can buy products","de":"Geschäft im Internet"}],"rule":"Also written 'Online-Shop'; plural simply adds -s (English loanword).","example":"Ich bestelle Schuhe in einem Onlineshop.","exampleEn":"I'm ordering shoes from an online shop.","example2":"Der Onlineshop bietet kostenlosen Versand an.","example2En":"The online shop offers free shipping."},{"de":"das Onlineshopping","en":"online shopping","pos":"noun","plural":"","meanings":[{"en":"the activity of shopping on the internet","de":"Einkaufen im Internet"}],"rule":"Uncountable noun, no plural; English loanword, often written 'Online-Shopping'.","example":"Onlineshopping ist bei jungen Leuten sehr beliebt.","exampleEn":"Online shopping is very popular among young people.","example2":"Beim Onlineshopping kann man Preise gut vergleichen.","example2En":"With online shopping you can easily compare prices."},{"de":"optimistisch","en":"optimistic","pos":"adjective","plural":"","meanings":[{"en":"expecting good outcomes; hopeful","de":"hoffnungsvoll, positiv denkend"}],"rule":"Regular comparison: optimistisch, optimistischer, am optimistischsten.","example":"Sie ist optimistisch, dass sie die Prüfung besteht.","exampleEn":"She is optimistic that she will pass the exam.","example2":"Trotz der Probleme bleibt er optimistisch.","example2En":"Despite the problems, he stays optimistic."},{"de":"das Original","en":"original","pos":"noun","plural":"die Originale","meanings":[{"en":"the genuine first version of something (not a copy)","de":"das Echte, keine Kopie"}],"rule":"Neuter noun; note adjective 'original' exists too but here used as a noun.","example":"Das ist kein Original, sondern eine Kopie.","exampleEn":"That's not an original, but a copy.","example2":"Bitte bringen Sie das Original des Dokuments mit.","example2En":"Please bring the original of the document."},{"de":"das Paket","en":"package, parcel","pos":"noun","plural":"die Pakete","meanings":[{"en":"a wrapped package sent by post","de":"verpackte Sendung per Post"},{"en":"a bundled set of things/services","de":"Bündel, z. B. Angebotspaket"}],"rule":"Neuter noun; common phrase 'ein Paket schicken/bekommen'.","example":"Ich habe ein Paket von meiner Mutter bekommen.","exampleEn":"I received a package from my mother.","example2":"Der Anbieter hat ein günstiges Paket für Internet und Telefon.","example2En":"The provider has a cheap package for internet and phone."},{"de":"der Paketbote","en":"parcel delivery man","pos":"noun","plural":"die Paketboten","meanings":[{"en":"a person who delivers parcels","de":"Person, die Pakete zustellt"}],"rule":"Feminine form: die Paketbotin; weak noun (den/dem/des Paketboten).","example":"Der Paketbote hat heute zweimal geklingelt.","exampleEn":"The parcel delivery man rang the bell twice today.","example2":"Ich habe das Paket persönlich vom Paketboten bekommen.","example2En":"I received the package personally from the delivery man."},{"de":"der Paketdienst","en":"parcel delivery service","pos":"noun","plural":"die Paketdienste","meanings":[{"en":"a company/service that delivers parcels","de":"Firma, die Pakete zustellt"}],"rule":"Compound: Paket + Dienst; gender follows der Dienst.","example":"Der Paketdienst bringt die Sendung morgen.","exampleEn":"The parcel service will deliver the shipment tomorrow.","example2":"Welcher Paketdienst liefert bei euch aus?","example2En":"Which parcel service delivers in your area?"},{"de":"der Papiermüll","en":"paper waste","pos":"noun","plural":"","meanings":[{"en":"waste consisting of paper, to be recycled","de":"Abfall aus Papier"}],"rule":"Uncountable; compound of Papier + Müll, gender follows der Müll.","example":"Alte Zeitungen kommen in den Papiermüll.","exampleEn":"Old newspapers go into the paper waste.","example2":"Der Papiermüll wird einmal im Monat abgeholt.","example2En":"The paper waste is collected once a month."},{"de":"die Pappe","en":"cardboard","pos":"noun","plural":"die Pappen","meanings":[{"en":"stiff, thick paper material","de":"dickes, festes Papier"}],"rule":"Usually used uncountably in singular; plural rarely used (types of cardboard).","example":"Der Karton ist aus dicker Pappe.","exampleEn":"The box is made of thick cardboard.","example2":"Wir haben das Plakat auf Pappe geklebt.","example2En":"We glued the poster onto cardboard."},{"de":"das Paradies","en":"paradise","pos":"noun","plural":"die Paradiese","meanings":[{"en":"a place of perfect happiness/beauty","de":"ein Ort vollkommenen Glücks"}],"rule":"Neuter noun; also religious sense (Garden of Eden), plural rarely used.","example":"Diese Insel ist wie ein Paradies.","exampleEn":"This island is like paradise.","example2":"Für Wanderer ist die Region ein wahres Paradies.","example2En":"For hikers, the region is a real paradise."},{"de":"parken","en":"to park","pos":"verb","plural":"","meanings":[{"en":"to stop and leave a vehicle somewhere","de":"ein Fahrzeug abstellen"}],"rule":"Regular (weak) verb: parkt, parkte, hat geparkt.","example":"Ich habe das Auto vor dem Haus geparkt.","exampleEn":"I parked the car in front of the house.","example2":"Hier darf man nicht parken.","example2En":"You're not allowed to park here."},{"de":"die Parklücke","en":"parking space","pos":"noun","plural":"die Parklücken","meanings":[{"en":"a gap in which a car can be parked","de":"freier Platz zum Parken"}],"rule":"Compound: parken + Lücke; gender follows die Lücke.","example":"Endlich habe ich eine Parklücke gefunden.","exampleEn":"I finally found a parking space.","example2":"Die Parklücke war zu klein für unser Auto.","example2En":"The parking space was too small for our car."},{"de":"der Passagier / die Passagierin","en":"passenger","pos":"noun","plural":"die Passagiere","meanings":[{"en":"a person travelling in a vehicle (plane, ship, train), not the driver","de":"Fahrgast, z. B. im Flugzeug oder Schiff"}],"rule":"Feminine form: die Passagierin, plural die Passagierinnen.","example":"Alle Passagiere müssen sich anschnallen.","exampleEn":"All passengers must fasten their seatbelts.","example2":"Der Flug hatte über 200 Passagiere.","example2En":"The flight had over 200 passengers."},{"de":"die Passkontrolle","en":"passport control","pos":"noun","plural":"die Passkontrollen","meanings":[{"en":"checking of passports at a border/airport","de":"Überprüfung des Reisepasses"}],"rule":"Compound: Pass + Kontrolle; gender follows die Kontrolle.","example":"Bei der Passkontrolle mussten wir lange warten.","exampleEn":"We had to wait a long time at passport control.","example2":"Bitte halten Sie Ihren Reisepass für die Passkontrolle bereit.","example2En":"Please have your passport ready for passport control."},{"de":"der PC","en":"PC, personal computer","pos":"noun","plural":"die PCs","meanings":[{"en":"personal computer","de":"Personalcomputer"}],"rule":"Abbreviation, pronounced 'Pe-Tse'; plural adds -s.","example":"Ich arbeite jeden Tag am PC.","exampleEn":"I work on the PC every day.","example2":"Der PC ist plötzlich abgestürzt.","example2En":"The PC suddenly crashed."},{"de":"der Personenschaden","en":"personal injury","pos":"noun","plural":"die Personenschäden","meanings":[{"en":"injury or harm to a person (e.g. in an accident)","de":"Verletzung einer Person, z. B. bei einem Unfall"}],"rule":"Compound: Person(en) + Schaden; contrast with 'Sachschaden' (property damage).","example":"Bei dem Unfall gab es keinen Personenschaden.","exampleEn":"There was no personal injury in the accident.","example2":"Zum Glück entstand nur ein Sachschaden, kein Personenschaden.","example2En":"Luckily only property damage occurred, no personal injury."},{"de":"die Pferdestärke (PS)","en":"horsepower (unit)","pos":"noun","plural":"(Plural: PS, unverändert)","meanings":[{"en":"unit measuring engine power","de":"Maßeinheit für die Leistung eines Motors"}],"rule":"feminine noun 'die Pferdestärke'; abbreviation PS is invariable in plural; often used with numbers: 90 PS","example":"Mein neues Auto hat 120 PS.","exampleEn":"My new car has 120 horsepower.","example2":"Wie viel PS hat dein Motorrad?","example2En":"How many horsepower does your motorcycle have?"},{"de":"der Pflegehelfer / die Pflegehelferin","en":"nursing assistant, care aide","pos":"noun","plural":"die Pflegehelfer","meanings":[{"en":"a person trained to assist in nursing/care work","de":"Person, die bei der Pflege hilft"}],"rule":"Feminine form: die Pflegehelferin, plural die Pflegehelferinnen.","example":"Der Pflegehelfer unterstützt die Krankenschwester.","exampleEn":"The nursing assistant supports the nurse.","example2":"Sie arbeitet als Pflegehelferin im Altenheim.","example2En":"She works as a care aide in the nursing home."},{"de":"die Pflegekraft","en":"caregiver; nurse/care worker","pos":"noun","plural":"die Pflegekräfte","meanings":[{"en":"a person who professionally cares for sick/elderly people","de":"jemand, der beruflich kranke oder alte Menschen pflegt"}],"rule":"Compound noun (Pflege + Kraft); feminine even when referring to a man, though 'Pflegekräfte' is often used as gender-neutral plural.","example":"Im Altenheim fehlen qualifizierte Pflegekräfte.","exampleEn":"The nursing home lacks qualified care workers.","example2":"Meine Mutter wird von einer Pflegekraft betreut.","example2En":"My mother is looked after by a caregiver."},{"de":"die Phase","en":"phase; stage","pos":"noun","plural":"die Phasen","meanings":[{"en":"a stage in a process or development","de":"ein Abschnitt in einer Entwicklung"}],"rule":"Weak-ish feminine noun, plural adds -n.","example":"Das Projekt befindet sich noch in der Planungsphase.","exampleEn":"The project is still in the planning phase.","example2":"Jedes Kind durchläuft verschiedene Phasen.","example2En":"Every child goes through different phases."},{"de":"das Picknick","en":"picnic","pos":"noun","plural":"die Picknicks","meanings":[{"en":"an outdoor meal eaten casually, often in nature","de":"ein Essen im Freien, meist in der Natur"}],"rule":"Neuter noun of English origin; plural with -s.","example":"Wir machen am Sonntag ein Picknick im Park.","exampleEn":"We're having a picnic in the park on Sunday.","example2":"Beim Picknick gab es Sandwiches und Obst.","example2En":"At the picnic there were sandwiches and fruit."},{"de":"der Pilotenstreik","en":"pilots' strike","pos":"noun","plural":"die Pilotenstreiks","meanings":[{"en":"a strike organized by airline pilots","de":"ein Streik der Flugzeugpiloten"}],"rule":"Compound noun (Piloten + Streik); follows gender of 'der Streik'.","example":"Wegen des Pilotenstreiks fallen viele Flüge aus.","exampleEn":"Because of the pilots' strike, many flights are cancelled.","example2":"Der Pilotenstreik dauerte drei Tage.","example2En":"The pilots' strike lasted three days."},{"de":"der Planet","en":"planet","pos":"noun","plural":"die Planeten","meanings":[{"en":"a large celestial body orbiting a star","de":"ein großer Himmelskörper, der einen Stern umkreist"}],"rule":"Weak masculine noun (n-declension): den/dem/des Planeten in singular oblique cases.","example":"Die Erde ist unser Planet.","exampleEn":"Earth is our planet.","example2":"Mars ist ein roter Planet.","example2En":"Mars is a red planet."},{"de":"das Plastik","en":"plastic (material)","pos":"noun","plural":"","meanings":[{"en":"synthetic material used for many products","de":"ein künstlich hergestellter Werkstoff"}],"rule":"Uncountable neuter noun; note: 'die Plastik' (feminine) means 'sculpture', a different word.","example":"Die Verpackung besteht aus Plastik.","exampleEn":"The packaging is made of plastic.","example2":"Wir versuchen, weniger Plastik zu verwenden.","example2En":"We try to use less plastic."},{"de":"politisch","en":"political","pos":"adjective","plural":"","meanings":[{"en":"relating to politics or government","de":"die Politik betreffend"}],"rule":"Regular adjective, no irregular comparison (politischer, am politischsten, rarely used comparatively).","example":"Er interessiert sich sehr für politische Themen.","exampleEn":"He is very interested in political topics.","example2":"Die Lage im Land ist politisch instabil.","example2En":"The situation in the country is politically unstable."},{"de":"der Pool","en":"pool (swimming)","pos":"noun","plural":"die Pools","meanings":[{"en":"a swimming pool","de":"ein Schwimmbecken"}],"rule":"Masculine noun of English origin; plural with -s.","example":"Im Sommer schwimmen wir jeden Tag im Pool.","exampleEn":"In summer we swim in the pool every day.","example2":"Das Hotel hat einen großen Pool.","example2En":"The hotel has a large pool."},{"de":"das Porto","en":"postage","pos":"noun","plural":"","meanings":[{"en":"the fee charged for mailing a letter or parcel","de":"die Gebühr für den Versand eines Briefes oder Pakets"}],"rule":"Usually uncountable in everyday use, though plural 'die Portos/Porti' exists rarely.","example":"Wie hoch ist das Porto für einen Brief nach Frankreich?","exampleEn":"How much is the postage for a letter to France?","example2":"Das Porto hat sich erhöht.","example2En":"Postage rates have gone up."},{"de":"portofrei","en":"postage-free","pos":"adjective","plural":"","meanings":[{"en":"without any charge for postage","de":"ohne Portokosten"}],"rule":"Compound adjective (Porto + frei); no irregular comparison.","example":"Ab 50 Euro liefern wir portofrei.","exampleEn":"From 50 euros we deliver free of postage.","example2":"Dieses Angebot gilt nur für portofreie Bestellungen.","example2En":"This offer only applies to postage-free orders."},{"de":"die Portokosten","en":"postage costs","pos":"noun","plural":"die Portokosten","meanings":[{"en":"the costs charged for postage","de":"die Kosten für das Porto"}],"rule":"Plural-only noun (Pluraletantum); always used in plural form.","example":"Die Portokosten trägt der Käufer.","exampleEn":"The buyer pays the postage costs.","example2":"Die Portokosten sind im Preis enthalten.","example2En":"The postage costs are included in the price."},{"de":"der Posteingang","en":"inbox","pos":"noun","plural":"die Posteingänge","meanings":[{"en":"the folder where incoming mail (post or email) arrives","de":"der Ordner für eingehende Post oder E-Mails"}],"rule":"Compound noun (Post + Eingang); follows gender of 'der Eingang'.","example":"Ich habe drei neue Nachrichten im Posteingang.","exampleEn":"I have three new messages in my inbox.","example2":"Bitte überprüfen Sie Ihren Posteingang.","example2En":"Please check your inbox."},{"de":"präsentieren","en":"to present","pos":"verb","plural":"","meanings":[{"en":"to show or explain something formally to others","de":"etwas vor anderen vorstellen oder erklären"}],"rule":"Regular weak verb; präsentiert, präsentierte, hat präsentiert; often takes an object (+ Akkusativ).","example":"Sie präsentiert morgen ihr neues Projekt.","exampleEn":"She is presenting her new project tomorrow.","example2":"Wir haben die Ergebnisse dem Team präsentiert.","example2En":"We presented the results to the team."},{"de":"die Privatnummer","en":"private phone number","pos":"noun","plural":"die Privatnummern","meanings":[{"en":"a personal, non-business phone number","de":"eine persönliche, nicht dienstliche Telefonnummer"}],"rule":"Compound noun (Privat + Nummer); follows gender of 'die Nummer'.","example":"Er hat mir seine Privatnummer gegeben.","exampleEn":"He gave me his private phone number.","example2":"Bitte rufen Sie mich nicht auf meiner Privatnummer an.","example2En":"Please don't call me on my private number."},{"de":"die Probezeit","en":"probation period","pos":"noun","plural":"die Probezeiten","meanings":[{"en":"a trial period at the start of a new job","de":"eine Testphase am Anfang einer neuen Arbeitsstelle"}],"rule":"Compound noun (Probe + Zeit); follows gender of 'die Zeit'.","example":"Meine Probezeit dauert sechs Monate.","exampleEn":"My probation period lasts six months.","example2":"In der Probezeit kann der Vertrag schneller gekündigt werden.","example2En":"During the probation period the contract can be terminated more quickly."},{"de":"problemlos","en":"without problems; smooth","pos":"adjective","plural":"","meanings":[{"en":"happening easily, without difficulties","de":"ohne Schwierigkeiten ablaufend"}],"rule":"Compound adjective (Problem + los); no irregular comparison.","example":"Die Reise verlief problemlos.","exampleEn":"The trip went smoothly, without problems.","example2":"Die Installation ist problemlos.","example2En":"The installation is problem-free."},{"de":"produzieren","en":"to produce","pos":"verb","plural":"","meanings":[{"en":"to manufacture or create goods, often on a larger scale","de":"etwas herstellen oder erzeugen"}],"rule":"Regular weak verb; produziert, produzierte, hat produziert; + Akkusativ.","example":"Die Firma produziert Autos.","exampleEn":"The company produces cars.","example2":"Der Vulkan produziert viel Rauch.","example2En":"The volcano produces a lot of smoke."},{"de":"der Protest","en":"protest","pos":"noun","plural":"die Proteste","meanings":[{"en":"a public expression of disapproval or objection","de":"eine öffentliche Ablehnung oder Beschwerde"}],"rule":"Masculine noun; often used with preposition 'gegen' (+ Akkusativ): Protest gegen etwas.","example":"Es gab einen lauten Protest gegen die neuen Regeln.","exampleEn":"There was a loud protest against the new rules.","example2":"Die Bürger organisierten einen Protest.","example2En":"The citizens organized a protest."},{"de":"protestieren","en":"to protest","pos":"verb","plural":"","meanings":[{"en":"to express opposition, object","de":"seinen Widerspruch/Unmut ausdrücken"}],"rule":"regelmäßig: protestiert, protestierte, hat protestiert; oft mit 'gegen + Akkusativ'","example":"Die Studenten protestieren gegen die Studiengebühren.","exampleEn":"The students are protesting against the tuition fees.","example2":"Er protestierte laut, aber niemand hörte ihm zu.","example2En":"He protested loudly, but nobody listened to him."},{"de":"die Qualifikation","en":"qualification","pos":"noun","plural":"die Qualifikationen","meanings":[{"en":"skills/education needed for a job","de":"fachliche Voraussetzung für einen Beruf"},{"en":"qualifying round in sport","de":"Ausscheidungswettkampf im Sport"}],"rule":"feminine noun ending in -ion; often used with 'für' or 'zu'","example":"Für diese Stelle brauchen Sie eine besondere Qualifikation.","exampleEn":"For this position you need a special qualification.","example2":"Die Mannschaft hat die Qualifikation für die WM geschafft.","example2En":"The team achieved qualification for the World Cup."},{"de":"die Qualität","en":"quality","pos":"noun","plural":"die Qualitäten","meanings":[{"en":"standard/degree of excellence","de":"Güte, Beschaffenheit"}],"rule":"feminine noun ending in -ät; opposite: die Quantität","example":"Die Qualität des Stoffes ist sehr gut.","exampleEn":"The quality of the fabric is very good.","example2":"Wir achten mehr auf Qualität als auf Quantität.","example2En":"We care more about quality than quantity."},{"de":"der Quark","en":"quark (soft curd cheese)","pos":"noun","plural":"","meanings":[{"en":"soft fresh cheese similar to curd","de":"weicher Frischkäse aus Milch"}],"rule":"masculine, uncountable (kein Plural); typical in German breakfasts and desserts","example":"Zum Frühstück esse ich gern Quark mit Früchten.","exampleEn":"For breakfast I like to eat quark with fruit.","example2":"Sie backt einen Kuchen mit Quark.","example2En":"She's baking a cake with quark."},{"de":"quietschen","en":"to squeak, to squeal","pos":"verb","plural":"","meanings":[{"en":"to make a high-pitched noise","de":"einen hohen, schrillen Ton von sich geben"}],"rule":"regelmäßig: quietscht, quietschte, hat gequietscht; oft bei Türen, Bremsen, Schuhen","example":"Die Tür quietscht, wenn man sie öffnet.","exampleEn":"The door squeaks when you open it.","example2":"Die Bremsen quietschten laut.","example2En":"The brakes squealed loudly."},{"de":"die Quizshow","en":"quiz show","pos":"noun","plural":"die Quizshows","meanings":[{"en":"TV entertainment program with questions","de":"Fernsehsendung mit Wissensfragen"}],"rule":"feminine noun; compound of 'Quiz' + 'Show' (beide Wörter aus dem Englischen)","example":"Jeden Samstag sehe ich mir eine Quizshow im Fernsehen an.","exampleEn":"Every Saturday I watch a quiz show on TV.","example2":"Er hat bei einer Quizshow viel Geld gewonnen.","example2En":"He won a lot of money on a quiz show."}]},{"id":"b1-14","title":"B1 · R–S (14)","level":"B1","words":[{"de":"das Radrennen","en":"cycle race","pos":"noun","plural":"die Radrennen","meanings":[{"en":"competitive race on bicycles","de":"sportlicher Wettkampf mit dem Fahrrad"}],"rule":"neuter compound noun: das Rad + das Rennen; plural unverändert (die Radrennen)","example":"Am Sonntag findet ein großes Radrennen statt.","exampleEn":"On Sunday there is a big cycle race.","example2":"Er trainiert jeden Tag für das Radrennen.","example2En":"He trains every day for the cycle race."},{"de":"die Rangliste","en":"ranking list","pos":"noun","plural":"die Ranglisten","meanings":[{"en":"list ordering people/teams by performance","de":"Liste, die nach Leistung ordnet"}],"rule":"feminine compound noun: der Rang + die Liste","example":"Sie steht auf Platz eins der Rangliste.","exampleEn":"She is in first place on the ranking list.","example2":"Die Rangliste wird jede Woche aktualisiert.","example2En":"The ranking list is updated every week."},{"de":"rasieren","en":"to shave","pos":"verb","plural":"","meanings":[{"en":"to remove facial/body hair with a razor","de":"Barthaare mit einem Rasierer entfernen"}],"rule":"regelmäßig: rasiert, rasierte, hat rasiert; oft reflexiv 'sich rasieren' (Akkusativ)","example":"Er rasiert sich jeden Morgen.","exampleEn":"He shaves every morning.","example2":"Der Friseur hat ihm den Bart rasiert.","example2En":"The barber shaved his beard."},{"de":"das Rätsel","en":"riddle, puzzle","pos":"noun","plural":"die Rätsel","meanings":[{"en":"a puzzling question or game","de":"eine schwierige Frage oder ein Denkspiel"},{"en":"something mysterious, unsolved","de":"etwas Unerklärliches, Geheimnisvolles"}],"rule":"neuter noun; plural unverändert (die Rätsel)","example":"Die Kinder lösen gern Rätsel.","exampleEn":"The children like solving puzzles.","example2":"Sein Verschwinden bleibt ein Rätsel.","example2En":"His disappearance remains a mystery."},{"de":"rechtzeitig","en":"on time, in time","pos":"adjective","plural":"","meanings":[{"en":"happening at the right/planned time","de":"zur richtigen Zeit, nicht zu spät"}],"rule":"regelmäßige Steigerung: rechtzeitig, rechtzeitiger, am rechtzeitigsten (selten gesteigert, meist nur im Positiv verwendet)","example":"Wir sind rechtzeitig am Flughafen angekommen.","exampleEn":"We arrived at the airport on time.","example2":"Bitte melde dich rechtzeitig, wenn du nicht kommen kannst.","example2En":"Please let us know in time if you can't come."},{"de":"recyceln","en":"to recycle","pos":"verb","plural":"","meanings":[{"en":"to process waste for reuse","de":"Abfall wiederverwerten"}],"rule":"regelmäßig: recycelt, recycelte, hat recycelt; Betonung auf der zweiten Silbe (re-CY-celn); 'ich'-Form verliert das e: ich recycle","example":"Wir recyceln Papier und Plastik.","exampleEn":"We recycle paper and plastic.","example2":"Diese Flaschen können recycelt werden.","example2En":"These bottles can be recycled."},{"de":"reduzieren","en":"to reduce","pos":"verb","plural":"","meanings":[{"en":"to make smaller/less in amount","de":"verringern, kleiner machen"}],"rule":"regelmäßig: reduziert, reduzierte, hat reduziert; oft mit 'um' (um wie viel) oder 'auf' (auf wie viel)","example":"Die Firma hat die Preise reduziert.","exampleEn":"The company has reduced the prices.","example2":"Er versucht, seinen Zuckerkonsum zu reduzieren.","example2En":"He is trying to reduce his sugar consumption."},{"de":"regeln","en":"to regulate, to arrange, to settle","pos":"verb","plural":"","meanings":[{"en":"to organize/settle something","de":"etwas ordnen oder klären"},{"en":"to control (e.g. traffic, a device)","de":"steuern, kontrollieren"}],"rule":"regelmäßig: regelt, regelte, hat geregelt","example":"Wir müssen noch die Details regeln.","exampleEn":"We still need to sort out the details.","example2":"Ein Polizist regelt den Verkehr an der Kreuzung.","example2En":"A police officer is directing traffic at the intersection."},{"de":"die Regierung","en":"government","pos":"noun","plural":"die Regierungen","meanings":[{"en":"the group governing a country/state","de":"die politische Führung eines Landes"}],"rule":"feminine noun from 'regieren'; oft mit 'an der Regierung sein'","example":"Die Regierung hat neue Gesetze beschlossen.","exampleEn":"The government has passed new laws.","example2":"Seit zehn Jahren ist diese Partei an der Regierung.","example2En":"This party has been in government for ten years."},{"de":"regulieren","en":"to regulate","pos":"verb","plural":"","meanings":[{"en":"to control or adjust something (e.g. by rules or technically)","de":"steuern, einstellen, durch Vorschriften kontrollieren"}],"rule":"regelmäßig: reguliert, regulierte, hat reguliert; oft technisch oder rechtlich verwendet","example":"Man kann die Temperatur am Thermostat regulieren.","exampleEn":"You can regulate the temperature on the thermostat.","example2":"Der Staat reguliert den Energiemarkt.","example2En":"The state regulates the energy market."},{"de":"die Regulierung","en":"regulation","pos":"noun","plural":"die Regulierungen","meanings":[{"en":"the act or system of controlling/adjusting something","de":"das Steuern, Einstellen oder Kontrollieren durch Vorschriften"}],"rule":"feminine noun from 'regulieren'; oft in Wirtschafts- und Politikkontexten","example":"Die Regulierung des Marktes soll fairer werden.","exampleEn":"The regulation of the market is supposed to become fairer.","example2":"Neue Regulierungen sollen die Umwelt schützen.","example2En":"New regulations are meant to protect the environment."},{"de":"der Reifen","en":"tire","pos":"noun","plural":"die Reifen","meanings":[{"en":"tire (of a vehicle)","de":"Gummiring am Rad eines Fahrzeugs"}],"rule":"Der Plural ist identisch mit dem Singular: der Reifen, die Reifen.","example":"Der Reifen meines Autos ist kaputt.","exampleEn":"My car's tire is flat.","example2":"Im Winter brauchst du andere Reifen.","example2En":"In winter you need different tires."},{"de":"die Reihe","en":"row; series","pos":"noun","plural":"die Reihen","meanings":[{"en":"row (line of things/people)","de":"mehrere Personen oder Dinge nebeneinander"},{"en":"series, sequence","de":"eine Abfolge von Dingen"}],"rule":"Feste Ausdrücke: 'in der ersten Reihe sitzen', 'eine Reihe von' (+ Dativ) = mehrere.","example":"Wir sitzen in der dritten Reihe.","exampleEn":"We are sitting in the third row.","example2":"Es gab eine Reihe von Problemen.","example2En":"There was a series of problems."},{"de":"die Reinigungsfirma","en":"cleaning company","pos":"noun","plural":"die Reinigungsfirmen","meanings":[{"en":"company that cleans buildings/offices","de":"Firma, die putzt"}],"rule":"Zusammensetzung aus 'reinigen' + 'Firma'; Genus vom letzten Bestandteil: die Firma.","example":"Die Reinigungsfirma putzt jeden Abend unser Büro.","exampleEn":"The cleaning company cleans our office every evening.","example2":"Wir haben eine neue Reinigungsfirma beauftragt.","example2En":"We hired a new cleaning company."},{"de":"der Reinigungsvertrag","en":"cleaning contract","pos":"noun","plural":"die Reinigungsverträge","meanings":[{"en":"contract for cleaning services","de":"Vertrag über Reinigungsleistungen"}],"rule":"Zusammensetzung; Genus vom letzten Bestandteil: der Vertrag. Plural mit Umlaut: -verträge.","example":"Wir haben einen Reinigungsvertrag mit der Firma unterschrieben.","exampleEn":"We signed a cleaning contract with the company.","example2":"Der Reinigungsvertrag läuft ein Jahr.","example2En":"The cleaning contract runs for one year."},{"de":"das Reisebüro","en":"travel agency","pos":"noun","plural":"die Reisebüros","meanings":[{"en":"travel agency","de":"Büro, das Reisen plant und verkauft"}],"rule":"Zusammensetzung aus 'Reise' + 'Büro'; Genus vom letzten Bestandteil: das Büro. Plural auf -s.","example":"Ich habe die Reise im Reisebüro gebucht.","exampleEn":"I booked the trip at the travel agency.","example2":"Das Reisebüro hat ein gutes Angebot für Spanien.","example2En":"The travel agency has a good deal for Spain."},{"de":"der Reiseplan","en":"travel itinerary","pos":"noun","plural":"die Reisepläne","meanings":[{"en":"itinerary, travel plan","de":"Plan für eine Reise"}],"rule":"Zusammensetzung; Genus vom letzten Bestandteil: der Plan. Plural mit Umlaut: -pläne.","example":"Unser Reiseplan sieht drei Städte vor.","exampleEn":"Our travel itinerary includes three cities.","example2":"Kannst du mir den Reiseplan schicken?","example2En":"Can you send me the itinerary?"},{"de":"die Reiseplanung","en":"trip planning","pos":"noun","plural":"","meanings":[{"en":"the process of planning a trip","de":"das Planen einer Reise"}],"rule":"Meist unzählbar, kein Plural üblich.","example":"Die Reiseplanung hat viel Zeit gekostet.","exampleEn":"Planning the trip took a lot of time.","example2":"Bei der Reiseplanung helfen wir dir gern.","example2En":"We're happy to help you with trip planning."},{"de":"reiten","en":"to ride (a horse)","pos":"verb","plural":"","meanings":[{"en":"to ride a horse","de":"auf einem Pferd sitzen und es lenken"}],"rule":"unregelmäßig: reitet, ritt, ist/hat geritten (mit 'sein' bei Richtungsangabe, mit 'haben' ohne).","example":"Sie reitet jeden Samstag auf dem Bauernhof.","exampleEn":"She rides a horse every Saturday on the farm.","example2":"Wir sind durch den Wald geritten.","example2En":"We rode through the forest."},{"de":"die Reklamation","en":"complaint (about goods/services)","pos":"noun","plural":"die Reklamationen","meanings":[{"en":"complaint about a faulty product or bad service","de":"Beschwerde wegen eines Mangels"}],"rule":"Typisch: 'eine Reklamation einreichen/bearbeiten'.","example":"Ich möchte wegen dieses Geräts eine Reklamation einreichen.","exampleEn":"I would like to file a complaint about this device.","example2":"Die Firma bearbeitet die Reklamation innerhalb einer Woche.","example2En":"The company processes the complaint within a week."},{"de":"die Reportage","en":"report, reportage","pos":"noun","plural":"die Reportagen","meanings":[{"en":"journalistic report/feature","de":"Bericht in Zeitung, Radio oder Fernsehen"}],"rule":"Aus dem Französischen, betont auf der letzten Silbe: Reporta-ge [ʒə].","example":"Im Fernsehen lief eine Reportage über Umweltschutz.","exampleEn":"There was a report on TV about environmental protection.","example2":"Er schreibt eine Reportage über das Leben in der Stadt.","example2En":"He is writing a feature about life in the city."},{"de":"der Reporter / die Reporterin","en":"reporter","pos":"noun","plural":"die Reporter / die Reporterinnen","meanings":[{"en":"journalist who reports news","de":"Person, die für Zeitung, Radio oder TV berichtet"}],"rule":"Weibliche Form mit -in: die Reporterin, Plural die Reporterinnen.","example":"Der Reporter interviewt den Bürgermeister.","exampleEn":"The reporter is interviewing the mayor.","example2":"Die Reporterin berichtet live vom Unfallort.","example2En":"The reporter is reporting live from the accident scene."},{"de":"die Republik","en":"republic","pos":"noun","plural":"die Republiken","meanings":[{"en":"republic (form of government)","de":"Staatsform ohne Monarchie"}],"rule":"Feste Wendung: 'die Bundesrepublik Deutschland'.","example":"Deutschland ist eine Republik.","exampleEn":"Germany is a republic.","example2":"Die Republik wurde 1949 gegründet.","example2En":"The republic was founded in 1949."},{"de":"die Retoure","en":"return (of goods)","pos":"noun","plural":"die Retouren","meanings":[{"en":"returned item/shipment","de":"zurückgeschickte Ware"}],"rule":"Typisch beim Online-Einkauf: 'eine Retoure schicken'.","example":"Die Retoure ist gestern bei uns angekommen.","exampleEn":"The return arrived at our place yesterday.","example2":"Sie hat die Schuhe als Retoure zurückgeschickt.","example2En":"She sent the shoes back as a return."},{"de":"der Retourenschein","en":"return label/slip","pos":"noun","plural":"die Retourenscheine","meanings":[{"en":"label/form used to send back goods","de":"Schein, mit dem man Ware zurückschickt"}],"rule":"Zusammensetzung aus 'Retoure' + 'Schein'; Genus vom letzten Bestandteil: der Schein.","example":"Leg den Retourenschein in das Paket.","exampleEn":"Put the return label in the package.","example2":"Ohne Retourenschein kann ich die Ware nicht zurückschicken.","example2En":"Without a return slip I can't send the item back."},{"de":"retten","en":"to save, to rescue","pos":"verb","plural":"","meanings":[{"en":"to rescue someone/something from danger","de":"jemanden/etwas aus Gefahr befreien"}],"rule":"regelmäßig: rettet, rettete, hat gerettet.","example":"Die Feuerwehr hat den Mann aus dem brennenden Haus gerettet.","exampleEn":"The fire brigade saved the man from the burning house.","example2":"Er konnte den Hund vor dem Ertrinken retten.","example2En":"He managed to save the dog from drowning."},{"de":"der Richter / die Richterin","en":"judge","pos":"noun","plural":"die Richter / die Richterinnen","meanings":[{"en":"judge at a court","de":"Person, die vor Gericht entscheidet"}],"rule":"Weibliche Form mit -in: die Richterin.","example":"Der Richter verurteilte den Mann zu einer Geldstrafe.","exampleEn":"The judge sentenced the man to a fine.","example2":"Die Richterin hat das Urteil heute verkündet.","example2En":"The judge announced the verdict today."},{"de":"romantisch","en":"romantic","pos":"adjective","plural":"","meanings":[{"en":"romantic (loving, emotionally beautiful)","de":"gefühlvoll, liebevoll"}],"rule":"Regelmäßige Steigerung: romantisch, romantischer, am romantischsten.","example":"Wir haben ein romantisches Abendessen zu zweit.","exampleEn":"We're having a romantic dinner for two.","example2":"Die kleine Stadt hat eine romantische Altstadt.","example2En":"The small town has a romantic old town."},{"de":"das Rücklicht","en":"rear light, taillight","pos":"noun","plural":"die Rücklichter","meanings":[{"en":"rear/taillight of a vehicle","de":"Licht hinten am Auto oder Fahrrad"}],"rule":"Zusammensetzung aus 'Rück-' + 'Licht'; Genus vom letzten Bestandteil: das Licht.","example":"Dein Rücklicht ist kaputt.","exampleEn":"Your rear light is broken.","example2":"Bei Dunkelheit muss das Rücklicht am Fahrrad leuchten.","example2En":"In the dark, the bicycle's taillight must be lit."},{"de":"die Rückscheibe","en":"rear window (car)","pos":"noun","plural":"die Rückscheiben","meanings":[{"en":"rear window of a vehicle","de":"das hintere Fenster eines Autos"}],"rule":"Kompositum aus dem Präfix 'Rück-' (verwandt mit 'zurück') + 'Scheibe'; Genus wie 'die Scheibe'.","example":"Die Rückscheibe des Autos ist beschlagen.","exampleEn":"The car's rear window is fogged up.","example2":"Kannst du die Rückscheibe sauber machen?","example2En":"Can you clean the rear window?"},{"de":"die Rücksendung","en":"return shipment","pos":"noun","plural":"die Rücksendungen","meanings":[{"en":"sending something back (e.g. a package)","de":"das Zurücksenden einer Ware"}],"rule":"von 'zurücksenden'; oft im Online-Shopping-Kontext.","example":"Die Rücksendung des Pakets ist kostenlos.","exampleEn":"Returning the package is free of charge.","example2":"Bitte legen Sie das Formular der Rücksendung bei.","example2En":"Please enclose the form with the return shipment."},{"de":"die Rücksicht","en":"consideration, regard","pos":"noun","plural":"","meanings":[{"en":"consideration/thoughtfulness towards others","de":"das Achten auf andere Menschen"}],"rule":"meist uncountable; feste Wendung: 'Rücksicht nehmen auf + Akkusativ'.","example":"Bitte nimm Rücksicht auf die Nachbarn.","exampleEn":"Please be considerate of the neighbors.","example2":"Im Straßenverkehr sollte man immer Rücksicht nehmen.","example2En":"In traffic you should always show consideration for others."},{"de":"rückwärts","en":"backwards","pos":"adverb","plural":"","meanings":[{"en":"in a backward direction","de":"in Richtung nach hinten"}],"rule":"keine Steigerung; Gegenteil von 'vorwärts'.","example":"Er fährt das Auto rückwärts aus der Garage.","exampleEn":"He drives the car backwards out of the garage.","example2":"Kannst du von zehn rückwärts zählen?","example2En":"Can you count backwards from ten?"},{"de":"die Ruhezeit","en":"rest period, quiet hours","pos":"noun","plural":"die Ruhezeiten","meanings":[{"en":"designated period of rest or quiet","de":"eine Zeit, in der Ruhe herrschen soll"}],"rule":"Kompositum aus 'Ruhe' + 'Zeit'; in Deutschland oft gesetzlich geregelt (z. B. Mittagsruhe).","example":"In der Ruhezeit darf man keine laute Musik hören.","exampleEn":"During quiet hours you're not allowed to play loud music.","example2":"Die Ruhezeit beginnt um 22 Uhr.","example2En":"Quiet hours start at 10 p.m."},{"de":"die Runde","en":"round, lap","pos":"noun","plural":"die Runden","meanings":[{"en":"a lap or circuit (sports, race)","de":"eine Strecke im Kreis, z. B. beim Sport"},{"en":"a round (of drinks, a game, negotiations)","de":"ein Durchgang, z. B. bei Getränken oder Verhandlungen"}],"rule":"feste Wendung: 'eine Runde drehen/laufen'; 'eine Runde ausgeben' (Getränke spendieren).","example":"Wir laufen noch eine Runde um den See.","exampleEn":"We're doing one more lap around the lake.","example2":"Er hat eine Runde Bier ausgegeben.","example2En":"He bought a round of beer."},{"de":"rutschen","en":"to slip, to slide","pos":"verb","plural":"","meanings":[{"en":"to slide or skid (on a surface)","de":"sich gleitend auf einer Oberfläche bewegen"},{"en":"to slip and lose one's footing","de":"das Gleichgewicht verlieren und ausrutschen"}],"rule":"regelmäßig; Perfekt mit 'sein': ist gerutscht (Bewegung/Ortswechsel).","example":"Die Kinder rutschen gern die Rutsche runter.","exampleEn":"The children love sliding down the slide.","example2":"Pass auf, auf dem Eis kann man leicht rutschen!","example2En":"Be careful, it's easy to slip on the ice!"},{"de":"der Sachbearbeiter / die Sachbearbeiterin","en":"clerk, case handler","pos":"noun","plural":"die Sachbearbeiter/innen","meanings":[{"en":"office employee responsible for handling a specific case or task","de":"jemand, der Aufgaben oder Anträge bei einer Behörde/Firma bearbeitet"}],"rule":"Kompositum aus 'Sache' + 'Bearbeiter'; typische Berufsbezeichnung in Ämtern und Firmen.","example":"Der Sachbearbeiter prüft Ihren Antrag.","exampleEn":"The case handler is reviewing your application.","example2":"Bitte wenden Sie sich an die zuständige Sachbearbeiterin.","example2En":"Please contact the responsible clerk."},{"de":"der Sachschaden","en":"property damage","pos":"noun","plural":"die Sachschäden","meanings":[{"en":"damage to property or objects (not people)","de":"Schaden an Gegenständen oder Eigentum, kein Personenschaden"}],"rule":"Kompositum aus 'Sache' + 'Schaden'; Gegensatz: 'Personenschaden'.","example":"Bei dem Unfall entstand nur Sachschaden.","exampleEn":"The accident only caused property damage.","example2":"Der Sturm hat einen hohen Sachschaden verursacht.","example2En":"The storm caused extensive property damage."},{"de":"der Sack","en":"sack, bag","pos":"noun","plural":"die Säcke","meanings":[{"en":"a large bag made of cloth, paper or plastic","de":"ein großer Beutel aus Stoff, Papier oder Plastik"}],"rule":"maskulin, Plural mit Umlaut: der Sack – die Säcke.","example":"Er trägt einen Sack Kartoffeln in den Keller.","exampleEn":"He carries a sack of potatoes into the cellar.","example2":"Wir brauchen noch einen Sack Zement.","example2En":"We still need a bag of cement."},{"de":"der Sales Manager / die Sales Managerin","en":"sales manager","pos":"noun","plural":"die Sales Manager/innen","meanings":[{"en":"person responsible for managing sales activities","de":"jemand, der für den Verkauf/Vertrieb einer Firma zuständig ist"}],"rule":"englisches Lehnwort im Berufskontext; Genus folgt dem biologischen Geschlecht.","example":"Sie arbeitet als Sales Managerin bei einer großen Firma.","exampleEn":"She works as a sales manager at a large company.","example2":"Der Sales Manager präsentiert die neuen Verkaufszahlen.","example2En":"The sales manager presents the new sales figures."},{"de":"sammeln","en":"to collect, to gather","pos":"verb","plural":"","meanings":[{"en":"to collect objects as a hobby or systematically","de":"Dinge als Hobby oder systematisch zusammentragen"},{"en":"to gather people or things together","de":"Personen oder Dinge an einem Ort zusammenbringen"}],"rule":"regelmäßig; Perfekt mit 'haben': hat gesammelt; auch reflexiv: 'sich sammeln' (sich versammeln).","example":"Mein Sohn sammelt Briefmarken.","exampleEn":"My son collects stamps.","example2":"Die Schüler sammeln sich vor dem Eingang.","example2En":"The students gather in front of the entrance."},{"de":"die Sammelstelle","en":"collection point","pos":"noun","plural":"die Sammelstellen","meanings":[{"en":"a designated place where things (e.g. waste, donations) are collected","de":"ein Ort, an dem etwas (z. B. Müll oder Spenden) gesammelt wird"}],"rule":"Kompositum aus 'sammeln' + 'Stelle'.","example":"Alte Batterien bringt man zur Sammelstelle.","exampleEn":"You take old batteries to the collection point.","example2":"Die Sammelstelle für Kleidung ist am Marktplatz.","example2En":"The clothing collection point is at the market square."},{"de":"sauber","en":"clean","pos":"adjective","plural":"","meanings":[{"en":"clean, free of dirt","de":"ohne Schmutz"},{"en":"neat, tidy, proper (figurative: honest)","de":"ordentlich, korrekt, ehrlich"}],"rule":"regelmäßige Steigerung: sauber, sauberer, am saubersten.","example":"Die Küche ist endlich wieder sauber.","exampleEn":"The kitchen is finally clean again.","example2":"Er hat eine saubere Arbeit abgeliefert.","example2En":"He delivered a neat, proper piece of work."},{"de":"die Sauberkeit","en":"cleanliness","pos":"noun","plural":"","meanings":[{"en":"the state of being clean","de":"der Zustand, sauber zu sein"}],"rule":"von 'sauber' abgeleitetes Abstraktum; uncountable, kein Plural.","example":"In diesem Restaurant achtet man sehr auf Sauberkeit.","exampleEn":"This restaurant pays great attention to cleanliness.","example2":"Die Sauberkeit der Straßen hat sich verbessert.","example2En":"The cleanliness of the streets has improved."},{"de":"sauer","en":"sour; angry","pos":"adjective","plural":"","meanings":[{"en":"sour, acidic in taste","de":"mit saurem Geschmack, z. B. Zitrone"},{"en":"(colloquial) angry, upset","de":"(umgangssprachlich) verärgert, wütend"}],"rule":"regelmäßige Steigerung: sauer, saurer, am sauersten; umgangssprachlich: 'sauer sein auf jemanden' (+ Akkusativ).","example":"Die Zitrone schmeckt sehr sauer.","exampleEn":"The lemon tastes very sour.","example2":"Er ist sauer auf seinen Bruder.","example2En":"He's angry at his brother."},{"de":"der Schaden","en":"damage, harm","pos":"noun","plural":"die Schäden","meanings":[{"en":"physical or material damage","de":"ein materieller oder körperlicher Schaden"},{"en":"harm, disadvantage (figurative)","de":"ein Nachteil oder negative Folge"}],"rule":"Plural mit Umlaut: der Schaden – die Schäden; feste Wendung: 'einen Schaden verursachen/melden'.","example":"Der Unfall hat einen großen Schaden verursacht.","exampleEn":"The accident caused a lot of damage.","example2":"Rauchen kann der Gesundheit erheblichen Schaden zufügen.","example2En":"Smoking can cause significant harm to your health."},{"de":"der Schadensfall","en":"case of damage/loss","pos":"noun","plural":"die Schadensfälle","meanings":[{"en":"an event causing damage or loss (esp. insurance)","de":"ein Ereignis, bei dem ein Schaden entsteht"}],"rule":"Compound noun (Schaden + Fall); gender follows der Fall. Common in insurance contexts: 'im Schadensfall'.","example":"Im Schadensfall müssen Sie die Versicherung sofort informieren.","exampleEn":"In the event of a claim, you must inform the insurance company immediately.","example2":"Der Schadensfall wurde von einem Gutachter geprüft.","example2En":"The case of damage was examined by an assessor."},{"de":"schädigen","en":"to damage, to harm","pos":"verb","plural":"","meanings":[{"en":"to cause harm or damage to someone/something","de":"jemandem/etwas Schaden zufügen"}],"rule":"Regular weak verb: schädigt, schädigte, hat geschädigt. Often + Akkusativ (jemanden/etwas schädigen).","example":"Rauchen schädigt die Gesundheit.","exampleEn":"Smoking damages your health.","example2":"Der Skandal hat das Image der Firma schwer geschädigt.","example2En":"The scandal severely damaged the company's image."},{"de":"schädlich","en":"harmful","pos":"adjective","plural":"","meanings":[{"en":"causing harm or damage","de":"Schaden verursachend"}],"rule":"Regular comparison: schädlich, schädlicher, am schädlichsten. Often used with 'für': schädlich für die Umwelt.","example":"Zu viel Zucker ist schädlich für die Zähne.","exampleEn":"Too much sugar is harmful to your teeth.","example2":"Die Abgase sind schädlich für die Umwelt.","example2En":"The exhaust fumes are harmful to the environment."},{"de":"der Schadstoff","en":"pollutant, harmful substance","pos":"noun","plural":"die Schadstoffe","meanings":[{"en":"a substance that is harmful to health or the environment","de":"ein Stoff, der Gesundheit oder Umwelt schadet"}],"rule":"Compound: Schaden + Stoff → der Stoff (masculine).","example":"Das neue Auto stößt weniger Schadstoffe aus.","exampleEn":"The new car emits fewer pollutants.","example2":"Die Fabrik leitet Schadstoffe in den Fluss.","example2En":"The factory discharges pollutants into the river."}]},{"id":"b1-15","title":"B1 · S (15)","level":"B1","words":[{"de":"schalten","en":"to switch, to shift gears","pos":"verb","plural":"","meanings":[{"en":"to operate a switch/change a setting","de":"einen Schalter bedienen, etwas umstellen"},{"en":"to shift gears (in a car)","de":"beim Autofahren den Gang wechseln"}],"rule":"Regular weak verb: schaltet, schaltete, hat geschaltet. 'in den dritten Gang schalten' = shift into third gear.","example":"Bitte schalte das Licht aus.","exampleEn":"Please switch off the light.","example2":"Beim Bergabfahren musst du in einen niedrigeren Gang schalten.","example2En":"When going downhill you have to shift into a lower gear."},{"de":"der Schalter","en":"switch; counter/window (service desk)","pos":"noun","plural":"die Schalter","meanings":[{"en":"a device to turn something on/off","de":"ein Gerät zum Ein- und Ausschalten"},{"en":"a service counter or window (e.g. at a bank, post office)","de":"ein Bereich, an dem man bedient wird, z. B. in einer Bank"}],"rule":"Masculine noun, plural unchanged (der Schalter – die Schalter).","example":"Der Schalter an der Wand funktioniert nicht mehr.","exampleEn":"The switch on the wall doesn't work anymore.","example2":"Gehen Sie bitte zu Schalter 3.","example2En":"Please go to counter number 3."},{"de":"die Scheibe","en":"pane (of glass); slice","pos":"noun","plural":"die Scheiben","meanings":[{"en":"a pane of glass, e.g. a window","de":"eine Glasplatte, z. B. in einem Fenster"},{"en":"a slice (of bread, cheese, etc.)","de":"ein dünnes, flaches Stück, z. B. von Brot"}],"rule":"Feminine noun. Common collocation: eine Scheibe Brot (a slice of bread), die Windschutzscheibe (windshield).","example":"Die Scheibe des Autos ist kaputt.","exampleEn":"The car window is broken.","example2":"Ich möchte noch eine Scheibe Brot, bitte.","example2En":"I'd like another slice of bread, please."},{"de":"der Scheinwerfer","en":"headlight; spotlight","pos":"noun","plural":"die Scheinwerfer","meanings":[{"en":"a car headlight","de":"das Licht vorne am Auto"},{"en":"a spotlight (e.g. on stage)","de":"ein starkes Licht, z. B. auf der Bühne"}],"rule":"Masculine noun, plural unchanged. Compound of 'scheinen' (to shine) + 'Werfer' (thrower).","example":"Bitte schalte die Scheinwerfer ein, es wird dunkel.","exampleEn":"Please turn on the headlights, it's getting dark.","example2":"Der Sänger stand im Licht der Scheinwerfer.","example2En":"The singer stood in the light of the spotlights."},{"de":"der Schiedsrichter","en":"referee, umpire","pos":"noun","plural":"die Schiedsrichter","meanings":[{"en":"an official who enforces the rules in a sports match","de":"eine Person, die bei einem Sportspiel die Regeln kontrolliert"}],"rule":"Masculine noun; female form die Schiedsrichterin. Plural unchanged for masculine.","example":"Der Schiedsrichter zeigte dem Spieler die rote Karte.","exampleEn":"The referee showed the player the red card.","example2":"Die Fans waren mit der Entscheidung des Schiedsrichters nicht einverstanden.","example2En":"The fans disagreed with the referee's decision."},{"de":"schießen","en":"to shoot","pos":"verb","plural":"","meanings":[{"en":"to fire a weapon or shoot a ball","de":"eine Waffe abfeuern oder einen Ball stark treten/werfen"}],"rule":"Irregular (strong) verb: schießt, schoss, hat geschossen. 'ein Tor schießen' = to score a goal.","example":"Er hat in letzter Minute ein Tor geschossen.","exampleEn":"He scored a goal in the last minute.","example2":"Die Polizei musste in die Luft schießen.","example2En":"The police had to shoot into the air."},{"de":"der Schläger","en":"racket/bat/club; thug","pos":"noun","plural":"die Schläger","meanings":[{"en":"a racket, bat, or club used in sports (tennis, golf, hockey)","de":"ein Sportgerät zum Schlagen, z. B. beim Tennis"},{"en":"a violent person, thug","de":"eine gewalttätige Person"}],"rule":"Masculine noun, plural unchanged. Derived from 'schlagen' (to hit).","example":"Ich brauche einen neuen Tennisschläger.","exampleEn":"I need a new tennis racket.","example2":"Vor der Disco kam es zu einer Schlägerei mit mehreren Schlägern.","example2En":"There was a brawl with several thugs outside the club."},{"de":"die Schlange","en":"snake; queue/line","pos":"noun","plural":"die Schlangen","meanings":[{"en":"a snake (the animal)","de":"ein Reptil ohne Beine"},{"en":"a queue, a line of waiting people","de":"eine lange Reihe wartender Menschen"}],"rule":"Feminine noun. 'Schlange stehen' = to stand in line/queue.","example":"Im Zoo haben wir eine giftige Schlange gesehen.","exampleEn":"At the zoo we saw a poisonous snake.","example2":"Vor der Kasse mussten wir lange Schlange stehen.","example2En":"We had to stand in a long queue at the checkout."},{"de":"schmutzig","en":"dirty","pos":"adjective","plural":"","meanings":[{"en":"not clean, soiled","de":"nicht sauber, voller Schmutz"}],"rule":"Regular comparison: schmutzig, schmutziger, am schmutzigsten.","example":"Deine Schuhe sind total schmutzig.","exampleEn":"Your shoes are totally dirty.","example2":"Die schmutzige Wäsche liegt im Korb.","example2En":"The dirty laundry is lying in the basket."},{"de":"schneiden","en":"to cut","pos":"verb","plural":"","meanings":[{"en":"to cut something with a knife/scissors","de":"mit einem Messer oder einer Schere teilen"},{"en":"to cut oneself (injure)","de":"sich verletzen, indem man sich schneidet"}],"rule":"Irregular verb: schneidet, schnitt, hat geschnitten. Reflexive possible: sich schneiden (to cut oneself).","example":"Kannst du das Brot in Scheiben schneiden?","exampleEn":"Can you cut the bread into slices?","example2":"Ich habe mich beim Kochen in den Finger geschnitten.","example2En":"I cut my finger while cooking."},{"de":"das Schreiben","en":"letter, written document","pos":"noun","plural":"die Schreiben","meanings":[{"en":"a formal letter or written document","de":"ein offizieller Brief oder ein schriftliches Dokument"}],"rule":"Neuter noun (nominalized infinitive of 'schreiben'); plural unchanged. Used in formal/official contexts.","example":"Wir haben ein Schreiben vom Finanzamt bekommen.","exampleEn":"We received a letter from the tax office.","example2":"Bitte antworten Sie auf unser Schreiben bis zum 10. Oktober.","example2En":"Please reply to our letter by October 10th."},{"de":"schützen","en":"to protect","pos":"verb","plural":"","meanings":[{"en":"to protect someone/something from harm","de":"jemanden/etwas vor Schaden bewahren"}],"rule":"Regular weak verb: schützt, schützte, hat geschützt. Often + 'vor' (+ Dativ): jemanden vor etwas schützen.","example":"Eine Creme schützt die Haut vor der Sonne.","exampleEn":"A cream protects the skin from the sun.","example2":"Die Polizei soll die Bürger schützen.","example2En":"The police are supposed to protect citizens."},{"de":"schwingen","en":"to swing, to vibrate","pos":"verb","plural":"","meanings":[{"en":"to move back and forth, to swing something","de":"sich hin und her bewegen oder etwas hin und her bewegen"},{"en":"to vibrate/resonate (sound, feeling)","de":"schwingen, z. B. bei Tönen oder Gefühlen mitschwingen"}],"rule":"Irregular verb: schwingt, schwang, hat geschwungen. 'sich schwingen' (reflexive) = to swing oneself up onto something.","example":"Er schwang den Hammer kräftig.","exampleEn":"He swung the hammer powerfully.","example2":"In ihrer Stimme schwang etwas Traurigkeit mit.","example2En":"There was a hint of sadness in her voice."},{"de":"die Seifenoper","en":"soap opera","pos":"noun","plural":"die Seifenopern","meanings":[{"en":"a long-running, dramatic TV series (soap opera)","de":"eine lange, dramatische Fernsehserie"}],"rule":"Feminine noun (compound: Seife + Oper); loan translation of English 'soap opera'.","example":"Meine Oma sieht jeden Nachmittag ihre Lieblings-Seifenoper.","exampleEn":"My grandma watches her favorite soap opera every afternoon.","example2":"Die Handlung der Serie ist wie in einer Seifenoper.","example2En":"The plot of the series is like in a soap opera."},{"de":"seitdem","en":"since then; since (temporal conjunction/adverb)","pos":"adverb","plural":"","meanings":[{"en":"since then (adverb)","de":"von diesem Zeitpunkt an"},{"en":"since / ever since (conjunction)","de":"seit dem Zeitpunkt, an dem"}],"rule":"Als Adverb steht 'seitdem' allein im Satz; als Konjunktion leitet es einen Nebensatz ein (Verb ans Ende).","example":"Er hat vor drei Jahren geheiratet, seitdem wohnt er in Köln.","exampleEn":"He got married three years ago; since then he has lived in Cologne.","example2":"Seitdem sie umgezogen ist, sehen wir uns selten.","example2En":"Since she moved, we rarely see each other."},{"de":"der Selbstständige / die Selbstständige","en":"self-employed person","pos":"noun","plural":"die Selbstständigen","meanings":[{"en":"a self-employed person","de":"jemand, der eine eigene Firma hat und nicht angestellt ist"}],"rule":"Substantiviertes Adjektiv: wird wie ein Adjektiv dekliniert (ein Selbstständiger, die Selbstständigen).","example":"Als Selbstständige muss sie ihre Steuern selbst berechnen.","exampleEn":"As a self-employed person, she has to calculate her own taxes.","example2":"Viele Selbstständige haben keine feste Arbeitszeit.","example2En":"Many self-employed people have no fixed working hours."},{"de":"selbstverständlich","en":"obvious(ly); naturally, of course","pos":"adjective","plural":"","meanings":[{"en":"obvious / natural","de":"klar, logisch"},{"en":"of course (as adverb)","de":"natürlich"}],"rule":"Sehr häufig als Antwort-Adverb im Sinn von 'natürlich, gerne'.","example":"Das ist doch selbstverständlich!","exampleEn":"That's obvious, of course!","example2":"Selbstverständlich helfe ich dir.","example2En":"Of course I'll help you."},{"de":"senden","en":"to send; to broadcast","pos":"verb","plural":"","meanings":[{"en":"to send (mail, a signal)","de":"schicken"},{"en":"to broadcast (TV/radio)","de":"im Fernsehen/Radio übertragen"}],"rule":"sendet, sandte/sendete, hat gesandt/gesendet (beide Formen korrekt; 'gesendet' meist für Rundfunk).","example":"Ich habe dir die Unterlagen per E-Mail gesendet.","exampleEn":"I sent you the documents by email.","example2":"Das Programm wird live gesendet.","example2En":"The program is broadcast live."},{"de":"die Sendung","en":"broadcast, program; shipment","pos":"noun","plural":"die Sendungen","meanings":[{"en":"TV/radio program","de":"eine Radio- oder Fernsehsendung"},{"en":"shipment, parcel","de":"ein Paket oder Brief, der verschickt wird"}],"rule":"Zwei getrennte Bedeutungen: Medien und Post/Versand.","example":"Hast du gestern die Sendung im Fernsehen gesehen?","exampleEn":"Did you see the TV program yesterday?","example2":"Die Sendung ist noch nicht angekommen.","example2En":"The shipment hasn't arrived yet."},{"de":"das Seniorenheim","en":"retirement home, nursing home","pos":"noun","plural":"die Seniorenheime","meanings":[{"en":"a home/residence for elderly people","de":"ein Heim, in dem alte Menschen wohnen und betreut werden"}],"rule":"Zusammensetzung aus 'Senioren' + 'Heim'; oft Synonym für Altersheim/Altenheim.","example":"Meine Großmutter lebt seit einem Jahr im Seniorenheim.","exampleEn":"My grandmother has lived in the retirement home for a year.","example2":"Das Seniorenheim sucht neue Pflegekräfte.","example2En":"The nursing home is looking for new caregivers."},{"de":"senken","en":"to lower, to reduce","pos":"verb","plural":"","meanings":[{"en":"to lower / reduce (prices, level)","de":"kleiner/niedriger machen"}],"rule":"Regelmäßiges Verb: senkt, senkte, hat gesenkt. Nicht verwechseln mit 'sinken' (intransitiv, selbst fallen).","example":"Die Firma will die Preise senken.","exampleEn":"The company wants to lower the prices.","example2":"Er hat seinen Blutdruck durch Sport gesenkt.","example2En":"He lowered his blood pressure through exercise."},{"de":"die Serie","en":"series","pos":"noun","plural":"die Serien","meanings":[{"en":"a series (TV show, sequence)","de":"eine Reihe von zusammengehörenden Folgen oder Dingen"}],"rule":"Plural regelmäßig: die Serien.","example":"Wir schauen jeden Abend eine Folge dieser Serie.","exampleEn":"We watch one episode of this series every evening.","example2":"In letzter Zeit gab es eine Serie von Einbrüchen.","example2En":"There has been a series of burglaries lately."},{"de":"das Shopping","en":"shopping","pos":"noun","plural":"","meanings":[{"en":"shopping (leisure activity)","de":"das Einkaufen, besonders zum Vergnügen"}],"rule":"Anglizismus, meist unzählbar, kein Plural; die Aktivität wird meist mit dem Verb 'shoppen' ausgedrückt ('shoppen gehen'), 'Shopping' selbst steht oft in Komposita wie 'Online-Shopping'.","example":"Am Samstag gehen wir in der Stadt shoppen.","exampleEn":"On Saturday we're going shopping in the city.","example2":"Online-Shopping ist für viele bequemer.","example2En":"Online shopping is more convenient for many people."},{"de":"sich etwas angewöhnen","en":"to get into the habit of","pos":"verb","plural":"","meanings":[{"en":"to adopt a habit","de":"sich eine Gewohnheit zulegen"}],"rule":"reflexiv mit Dativ (sich) + Akkusativ der Sache: sich (Dat.) etwas (Akk.) angewöhnen; trennbar: gewöhnt sich etwas an, gewöhnte sich etwas an, hat sich etwas angewöhnt","example":"Ich habe mir angewöhnt, jeden Morgen zu joggen.","exampleEn":"I've gotten into the habit of jogging every morning.","example2":"Er sollte sich das Rauchen nicht angewöhnen.","example2En":"He shouldn't get into the habit of smoking."},{"de":"siegen","en":"to win, to be victorious","pos":"verb","plural":"","meanings":[{"en":"to win, to triumph (esp. in sport/competition)","de":"gewinnen, den Sieg erringen"}],"rule":"Regelmäßig: siegt, siegte, hat gesiegt. Oft mit 'gegen' + Akkusativ (gegen jemanden siegen).","example":"Unsere Mannschaft hat gestern gesiegt.","exampleEn":"Our team won yesterday.","example2":"Er siegte im Finale gegen den Favoriten.","example2En":"He won the final against the favorite."},{"de":"der Sieger / die Siegerin","en":"winner, victor","pos":"noun","plural":"die Sieger / die Siegerinnen","meanings":[{"en":"the winner of a competition","de":"wer gewonnen hat"}],"rule":"Movierung: männlich der Sieger, weiblich die Siegerin (Plural: die Siegerinnen).","example":"Der Sieger des Wettbewerbs bekommt einen Pokal.","exampleEn":"The winner of the competition gets a trophy.","example2":"Die Siegerin wurde mit Applaus gefeiert.","example2En":"The (female) winner was celebrated with applause."},{"de":"der Sinn","en":"sense, meaning; purpose","pos":"noun","plural":"die Sinne","meanings":[{"en":"meaning, point (of something)","de":"die Bedeutung oder der Zweck von etwas"},{"en":"a (physical) sense","de":"eines der fünf Sinnesorgane, z. B. Sehen, Hören"}],"rule":"Feste Wendung: 'es hat keinen Sinn' = es bringt nichts; Plural 'die Sinne' meist für Sinnesorgane.","example":"Ich verstehe nicht, welchen Sinn diese Regel hat.","exampleEn":"I don't understand the point of this rule.","example2":"Der Geruchssinn ist einer unserer fünf Sinne.","example2En":"The sense of smell is one of our five senses."},{"de":"sinnlos","en":"pointless, senseless","pos":"adjective","plural":"","meanings":[{"en":"pointless, without purpose","de":"ohne Sinn oder Zweck"}],"rule":"Gegenteil von 'sinnvoll'; regelmäßige Steigerung (sinnlos, sinnloser, am sinnlosesten).","example":"Es ist sinnlos, jetzt noch zu diskutieren.","exampleEn":"It's pointless to discuss it any further now.","example2":"Ohne Plan zu arbeiten ist sinnlos.","example2En":"Working without a plan is pointless."},{"de":"sinnvoll","en":"sensible, meaningful, useful","pos":"adjective","plural":"","meanings":[{"en":"sensible, making sense","de":"vernünftig, logisch"},{"en":"useful, worthwhile","de":"nützlich, wertvoll"}],"rule":"Gegenteil von 'sinnlos'; regelmäßige Steigerung.","example":"Es wäre sinnvoll, früher aufzustehen.","exampleEn":"It would be sensible to get up earlier.","example2":"Diese Investition ist sehr sinnvoll.","example2En":"This investment is very worthwhile."},{"de":"der Skisport","en":"skiing (as a sport)","pos":"noun","plural":"","meanings":[{"en":"skiing as a sport/discipline","de":"der Sport, bei dem man auf Skiern fährt"}],"rule":"Meist unzählbar, kein Plural; Zusammensetzung Ski + Sport.","example":"Er interessiert sich sehr für Skisport.","exampleEn":"He is very interested in skiing (as a sport).","example2":"Im Fernsehen läuft heute eine Sendung über Skisport.","example2En":"There's a program about skiing on TV today."},{"de":"die Soap","en":"soap opera","pos":"noun","plural":"die Soaps","meanings":[{"en":"a soap opera (TV series)","de":"eine Fernsehserie mit vielen Folgen, oft über Familien/Beziehungen"}],"rule":"Anglizismus, kurz für 'soap opera'; Plural die Soaps.","example":"Meine Schwester schaut jeden Tag ihre Lieblings-Soap.","exampleEn":"My sister watches her favorite soap opera every day.","example2":"Diese Soap läuft schon seit zwanzig Jahren.","example2En":"This soap opera has been running for twenty years."},{"de":"die Solarenergie","en":"solar energy","pos":"noun","plural":"","meanings":[{"en":"energy from the sun","de":"Energie, die aus Sonnenlicht gewonnen wird"}],"rule":"Unzählbar, kein Plural; Zusammensetzung Solar + Energie.","example":"Unser Haus wird mit Solarenergie beheizt.","exampleEn":"Our house is heated with solar energy.","example2":"Die Nutzung von Solarenergie wächst weltweit.","example2En":"The use of solar energy is growing worldwide."},{"de":"der Sondermüll","en":"hazardous waste, special waste","pos":"noun","plural":"","meanings":[{"en":"hazardous/special waste requiring special disposal","de":"gefährlicher Müll, der besonders entsorgt werden muss"}],"rule":"Unzählbar, kein Plural; Zusammensetzung Sonder + Müll.","example":"Batterien gehören nicht in den Hausmüll, sondern in den Sondermüll.","exampleEn":"Batteries don't belong in household waste, but in hazardous waste.","example2":"Die Firma muss ihren Sondermüll fachgerecht entsorgen.","example2En":"The company must dispose of its hazardous waste properly."},{"de":"der Sonnenschein","en":"sunshine","pos":"noun","plural":"","meanings":[{"en":"sunshine","de":"das Licht der Sonne"}],"rule":"Uncountable, no plural. Compound: die Sonne + der Schein.","example":"Bei Sonnenschein frühstücken wir gern auf dem Balkon.","exampleEn":"When it's sunny, we like to have breakfast on the balcony.","example2":"Nach dem Regen kam wieder Sonnenschein.","example2En":"After the rain, the sunshine came back."},{"de":"der Sonnenschirm","en":"parasol, sun umbrella","pos":"noun","plural":"die Sonnenschirme","meanings":[{"en":"parasol / sun umbrella","de":"ein Schirm, der vor der Sonne schützt"}],"rule":"Compound noun: die Sonne + der Schirm, takes der.","example":"Kannst du bitte den Sonnenschirm aufspannen?","exampleEn":"Can you open the parasol, please?","example2":"Am Strand hatten wir keinen Sonnenschirm dabei.","example2En":"We didn't have a parasol with us at the beach."},{"de":"die Sonnenterrasse","en":"sun terrace","pos":"noun","plural":"die Sonnenterrassen","meanings":[{"en":"sun terrace","de":"eine Terrasse mit viel Sonne"}],"rule":"Compound: die Sonne + die Terrasse, takes die.","example":"Das Café hat eine schöne Sonnenterrasse.","exampleEn":"The café has a nice sun terrace.","example2":"Wir sitzen am liebsten auf der Sonnenterrasse.","example2En":"We prefer to sit on the sun terrace."},{"de":"der Sonnenuntergang","en":"sunset","pos":"noun","plural":"die Sonnenuntergänge","meanings":[{"en":"sunset","de":"wenn die Sonne untergeht"}],"rule":"Compound: die Sonne + der Untergang.","example":"Wir haben den Sonnenuntergang am Meer beobachtet.","exampleEn":"We watched the sunset by the sea.","example2":"Der Sonnenuntergang war heute besonders schön.","example2En":"The sunset was especially beautiful today."},{"de":"die Sorge","en":"worry, concern","pos":"noun","plural":"die Sorgen","meanings":[{"en":"worry, concern","de":"ein Gefühl der Angst oder Unruhe"},{"en":"care (for someone's well-being)","de":"die Fürsorge für jemanden"}],"rule":"Common phrase: sich Sorgen machen (um + Akk.) = to worry about. Fixed idiom 'Sorge tragen für' (to take care of / be responsible for) is used without an article before Sorge.","example":"Mach dir keine Sorgen, alles wird gut.","exampleEn":"Don't worry, everything will be fine.","example2":"Die Eltern tragen Sorge für ihre Kinder.","example2En":"Parents take care of their children."},{"de":"sortieren","en":"to sort","pos":"verb","plural":"","meanings":[{"en":"to sort, arrange","de":"nach einem System ordnen"}],"rule":"Regular weak verb; sortiert, sortierte, hat sortiert. Often + nach (sortieren nach Größe).","example":"Sie sortiert die Wäsche nach Farben.","exampleEn":"She sorts the laundry by colour.","example2":"Bitte sortiere die Dokumente alphabetisch.","example2En":"Please sort the documents alphabetically."},{"de":"soweit","en":"as far as, so far","pos":"conjunction","plural":"","meanings":[{"en":"as far as (I know/concerned), insofar as","de":"in dem Maße, wie; insofern"},{"en":"ready, that far along","de":"bereit, fertig"}],"rule":"As a subordinating conjunction meaning 'insofar as', it is written as one word: 'soweit ich weiß' (verb goes to the end of the clause). For the colloquial sense 'to be ready', it is correctly spelled as two words: 'so weit sein' (e.g. 'Bist du so weit?').","example":"Soweit ich weiß, kommt sie morgen.","exampleEn":"As far as I know, she's coming tomorrow.","example2":"Bist du so weit? Wir können los.","example2En":"Are you ready? We can go."},{"de":"spannend","en":"exciting, thrilling","pos":"adjective","plural":"","meanings":[{"en":"exciting, suspenseful","de":"interessant und aufregend"}],"rule":"Regular comparison: spannend, spannender, am spannendsten.","example":"Der Film war wirklich spannend.","exampleEn":"The movie was really exciting.","example2":"Sie liest gerade ein spannendes Buch.","example2En":"She's currently reading an exciting book."},{"de":"sparsam","en":"thrifty, economical","pos":"adjective","plural":"","meanings":[{"en":"thrifty, frugal (of a person)","de":"gibt wenig Geld aus"},{"en":"economical, efficient (of a device)","de":"verbraucht wenig Energie"}],"rule":"Regular comparison: sparsam, sparsamer, am sparsamsten.","example":"Meine Oma ist sehr sparsam und spart viel Geld.","exampleEn":"My grandma is very thrifty and saves a lot of money.","example2":"Das neue Auto ist sehr sparsam im Verbrauch.","example2En":"The new car is very fuel-efficient."},{"de":"die Speise","en":"dish, food","pos":"noun","plural":"die Speisen","meanings":[{"en":"dish, food, meal","de":"etwas, das man isst"}],"rule":"Somewhat formal/written word; often seen in 'Speisekarte' (menu).","example":"Auf der Karte stehen viele leckere Speisen.","exampleEn":"There are many tasty dishes on the menu.","example2":"Diese Speise schmeckt sehr würzig.","example2En":"This dish tastes very flavorful."},{"de":"der Sperrmüll","en":"bulky waste","pos":"noun","plural":"","meanings":[{"en":"bulky waste (large household items for disposal)","de":"große Gegenstände, die man wegwirft, z. B. Möbel"}],"rule":"Uncountable, no plural. Compound: sperrig (bulky, unwieldy) + der Müll — not from 'sperren'.","example":"Der alte Schrank kommt zum Sperrmüll.","exampleEn":"The old wardrobe is going to bulky waste collection.","example2":"Wann wird hier der Sperrmüll abgeholt?","example2En":"When is the bulky waste collected here?"},{"de":"spezialisieren (sich)","en":"to specialize","pos":"verb","plural":"","meanings":[{"en":"to specialize (in something)","de":"sich auf ein bestimmtes Gebiet konzentrieren"}],"rule":"Reflexive verb: sich spezialisieren auf + Akk. Regular: spezialisiert, spezialisierte, hat sich spezialisiert.","example":"Der Arzt hat sich auf Kinderkrankheiten spezialisiert.","exampleEn":"The doctor specialized in children's illnesses.","example2":"Unsere Firma spezialisiert sich auf Software.","example2En":"Our company specializes in software."},{"de":"der Spieler / die Spielerin","en":"player","pos":"noun","plural":"die Spieler / die Spielerinnen","meanings":[{"en":"player (sports, games)","de":"jemand, der ein Spiel spielt"}],"rule":"Feminine form adds -in; plural die Spielerinnen.","example":"Der Spieler schoss ein tolles Tor.","exampleEn":"The player scored a great goal.","example2":"Sie ist eine sehr gute Spielerin.","example2En":"She is a very good player."},{"de":"der Spielfilm","en":"feature film","pos":"noun","plural":"die Spielfilme","meanings":[{"en":"feature film (fictional, as opposed to documentary)","de":"ein Film mit einer erfundenen Geschichte"}],"rule":"Compound: spielen + der Film.","example":"Heute Abend läuft ein spannender Spielfilm im Fernsehen.","exampleEn":"An exciting feature film is on TV tonight.","example2":"Der Spielfilm dauert etwa zwei Stunden.","example2En":"The feature film lasts about two hours."},{"de":"der Sportwagen","en":"sports car","pos":"noun","plural":"die Sportwagen","meanings":[{"en":"sports car","de":"ein schnelles, sportliches Auto"}],"rule":"Compound: der Sport + der Wagen; plural unchanged.","example":"Er träumt von einem roten Sportwagen.","exampleEn":"He dreams of a red sports car.","example2":"Sportwagen verbrauchen meistens viel Benzin.","example2En":"Sports cars usually use a lot of petrol."},{"de":"der Sprachnachweis","en":"language certificate","pos":"noun","plural":"die Sprachnachweise","meanings":[{"en":"proof/certificate of language proficiency","de":"ein Dokument, das Sprachkenntnisse bestätigt"}],"rule":"Compound: die Sprache + der Nachweis.","example":"Für das Studium brauche ich einen Sprachnachweis in Deutsch.","exampleEn":"I need a German language certificate for my studies.","example2":"Ohne Sprachnachweis konnte er sich nicht bewerben.","example2En":"Without a language certificate he couldn't apply."},{"de":"der Staat","en":"state, country","pos":"noun","plural":"die Staaten","meanings":[{"en":"state, country, nation","de":"ein Land mit eigener Regierung"}],"rule":"No special irregularities; genitive: des Staates.","example":"Deutschland ist ein demokratischer Staat.","exampleEn":"Germany is a democratic state.","example2":"Der Staat unterstützt Familien mit Kindergeld.","example2En":"The state supports families with child benefit."}]},{"id":"b1-16","title":"B1 · S–Ü (16)","level":"B1","words":[{"de":"die Staatsgründung","en":"founding of a state","pos":"noun","plural":"die Staatsgründungen","meanings":[{"en":"founding/establishment of a state","de":"die Entstehung eines neuen Staates"}],"rule":"Compound: der Staat + die Gründung.","example":"Die Staatsgründung fand vor über 70 Jahren statt.","exampleEn":"The founding of the state took place more than 70 years ago.","example2":"Historiker diskutieren über die Umstände der Staatsgründung.","example2En":"Historians discuss the circumstances of the state's founding."},{"de":"das Stadion","en":"stadium","pos":"noun","plural":"die Stadien","meanings":[{"en":"stadium (sports venue)","de":"große Sportanlage mit Rängen für Zuschauer"}],"rule":"Plural unregelmäßig: die Stadien (nicht 'Stadions').","example":"Am Samstag gehen wir ins Stadion, um das Fußballspiel zu sehen.","exampleEn":"On Saturday we're going to the stadium to watch the football match.","example2":"Das neue Stadion bietet Platz für 50.000 Zuschauer.","example2En":"The new stadium has room for 50,000 spectators."},{"de":"die Statistik","en":"statistics","pos":"noun","plural":"die Statistiken","meanings":[{"en":"statistics (data/figures)","de":"Zusammenstellung von Zahlen und Daten"},{"en":"statistics (the science)","de":"wissenschaftliche Methode zur Auswertung von Daten"}],"rule":"Im Singular oft für 'eine Statistik' (eine Datentabelle), im Uni-Kontext auch das Fach 'Statistik' ohne Plural.","example":"Laut einer Statistik fahren immer mehr Menschen mit dem Fahrrad.","exampleEn":"According to a statistic, more and more people are cycling.","example2":"Im Studium musste sie einen Kurs in Statistik belegen.","example2En":"During her studies she had to take a course in statistics."},{"de":"stattfinden","en":"to take place","pos":"verb","plural":"","meanings":[{"en":"to take place / happen (event)","de":"(Veranstaltung) durchgeführt werden"}],"rule":"Trennbar: findet ... statt, fand statt, hat stattgefunden. Nur mit Sachen/Ereignissen als Subjekt, nicht mit Personen.","example":"Die Konferenz findet nächste Woche in Berlin statt.","exampleEn":"The conference takes place next week in Berlin.","example2":"Wegen des Regens fand das Konzert nicht im Freien statt.","example2En":"Because of the rain, the concert did not take place outdoors."},{"de":"die Stellenanzeige","en":"job advertisement","pos":"noun","plural":"die Stellenanzeigen","meanings":[{"en":"job advertisement / job posting","de":"Anzeige, mit der eine freie Arbeitsstelle gesucht wird"}],"rule":"Zusammensetzung aus 'Stelle' (Job/Position) + 'Anzeige' (Werbung); steht meist in Zeitungen oder online.","example":"Ich habe in der Zeitung eine interessante Stellenanzeige gefunden.","exampleEn":"I found an interesting job ad in the newspaper.","example2":"Auf die Stellenanzeige haben sich über 50 Personen beworben.","example2En":"More than 50 people applied for the job posting."},{"de":"der Stern","en":"star","pos":"noun","plural":"die Sterne","meanings":[{"en":"star (in the sky)","de":"leuchtender Himmelskörper"},{"en":"star (symbol, e.g. in ratings)","de":"Symbol in Sternform, z. B. bei Bewertungen (fünf Sterne)"}],"rule":"Maskulin, regelmäßiger Plural: die Sterne. Achtung: 'Star' (Berühmtheit) ist ein anderes Wort - der Star, die Stars.","example":"Nachts kann man am Himmel viele Sterne sehen.","exampleEn":"At night you can see many stars in the sky.","example2":"Das Hotel hat fünf Sterne.","example2En":"The hotel has five stars."},{"de":"der Steuerberater / die Steuerberaterin","en":"tax advisor","pos":"noun","plural":"die Steuerberater / die Steuerberaterinnen","meanings":[{"en":"tax advisor / accountant","de":"Fachperson, die bei Steuerfragen berät"}],"rule":"Zusammensetzung aus 'Steuer' (tax) + 'Berater' (advisor); weibliche Form mit -in.","example":"Mein Steuerberater hilft mir bei der Steuererklärung.","exampleEn":"My tax advisor helps me with my tax return.","example2":"Für die Firma ist eine gute Steuerberaterin sehr wichtig.","example2En":"A good tax advisor is very important for the company."},{"de":"das Steuerberatungsbüro","en":"tax consultancy office","pos":"noun","plural":"die Steuerberatungsbüros","meanings":[{"en":"tax consultancy office / accounting firm","de":"Büro, in dem Steuerberater arbeiten"}],"rule":"Zusammensetzung aus 'Steuerberatung' + 'Büro'; Plural auf -s wie bei vielen Wörtern auf -o.","example":"Das Steuerberatungsbüro liegt direkt neben der Bank.","exampleEn":"The tax consultancy office is right next to the bank.","example2":"Sie arbeitet seit fünf Jahren in einem Steuerberatungsbüro.","example2En":"She has worked at a tax consultancy office for five years."},{"de":"stinken","en":"to stink","pos":"verb","plural":"","meanings":[{"en":"to stink / smell bad","de":"schlecht riechen"}],"rule":"Unregelmäßig: stinkt, stank, hat gestunken.","example":"Der Müll im Hof stinkt schon seit Tagen.","exampleEn":"The garbage in the yard has been stinking for days.","example2":"Nach dem Sport stinken seine Schuhe fürchterlich.","example2En":"After sports, his shoes smell terrible."},{"de":"stinksauer","en":"furious (coll.)","pos":"adjective","plural":"","meanings":[{"en":"furious / really angry (colloquial)","de":"(umgangssprachlich) sehr wütend"}],"rule":"Umgangssprachliche Verstärkung von 'sauer' (wütend); keine unregelmäßige Steigerung, wird meist prädikativ benutzt.","example":"Er war stinksauer, weil der Bus schon wieder zu spät kam.","exampleEn":"He was furious because the bus was late again.","example2":"Meine Chefin ist stinksauer auf mich, weil ich den Termin vergessen habe.","example2En":"My boss is really angry at me because I forgot the appointment."},{"de":"das Stipendium","en":"scholarship","pos":"noun","plural":"die Stipendien","meanings":[{"en":"scholarship / grant","de":"finanzielle Unterstützung für Studium oder Ausbildung"}],"rule":"Plural unregelmäßig: die Stipendien (wie bei vielen Wörtern auf -ium).","example":"Sie hat ein Stipendium für ihr Studium in Deutschland bekommen.","exampleEn":"She got a scholarship for her studies in Germany.","example2":"Ohne das Stipendium könnte er sich die Uni nicht leisten.","example2En":"Without the scholarship, he couldn't afford university."},{"de":"stören","en":"to disturb","pos":"verb","plural":"","meanings":[{"en":"to disturb / bother","de":"jemanden bei etwas unterbrechen oder belästigen"},{"en":"to bother / annoy (impersonal, etwas stört jmdn.)","de":"jemandem unangenehm auffallen"}],"rule":"Regelmäßig: stört, störte, hat gestört. Oft mit Akkusativobjekt der Person: 'jemanden stören'.","example":"Entschuldigung, störe ich Sie gerade?","exampleEn":"Excuse me, am I disturbing you right now?","example2":"Der Lärm von der Baustelle stört mich beim Arbeiten.","example2En":"The noise from the construction site bothers me while I work."},{"de":"die Stoßstange","en":"bumper","pos":"noun","plural":"die Stoßstangen","meanings":[{"en":"bumper (of a car)","de":"vorderer oder hinterer Teil des Autos zum Schutz bei Stößen"}],"rule":"Zusammensetzung aus 'stoßen' (to push/bump) + 'Stange' (bar).","example":"Bei dem Unfall wurde nur die Stoßstange beschädigt.","exampleEn":"In the accident, only the bumper was damaged.","example2":"Die vordere Stoßstange hat einen tiefen Kratzer.","example2En":"The front bumper has a deep scratch."},{"de":"der Straßenrand","en":"roadside / curb","pos":"noun","plural":"die Straßenränder","meanings":[{"en":"roadside / edge of the street","de":"der äußere Rand einer Straße"}],"rule":"Zusammensetzung aus 'Straße' + 'Rand'; oft in 'am Straßenrand' (Präposition 'an' + Dativ).","example":"Das Auto war am Straßenrand geparkt.","exampleEn":"The car was parked at the roadside.","example2":"Am Straßenrand wachsen viele Blumen.","example2En":"Many flowers grow along the roadside."},{"de":"der Straßenverkehr","en":"road traffic","pos":"noun","plural":"","meanings":[{"en":"road traffic","de":"Verkehr von Autos, Fahrrädern usw. auf der Straße"}],"rule":"Unzählbar, kein Plural. Zusammensetzung aus 'Straße' + 'Verkehr'.","example":"Der Straßenverkehr ist in der Stadt oft sehr stressig.","exampleEn":"Road traffic in the city is often very stressful.","example2":"Kinder lernen in der Schule, sich sicher im Straßenverkehr zu bewegen.","example2En":"Children learn at school how to move safely in road traffic."},{"de":"das Streichholz","en":"match (for lighting)","pos":"noun","plural":"die Streichhölzer","meanings":[{"en":"match (used to light fire)","de":"kleines Holzstück zum Anzünden von Feuer"}],"rule":"Zusammensetzung aus 'streichen' (to strike) + 'Holz' (wood); Plural mit Umlaut: die Streichhölzer.","example":"Kannst du mir bitte ein Streichholz geben, um die Kerze anzuzünden?","exampleEn":"Can you give me a match to light the candle, please?","example2":"Die Streichhölzer liegen in der Küchenschublade.","example2En":"The matches are in the kitchen drawer."},{"de":"streiken","en":"to strike","pos":"verb","plural":"","meanings":[{"en":"to strike (workers/labor action)","de":"aus Protest gemeinsam die Arbeit niederlegen"}],"rule":"Regelmäßig: streikt, streikte, hat gestreikt.","example":"Die Lokführer streiken diese Woche für höhere Löhne.","exampleEn":"The train drivers are striking this week for higher wages.","example2":"Die Fluglotsen streiken heute, deshalb fallen viele Flüge aus.","example2En":"The air traffic controllers are striking today, so many flights are cancelled."},{"de":"streiten","en":"to argue","pos":"verb","plural":"","meanings":[{"en":"to argue / quarrel","de":"einen Streit mit jemandem haben"},{"en":"to argue (sich streiten, reflexive, mutual dispute)","de":"sich gegenseitig streiten"}],"rule":"Unregelmäßig: streitet, stritt, hat gestritten. Oft reflexiv: 'sich streiten mit + Dativ' oder 'sich streiten über + Akkusativ'.","example":"Die Geschwister streiten sich ständig um das Spielzeug.","exampleEn":"The siblings constantly argue about the toy.","example2":"Wir haben lange über den richtigen Weg gestritten.","example2En":"We argued for a long time about the right way."},{"de":"der Strom","en":"electricity","pos":"noun","plural":"die Ströme","meanings":[{"en":"electricity / power","de":"elektrische Energie"},{"en":"stream / large river","de":"großer, breiter Fluss"},{"en":"stream / flow (of people, traffic, etc.)","de":"große, gleichmäßige Bewegung von Menschen oder Dingen"}],"rule":"Für 'Elektrizität' meist Singular ohne Plural verwendet; als 'großer Fluss' regelmäßiger Plural: die Ströme.","example":"Der Strom ist heute Morgen für zwei Stunden ausgefallen.","exampleEn":"The power was out for two hours this morning.","example2":"Ein Strom von Touristen fließt jeden Tag durch die Altstadt.","example2En":"A stream of tourists flows through the old town every day."},{"de":"der Stromanbieter","en":"electricity provider","pos":"noun","plural":"die Stromanbieter","meanings":[{"en":"company that supplies electricity","de":"Firma, die Strom liefert"}],"rule":"Compound: der Strom + der Anbieter; masculine like Anbieter; often used with 'wechseln' (den Stromanbieter wechseln).","example":"Wir haben den Stromanbieter gewechselt, weil er billiger ist.","exampleEn":"We switched electricity providers because it's cheaper.","example2":"Mein Stromanbieter hat die Preise erhöht.","example2En":"My electricity provider has raised the prices."},{"de":"die Stromkosten","en":"electricity costs","pos":"noun","plural":"die Stromkosten","meanings":[{"en":"money paid for electricity","de":"Kosten für den Stromverbrauch"}],"rule":"Plural-only noun (Pluraletantum); no singular form in everyday use.","example":"Die Stromkosten steigen jedes Jahr.","exampleEn":"Electricity costs rise every year.","example2":"Wir wollen unsere Stromkosten senken.","example2En":"We want to reduce our electricity costs."},{"de":"die Studie","en":"study; survey","pos":"noun","plural":"die Studien","meanings":[{"en":"a scientific or research study","de":"wissenschaftliche Untersuchung"}],"rule":"Feminine noun; do not confuse with 'das Studium' (course of study at university).","example":"Eine neue Studie zeigt die Wirkung des Medikaments.","exampleEn":"A new study shows the effect of the medication.","example2":"Laut einer Studie schlafen viele Deutsche zu wenig.","example2En":"According to a study, many Germans sleep too little."},{"de":"der Sturm","en":"storm","pos":"noun","plural":"die Stürme","meanings":[{"en":"a violent windstorm","de":"sehr starker Wind"}],"rule":"Masculine noun; umlaut in plural (Sturm → Stürme).","example":"Der Sturm hat viele Bäume umgeworfen.","exampleEn":"The storm knocked down many trees.","example2":"Heute Abend soll ein starker Sturm kommen.","example2En":"A strong storm is expected tonight."},{"de":"der SUV","en":"SUV (sport utility vehicle)","pos":"noun","plural":"die SUVs","meanings":[{"en":"a large, high-riding car","de":"großes, hoch gebautes Auto"}],"rule":"Loanword/abbreviation from English; masculine article der SUV; plural adds -s.","example":"Sie fährt einen großen SUV.","exampleEn":"She drives a big SUV.","example2":"SUVs verbrauchen oft mehr Benzin als kleine Autos.","example2En":"SUVs often use more fuel than small cars."},{"de":"der Tagesablauf","en":"daily routine","pos":"noun","plural":"die Tagesabläufe","meanings":[{"en":"the sequence of events in a typical day","de":"der übliche Ablauf eines Tages"}],"rule":"Compound: der Tag(es) + der Ablauf; masculine.","example":"Mein Tagesablauf beginnt mit einer Tasse Kaffee.","exampleEn":"My daily routine starts with a cup of coffee.","example2":"Der Tagesablauf im Kindergarten ist gut strukturiert.","example2En":"The daily routine at the kindergarten is well structured."},{"de":"die Talkshow","en":"talk show","pos":"noun","plural":"die Talkshows","meanings":[{"en":"a TV program where guests are interviewed or discuss topics","de":"Fernsehsendung mit Gästen und Diskussion"}],"rule":"Loanword from English; feminine article (die Show); plural adds -s.","example":"Er war gestern Gast in einer Talkshow.","exampleEn":"He was a guest on a talk show yesterday.","example2":"In der Talkshow diskutieren Politiker über die Wahl.","example2En":"In the talk show, politicians discuss the election."},{"de":"die Taschenlampe","en":"flashlight","pos":"noun","plural":"die Taschenlampen","meanings":[{"en":"a small portable electric light","de":"kleines tragbares Licht mit Batterie"}],"rule":"Compound: die Tasche + die Lampe; feminine.","example":"Ich brauche eine Taschenlampe, weil es dunkel ist.","exampleEn":"I need a flashlight because it's dark.","example2":"Die Taschenlampe funktioniert nicht mehr, die Batterie ist leer.","example2En":"The flashlight doesn't work anymore, the battery is dead."},{"de":"das Taschenmesser","en":"pocketknife","pos":"noun","plural":"die Taschenmesser","meanings":[{"en":"a small folding knife","de":"kleines Klappmesser zum Mitnehmen"}],"rule":"Compound: die Tasche + das Messer; neuter (takes gender of Messer).","example":"Er hat immer ein Taschenmesser dabei.","exampleEn":"He always carries a pocketknife with him.","example2":"Mit dem Taschenmesser kann man Brot schneiden.","example2En":"You can cut bread with the pocketknife."},{"de":"tatsächlich","en":"actual, actually; indeed","pos":"adjective","plural":"","meanings":[{"en":"real, actual (adjective)","de":"wirklich, real"},{"en":"really, in fact (adverb/discourse particle)","de":"wirklich, tatsächlich so"}],"rule":"Can be used both as adjective (die tatsächlichen Kosten) and as adverb/modal particle expressing surprise or confirmation.","example":"Die tatsächlichen Kosten waren höher als geplant.","exampleEn":"The actual costs were higher than planned.","example2":"Er hat tatsächlich die Prüfung bestanden!","example2En":"He actually passed the exam!"},{"de":"die Teamfähigkeit","en":"teamwork skills, ability to work in a team","pos":"noun","plural":"","meanings":[{"en":"the ability to work well with others in a team","de":"Fähigkeit, gut mit anderen zusammenzuarbeiten"}],"rule":"Feminine, uncountable noun; common in job ads (Wir erwarten Teamfähigkeit).","example":"Teamfähigkeit ist in diesem Beruf sehr wichtig.","exampleEn":"Teamwork skills are very important in this job.","example2":"Im Bewerbungsgespräch wurde nach meiner Teamfähigkeit gefragt.","example2En":"In the job interview, I was asked about my ability to work in a team."},{"de":"die Teilkaskoversicherung","en":"partial comprehensive insurance (for cars)","pos":"noun","plural":"die Teilkaskoversicherungen","meanings":[{"en":"limited car insurance covering theft, fire, glass, etc. but not own-fault collision damage","de":"Autoversicherung, die z. B. Diebstahl und Glasschäden, aber keine selbst verursachten Unfallschäden deckt"}],"rule":"Compound: Teil + Kasko + Versicherung; feminine; short form 'die Teilkasko' is common.","example":"Für das alte Auto reicht eine Teilkaskoversicherung.","exampleEn":"For the old car, partial comprehensive insurance is enough.","example2":"Die Teilkasko zahlt, wenn das Auto gestohlen wird.","example2En":"The partial comprehensive insurance pays if the car is stolen."},{"de":"die Teilung","en":"division; split","pos":"noun","plural":"die Teilungen","meanings":[{"en":"the act of dividing something into parts","de":"das Aufteilen in mehrere Teile"}],"rule":"Feminine noun from the verb 'teilen'.","example":"Die Teilung des Kuchens war nicht gerecht.","exampleEn":"The division of the cake wasn't fair.","example2":"Nach der Teilung Deutschlands gab es zwei Staaten.","example2En":"After the division of Germany, there were two states."},{"de":"die Telekommunikation","en":"telecommunications","pos":"noun","plural":"","meanings":[{"en":"technology and services for transmitting information over distance (phone, internet, etc.)","de":"Übertragung von Informationen über Entfernungen, z. B. Telefon, Internet"}],"rule":"Feminine, uncountable noun; often used in compounds like Telekommunikationsunternehmen.","example":"Er arbeitet in der Telekommunikation.","exampleEn":"He works in telecommunications.","example2":"Die Telekommunikation hat sich in den letzten Jahren stark verändert.","example2En":"Telecommunications has changed a lot in recent years."},{"de":"der Terminkalender","en":"appointment calendar, diary","pos":"noun","plural":"die Terminkalender","meanings":[{"en":"a calendar for keeping track of appointments","de":"Kalender, in dem man Termine einträgt"}],"rule":"Compound: der Termin + der Kalender; masculine.","example":"Mein Terminkalender ist diese Woche voll.","exampleEn":"My appointment calendar is full this week.","example2":"Sie trägt jeden Termin sofort in den Terminkalender ein.","example2En":"She immediately writes every appointment into her calendar."},{"de":"die Tiefkühlpizza","en":"frozen pizza","pos":"noun","plural":"die Tiefkühlpizzen","meanings":[{"en":"pizza sold frozen for home baking","de":"Pizza, die tiefgefroren verkauft wird"}],"rule":"Compound: tiefkühlen/tiefgekühlt + die Pizza; feminine.","example":"Wir haben abends nur eine Tiefkühlpizza gegessen.","exampleEn":"We just ate a frozen pizza in the evening.","example2":"Tiefkühlpizza ist schnell und einfach zuzubereiten.","example2En":"Frozen pizza is quick and easy to prepare."},{"de":"tierisch","en":"animal (adj.); (colloquial) extremely","pos":"adjective","plural":"","meanings":[{"en":"relating to animals","de":"das Tier betreffend"},{"en":"(informal) very, extremely","de":"(umgangssprachlich) sehr, stark"}],"rule":"As adjective means 'animal-related' (tierisches Fett = animal fat); colloquially used as intensifier (tierisch müde = extremely tired).","example":"Tierisches Fett steckt in vielen Fertiggerichten.","exampleEn":"Animal fat is found in many ready meals.","example2":"Ich bin heute tierisch müde.","example2En":"I'm extremely tired today."},{"de":"der Tierschutz","en":"animal welfare, animal protection","pos":"noun","plural":"","meanings":[{"en":"protection of animals from cruelty and suffering","de":"Schutz der Tiere vor Leid und Missbrauch"}],"rule":"Compound: das Tier + der Schutz; masculine, uncountable.","example":"Sie engagiert sich für den Tierschutz.","exampleEn":"She is committed to animal welfare.","example2":"Der Tierschutzverein sucht neue Mitglieder.","example2En":"The animal welfare association is looking for new members."},{"de":"das Tor","en":"goal; gate","pos":"noun","plural":"die Tore","meanings":[{"en":"gate/large door","de":"großer Eingang, z. B. bei einem Haus oder einer Stadt"},{"en":"goal (sports)","de":"Punkt im Fußball, wenn der Ball ins Netz geht"}],"rule":"Neutrum, endet auf -e im Plural: das Tor, die Tore. Nicht verwechseln mit 'der Tor' (Narr, veraltet).","example":"Die Fans haben das geschossene Tor bejubelt.","exampleEn":"The fans cheered the goal that was scored.","example2":"Bitte mach das Tor zum Garten zu.","example2En":"Please close the gate to the garden."},{"de":"der Torwart / die Torwartin","en":"goalkeeper","pos":"noun","plural":"die Torwarte / die Torwartinnen","meanings":[{"en":"goalkeeper in football/handball","de":"Spieler, der das Tor verteidigt"}],"rule":"Movierte Form: -in im Femininum. Synonym: der Torhüter / die Torhüterin.","example":"Der Torwart hat den Elfmeter gehalten.","exampleEn":"The goalkeeper saved the penalty.","example2":"Sie spielt als Torwartin in der Jugendmannschaft.","example2En":"She plays as goalkeeper on the youth team."},{"de":"total","en":"totally; completely","pos":"adjective","plural":"","meanings":[{"en":"total/entire (extent)","de":"ganz, vollständig"},{"en":"completely, very (intensifier, colloquial)","de":"sehr, völlig (umgangssprachlich)"}],"rule":"Wird oft als Adverb/Verstärker im Alltag benutzt, z. B. 'total müde'.","example":"Das Haus wurde total renoviert.","exampleEn":"The house was totally renovated.","example2":"Ich bin heute total müde.","example2En":"I'm totally tired today."},{"de":"traditionsreich","en":"rich in tradition, steeped in tradition","pos":"adjective","plural":"","meanings":[{"en":"having a long, rich tradition","de":"mit einer langen, bedeutenden Tradition"}],"rule":"Zusammengesetztes Adjektiv (Tradition + reich), regelmäßig steigerbar, meist ohne Steigerung verwendet.","example":"Das ist ein traditionsreiches Restaurant in der Altstadt.","exampleEn":"That is a restaurant with a rich tradition in the old town.","example2":"Die traditionsreiche Firma feiert in diesem Jahr ihr 100-jähriges Jubiläum.","example2En":"The company, which has a long tradition, is celebrating its 100th anniversary this year."},{"de":"traumhaft","en":"dreamlike, fantastic","pos":"adjective","plural":"","meanings":[{"en":"wonderful, like a dream","de":"wunderschön, wie im Traum"}],"rule":"Regelmäßig: traumhaft, traumhafter, am traumhaftesten. Oft für Landschaften, Urlaub, Wetter.","example":"Wir hatten traumhaftes Wetter im Urlaub.","exampleEn":"We had fantastic weather on vacation.","example2":"Der Ausblick von hier ist einfach traumhaft.","example2En":"The view from here is simply dreamlike."},{"de":"der Trend","en":"trend","pos":"noun","plural":"die Trends","meanings":[{"en":"a general tendency or direction of development","de":"allgemeine Entwicklung oder Richtung"}],"rule":"Maskulin, Plural mit -s (Fremdwort aus dem Englischen).","example":"Fahrräder liegen voll im Trend.","exampleEn":"Bicycles are very much in trend right now.","example2":"Der Trend geht zu kleineren Wohnungen.","example2En":"The trend is moving toward smaller apartments."},{"de":"treu","en":"loyal, faithful","pos":"adjective","plural":"","meanings":[{"en":"loyal, faithful (to a person, principle)","de":"loyal, verlässlich, ohne jemanden zu verraten"}],"rule":"Regelmäßig gesteigert: treu, treuer, am treuesten. Achtung: 'treu' verlangt den Dativ (jemandem treu sein/bleiben).","example":"Er ist seiner Frau immer treu geblieben.","exampleEn":"He has always stayed faithful to his wife.","example2":"Unser Hund ist sehr treu.","example2En":"Our dog is very loyal."},{"de":"das Trinkwasser","en":"drinking water","pos":"noun","plural":"","meanings":[{"en":"water safe for drinking","de":"Wasser, das man trinken kann"}],"rule":"Neutrum, unzählbar, kein Plural. Zusammensetzung: trinken + Wasser.","example":"In Deutschland kann man das Leitungswasser als Trinkwasser nutzen.","exampleEn":"In Germany you can use tap water as drinking water.","example2":"Sauberes Trinkwasser ist nicht überall selbstverständlich.","example2En":"Clean drinking water is not a given everywhere."},{"de":"tropfen","en":"to drip","pos":"verb","plural":"","meanings":[{"en":"to drip, fall in drops","de":"in Tropfen herabfallen"}],"rule":"Regelmäßig: tropft, tropfte, hat/ist getropft (mit 'ist' bei Ortsveränderung). Nicht verwechseln mit 'der Tropfen' (Nomen).","example":"Der Wasserhahn tropft schon seit Tagen.","exampleEn":"The faucet has been dripping for days.","example2":"Regen tropfte vom Dach.","example2En":"Rain dripped from the roof."},{"de":"trüb","en":"cloudy, dull, murky","pos":"adjective","plural":"","meanings":[{"en":"cloudy, hazy (liquid or weather)","de":"nicht klar, bewölkt"},{"en":"gloomy, dreary (mood)","de":"traurig, bedrückend (Stimmung)"}],"rule":"Regelmäßig: trüb, trüber, am trübsten.","example":"Das Wasser im Fluss ist heute ganz trüb.","exampleEn":"The water in the river is quite murky today.","example2":"Der Himmel war den ganzen Tag trüb.","example2En":"The sky was dull all day long."},{"de":"der Tsunami","en":"tsunami","pos":"noun","plural":"die Tsunamis","meanings":[{"en":"a huge destructive sea wave, usually caused by an earthquake","de":"riesige, zerstörerische Meereswelle, meist durch ein Erdbeben ausgelöst"}],"rule":"Maskulin, Fremdwort aus dem Japanischen, Plural mit -s.","example":"Der Tsunami hat die Küste komplett zerstört.","exampleEn":"The tsunami completely destroyed the coast.","example2":"Nach dem Erdbeben warnten die Behörden vor einem Tsunami.","example2En":"After the earthquake, the authorities warned of a tsunami."},{"de":"der Turm","en":"tower","pos":"noun","plural":"die Türme","meanings":[{"en":"a tall building or structure","de":"hohes, schmales Bauwerk"}],"rule":"Maskulin, Plural mit Umlaut: der Turm, die Türme.","example":"Man kann auf den Turm der Kirche steigen.","exampleEn":"You can climb up the church tower.","example2":"Der Eiffelturm ist ein berühmter Turm in Paris.","example2En":"The Eiffel Tower is a famous tower in Paris."},{"de":"übereinstimmen","en":"to agree, correspond","pos":"verb","plural":"","meanings":[{"en":"to agree, be in accordance (opinions)","de":"die gleiche Meinung haben"},{"en":"to match, correspond (facts/data)","de":"gleich sein, zusammenpassen"}],"rule":"Trennbar: stimmt überein, stimmte überein, hat übereingestimmt. Oft mit 'mit + Dativ'.","example":"Die beiden Zeugen stimmen in ihrer Aussage überein.","exampleEn":"The two witnesses agree in their statement.","example2":"Die Zahlen stimmen nicht mit dem Bericht überein.","example2En":"The numbers do not match the report."}]},{"id":"b1-17","title":"B1 · Ü–V (17)","level":"B1","words":[{"de":"übergeben","en":"to hand over; to vomit (reflexive)","pos":"verb","plural":"","meanings":[{"en":"to hand over, pass on","de":"jemandem etwas geben, übertragen"},{"en":"to vomit (sich übergeben)","de":"erbrechen (reflexiv)"}],"rule":"Untrennbar: übergibt, übergab, hat übergeben. Reflexiv 'sich übergeben' = erbrechen.","example":"Der Chef hat ihr die Verantwortung übergeben.","exampleEn":"The boss handed over the responsibility to her.","example2":"Ihm war so schlecht, dass er sich übergeben musste.","example2En":"He felt so sick that he had to vomit."},{"de":"überglücklich","en":"overjoyed","pos":"adjective","plural":"","meanings":[{"en":"extremely happy","de":"sehr, sehr glücklich"}],"rule":"Verstärkung mit 'über-'; meist nicht gesteigert, da schon Superlativbedeutung.","example":"Sie war überglücklich über die bestandene Prüfung.","exampleEn":"She was overjoyed about passing the exam.","example2":"Die Eltern sind überglücklich über das neue Baby.","example2En":"The parents are overjoyed about the new baby."},{"de":"überlegen","en":"to consider, think over; superior","pos":"verb","plural":"","meanings":[{"en":"to think about, consider (verb, untrennbar)","de":"nachdenken, abwägen"},{"en":"superior (adjective)","de":"deutlich besser, stärker"}],"rule":"Als Verb untrennbar: überlegt, überlegte, hat überlegt (oft reflexiv: sich (Dativ) etwas überlegen). Als Adjektiv (+ Dativ): überlegen, überlegener, am überlegensten, z. B. jemandem überlegen sein.","example":"Ich muss mir das noch überlegen.","exampleEn":"I still need to think it over.","example2":"Die Mannschaft war ihrem Gegner klar überlegen.","example2En":"The team was clearly superior to their opponent."},{"de":"übernachten","en":"to stay overnight","pos":"verb","plural":"","meanings":[{"en":"to spend the night somewhere","de":"die Nacht irgendwo verbringen"}],"rule":"Untrennbar, regelmäßig: übernachtet, übernachtete, hat übernachtet.","example":"Wir übernachten in einem kleinen Hotel am See.","exampleEn":"We are staying overnight in a small hotel by the lake.","example2":"Kann ich heute bei dir übernachten?","example2En":"Can I stay over at your place tonight?"},{"de":"die Übernachtung","en":"overnight stay","pos":"noun","plural":"die Übernachtungen","meanings":[{"en":"staying overnight (e.g. in a hotel)","de":"das Schlafen an einem Ort für eine Nacht"}],"rule":"Nomen von 'übernachten'; oft mit Präposition: eine Übernachtung in einem Hotel.","example":"Die Übernachtung im Hotel kostet 80 Euro.","exampleEn":"The overnight stay at the hotel costs 80 euros.","example2":"Wir haben drei Übernachtungen gebucht.","example2En":"We booked three nights' stay."},{"de":"überraschen","en":"to surprise","pos":"verb","plural":"","meanings":[{"en":"to surprise someone","de":"jemandem etwas Unerwartetes zeigen/sagen"}],"rule":"Untrennbar (kein 'ge-' im Partizip): überrascht, überraschte, hat überrascht.","example":"Sie hat ihn zum Geburtstag überrascht.","exampleEn":"She surprised him on his birthday.","example2":"Das Ergebnis hat alle überrascht.","example2En":"The result surprised everyone."},{"de":"die Überschwemmung","en":"flood","pos":"noun","plural":"die Überschwemmungen","meanings":[{"en":"flooding of land or buildings","de":"wenn Wasser das Land überflutet"}],"rule":"Von 'überschwemmen'; oft im Kontext von Naturkatastrophen benutzt.","example":"Der starke Regen hat eine Überschwemmung verursacht.","exampleEn":"The heavy rain caused a flood.","example2":"Viele Häuser wurden durch die Überschwemmung zerstört.","example2En":"Many houses were destroyed by the flood."},{"de":"übersetzen","en":"to translate","pos":"verb","plural":"","meanings":[{"en":"to translate a text","de":"einen Text in eine andere Sprache übertragen"}],"rule":"Untrennbar: übersetzt, übersetzte, hat übersetzt. (Trennbare Variante 'übersetzen' = ans andere Ufer fahren, seltener im B1-Wortschatz.)","example":"Kannst du diesen Satz ins Englische übersetzen?","exampleEn":"Can you translate this sentence into English?","example2":"Der Roman wurde in viele Sprachen übersetzt.","example2En":"The novel has been translated into many languages."},{"de":"die Übersetzung","en":"translation","pos":"noun","plural":"die Übersetzungen","meanings":[{"en":"a translated text","de":"ein Text, der übersetzt wurde"}],"rule":"Nomen von 'übersetzen'; mit Präposition 'in': die Übersetzung ins Deutsche.","example":"Die Übersetzung des Briefes war sehr schwierig.","exampleEn":"The translation of the letter was very difficult.","example2":"Sie arbeitet an einer Übersetzung ins Spanische.","example2En":"She is working on a translation into Spanish."},{"de":"das Übersetzungsbüro","en":"translation agency","pos":"noun","plural":"die Übersetzungsbüros","meanings":[{"en":"an office that provides translation services","de":"eine Firma, die Texte übersetzt"}],"rule":"Zusammensetzung aus 'Übersetzung' + 'Büro'; sächlich wegen 'das Büro'.","example":"Ich habe den Vertrag an ein Übersetzungsbüro geschickt.","exampleEn":"I sent the contract to a translation agency.","example2":"Das Übersetzungsbüro arbeitet mit zehn Sprachen.","example2En":"The translation agency works with ten languages."},{"de":"die Überstunde","en":"overtime hour","pos":"noun","plural":"die Überstunden","meanings":[{"en":"an hour worked beyond normal hours","de":"eine Arbeitsstunde zusätzlich zur normalen Arbeitszeit"}],"rule":"Meist im Plural benutzt: Überstunden machen/leisten.","example":"Ich musste gestern zwei Überstunden machen.","exampleEn":"I had to work two hours of overtime yesterday.","example2":"Werden die Überstunden bezahlt?","example2En":"Is the overtime paid?"},{"de":"die Übertragung","en":"broadcast; transmission","pos":"noun","plural":"die Übertragungen","meanings":[{"en":"a live broadcast (TV/radio)","de":"die Sendung eines Ereignisses im Fernsehen/Radio"},{"en":"the transfer or transmission of something","de":"das Übertragen von etwas (z. B. Daten, Krankheit)"}],"rule":"Nomen von 'übertragen'; wird oft mit 'live' kombiniert: die Live-Übertragung.","example":"Wir haben die Übertragung des Fußballspiels gesehen.","exampleEn":"We watched the broadcast of the football match.","example2":"Die Übertragung des Virus erfolgt über Tröpfchen.","example2En":"The transmission of the virus happens via droplets."},{"de":"überzeugen","en":"to convince","pos":"verb","plural":"","meanings":[{"en":"to convince someone","de":"jemanden von etwas überzeugen, sodass er es glaubt"}],"rule":"Untrennbar: überzeugt, überzeugte, hat überzeugt. Oft mit 'von': jemanden von etwas überzeugen.","example":"Er hat mich von seiner Idee überzeugt.","exampleEn":"He convinced me of his idea.","example2":"Das neue Produkt konnte die Kunden überzeugen.","example2En":"The new product managed to convince the customers."},{"de":"üblich","en":"usual, customary","pos":"adjective","plural":"","meanings":[{"en":"normal or common practice","de":"normal, wie es meistens gemacht wird"}],"rule":"Regelmäßige Steigerung: üblich, üblicher, am üblichsten. Häufig: wie üblich.","example":"Wie üblich kam er zu spät.","exampleEn":"As usual, he came late.","example2":"Das ist hier nicht üblich.","example2En":"That is not customary here."},{"de":"umdrehen","en":"to turn around","pos":"verb","plural":"","meanings":[{"en":"to turn something/someone around","de":"etwas oder sich in die andere Richtung drehen"}],"rule":"Trennbar: dreht um, drehte um, hat umgedreht. Oft reflexiv: sich umdrehen.","example":"Sie hat sich schnell umgedreht.","exampleEn":"She quickly turned around.","example2":"Kannst du das Blatt bitte umdrehen?","example2En":"Can you please turn the sheet over?"},{"de":"umfallen","en":"to fall over","pos":"verb","plural":"","meanings":[{"en":"to fall down/topple over","de":"plötzlich das Gleichgewicht verlieren und hinfallen"}],"rule":"Trennbar, unregelmäßig: fällt um, fiel um, ist umgefallen.","example":"Die Vase ist vom Tisch umgefallen.","exampleEn":"The vase fell over from the table.","example2":"Er wurde so müde, dass er fast umgefallen wäre.","example2En":"He got so tired that he almost toppled over."},{"de":"der Umgang","en":"handling, dealing with","pos":"noun","plural":"","meanings":[{"en":"the way of dealing with someone/something","de":"die Art, wie man mit jemandem/etwas umgeht"}],"rule":"Unzählbar, kein Plural. Feste Wendung: der Umgang mit + Dativ.","example":"Der Umgang mit Kunden erfordert Geduld.","exampleEn":"Dealing with customers requires patience.","example2":"Er hat einen freundlichen Umgang mit seinen Kollegen.","example2En":"He has a friendly way of dealing with his colleagues."},{"de":"die Umgebung","en":"surroundings, area","pos":"noun","plural":"die Umgebungen","meanings":[{"en":"the area surrounding a place","de":"das Gebiet rund um einen Ort"}],"rule":"Oft im Singular benutzt: in der Umgebung von.","example":"Wir haben die Umgebung der Stadt erkundet.","exampleEn":"We explored the surroundings of the city.","example2":"In der Umgebung gibt es viele Wälder.","example2En":"There are many forests in the area."},{"de":"umgehen","en":"to handle/deal with; to avoid, bypass","pos":"verb","plural":"","meanings":[{"en":"to deal with / handle something (trennbar)","de":"mit jemandem/etwas umgehen, z. B. mit einer Maschine oder einer Person"},{"en":"to avoid, bypass, circumvent (untrennbar)","de":"ein Problem oder eine Regel geschickt vermeiden"}],"rule":"Zwei Formen: trennbar 'mit etw./jmdm. umgehen' (geht um, ging um, ist umgegangen) = handhaben; untrennbar 'etw. umgehen' (umgeht, umging, hat umgangen) = vermeiden.","example":"Er kann gut mit Kritik umgehen.","exampleEn":"He can handle criticism well.","example2":"Die Firma versucht, die Vorschrift zu umgehen.","example2En":"The company is trying to bypass the regulation."},{"de":"umgehend","en":"immediate, immediately","pos":"adjective","plural":"","meanings":[{"en":"without delay, right away","de":"sofort, ohne Verzögerung"}],"rule":"Wird oft als Adverb benutzt; formeller als 'sofort', typisch in Geschäftsbriefen.","example":"Bitte antworten Sie uns umgehend.","exampleEn":"Please reply to us immediately.","example2":"Wir werden das Problem umgehend lösen.","example2En":"We will solve the problem right away."},{"de":"die Umschulung","en":"retraining","pos":"noun","plural":"die Umschulungen","meanings":[{"en":"vocational retraining for a new job/career","de":"eine neue berufliche Ausbildung für einen anderen Beruf"}],"rule":"Von 'umschulen'; oft mit 'zu/zum': eine Umschulung zum Krankenpfleger.","example":"Sie macht eine Umschulung zur Bürokauffrau.","exampleEn":"She is doing a retraining course to become an office clerk.","example2":"Nach der Kündigung begann er eine Umschulung.","example2En":"After being laid off, he started a retraining program."},{"de":"umso","en":"the (more/less) — all the more","pos":"adverb","plural":"","meanings":[{"en":"the (with comparative, showing proportional increase)","de":"drückt aus: in noch stärkerem Maße, wenn ..."}],"rule":"Used with comparatives, often after 'je': 'je ..., umso ...'. Not a standalone word.","example":"Je länger ich warte, umso ungeduldiger werde ich.","exampleEn":"The longer I wait, the more impatient I become.","example2":"Sie hat wenig Zeit, umso wichtiger ist eine gute Planung.","example2En":"She has little time, so good planning is all the more important."},{"de":"umweltfreundlich","en":"environmentally friendly","pos":"adjective","plural":"","meanings":[{"en":"not harmful to the environment","de":"der Umwelt nicht schadend"}],"rule":"Regular comparison: umweltfreundlich, umweltfreundlicher, am umweltfreundlichsten.","example":"Wir kaufen nur noch umweltfreundliche Produkte.","exampleEn":"We only buy environmentally friendly products now.","example2":"Fahrradfahren ist sehr umweltfreundlich.","example2En":"Cycling is very environmentally friendly."},{"de":"der Umweltschutz","en":"environmental protection","pos":"noun","plural":"","meanings":[{"en":"protection of the natural environment","de":"Schutz der Natur und Umwelt"}],"rule":"Uncountable, no plural. Compound: Umwelt + Schutz, masculine like 'der Schutz'.","example":"Umweltschutz ist ihr sehr wichtig.","exampleEn":"Environmental protection is very important to her.","example2":"Die Firma investiert viel Geld in den Umweltschutz.","example2En":"The company invests a lot of money in environmental protection."},{"de":"die Umweltverschmutzung","en":"environmental pollution","pos":"noun","plural":"","meanings":[{"en":"pollution of the environment","de":"Verschmutzung von Luft, Wasser und Boden"}],"rule":"Uncountable, no plural. Feminine like 'die Verschmutzung'.","example":"Die Umweltverschmutzung in den Großstädten nimmt zu.","exampleEn":"Environmental pollution is increasing in big cities.","example2":"Autos tragen stark zur Umweltverschmutzung bei.","example2En":"Cars contribute a lot to environmental pollution."},{"de":"unbefristet","en":"permanent, unlimited (contract)","pos":"adjective","plural":"","meanings":[{"en":"without a fixed end date","de":"ohne zeitliche Begrenzung"}],"rule":"Opposite of 'befristet'. Common collocation: ein unbefristeter Vertrag/Arbeitsvertrag.","example":"Sie hat einen unbefristeten Arbeitsvertrag bekommen.","exampleEn":"She got a permanent employment contract.","example2":"Der Mietvertrag ist unbefristet.","example2En":"The rental contract is unlimited (open-ended)."},{"de":"unentschieden","en":"undecided; drawn (tied), score-wise","pos":"adjective","plural":"","meanings":[{"en":"not yet decided","de":"noch nicht entschieden"},{"en":"tied (sports result)","de":"mit gleichem Ergebnis, ohne Sieger"}],"rule":"Also used as a noun 'das Unentschieden' meaning 'a draw/tie' in sports.","example":"Ich bin noch unentschieden, ob ich mitkomme.","exampleEn":"I'm still undecided whether I'll come along.","example2":"Das Spiel endete unentschieden, 1:1.","example2En":"The match ended in a draw, 1:1."},{"de":"der Unfall","en":"accident","pos":"noun","plural":"die Unfälle","meanings":[{"en":"an unplanned, harmful event","de":"ein plötzliches, schädliches Ereignis"}],"rule":"Irregular plural with umlaut: der Unfall, die Unfälle. Common collocation: einen Unfall haben/verursachen.","example":"Er hatte gestern einen Autounfall.","exampleEn":"He had a car accident yesterday.","example2":"Zum Glück ist bei dem Unfall niemand verletzt worden.","example2En":"Luckily, no one was injured in the accident."},{"de":"die Unfallgefahr","en":"risk of accident","pos":"noun","plural":"die Unfallgefahren","meanings":[{"en":"danger that an accident will happen","de":"Gefahr, dass ein Unfall passiert"}],"rule":"Compound of Unfall + Gefahr, feminine like 'die Gefahr'.","example":"Bei Glatteis steigt die Unfallgefahr stark.","exampleEn":"On icy roads, the risk of accidents rises sharply.","example2":"An dieser Kreuzung besteht eine hohe Unfallgefahr.","example2En":"There is a high risk of accidents at this intersection."},{"de":"ungeduldig","en":"impatient","pos":"adjective","plural":"","meanings":[{"en":"not able to wait calmly","de":"ohne Geduld"}],"rule":"Opposite of 'geduldig'. Regular comparison.","example":"Die Kinder wurden ungeduldig, weil der Bus nicht kam.","exampleEn":"The children got impatient because the bus didn't come.","example2":"Sei nicht so ungeduldig, es dauert nicht mehr lange.","example2En":"Don't be so impatient, it won't take much longer."},{"de":"ungesund","en":"unhealthy","pos":"adjective","plural":"","meanings":[{"en":"bad for one's health","de":"schlecht für die Gesundheit"}],"rule":"Opposite of 'gesund'. Takes an umlaut in comparison (like gesund → gesünder): ungesund, ungesünder, am ungesündesten.","example":"Fast Food ist oft sehr ungesund.","exampleEn":"Fast food is often very unhealthy.","example2":"Er raucht und lebt ziemlich ungesund.","example2En":"He smokes and lives quite unhealthily."},{"de":"unglaublich","en":"unbelievable, incredible","pos":"adjective","plural":"","meanings":[{"en":"hard to believe","de":"kaum zu glauben"},{"en":"used as intensifier: extremely","de":"umgangssprachlich: sehr, extrem"}],"rule":"Can also be used adverbially as an intensifier: 'unglaublich gut' (incredibly good).","example":"Das ist eine unglaubliche Geschichte!","exampleEn":"That's an unbelievable story!","example2":"Der Film war unglaublich spannend.","example2En":"The movie was incredibly exciting."},{"de":"unnötig","en":"unnecessary","pos":"adjective","plural":"","meanings":[{"en":"not needed","de":"nicht nötig"}],"rule":"Opposite of 'nötig'. Regular comparison.","example":"Diese Diskussion ist völlig unnötig.","exampleEn":"This discussion is completely unnecessary.","example2":"Kauf nichts Unnötiges, wir haben nicht viel Geld.","example2En":"Don't buy anything unnecessary, we don't have much money."},{"de":"das Unrecht","en":"injustice, wrong","pos":"noun","plural":"","meanings":[{"en":"an unfair or wrongful act/situation","de":"etwas, das nicht gerecht ist"}],"rule":"Uncountable, no plural. Neuter. Fixed phrase: Unrecht haben (to be wrong).","example":"Man hat ihm großes Unrecht getan.","exampleEn":"He was done a great injustice.","example2":"Ich glaube, du hast Unrecht.","example2En":"I think you are wrong."},{"de":"die Unterhaltung","en":"conversation; entertainment","pos":"noun","plural":"die Unterhaltungen","meanings":[{"en":"a conversation, chat","de":"ein Gespräch"},{"en":"entertainment, amusement","de":"Zeitvertreib, Vergnügen"}],"rule":"From verb 'sich unterhalten' (+ mit + Dativ) = to converse; also 'unterhalten' = to entertain.","example":"Wir hatten eine nette Unterhaltung im Café.","exampleEn":"We had a nice conversation in the café.","example2":"Das Fest bot viel Unterhaltung für die Kinder.","example2En":"The festival offered a lot of entertainment for the children."},{"de":"unverbindlich","en":"non-binding, without obligation","pos":"adjective","plural":"","meanings":[{"en":"not legally or formally binding","de":"ohne Verpflichtung"}],"rule":"Opposite of 'verbindlich'. Common in offers: ein unverbindliches Angebot.","example":"Die Beratung ist kostenlos und unverbindlich.","exampleEn":"The consultation is free and without obligation.","example2":"Er gab nur eine unverbindliche Antwort.","example2En":"He only gave a noncommittal answer."},{"de":"das Unwetter","en":"storm, severe weather","pos":"noun","plural":"die Unwetter","meanings":[{"en":"a violent storm","de":"ein sehr starkes, gefährliches Wetter"}],"rule":"Neuter noun, plural unchanged: das Unwetter, die Unwetter.","example":"Das Unwetter hat viele Bäume umgeworfen.","exampleEn":"The storm knocked down many trees.","example2":"Vor dem Unwetter wurde im Radio gewarnt.","example2En":"People were warned about the storm on the radio in advance."},{"de":"der Urlaubstag","en":"vacation day, day off","pos":"noun","plural":"die Urlaubstage","meanings":[{"en":"a day of paid vacation/leave","de":"ein Tag, an dem man frei von der Arbeit hat"}],"rule":"Compound of Urlaub + Tag, masculine like 'der Tag'.","example":"Ich habe noch fünf Urlaubstage in diesem Jahr.","exampleEn":"I still have five vacation days this year.","example2":"Er nimmt morgen einen Urlaubstag.","example2En":"He's taking a day off tomorrow."},{"de":"das Urteil","en":"judgment, verdict","pos":"noun","plural":"die Urteile","meanings":[{"en":"a court's official decision","de":"die Entscheidung eines Gerichts"},{"en":"an opinion or assessment","de":"eine persönliche Meinung/Bewertung"}],"rule":"Neuter noun. Collocation: ein Urteil fällen/sprechen (to pass judgment).","example":"Das Gericht hat sein Urteil gesprochen.","exampleEn":"The court has passed its verdict.","example2":"Ich möchte mir noch kein Urteil über ihn erlauben.","example2En":"I don't want to form a judgment about him yet."},{"de":"vegan","en":"vegan","pos":"adjective","plural":"","meanings":[{"en":"vegan (no animal products)","de":"ohne tierische Produkte"}],"rule":"No comparison typically used; regular adjective endings: veganes Essen, vegane Ernährung.","example":"Sie ernährt sich seit zwei Jahren vegan.","exampleEn":"She has been eating vegan for two years.","example2":"Das Restaurant bietet auch vegane Gerichte an.","example2En":"The restaurant also offers vegan dishes."},{"de":"der Veganer / die Veganerin","en":"vegan (person)","pos":"noun","plural":"die Veganer / die Veganerinnen","meanings":[{"en":"a person who eats no animal products","de":"jemand, der vegan lebt"}],"rule":"Agent noun from 'vegan'; masculine -er, feminine -erin.","example":"Als Veganer isst er keine Milchprodukte.","exampleEn":"As a vegan, he doesn't eat dairy products.","example2":"Immer mehr Veganerinnen kochen ohne Fleisch und Eier.","example2En":"More and more vegan women cook without meat and eggs."},{"de":"verändern","en":"to change, alter","pos":"verb","plural":"","meanings":[{"en":"to change something","de":"etwas anders machen"},{"en":"(sich verändern) to change, develop","de":"anders werden"}],"rule":"Regular weak verb (veränderte, hat verändert); can be used transitively or reflexively (sich verändern).","example":"Die neue Arbeit hat sein Leben verändert.","exampleEn":"The new job changed his life.","example2":"Die Stadt hat sich in den letzten Jahren stark verändert.","example2En":"The city has changed a lot in recent years."},{"de":"verärgert","en":"annoyed, angry","pos":"adjective","plural":"","meanings":[{"en":"annoyed, angry (about something)","de":"wütend, genervt"}],"rule":"Past participle of 'verärgern' used as adjective; often with 'über + Akkusativ'.","example":"Er war sehr verärgert über die Verspätung.","exampleEn":"He was very annoyed about the delay.","example2":"Die Kundin reagierte verärgert auf die schlechte Beratung.","example2En":"The customer reacted angrily to the poor service."},{"de":"der Verbrauch","en":"consumption, usage","pos":"noun","plural":"","meanings":[{"en":"the amount used (of energy, water, etc.)","de":"die verbrauchte Menge"}],"rule":"Uncountable noun; related verb 'verbrauchen'; often in compounds like Energieverbrauch, Wasserverbrauch.","example":"Der Verbrauch an Strom ist im Winter höher.","exampleEn":"Electricity consumption is higher in winter.","example2":"Wir müssen unseren Verbrauch an Plastik reduzieren.","example2En":"We need to reduce our plastic consumption."},{"de":"der Verbraucher / die Verbraucherin","en":"consumer","pos":"noun","plural":"die Verbraucher / die Verbraucherinnen","meanings":[{"en":"a person who buys/uses goods and services","de":"jemand, der Waren oder Dienstleistungen kauft"}],"rule":"Agent noun from 'verbrauchen'; often used in 'Verbraucherschutz' (consumer protection).","example":"Die Verbraucher achten immer mehr auf Qualität.","exampleEn":"Consumers pay more and more attention to quality.","example2":"Als Verbraucherin hat sie ein Recht auf klare Informationen.","example2En":"As a consumer, she has a right to clear information."},{"de":"verdrängen","en":"to displace, push out; to repress","pos":"verb","plural":"","meanings":[{"en":"to push something out / take its place","de":"etwas wegdrängen, ersetzen"},{"en":"to repress (a thought or feeling)","de":"etwas nicht wahrhaben wollen"}],"rule":"Regular weak verb (verdrängte, hat verdrängt); + Akkusativ.","example":"Das neue Geschäft hat den kleinen Laden vom Markt verdrängt.","exampleEn":"The new store pushed the small shop out of the market.","example2":"Sie versucht, die schlechten Erinnerungen zu verdrängen.","example2En":"She tries to repress the bad memories."},{"de":"vereinbar","en":"compatible","pos":"adjective","plural":"","meanings":[{"en":"able to be combined or reconciled with something","de":"gut zusammenpassend mit etwas"}],"rule":"Often with 'mit + Dativ'; opposite is 'unvereinbar'.","example":"Der Job ist gut mit dem Familienleben vereinbar.","exampleEn":"The job is easily compatible with family life.","example2":"Diese Werte sind nicht mit unserer Firmenpolitik vereinbar.","example2En":"These values are not compatible with our company policy."},{"de":"vereinigen","en":"to unite, combine","pos":"verb","plural":"","meanings":[{"en":"to bring together, unite","de":"zusammenbringen"}],"rule":"Regular weak verb (vereinigte, hat vereinigt); can be reflexive (sich vereinigen); related noun: die Vereinigung.","example":"Die beiden Firmen haben sich zu einem Konzern vereinigt.","exampleEn":"The two companies merged into one corporation.","example2":"1990 wurden Ost- und Westdeutschland vereinigt.","example2En":"In 1990, East and West Germany were united."},{"de":"verfolgen","en":"to follow, pursue; to chase","pos":"verb","plural":"","meanings":[{"en":"to chase or pursue someone","de":"jemandem hinterherlaufen"},{"en":"to follow (news, a goal) closely","de":"aufmerksam beobachten"}],"rule":"Regular weak verb (verfolgte, hat verfolgt); + Akkusativ.","example":"Die Polizei hat den Dieb bis zum Bahnhof verfolgt.","exampleEn":"The police chased the thief to the train station.","example2":"Ich verfolge die Nachrichten jeden Tag im Internet.","example2En":"I follow the news every day online."},{"de":"vergleichbar","en":"comparable","pos":"adjective","plural":"","meanings":[{"en":"similar enough to be compared","de":"ähnlich, vergleichen lassend"}],"rule":"Often with 'mit + Dativ'; from verb 'vergleichen'.","example":"Die Preise sind mit denen im letzten Jahr vergleichbar.","exampleEn":"The prices are comparable to those last year.","example2":"Seine Situation ist kaum mit meiner vergleichbar.","example2En":"His situation is hardly comparable to mine."}]},{"id":"b1-18","title":"B1 · V–W (18)","level":"B1","words":[{"de":"die Vergütung","en":"payment, remuneration","pos":"noun","plural":"die Vergütungen","meanings":[{"en":"payment for work or a service","de":"Bezahlung für eine Leistung"}],"rule":"From verb 'vergüten'; formal word, often used for salary/compensation in job contexts.","example":"Die Vergütung für den Praktikanten ist leider gering.","exampleEn":"The compensation for the intern is unfortunately low.","example2":"Er verlangt eine angemessene Vergütung für seine Arbeit.","example2En":"He demands fair pay for his work."},{"de":"verhaften","en":"to arrest","pos":"verb","plural":"","meanings":[{"en":"to arrest someone (by police)","de":"jemanden festnehmen"}],"rule":"Regular weak verb (verhaftete, hat verhaftet); + Akkusativ; often used in passive: wird verhaftet.","example":"Die Polizei hat den Mann wegen Diebstahls verhaftet.","exampleEn":"The police arrested the man for theft.","example2":"Er wurde am Flughafen verhaftet.","example2En":"He was arrested at the airport."},{"de":"verlängern","en":"to extend, lengthen","pos":"verb","plural":"","meanings":[{"en":"to make longer in time","de":"die Dauer verlängern"},{"en":"to make longer in length","de":"länger machen"}],"rule":"Regular weak verb (verlängerte, hat verlängert); + Akkusativ.","example":"Ich möchte meinen Vertrag um ein Jahr verlängern.","exampleEn":"I would like to extend my contract by one year.","example2":"Die Schneiderin hat die Hose verlängert.","example2En":"The tailor lengthened the trousers."},{"de":"verlassen","en":"to leave (a place/person); (sich verlassen auf) to rely on","pos":"verb","plural":"","meanings":[{"en":"to leave a place or a person","de":"einen Ort oder eine Person weggehen"},{"en":"(sich verlassen auf) to rely/depend on someone","de":"jemandem vertrauen"}],"rule":"Irregular: verlässt, verließ, hat verlassen; + Akkusativ; reflexive form 'sich verlassen auf + Akkusativ' means 'to rely on'.","example":"Sie hat die Stadt vor zehn Jahren verlassen.","exampleEn":"She left the city ten years ago.","example2":"Du kannst dich auf mich verlassen.","example2En":"You can rely on me."},{"de":"verlaufen","en":"to go, take a course; (sich verlaufen) to get lost","pos":"verb","plural":"","meanings":[{"en":"to proceed, happen (an event, road)","de":"einen bestimmten Verlauf nehmen"},{"en":"(sich verlaufen) to lose one's way","de":"sich nicht mehr auskennen, den Weg verlieren"}],"rule":"Irregular: verläuft, verlief, ist/hat verlaufen (intransitive 'ist', reflexive 'hat'); reflexive form means 'to get lost'.","example":"Die Veranstaltung ist ohne Probleme verlaufen.","exampleEn":"The event went off without any problems.","example2":"Wir haben uns im Wald verlaufen.","example2En":"We got lost in the forest."},{"de":"verletzen","en":"to injure, hurt","pos":"verb","plural":"","meanings":[{"en":"to physically injure someone","de":"jemandem körperlich schaden"},{"en":"to hurt someone's feelings","de":"jemanden kränken"}],"rule":"Regular weak verb (verletzte, hat verletzt); + Akkusativ; often reflexive: sich verletzen (to injure oneself).","example":"Er hat sich beim Fußballspielen am Bein verletzt.","exampleEn":"He injured his leg while playing football.","example2":"Ihre Bemerkung hat mich sehr verletzt.","example2En":"Her remark hurt me a lot."},{"de":"der Verlierer / die Verliererin","en":"loser","pos":"noun","plural":"die Verlierer / die Verliererinnen","meanings":[{"en":"person who loses (a game, competition)","de":"jemand, der verliert"}],"rule":"Gebildet von 'verlieren'; weibliche Form: die Verliererin.","example":"Er ist ein fairer Verlierer und gratuliert dem Sieger.","exampleEn":"He is a fair loser and congratulates the winner.","example2":"Bei diesem Spiel gibt es nur einen Verlierer.","example2En":"In this game there is only one loser."},{"de":"vermischen","en":"to mix, blend","pos":"verb","plural":"","meanings":[{"en":"to mix substances together","de":"verschiedene Dinge zusammenmischen"}],"rule":"Regelmäßig: vermischt, vermischte, hat vermischt. Oft reflexiv: sich vermischen.","example":"Man muss Mehl und Wasser vermischen.","exampleEn":"You have to mix flour and water.","example2":"Die Farben vermischen sich zu Grau.","example2En":"The colors mix together to become gray."},{"de":"vermissen","en":"to miss (someone/something)","pos":"verb","plural":"","meanings":[{"en":"to feel the absence of someone or something","de":"das Fehlen von jemandem/etwas schmerzlich spüren"}],"rule":"Regelmäßig: vermisst, vermisste, hat vermisst. + Akkusativ.","example":"Ich vermisse meine Familie sehr.","exampleEn":"I miss my family a lot.","example2":"Seit dem Umzug vermisse ich meine alten Freunde.","example2En":"Since moving, I miss my old friends."},{"de":"verpacken","en":"to pack, wrap up","pos":"verb","plural":"","meanings":[{"en":"to put something in packaging","de":"etwas in eine Verpackung tun"}],"rule":"Regelmäßig: verpackt, verpackte, hat verpackt.","example":"Sie verpackt das Geschenk in buntes Papier.","exampleEn":"She wraps the gift in colorful paper.","example2":"Die Ware wird sicher verpackt und versandt.","example2En":"The goods are securely packed and shipped."},{"de":"verpflichten","en":"to oblige, commit (someone)","pos":"verb","plural":"","meanings":[{"en":"to bind someone to a duty or contract","de":"jemanden zu etwas verbindlich machen"},{"en":"to sign/hire (a player, employee)","de":"jemanden vertraglich engagieren"}],"rule":"Regelmäßig: verpflichtet, verpflichtete, hat verpflichtet. Oft reflexiv: sich verpflichten (zu + Dativ).","example":"Der Vertrag verpflichtet ihn zu pünktlicher Zahlung.","exampleEn":"The contract obliges him to pay on time.","example2":"Der Verein hat einen neuen Trainer verpflichtet.","example2En":"The club has signed a new coach."},{"de":"verreisen","en":"to go on a trip, travel away","pos":"verb","plural":"","meanings":[{"en":"to leave for a journey","de":"eine Reise antreten"}],"rule":"Regelmäßig, mit 'sein': verreist, verreiste, ist verreist.","example":"Wir verreisen im Sommer nach Italien.","exampleEn":"We are going on a trip to Italy in the summer.","example2":"Er ist beruflich verreist und kommt erst nächste Woche zurück.","example2En":"He has gone away on business and won't be back until next week."},{"de":"der Versand","en":"shipping, dispatch","pos":"noun","plural":"","meanings":[{"en":"the process of sending goods","de":"das Versenden von Waren"}],"rule":"Maskulin, meist im Singular (unzählbar); von 'versenden'.","example":"Der Versand der Bestellung dauert zwei Tage.","exampleEn":"Shipping of the order takes two days.","example2":"Der Versand ist kostenlos ab 50 Euro Bestellwert.","example2En":"Shipping is free from an order value of 50 euros."},{"de":"die Versandkosten (Pl.)","en":"shipping costs","pos":"noun","plural":"","meanings":[{"en":"fees charged for shipping","de":"Kosten für den Versand einer Ware"}],"rule":"Nur im Plural gebräuchlich; Zusammensetzung aus Versand + Kosten.","example":"Die Versandkosten betragen 4,95 Euro.","exampleEn":"The shipping costs are 4.95 euros.","example2":"Bitte prüfen Sie die Versandkosten vor der Bestellung.","example2En":"Please check the shipping costs before ordering."},{"de":"versandkostenfrei","en":"free shipping (adj.)","pos":"adjective","plural":"","meanings":[{"en":"without shipping costs","de":"ohne Versandkosten"}],"rule":"Keine Steigerung üblich; zusammengesetztes Adjektiv aus Versandkosten + frei.","example":"Ab 30 Euro liefern wir versandkostenfrei.","exampleEn":"From 30 euros, we deliver with free shipping.","example2":"Dieser Artikel ist versandkostenfrei erhältlich.","example2En":"This item is available with free shipping."},{"de":"die Versandkostenpauschale","en":"flat shipping fee","pos":"noun","plural":"die Versandkostenpauschalen","meanings":[{"en":"a fixed flat-rate shipping charge","de":"ein fester Pauschalbetrag für den Versand"}],"rule":"Feminin; Zusammensetzung aus Versandkosten + Pauschale.","example":"Wir berechnen eine Versandkostenpauschale von 5 Euro.","exampleEn":"We charge a flat shipping fee of 5 euros.","example2":"Die Versandkostenpauschale gilt für die ganze Bestellung.","example2En":"The flat shipping fee applies to the whole order."},{"de":"verschieben","en":"to postpone; to move/shift","pos":"verb","plural":"","meanings":[{"en":"to postpone to a later time","de":"auf einen späteren Zeitpunkt legen"},{"en":"to move something to another position","de":"etwas an eine andere Stelle rücken"}],"rule":"Unregelmäßig: verschiebt, verschob, hat verschoben. + Akkusativ.","example":"Wir müssen den Termin auf nächste Woche verschieben.","exampleEn":"We have to postpone the appointment to next week.","example2":"Kannst du den Schrank ein Stück verschieben?","example2En":"Can you move the cupboard a bit?"},{"de":"verschmutzen","en":"to pollute, get dirty","pos":"verb","plural":"","meanings":[{"en":"to make something dirty/polluted","de":"etwas schmutzig machen"},{"en":"to become dirty/polluted","de":"schmutzig werden"}],"rule":"Regelmäßig; transitiv mit 'haben' (hat verschmutzt), intransitiv mit 'sein' (ist verschmutzt).","example":"Die Fabrik verschmutzt den Fluss.","exampleEn":"The factory pollutes the river.","example2":"Die Luft in der Stadt ist stark verschmutzt.","example2En":"The air in the city is heavily polluted."},{"de":"verschwenden","en":"to waste","pos":"verb","plural":"","meanings":[{"en":"to use something carelessly without benefit","de":"etwas nutzlos vergeuden"}],"rule":"Regelmäßig: verschwendet, verschwendete, hat verschwendet. + Akkusativ.","example":"Du solltest kein Wasser verschwenden.","exampleEn":"You shouldn't waste water.","example2":"Er hat viel Geld für unnötige Dinge verschwendet.","example2En":"He wasted a lot of money on unnecessary things."},{"de":"die Verschwendung","en":"waste, wastefulness","pos":"noun","plural":"die Verschwendungen","meanings":[{"en":"the act of wasting resources","de":"das Verschwenden von etwas"}],"rule":"Feminin; von 'verschwenden'; meist im Singular verwendet.","example":"Das ist reine Zeitverschwendung.","exampleEn":"That is a pure waste of time.","example2":"Die Verschwendung von Lebensmitteln ist ein großes Problem.","example2En":"The waste of food is a big problem."},{"de":"versehentlich","en":"accidentally, by mistake","pos":"adverb","plural":"","meanings":[{"en":"unintentionally, by accident","de":"ohne Absicht, aus Versehen"}],"rule":"Keine Steigerung; oft mit 'aus Versehen' austauschbar.","example":"Ich habe versehentlich die falsche E-Mail geschickt.","exampleEn":"I accidentally sent the wrong email.","example2":"Er hat versehentlich meine Tasche mitgenommen.","example2En":"He accidentally took my bag."},{"de":"versenden","en":"to send, dispatch","pos":"verb","plural":"","meanings":[{"en":"to send goods, mail or messages","de":"etwas per Post, Kurier o. Ä. schicken"}],"rule":"Unregelmäßig/regelmäßig möglich: versendet, versandte/versendete, hat versandt/versendet. + Akkusativ.","example":"Wir versenden die Ware noch heute.","exampleEn":"We will dispatch the goods today.","example2":"Die Einladungen wurden per Post versendet.","example2En":"The invitations were sent by mail."},{"de":"versichern","en":"to insure; to assure","pos":"verb","plural":"","meanings":[{"en":"to insure something against risk","de":"etwas gegen Schäden absichern"},{"en":"to assure someone of something","de":"jemandem etwas fest zusichern"}],"rule":"Regelmäßig: versichert, versicherte, hat versichert. Oft reflexiv: sich versichern.","example":"Er hat sein Auto gegen Diebstahl versichert.","exampleEn":"He insured his car against theft.","example2":"Sie versicherte mir, dass alles in Ordnung sei.","example2En":"She assured me that everything was fine."},{"de":"der Versicherungsberater / die Versicherungsberaterin","en":"insurance advisor","pos":"noun","plural":"die Versicherungsberater / die Versicherungsberaterinnen","meanings":[{"en":"a professional who advises on insurance matters","de":"jemand, der beruflich zu Versicherungen berät"}],"rule":"Zusammensetzung aus Versicherung + Berater; weibliche Form: die Versicherungsberaterin.","example":"Der Versicherungsberater hat mir eine passende Police empfohlen.","exampleEn":"The insurance advisor recommended a suitable policy to me.","example2":"Ich habe einen Termin bei meiner Versicherungsberaterin.","example2En":"I have an appointment with my insurance advisor."},{"de":"der Versicherungsschutz","en":"insurance coverage","pos":"noun","plural":"","meanings":[{"en":"the protection/coverage provided by an insurance policy","de":"der Schutz durch eine Versicherung"}],"rule":"Kompoundwort: Versicherung + Schutz; meist ohne Plural, unzählbar.","example":"Mein Versicherungsschutz umfasst auch Diebstahl.","exampleEn":"My insurance coverage also includes theft.","example2":"Ohne ausreichenden Versicherungsschutz kann das teuer werden.","example2En":"Without adequate insurance coverage, this can get expensive."},{"de":"versorgen","en":"to provide for; to take care of/supply","pos":"verb","plural":"","meanings":[{"en":"to supply someone with something","de":"jemandem etwas geben, das er braucht"},{"en":"to take care of / look after (a person, wound)","de":"sich um jemanden kümmern"}],"rule":"regelmäßig: versorgt, versorgte, hat versorgt; + Akkusativ (Person) + mit (Sache): jemanden mit etwas versorgen.","example":"Die Firma versorgt die Stadt mit Strom.","exampleEn":"The company supplies the city with electricity.","example2":"Sie hat die Wunde sofort versorgt.","example2En":"She took care of the wound immediately."},{"de":"versprechen","en":"to promise","pos":"verb","plural":"","meanings":[{"en":"to give a promise","de":"fest zusagen, etwas zu tun"},{"en":"to expect/hope for (sich etwas versprechen von)","de":"sich etwas erhoffen"}],"rule":"unregelmäßig: verspricht, versprach, hat versprochen; + Dativ der Person.","example":"Er hat mir versprochen, pünktlich zu kommen.","exampleEn":"He promised me that he would come on time.","example2":"Sie verspricht sich viel von dem neuen Job.","example2En":"She expects a lot from the new job."},{"de":"das Verständnis","en":"understanding","pos":"noun","plural":"","meanings":[{"en":"comprehension (of a text, situation)","de":"das Begreifen einer Sache"},{"en":"sympathy/empathy for someone's situation","de":"Mitgefühl für jemanden"}],"rule":"unzählbar, kein Plural; + für: Verständnis für etwas haben.","example":"Ich habe kein Verständnis für dieses Verhalten.","exampleEn":"I have no sympathy for this behavior.","example2":"Vielen Dank für Ihr Verständnis.","example2En":"Thank you very much for your understanding."},{"de":"die Verstärkung","en":"reinforcement; strengthening","pos":"noun","plural":"die Verstärkungen","meanings":[{"en":"additional support/reinforcement (people)","de":"zusätzliche Unterstützung"},{"en":"strengthening/amplification (of a signal, sound)","de":"das Stärker-Machen"}],"rule":"von 'verstärken'; als Person: Verstärkung bekommen/holen.","example":"Das Team braucht dringend Verstärkung.","exampleEn":"The team urgently needs reinforcement.","example2":"Die Verstärkung des Signals war deutlich zu hören.","example2En":"The amplification of the signal was clearly audible."},{"de":"der Verstoß","en":"violation; infringement","pos":"noun","plural":"die Verstöße","meanings":[{"en":"a breach of a rule or law","de":"das Nichtbeachten einer Regel"}],"rule":"+ gegen: ein Verstoß gegen das Gesetz/die Regeln.","example":"Das ist ein klarer Verstoß gegen die Vorschriften.","exampleEn":"That is a clear violation of the regulations.","example2":"Für diesen Verstoß droht eine Geldstrafe.","example2En":"A fine is possible for this violation."},{"de":"verstoßen","en":"to violate; to disown/reject","pos":"verb","plural":"","meanings":[{"en":"to break a rule or law (gegen etwas verstoßen)","de":"gegen eine Regel handeln"},{"en":"to disown/cast out a person (jemanden verstoßen)","de":"jemanden aus der Familie ausschließen"}],"rule":"unregelmäßig: verstößt, verstieß, hat verstoßen; +gegen (Akk.) für Regeln, + Akk. Person für 'verstoßen' im Sinn von ausschließen.","example":"Er hat gegen die Verkehrsregeln verstoßen.","exampleEn":"He violated the traffic rules.","example2":"Die Familie hat ihn verstoßen.","example2En":"The family disowned him."},{"de":"vertragen","en":"to tolerate/stand; (sich vertragen) to get along","pos":"verb","plural":"","meanings":[{"en":"to tolerate physically (food, medicine, weather)","de":"etwas ohne negative Folgen aushalten"},{"en":"sich vertragen: to get along well with someone","de":"gut miteinander auskommen"}],"rule":"unregelmäßig: verträgt, vertrug, hat vertragen; reflexiv 'sich vertragen mit + Dativ'.","example":"Ich vertrage keinen Kaffee am Abend.","exampleEn":"I can't tolerate coffee in the evening.","example2":"Die Geschwister vertragen sich wieder gut.","example2En":"The siblings get along well again."},{"de":"das Vertragsende","en":"end of contract","pos":"noun","plural":"die Vertragsenden","meanings":[{"en":"the date/point when a contract ends","de":"der Zeitpunkt, an dem ein Vertrag endet"}],"rule":"Kompositum: Vertrag + Ende; meist im Singular verwendet.","example":"Das Vertragsende liegt am 31. Dezember.","exampleEn":"The end of the contract is on December 31st.","example2":"Bitte kündigen Sie rechtzeitig vor Vertragsende.","example2En":"Please cancel in good time before the end of the contract."},{"de":"die Vertragsnummer","en":"contract number","pos":"noun","plural":"die Vertragsnummern","meanings":[{"en":"the reference number of a contract","de":"die Nummer, die einen Vertrag kennzeichnet"}],"rule":"Kompositum: Vertrag + Nummer; regelmäßiger Plural auf -n.","example":"Bitte geben Sie Ihre Vertragsnummer an.","exampleEn":"Please provide your contract number.","example2":"Die Vertragsnummer finden Sie oben rechts auf dem Schreiben.","example2En":"You can find the contract number at the top right of the letter."},{"de":"verursachen","en":"to cause","pos":"verb","plural":"","meanings":[{"en":"to bring about/cause (usually something negative)","de":"etwas (meist Negatives) bewirken"}],"rule":"regelmäßig: verursacht, verursachte, hat verursacht; + Akkusativ.","example":"Der Unfall wurde durch Glatteis verursacht.","exampleEn":"The accident was caused by black ice.","example2":"Rauchen verursacht viele Krankheiten.","example2En":"Smoking causes many diseases."},{"de":"verurteilen","en":"to convict/sentence; to condemn","pos":"verb","plural":"","meanings":[{"en":"to sentence someone in court","de":"jemanden gerichtlich bestrafen"},{"en":"to condemn/disapprove strongly of something","de":"etwas stark missbilligen"}],"rule":"regelmäßig: verurteilt, verurteilte, hat verurteilt; + Akkusativ + zu (Strafe).","example":"Der Richter hat ihn zu drei Jahren Haft verurteilt.","exampleEn":"The judge sentenced him to three years in prison.","example2":"Viele Politiker verurteilen die Gewalt.","example2En":"Many politicians condemn the violence."},{"de":"verwerten","en":"to use/utilize; to recycle","pos":"verb","plural":"","meanings":[{"en":"to make use of something (material, information)","de":"etwas nutzen oder verwenden"},{"en":"to recycle waste materials","de":"Abfall wiederverwenden"}],"rule":"regelmäßig: verwertet, verwertete, hat verwertet; + Akkusativ.","example":"Die Firma verwertet alte Elektrogeräte.","exampleEn":"The company recycles old electronic devices.","example2":"Man kann die Reste vom Gemüse gut verwerten.","example2En":"You can make good use of the vegetable leftovers."},{"de":"der Verzehr","en":"consumption (of food/drink)","pos":"noun","plural":"","meanings":[{"en":"the act of eating or drinking something","de":"das Essen oder Trinken von etwas"}],"rule":"unzählbar, kein Plural; typisch in Hinweisen: 'zum sofortigen Verzehr bestimmt'.","example":"Das Getränk ist nach dem Öffnen zum sofortigen Verzehr bestimmt.","exampleEn":"After opening, the drink is intended for immediate consumption.","example2":"Der Verzehr von rohem Fisch kann riskant sein.","example2En":"The consumption of raw fish can be risky."},{"de":"verzichten","en":"to do without; to renounce","pos":"verb","plural":"","meanings":[{"en":"to give up or forgo something voluntarily","de":"freiwillig auf etwas verzichten"}],"rule":"regelmäßig: verzichtet, verzichtete, hat verzichtet; + auf (Akkusativ).","example":"Er verzichtet auf Fleisch.","exampleEn":"He does without meat.","example2":"Sie hat auf ihren Urlaub verzichtet, um zu arbeiten.","example2En":"She gave up her vacation in order to work."},{"de":"das Visum","en":"visa","pos":"noun","plural":"die Visa","meanings":[{"en":"official permission document to enter a country","de":"die offizielle Einreiseerlaubnis"}],"rule":"unregelmäßiger Plural: die Visa (auch: die Visen).","example":"Für die Einreise brauchen wir ein Visum.","exampleEn":"We need a visa to enter the country.","example2":"Das Visum ist drei Monate gültig.","example2En":"The visa is valid for three months."},{"de":"völlig","en":"completely; total","pos":"adjective","plural":"","meanings":[{"en":"completely, entirely","de":"ganz, vollständig"}],"rule":"keine unregelmäßige Steigerung; wird oft als Adverb verwendet: völlig neu, völlig egal.","example":"Das ist mir völlig egal.","exampleEn":"That's completely irrelevant to me.","example2":"Die Straße war völlig leer.","example2En":"The street was completely empty."},{"de":"die Vollkaskoversicherung (Vollkasko)","en":"comprehensive car insurance","pos":"noun","plural":"die Vollkaskoversicherungen","meanings":[{"en":"comprehensive insurance covering damage to one's own car regardless of fault","de":"Versicherung, die auch selbst verursachte Schäden am eigenen Auto abdeckt"}],"rule":"Kompositum: voll + Kasko + Versicherung; Kurzform 'Vollkasko' ist gebräuchlich, meist ohne Artikel im Alltag.","example":"Für das neue Auto habe ich eine Vollkaskoversicherung abgeschlossen.","exampleEn":"I took out comprehensive insurance for the new car.","example2":"Mit Vollkasko sind auch selbst verschuldete Unfälle versichert.","example2En":"With comprehensive insurance, even self-caused accidents are covered."},{"de":"voraussichtlich","en":"expected; probably","pos":"adjective","plural":"","meanings":[{"en":"expected, anticipated","de":"wie erwartet, vermutlich"}],"rule":"Wird sowohl attributiv vor dem Nomen als auch adverbial bei Verben verwendet; da kaum graduierbar, praktisch nicht gesteigert.","example":"Der Zug kommt voraussichtlich um 18 Uhr an.","exampleEn":"The train is expected to arrive at 6 pm.","example2":"Die Reparatur dauert voraussichtlich zwei Tage.","example2En":"The repair is expected to take two days."},{"de":"vorbeigehen","en":"to walk past; to pass (of time/pain)","pos":"verb","plural":"","meanings":[{"en":"to walk/go past someone or something","de":"an jemandem/etwas vorübergehen"},{"en":"(of pain, time) to pass, to go away","de":"aufhören, enden"}],"rule":"trennbar: geht ... vorbei, ging vorbei, ist vorbeigegangen; oft mit 'an + Dativ'","example":"Ich bin an deinem Haus vorbeigegangen.","exampleEn":"I walked past your house.","example2":"Die Kopfschmerzen gehen bald vorbei.","example2En":"The headache will pass soon."},{"de":"vorher","en":"before; beforehand","pos":"adverb","plural":"","meanings":[{"en":"before that, earlier, beforehand","de":"davor, früher"}],"rule":"Temporaladverb, Gegenteil von 'nachher'; unveränderlich (nicht deklinierbar).","example":"Vorher hatte ich noch nie Sushi gegessen.","exampleEn":"Before that, I had never eaten sushi.","example2":"Ich muss vorher noch schnell einkaufen gehen.","example2En":"I need to quickly go shopping beforehand."},{"de":"vorhersagen","en":"to predict, to forecast","pos":"verb","plural":"","meanings":[{"en":"to predict, forecast","de":"im Voraus sagen, prognostizieren"}],"rule":"trennbar: sagt ... vorher, sagte vorher, hat vorhergesagt","example":"Der Wetterbericht sagt Regen für morgen vorher.","exampleEn":"The weather forecast predicts rain for tomorrow.","example2":"Niemand konnte diesen Erfolg vorhersagen.","example2En":"Nobody could have predicted this success."},{"de":"vorschreiben","en":"to prescribe, to dictate (rules)","pos":"verb","plural":"","meanings":[{"en":"to prescribe, require, dictate","de":"vorgeben, anordnen, befehlen"}],"rule":"unregelmäßig: schreibt ... vor, schrieb vor, hat vorgeschrieben; oft im Passiv 'vorgeschrieben sein'","example":"Das Gesetz schreibt für Motorradfahrer das Tragen eines Helms vor.","exampleEn":"The law requires motorcyclists to wear a helmet.","example2":"Lass dir nicht vorschreiben, was du tun sollst.","example2En":"Don't let anyone dictate what you should do."},{"de":"vorsichtig","en":"careful, cautious","pos":"adjective","plural":"","meanings":[{"en":"careful, cautious","de":"achtsam, behutsam"}],"rule":"Regelmäßige Steigerung: vorsichtig, vorsichtiger, am vorsichtigsten.","example":"Sei vorsichtig, die Straße ist glatt!","exampleEn":"Be careful, the road is slippery!","example2":"Er fährt immer sehr vorsichtig.","example2En":"He always drives very cautiously."},{"de":"wahr","en":"true","pos":"adjective","plural":"","meanings":[{"en":"true, in accordance with fact","de":"der Wirklichkeit entsprechend"}],"rule":"Regelmäßige Steigerung: wahr, wahrer, am wahrsten (selten gesteigert); Nicht verwechseln mit 'war' (Präteritum von 'sein').","example":"Ist es wahr, dass du umziehst?","exampleEn":"Is it true that you're moving?","example2":"Diese Geschichte ist leider wahr.","example2En":"Unfortunately, this story is true."},{"de":"wahrscheinlich","en":"probable, likely","pos":"adjective","plural":"","meanings":[{"en":"probable, likely","de":"vermutlich, höchstwahrscheinlich"}],"rule":"Wird auch als Adverb gebraucht; regelmäßige Steigerung.","example":"Er kommt wahrscheinlich morgen an.","exampleEn":"He will probably arrive tomorrow.","example2":"Das ist die wahrscheinlichste Erklärung.","example2En":"That is the most probable explanation."}]},{"id":"b1-19","title":"B1 · W–Z (19)","level":"B1","words":[{"de":"der Wanderer / die Wanderin","en":"hiker","pos":"noun","plural":"die Wanderer / die Wanderinnen","meanings":[{"en":"person who hikes, walker in nature","de":"jemand, der wandert"}],"rule":"Maskuline Form 'der Wanderer' bleibt im Plural gleich; weibliche Form 'die Wanderin', Plural 'die Wanderinnen'.","example":"Die Wanderer machten am Gipfel eine Pause.","exampleEn":"The hikers took a break at the summit.","example2":"Eine Wanderin zeigte uns den richtigen Weg.","example2En":"A hiker showed us the right path."},{"de":"die Wandertour","en":"hiking tour, hike","pos":"noun","plural":"die Wandertouren","meanings":[{"en":"a planned hike or hiking trip","de":"eine organisierte Wanderung"}],"rule":"Zusammensetzung aus 'wandern' + 'Tour'; feminines Genus wie 'die Tour'.","example":"Am Samstag machen wir eine Wandertour in den Bergen.","exampleEn":"On Saturday we're going on a hiking tour in the mountains.","example2":"Die Wandertour dauert ungefähr fünf Stunden.","example2En":"The hike takes about five hours."},{"de":"die Ware","en":"goods, merchandise","pos":"noun","plural":"die Waren","meanings":[{"en":"goods, merchandise, product for sale","de":"Produkt, das verkauft wird"}],"rule":"Oft im Plural 'die Waren' für Handelsgüter allgemein.","example":"Die Ware wird morgen geliefert.","exampleEn":"The goods will be delivered tomorrow.","example2":"Im Supermarkt gibt es viele verschiedene Waren.","example2En":"There are many different goods in the supermarket."},{"de":"der Warenkorb","en":"shopping basket/cart","pos":"noun","plural":"die Warenkörbe","meanings":[{"en":"shopping basket or cart (also online)","de":"Korb für Einkäufe, auch online"}],"rule":"Zusammensetzung aus 'Ware' + 'Korb'; im Online-Shop = 'Einkaufswagen/-korb' virtuell.","example":"Leg das Produkt in den Warenkorb.","exampleEn":"Add the product to the shopping cart.","example2":"Mein Warenkorb ist schon voll.","example2En":"My shopping basket is already full."},{"de":"die Wärme","en":"warmth, heat","pos":"noun","plural":"","meanings":[{"en":"warmth, heat (physical)","de":"warme Temperatur"},{"en":"warmth (emotional, friendliness)","de":"Herzlichkeit"}],"rule":"Unzählbares Substantiv, kein Plural.","example":"Die Wärme der Sonne tut gut.","exampleEn":"The warmth of the sun feels good.","example2":"Sie begrüßte uns mit großer Wärme.","example2En":"She greeted us with great warmth."},{"de":"der Waschraum","en":"washroom, washing room","pos":"noun","plural":"die Waschräume","meanings":[{"en":"a room for washing (laundry or personal hygiene)","de":"Raum zum Waschen"}],"rule":"Zusammensetzung aus 'waschen' + 'Raum'; Genus wie 'der Raum'.","example":"Der Waschraum befindet sich im Keller.","exampleEn":"The washroom is located in the basement.","example2":"Bitte benutzt den Waschraum nach dem Sport.","example2En":"Please use the washroom after sports."},{"de":"wasserdicht","en":"waterproof","pos":"adjective","plural":"","meanings":[{"en":"waterproof, impervious to water","de":"kein Wasser durchlassend"}],"rule":"Zusammensetzung aus 'Wasser' + 'dicht'; regelmäßige Steigerung.","example":"Diese Jacke ist wasserdicht.","exampleEn":"This jacket is waterproof.","example2":"Ich brauche wasserdichte Schuhe für die Wanderung.","example2En":"I need waterproof shoes for the hike."},{"de":"der Wasserhahn","en":"water tap, faucet","pos":"noun","plural":"die Wasserhähne","meanings":[{"en":"tap/faucet for water","de":"Hahn, um Wasser laufen zu lassen"}],"rule":"Zusammensetzung aus 'Wasser' + 'Hahn'; Plural mit Umlaut: die Wasserhähne.","example":"Dreh den Wasserhahn zu, bitte.","exampleEn":"Turn off the tap, please.","example2":"Der Wasserhahn in der Küche tropft.","example2En":"The kitchen tap is dripping."},{"de":"wegfahren","en":"to drive away, to leave","pos":"verb","plural":"","meanings":[{"en":"to drive/go away, to leave (by vehicle)","de":"mit einem Fahrzeug weggehen"}],"rule":"trennbar, unregelmäßig: fährt ... weg, fuhr weg, ist weggefahren","example":"Wir fahren am Freitag in den Urlaub weg.","exampleEn":"We're leaving for vacation on Friday.","example2":"Das Auto ist schon weggefahren.","example2En":"The car has already driven away."},{"de":"wegräumen","en":"to put away, to clear away","pos":"verb","plural":"","meanings":[{"en":"to tidy up, put things away","de":"aufräumen, an den richtigen Platz legen"}],"rule":"trennbar, regelmäßig: räumt ... weg, räumte weg, hat weggeräumt","example":"Räum bitte dein Spielzeug weg.","exampleEn":"Please put your toys away.","example2":"Er hat das Geschirr schnell weggeräumt.","example2En":"He quickly cleared away the dishes."},{"de":"wegschmeißen","en":"to throw away (colloquial)","pos":"verb","plural":"","meanings":[{"en":"to throw something away (informal)","de":"etwas wegwerfen (umgangssprachlich)"}],"rule":"trennbar: schmeißt weg, schmiss weg, hat weggeschmissen; unregelmäßig (schmeißen, schmiss, geschmissen); ugs. Synonym zu wegwerfen","example":"Schmeiß die alte Zeitung weg!","exampleEn":"Throw away the old newspaper!","example2":"Ich habe das kaputte Handy weggeschmissen.","example2En":"I threw away the broken phone."},{"de":"wegwerfen","en":"to throw away, discard","pos":"verb","plural":"","meanings":[{"en":"to get rid of something as rubbish","de":"etwas in den Müll werfen"}],"rule":"trennbar: wirft weg, warf weg, hat weggeworfen; unregelmäßig (werfen, warf, geworfen)","example":"Wirf den Müll bitte weg.","exampleEn":"Please throw the rubbish away.","example2":"Man sollte Lebensmittel nicht einfach wegwerfen.","example2En":"You shouldn't just throw away food."},{"de":"die Weise","en":"way, manner","pos":"noun","plural":"die Weisen","meanings":[{"en":"manner, way of doing something","de":"die Art und Weise"},{"en":"tune, melody (less common)","de":"eine Melodie"}],"rule":"oft in der festen Wendung 'auf diese Weise' (in this way); Genus: die Weise","example":"Auf diese Weise sparen wir viel Zeit.","exampleEn":"This way, we save a lot of time.","example2":"Sie löste das Problem auf ihre eigene Weise.","example2En":"She solved the problem in her own way."},{"de":"weitergehen","en":"to go on, continue (walking/happening)","pos":"verb","plural":"","meanings":[{"en":"to continue walking","de":"weiter gehen, nicht stehen bleiben"},{"en":"to continue, carry on (of events/situations)","de":"weiter passieren, fortgesetzt werden"}],"rule":"trennbar: geht weiter, ging weiter, ist weitergegangen; unregelmäßig (gehen, ging, gegangen); Perfekt mit 'sein'","example":"Bitte weitergehen, hier gibt es nichts zu sehen!","exampleEn":"Please keep moving, there's nothing to see here!","example2":"Wie soll es jetzt mit dem Projekt weitergehen?","example2En":"How should the project continue now?"},{"de":"weiterhelfen","en":"to help further, be of help","pos":"verb","plural":"","meanings":[{"en":"to help someone get further with a problem","de":"jemandem bei etwas helfen, weiterkommen"}],"rule":"trennbar: hilft weiter, half weiter, hat weitergeholfen; + Dativ; unregelmäßig (helfen, half, geholfen)","example":"Können Sie mir bitte weiterhelfen?","exampleEn":"Can you please help me further?","example2":"Diese Information hat mir sehr weitergeholfen.","example2En":"This information helped me a lot."},{"de":"die Weiterleitung","en":"forwarding, redirection","pos":"noun","plural":"die Weiterleitungen","meanings":[{"en":"the act of forwarding (e.g. mail, calls, data)","de":"das Weiterleiten von etwas"}],"rule":"Nominalisierung von 'weiterleiten' (trennbar, leitet weiter, leitete weiter, hat weitergeleitet)","example":"Ich kümmere mich um die Weiterleitung der E-Mail.","exampleEn":"I'll take care of forwarding the email.","example2":"Die Weiterleitung des Anrufs hat einen Moment gedauert.","example2En":"Forwarding the call took a moment."},{"de":"das Weltall","en":"universe, outer space","pos":"noun","plural":"","meanings":[{"en":"the universe, space beyond Earth","de":"der Weltraum, das Universum"}],"rule":"unzählbar, kein Plural; Synonym: der Weltraum, das Universum","example":"Astronauten fliegen ins Weltall.","exampleEn":"Astronauts fly into space.","example2":"Das Weltall ist unvorstellbar groß.","example2En":"The universe is unimaginably big."},{"de":"die Weltmeisterschaft (WM)","en":"world championship","pos":"noun","plural":"die Weltmeisterschaften","meanings":[{"en":"a sports competition to determine a world champion","de":"ein internationaler Wettkampf um den Weltmeistertitel"}],"rule":"Abkürzung: die WM; oft mit Sportart kombiniert, z. B. 'Fußball-Weltmeisterschaft'","example":"Deutschland hat die Weltmeisterschaft gewonnen.","exampleEn":"Germany won the world championship.","example2":"Die nächste WM findet in zwei Jahren statt.","example2En":"The next World Cup will take place in two years."},{"de":"der Werktag","en":"weekday, working day","pos":"noun","plural":"die Werktage","meanings":[{"en":"a day on which people usually work (Mon–Sat)","de":"ein Tag, an dem man normalerweise arbeitet"}],"rule":"Gegenteil: der Feiertag/das Wochenende; umfasst in Deutschland meist Montag bis Samstag","example":"An Werktagen stehe ich um sechs Uhr auf.","exampleEn":"On weekdays I get up at six o'clock.","example2":"Die Lieferung dauert drei Werktage.","example2En":"Delivery takes three working days."},{"de":"das Werkzeug","en":"tool","pos":"noun","plural":"die Werkzeuge","meanings":[{"en":"a tool or instrument for doing manual work","de":"ein Gerät zum Arbeiten, z. B. Hammer oder Schraubenzieher"}],"rule":"Genus: das Werkzeug; auch als Sammelbegriff (Werkzeug = tools in general) ohne Plural verwendbar","example":"Der Handwerker hat sein Werkzeug vergessen.","exampleEn":"The craftsman forgot his tools.","example2":"Ein Hammer ist ein wichtiges Werkzeug.","example2En":"A hammer is an important tool."},{"de":"der Wert","en":"value","pos":"noun","plural":"die Werte","meanings":[{"en":"monetary or material worth","de":"der Geldwert, der Preis"},{"en":"a measured number/reading","de":"eine gemessene Zahl, z. B. Blutdruckwert"},{"en":"importance, significance","de":"die Bedeutung, Wichtigkeit"}],"rule":"feste Wendung: 'Wert legen auf' (to attach importance to); Adjektiv 'wert sein' = to be worth","example":"Das Haus hat stark an Wert gewonnen.","exampleEn":"The house has gained a lot in value.","example2":"Der Arzt hat meine Blutwerte kontrolliert.","example2En":"The doctor checked my blood values."},{"de":"der Wertstoff","en":"recyclable material","pos":"noun","plural":"die Wertstoffe","meanings":[{"en":"material that can be recycled/reused","de":"Material, das recycelt werden kann, z. B. Glas, Papier, Plastik"}],"rule":"häufig in Zusammensetzungen: der Wertstoffhof, die Wertstofftonne","example":"Papier und Glas sind Wertstoffe.","exampleEn":"Paper and glass are recyclable materials.","example2":"Wir bringen die Wertstoffe zum Wertstoffhof.","example2En":"We take the recyclables to the recycling center."},{"de":"weshalb","en":"why, for which reason","pos":"adverb","plural":"","meanings":[{"en":"why, the reason why (question word / relative connector)","de":"warum, aus welchem Grund"}],"rule":"Synonym zu 'warum'/'wieso'; Interrogativ-/Relativadverb (keine Konjunktion), oft: 'der Grund, weshalb...'","example":"Weshalb bist du gestern nicht gekommen?","exampleEn":"Why didn't you come yesterday?","example2":"Sie erklärte, weshalb sie die Stelle wechseln wollte.","example2En":"She explained why she wanted to change jobs."},{"de":"wetterfest","en":"weatherproof","pos":"adjective","plural":"","meanings":[{"en":"resistant to weather conditions (rain, wind, sun)","de":"widerstandsfähig gegen Wetter (Regen, Wind, Sonne)"}],"rule":"regelmäßige Steigerung: wetterfest, wetterfester, am wetterfestesten; oft bei Kleidung oder Materialien","example":"Die Jacke ist wetterfest und hält dich trocken.","exampleEn":"The jacket is weatherproof and keeps you dry.","example2":"Wir brauchen wetterfeste Möbel für den Balkon.","example2En":"We need weatherproof furniture for the balcony."},{"de":"widerrufen","en":"to revoke, cancel, retract","pos":"verb","plural":"","meanings":[{"en":"to officially cancel a contract, order or statement","de":"einen Vertrag, eine Bestellung oder Aussage offiziell rückgängig machen"}],"rule":"untrennbar, kein 'ge-' im Partizip: widerruft, widerrief, hat widerrufen; unregelmäßig","example":"Sie können den Vertrag innerhalb von 14 Tagen widerrufen.","exampleEn":"You can cancel the contract within 14 days.","example2":"Der Zeuge hat seine Aussage widerrufen.","example2En":"The witness retracted his statement."},{"de":"das Widerrufsrecht","en":"right of withdrawal, right of cancellation","pos":"noun","plural":"die Widerrufsrechte","meanings":[{"en":"the legal right to cancel a contract within a set period","de":"das Recht, einen Vertrag innerhalb einer bestimmten Frist rückgängig zu machen"}],"rule":"Zusammensetzung aus 'widerrufen' + 'Recht'; wichtig bei Online-Käufen (meist 14 Tage)","example":"Bei Online-Käufen haben Sie ein Widerrufsrecht.","exampleEn":"You have a right of withdrawal for online purchases.","example2":"Das Widerrufsrecht gilt 14 Tage nach Erhalt der Ware.","example2En":"The right of withdrawal applies for 14 days after receiving the goods."},{"de":"der Widerspruch","en":"objection, contradiction","pos":"noun","plural":"die Widersprüche","meanings":[{"en":"a formal objection (e.g. legal/administrative)","de":"ein formeller Einspruch, z. B. gegen einen Bescheid"},{"en":"a logical contradiction","de":"ein logischer Gegensatz zwischen Aussagen"}],"rule":"Verb dazu: widersprechen (+ Dativ); feste Wendung: 'Widerspruch einlegen'","example":"Sie hat Widerspruch gegen den Bescheid eingelegt.","exampleEn":"She filed an objection against the notice.","example2":"Seine Aussagen enthalten einen klaren Widerspruch.","example2En":"His statements contain a clear contradiction."},{"de":"wiedervereinigen","en":"to reunite, reunify","pos":"verb","plural":"","meanings":[{"en":"to bring together again (people, countries)","de":"wieder zusammenbringen, z. B. Länder oder Familien"}],"rule":"trennbar: vereinigt wieder, vereinigte wieder, hat wiedervereinigt; oft reflexiv 'sich wiedervereinigen'; historisch: die Wiedervereinigung Deutschlands 1990","example":"1990 wurde Deutschland wiedervereinigt.","exampleEn":"In 1990 Germany was reunified.","example2":"Nach Jahren konnte sich die Familie endlich wiedervereinigen.","example2En":"After years, the family was finally able to reunite."},{"de":"die Wiedervereinigung","en":"reunification","pos":"noun","plural":"die Wiedervereinigungen","meanings":[{"en":"reunification (esp. of Germany)","de":"das Wiederzusammenkommen zweier getrennter Teile"}],"rule":"Meist im Zusammenhang mit der deutschen Wiedervereinigung 1990 gebraucht; von 'wiedervereinigen' + -ung.","example":"Die Wiedervereinigung Deutschlands war 1990.","exampleEn":"The reunification of Germany was in 1990.","example2":"Nach der Wiedervereinigung hat sich das Land stark verändert.","example2En":"After reunification, the country changed a lot."},{"de":"der Wind","en":"wind","pos":"noun","plural":"die Winde","meanings":[{"en":"wind (moving air)","de":"bewegte Luft"}],"rule":"Maskulin; oft in Wendungen wie 'bei Wind und Wetter'.","example":"Heute weht ein starker Wind.","exampleEn":"There's a strong wind blowing today.","example2":"Der Wind hat meinen Hut weggeweht.","example2En":"The wind blew my hat away."},{"de":"die Windel","en":"diaper, nappy","pos":"noun","plural":"die Windeln","meanings":[{"en":"diaper / nappy for babies","de":"Unterwäsche für Babys, die Urin und Kot aufnimmt"}],"rule":"Feminin; Plural regelmäßig auf -n.","example":"Das Baby braucht eine neue Windel.","exampleEn":"The baby needs a new diaper.","example2":"Wir kaufen immer eine große Packung Windeln.","example2En":"We always buy a big pack of diapers."},{"de":"die Windschutzscheibe","en":"windshield, windscreen","pos":"noun","plural":"die Windschutzscheiben","meanings":[{"en":"windscreen of a car","de":"vordere Glasscheibe am Auto"}],"rule":"Zusammensetzung aus 'Wind' + 'Schutz' + 'Scheibe'; feminin.","example":"Die Windschutzscheibe ist nass vom Regen.","exampleEn":"The windshield is wet from the rain.","example2":"Ein Stein hat die Windschutzscheibe beschädigt.","example2En":"A stone damaged the windshield."},{"de":"der Wirbelsturm","en":"hurricane, cyclone","pos":"noun","plural":"die Wirbelstürme","meanings":[{"en":"hurricane / cyclone / tornado","de":"sehr starker, kreisender Sturm"}],"rule":"Maskulin; Plural mit Umlaut: Wirbelstürme.","example":"Der Wirbelsturm hat viele Häuser zerstört.","exampleEn":"The hurricane destroyed many houses.","example2":"In der Karibik gibt es oft Wirbelstürme.","example2En":"There are often hurricanes in the Caribbean."},{"de":"der Wohnwagen","en":"caravan, camper trailer","pos":"noun","plural":"die Wohnwagen","meanings":[{"en":"caravan / trailer used for living/traveling","de":"Anhänger, in dem man wohnen und reisen kann"}],"rule":"Maskulin; Plural bleibt gleich (der Wohnwagen – die Wohnwagen).","example":"Wir machen Urlaub mit dem Wohnwagen.","exampleEn":"We're going on vacation with the caravan.","example2":"Der Wohnwagen steht auf dem Campingplatz.","example2En":"The caravan is parked at the campsite."},{"de":"die Wolke","en":"cloud","pos":"noun","plural":"die Wolken","meanings":[{"en":"cloud in the sky","de":"sichtbare Ansammlung von Wasserdampf am Himmel"}],"rule":"Feminin; Plural regelmäßig auf -n.","example":"Am Himmel sind viele dunkle Wolken.","exampleEn":"There are many dark clouds in the sky.","example2":"Die Sonne verschwand hinter einer Wolke.","example2En":"The sun disappeared behind a cloud."},{"de":"die Wurst","en":"sausage","pos":"noun","plural":"die Würste","meanings":[{"en":"sausage","de":"Lebensmittel aus gehacktem Fleisch in einer Hülle"}],"rule":"Feminin; Plural mit Umlaut: Würste.","example":"Zum Frühstück essen wir Brot mit Wurst.","exampleEn":"For breakfast we eat bread with sausage.","example2":"Auf dem Grill liegen Würste.","example2En":"There are sausages on the grill."},{"de":"wütend","en":"furious, angry","pos":"adjective","plural":"","meanings":[{"en":"furious, very angry","de":"sehr zornig, wütend"}],"rule":"Regelmäßige Steigerung: wütend, wütender, am wütendsten; oft mit 'auf + Akkusativ'.","example":"Er war wütend auf seinen Chef.","exampleEn":"He was furious at his boss.","example2":"Sie wurde wütend, als der Zug ausfiel.","example2En":"She got angry when the train was cancelled."},{"de":"die Zahlung","en":"payment","pos":"noun","plural":"die Zahlungen","meanings":[{"en":"payment (of money)","de":"das Bezahlen eines Betrags"}],"rule":"Feminin; von 'zahlen' + -ung; oft 'Zahlung leisten/erhalten'.","example":"Die Zahlung ist bereits eingegangen.","exampleEn":"The payment has already arrived.","example2":"Bitte überweisen Sie die Zahlung bis Freitag.","example2En":"Please transfer the payment by Friday."},{"de":"zappen","en":"to channel-surf, flip through channels","pos":"verb","plural":"","meanings":[{"en":"to flip/surf through TV channels","de":"mit der Fernbedienung schnell zwischen Fernsehsendern wechseln"}],"rule":"Regelmäßig: zappt, zappte, hat gezappt.","example":"Er zappt ständig durch die Fernsehprogramme.","exampleEn":"He's constantly flipping through the TV channels.","example2":"Zapp doch mal, vielleicht kommt ein guter Film.","example2En":"Just flip through the channels, maybe there's a good movie on."},{"de":"zaubern","en":"to do magic, conjure","pos":"verb","plural":"","meanings":[{"en":"to perform magic tricks","de":"mit Tricks etwas scheinbar unmöglich Erscheinendes tun"},{"en":"to conjure up (figurative, e.g. cook quickly)","de":"etwas wie durch Zauberei schnell herstellen"}],"rule":"Regelmäßig: zaubert, zauberte, hat gezaubert.","example":"Der Zauberer kann echt gut zaubern.","exampleEn":"The magician can really do magic well.","example2":"Meine Mutter zaubert immer ein tolles Essen aus wenig Zutaten.","example2En":"My mother always conjures up a great meal from few ingredients."},{"de":"der Zeichentrickfilm","en":"animated film, cartoon","pos":"noun","plural":"die Zeichentrickfilme","meanings":[{"en":"animated cartoon film","de":"Film mit gezeichneten, bewegten Figuren"}],"rule":"Maskulin; Zusammensetzung aus 'Zeichen' + 'Trick' + 'Film'.","example":"Kinder lieben Zeichentrickfilme.","exampleEn":"Children love animated films.","example2":"Wir haben gestern Abend einen Zeichentrickfilm gesehen.","example2En":"We watched a cartoon last night."},{"de":"zeitlich","en":"temporal, time-related","pos":"adjective","plural":"","meanings":[{"en":"related to time, temporal","de":"die Zeit betreffend"}],"rule":"Keine unregelmäßige Steigerung; oft 'zeitlich möglich/begrenzt'.","example":"Das ist zeitlich leider nicht möglich.","exampleEn":"That's not possible time-wise, unfortunately.","example2":"Der Termin passt zeitlich nicht in meinen Plan.","example2En":"The appointment doesn't fit into my schedule time-wise."},{"de":"der Zeitmangel","en":"lack of time","pos":"noun","plural":"","meanings":[{"en":"lack of time","de":"zu wenig verfügbare Zeit für etwas"}],"rule":"Maskulin, unzählbar, kein Plural; oft 'aus Zeitmangel'; nach 'wegen' steht der Genitiv: 'wegen Zeitmangels'.","example":"Aus Zeitmangel konnte ich nicht kommen.","exampleEn":"I couldn't come due to lack of time.","example2":"Wegen Zeitmangels musste das Projekt warten.","example2En":"Because of a lack of time, the project had to wait."},{"de":"der Zeitpunkt","en":"point in time, moment","pos":"noun","plural":"die Zeitpunkte","meanings":[{"en":"a specific point in time","de":"ein bestimmter Moment"}],"rule":"Maskulin; oft 'zum jetzigen Zeitpunkt'.","example":"Das ist im Moment der falsche Zeitpunkt.","exampleEn":"Right now is the wrong moment.","example2":"Wir müssen den richtigen Zeitpunkt abwarten.","example2En":"We have to wait for the right moment."},{"de":"der Zeitraum","en":"period of time","pos":"noun","plural":"die Zeiträume","meanings":[{"en":"a period/span of time","de":"eine Zeitspanne zwischen zwei Zeitpunkten"}],"rule":"Maskulin; Plural mit Umlaut: Zeiträume.","example":"In diesem Zeitraum war ich im Urlaub.","exampleEn":"During this period I was on vacation.","example2":"Der Vertrag gilt für einen Zeitraum von zwei Jahren.","example2En":"The contract is valid for a period of two years."},{"de":"der Zeitungsbericht","en":"newspaper report/article","pos":"noun","plural":"die Zeitungsberichte","meanings":[{"en":"a report/article in a newspaper","de":"ein Bericht in der Zeitung"}],"rule":"Kompositum: die Zeitung + der Bericht; Genus vom Grundwort 'Bericht' (maskulin).","example":"Ich habe den Zeitungsbericht über den Unfall gelesen.","exampleEn":"I read the newspaper report about the accident.","example2":"In dem Zeitungsbericht standen viele Details.","example2En":"The newspaper article contained many details."},{"de":"die Zeitverschwendung","en":"waste of time","pos":"noun","plural":"","meanings":[{"en":"a waste of time","de":"nutzlos verbrachte Zeit"}],"rule":"Unzählbar, meist ohne Plural; Kompositum aus Zeit + Verschwendung.","example":"Diese Besprechung war reine Zeitverschwendung.","exampleEn":"That meeting was a complete waste of time.","example2":"Warte nicht auf ihn, das ist Zeitverschwendung.","example2En":"Don't wait for him, it's a waste of time."},{"de":"das Zelt","en":"tent","pos":"noun","plural":"die Zelte","meanings":[{"en":"a tent","de":"eine tragbare Unterkunft aus Stoff"}],"rule":"Regelmäßige Pluralbildung mit -e.","example":"Wir haben unser Zelt am See aufgebaut.","exampleEn":"We set up our tent by the lake.","example2":"Das Zelt hält auch bei starkem Regen dicht.","example2En":"The tent stays waterproof even in heavy rain."},{"de":"zerschlagen","en":"to smash / to shatter","pos":"verb","plural":"","meanings":[{"en":"to break something into pieces","de":"etwas kaputtschlagen"},{"en":"(figurative) to destroy/ruin plans","de":"Pläne zunichtemachen"}],"rule":"unregelmäßig: er zerschlägt, zerschlug, hat zerschlagen; untrennbar (kein 'ge-' im Partizip).","example":"Er hat vor Wut das Glas zerschlagen.","exampleEn":"In anger, he smashed the glass.","example2":"Die Krise hat unsere Pläne zerschlagen.","example2En":"The crisis shattered our plans."},{"de":"zerstören","en":"to destroy","pos":"verb","plural":"","meanings":[{"en":"to destroy, ruin completely","de":"völlig kaputt machen, vernichten"}],"rule":"regelmäßig: er zerstört, zerstörte, hat zerstört; untrennbar, kein 'ge-'.","example":"Der Sturm hat viele Häuser zerstört.","exampleEn":"The storm destroyed many houses.","example2":"Lügen können Vertrauen zerstören.","example2En":"Lies can destroy trust."}]},{"id":"b1-20","title":"B1 · Z (20)","level":"B1","words":[{"de":"die Zerstörung","en":"destruction","pos":"noun","plural":"die Zerstörungen","meanings":[{"en":"the act or result of destroying something","de":"das Zerstören, der Schaden"}],"rule":"Abgeleitet vom Verb 'zerstören'; feminin, Plural auf -en möglich bei mehreren Fällen.","example":"Die Zerstörung der alten Stadt dauerte nur Stunden.","exampleEn":"The destruction of the old city took only hours.","example2":"Die Zerstörungen nach dem Erdbeben waren enorm.","example2En":"The destruction after the earthquake was enormous."},{"de":"das Ziel","en":"goal / destination","pos":"noun","plural":"die Ziele","meanings":[{"en":"a goal or objective","de":"etwas, das man erreichen will"},{"en":"a destination","de":"der Ort, den man erreichen möchte"}],"rule":"Regelmäßiger Plural auf -e; oft in 'sich ein Ziel setzen'.","example":"Mein Ziel ist es, die Prüfung zu bestehen.","exampleEn":"My goal is to pass the exam.","example2":"Nach drei Stunden erreichten wir unser Ziel.","example2En":"After three hours we reached our destination."},{"de":"ziemlich","en":"quite / rather","pos":"adverb","plural":"","meanings":[{"en":"quite, fairly, rather","de":"in relativ hohem Maße"}],"rule":"Keine Steigerung; verstärkt Adjektive/Adverbien, z. B. 'ziemlich müde'.","example":"Das Essen war ziemlich teuer.","exampleEn":"The food was quite expensive.","example2":"Sie spricht ziemlich gut Deutsch.","example2En":"She speaks German quite well."},{"de":"die Zigarettenkippe","en":"cigarette butt","pos":"noun","plural":"die Zigarettenkippen","meanings":[{"en":"the remaining stub of a smoked cigarette","de":"der Rest einer gerauchten Zigarette"}],"rule":"Kompositum aus Zigarette + Kippe; regelmäßiger Plural auf -n.","example":"Auf dem Gehweg lagen viele Zigarettenkippen.","exampleEn":"There were many cigarette butts on the sidewalk.","example2":"Er drückte die Zigarettenkippe im Aschenbecher aus.","example2En":"He put out the cigarette butt in the ashtray."},{"de":"die Zimmerlautstärke","en":"room volume (moderate/indoor volume level)","pos":"noun","plural":"","meanings":[{"en":"a volume level suitable for indoors, not disturbing neighbors","de":"eine Lautstärke, die drinnen niemanden stört"}],"rule":"Unzählbar, kein Plural; typisch in Mietverträgen: 'Musik nur in Zimmerlautstärke'.","example":"Bitte spiel die Musik nur in Zimmerlautstärke.","exampleEn":"Please play the music only at a moderate indoor volume.","example2":"Nach 22 Uhr gilt im Haus Zimmerlautstärke.","example2En":"After 10 p.m., only indoor-level volume is allowed in the building."},{"de":"der Zoll","en":"customs / customs duty","pos":"noun","plural":"die Zölle","meanings":[{"en":"customs (the authority/control at a border)","de":"die Behörde/Kontrolle an der Grenze"},{"en":"a tariff or duty charged on goods","de":"eine Abgabe auf (importierte) Waren"}],"rule":"Maskulin; Plural 'die Zölle' meist bei Zollgebühren/Tarifen, bei der Behörde meist Singular.","example":"Am Flughafen musste er durch den Zoll gehen.","exampleEn":"At the airport he had to go through customs.","example2":"Auf importierte Waren werden hohe Zölle erhoben.","example2En":"High tariffs are charged on imported goods."},{"de":"zudrehen","en":"to turn off / close (a tap, valve)","pos":"verb","plural":"","meanings":[{"en":"to close by turning, e.g. a tap or valve","de":"durch Drehen schließen, z. B. einen Hahn"}],"rule":"trennbar: er dreht zu, drehte zu, hat zugedreht.","example":"Dreh bitte den Wasserhahn zu!","exampleEn":"Please turn off the tap!","example2":"Er hat das Gasventil zugedreht.","example2En":"He closed the gas valve."},{"de":"zufällig","en":"by chance / accidental","pos":"adjective","plural":"","meanings":[{"en":"happening by chance, coincidental","de":"unabsichtlich, ohne Plan geschehend"}],"rule":"Adjektiv und Adverb identisch; wird meist ohne Steigerung verwendet, da 'zufällig' eine Ja/Nein-Eigenschaft beschreibt (nicht abstufbar); regiert keinen Kasus.","example":"Ich habe sie zufällig im Supermarkt getroffen.","exampleEn":"I ran into her by chance at the supermarket.","example2":"Das war kein Plan, das ist rein zufällig passiert.","example2En":"That wasn't planned, it happened purely by chance."},{"de":"zugeben","en":"to admit","pos":"verb","plural":"","meanings":[{"en":"to admit, confess something","de":"etwas als wahr/richtig einräumen"}],"rule":"trennbar, unregelmäßig: er gibt zu, gab zu, hat zugegeben.","example":"Er musste zugeben, dass er einen Fehler gemacht hatte.","exampleEn":"He had to admit that he had made a mistake.","example2":"Ich gebe zu, ich war zu spät.","example2En":"I admit I was late."},{"de":"zügig","en":"swift / brisk","pos":"adjective","plural":"","meanings":[{"en":"fast and steady, without delay","de":"schnell und ohne Unterbrechung"}],"rule":"Regelmäßige Steigerung: zügig, zügiger, am zügigsten.","example":"Die Arbeiten gingen zügig voran.","exampleEn":"The work progressed swiftly.","example2":"Bitte gehen Sie zügig zum Ausgang.","example2En":"Please move briskly to the exit."},{"de":"zulassen","en":"to allow / to permit","pos":"verb","plural":"","meanings":[{"en":"to permit, allow something to happen","de":"etwas erlauben, geschehen lassen"},{"en":"to officially register/approve (e.g. a car)","de":"amtlich genehmigen, z. B. ein Fahrzeug"}],"rule":"trennbar, unregelmäßig: er lässt zu, ließ zu, hat zugelassen.","example":"Der Lehrer lässt keine Ausreden zu.","exampleEn":"The teacher doesn't allow excuses.","example2":"Das Auto wurde gerade neu zugelassen.","example2En":"The car was just newly registered."},{"de":"zumachen","en":"to close / to shut","pos":"verb","plural":"","meanings":[{"en":"to close, shut something","de":"etwas schließen"},{"en":"(informal) to close down, stop operating","de":"ein Geschäft schließen/aufgeben"}],"rule":"trennbar, regelmäßig: er macht zu, machte zu, hat zugemacht.","example":"Mach bitte das Fenster zu, es ist kalt.","exampleEn":"Please close the window, it's cold.","example2":"Der Laden hat wegen der Krise zugemacht.","example2En":"The shop closed down because of the crisis."},{"de":"zunehmen","en":"to increase / to gain weight","pos":"verb","plural":"","meanings":[{"en":"to increase, grow in extent","de":"größer/stärker werden"},{"en":"to gain (body) weight","de":"schwerer werden, an Gewicht zulegen"}],"rule":"trennbar, unregelmäßig: er nimmt zu, nahm zu, hat zugenommen.","example":"Die Zahl der Unfälle nimmt im Winter zu.","exampleEn":"The number of accidents increases in winter.","example2":"Seit dem Urlaub habe ich drei Kilo zugenommen.","example2En":"I've gained three kilos since the vacation."},{"de":"zurückfahren","en":"to drive/go back","pos":"verb","plural":"","meanings":[{"en":"to travel back (by vehicle)","de":"mit einem Fahrzeug zurückfahren"},{"en":"to back up / reverse (a vehicle)","de":"rückwärts fahren"}],"rule":"trennbar: fährt zurück, fuhr zurück, ist zurückgefahren (Perfekt mit sein)","example":"Wir fahren morgen mit dem Zug nach Hause zurück.","exampleEn":"We are traveling back home by train tomorrow.","example2":"Er ist mit dem Auto ein Stück zurückgefahren.","example2En":"He reversed the car a bit."},{"de":"zurückkehren","en":"to return, come back","pos":"verb","plural":"","meanings":[{"en":"to return to a place","de":"an einen Ort zurückkommen"}],"rule":"trennbar: kehrt zurück, kehrte zurück, ist zurückgekehrt (Perfekt mit sein)","example":"Nach drei Jahren ist sie in ihre Heimat zurückgekehrt.","exampleEn":"After three years she returned to her homeland.","example2":"Der Chef kehrt nächste Woche aus dem Urlaub zurück.","example2En":"The boss returns from vacation next week."},{"de":"zurücklassen","en":"to leave behind","pos":"verb","plural":"","meanings":[{"en":"to leave something/someone behind","de":"etwas/jemanden an einem Ort lassen und weggehen"}],"rule":"trennbar, unregelmäßig: lässt zurück, ließ zurück, hat zurückgelassen","example":"Er musste sein Gepäck am Flughafen zurücklassen.","exampleEn":"He had to leave his luggage behind at the airport.","example2":"Sie hat eine Nachricht auf dem Tisch zurückgelassen.","example2En":"She left a note on the table."},{"de":"zurückschicken","en":"to send back","pos":"verb","plural":"","meanings":[{"en":"to return something by post/mail","de":"etwas per Post zurücksenden"}],"rule":"trennbar: schickt zurück, schickte zurück, hat zurückgeschickt; jemandem (Dativ) etwas (Akkusativ) zurückschicken","example":"Ich habe den defekten Artikel zurückgeschickt.","exampleEn":"I sent the defective item back.","example2":"Können Sie mir das Formular bitte zurückschicken?","example2En":"Could you please send the form back to me?"},{"de":"zurücksenden","en":"to send back, return","pos":"verb","plural":"","meanings":[{"en":"to return something (formal, same as zurückschicken)","de":"etwas zurückschicken (formell)"}],"rule":"trennbar: sendet zurück, sandte/sendete zurück, hat zurückgesandt/zurückgesendet; jemandem (Dativ) etwas (Akkusativ) zurücksenden","example":"Bitte senden Sie das unterschriebene Formular zurück.","exampleEn":"Please send the signed form back.","example2":"Die Ware wurde unbeschädigt zurückgesendet.","example2En":"The goods were returned undamaged."},{"de":"zurücktreten","en":"to step back; to resign","pos":"verb","plural":"","meanings":[{"en":"to step back (physically)","de":"einen Schritt nach hinten machen"},{"en":"to resign from an office/position","de":"ein Amt aufgeben"}],"rule":"trennbar, unregelmäßig: tritt zurück, trat zurück, ist zurückgetreten (Perfekt mit sein)","example":"Bitte treten Sie einen Schritt zurück!","exampleEn":"Please step back!","example2":"Der Minister ist wegen des Skandals zurückgetreten.","example2En":"The minister resigned because of the scandal."},{"de":"die Zusammenarbeit","en":"cooperation, collaboration","pos":"noun","plural":"","meanings":[{"en":"joint work between people/organizations","de":"gemeinsames Arbeiten mehrerer Personen/Firmen"}],"rule":"meist ohne Plural verwendet (unzählbar); oft mit 'mit' (Zusammenarbeit mit einer Firma)","example":"Die Zusammenarbeit zwischen den Abteilungen funktioniert gut.","exampleEn":"The cooperation between the departments works well.","example2":"Wir freuen uns auf eine gute Zusammenarbeit.","example2En":"We look forward to good cooperation."},{"de":"zusammenarbeiten","en":"to work together, cooperate","pos":"verb","plural":"","meanings":[{"en":"to work jointly with someone","de":"gemeinsam mit jemandem arbeiten"}],"rule":"trennbar: arbeitet zusammen, arbeitete zusammen, hat zusammengearbeitet","example":"Die beiden Firmen arbeiten seit Jahren zusammen.","exampleEn":"The two companies have been working together for years.","example2":"Wir sollten enger zusammenarbeiten.","example2En":"We should work together more closely."},{"de":"das Zusammenleben","en":"living together, coexistence","pos":"noun","plural":"","meanings":[{"en":"the act/state of living together","de":"gemeinsames Leben, z.B. als Paar oder in einer Gesellschaft"}],"rule":"unzählbar (kein Plural); substantiviertes Verb 'zusammenleben'","example":"Das Zusammenleben mit den Nachbarn klappt gut.","exampleEn":"Living together with the neighbors works well.","example2":"Respekt ist wichtig für das Zusammenleben in der Gesellschaft.","example2En":"Respect is important for coexistence in society."},{"de":"zusammenstellen","en":"to put together, compile","pos":"verb","plural":"","meanings":[{"en":"to assemble or compile a group/list of items","de":"mehrere Dinge zu einem Ganzen ordnen"}],"rule":"trennbar: stellt zusammen, stellte zusammen, hat zusammengestellt","example":"Sie hat eine Liste mit wichtigen Adressen zusammengestellt.","exampleEn":"She compiled a list of important addresses.","example2":"Der Koch stellt täglich ein neues Menü zusammen.","example2En":"The chef puts together a new menu every day."},{"de":"zusammenstoßen","en":"to collide, crash into each other","pos":"verb","plural":"","meanings":[{"en":"to collide physically (vehicles, people)","de":"gegeneinander prallen"}],"rule":"trennbar, unregelmäßig: stößt zusammen, stieß zusammen, ist zusammengestoßen (Perfekt mit sein)","example":"Zwei Autos sind an der Kreuzung zusammengestoßen.","exampleEn":"Two cars collided at the intersection.","example2":"Beim Rennen sind zwei Läufer zusammengestoßen.","example2En":"During the race two runners collided."},{"de":"zusätzlich","en":"additional, extra","pos":"adjective","plural":"","meanings":[{"en":"additional, on top of what already exists","de":"noch dazukommend, extra"}],"rule":"in der Regel nicht gesteigert (absolute Bedeutung); häufig in der Wendung 'zusätzlich zu' + Dativ (= on top of)","example":"Wir brauchen zusätzliches Personal für das Projekt.","exampleEn":"We need additional staff for the project.","example2":"Zusätzlich zum Gehalt bekommt er einen Bonus.","example2En":"In addition to his salary, he gets a bonus."},{"de":"die Zusatzqualifikation","en":"additional qualification","pos":"noun","plural":"die Zusatzqualifikationen","meanings":[{"en":"an extra qualification beyond the basic one","de":"eine zusätzliche Qualifikation neben der Grundausbildung"}],"rule":"Kompositum aus 'Zusatz' + 'Qualifikation'; Genus wie 'die Qualifikation'","example":"Mit dieser Zusatzqualifikation hat er bessere Chancen auf dem Arbeitsmarkt.","exampleEn":"With this additional qualification he has better chances on the job market.","example2":"Sie hat eine Zusatzqualifikation im Bereich Projektmanagement erworben.","example2En":"She acquired an additional qualification in project management."},{"de":"der Zusatzstoff","en":"additive (e.g. food additive)","pos":"noun","plural":"die Zusatzstoffe","meanings":[{"en":"a substance added to food/products","de":"ein Stoff, der einem Produkt (z.B. Lebensmittel) hinzugefügt wird"}],"rule":"Kompositum aus 'Zusatz' + 'Stoff'; Genus wie 'der Stoff'","example":"Dieses Brot enthält keine künstlichen Zusatzstoffe.","exampleEn":"This bread contains no artificial additives.","example2":"Manche Zusatzstoffe können Allergien auslösen.","example2En":"Some additives can trigger allergies."},{"de":"die Zusatzversicherung","en":"supplementary insurance","pos":"noun","plural":"die Zusatzversicherungen","meanings":[{"en":"extra insurance on top of basic coverage","de":"eine zusätzliche Versicherung neben der Grundversicherung"}],"rule":"Kompositum aus 'Zusatz' + 'Versicherung'; Genus wie 'die Versicherung'","example":"Er hat eine Zusatzversicherung für Zahnbehandlungen abgeschlossen.","exampleEn":"He took out supplementary insurance for dental treatment.","example2":"Die Zusatzversicherung kostet zwanzig Euro im Monat.","example2En":"The supplementary insurance costs twenty euros a month."},{"de":"der Zuschauer / die Zuschauerin","en":"spectator, viewer","pos":"noun","plural":"die Zuschauer / die Zuschauerinnen","meanings":[{"en":"a person watching an event, show, or TV","de":"eine Person, die etwas ansieht (z.B. Spiel, Sendung)"}],"rule":"maskulin -er, feminin -erin; Plural maskulin/gemischt: die Zuschauer","example":"Das Stadion war voll mit Zuschauern.","exampleEn":"The stadium was full of spectators.","example2":"Die Sendung hat viele junge Zuschauerinnen.","example2En":"The show has many young female viewers."},{"de":"der Zuschlag","en":"surcharge, supplement","pos":"noun","plural":"die Zuschläge","meanings":[{"en":"an extra fee added to the basic price","de":"ein zusätzlicher Betrag zum Grundpreis"}],"rule":"oft mit 'für/auf': Zuschlag für den ICE; kombinieren mit Verb 'zahlen/bezahlen'","example":"Für den ICE muss man einen Zuschlag bezahlen.","exampleEn":"You have to pay a surcharge for the ICE train.","example2":"Am Feiertag gibt es einen Zuschlag von zehn Prozent.","example2En":"On public holidays there is a ten percent surcharge."},{"de":"zustellen","en":"to deliver","pos":"verb","plural":"","meanings":[{"en":"to deliver mail/parcels to someone","de":"Post oder Pakete an jemanden liefern"}],"rule":"trennbar: stellt zu, stellte zu, hat zugestellt; jemandem (Dativ) etwas (Akkusativ) zustellen","example":"Die Post wird jeden Morgen zugestellt.","exampleEn":"The mail is delivered every morning.","example2":"Der Bote hat das Paket direkt an die Haustür zugestellt.","example2En":"The courier delivered the parcel right to the front door."},{"de":"zustimmen","en":"to agree","pos":"verb","plural":"","meanings":[{"en":"to agree (with someone/something)","de":"seine Zustimmung geben, einverstanden sein"}],"rule":"trennbar: stimmt zu, stimmte zu, hat zugestimmt; + Dativ (jemandem/etwas zustimmen)","example":"Ich stimme deinem Vorschlag zu.","exampleEn":"I agree with your suggestion.","example2":"Alle Kollegen haben dem Plan zugestimmt.","example2En":"All the colleagues agreed to the plan."},{"de":"der Zutritt","en":"access; admission","pos":"noun","plural":"","meanings":[{"en":"permission to enter a place","de":"das Recht, einen Ort zu betreten"}],"rule":"meist ohne Plural; oft mit 'Zutritt haben/verboten' + zu + Dativ","example":"Kinder unter 16 haben keinen Zutritt zur Disco.","exampleEn":"Children under 16 are not allowed into the disco.","example2":"Der Zutritt zum Gebäude ist nur mit Ausweis möglich.","example2En":"Entry to the building is only possible with an ID card."},{"de":"die Zuverlässigkeit","en":"reliability","pos":"noun","plural":"","meanings":[{"en":"the quality of being dependable/trustworthy","de":"die Eigenschaft, verlässlich zu sein"}],"rule":"Abstraktes Nomen, kein Plural; von 'zuverlässig' (Adjektiv)","example":"Der Chef schätzt die Zuverlässigkeit seiner Mitarbeiter.","exampleEn":"The boss values the reliability of his employees.","example2":"Dieses Auto ist bekannt für seine Zuverlässigkeit.","example2En":"This car is known for its reliability."}]}]};
